D.Strings[1]="跟着我，$n。我会把你带到迪菲亚兄弟会的老巢里。但是你最好能保护我，不然我就死定了。"
D.Strings[2]="入口就隐藏在月溪镇里。注意那些盗贼，他们想要我的命。"
D.Strings[3]="你可以去告诉斯托曼，这里就是迪菲亚盗贼的藏身之处，$n。"
D.Strings[4]="我伤得很重。很抱歉我不能走得更快一些。"
D.Strings[5]="啊，新鲜的空气！我要休息一下。"
D.Strings[6]="黑石氏族的兽人在这一带部署了不少兵力，我会尽我所能跟上你。我们出发吧！"
D.Strings[7]="马瑞斯大人！第12军团的基沙恩下士从战场返回，前来报到！"
D.Strings[8]="勇敢的冒险者，谢谢你救了我！我保证马瑞斯大人会重赏你的。"
D.Strings[9]="亡灵在这里四处横行！但暴风城的军队在哪里？"
D.Strings[10]="我们需要暴风城更积极的反应和更多的支援，我们的家园正在遭到亡灵的进攻。"
D.Strings[11]="暮色森林的议会必须行动起来了。这里已经充满了邪恶。"
D.Strings[12]="夜色镇的人民对议会充满了期望。我们不能让他们受到邪恶的伤害。"
