D.Strings[16]="亚伯？是你吗？啊……我很饿，亚伯！我饿啊！！"
D.Strings[17]="等等……你不是我的丈夫。但肯定是他派你来的。你看起来……很可口！"
D.Strings[18]="贝尔姆，嘿！给我一杯雷酒，再给我的好朋友$n来一杯。"
D.Strings[19]="看管酒桶的工作怎样了啊……？"
