D.Strings[26]="擦一件装甲只收一个铜板咯！"
D.Strings[27]="这都是他们的错，愚蠢的联盟军队。居然在我的农场背后修建他们的哨塔。"
D.Strings[28]="这都是他们的错，愚蠢的兽人。居然放火烧我的农场。"
D.Strings[29]="西部荒野的人民向勇敢的$n致敬！"
