D.Strings[43]="你好，埃林！你好啊，艾莱尼！我要来点奶酪。"
D.Strings[44]="你好啊，提亚斯！我要买些奶酪。"
D.Strings[45]="你好，科贝特。这是今天早上刚做好的奶酪！你的商店生意还好么？"
