D.Strings[59]="嗯，可能就是那个爱管闲事的肖尔，我要去看看能找到些什么。回头再联系吧。"
D.Strings[60]="我……我……感到有些不对劲……"
D.Strings[61]="我的思想……我的血肉……我在腐烂……！"
D.Strings[62]="以拉格纳罗斯的名义，去死吧！"
