D.Strings[221]="救命啊！$n在攻击我！"
D.Strings[222]="$n朝这边来了！杀啊！"
D.Strings[223]="我来了！入侵者们，你们的末日到了！"
D.Strings[224]="%s仔细检查着那些钳嘴龟的壳……"
D.Strings[225]="嗯……"
D.Strings[226]="奇怪。非常奇怪……"
D.Strings[227]="$n。这些甲壳告诉了我很多事情，但同时也带来了更多谜团……"
D.Strings[228]="我们为什么要走这条路？"
D.Strings[229]="我们要去哪里？"
D.Strings[230]="我要上厕所。"
D.Strings[231]="我要去看法师塔。"
D.Strings[232]="真的吗？运河里真的有鳄鱼吗？"
D.Strings[233]="我腿疼！"
D.Strings[234]="你说，为什么咱们总是沿着这条路线跑？"
D.Strings[235]="新鲜的面包啦！"
D.Strings[236]="热乎乎的新鲜面包啦！"
D.Strings[237]="长面包，圆面包，各种各样的面包，都是新鲜出炉的啊！"
D.Strings[238]="新鲜出炉的面包！"
D.Strings[239]="有水吗，艾玛？去弄点水，艾玛？你要是再不去打水，我都快忘了水是什么样的了……"
D.Strings[240]="我这么多年来好像都没干过比打水更有意义的事情似的！"
D.Strings[241]="我一天要走好多趟到水井那边去打水，现在的年轻人啊……"
D.Strings[242]="我只是在自言自语罢了，和这里的其他人说话的时候，我总是得不到应有的尊重。"
D.Strings[243]="我总有一天要把他用那件蓝色的长袍裹起来，和他的扫帚一起扔到河里去。"
D.Strings[244]="每天都要累死我！"
D.Strings[245]="我要上路了。"
D.Strings[246]="有那么一小会儿，我以为自己回家了……在亡灵天灾到来之前的那个家……"
D.Strings[247]="把这些东西搬到船上去！"
D.Strings[248]="谁说要休息？想都别想！赶快去干活，你们这些蠢货！"
D.Strings[249]="我们被攻击了！把他们都干掉！"
D.Strings[250]="%s看到朋友在战斗中倒下，变得非常愤怒！"
D.Strings[251]="%s从发光的水果中取出种子……"
D.Strings[252]="让我们看看这些种子是如何在我准备的土壤里生长的……"
D.Strings[253]="%s种下了水果种子。"
D.Strings[254]="%s快步来到培养槽前。"
D.Strings[255]="我希望这种植物可以顺利生根……"
D.Strings[256]="%s破土而出了！"
D.Strings[257]="杀！！！"
D.Strings[258]="以群星的名义！"
D.Strings[259]="过去的事情谁也说不清，但重要的是我们的未来！"
D.Strings[260]="我可以自己想办法回去了，$n。谢谢你！"
D.Strings[261]="好的，我们走吧！"
D.Strings[262]="在蓝色隐士有免费的饮料！"
D.Strings[263]="到蓝色隐士去，那里每个人都知道你的名字！"
D.Strings[264]="暴风城最好的饮料！"
D.Strings[265]="过来喝杯啤酒，享受一下这里的欢乐气氛！"
D.Strings[266]="繁重的魔法研究让你身心疲惫吗？到蓝色隐士放松一下！"
D.Strings[267]="到蓝色隐士来吧，暴风城唯一一个魔法和精神完美结合的地方！"
D.Strings[268]="感到忧郁了？来蓝色隐士放松一下吧！"
D.Strings[269]="%s研究着从暮光之书上撕下来的羊皮纸……"
D.Strings[270]="%s被魔法击中了！"
D.Strings[271]="我的灵魂终于可以安息了……哦，亲爱的塞瑞利恩……"
D.Strings[272]="锐爪？！放松点，我的朋友……你的主人沃科尔在哪里？"
D.Strings[273]="放松，放松，我的朋友。等一下……"
D.Strings[274]="很好。现在告诉我发生了什么，锐爪。"
D.Strings[275]="我明白，朋友。我会找人去帮助你的主人。现在你要回到他那边去，至少离他近一点。"
D.Strings[276]="%s对你咆哮，然后伸出鼻子嗅了嗅你。"
D.Strings[277]="再次感谢你，$n。我现在要上路了。如果可以的话，请你去找特伦希斯，告诉他我已经安全逃脱了。"
D.Strings[278]="现在把这些稀土放到我的培养槽里去……"
D.Strings[279]="再次感谢你，$n。这些稀土对我的实验帮助很大。"
D.Strings[280]="解散，$n。"
D.Strings[281]="我们成功了，朋友。请找到特伦希斯，告诉他我们安全了。再次感谢你。"
D.Strings[282]="在唤醒仪式开始前我必须做好必要的准备。你要保护我！"
D.Strings[283]="这些洞穴曾经是一座神殿，是贫瘠之地万物生长的保证。现在那里简直就是个地狱。"
D.Strings[284]="过来，我们一定要继续下去。在我们把纳拉雷克斯从噩梦中拯救出来之前还有很多事情要做。"
D.Strings[285]="我必须在这个火焰法阵中使用法术来驱逐那些德鲁伊的灵魂。"
D.Strings[286]="这些洞穴已经被净化了，现在我们得赶去纳拉雷克斯的藏身之地！"
D.Strings[287]="纳拉雷克斯就在这个走廊的尽头沉睡着。我们要赶快唤醒他，否则就太晚了。"
D.Strings[288]="在我进入翡翠梦境拯救纳拉雷克斯的时候，你一定要保护好我！"
D.Strings[289]="%s开始进行唤醒纳拉雷克斯的仪式。"
D.Strings[290]="纳拉雷克斯终于从噩梦中醒过来了！"
D.Strings[291]="%s在噩梦中辗转反侧。"
D.Strings[292]="%s痛苦地挣扎着。信徒们似乎快要打进来了。"
D.Strings[293]="%s梦见了可怕的场景，一些东西在黑暗的水下搅动着。"
D.Strings[294]="我终于醒来了！"
D.Strings[295]="啊，我终于从可怖的噩梦中被拉回来了！谢谢你，我忠诚的信徒，还有你勇敢的同伴。"
D.Strings[296]="上啊！帮我把这个$n干掉！"
D.Strings[297]="毫无疑问，这个$n是从纳拉雷克斯的噩梦里跑出来的！"
D.Strings[298]="安娜雅……？我的双眼没有欺骗我吗？真的是你吗？"
D.Strings[299]="岁月对我和你都很残酷，我的爱人……但最后我们还是重逢了。"
D.Strings[300]="命运是如此残酷，它让我们在分别了数千年之后才能重逢……"
D.Strings[301]="我的爱人，你恨我吗？我在万般无奈之下摧毁了你的躯壳，因为只有这样才能让你从痛苦中永久地解脱。"
D.Strings[302]="亲爱的，不要为此而感到内疚。你使我从无尽的苦楚和折磨中解脱了出来，我只会为此而更加爱你。"
D.Strings[303]="但是，即使是这经过数千年的分离才换来的重逢也是如此短暂……我和这个世界的联结正在逐渐减弱，我正在慢慢地离开它……离开你……"
D.Strings[304]="再见了，塞瑞利恩，我的爱人。我们终能再见……"
D.Strings[305]="%s柔和的声音在薄雾中轻轻回响，“我永远爱你……”"
D.Strings[306]="不！安娜雅……安娜雅！请不要离开我！不……"
D.Strings[307]="怎么办，我的爱人？没有你，我怎么办……没有你……我如何有勇气在这个世界上生存……"
D.Strings[308]="一个圣骑士！杀死他的话，主人会很高兴的。进攻！"
D.Strings[309]="终于从这个肮脏的房间逃了出来！让我带你到院子里去……"
D.Strings[310]="你居然想要对付这扇门后的那些怪物，你真的很勇敢。"
D.Strings[311]="我们这就出发！"
D.Strings[312]="希望你能解决掉阿鲁高。我必须赶快回到哈德瑞克那里。"
D.Strings[313]="%s从阴影中跳了出来！"
D.Strings[314]="有人杀死了那个可怜的家伙。"
D.Strings[315]="就这一次我同意你的意见……垃圾。"
D.Strings[316]="密斯特！我担心再也看不到你了！嗯，我很好，不用担心我。你必须好好休息，恢复健康。"
D.Strings[317]="跟着我，我将会为你打开庭院的门。"
D.Strings[318]="我能打开这扇门。但是为什么正好我就没法打开监牢的门呢？"
D.Strings[319]="搞定了！祝你们好运。我必须马上回去向肯瑞托报告！"
D.Strings[320]="%s在进入森林之前大声咆哮着以示感谢。"
D.Strings[321]="赶快去，$n。我的命运掌握在你手中。"
D.Strings[322]="女神啊，我同伴的数量正在不断地减少，我的力量很快就不足以阻止费伍德森林的恶魔了。"
D.Strings[323]="女神啊，赐予我战胜敌人的力量吧！女神啊，请听我说，我现在要拼死一搏了，我所做的一切都是为了正义！"
D.Strings[324]="什么……这是什么？这就是女神对我祈祷的回应？艾露恩赐予我一件武器，一把镰刀，去打败那些恶魔！"
D.Strings[325]="我失败了……我最终还是失败了……我愧对我的同胞……狼人肆虐，而女神赐予我的镰刀也丢失了。"
D.Strings[326]="我引来了这些邪恶的生物……当初女神赐予我的圣物到底在哪里……究竟是谁在主导这一切？"
D.Strings[327]="悉尼迟到了。我原本以为现在他该到家了。"
D.Strings[328]="女士，他是你的丈夫，不是我的。你问我他在哪里干什么？"
D.Strings[329]="他一定被修道院的工作拖住了。但是不管怎么样，他现在也该回来了。"
D.Strings[330]="净化这个世界上的污秽并不是一件容易的事，南希。但是总是要有人去做这样的事情的。"
D.Strings[331]="好吧，我要出去检查一下。似乎有些不对劲。"
D.Strings[332]="这个混蛋终于得到了应有的报应。"
D.Strings[333]="石爪山的自然之灵依然十分愤怒，$n。"
D.Strings[334]="我担心无法使他们平静下来……"
D.Strings[335]="谁敢打扰阿鲁高的仆人？准备面对你的末日吧！"
D.Strings[336]="在大灾变时，亚米萨兰正在大陆崩裂的边界，几乎没有什么幸存者逃过那次劫难。"
D.Strings[337]="埃瑟里克斯来到我们面前，他声称能把我们从痛苦中解救出来。他给我们施了魔法，让我们免受伤害。"
D.Strings[338]="当震动停下来的时候，他的真实目的暴露出来了。我们都被困住了，而他在慢慢地汲取我们的能量。"
D.Strings[339]="他的副官，伊克鲁德·玛格苏尔有一本书，里面也许记载着其它灵魂宝石的所在地。"
D.Strings[340]="喔，喔！终于出来了。不过接下来还有危险，所以要保持警惕。"
D.Strings[341]="那上面就是卡尔加·刺肋的住处。那个该死的又干又瘪的老太婆。"
D.Strings[342]="这个沟里就有蓝叶薯！它们可都是唾手可得的金子啊！"
D.Strings[343]="这里到处都潜伏着危险。"
D.Strings[344]="我不明白这些愚蠢的动物是怎么在这种地方生存的……闻起来真臭！"
D.Strings[345]="我想我看到了一条可以走出这片荆棘林的路。"
D.Strings[346]="能走出这条臭沟真好，尽管出去了也好不了多少。"
D.Strings[347]="终于！我终于能走出这个地方了。"
D.Strings[348]="我想在回到棘齿城之前休息一下。谢谢你的帮助！"
D.Strings[349]="好了，现在我要起身去棘齿城了！祝你好运！"
D.Strings[350]="曾经有数百人被他的法术困住。现在只有一小部分还被囚禁着。他有时也会和我们交谈。"
D.Strings[351]="他担心他的法力会减弱，那块宝贵的灵魂宝石也会消失和死亡。"
D.Strings[352]="%s指了指井边的水罐。"
D.Strings[353]="救命！快帮我把这$n搞定！"
D.Strings[354]="我们会再见的，勇敢的$c。"
D.Strings[355]="好的，我们开始吧。"
D.Strings[356]="现在让我们去寻找药草吧。"
D.Strings[357]="不，不在这里……"
D.Strings[358]="这一带肯定有我们要的草药……"
D.Strings[359]="哈，那里就有一个！"
D.Strings[360]="过来，$n！让我们到那里仔细找找看！"
D.Strings[361]="%s从地上捡起药草。"
D.Strings[362]="好了，我们离开这里！"
D.Strings[363]="接下来我可以自己应付了。谢谢，$n！去向我的老板要酬金吧！"
D.Strings[364]="%s转身消失在沼泽地里。"
D.Strings[365]="小心！$n发起了攻击！"
D.Strings[366]="救命！我遭到攻击了！"
D.Strings[367]="救命！那野兽过来了！"
D.Strings[368]="我很高兴你在这里！我需要你的帮助！！"
D.Strings[369]="我要去干什么来着？"
D.Strings[370]="如果被上尉发现，我就死定了。"
D.Strings[371]="这到底怎么回事？"
D.Strings[372]="突然之间，到处都是那帮家伙了。"
D.Strings[373]="他们一定是得到了某些人的帮助。"
D.Strings[374]="为什么我们不现在解决呢，亨德尔？普罗德摩尔女士将会很乐意在塔里接见你的。"
D.Strings[375]="我注意到岛那边有一些火光。还有一个人。让我们去那边看看，$n。"
D.Strings[376]="那是帕瓦尔·雷瑟。让我们过去看看他会说什么，如何？"
D.Strings[377]="你……你要干什么？离我远一点……"
D.Strings[378]="我发誓，我没有偷你的任何东西！我的东西你可以随便拿，但是请快点离开！"
D.Strings[379]="把这个喝了，它对你有好处。"
D.Strings[380]="你会好起来的。"
D.Strings[381]="让我帮帮你吧。"
D.Strings[382]="和我们讲讲你对树荫旅店的事情有什么了解，放心，我不会打你的。"
D.Strings[383]="我……好吧，我也许从旅店里拿了一些东西……但是为什么食人魔要关心这个？"
D.Strings[384]="看看这里，如果你不告诉我有关那次火灾的事情的话——"
D.Strings[385]="不要过来，食人魔！"
D.Strings[386]="我对你的这些火并不了解……"
D.Strings[387]="好了，好了！不要再打了！不要再有人受伤了。"
D.Strings[388]="好了，伙计们，退后。你们做得够多了。我们以后再见！"
D.Strings[389]="帕瓦尔·雷瑟！终于找到你了。你现在和食人魔混在一起了？不要害怕，即便是背叛者也会得到宽恕。"
D.Strings[390]="士兵，别对雷瑟中尉太狠了。"
D.Strings[391]="愿意效劳，长官。"
D.Strings[392]="啊……哈兰，我没有想到……"
D.Strings[393]="现在让我们把剩下的垃圾清理干净！"
D.Strings[394]="该死！你最好不要死在我手上！"
D.Strings[395]="今天一定是你幸运的一天。好吧，我会说的。先让我一个人呆一会。瞧，你还不相信我，但它……哦，天哪……"
D.Strings[396]="雷瑟，你在干什么？"
D.Strings[397]="好像是挂了，你最好回去告诉克罗格这里发生了什么。"
D.Strings[398]="顺便说一下，谢谢你帮我望风。"
D.Strings[399]="那是什么？你听到什么了吗？"
D.Strings[400]="%s被箭射中了胸膛，摇摇晃晃地向后退了几步。"
D.Strings[401]="好了，好了！我们投降……不过请放下你的武器，我会合作的！"
D.Strings[402]="求求你了……普罗德摩尔小姐。我并不是想要……"
D.Strings[403]="真对不起，我花了这么多时间才到这里。我希望普罗德摩尔女士现在就能接见我。"
D.Strings[404]="嘿，$n！不要忘了去拿一只箱子，还有操作手册和指挥棒！"
D.Strings[405]="我们马上就要回塔里去了。如果你有话想要和我们说，可以在那里找到我们。"
D.Strings[406]="这不会花很长时间……"
D.Strings[407]="隐形药水已经准备好了，$n。"
D.Strings[408]="让我们离开这个地方吧。"
D.Strings[409]="谢谢你，$n。我将会永远记住你。你可以在斯通纳德北部的营地里找到那个大箱子。"
D.Strings[410]="%s消失在沼泽地里。"
D.Strings[411]="这里什么人都没有……"
D.Strings[412]="呀呀呀！我要逃走！"
D.Strings[413]="哈，有机会试试我这把利刃了。"
D.Strings[414]="兄弟会不能容忍你的行为。"
D.Strings[415]="感受兄弟会的力量吧！"
D.Strings[416]="啊啊啊……新鲜的肉！"
D.Strings[417]="感受黑石兽人的力量吧！"
D.Strings[418]="你不配与黑石兽人较量！"
D.Strings[419]="我渴望战斗！"
D.Strings[420]="杀死你简直是易如反掌。"
D.Strings[421]="我要杀了你！"
D.Strings[422]="死吧！"
D.Strings[423]="都将在我们的剑下屈服。"
D.Strings[424]="呀呀！杀啊！"
D.Strings[425]="我不怕你这样的$c！"
D.Strings[426]="我要撕碎你！"
D.Strings[427]="你去死吧！"
D.Strings[428]="啊！！！我要干掉$r！"
D.Strings[429]="这个$R看上去很好吃！"
D.Strings[430]="扁它！"
D.Strings[431]="呃？那是什么？"
D.Strings[432]="不要穿过黑铁矮人的地盘，$C。"
D.Strings[433]="去死吧，$C。"
D.Strings[434]="感受一下黑铁矮人的力量吧！"
D.Strings[435]="为了龙喉氏族而战！"
D.Strings[436]="我要踩碎你的骨头，$R！"
D.Strings[437]="龙喉氏族万岁！去死吧，没用的$c！"
D.Strings[438]="食物……"
D.Strings[439]="一个活着的$R……不久就会变成一个像我这样的亡灵。"
D.Strings[440]="加入我们吧，$C。"
D.Strings[441]="我必须摧毁这些恶魔的工具！为了部落！"
D.Strings[442]="现在你要好好了解一下了，$n！"
D.Strings[443]="好了，你这堆可怜的烂骨头。让我们看看你有什么本事。攻击你的对手，我说停的时候你才能停止。"
D.Strings[444]="停！你们把这个叫做战斗？真可怜！现在用心去战斗，好吧，你们其实已经没那东西了。"
D.Strings[445]="你们知道自己看起来有多烂吗？这是我见过的最可笑的战斗！"
D.Strings[446]="你们不再是只为了自己而战斗，蠢货！你们现在是为希尔瓦娜斯女王而战，所以快点表现出你们的价值来！"
D.Strings[447]="你们是死了，但不是被埋了。现在让我看看你们的实力吧！"
D.Strings[448]="木头和稻草会显示出怜悯之心，但巫妖王不会！"
D.Strings[449]="你们最好现在就能证明自己不是个废物！"
D.Strings[450]="剑不是工具，它是你的延伸。我希望你们能做得更好！"
D.Strings[451]="你那也叫作战？如果那也叫战斗，那我就是战神了！"
D.Strings[452]="利斯塔，把战俘带过来。"
D.Strings[453]="爱德华，泰勒尔出来。准备接受你们的第一轮挑战。"
D.Strings[454]="看来你们应付第一轮还是非常轻松的嘛。让我们看看你是怎样对付第二轮测试的。利斯塔，把巫妖王的爪牙带上来。"
D.Strings[455]="年轻的战士，面对你们最后一轮挑战吧！"
D.Strings[456]="干得很好。现在站到旁边去，让其他的兄弟来试试。"
D.Strings[457]="你觉得我的新玩具怎么样？"
D.Strings[458]="瑟里莎，把这个交给兰克斯特神父。"
D.Strings[459]="我的主人阿博纳斯大人让我把这个交给你。"
D.Strings[460]="遵命，大人。"
D.Strings[461]="大人，这是兰克斯特神父给您的。"
D.Strings[462]="你喜欢我的宠物吗？"
D.Strings[463]="她难道不是最让人惊奇的小东西吗？"
D.Strings[464]="我不是告诉你新的控制技术会成功的吗？"
D.Strings[465]="和我告诉你的一样棒，是吗？"
D.Strings[466]="摧毁她的精神对我来说很容易。"
D.Strings[467]="你不是想要让我把所有的秘密都告诉你吧？"
D.Strings[468]="一个小小的仪式就够你受的了。"
D.Strings[469]="一点点小魔法，她当然非常关心这些……"
D.Strings[470]="每个人都有弱点，关键是如何要找到它。"
D.Strings[471]="经过努力，我发现大脑中有这样一个特定的部位，如果你将其切除或者施加特定的刺激，就可以使得该生物变得更加温顺。"
D.Strings[472]="谢谢你，我的宝贝。"
D.Strings[473]="真是让人惊讶，杰勒德。你是怎么办到的？"
D.Strings[474]="真让人感到惊讶！你是怎么实现恒定控制的呢？"
D.Strings[475]="杰勒德，我不赞成你的试验，但是我承认结果是令人印象深刻的。你到底对她作了什么？"
D.Strings[476]="真令人惊讶。你在控制她，但她还能保持自己的意识。你是怎么做到的？"
D.Strings[477]="她保留了她的知识和语言能力，同时还能为你出色地完成任务。你到底做了些什么？"
D.Strings[478]="我从来没见过这样的情况。一个生物居然能够在没有失去自己意识的情况下被控制。你对她作了什么？"
D.Strings[479]="妙极了，杰勒德，你们超越了自己，再来一次。"
D.Strings[480]="杰勒德，你给我留下了深刻的印象。我原本以为你只会夸夸其谈，但事实证明我错了。"
D.Strings[481]="太不可思议了。这里面到底有什么诀窍？"
D.Strings[482]="很好，杰勒德。接下来，你要负责培养出更多这样的生物。"
D.Strings[483]="这绝对是一个令人惊讶的发现。我很想看看你失败了的那些试验品。"
D.Strings[484]="我不同意你用炼金术去解决这些问题，但我对结果感到满意。你干得很好。"
D.Strings[485]="你的宠物很不错，杰勒德，但我想她需要一个带着铃铛的项圈。"
D.Strings[486]="杰勒德，你有训练她的场地吗？"
D.Strings[487]="啊！那个无赖派他的人来找我吗？在我动手杀了你之前滚出我的视线，还有，拿上这个。"
D.Strings[488]="啊，在这里。"
D.Strings[489]="《不可思议的魔法流动及它是如何影响这个世界的》，玛吉诺·仲马著。我在一直寻找这本书。"
D.Strings[490]="看来我真的需要一个更好的图书分类系统了。啊，就是这本！"
D.Strings[491]="《卡德加的魔法日记，第八卷》，我要的是这一本。"
D.Strings[492]="哈，《达拉然大法师的神秘咒术》，太棒了。"
D.Strings[493]="不知道我能不能找到《魔法和能量的守则》这本书。啊哈，在这里，它怎么会在这里？"
D.Strings[494]="《魔法致病学》，不对不对。《魔法矩阵》，也不对。啊，就是这个，《魔法神秘学》。"
D.Strings[495]="这就是我要寻找的魔法书。"
D.Strings[496]="没错。嗯，这本书参考了另外一本书的内容。看来我还要去找那一本书。"
D.Strings[497]="这一本不是很有用。让我看一下另外一本。"
D.Strings[498]="那就是我想要知道的东西。现在我要知道书中的哪个章节讨论的是魔法流量的变化问题。"
D.Strings[499]="非常有趣。但如果确实是这样的话，那我的理论就是错误的。我要重新去读另一部分，看看我究竟错过了什么。"
D.Strings[500]="看来我对于能量的理解是正确的。让我们去看看另一本书讲了些什么。"
D.Strings[501]="如果这个理论是正确的，那我就得做很多研究了。"
D.Strings[502]="但这个肯定不对。我把那本大书放哪里去了？"
D.Strings[503]="从头再来一遍。"
D.Strings[504]="如果你在这里，那就表明你已经准备好去研究召唤恶魔的方法了。我们将从最低级的生物召唤开始，然后再慢慢进阶。让我们开始吧。"
D.Strings[505]="最容易召唤的是小鬼。你的能力也许已经远远超过召唤小鬼的水平，但是我们为了保证召唤教学的完整性，所以还是从召唤它开始吧。"
D.Strings[506]="这些邪恶的小家伙就是小鬼。它很小而且很瘦弱，显然是不能做为肉盾使用的，而它的威力也不大。这种召唤生物最好是在多人组队的时候作为支援力量使用。"
D.Strings[507]="现在你已经了解了小鬼的特性，那么让我们继续研究下一种你可以召唤的生物：虚空行者。"
D.Strings[508]="这种恶魔被称为虚空行者。它的力量和耐力都非常惊人，可以出色地胜任防御任务。首先控制它来攻击你的敌人，这样就能保证你在有肉盾保护的情况下安全地使用法术和技能。"
D.Strings[509]="如果你还没有看见过虚空行者，那你一定要去看看。这种生物看上去就极具气势，而且在战场上也能发挥很强的作用。接下来，让我们看看所有男性学员都在热切期盼的召唤生物：魅魔。"
D.Strings[510]="好了。除了和前面那两种召唤生物的外形有着明显的差异之外，魅魔的攻击能力也非常可观。然而，她的防御力很差，所有很难作为肉盾来使用。"
D.Strings[511]="努力学习，总有一天你们也可以召唤魅魔的，但现在我们要继续课程了，下一讲是地狱猎犬。"
D.Strings[512]="现在你们看到的就是地狱猎犬。这种生物拥有法力燃烧等多种技能，这些技能在对付施法型的敌人时是十分有用的。"
D.Strings[513]="当遇见施法者的时候，这种恶魔是你最好的朋友。现在，让我们进行一下讲的课程。这种召唤生物主要被用来帮助你更快地旅行。它就是地狱战马，有时也被称为梦魇。"
D.Strings[514]="我怀疑你已经看过很多次这个生物了。这些恶魔马能让你的旅行速度加快，只要你召唤出它们来，就可以把它们当作自己的坐骑。但是地狱战马是非常难以驯服的，所以在尝试之前，你最好确定自己准备充足。"
D.Strings[515]="所有的召唤生物都介绍完毕了。召唤课程已经结束。新的课程将会很快开始，如果你要想要得到进一步的提高，那就请不要走远，先在周围转转。"
D.Strings[516]="嗯，看来基佛需要一个新的项目。如果那个笨蛋阿博纳斯继续从基佛手里抢项目，基佛肯定会对他有意见的。"
D.Strings[517]="嗯，搞定了。现在让基佛试试看。"
D.Strings[518]="不是基佛想要的结果。基佛可能加了太多的地根草。我们来看一下第二份药水是不是基佛所需要的。"
D.Strings[519]="%s戳了戳那只小蛤蟆。"
D.Strings[520]="%s给蛤蟆喂了一些奇怪的液体。"
D.Strings[521]="%s失望地戳了戳那只小松鼠。"
D.Strings[522]="好吧，失败了。这种生物太小了。让我们看看基佛的第三批药剂效果如何。"
D.Strings[523]="%s给松鼠喂了一些粘粘的液体。"
D.Strings[524]="%s戳了戳那只野兔。"
D.Strings[525]="基佛对这个结果不太满意。也许如果基佛尝试一下大剂量的话，效果会好一些。"
D.Strings[526]="%s抓住野兔，把那瓶液体全数灌入野兔腹中，然后把它塞回笼子。"
D.Strings[527]="这是什么？基佛要的是一只绵羊？基佛想要一件强力的武器，但他现在得到的就是这只绵羊。基佛非常失望。"
D.Strings[528]="%s反复地戳那只绵羊。"
D.Strings[529]="基佛很高兴。"
D.Strings[530]="%s强行把液体灌进了那个疲惫不堪的人的口中。"
D.Strings[531]="%s轻声告诉$n开启保险箱的秘诀。"
D.Strings[532]="现在让我们来试一试……"
D.Strings[533]="啊！太恐怖了！"
D.Strings[534]="终于可以唤醒纳拉雷克斯了！过来帮帮我，勇敢的冒险者！"
D.Strings[535]="我们必须去和其他的信徒会合。在我重建贫瘠之地前，有许多工作要做。再见，勇敢的灵魂！"
D.Strings[536]="为了酋长而战！"
D.Strings[537]="我亲爱的托尔塔！我终于回来了。"
D.Strings[538]="你知不知道我在这里等了很久？晚饭在哪里？那么晚了还没有晚饭的影子？"
D.Strings[539]="亲爱的托尔塔，在别离那么长时间之后我们终于再次相见了。我们之间的爱还会更加热烈。"
D.Strings[540]="少废话，我肚子饿了！现在去海里给我找点吃的来！"
D.Strings[541]="好吧，托尔塔。你要什么我就给你找什么……"
D.Strings[542]="这次不要再迷路了……"
D.Strings[543]="愿安宁和耐心永远与你同在，$n。"
D.Strings[544]="我们还要走更远吗？"
D.Strings[545]="我很渴。"
D.Strings[546]="沙子灌进鞋里了……"
D.Strings[547]="要走多远？"
D.Strings[548]="你能背我走一段吗？"
D.Strings[549]="你听说过食人魔、地精和深渊领主的故事吗？"
D.Strings[550]="托尔塔肯定很担心。"
D.Strings[551]="这是个很好的战利品，$c。"
D.Strings[552]="我的爪子将把你撕得粉碎，$R。"
D.Strings[553]="你死定了，$C。"
D.Strings[554]="$n，准备战斗！"
D.Strings[555]="你！快加入战斗！"
D.Strings[556]="战斗结束了！"
D.Strings[557]="挑战者输了！"
D.Strings[558]="我们成功了！我们赢了！"
D.Strings[559]="到房子那边去！无论如何都要紧跟着我！那里有枪和弹药！"
D.Strings[560]="有人挂啦！"
D.Strings[561]="%s开始吟唱召唤法术……"
D.Strings[562]="集中精神，$n。我马上要开始召唤仪式了……"
D.Strings[563]="战士，做好准备。"
D.Strings[564]="能当自己的老板实在是件好事！$B$B嘿，你能给我几个铜板，让我买个三明治吗？我快饿死了。"
D.Strings[565]="看看，风险投资公司的新伐木机比我的要好多啦，从可拆换的机械臂到控制把手，都是那么棒！我的老板给我下了死命令，但我们却拿不出任何东西。$b$b现在我们自己的设计研制工作已经完全停止了，所以我决定向他们“借”一个。我派维兹克兰克去淤泥沼泽偷一个回来，但他到现在还没音讯！"
D.Strings[566]="我曾经负责管理热砂港的伐木机开发工作。但上个月，我自己出来单干了。现在我的全部供应商都把我列入了黑名单。更糟糕的是，我的开发工作至今都没有实际成效。所以我非常需要你的帮助，$n！"
D.Strings[567]="年轻的$c，靠近一点。我年轻的时候耳朵可好使了，但现在你必须大声说话我才能听到。"
D.Strings[568]="跟我讲讲故事，斯考恩。"
D.Strings[569]="你杀了鬼嚎。你这个傻瓜！"
D.Strings[570]="我在这片平原上生活了很多很多年，我捕猎过许多凶猛的野兽，从来没有失败过……直到我遇见了鬼嚎。$B$B很久以前，这只巨狼曾经是牛头人的盟友，还和燃烧军团英勇作战。不过后来它被一个恶魔所伤，身上的伤口一直没有治愈。最后……这道伤口把它逼疯了。$B$B现在它总是痛苦地在平原上游荡，寻找终止它的痛苦的方法。我很惭愧，因为我无力把他杀掉……"
D.Strings[571]="%s高声尖叫，寻求帮助！"
D.Strings[572]="你好啊，法师。我能在魔法知识的学习上为你提供什么帮助吗？"
D.Strings[573]="我对法师的相关训练感兴趣。"
D.Strings[574]="你好。我是一个侏儒法师训练师，而你是一个法师。"
D.Strings[575]="你好，$c。你想要一些建议？好吧，找个法师当朋友就对了！我们的袖口里藏着一些小把戏……"
D.Strings[576]="你好。我是一个亡灵法师训练师，而你是一个法师。"
D.Strings[577]="你好，$C。你是来学习神秘的手艺的吗？"
D.Strings[578]="你好，$c。我怜悯你，因为魔法的真正秘密是你永远也无法企及的……"
D.Strings[579]="我对术士的相关训练感兴趣。"
D.Strings[580]="现在还不是让你长眠的时候。我会帮你起死回生……但你也要为此付出一些代价。"
D.Strings[581]="经希尔瓦娜斯女王批准，亡灵哨兵的数量增加了。在敌人料想不到的时候派出更多的人手实施打击。"
D.Strings[582]="让我复活吧。"
D.Strings[583]="你终究是要说的，还不如现在就说了。"
D.Strings[584]="坦白交待了，我们就放你走。"
D.Strings[585]="什么？哦，好吧，我不在乎你说什么。我只是喜欢这样。"
D.Strings[586]="你要做什么，$c？我要迟到了，而我的雇主不喜欢拖沓。"
D.Strings[587]="你是阿斯托·哈德恩，对吗？"
D.Strings[588]="是的，我是阿斯托·哈德恩。你是？"
D.Strings[589]="你有我所要的东西，阿斯托。我现在要拿走它。"
D.Strings[590]="碎手氏族将会见证部落重铸荣耀。"
D.Strings[591]="我想要接受训练。"
D.Strings[592]="你受到了天灾军团的污染。准备进入扭曲虚空吧。"
D.Strings[593]="你无处可逃。十字军将消灭所有携带天灾病毒的人。"
D.Strings[594]="圣光将会惩罚所有心怀不轨的人。你死定了！"
D.Strings[595]="血色十字军将会消灭一切邪恶的力量，把它们彻底赶出这片领地！"
D.Strings[596]="别轻举妄动，$n，这颗宝珠中的恶魔是个相当可怕的野兽。"
D.Strings[597]="看啊，竟然有个年轻的$c来看像我这样的老农夫？"
D.Strings[598]="纳拉雷克斯又陷入了沉睡！$b$b很久以前，纳拉雷克斯曾满怀着进入翡翠梦境、让贫瘠之地重新变成茂密森林的伟大理想而来到了这处洞穴中。但他的执着却逐渐消退了，而他的思想也被脑海蜿蜒的影象所侵染。$b$b现在，那些奇怪的爬虫正从他的梦境中爬到这片土地上来，我们必须把他从梦魇中唤醒过来，否则他就将永远失落于其中，并继续给这片大地带来邪恶的力量！$b$b不过，只有杀死他那些堕落的仆人——毒牙之王，我才能开始进行唤醒仪式。"
D.Strings[599]="毒牙之王死了！我们还有希望！$b$b然而，整个唤醒仪式是非常复杂的，我无法独自完成它。$b$b我现在就开始着手完成所有必要的准备工作，但与此同时，我需要你保护好我。从纳拉雷克斯的噩梦中召唤出的怪物确实非常难缠。如果没有你的帮助，这个任务对我来说会非常可怕。$b$b当你准备好要保护我的时候，就过来跟我说一声，我会带你到纳拉雷克斯的房间去。"
D.Strings[600]="活动开始了！"
D.Strings[601]="机器转过来面对着你。$B$B它的背后有一个奇怪的凹槽，上面刻着一行字：“基尔卡克·旋杆的财产”"
D.Strings[602]="啊呀！你都干了些什么？他疯了！快关上舱门！把操纵杆往上拉！啊啊啊啊啊！赶快！"
D.Strings[603]="嘿！你在为提尔斯干活吗？如果我是你的话，我会离他远远的！酒精把他的大脑麻痹了，但是他的魔法还是和以前一样厉害！"
D.Strings[604]="当然了，我会告诉你密码的。只要你不让提尔斯抓到我就行了！"
D.Strings[605]="基尔卡克的钥匙滑到了缝隙中。"
D.Strings[606]="当我因为绑着这个大铁球而不能保护自己的时候，你会嘲笑我吗？"
D.Strings[607]="有个人类手中有能打开这个装置的钥匙。我想他的名字叫埃斯顿。"
D.Strings[608]="从这里离开，$c，不然他们也会把你锁住的。"
D.Strings[609]="这把锁的钥匙呢？"
D.Strings[610]="玛尔根……他是一个狱卒。他应该有那把钥匙。"
D.Strings[611]="银行坐落在贸易区，就在城门的西北面。来，让我在地图上指给你看。"
D.Strings[612]="我希望雪融化掉。它总是把我的长袍弄湿，把一切都搞得乱糟糟的！"
D.Strings[613]="该死的雪……哦，你是……$n，是吗？刚刚还有人跟我打听你的事情呢。"
D.Strings[614]="铁炉堡的术士拉戈·黑钳在找你，你要立刻到他那里向他报告。你可以在铁炉堡的荒弃的洞穴里找到他。"
D.Strings[615]="你好，$c，我是萨纳瑞恩·绿树。"
D.Strings[616]="如果你问我，那我要说，地精的科技更加先进。我们有工具，我们还有天赋！"
D.Strings[617]="要不是侏儒的狗屎运，他们就永远不会赢！"
D.Strings[618]="如果我是你，我就赌地精赢。压其他车队都是在浪费时间。"
D.Strings[619]="我已经把钱压在地精身上了！如果你够聪明的话也应该赌地精获胜！"
D.Strings[620]="我听说下一场比赛的时候他们要把地精的车炸掉！不管是真是假，我会待在安全的地方。"
D.Strings[621]="哦，你说的是约翰森？我听说他躲起来了。"
D.Strings[622]="要不是地精的狗屎运，他们每次都会把车撞进山里去！"
D.Strings[623]="这种车赛是展现我们高新科技的大好机会！"
D.Strings[624]="我给我们的车里安装了新的矩阵式调节器，它可以使赛车的引擎转速提高至少百分之十五！"
D.Strings[625]="我那两岁的儿子设计的赛车都比那些可笑的地精造出来的破烂跑得更快！"
D.Strings[626]="我的数据分析师认为这次我们会比上次的纪录提高二十秒！"
D.Strings[627]="这些天提尔斯和他的助手都变得怪怪的。"
D.Strings[628]="约翰森？我认为他在附近的某个地方……"
D.Strings[629]="哈！提尔斯这段时间以来都在找他，但是他不想被找到。他是一只小鸡。"
D.Strings[630]="终于！终于从这破牢房里逃出来了！$b$b肯瑞托将我从达拉然派到这个银松森林里来，要我调查阿鲁高和他的亡灵仆从们的活动，可我们却一点也不知道那个巫师已经完全失去了理智。$b$b我必须立刻把这个消息汇报上去！可在我离开之前，让我先把庭院门上的魔法锁给打开。$b$b既然你能击败雷希戈尔，或许也能从前面的层层埋伏中杀出一条血路……"
D.Strings[631]="终于！终于有人把我从这破牢房里给救出来了！$b$b高级执行官哈德瑞克大人派我们来这儿收集这座要塞里的信息，以便制定一个能永久消灭铲除阿鲁高的计划。$b$b但那个老不死的巫师还真有点能耐，我们很快就被他的魔法结界给发现了。我被抓来关在这里，不过文森特可就没这么走运了。$b$b我得马上回去向哈德瑞克大人汇报。首先我会把庭院里的锁给你打开，或许你这么强悍的$c能从前面的一大堆伏兵里杀出一条血路……"
D.Strings[632]="我以前曾经追寻过墓光之锤的道路。为了找到复活上古之神的方法，我只身深入这座巢穴，想要找到从那个该死的恶魔阿库麦尔身上抽取能量的方法。$B$B在看到无数无辜人白白地牺牲之后，我慢慢恢复了理智。$B$B我被困住了一段时间，但是现在我自由了！不幸的是，这里离我的家乡卡兹莫丹太远了！$B$B勇敢的冒险者，我现在可以将你传送到一个特别的地方，然后回来干掉阿库麦尔。如果你愿意的话，我现在就送你到达纳苏斯去。"
D.Strings[633]="放松一下自己疲倦的身心。"
D.Strings[634]="我们欢迎你随时来访，就像我们欢迎平原上吹过的风。"
D.Strings[635]="满上一杯啤酒，拉一张凳子过来坐坐。我们要畅饮一番，同时还要分享我们的故事。"
D.Strings[636]="你看上去很疲惫。在我们的屋里休息一会儿吧，让艾露恩引领你进入甜美的梦乡。"
D.Strings[637]="请进，请进！不要坐得离火炉太近。它今天还没爆炸，但是为了安全起见，我想你还是坐在别的地方比较好。"
D.Strings[638]="你好，$c，很高兴认识你。"
D.Strings[639]="请把我传送到达纳苏斯。"
D.Strings[640]="异教徒， 净化他们！"
D.Strings[641]="阿库麦尔死了！我终于可以离开这块伤心地了。"
D.Strings[642]="跟我谈谈，听听我的故事吧。"
D.Strings[643]="看看谁来了……有什么要我帮你的吗，$c？"
D.Strings[644]="科瑞恩，我需要接受一些训练。"
D.Strings[645]="你可以在英雄谷东北边的那个城堡平台上找到狮鹫管理员。"
D.Strings[646]="兄弟会是不可能被你这种微不足道的$c所阻拦的。"
D.Strings[647]="啊，你在找杜加尔·朗德瑞克。他那里有卡兹莫丹飞得最快的狮鹫！你可以在贸易区的外墙上找到他。"
D.Strings[648]="你需要租用一只狮鹫进行飞行，是吗？杜加尔就在贸易区的城墙上，他那里有很多狮鹫，记着飞行的时候要抓紧哦！"
D.Strings[649]="狮鹫？你是要使用空中旅行服务吧，到贸易区的城墙上去找到杜加尔·朗德瑞克就可以了。"
D.Strings[650]="你可以在贸易区的暴风城接待中心里找到奥德文·拉弗林。"
D.Strings[651]="你想要成立一个公会，对吗？祝你好运！\n\n和暴风城接待中心的奥德文·拉弗林谈谈吧。你从英雄谷进入贸易区之后就可以看到暴风城接待中心了。"
D.Strings[652]="哈，你要找的是暴风城访客中心。从英雄谷走到贸易区后左手边的第一座建筑就是了。"
D.Strings[653]="你要寻找哪种职业的训练师？"
D.Strings[654]="法师们都聚集在法师区的巫师圣殿里，那里有一座高塔。和它相比，我们的兵营就好像是一座农舍。"
D.Strings[655]="哦，你正在学习魔法？那没有什么地方会比法师区的巫师圣殿更好了。"
D.Strings[656]="听起来你得去跟玛吉诺·仲马谈谈！你可以在法师区的巫师圣殿找到他。当然，那些法师总是来去无踪……"
D.Strings[657]="你应该和奥斯伯谈谈。暴风城没有比他更擅长潜行艺术了，那家伙就在旧城区里。"
D.Strings[658]="哎，潜行者只会影响我们在暴风城的工作。我真希望能把奥斯伯和马迪亚斯直接送到暴风城监狱去。"
D.Strings[659]="如果你要找潜行者的话，就应该去旧城区。它坐落在暴风城的东部。"
D.Strings[660]="战士们通常都待在猪和哨声旅店或者旧城区的兵营里。但是我建议你还是去旅店看看。"
D.Strings[661]="想要接受训练？我可以把你训练成暴风城最好的战士，但是守卫是不能这么做的。我想你得去兵营或者猪和哨声旅店，找些合适的人来对你进行训练。"
D.Strings[662]="去兵营或者猪和哨声旅店逛逛吧。如果你去旅店的话，别忘了尝尝那里的好酒，那些酒绝对能让矮人的酒相形见拙。"
D.Strings[663]="教堂广场的光明大教堂是暴风城神职人员的住所，你可以在那里找到高阶牧师劳瑞娜。"
D.Strings[664]="劳瑞娜是暴风城的高阶牧师，你可以在教堂广场上的光明大教堂里找到她。"
D.Strings[665]="我建议你去教堂广场上的光明大教堂里找一找。"
D.Strings[666]="如果你想变成强大的圣骑士，那么格雷森·沙东布瑞克公爵是你最好的导师。你可以在教堂广场上的光明大教堂中找到他。"
D.Strings[667]="索尔芬·石盾从铁炉堡而来，让我们见识到了什么叫真正的狩猎艺术。如果你不介意被烟熏得泪流满面，就到矮人区去找他吧。他的屋子就在那个区域的东北部。"
D.Strings[668]="什么？我不认为暴风城里有术士训练师。\n\n不过……在法师区的那家名叫“已宰的羔羊”的旅店中有一些与恶魔有关的活动，我想你应该去那里看看。"
D.Strings[669]="是什么把你带到这个地方的，$c？"
D.Strings[670]="他变得越来越胖而且越来越堕落，你可以闻到他身上发出臭味，他很脏所以我觉得他要去洗洗。$B$B好吧，不说这些奇怪的东西了。你从哪里来，我能帮你什么忙吗，$c？"
D.Strings[671]="霍夫丹，你好，我要接受训练。"
D.Strings[672]="如果你要学习炼金术，暴风城只有一个地方值得你去……那就是炼金材料店。你可以沿着法师区的外围找到这家店铺。"
D.Strings[673]="你应该去找瑟鲁姆·深炉谈谈，他是我见过的最好的矮人铁匠。你可以在矮人区的中心地带找到他。"
D.Strings[674]="如果你想要成为一名好厨师，那就去旧城区的猪和哨声旅店，找斯蒂芬·雷百克谈谈。那家伙知道怎样才能做出与众不同的肋排大餐来。\n\n啊……说到他那著名的肋骨大餐，我都感到有些饿了。你可不要指望他会把那道菜的做法传授给你！"
D.Strings[675]="暴风城有一个天才侏儒名叫利廉姆·火轴，他是这里最好的工程学训练师。你可以在矮人区的后面找到他。"
D.Strings[676]="光明大教堂是暴风城所有治疗相关技能的训练中心。你可以去那里找安吉拉·雷菲德学习急救技能。"
D.Strings[677]="你可以在法师区的炼金材料店外面找到塔尼莎。"
D.Strings[678]="你想要学习制皮？西蒙·坦纳尔可以教你。你可以在旧城区的“护体皮甲”店里找到他。"
D.Strings[679]="你可以去找吉尔曼·石手谈谈。我知道他在矮人区有一栋房子，但我不知道确切的地方。如果我是你的话，我就会去那边看看。"
D.Strings[680]="如果你要去学剥皮术，可以到旧城区的“护体皮甲”店里看看。"
D.Strings[681]="邓肯雇佣了暴风城最好的裁缝，乔吉奥·波利罗。他的店就坐落在法师区里。"
D.Strings[682]="约翰森不想让提尔斯知道他还在闪光平原，所以他把自己变成了一只小鸡！$B$B如果你找到约翰森，就冲他招招手。没准他会跑过来的。"
D.Strings[683]="我希望你已经准备开工了。"
D.Strings[684]="欢迎来观看赛车！希望你喜欢这里，但请记得不要把钱都压在一支车队上。"
D.Strings[685]="你好，$c！欢迎来闪光平原观看赛车！"
D.Strings[686]="哪个车队的赛车最快？天知道！"
D.Strings[687]="地精的赛车马力强劲，但侏儒的赛车也有不少独到之处……"
D.Strings[688]="你需要帮助吗？"
D.Strings[689]="像只猫一样在雨里爬行，你抓着刨着，一遍又一遍……稍后继续……$B$B哦，我没看见你进来，$n！我能为你做什么吗？"
D.Strings[690]="你好！我是一个潜行者，我需要接受训练。"
D.Strings[691]="如果我们要成为这块新地区的主人，那么我们就必须要找个地方好好休息。把你的斧子放在火边，让大家分享你英勇战斗的故事吧。"
D.Strings[692]="没有什么能比在水晶湖钓一天的鱼更惬意的事情了。阿诺德·利兰教我学会了钓鱼。你可以在运河区的码头找到他。\n\n哦，不要相信他告诉你的任何关于运河里有怪物之类的故事。"
D.Strings[693]="鲁坎·考迪尔在监狱附近的运河边上有一家小店。我相信他可以教你附魔的技巧。"
D.Strings[694]="我独自走在路上，为了捍卫荣誉和清除这片大陆上的敌人而战。$B$B我能为你做什么，$n？"
D.Strings[695]="*机械打手4100型做好了跟随你的准备*"
D.Strings[696]="是的，我看到你要寻找的萨满祭司了。上次我见到她的时候是在这里的西边，她隐居在钢鬃部族旁的小山上。如果你够聪明的话，就可以找到一条通往小屋的山路，就在北边不远的地方，那条路可以让你避开野猪人，直接找到她。"
D.Strings[697]="到果园去和我碰头——我现在要去把我的枪放好。"
D.Strings[698]="无论萨尔是否存在，碎手氏族的秩序都将延续下去。"
D.Strings[699]="碎手氏族的赞杜沙。赞杜沙怎么会帮你？他不能！也绝对不会！"
D.Strings[700]="你是来接受训练，还是来浪费一个战士的时间的？"
D.Strings[701]="我需要进行战士技能的训练。"
D.Strings[702]="这台机器开始运转了。"
D.Strings[703]="按下贴着“盗贼工具”标签的黄色按钮。"
D.Strings[704]="他给你蜂蜜酒$b$b他给你啤酒$b$b他总是过着快乐的生活$b$b这么多年他为我们每个人都服务过$b我们叫他微笑的吉姆。"
D.Strings[705]="这是一种非常奇怪的植物，你从未在泰达希尔的其它地方见过。"
D.Strings[706]="这个植物矗立在泰达希尔的普通植物之间，散发着奇异的紫色光芒。"
D.Strings[707]="按下贴着“大饼干”标签的红色按钮。"
D.Strings[708]="你好。我的职责在得到允许的情况下，根据艾泽拉斯的造物者对于土灵的分析，向来访者提供相关的信息。我随时都可以与你分享这些信息。"
D.Strings[709]="土灵是造物者设计的综合产物，并作为艾泽拉斯开始的几个种族之一。土灵被用于帮助造物者改善这个世界。$B$B他们是造物者在其它世界中设计的标准地下生物的改良型态。在最初的结构得以确定之后，这种原型产生了很多的变化。"
D.Strings[710]="它是造物者在开创世界的时候创建的最早的一个物种。造物者所创建的每种生物都肩负了一定的使命。对于艾泽拉斯来说，必须改造原有的标准地下生物构造，使其适应地下深处的生活，土灵就是这种改造的产品。$B$B在土灵被创造出来之后，由于巨大的环境压力，它们出现了许多事先无法预见的变化。"
D.Strings[711]="在正确回答这个问题之前，需要向你介绍更多关于土灵的背景资料。$B$B资料处理中。$B$B为了理解土灵的变化，首先要了解土灵的设计特征。创世者的目的是要提高标准地下生物母体的存活性，因此他们把与整个世界相联系的弹性构造基础整合在其中，土灵的出现正是为了达到这一目的。"
D.Strings[712]="所谓弹性构造基础就是指用于种族合成的基本材料。造物者在创造土灵的时候放弃了以前创造世界时一直使用的基础材料，转而使用这种常见于艾泽拉斯的材料。$B$B通过对世界组成成分的分析，造物者认为可以合成一种加强型的生物，将它作为世界本质的缩影。造物者最终通过混合艾泽拉斯大陆上各种不同的石头成分，最后组成了这样一种生物的构造基础。"
D.Strings[713]="简单地说，事实确实如此。$B$B虽然土灵的外表看上去像是一个小型的人型生物，但它们包含了艾泽拉斯大陆上各种石头的成分。它们在得到了力量和耐力最大化的同时也没有牺牲敏锐的感觉。它们的皮肤和肌肉的设计使其几乎完全免疫物理伤害，而且只需进行非常小的改动，土灵就可以展现出惊人的魔法抗性。"
D.Strings[714]="以上这些内容是用来帮助你理解创世者的动机。他们创造出土灵这样一个物种是为了在他们离开之后，土灵可以成为这个世界中的一个重要部分，并保障创世者在艾泽拉斯世界的宏大计划得以继续实施。$B$B创世者对于“土灵”这个名字十分满意，因为它很好地体现了这个种族的基本特性。"
D.Strings[715]="土灵唯一的异常变化是在高压环境下对于母体扰动的趋向。$B$B附录：设计的目的是让该物种能够适合地下深处的生活，从而无法满足高压环境下的适应性要求。$B$B这种扰动直到土灵按照计划进入世界的主循环之后才被发现。造物者并没有将土灵召回再重新进行改造，而是直接对其进行了实时的改造。"
D.Strings[716]="[当你问了这个问题之后，它明显地停顿了一会儿]$B$B你需要的信息无法在该数据库中获取。对此我表示歉意。$B$B你可以在数据更新之后再次查询该信息，或者从艾泽拉斯的其它信息数据库处获得更多信息。"
D.Strings[717]="当土灵的合成母体不稳定的时候，产生了两个变种。一号教程图像正在初始化。$B$B第一类变种被称为“穴居人”。这个变种保留了土灵的力量和耐力，但是它的感知力量完全丧失。欲望和狡诈成为了穴居人的本能。"
D.Strings[718]="抱歉，我无法将现有记录数据按照时间顺序进行排序。$B$B虽然穴居人仍然包含了艾泽拉斯的各种石头的核心成分，但是它们感知能力的丧失是造物者无法接受的。$B$B穴居人可以进行单体繁殖。它们会把所有的东西当作食物，包括石头，甚至是另外一个穴居人。这样的同类相残是造物者极度反感的。"
D.Strings[719]="二号教程图像正在初始化。$B$B土灵母体的第二个变种和标准的地下生物母体相比较而言，保留了很多必要的元素。这个种族被称作“矮人”。$B$B这个变种同样保留了土灵的力量和耐力。在某些方面，矮人甚至超过了土灵母体所具有的感知能力。但是，矮人这个变种的身体结构中已经完全没有了石质成分的踪迹。"
D.Strings[720]="你的问题在数据库中有相关联接。$B$B矮人依然和艾泽拉斯的各种石头有着密切的关系，但是由于土灵在高压环境下的变异，矮人的结构与标准地下生物母体的结构保持了一致。$B$B因此，正如你所猜想的那样，矮人确实是从母体中变异出来的。"
D.Strings[721]="抱歉，我无法将现有记录数据按照时间顺序进行排序。$B$B虽然矮人还是和艾泽拉斯的各种石头有着某种联系，但是他们更多的是向普通的地下物种发展。矮人的生活习性和繁衍方式都和其它的标准生物完全一致。$B$B造物者认为矮人是一种可以接受的变种，可以让其继续发展下去。"
D.Strings[722]="造物者就是……造物者。$B$B他们根据自己的设计来创造和改变这个世界。他们是这个世界出现的原因，他们是艾泽拉斯的创造者。"
D.Strings[723]="造物者也知道这个数据库中汇集了大量的信息。所以，如果你拥有诺甘农圆盘的话，便可以得到一份所有信息的拷贝。$B$B请确认你现在没有关于这方面信息的问题了。当你找到诺甘农圆盘之后，可以随时过来制作拷贝。"
D.Strings[724]="土灵到底是什么？"
D.Strings[725]="什么是“地下生物母体”？"
D.Strings[726]="你所说的变化是什么？"
D.Strings[727]="什么是“弹性构造基础”？"
D.Strings[728]="难道……土灵是用石头做出来的？"
D.Strings[729]="还有关于土灵的其它信息吗？"
D.Strings[730]="我想我现在明白造物者设计土灵的意图了。你之前说的土灵的变化是指什么？"
D.Strings[731]="为什么高压环境会引起土灵的不稳定性？"
D.Strings[732]="土灵不稳定时会发生什么？"
D.Strings[733]="穴居人？！你说的穴居人难道就是现在的那种穴居人？"
D.Strings[734]="你提到当土灵不稳定的时候出现了两个变种。那第二个是什么？"
D.Strings[735]="矮人！！难道矮人是起源于土灵的？！"
D.Strings[736]="这些矮人和现在的矮人是同一种生物吗？矮人还和土灵有其它的联系吗？"
D.Strings[737]="造物者是谁？"
D.Strings[738]="有许多东西需要思考……"
D.Strings[739]="我现在就去找那张碟片。"
D.Strings[740]="没人可以窃取造物者的秘密！"
D.Strings[741]="那么说来你想要成为一名铁匠？$g小伙子:小姑娘;，扎好围裙，拿上铁锤，让我们开始吧。"
D.Strings[742]="请让我接受训练。"
D.Strings[743]="请传授我更多关于锻造护甲的知识。"
D.Strings[744]="$n，我已经许久没有看见过有上好的护甲被锻造出来了。我以前曾经在大锻炉的格鲁努斯·削钢那里接受过训练。我相信如果你去他那里的话，肯定可以学到很多东西。"
D.Strings[745]="你能帮我指指路吗？"
D.Strings[746]="如果你想要找格鲁努斯的话，那么首先要到铁炉堡去，然后去城市中心的大锻炉，在那里你就可以找到格鲁努斯。"
D.Strings[747]="请传授我更多关于锻造武器的知识。"
D.Strings[748]="$n，你已经拥有了惊人的锻造技能。我不得不承认你锻造出的武器已经超过了我的水平。我所认识的水平高过你的铁匠只有博古斯·钢拳，我相信你可以从他那里学到不少东西。"
D.Strings[749]="你想要接受博古斯的训练？当然，我可以告诉你在什么地方能够找到他。往西北方向穿过广场，然后再顺着西面的路走，在右手边的第二座建筑??可以找到他。"
D.Strings[750]="碎手氏族的影响遍布这一地区。我们已经统治了整个卡利姆多——法律，政治，军事，一切的一切。我们无所不知，我们目及一切。$B$B你现在已经成长到能够为我们效力的时候了，$n。是时候让你投入战斗了。$B$B你做好接受下一个任务的准备了吗？"
D.Strings[751]="难道你看不出我现在很忙吗？有什么事？"
D.Strings[752]="你真的那么笨吗？你锻造出来的是什么东西？那最多算得上是一把水果刀罢了。我可不会花时间来训练一个菜鸟。"
D.Strings[753]="欢迎来到大锻炉，$g小伙子:姑娘;。外面虽然非常寒冷，但是这里确实热火朝天。拿起锤子开工吧，让我看看你到底有些什么能耐！"
D.Strings[754]="干得好，$n，我打赌你做的东西和布鲁克的酒一样正点。你应该去和米洛尔·怒斩谈谈，他会给你更多指引的。"
D.Strings[755]="当然，我会告诉你怎么才能找到米洛尔的。他就在大锻炉的铁砧旁。仔细聆听他的教导吧，米洛尔绝对是名不虚传！"
D.Strings[756]="$n，你已经得到了我的认可，你是我这些年来带过的最好的徒弟。如果你想要铸造一把真正的武器，那么你一定要去和米洛尔·怒斩谈谈。那个矮人能够教你铸造出一把真真正正的绝世好剑。"
D.Strings[757]="你要找米洛尔·怒斩？他就在那儿，你瞧，就在你身后！呃，好吧，也许在你前面！反正就在大锻炉附近！"
D.Strings[758]="厄运袭击了这座塔。这附近的所有风险投资公司雇员，包括我，都病倒了。$B$B就在上个星期，我们巡逻队的两个人死掉了，然后就变成了两具没有思想的行尸！$B$B我感到自己的生命力正在慢慢地被抽干……我已经渐渐丧失对自己的控制力。快让这样的痛苦结束吧……求求你了……*费苏勒重重地拍打着自己的脸*我还没有死……听着……作为风险投资公司的高级成员，我知道很多敏感的信息。"
D.Strings[759]="你打扰我就是为了这个？你穿得真是跟垃圾一样，你还不如背着个死兔子到巨魔的洞里去跑一圈哪！"
D.Strings[760]="$n，这真是你做的吗？真是一件精美的作品。我会继续训练你的，相信总有一天你可以达到皇家铸甲匠的水准。"
D.Strings[761]="大约五个月之前，风险投资公司荆棘谷分公司从藏宝海湾的一个名叫克兰克·菲兹巴布的神秘商人那里买了一瓶特别的毒药。显然，那是从赞吉尔手中偷来的！$B$B没错，我说的就是那个被流放的赞吉尔，他因为研究亡灵巫术而被他的部族赶了出去。$B$B那帮荆棘谷分公司的家伙拿到毒药之后就开始互相实验，结果可想而知。"
D.Strings[762]="大工头普兹克·加里维克斯在那件事情发生之后就把剩余的毒药带到了他在淤泥沼泽的塔中继续进行研究，主要是想要解决毒药的不稳定性。最后他决定和迪菲亚兄弟会达成协议，共同研制开发这种毒药，代价是由迪菲亚兄弟会提供批量的成品毒药。$B$B迪菲亚兄弟会的克拉文·摩特维克负责对赞吉尔的毒药进行改良。"
D.Strings[763]="接下来就是你看到的情况了：毒药发挥了预期的作用，喝下毒药的人都变成了被人控制的行尸走人，然而，这种毒药非常不稳定。$B$B加里维克斯，还有这座塔里里外外的人都已经感染了这种毒药。我们的意志和身体都在不断被侵袭。我们的器官变得越来越脆弱。$n，我已经无力去拯救这里的人了，而且我感觉自己马上要变成他们的一份子了。"
D.Strings[764]="现在，这座塔的防御力量正处于最薄弱的时刻。包括加里维克斯在内的所有人都感染了疾病，你的攻击一定可以对他们造成致命打击！$B$B我想让你进塔拿到大工头普兹克·加里维克斯的徽记，还有最后一瓶药，把这些东西都交给申苏尔。他会知道接下来该怎么办的……我希望如此。"
D.Strings[765]="哎呦！"
D.Strings[766]="我希望你是因为好事才打断我的，我正在做一些重要的工作。"
D.Strings[767]="关于草药学，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。"
D.Strings[768]="啊，一个渔夫。你想要接受训练吗？也许我能教你些东西？"
D.Strings[769]="欢迎来暴风城。我们可是花了很长时间才将它重建起来的，但是这些工作都很值得。那么，你是来参观的还是有任务在身？"
D.Strings[770]="找我学习烹饪的学徒并不多，如果你准备好了的话，我马上就可以教你一些烹饪技巧。"
D.Strings[771]="我看上去像是那种闲得可以招待每个旅行者的人吗？快点告诉我你需要什么，我可没有时间和你慢慢磨蹭。"
D.Strings[772]="找我学习剥皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。"
D.Strings[773]="虽然现在是和平时期，但是我们可不能荒废了我们的战斗技能！"
D.Strings[774]="暴风城是人类的支柱，它是建立在钢铁的意志和锋利的刀刃上的。"
D.Strings[775]="你好。你想要学一些战斗技巧吗？"
D.Strings[776]="活到老，学到老。"
D.Strings[777]="战士的任务之一就是保护。正如我们在战场上保护自己的同伴一样，我们要时刻保护被遗忘者的利益。"
D.Strings[778]="哦，一个医师。我愿意传授给你一些能够在你旅途中对你有所帮助的东西。"
D.Strings[779]="怎么了，$g小伙子:姑娘;？我能帮你什么忙吗？"
D.Strings[780]="我从铁炉堡来到这里协助进行重建工作。我希望能向你传授尽可能多的本领，然后我就能回家去，把这堆事情丢给你来做。"
D.Strings[781]="什么？你打扰我了，你最好赶快找到一个说得过去的理由。"
D.Strings[782]="在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。"
D.Strings[783]="我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！"
D.Strings[784]="我想要看看你卖的货物。"
D.Strings[785]="为了增进暗夜精灵和人类的联盟关系，我千里迢迢带来了由泰达希尔最好的工匠制作的东西。我这里的东西应有尽有，请随意挑选。"
D.Strings[786]="暴风城最好的货物啊，朋友，你绝对不应该错过。看看有什么你需要的东西吗？"
D.Strings[787]="看看我卖的东西吧，有什么你想要的吗？"
D.Strings[788]="我这里只卖最好的东西，而且绝无二价。你想要讨价还价的话，就去找个地精商人。"
D.Strings[789]="让圣光保佑你一路平安。如果你需要需要任何帮助，就来找我吧。"
D.Strings[790]="不要让市场上的人类愚弄了你，$g小伙子:姑娘;。有了侏儒建造的那条地铁运输线，你可以很轻松地把货物从铁炉堡运送过来。如果那些家伙要收你运费的话，那么就告诉他们你要到我这里来买东西。"
D.Strings[791]="如果你把A标签插到B槽中，那么当然会爆炸！来，看看我有些什么，然后你可以问利廉姆怎样组合才不会爆炸。"
D.Strings[792]="没有人能够从这里偷走东西。从来没有人……从来！"
D.Strings[793]="我想要查看一下我的储物箱。"
D.Strings[794]="谁胆敢唤醒阿扎达斯？谁胆敢触怒造物之神？"
D.Strings[795]="欢迎来到蓝色隐士，这里是魔法汇集的地方。$g先生:女士;，我能帮你什么忙吗？"
D.Strings[796]="我建议你最好不要坐得靠近阴影。"
D.Strings[797]="欢迎来到猪和哨声旅店！和朋友在这里举杯畅饮，不亦乐乎！"
D.Strings[798]="欢迎来到暴风城银行。我们竭诚为您提供最优质的服务，包括金融账户和绝对安全的储物箱。$g先生:女士;，您是否已经拥有了本银行的账户呢？"
D.Strings[799]="我们是整个暴风城中唯一提供鲜花的地方。你可以在我们店里购买到各种美丽的花儿。"
D.Strings[800]="$g先生:女士;，你想去哪里？只需要花几个小钱，你就可以搭乘狮鹫快速到达目的地。"
D.Strings[801]="这些巨兽比你更会寻找道路，它们能让你更快地到达目的地，而且还可轻松欣赏沿途的美景。"
D.Strings[802]="我需要空运服务。"
D.Strings[803]="在这里说话你要小心点，一不小心就可能招来杀身之祸。现在，你有什么需要我帮助的事情吗？"
D.Strings[804]="欢迎来到暴风城公会注册办公室。有什么需要我帮忙的吗？"
D.Strings[805]="我如何才能建立一个公会？"
D.Strings[806]="我要设计一件公会战袍。"
D.Strings[807]="我希望你千里迢迢来到大煅炉不只是为了取暖。$g小伙子:小姑娘;，我能帮你什么忙吗？"
D.Strings[808]="你看上去就是一个天生的铁匠。你的指甲缝中都是煤灰，双手充满了钢铁般的力量。啊，我甚至可以感觉到铁匠的血液在你的血管中奔流。你应该是来这里学东西的，好吧，$g小伙子:小姑娘;，拿起锤子，让我看看我能教你些什么吧。"
D.Strings[809]="银行"
D.Strings[810]="去找克拉姆吧。你可以在中心高地上的雷霆崖咨询处里找到他。"
D.Strings[811]="你可以在中心高地上找到雷霆崖银行。"
D.Strings[812]="双足飞龙巢穴就在城镇中心的图腾柱顶部。"
D.Strings[813]="去长者高地的长者大厅找图拉克·符文图腾吧。"
D.Strings[814]="啊，那你就要去猎人高地上的猎手大厅了。你可以在那里找到像浩特·雷角那样伟大的猎人。"
D.Strings[815]="你是魔法的研习者？嗯，好吧……你可以在灵魂高地下的预见之池中找到他们。"
D.Strings[816]="你应该找柯布神父谈谈，到灵魂高地下的预见之池去找他吧。"
D.Strings[817]="灵魂大厅是萨满祭司的家园，它坐落在灵魂高地上。愿你的先祖保佑你。"
D.Strings[818]="想要加入我们的行列？萨尔克·暴怒图腾可以指引你，他就在猎手大厅里。"
D.Strings[819]="真有趣……我总是听到人类和兽人互相抱怨对方的名声是多么的差。对我来说，世界上所有种族都是一样的：他们都是笨蛋，而且脑子里只有贪婪两个字。$B$B你觉得我在胡言乱语？你难道没有发现你的生命只是为了满足贪婪的欲望而度过的吗？$B$B所有人都是这样。贪婪让我离开了家园，贪婪也会让我重新回去。"
D.Strings[820]="$r，你是回来帮助库米沙的吗？不用担心，你腹中的剧痛只是说明你的意志力在崩溃。$B$B幸好这项收集任务不需要你的意志力。我相信当你给我拿来我需要的东西时，也一定会对我给你的报酬满意的。"
D.Strings[821]="到中部高地的“本娜的炼金店”去找本娜，她可以指导你学习配制药剂的方法。"
D.Strings[822]="你想知道如何用铁砧和锤子制作东西吗？卡恩·石蹄可以教你这些。他是个铁匠，就在中部高地的水池旁。"
D.Strings[823]="在雷霆崖，你肯定找不到比阿丝卡·迷雾行者更好的厨师。嗯……我在这里都可以闻到他正在烹制的美味佳肴。你可以在中部高地的厨房里找到她。\n\n呃……我又饿了。"
D.Strings[824]="到中部高地的附魔店去看看吧。泰戈会很乐意帮助你的。"
D.Strings[825]="急救是一项很有用的技能。在战斗中，它常常能救人一命。如果你想要学习这项技能的话，就去灵魂高地的“精神治疗”小店里面找找潘德·缚石，他可是这方面最好的训练师。"
D.Strings[826]="我不会因为你想学钓鱼而责怪你的。莫高雷有卡利姆多大陆上最好的钓鱼胜地，而在山顶渔具店中，你可以找到钓鱼所需的一切装备。\n\n告诉卡尔·迷雾行者是我让你去的！"
D.Strings[827]="如果你想要学习草药学的话，就应该去找克米恩·冰蹄谈谈。他在中部高地那里。"
D.Strings[828]="去雷霆崖中部高地的雷霆崖防具店找犹纳吧。"
D.Strings[829]="去中部高地的石蹄地质学会找布瑞克·石蹄，他会教你如何采集矿石和宝石。"
D.Strings[830]="坦帕以她制作的衣物而闻名，你可以在中部高地的雷霆崖防具店找到她。"
D.Strings[831]="莫兰塔可以教你如何剥皮。你可以在中部高地的卡恩铁匠铺旁找到她。"
D.Strings[832]="这块被诅咒的土地上的野兽拥有超自然的能力。$B$B我们的研究表明，在黑暗之门打开的时候泄漏出了特别的能量，这种能量注入了那些野兽的体内，并把它们变成了现在的样子。$B$B毫无疑问，这些野兽非常危险，但是我们也认为它们能够在我们的研究中发挥很大的作用。$B$B$n，也许你有兴趣帮助我们研究这些野兽？"
D.Strings[833]="%s将在10秒内安装完毕！"
D.Strings[834]="%s将在5秒内安装完毕！"
D.Strings[835]="%s已经安装完毕！"
D.Strings[836]="我的兄弟德拉吉亚专注于研究诅咒之地上的这些野兽的生理特点，而我则倾向于研究它们的精神特点。$B$B那些野兽确实具有相当惊人的力量、敏捷和耐力，而且还拥有惊人的智力和重生能力，这和它们的外表显得不太符合。$B$B$n，你是不是有兴趣来协助我进行研究呢？"
D.Strings[837]="很难想象如此多的死亡和恐惧会汇集在那么小的一块地区中。在这些门后是一块充斥着混乱和毁灭的大陆。$B$B冒险者，你要非常小心谨慎才行。诅咒之地中到处都是可以让你丧命的强大生物。"
D.Strings[838]="作为萨尔手下最强大的二十名战士，我们被称为萨尔近卫军。$B$B在等待奥格瑞玛的命令时，我要求在诅咒之地边境建立一座营地。但是数星期过去了，酋长那里还是没有任何消息传来，我们开始变得有些焦躁不安了。$B$B$n，那是个错误的决定。我曾经年轻而又雄心勃勃，无所畏惧。这支部队在我的指挥下开进了诅咒之地。$B$B不久之后我就开始后悔了。"
D.Strings[839]="后悔。这就是现在我所能感受到的一切。一个错误的决定导致了如此灾难性的后果。我多么希望当时能多等几天，直到命令传来。也许那样我们就能事先知道这片被诅咒的土地上到底有多少恐怖的东西等着我们！也许这一条命令就能指引我们去另外一个方向！无论怎么样，这都是我的错。所有的一切都是我造成的。"
D.Strings[840]="你们怎敢侵入我的圣地！"
D.Strings[841]="让混沌之火将你吞噬吧！"
D.Strings[842]="伊利法尔，你的主人在召唤你！"
D.Strings[843]="面对我的勇士吧，凡人！"
D.Strings[844]="准备坠入无限的痛苦深渊吧……我要复仇……"
D.Strings[845]="你能相信作为精英战士的我居然失败了吗？$B$B我们的部队被无法抗拒的力量彻底摧毁，我所记得的一切就是不顾一切地逃跑，我所听到的一切只有我的战友撕心裂肺的惨叫和我自己的心跳。$B$B过了不久，我又回到了诅咒之地，希望能拯救我的伙伴。但是我被抓住了，最后被活活打死。$B$B这段日子中，我所能感受到的只有恐惧。"
D.Strings[846]="请继续，英雄……"
D.Strings[847]="我被抓之后遭受了非人的虐待，$n。他们轮番拷打我和基利斯中尉，而且在虐待一方的同时让另外一个在旁边看着。我们不断被折磨，直到有一天基利斯把战友们的遭遇告诉了我，还有他的拯救计划。$B$B他们所遭受的痛苦比我和基利斯所遭受的还要多，他们真的是生不如死。"
D.Strings[848]="有什么比死亡还要痛苦？"
D.Strings[849]="你和我都无法想象当他们的灵魂被强行从躯体中剥离出来的时候有多么痛苦。他们没有死，但是他们也不是活着的。他们成为了一具具行尸，只会听从主人发号施令。$B$B干出这些惨绝人寰的事情的就是这里的恶魔首领拉瑟莱克，他把我的战友都变成了奴隶。其中的九个被他绑定在黑暗之门附近，其余的九个则被他的爪牙们瓜分。"
D.Strings[850]="手下？"
D.Strings[851]="大法师奥利斯塔，术士瑟温妮，还有食人魔戈洛尔，他们各自分配到了三个。$B$B$n，你要知道，如果没有灵魂，我的战友是无法被杀死的。他们现在都处于一种无敌的状态。幸好的是，他们不能离开禁锢之石太远的距离。"
D.Strings[852]="禁锢之石是什么？"
D.Strings[853]="那些禁锢之石就是你要去摧毁的东西！正如我刚刚所说的，基利斯有一个完整的计划。$B$B每个被奴役的战士都有一个弱点，你必须尽量攻击他们，直到他们的实体形态几近瓦解。这时禁锢之石就会变得非常脆弱。你一定要抓紧时间摧毁禁锢之石，否则不久之后，那些奴隶又将获得新的力量，并再次变得刀枪不入了。"
D.Strings[854]="英雄，你可以信赖我。"
D.Strings[855]="我想你真的可以帮我，$n，但是单凭你的力量是无法和拉瑟莱克以及他的爪牙抗衡的。$B$B你一定要找到一支足够强大的队伍来解救我的战友，让他们脱离无尽的痛苦！你总共要摧毁十八块石头。$B$B努力地去战斗吧，$n。"
D.Strings[856]="需要一些炼金术的材料吗？或者你有别的什么事情？"
D.Strings[857]="啊，注意！"
D.Strings[858]="$n，等在这里。间谍机器人会尽快让他们出来的。准备好！在听完他们的对话之后再发起攻击。"
D.Strings[859]="大人，您的客人到了。他正在等你。"
D.Strings[860]="英雄，我有紧急的事情要和桑德·裂蹄商讨。"
D.Strings[861]="你们好。我要找莱斯科瓦公爵谈谈。"
D.Strings[862]="谢谢，愿圣光与你们同在。"
D.Strings[863]="当然，他在图书馆等您。"
D.Strings[864]="啊，非常感谢。当我料理好这件小事之后就去图书馆。"
D.Strings[865]="好了，我这就去！"
D.Strings[866]="林吉自由了！"
D.Strings[867]="林吉现在可以看到路了，$n。林吉认识回家的路。"
D.Strings[868]="阁下，我会善用时间的。谢谢您。"
D.Strings[869]="这沙漠可真不是人呆的地方！在这种高温下还得站在外面，我都快渴死啦！"
D.Strings[870]="备用动力启动！启动流动电机！咯咯嗒！"
D.Strings[871]="侦测到威胁！实施躲避动作！咯咯嗒！"
D.Strings[872]="威胁分析！启动二号战斗计划！咯咯嗒！"
D.Strings[873]="咯咯嗒！探测到空间异常——危险临近！咯咯嗒！"
D.Strings[874]="救命！$B$B如果你能帮我离开这里，我就帮你炸开通向祖尔法拉克酋长所在地的那扇门！"
D.Strings[875]="我们要杀掉更多的巨魔！杀了足够的巨魔，我就炸开巨魔酋长的门！"
D.Strings[876]="谢谢你，$n。你出现的真是时候，我差一点就死于非命了！现在我们只差打破这扇门就能面对巨魔酋长了……"
D.Strings[877]="你现在可以炸开那扇门了吗？"
D.Strings[878]="救命啊！我的队伍被巨魔俘虏了，他们准备杀了我们！$B$B只要你能救我们出去，我会答应你的任何条件！"
D.Strings[879]="没有时间聊天了！我们必须马上想办法对付那些巨魔！"
D.Strings[880]="$n，非常感谢你。没有你，我们绝对没办法逃离魔爪。哦，如果我刚才说过要报答你之类的话……忘掉它吧！"
D.Strings[881]="没人敢挑战废土强盗团——机械小鸡也不行！进攻！"
D.Strings[882]="你好！如果你想要接受一些挑战的话，我这里有个建议给你！$B$B我正在利用我发明的超级测蛋器帮助暗夜精灵的德鲁伊们拯救鹰角兽。由于菲拉斯废墟中的戈杜尼食人魔，这种生物的数量正在迅速减少。$B$B我收集各种不同类型的蛋。"
D.Strings[883]="请告诉我更多关于角鹰兽的信息。"
D.Strings[884]="这里西边有一处叫做菲拉斯的地方，那一带的鹰角兽正处于危险的境地中。$B$B我需要你从菲拉斯南部的伊斯迪尔废墟中给我带回鹰角兽的蛋，超级测蛋器会分析你带回来的蛋，并判断它是否可以孵化。然后我可以把蛋送到达纳苏斯去孵化，避免它们受到戈杜尼食人魔的黑暗魔法的影响！$B$B$n，你要知道，有些蛋即使完整无缺也是不可能孵化出来的。"
D.Strings[885]="飞行系统启动！咯咯嗒！发动火箭并准备传送到藏宝海湾！"
D.Strings[886]="林吉现在可以告诉你我的秘密了……$n应该去望海崖。林吉在那里的小岛上藏了一点东西。"
D.Strings[887]="你找到它，它就是你的了！不要把林吉告诉你的秘密告诉任何人！"
D.Strings[888]="进攻，我的姐妹们！一个巨魔都不要放过！"
D.Strings[889]="我会的。"
D.Strings[890]="林吉被攻击了！"
D.Strings[891]="林吉需要帮助！"
D.Strings[892]="什么？你怎么敢这么对我说话？！"
D.Strings[893]="我们就此结束了？好吧，我一点都不喜欢你！！"
D.Strings[894]="你好，$n！如果你需要的东西在我店里找不到，那么我可以专门去帮你找一下！"
D.Strings[895]="请告诉我更多关于戈杜尼食人魔的信息。"
D.Strings[896]="庞大的戈杜尼食人魔部落控制了菲拉斯森林的很大一块区域。他们的黑暗魔法已经渗透了周围的环境，从而直接对那里的其它生物造成了毁灭性的打击。$B$B如果你去菲拉斯的话，可得小心那些食人魔——他们非常肮脏，而且很多都会使用强大的黑暗魔法。"
D.Strings[897]="铁匠？真少见啊。我能为你做什么吗？"
D.Strings[898]="迪菲亚兄弟会必胜！没有人能阻止我们！"
D.Strings[899]="如果不住在有大理石天花板的房间里，我就浑身不舒服。天上的星星让我觉得很烦燥……"
D.Strings[900]="这确实是一件上好的护甲，它给我留下了深刻的印象。我只知道谁可以打造出同样品质的护甲，他叫格鲁努斯·削钢，就在铁炉堡的大煅炉那里。我相信那位锻造大师一定可以教你不少东西。"
D.Strings[901]="大煅炉在铁炉堡的最中心。他就在那里和其他的铸造大师一起工作。"
D.Strings[902]="欢迎你，铁匠。让我和你分享一些秘密吧。在这世界上，你不能相信任何人。任何人……你能相信的只有钢铁。"
D.Strings[903]="你有什么事？你是来接受训练的吗？你是来寻找钢铁的秘密的吗？还是要学习锻造的技巧？快说！"
D.Strings[904]="到奥格瑞玛的荣誉谷去找她。她和她的丈夫还有两个孩子都住在那里。他们都是出色的铁匠，而她将会是你最好的导师。"
D.Strings[905]="你已经在锻造方面有了相当的造诣，可以把钢铁变成护身的铠甲。你的技艺已经超过了我，我必须让你去更好的锻造训练师那里深造。$n，你应该去奥格瑞玛找莎伊斯·钢怒，她是我所知道的最好的铸甲师，她应该能教你很多东西。"
D.Strings[906]="所有东西都有灵魂，如果学会聆听它们的声音，你就可以随心所欲地使用它们的力量。锻造并不是击打金属并将其改变成自己想要的形状那么简单，你必须倾听钢铁的声音，然后指引它，让它为你所用。"
D.Strings[907]="你似乎正在寻求知识。也许你在找寻锻造之道，也许我能在这条道路上指引你。但是一旦你决定从事铁匠这个职业，你就应该学会聆听钢铁中的那些灵魂的呼喊。"
D.Strings[908]="到奥格瑞玛去，你可以在荣誉谷找到她和她的家人。"
D.Strings[909]="你所锻造的护甲能够抵挡最锋利的刀刃。$n你给我留下了深刻的印象，这可不容易。去找一个名叫莎伊斯·钢怒的兽人吧，她是除了那些该死的矮人之外最好的铸甲匠。"
D.Strings[910]="你铸造的武器怎么样？你认为它能轻易击败敌人吗？让我来告诉你如何把它变得更加锋利吧。"
D.Strings[911]="想要成为一名铁匠？想要锻造出最好的武器？我可以帮你，希望你能对这门手艺投入最大的热情。"
D.Strings[912]="到兽人城市奥格瑞玛去，他就在荣誉谷的“传说中的装备”那家店里。"
D.Strings[913]="$n，你铸造的武器很不错，已经达到切金断玉的水准了。但是我还认识比你的技艺更加精湛的铁匠，那是一个名叫克尔格鲁克·血斧的兽人，去找他继续学习吧！"
D.Strings[914]="$n，欢迎回到大锻炉。你是来拜访我的，还是准备进行下一阶段的训练？"
D.Strings[915]="$n，这些金属真不错。拿把铁锤过来，让我指导你如何锻造一把绝世的利器。"
D.Strings[916]="$n，你是回来学更多东西的吗？那么当你准备好的时候，我们就继续吧。"
D.Strings[917]="什么事？你没有看到我很忙吗？"
D.Strings[918]="$n，你的旅行怎么样？$g苏米和图米都很想念你，在你结束训练之后应该去拜访他们:我听说了一些关于你的故事，你似乎一直都很忙;。现在让我们来看看在你离开的这段时间里，你都学了些什么。"
D.Strings[919]="$n，我已经看到了你的潜力。现在拿上锤子准备开工吧，你需要大量的练习才能提高自己的水平。"
D.Strings[920]="我不会训练一点水平都没有的铁匠，等你觉得自己达到我的要求之后再回来找我。"
D.Strings[921]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-A，这是一台一级机密等级的终端。$B$B你必须拥有一张白色穿孔卡片才能够使用该终端的功能。\n\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001"
D.Strings[922]="白色穿孔卡片读取成功……$B$B正在分配二级机密等级权限。\n\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101"
D.Strings[923]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-B，这是一台二级机密等级的终端。$B$B你必须拥有一张黄色穿孔卡片才能够使用该终端的功能。\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001"
D.Strings[924]="黄色穿孔卡片读取成功……$B$B正在分配三级机密等级权限。\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001"
D.Strings[925]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-C，这是一台三级机密等级的终端。$B$B你必须拥有一张蓝色穿孔卡片才能够使用该终端的功能。\n\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000"
D.Strings[926]="蓝色穿孔卡片读取成功……$B$B正在分配四级机密等级权限。\n\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111"
D.Strings[927]="获取更高等级的权限卡"
D.Strings[928]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-D，这是一台四级机密等级级终端。$B$B你必须拥有一张红色穿孔卡片才能够使用该终端的功能。\n\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100"
D.Strings[929]="获取更高等级的数据卡。"
D.Strings[930]="红色穿孔卡片读取成功……$B$B正在分配四级机密等级权限。\n\n00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110"
D.Strings[931]="吉布尔-埃拉卡$B猛虎之神，万兽之王$B$B缪萨拉-安泰恩$B死亡之神，时间之子，睡眠之父，夜晚之友"
D.Strings[932]="沙德拉-艾罗萨$B蜘蛛之神，剧毒之母，蛛丝舞者，死亡之吻。"
D.Strings[933]="矩阵式科技知识检测器探测到了你所具备的工程学天赋。你可以从以下选项中进行选择：\n\n01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001"
D.Strings[934]="访问中……\n\n工程学<#技能等级 == 菜鸟>\n \n01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\n\n拒绝访问！"
D.Strings[935]="数据访问授权。祝你开心！\n\n01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011"
D.Strings[936]="卖新鲜的水果啦！"
D.Strings[937]="快来买这些苹果啊，又甜又脆的新鲜苹果！"
D.Strings[938]="产自茂密的艾尔文森林的新鲜水果，快来尝尝啊！"
D.Strings[939]="请等一下，$n。辛达尔在想办法把精灵龙从恐怖图腾营地中救出来。我们正巧路过这里，谁知道那些邪恶的牛头人对它们做了些什么。"
D.Strings[940]="有了你的帮助，我就可以测量这些通道了。"
D.Strings[941]="让我们看看能否发现这些穴居人是从哪里来的……然后想办法阻止他们！"
D.Strings[942]="太混乱了……简直一团糟……"
D.Strings[943]="向你致敬。我是这个入口的守卫。除非你的圆盘中包括奥丹姆圆盘，否则我是不会让你进入奥丹姆的。"
D.Strings[944]="你的职责是什么？"
D.Strings[945]="我的职责是为造物者守卫奥丹姆的入口。只有拥有正确的圆盘才能进入其中。$B$B你的圆盘中没有包含奥丹姆圆盘，所以你不具备进入奥丹姆的基本条件。除非奥丹姆圆盘存在，否则你无法进入。"
D.Strings[946]="什么是奥丹姆圆盘？"
D.Strings[947]="奥丹姆圆盘在哪里？"
D.Strings[948]="什么？我们的世界“被安排了新的探访计划”？这是什么意思？！"
D.Strings[949]="那么……奥丹姆里面到底有些什么？"
D.Strings[950]="我找到奥丹姆圆盘之后会回来的。"
D.Strings[951]="拥有奥丹姆圆盘才能够进入奥丹姆。这些圆盘中储存了造物者在这里的所有活动的纪录。$B$B从组成上来看，这些圆盘各不相同。它们的标注则只和奥丹姆信息相关，与奥达曼圆盘截然不同。"
D.Strings[952]="造物者制造了若干张奥丹姆圆盘以供使用。他们控制着向整个世界分配奥丹姆圆盘的工作。同样，艾泽拉斯已经被安排了新的探访计划，到那时，未来的奥丹姆圆盘也许会重新开始流通。$B$B现有的奥丹姆圆盘已经被全部分给了具有一定忠诚度的种族。"
D.Strings[953]="当外部势力和内部势力相互冲突，以至于扰乱整个世界的时候，造物者将探访计划作为重新控制世界的手段，不过执行这样的策略并不容易。$B$B关于预先安排的探访计划的更多信息，请查询所有与造物者相关的数据库。"
D.Strings[954]="奥丹姆是一座为维系艾泽拉斯的自然体系而建造的研究工厂。只有那些拥有奥丹姆圆盘的人知道创世者在奥丹姆所进行的研究工作的详细情况。$B$B奥丹姆中的数据库被用于进行特殊的试验和数据编辑，更多详细信息，请查询数据库。"
D.Strings[955]="感谢圣光！现在情况十分紧急，即使有一个双头食人魔愿意施以援手，我也会欣然接受的。\n\n这座城市里到处都是穴居人！为了把它们赶出这里，我们采取了一些行动，但是却导致这一地区遭受了大面积的污染。幸好我们还有希望！\n\n我们疏散到铁炉堡的科学家正在研究对付辐射疾病的方法。同时，如果你能帮我阻止穴居人的入侵，那也许我们就能够夺回我们的城市！"
D.Strings[956]="我准备好了。"
D.Strings[957]="$n，给我几分钟时间。这里刚刚发生了一些事情，我要去确定一切都已经搞定了。我会马上会来继续和你谈谈的。"
D.Strings[958]="这里很安静……"
D.Strings[959]="……太安静了。"
D.Strings[960]="看！在隧道那边！"
D.Strings[961]="穴居人过来了！保护我，我要把这个洞炸掉！"
D.Strings[962]="一发炸弹还搞不定，继续保护我！"
D.Strings[963]="炸弹安放好了。向后撤，炸弹马上要爆炸了！"
D.Strings[964]="炸弹将在10秒内爆炸！"
D.Strings[965]="炸弹将在5秒内爆炸。清理通道！向后撤！"
D.Strings[966]="欢迎你，$c。如果你有什么问题，尽管来问我。"
D.Strings[967]="警报！警报！入侵警报！入侵警报！"
D.Strings[968]="就这么办吧！我实在是厌倦了事事都帮你。我们到战场上去解决问题吧！"
D.Strings[969]="你们的午饭来了，孩子们。把它们全部吃光吧！"
D.Strings[970]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-A，这是一台一级机密等级的终端。$B$B检测到白色穿孔卡片。权限开放。\n\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111"
D.Strings[971]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-B，这是一台二级机密等级的终端。$B$B检测到黄色穿孔卡片。权限开放。\n\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001"
D.Strings[972]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-C，这是一台三级机密等级的终端。$B$B检测到蓝色穿孔卡片。权限开放。\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001"
D.Strings[973]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-D，这是一台四级机密等级的终端。$B$B检测到红色穿孔卡片。权限开放。\n\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111"
D.Strings[974]="保护你们的主人！"
D.Strings[975]="苏利萨斯的子嗣会保护他们的主人……"
D.Strings[976]="和我们战斗的那些生物的灵魂，或者说“灵魂精华”中存在着不可思议的力量。$B$B看清你的内心；学着驾驭你的灵魂之力吧，你将获得超乎想象的强大力量。"
D.Strings[977]="苏萨斯……第一次听到这个词的时候，我还和你一样大。那个时候这个词对我来说没有什么意义，就好像现在它对你没有什么意义一样。但是当一群巨魔从祖尔法拉克来到这里肆意妄为之后，这个词就变成了恐惧的代名词。$B$B这里的人都会告诉你痛苦双刃并不存在，那只是一个神话，一个用来吓唬小孩子的故事。但是，$r，请相信我，它确实存在。$B$B<说到这里，特伦顿不禁开始用手抚摸自己脸上累累的伤疤。>"
D.Strings[978]="请继续说下去，特伦顿。"
D.Strings[979]="分久必合，合久必分。那两把剑被隐藏在祖尔法拉克城中。$B$B苏萨斯会在两把剑都被发现时重生。"
D.Strings[980]="干得好！没有你的帮助，我是无法抵挡穴居人的！"
D.Strings[981]="我听到那里有点动静。"
D.Strings[982]="穴居人！挡住它们，我要准备爆破了！"
D.Strings[983]="塞拉摩的卫兵都是原本驻扎在卡利姆多的联盟精英力量。即使远离了家园，但我们还是会努力维护联盟的律法。"
D.Strings[984]="我们对于树荫旅店被焚烧以及詹姆斯·海厄尔的妻子和孩子没能及时逃脱这些事情了解得并不多。$B$B我们想要找到詹姆斯的尸体，但是他却根本不在那堆废墟中。$B$B我们有一些线索，但是证据仍然很缺乏。我们希望能通过卫兵和塞拉摩人民的帮助让这件惨案得以大白天下。$B$B如果你也想帮忙的话，可以到贫瘠之地的边境那里调查一下旅店的废墟。"
D.Strings[985]="关于树荫旅店，你都听说过些什么？"
D.Strings[986]="你看到他们了吗？当然没有……我认为你是看不到的。以你的资质，即使有眼睛也和瞎了没有什么区别。"
D.Strings[987]="在抵抗燃烧军团时期，污染者拉瑟莱克是卡扎克麾下最强大的将领之一。当燃烧军团被击退，卡扎克的势力被压制之后，拉瑟莱克接受了诅咒之地的事务。$B$B当联盟和部落在诅咒之地以外的地方打得天昏地暗的时候，拉瑟莱克则在召集阴影议会的教徒，以及野蛮的巨槌食人魔。"
D.Strings[988]="可悲的是，正是因为萨尔的智慧才导致了恶魔之王和其它势力联合起来，特雷博的军队促成了恶魔之王、阴影议会和巨槌食人魔之间的联合。对于力量的无尽渴求使得他们签下了血契，对恶魔效忠。"
D.Strings[989]="瑟温妮、奥利斯塔和戈洛尔都没有意识到，其实他们和那些奴仆一样，都被永远禁锢在这片土地上了。他们所获得的不朽之力其实就是要永远为拉瑟莱克卖命。狡猾的拉瑟莱克又一次获得了胜利。"
D.Strings[990]="$n，他们的意识已经被污染了。是的，情况越来越严重。他们现在只会为拉瑟莱克而活。他们手中的护符碎片就是召唤恶魔之王的钥匙。但问题是，他们已经对于常规的攻击方式完全免疫了。"
D.Strings[991]="那么让我们假设你即将开始这段漫长而又艰辛的任务，你要做的是就是想办法摧毁这三个家伙的防御结界。然后呢？去污染者拉瑟莱克的巢穴挑战他？$B$B<洛拉姆斯大笑着。>"
D.Strings[992]="人类宣称尘泥沼泽是他们的领地，但是石槌部族在我们的帮助下将他们赶了回去。"
D.Strings[993]="烧毁的旅店。"
D.Strings[994]="人类在贫瘠之地的边界处建了一座旅店，他们叫它树荫旅店。几个星期前，这家旅店被烧掉了。$b$b为什么我会在意这种事？当然，我并不关心人类的死活。但我在那家旅店里安插了一名间谍。我不会让他就这样白白死掉。我要知道这是谁干的。$B$B如果你想帮忙的话，就去查看一下树荫旅店的废墟，把你能找到的线索都给我带回来。"
D.Strings[995]="寻找帕瓦尔·雷瑟。"
D.Strings[996]="如果雷瑟和树荫旅店被烧毁的事有某种联系的话，你就得找到他，问个清楚。$b$b我派了奥格隆去追他，应该是朝东南方向去了。去跟奥格隆会合，然后一起去找雷瑟吧。"
D.Strings[997]="会发生什么糟糕的事情？"
D.Strings[998]="你疯了吗？你难道不知道那里都是些凶残无比的野兽？我们可能得使用铲子才能挖出你的尸体。我们已经在那里损失了太多生命了。$B$B我的答案是，不行。如果你想要去灼热峡谷，那么我只能说抱歉了，此路不通。"
D.Strings[999]="此路不通？那还有别的路吗……"
D.Strings[1000]="我原本不想告诉你的：如果你能够穿过荒芜之地的话，那么你也许可以找到通往灼热峡谷的另外一条路。$B$B没错，我说的是荒芜之地。在卡加斯营地那里，兽人铺了一条通向灼热峡谷的小路。你说说他们有多蠢吧！那帮家伙居然造了一条通向地狱的道路？他们到底在想什么啊？"
D.Strings[1001]="兽人？荒芜之地？小意思！"
D.Strings[1002]="小意思？"
D.Strings[1003]="当然！"
D.Strings[1004]="不听我的劝告，你就等着有人来给你收尸吧！别以为你自己无所不能，小心使得万年船！"
D.Strings[1005]="对不起，贝波蒂。"
D.Strings[1006]="你猜怎么着，既然你觉得自己是个英雄，那么就穿过荒芜之地到灼热峡谷去，拿回一些能证明你的实力的东西，这样我也许能想办法帮你搞到一把钥匙。$B$B在灼热峡谷的最西南角有一个强壮的女士，嗯，几乎跟我一样强壮，她的名字叫狂暴的玛尔戈。也许你应该先去找她谈谈……"
D.Strings[1007]="完成了，全部完成了。"
D.Strings[1008]="可怜的杜里奥斯。那些黑铁矮人真是该死，帮帮我吧……"
D.Strings[1009]="就是这样，全部搞定了！"
D.Strings[1010]="当你待在旅店里的时候，你就可以好好地休息。因此,你可以比留在野外更快地恢复到精力充沛的状态，这样就可以获得更多的经验值。$B$B另外你还可以通过和旅店老板交谈来获得一块炉石，以后就可以使用这块炉石快速回到你绑定的旅店里了。"
D.Strings[1011]="全部准备就绪。后退！"
D.Strings[1012]="10秒钟后爆炸！退后！"
D.Strings[1013]="5秒钟后爆炸！！！！"
D.Strings[1014]="我们从地底而来！你们无法阻止我们！"
D.Strings[1015]="你现在进展顺利，$n。但是你还有很多东西要学的，南贫瘠之地将是你获得进一步发展的地方。"
D.Strings[1016]="虽然我们把这块土地称作贫瘠之地，但对于睿智者来说，这里到处都是生命。"
D.Strings[1017]="你不知道你干了什么！我们要为了你的利益而毁灭你。"
D.Strings[1018]="听着，塔纳利斯的居民！我宣布$n已经成为秘银会的成员之一。他是一个光荣而且极具耐心的铁匠。为$n欢呼吧！"
D.Strings[1019]="我出售山谷这一边最好的布料和皮革服饰！"
D.Strings[1020]="在丹莫罗寒冷的日子里，没有什么比热酒更好的东西了！"
D.Strings[1021]="哦，热啊热！如果这样的热度都不能让你跳起来，那你简直就是块石头了！"
D.Strings[1022]="告诉我关于发光的碎片的事情。"
D.Strings[1023]="你已经比许多人都走得更远了，$n。敬畏大自然的力量，你就会取得比大多数人都要伟大的成就。"
D.Strings[1024]="祭坛似乎在召唤你，好像它具有生命一样。"
D.Strings[1025]="触摸苏塔拉之石，召唤黑衣拉索里克和他的守卫者奥比斯顿。"
D.Strings[1026]="赞美艾露恩！好些年都没有人来拜访我了。"
D.Strings[1027]="我想要听听你的故事。"
D.Strings[1028]="作为黑海岸的一名年轻的暗夜精灵，我遇到了一队暮光之锤的成员。他们待我如同亲人，因此我背叛了对艾露恩的信仰，听信了他们的蛊惑之言。$B$B直到艾露恩的幻影从我眼前闪过，我才幡然醒悟。$B$B我满怀悔恨，开始向艾露恩祈祷。"
D.Strings[1029]="萨麦尔，请继续。"
D.Strings[1030]="我的自责、羞愧、懊悔和悲伤全都刻在这块纯金石板上。不幸的是，暮光之锤找到了石板，并认定我是诅咒者。我被立即处死，而那时我对艾露恩的祷告还没有做完。现在我已经成为了一个游荡的幽灵，无法降入扭曲虚空；我被关在笼子里，用来警告那些试图背叛暮光之锤的人。"
D.Strings[1031]="让我考虑一下，萨麦尔。"
D.Strings[1032]="古老的哈卡祭坛静静地矗立在房间的入口处。$B$B你注意到阳台上有一尊巨大的毒蛇雕像立在那儿。它看上去跟祭坛上的雕像非常相似。它们之间一定有什么联系……"
D.Strings[1033]="祭坛和雕像会有什么联系？"
D.Strings[1034]="这个地区有许多生物都是暗夜精灵的同盟。精灵们可以借助这些生物的能量来为自己效劳。部落也应该拥有这种能力。我想到一个方法，可以捕捉到这种能量并为我们所用。$B$B不要怀疑我告诉你的事情，$n。帮助我，你就会知道我所说的都是实话。"
D.Strings[1035]="如果你是个裁缝，维兹格里克肯定有你想要的东西！随便看看，$n，想要买什么东西就和我说！"
D.Strings[1036]="收拾你的行装，$n！我从灼热峡谷那边的尼莉丝·洛克拉夫收到消息说，有个被称作“黑市组织”的团体正在大熔炉一带运作。到灼热峡谷去找到尼莉丝·洛克拉夫，然后把那个黑市组织连窝端掉。"
D.Strings[1037]="房间中出现一道明亮的光束，随即消失了。然后你注意到了另一道光束……又一道光束。$B$B它们似乎拼接出了某种图案。"
D.Strings[1038]="我要复仇。"
D.Strings[1039]="可以告诉我究竟是什么在驱使你去复仇吗？"
D.Strings[1040]="我父亲被大熔炉中的恶棍杀害了。我恳求暴风城给予援助，但是他们根本没有理睬。不仅如此，他们甚至不愿意承认这个地区的存在，更不要说派遣军队来匡扶正义了。$B$B我要报仇，$c。这世界上还有比这更强烈的理由吗？"
D.Strings[1041]="正如你所见的一样，我只不过是单枪匹马。黑铁矮人和拉格纳罗斯的爪牙可以轻松把我摆平，但是我对于像你这样勇敢的冒险者充满了信心，你一定可以把大熔炉里的那些东西全部搞定的。如果你愿意帮助我，我会给予你丰富的奖励，那些奖励将是你做梦也想不到的。"
D.Strings[1042]="让我跟同伴交换一下意见。"
D.Strings[1043]="我们要奴役野猪人！"
D.Strings[1044]="我们要统治这片贫瘠之地！"
D.Strings[1045]="亡灵天灾很快就将统治世界！"
D.Strings[1046]="我的眼睛！它在燃烧……它在燃烧……"
D.Strings[1047]="不要再烦我了！放了我吧，凡人！悲伤沼泽……凡人……求你了……"
D.Strings[1048]="愚蠢的凡人，只要我被释放出来，我就要撕碎你的灵魂！"
D.Strings[1049]="你是邪恶之神的奴仆，愚蠢的家伙。我要见证你的毁灭！"
D.Strings[1050]="我的灵魂不是用来当装饰品的！凡人，你必须将我从枷锁中释放出来！"
D.Strings[1051]="这对我的伤害太深了……伊萨里奥斯，我的老朋友……请帮帮我……"
D.Strings[1052]="什么时候噩梦才能结束？！我不能强迫自己醒过来！"
D.Strings[1053]="我没能守护好神殿……我堕落的灵魂将永远无法平静……"
D.Strings[1054]="太棒了！在你的帮助下，我们又有机会夺回我们挚爱的城市了。让我们为你大声为你喝彩吧！"
D.Strings[1055]="耐心一点，$n。火炬就要完成了。"
D.Strings[1056]="我热烈欢迎你的到来，$c。你远道而来仅仅是为了找一个住在洞里的家伙，我相信你的这次旅程一定是有重要的事情，对吗？"
D.Strings[1057]="你好，$G先生:小姐;。我是克希雷姆大人的学徒尼瑞尔。如果你们有任何问题，请随意向主人询问。$B$B当你准备下山的时候，就过来找我吧。"
D.Strings[1058]="我知道你是谁，$n。由于某种原因，命运将你带到我面前，而且我对此并不感到高兴。在未来的日子里，你将做出很多抉择，我希望你拥有足够的智慧来做出正确的抉择。$B$B相信我吧，$c——总有正确的抉择。"
D.Strings[1059]="像你这样的精灵待在这种洞穴里干什么？"
D.Strings[1060]="你很好奇，这种好奇掩饰了你在理解能力上的缺乏。我说这些是因为，如果你来此有一个确定的目的，你要提的问题就会显得毫无意义。$B$B因为这个原因，我只好对你说再见。"
D.Strings[1061]="你知道有关伊兰尼库斯的事吗？"
D.Strings[1062]="你很清楚我知道这些，$r。我们坦率地说吧。$B$B很明显你来这里是因为你知道自己拿着什么样的东西，你在哈卡的神庙中得到的这件东西使你身负着一件使命来到我面前。这个使命就是让我的伙伴……我的兄弟，得到安息。他被困在翡翠梦境的噩梦中，他自己无法解脱出来。"
D.Strings[1063]="他究竟怎么了？当我……当我遇到他的时候，他显得非常邪恶。"
D.Strings[1064]="阿塔莱巨魔所崇拜的神灵曾经受到惩罚。我们毁掉了他的肉身并把神庙沉入水中，但是他比我们预料中的要强大得多。堕落的种子散播开来，腐化了它所接触的一切。$B$B伊兰尼库斯负责看守沉没的神庙，以确保阿塔莱巨魔或是阿塔莱神灵都不会再死灰复燃。他是个无辜的受害者，我们低估了堕落的力量。"
D.Strings[1065]="我拥有一部分伊兰尼库斯的精华。你想用它来做什么……或者要我做什么？"
D.Strings[1066]="你来到此地仅仅是第一步……如果你想帮助伊瑟拉的绿龙军团，这是个正确的选择。$B$B你到这儿来也许只是受到个人利益的驱使，也许是受到良心的谴责。什么缘由并不重要，重要的是结果：伊兰尼库斯所经受的痛苦令我从梦中惊醒，现在我要终止他的痛苦。我想请你帮助我完成这项任务。"
D.Strings[1067]="我会认真考虑你所告诉我的事情。"
D.Strings[1068]="有趣，真有趣……我知道有个德鲁伊居住在哀嚎洞穴上方的山顶，$n。她也许能告诉你有关这块碎片的更多信息。$B$B现在，我必须工作了！"
D.Strings[1069]="防御结界被摧毁了！醒来吧，阿塔莱！醒来吧！"
D.Strings[1070]="准备好，靠近点。要是你放松戒备的话，那些恶魔会从暗处跳出来偷袭你的。"
D.Strings[1071]="我们在艾萨拉度过的这段日子并不是辉煌而又灿烂的，但是我们仍然年轻而且热血沸腾——我们最终会获得胜利，这只是一个时间问题。"
D.Strings[1072]="贝尔戈洛姆派我们从奥格瑞玛到这里来帮助他，不过如果他成功了，那样整个部落就有了希望。$B$B虽然由于他一直以来都喜欢取悦女人，无数的兽人已经因此而丧生，但是他仍然是我们的指挥官，为了荣耀，我们只能尽力去做好。"
D.Strings[1073]="我不是为了荣耀而来这里的，$n。我来这里是为了兽人的骄傲。$B$B如果我没有拒绝贝尔戈洛姆的提议，那我肯定现在还在奥格瑞玛料理真正的生意。$B$B他对女人的渴望在杜隆塔尔的女性战士中尽人皆知，但是那仍然没有影响他成为大众情人。$B$B很幸运他并没有骚扰我太长时间——否则他会被砍成肉酱的。"
D.Strings[1074]="你好，$n。你是从奥格瑞玛来帮助我们的吧？很高兴见到你。我想尽快离开这片亡灵的森林，回到奥格瑞玛去喝酒度日。$B$B不过，我很想知道贝尔戈洛姆是如何说服你来这儿的。"
D.Strings[1075]="嗯，我大约需要5分钟的时间来完成关闭它的仪式。在我开始之后，你一定要好好保护我，否则我们都会没命的！"
D.Strings[1076]="还剩三分钟——我感觉到能量正在不断汇集！继续保护我！"
D.Strings[1077]="只有两分钟时间了！我们只完成了一半，不要放松警惕！"
D.Strings[1078]="再坚持一分钟！坚持住，仪式就要完成了！"
D.Strings[1079]="很好——我们成功了！雕像中的火焰即将永远熄灭！我就知道你能行的！"
D.Strings[1080]="你找塞纳里奥议会有什么事，$n？"
D.Strings[1081]="我知道，我知道，我知道我根本不知道自己在哪里！$B$B我的家在棘齿城，不过既然我的飞艇在这儿坠落了，那我不如现在就开始进行我的研究项目了！"
D.Strings[1082]="灵魂还在尸体旁徘徊。它那可怕的眼睛死死地盯着你……"
D.Strings[1083]="菲拉斯的土地经历了岁月的洗礼，$r。大地、树木和生物，它们改变着菲拉斯的现状和未来。$B$B跟这儿所发生的一切相比，双塔山可以算是亘古不变的了……"
D.Strings[1084]="为了让上来观光的旅行者安全地下去，我可以为你提供翅膀。"
D.Strings[1085]="你能帮我下去吗？"
D.Strings[1086]="嗯，既然你提及了这一点，不错，昨天下午我确实看见了奇怪的事情！$B$B当我从东南方的巨魔废墟处跑过时……好吧，我其实不是跑过去的，应该说是跳过去的……沙地真是太烫了！$B$B总之，当我从废墟旁跳过的时候，我注意到那儿有一座营帐。我不得不说，在那儿设立营帐是件可笑的事儿……我本来要到那里去看看的，但是一只疯狂的大秃鹫把我赶走了。"
D.Strings[1087]="谢谢你救了我！$B$B我是一名来自暴风城的厨师兼炼金师。我到这儿来是要帮我叔叔安古斯寻找草药和食物的，但是这些野猪人将我抓了起来。要不是你赶过来的话，我想我已经被它们煮着吃了。"
D.Strings[1088]="你会烹饪？我也会！你有什么独门菜谱可以传授给我吗？"
D.Strings[1089]="嗯……对，我这里确实有一些挺有用的菜谱。让我来教你吧！"
D.Strings[1090]="你是个炼金师？我也是。也许你可以教我些东西……"
D.Strings[1091]="不错，我确实知道一种罕见的炼金术配方。让我来教你吧！"
D.Strings[1092]="我要小心地配制这种——啊！……嗯，洒了一些出来，但是已经做好了！"
D.Strings[1093]="你好！如果你是来购买地精工程学图纸的，那你一定要知道，我们只为注册地精工程师服务。"
D.Strings[1094]="你好！欢迎你来购买侏儒工程学图纸。我们的扫描仪已经确认，你是注册侏儒工程师！"
D.Strings[1095]="你好，$g小伙子:姑娘;……我是奥格索普，你拥有的某件侏儒设备很可能就是我发明的！如果它爆炸了，那它就不是我发明的；如果它给你带来了财富，那我们可以讨论一下版权金的问题！$B$B哦，对了，如果你来自诺莫瑞根，那你可以走了。我没有什么跟你好说的。"
D.Strings[1096]="哦，这不是$n嘛！很高兴再见到你，我无法表达我对你的感激之情，你帮我及时完成了发明。$B$B我能为你做什么事吗？"
D.Strings[1097]="我是大工匠欧沃斯巴克，现代侏儒工程学领域的顶级设计师。我的工作就是用我们的闪亮崭新的扳手确保新的发明能够付诸实施！$B$B要是你碰巧懂得制造消除辐射污染的装置，那你算是来对地方啦……"
D.Strings[1098]="宝贝，让我来教你一个简单的加法守则：“地精”+“工程学”=“万事通”。告诉你其它算法的家伙肯定数学不及格。"
D.Strings[1099]="通过研究，我发现在哈卡的化身被击败之后，他的力量也会随之减弱。但是哈卡的大部分力量仍保留在扭曲虚空的深处。$B$B你曾经击败过哈卡的化身，$n。或许再次击败他的话就可以进一步削弱他的力量，也许有一天我们就将面对他的真身。$B$B我为你准备了一张卷轴，你可以用它在堕神圣地中再次召唤哈卡的化身。你敢再次迎接哈卡的挑战吗？"
D.Strings[1100]="你好，$c。虽然长期饮用烈酒已经让我的感觉变得迟钝了，但我的心灵之眼依然十分强大。"
D.Strings[1101]="你好，$n。我在这里训练和照料年轻的角鹰兽，你可以随意看看。"
D.Strings[1102]="请告诉我更多关于角鹰兽的事情。"
D.Strings[1103]="德鲁伊对世界上所有生物的生存状况都非常敏感。当我们知道这些鸟处于危险之中时，便设立了一套营救系统，防止它们遭受菲拉斯的堕落气息的影响。$B$B一个名叫克格尔·曲藤的侏儒负责这项工作，她收集鸟蛋并将其交给我照顾。$B$B我们总是在寻求更多的帮助，$n。或许你该前往加基森找克格尔谈一谈。"
D.Strings[1104]="$n，我要再次对你表示感谢。现在我会留在这里，等安全了再离开。"
D.Strings[1105]="谢谢你，小$c！"
D.Strings[1106]="你的烹饪水平实在是太低了。再去训练一段时间，也许我就可以教你一些我所知道的东西。"
D.Strings[1107]="你的炼金技能还不足以理解我所传授的知识。也许你应该晚些时候再来找我谈谈……"
D.Strings[1108]="魔法只会腐蚀那些意志薄弱的人。即便你不是术士，最好也牢记这一点。"
D.Strings[1109]="卫兵！"
D.Strings[1110]="要是你想去污染者高地的话，只管找我就行了。"
D.Strings[1111]="我想要挑战污染者。"
D.Strings[1112]="你好，$n 。你是来学习铁炉堡的历史的？"
D.Strings[1113]="当你准备听我讲述故事的时候就告诉我。"
D.Strings[1114]="我准备好了，阿克瑟努斯。"
D.Strings[1115]="数百年前，伟大的索瑞森城骄傲地矗立在富饶的大地之上，那里现在已经变成了荒芜的燃烧平原。$B$B索瑞森城是黑铁矮人的家乡，它那时正处于一场矮人的内战中。$B$B你知道，那片土地曾是赤脊山的一部分——直到有一天，索瑞森被一场大爆炸吞噬。城市变成一片废墟，周围的地区也被夷为平地。"
D.Strings[1116]="真惨。这是怎么发生的？"
D.Strings[1117]="我们不知道。$B$B活下来的黑铁矮人们躲入深山，并开始重建他们的城市。$B$B索瑞森的废墟上又出现了黑石塔和新的黑铁王国。他们在灼热峡谷内建立了新的防御工事，就在众所周知的大熔炉地区。$B$B一个关于远古邪恶力量控制黑铁王国的故事开始流传。"
D.Strings[1118]="很有意思，请继续。"
D.Strings[1119]="最近，黑铁矮人更加频繁地出现在地表上。他们在荒芜之地建造了堡垒，并派遣了庞大的探险队到奥达曼深处寻找古代的知识，他们甚至侵入了我们的祖国，攻击我们的巨石水坝。"
D.Strings[1120]="不可思议！他们怎么如此大胆？？"
D.Strings[1121]="我们需要一些冒险者的帮助，$n。你能帮我吗？"
D.Strings[1122]="我当然会帮忙的！"
D.Strings[1123]="很好！这就是你等待的机会！杀了他们！"
D.Strings[1124]="嗯，你好！如果你是来征收费用或者投递传票的，那你一定是将我认作别人了。非常抱歉！"
D.Strings[1125]="我想我的项链掉到湖里去了。那是我爸爸送给我的，他要是知道我弄丢了项链，肯定会气疯的。"
D.Strings[1126]="谢谢你，$g先生:小姐;，你找到了我的项链！你是最棒的！"
D.Strings[1127]="先不说外面的那些卫兵，我和我的兄弟们可都参加过海加尔山之战。谁想要在银行里面行窃，那就先过我们这一关。"
D.Strings[1128]="你好，$g先生:夫人;……你能花点时间帮帮我吗？求你了。"
D.Strings[1129]="我会用我的鲜血来保证这座银行的安全，你觉得很放心吧？"
D.Strings[1130]="再次感谢你帮助希拉里，$g先生:小姐;！我长大了也要成为你这样的英雄！"
D.Strings[1131]="你宁愿把你的货物交给一个地精吗?"
D.Strings[1132]="告诉我你要什么，别磨磨蹭蹭的。"
D.Strings[1133]="我活着的目的就是为主人服务。"
D.Strings[1134]="喵！"
D.Strings[1135]="我知道怎么跟小猫说话，喵喵说谢谢你。"
D.Strings[1136]="即使在和平时期仍然会有战争，而许多部落仍在酋长的领导下并肩奋战。你是来为奥格瑞玛而战的吗？"
D.Strings[1137]="你好，$n！我是一名熟练的技师，我叫斯库提。"
D.Strings[1138]="大地中蕴藏着许多秘密，$c。保护这些秘密是我们永远的职责。"
D.Strings[1139]="如果你是来浪费我的时间，那你就是在浪费整个塞纳里奥议会的时间。为你自己着想，希望你不至于那么蠢。"
D.Strings[1140]="在我们的家园面临重重危机的情况下……暴风城的官员们竟然将大批军队派往别处，我真不敢相信！$B$B来自西部荒野的盗贼和来自东西两面的豺狼人蜂拥而至，暴风城没有受到围攻可真是个奇迹。"
D.Strings[1141]="你好，$C。希望你是来支持我们的。野兽和盗贼在艾尔文森林肆意妄为，我们的人手不够，无法维持治安！$B$B如果你没有做过这样的工作，就去看看关于霍格的告示。他是森林中的一只野兽，我们一定要干掉他！"
D.Strings[1142]="你好，$n。欢迎来到塞尔萨玛，别忘了去本地的酿酒厂看看！"
D.Strings[1143]="欢迎来到塞尔萨玛，这儿是你在洛克莫丹的家！$B$B塞尔萨玛是个好地方，但是对那些相应召唤来到这儿的勇士来说，这里可不是个吃喝玩乐的地方！如果你想以联盟的名义挑战危险的话，就去读读贴在探险者协会塞尔萨玛分部外面的海报吧。"
D.Strings[1144]="嘿，$n！这场景不甚美观，是吧？地平线轻帆号沉在海底，我的手下狼狈不堪，我们的货物和乘客如同碎片一般到处都是，你也许会认为暴风城曾在这儿举办过节日庆典。$B$B麻烦事儿还不止这么点……"
D.Strings[1145]="我感觉到处都是阴谋。还有那些对我所做的事情缺乏理解的家伙，他们想要把我关起来！$B$B你最好不要牵扯进来。"
D.Strings[1146]="什么？我在干什么？你眼睛不好使吗？我是一个梦想家，亲爱的$g先生:女士;，我梦想我们的将来会更加美好。很明显，我充满远见。$B$B然而，有些人却在想尽办法把我们困在平庸的泥沼里。我告诉过他，我是一个梦想家，而大德鲁伊鹿盔却回答说，“哦，我们似乎还缺一些挖水沟的。”$B$B我会帮助塞纳里奥议会弄走周围的泥堆，直到平庸的枷锁从我们身上卸下的那一天。"
D.Strings[1147]="你好，$r。我是弗兰克罗恩·铸铁。你是来了解黑石塔和黑铁矮人的吗？"
D.Strings[1148]="我没有选择，至少我是这么认为的。我会忍受索瑞森的毁灭并与我的国王和同胞站在一起。$B$B在拉格纳罗斯的统治下，达格兰·索瑞森国王开凿了山脉的中央，并建立了黑石塔。我们不知疲倦地工作着，发誓要建立一座比以前的任何城市或堡垒都要坚固的矮人城堡……甚至将来也不会有能与之媲美的建筑。"
D.Strings[1149]="我眼睁睁地看着拉格纳罗斯的堕落渗透了整个黑铁矮人社会，使这个曾经荣耀的民族变得疯狂……变得邪恶。$B$B当黑石塔建造完毕时，我与同胞们共同生存下去的意愿也消失殆尽了。我作为新的黑铁矮人的英雄而死去。这座坟墓就在我亲手建造的城门处，作为对我的成就的敬意。"
D.Strings[1150]="请继续。"
D.Strings[1151]="我那柄巨大的战锤——铁胆之锤，被交给了新的建筑大师弗诺斯·达克维尔。这个家伙人品低劣，才疏学浅。$B$B这点就是你需要知道的，$n。我想阻止他。他无法将铁胆之锤的力量发挥到极致，但是如果他的后续者有这个能力的话，他们就会毁掉一切的，而这必将带来灾难性的后果。"
D.Strings[1152]="没错，但是如果你精通草药学的话，你会发现它非常有用！你要做的是用特别的种子来细心培育药草——而不是一遇到风吹草动就挥斧乱砍。虽然你即将得到的常青袋能让最没有经验的新手轻松进行种植工作，但那些对草药学有天资的冒险者将会得到更丰硕的成果。"
D.Strings[1153]="考虑清楚，$g小子:姑娘;，我可没心情顺着你的想法哄你。我在这里的工作是确认大德鲁伊的研究工作正在按计划进行，而不是跟那些不愿为塞纳里奥议会效劳的家伙聊天。"
D.Strings[1154]="您好，尊贵的$c。我这个塞纳里奥议会的谦卑的仆从愿祝福与您同在。"
D.Strings[1155]="小心一点，$c，我有一个为你准备的变形术……"
D.Strings[1156]="我喜欢馅饼。"
D.Strings[1157]="奶奶总是说世界上没有比一块自制的、鲜美的樱桃馅饼更好的东西了。"
D.Strings[1158]="这馅饼真好吃，你要尝尝吗？"
D.Strings[1159]="今天不太开心？尝尝这些樱桃馅饼吧。"
D.Strings[1160]="这块美味的樱桃馅饼能让小侏儒喜极而泣。"
D.Strings[1161]="尝尝樱桃馅饼吧，它会令你开怀大笑的。"
D.Strings[1162]="新鲜的樱桃馅饼！香味扑鼻，让你的眼睛发直！"
D.Strings[1163]="樱桃馅饼是我在整个艾泽拉斯最喜欢的食物。"
D.Strings[1164]="士兵们，干得好！轻松一下吧！"
D.Strings[1165]="绝不能让邪恶力量侵袭这个世界！来吧，孩子们！"
D.Strings[1166]="嗯，如果我能用树枝做掩护的话，那些守卫是看不见我的。"
D.Strings[1167]="你必须耐心一些，$n。我的间谍机器人正在进行非常精密的操作，马上就帮你搞定。$B$B哦，帮我个忙，尽量不要让莱斯科瓦看到你……我们要伏击他。"
D.Strings[1168]="艰难时期，嗯，$n？谁都需要帮助，我和我妻子也不例外。"
D.Strings[1169]="我想看看你出售的货物。"
D.Strings[1170]="%s疑惑地看着你。或许你该仔细看看？"
D.Strings[1171]="我想买点东西，行吗？"
D.Strings[1172]="你能告诉我怎样才能得到一份视灵药剂吗？"
D.Strings[1173]="当然，$n。看起来你是个值得信任的$r！我在一里开外就发现了……$B$B总之，说正经事。我需要一株灵根草才能制作视灵药剂。药剂所需的其它成分都是小菜一碟，但是灵根草就不是那么容易得到了。"
D.Strings[1174]="钥匙……拿到钥匙……格斯塔恩有……钥匙。"
D.Strings[1175]="你就不能有点出息么，$c？带我离开这儿！钥匙在审讯官那儿。"
D.Strings[1176]="嘿！嘿！叫你呢！$c！帮我离开这儿！"
D.Strings[1177]="%s呻吟着。"
D.Strings[1178]="好吧，让我好好看看这东西……"
D.Strings[1179]="哦，该死……"
D.Strings[1180]="……啊。"
D.Strings[1181]="快动手吧，肮脏的$r。$B$B<卡兰低下头，露出他粗壮的脖子。>"
D.Strings[1182]="我不是来伤害你的，卡兰。哥沙克派我来找你。他说你会告诉我关于公主的事情。"
D.Strings[1183]="一切都完了……"
D.Strings[1184]="我们还没有失去一切，卡兰！"
D.Strings[1185]="你看我像个傻子吗，$r？我可以签署她的死亡证明书！我为什么要信任你呢？"
D.Strings[1186]="因为你还活着，我的手也没有卡在你结实的短脖子上。"
D.Strings[1187]="<卡兰叹了口气。>$B$B我想……我想你是对的。$B$B哥沙克告诉我你的酋长有个大计划，一个可能会改变联盟和部落关系的计划。关于这点你知道些什么？"
D.Strings[1188]="没什么。我的任务是跟你谈谈，然后回去找萨尔。萨尔对营救公主的事情很有兴趣。"
D.Strings[1189]="那么听好了，$c。$B$B几个月前，湖畔镇的镇长派遣特使来到铁炉堡，恳求国王一同抵抗入侵赤脊山的黑石兽人。$B$B铁炉堡公主茉艾拉自愿前去援助，于是国王就指派了20个精英守卫，确保公主由洛克湖前往湖畔镇的途中一路平安，我也在卫队中。"
D.Strings[1190]="这就解释了你被关在黑石山下的囚房里的原因，是吧，矮人？"
D.Strings[1191]="<卡兰清了清喉咙。>$B$B我们艰难地穿过灼热峡谷的隧道，进入了这片饱经蹂躏的荒地。现在回想起来，这事情十分蹊跷。我们所遇到的危险只不过是在这个地区生存的一些野生动物，我们很容易就赶走了它们。$B$B我们轻松地抵达了黑石山，并毫不费力地穿过了这座由巨石砌成的堡垒。"
D.Strings[1192]="接下来发生了什么事？"
D.Strings[1193]="在我们穿越燃烧平原时遭到了敌人的伏击，有上百个黑铁矮人！他们从城墙内、平原上的岩石后面、还有岩石的裂缝中突然出现。他们包围了我们，很快就解决了那些答应帮助我们完成任务的英雄和守卫。$B$B很明显：这是一次早有预谋的伏击。他们似乎知道我们的每一步计划……"
D.Strings[1194]="你怀疑某个内部人员与此有关？向敌方泄密？"
D.Strings[1195]="还会有别的原因导致这种结果吗？一定是有人向黑铁矮人告密了。$B$B<卡兰在你面前挥舞着拳头。>$B$B帮帮我吧，如果我能离开这里，我发誓一定会把那个叛徒抓出来的。"
D.Strings[1196]="请继续讲你的故事。"
D.Strings[1197]="我说到哪里了？哦，对，我们被抓住了。我的伙伴被当场处死。他们没有杀我，但用山羊把公主带走了。我被带到了熔渣之池的拘留所，然后又被转送到了这座监狱里。$B$B也许他们是想用我这条可怜的小命勒索一笔赎金。或者他们只是想让我永远回忆那些缭绕在我脑海里的残酷事件。悔恨是最残忍的狱卒，$c。"
D.Strings[1198]="确实如此。"
D.Strings[1199]="她现在就在索瑞森大帝身边。他对她施加了某种可以改变思维的强大法术……而我只能待在这儿，束手无策。"
D.Strings[1200]="我会把门开着的，你怎么逃出去是你的问题。再见，卡兰。"
D.Strings[1201]="只有傻子才敢侵犯我的巢穴。"
D.Strings[1202]="我让你看看我的能力的证明，塞勒斯。"
D.Strings[1203]="<塞勒斯的眼睛熠熠生辉>$B$B我是囫囵吞了你呢，还是放你一条生路？$B$B或许你还有些用处……$B$B向我的奴仆发出挑战吧，$c。生存下来，并把你获胜的证据交给我。"
D.Strings[1204]="一个卫士倒下了！"
D.Strings[1205]="咕噜……咕噜……"
D.Strings[1206]="去大树以西的暗巷区中心寻找耶尔玛克药剂店。"
D.Strings[1207]="如果耶尔玛克认为你有能耐的话，他会教你配制药水的。去暗巷区中心的商店找他吧。"
D.Strings[1208]="跟燃烧的铁砧的萨鲁·钢怒谈谈。沿着红石谷矿业工会右边的道路走到尽头，去那的荣誉谷找他吧。"
D.Strings[1209]="或许有一天萨鲁·钢怒会教你学会制作一把质地精良的斧头。沿着红石谷矿业工会右边的道路，到荣誉谷的“燃烧的铁砧”店里去找他吧。"
D.Strings[1210]="扎姆沙在暗巷区上层的博斯坦的火坑。当你从力量谷进入暗巷区时走左边的楼梯。"
D.Strings[1211]="你肯定会想从扎姆沙那里学些什么的。当你从力量谷进来的时候走左边的楼梯到暗巷区上层的博斯坦的火坑去。"
D.Strings[1212]="古丹的符文工艺店就是你要去的地方。到暗巷区的西端可以找到，就在智慧谷的旁边。"
D.Strings[1213]="你能给我的斧头附魔吗？我需要永久性的。或许晚些。到智慧谷附近的暗巷区西端找到古丹的符文工艺店。"
D.Strings[1214]="阿诺克能制作很好的绷带。他住在精神山谷灵魂归宿旁边的湖畔，就在适者生存小屋。沿着力量山谷向西走便可抵达。"
D.Strings[1215]="我猜有人在战斗结束后需要帮我们这些战士包扎伤口。到精神谷的灵魂小屋旁边的适者生存小屋找阿诺克。往上走去力量谷的西边找到一个湖。那就是他呆的地方。"
D.Strings[1216]="鲁玛克……总是在荣誉谷的湖边钓鱼。你找到他后，顺便帮我向山吉斯问好。"
D.Strings[1217]="钓鱼是那些没有在战斗中死去的老人的运动！到荣誉谷的湖边可以找到鲁玛克。"
D.Strings[1218]="草药……你需要前往暗巷区，去加迪的植物园找她谈谈。在智慧谷阿索兰的市场后面有木制的阶梯。沿着阶梯可以到达暗巷区的上层。"
D.Strings[1219]="到暗巷区的科多兽皮工店那里去。问问卡洛雷克。"
D.Strings[1220]="你要找科多兽皮工店是吧。去暗巷区中心吧。"
D.Strings[1221]="到荣誉谷的湖泊的东北方找红石谷矿业工会。与那里的马卡鲁谈谈。"
D.Strings[1222]="马卡鲁整天都在荣誉谷的红石谷矿业工会，就在湖边。"
D.Strings[1223]="苏尔德将教你如何练习技能。去暗巷区的科多兽皮工店找他吧。"
D.Strings[1224]="你希望利用这些尸体以表示对它们的尊敬，这很好。去暗巷区中心的 科多兽皮工店找苏尔德吧。"
D.Strings[1225]="玛加尔的玛加尔布品店在暗巷区里。去科多兽皮工店旁边的大树南边就可以找到他。"
D.Strings[1226]="布衣！？那不会帮你抵挡住好钢做成的武器的！哈，如果你确定你想当个裁缝的话到暗巷区的玛加尔布品店那儿去吧。"
D.Strings[1227]="我们有自己的职责，$c。对部落应尽的职责。"
D.Strings[1228]="督军克罗姆扎在哪里？"
D.Strings[1229]="我听到他来了！朝西看！"
D.Strings[1230]="奥格瑞玛银行在力量谷那里。去主城门以北的地方找找吧。"
D.Strings[1231]="到力量谷去，在飞行塔的南面就是奥格瑞玛银行。"
D.Strings[1232]="到力量谷的飞行塔顶部可以找到双足飞龙管理员。多拉斯会确保你到达你想要战斗的地方。"
D.Strings[1233]="你认为双足飞龙管理员会在哪儿？到力量谷的飞行塔的顶部去！"
D.Strings[1234]="你在寻找部落大使馆里的乌特伦。在力量谷的西边你可以找到他。"
D.Strings[1235]="部落大使馆位于西边的力量谷。"
D.Strings[1236]="旅馆位于主城入口以北，力量谷右边的第二幢建筑物。和旅店老板格雷什卡谈谈。"
D.Strings[1237]="去力量谷寻找旅店老板格雷什卡。她的旅馆主城门以北东侧的地方。"
D.Strings[1238]="你会在力量谷中央的奥格瑞玛银行外面找到它们中的一个。"
D.Strings[1239]="你可以在力量谷中部的银行外面找到接收你情书的地方。"
D.Strings[1240]="到荣誉谷的猎人大厅去，它就位于就在大剧场的西边。与那里的奥玛克谈谈。"
D.Strings[1241]="你的目标位于荣誉谷西北角。你会在那儿发现猎人大厅的。"
D.Strings[1242]="往上走去力量谷以西，去精神谷的黑石南小屋找皮菲瑞多谈谈。"
D.Strings[1243]="什么，你找不到那里？到精神谷湖里的黑石南小屋去，就在力量谷往上靠西的地方。"
D.Strings[1244]="萨尤斯与他的牧师在精神谷那的灵魂小屋里。去力量谷上方西侧的湖泊那里可以找到他。"
D.Strings[1245]="治疗技能是给那些无法忍受痛苦的人学习的。如果你一定想学习的话，就去力量山谷上面以西的精神谷找灵魂归宿吧。"
D.Strings[1246]="你想找的是卡德里斯。她和其余的萨满正在智慧谷萨尔的要塞的入口房间那里。"
D.Strings[1247]="你的搜寻基本结束了。到智慧谷的萨尔的要塞入口房间里找寻真知吧。"
D.Strings[1248]="想找迅影兄弟会的申苏尔，是吗？去暗巷区，过了杜佛斯回收店之后就可以找到通往暗影裂口的通道。"
D.Strings[1249]="别让我发现你盗窃了任何东西！去暗影裂口地下寻找申苏尔以及他的 迅影兄弟会。在智慧谷以南能找到通向那儿的通道。"
D.Strings[1250]="你在寻找格罗达尔和暗火营地？在被称作暗影裂口的地下洞穴里找到他们。有两条通道可以进入洞穴，一条在智慧谷的南面，另一条在暗巷区里面。"
D.Strings[1251]="去荣誉谷的勇者大厅找格雷兹·怒拳谈谈。并代我向他问好！"
D.Strings[1252]="到荣耀谷去找到勇者大厅并与格雷兹·怒拳谈谈。告诉他们我在这里的轮岗结束后就会去向他们汇报。"
D.Strings[1253]="请不要打扰古老的灵魂。"
D.Strings[1254]="很少有人能找到我……我能为你做什么吗？"
D.Strings[1255]="我要怎样才能得到灵根草呢？"
D.Strings[1256]="呵呵呵呵……你是个相当好奇的家伙，不是吗，$n？嗯，我来告诉你该怎么做。$B$B在此地以北的古老废墟中居住着一个名叫米布隆·乱齿的令人厌恶的豺狼人。他日夜守护着灵根草，好像从不睡觉似的！$B$B你必须把他引开才行。我可以卖给你一些他喜欢吃的东西——把食物放在他附近，引他过来，然后你就可以趁机拿走灵根草啦。祝你好运！"
D.Strings[1257]="我对草药学没什么了解，那么我还能帮上忙吗？"
D.Strings[1258]="没错，但是如果你精通草药学的话，你会发现它更有用！你可以培育出特别的草药来。虽然常青袋是个连新手都能轻松使用的工具，但那些对草药学有天资的冒险者将会得到更丰硕的报酬。"
D.Strings[1259]="你好，$c。我这个羽月要塞的仆人可以为你做些什么呢？"
D.Strings[1260]="我想购买更多的萨伦迪斯种子。"
D.Strings[1261]="你在找什么？"
D.Strings[1262]="哪一项专业？"
D.Strings[1263]="我们肉体的死亡标志着我们灵魂和神圣使命的重生。"
D.Strings[1264]="去找我们的领袖杜姆雷尔发出挑战吧。"
D.Strings[1265]="我永远都不能再触摸石头了。我永远都无法再体会钢铁的荣誉了……"
D.Strings[1266]="你不能通过。你不是我们的人，也没有发出过挑战。"
D.Strings[1267]="你要找什么技能的训练师？"
D.Strings[1268]="挑战炎魔之王的下场就是我们现在的样子。"
D.Strings[1269]="我们的惩罚也是我们的祝福。"
D.Strings[1270]="你的奴役结束了，杜姆雷尔。我向你挑战！"
D.Strings[1271]="你想要学习这项古老的手艺？你希望冶炼黑铁？$B$B给我一样祭品我就会考虑的！"
D.Strings[1272]="你的意志很坚强，而且你的意图很明显。$B$B可能你的确有资格……"
D.Strings[1273]="你表明了自己的愿望，也支付了珍贵的石头。我会教你的……"
D.Strings[1274]="科卡尔部族是最强大的！"
D.Strings[1275]="为了部落！"
D.Strings[1276]="保卫碉堡！"
D.Strings[1277]="我们的敌人必将败北！"
D.Strings[1278]="小心，$n！看西边！"
D.Strings[1279]="离那些酒桶远一点！"
D.Strings[1280]="我……我真的不知道自己是怎么到那儿的……$B$B我依稀记得用的是……木筏……$B$B"
D.Strings[1281]="你会为此付出代价的！"
D.Strings[1282]="付钱给我，我就说……$B$B哦，是你，$n！别介意……"
D.Strings[1283]="你听说过我的名字吗？或许我们俩很早就相识了……$B$B我认为我得名于某个重要人物……"
D.Strings[1284]="嗨！很高兴你回来啦，$n。告诉我，你完成我给你的第一项任务了吗？如果完成了，我会给你第二项任务的……"
D.Strings[1285]="我在火山口游荡了许久，后来我想起曾有人告诉我……“继续往前，到山上去。”这个声音在我的脑海中出现。$B$B听了这话之后我就来到了这里，$n！"
D.Strings[1286]="很久之前，在我的旅途之中，我遇到了一个人，他告诉我：“掌握它的使用方法，你就可以拥有它。”$B$B你觉得那是什么意思？那时我还不知道，而且现在我还是不知道，真的……"
D.Strings[1287]="对任何人而言……包括我，这都是一个秘密！$B$B很高兴你找到了我——我没躲藏在树丛中或是岩石下，挺幸运的，是吧？"
D.Strings[1288]="谢谢你，$n！你是安戈洛环形山的英雄！"
D.Strings[1289]="拉格纳罗斯将拥有至高无上的统治权！"
D.Strings[1290]="喝点东西吧，$c。这可能是你最后一次喝东西啦！"
D.Strings[1291]="要不是因为这酒吧，我的空闲时间就只能用来剥龙鳞啦。"
D.Strings[1292]="水元素正在跟火元素交战，也就是说他们也在跟我们作战。他们的领袖之一的海达克希斯正在召集士兵……"
D.Strings[1293]="啊，真悬，我以为自己这次铁定玩完了。呃……还是有点晕……"
D.Strings[1294]="我听说水元素中的贵族海达克希斯发动了对火元素的战争。真希望他战败！"
D.Strings[1295]="海达克西斯公爵躲到了艾萨拉风暴海湾的某个岛屿上。那些家伙能有什么威胁？"
D.Strings[1296]="要是海达克西斯招募了新兵，就可能使双方的力量对比发生变化……"
D.Strings[1297]="枪炮与硝烟弥漫，直到某一方被摧毁。"
D.Strings[1298]="我父亲告诉我：有一天，会有一个陌生人跟我交谈，我必须控制住自己，不能杀了$g他:她;。"
D.Strings[1299]="勇敢的$c，欢迎来到石槌要塞。我能帮助你吗？"
D.Strings[1300]="你好，$c。如果你在寻找皮革制品和制皮物资的话，来问我这个半退休的圣骑士就算是找对人了。"
D.Strings[1301]="看来你需要通过无尽之海的通道。那你算来对地方了，这儿就是少女之爱号的停泊处，她是这片水域上最好的客船。当船到达后，你就登上甲板，然后用不了多久你就可以躺在荆棘谷的沙滩上晒太阳了。"
D.Strings[1302]="我必须承认，藏宝海湾有南海最好的杂烩蚌肉。哦，对烹饪不感兴趣？那么欢迎你投宿少女之爱号——在东部王国和卡利姆多之间航行的最好的客船。很快她将驰往棘齿城，在她到达之前好好享受吧。"
D.Strings[1303]="你在干什么？你这个入侵者！！"
D.Strings[1304]="氦弹点火和爆炸的过程是没有危险的。跟船只相比，这宝贝能更为快速安全地将你送达幽暗城，途中的景色真是惊心动魄。说到这，在地精飞艇上是不允许吸烟的，旅途中也不允许使用火的法术。"
D.Strings[1305]="你好！你正是我要找的人。坐下来听我说，我有个可以让咱们两个都发家致富的计划！"
D.Strings[1306]="我兄弟说我们能在这条商贸路线上赚到更多的钱的，但是他没告诉我要独自应对。要是你乘坐地精飞艇沿着这条路返回的话，你能帮我带点吃的吗？在奥格瑞玛，有人出售最好的肉类，当然我还能以那些苟延残喘的动物为食的。"
D.Strings[1307]="你干什么都不成，雷布里。现在该为你的邪恶付出代价了！"
D.Strings[1308]="不！滚开！帮帮我！！"
D.Strings[1309]="去红石谷矿业工会东北部的荣誉谷找诺格机械店。"
D.Strings[1310]="你会在荣誉谷找到那个地精和他的玩具商店的。"
D.Strings[1311]="我是一名拥有强大力量的法师，一直以来，我都潜心研究精神和记忆，这有利于学习知识和保持学会的知识。要不是我在夜晚听到一个巨大的声音说需要我的帮助，我的研究一定已经完成啦。我只在这儿呆一会儿，免费为你重修天赋。接着我就得离开，而你也要选择自己的道路。"
D.Strings[1312]="没问题！"
D.Strings[1313]="马上就来了！"
D.Strings[1314]="宝贝，我马上就过来……"
D.Strings[1315]="嘿，娜玛拉！来一杯黑铁啤酒怎么样？"
D.Strings[1316]="娜玛拉！还有羊肉吗？"
D.Strings[1317]="小姐，请你告诉普拉格，我想要更多的啤酒。这些远远不够！"
D.Strings[1318]="嘿，我说，娜玛拉，你能切给我一块吗……"
D.Strings[1319]="我想进行烹饪训练。"
D.Strings[1320]="你好，$n。如果你想学习烹饪技巧的话，可以随时来找我。"
D.Strings[1321]="<普瑞斯托女士怒视着你。>"
D.Strings[1322]="我就站在你旁边，笨蛋。我知道你在找什么。"
D.Strings[1323]="你是说为了满足一个妄想狂的地方官和一群没准正在遭受中暑之苦的乌合之众的愿望，我们就得把世界各地的部队都调回来，然后给他派过去吗？"
D.Strings[1324]="当然不是，亲爱的$g小伙子:姑娘;。你这种“冒险者”类型的$c经常成为政治的牺牲品，被政治家玩弄于股掌之间而毫无察觉。$B$B我给你的建议，就是去做一些更加具体的事情：找份新工作。$B$B这个世界已经有太多的英雄了。"
D.Strings[1325]="嗨，罗克诺特！"
D.Strings[1326]="我们走吧，宝贝。"
D.Strings[1327]="%s吻着她的情人。"
D.Strings[1328]="%s亲吻着娜玛拉小姐"
D.Strings[1329]="你想要什么？*嗝儿*"
D.Strings[1330]="温德索尔那天特别爱跟人争吵——相信我，对温德索尔来说，那是一个有纪念意义的伟大成就。他一直在跟我说“感觉有些怪异”。他不是在开玩笑！$B$B当那些肮脏的野兽出击时，我们还在黑石山脉的中央。当然，我指的是兽人。你别分神，好吗？一时之间，叫喊声和铁器的敲击声四起。"
D.Strings[1331]="我单挑50个兽人？我可不是傻子，$n。我爸爸常说“卑鄙是卑鄙者的通行证”这类的话，我突然之间就明白了那是什么意思。"
D.Strings[1332]="好吧，好吧。总之，从某种意义上说，我退到了一个不起眼的角落里。$B$B温德索尔似乎并不安分，看看他那歇斯底里的样儿。他拿着反对者战锤没命地乱挥，像发了疯一样对兽人咆哮着。"
D.Strings[1333]="嗯。你从来没有听说过反对者？那把传说中的令兽人闻风丧胆的战锤？对，对，那是温德索尔的锤子。他说是弗兰克罗恩·铸铁亲自为他伟大的父亲制造了那把锤。弗兰克罗恩·铸铁，就是那个建造了巨石水坝之类的……黑铁矮人。他还说有一把与反对者一起铸造出来的战锤被弗兰克罗恩自己留着用了。他好像叫它铁胆之锤什么的。"
D.Strings[1334]="我说到哪里了？哦，兽人突袭了温德索尔，温德索尔呢？他是山崩于前而面不改色，从容应对。只见反对者击起冲天血光，鲜血四溅，持续了数个小时，没准是数天。我记不得了。但是最终，杀戮停止了。"
D.Strings[1335]="死了？你在开玩笑吧，$n？搞清楚，$n$g先生:小姐;！温德索尔绝对不会死于区区50个兽人之手，这就跟塞尔萨玛血肠是世界上最美味的食物一样不容置疑，他被兽人层层包围，但是他确实还活着……而且他非常非常愤怒。"
D.Strings[1336]="你为什么总说他死了？谁告诉你他死了？我从来都没那么说过。$B$B他只是不知去向而已。$B$B你看，很明显，我们已经卷入了某个兽人对抗黑铁矮人的战争中。兽人是一群肮脏又卑劣的杂种，他们设计了一些圈套和你可能永远搞不明白的邪恶装置！"
D.Strings[1337]="矮人可不会喝醉，$g先生:小姐;。我只是有些邋遢。$B$B无论如何，温德索尔？我猜他在黑石深渊的某处。对你们这些未受教化的家伙来说，就是一座黑铁矮人的城市。"
D.Strings[1338]="放慢速度！就快接近了！$B$B他在那儿，全身血肉模糊，连内脏都流出来了，是谁把他弄成这样的？$B$B黑铁矮人！你记得我说过的话吗？？$B$B嗯，黑铁矮人比黑石兽人更为狡猾。他们是有备而来的。人数有300之多……*嗝尔*。"
D.Strings[1339]="$n$g先生:女士;，如果我不是很了解你的话，我就会以为你也是那些穴居人中的一员。$B$B黑铁矮人没有把温德索尔怎么样，毕竟他的老祖父的最好最好的朋友就是一个黑铁矮人，这可能也就是黑铁军队到现在还没把他干掉的原因。"
D.Strings[1340]="你的知识太缺乏了。当你熔炼技术更成熟些时再来找我！"
D.Strings[1341]="最后！用手指堵住你的耳朵，你的脑子有可能会变得有五倍大，事实上，我甚至担心你的脑子会泄出来。$B$B那么，黑铁矮人们饶了他的性命，但把他囚禁了起来。他们的首领，某个叫做索什么森的妄自尊大的，愚蠢的，自负的家伙，把反对者留作己用。那是我最后一次见到温德索尔了……*嗝儿*"
D.Strings[1342]="费伍德森林的堕落禁锢了我的灵魂……我也许永远都得不到安宁……"
D.Strings[1343]="欢迎来到我们的酒店！"
D.Strings[1344]="为什么你跟罗克诺特不去找个二人天地呢……"
D.Strings[1345]="好主意！"
D.Strings[1346]="再次感谢你，$n。罗克诺特和我非常合得来！"
D.Strings[1347]="你见过安戈洛环形山的所有奇景了吗，$n？真是令人惊讶。虽然它们没有我制造出的东西那样精密，但这里所有的东西都是天然而成的……这就真是太奇特了。$B$B我的叔叔雷塔维就喜欢这样的地方。我正沿着他的脚步前进——我还想从灭绝的文明中找到新的知识！"
D.Strings[1348]="嗯，我没有任何秘银外壳。我尽力了。只要有那个就可以修理A-Me 01了吗？哦，太好了！$B$B秘银外壳并不是很难找到。只需请一个技艺高超的技师为你制造一个就可以了。我想那可能需要几块秘银，但是如果你能帮我，我保证你会得到丰厚奖赏的！"
D.Strings[1349]="你一定要尝一下我们的黑铁啤酒。我听说附近的矮人总是有多少喝多少。"
D.Strings[1350]="我的主人普拉格是个不错的老板，而且他赚了很多钱。他的钱包都快要被撑破了！"
D.Strings[1351]="这是用钱能够建造出的最好最先进的交通工具。什么？矿道地铁？侏儒？听着，朋友，如果你相信那种废物的话，我就把荆棘谷中的那尊雕像卖给你。那么，你到底是要走着去格罗姆高营地，还是乘坐这架精美的飞行机器？你选吧。"
D.Strings[1352]="嘿！别碰那个！"
D.Strings[1353]="你在那儿做什么？"
D.Strings[1354]="不许偷盗货物！"
D.Strings[1355]="嘿！住手！"
D.Strings[1356]="法拉克斯，我想你需要好好教训一下这些家伙。"
D.Strings[1357]="我会重生的！伊森迪奥斯会从这些灰烬中将我复活的！"
D.Strings[1358]="你完了！"
D.Strings[1359]="好……很好，A-Me。A-Me好。家。找到家。"
D.Strings[1360]="你喝过雷霆啤酒吗？那可是好东西！"
D.Strings[1361]="我一个小时以后还要去值班，但在那之前……干杯！"
D.Strings[1362]="你在看我吗，$g小伙子:姑娘;？"
D.Strings[1363]="我要来一杯黑铁啤酒。哦，你不是侍者？"
D.Strings[1364]="我认为普拉格把桶装得太满了。你瞧，简直都要炸开了！"
D.Strings[1365]="在我参加聚会时别骚扰我……"
D.Strings[1366]="你有需要保管的财宝吗？去找铁炉堡银行的石衣兄弟吧。\n\n从铁炉堡的入口往东北方向走，银行就在那边。"
D.Strings[1367]="银行？哦，你是说银行！说到存储贵重物品的话，没有什么比银行更安全的地方了。它就在铁炉堡大门的东北方。"
D.Strings[1368]="想要乘坐狮鹫，是吗？你得去找格莱斯·瑟登。\n\n你可以在铁炉堡中心的大锻炉东边找到他。"
D.Strings[1369]="啊，没有什么比狮鹫更好的坐骑了。暗夜精灵偏爱可笑的角鹰兽，而我只需一头狮鹫就可以穿梭在云端！\n\n好吧，我不跟你唠叨了，到大锻炉东边的格莱斯·瑟登那儿去吧，他会向你出租狮鹫的。"
D.Strings[1370]="要是你想组建公会的话，那你首先需要通过铁炉堡访客中心的乔多·钢眉的认同。穿过铁炉堡大门往东南方向走，你就能找到他。"
D.Strings[1371]="旅馆？啊，你是来寻找铁炉堡出产的美酒的？你该去石火旅店。$B$B如果你在铁炉堡之外，它就在铁炉堡大门的左边；反之，则在大门右边。"
D.Strings[1372]="要是你要找旅馆的话，石火旅店是个不错的选择。若是你前往铁炉堡的话，会在城门的左边找到这个旅馆；要是在铁炉堡里面的话，它就在城门的右边。$B$B哦，要是你现在就去那里的话，告诉他们为我准备好啤酒吧。"
D.Strings[1373]="你会在那边的石火旅店旁边找到一个邮箱。那就在铁炉堡大门的北面。"
D.Strings[1374]="几天前，我无意中听雷格努斯·雷石在武器大厅中吹嘘他兽穴中的一件新饰品。要是你想成为一名技艺纯熟的猎人，就去找他吧。"
D.Strings[1375]="秘法大厅的法师彬克也许能帮忙解决你的一些魔法需求。\n\n秘法大厅就在铁炉堡的北部。"
D.Strings[1376]="去铁炉堡大门以北的神秘大厅，你会在那儿受到魔法训练的。朱莉·雷线总是在那儿埋头苦读。"
D.Strings[1377]="啊，布莱纳·火崖。她能使用魔法。她主管牧师事务。\n\n你要穿过铁炉堡大门，向北走，前往神秘大厅。她就在那里。"
D.Strings[1378]="布兰度尔·铁锤就是你想找的人。你可以去铁炉堡大门以北的神秘大厅找他。"
D.Strings[1379]="啊，布兰度尔·铁锤。毫无疑问，他能为你提供指导，$g小伙子:姑娘;。在铁炉堡大门以北的神秘大厅中能找到他。"
D.Strings[1380]="为什么我们需要这样的服务？荒弃的洞穴的潜行者霍夫丹·黑须已经给我们惹了一大堆麻烦，我是不是还要留意你一下？"
D.Strings[1381]="所有的潜行者都居住在铁炉堡以北的荒弃的洞穴。我敢打赌芬斯维克也在那儿，正在数着偷来的钱包中的硬币呢。我总有一天会抓住他的！\n\n同时，我也会好好看着你的，$g小伙子:姑娘;。"
D.Strings[1382]="没有什么地方比铁炉堡最黑暗的荒弃的洞穴更适合寻找那些阴暗的家伙了。你在那里肯定会找到瑟斯哈特，就象是召唤一个行径卑劣的动物去照他的吩咐办事。"
D.Strings[1383]="哦！你想接受战士的训练，是吗？克斯塔姆·碎石会帮你实现梦想的！去铁炉堡大门东边的武器大厅吧。"
D.Strings[1384]="你想要炼金训练者吗？嗯，我刚从那儿过来呢，真的。你可以在侏儒的聚集地侏儒区找浆泡小姐。"
D.Strings[1385]="你在寻找一个炼金术老师是不是？我也刚从那里回来。你会在侏儒集会的工匠区找到浆泡小姐的。\n\n：：叹气：：……为什么我没有服下蓝色药剂呢。"
D.Strings[1386]="你算来对地方了，$g小伙子:姑娘;！人们从世界各地来此学习成为一名铁匠。你会看到本古斯·深炉在我们漂亮的城市中央的大熔炉的铁砧上埋头工作。"
D.Strings[1387]="一个烹饪培训师？那好吧，你到大熔炉东北方的铜壶铁罐店去。达瑞尔·瑞克努索会教你制作极好的菜肴，那肯定会让你获得新生的！"
D.Strings[1388]="啊，要是你想成为一名附魔师的话，我想你需要找吉布·草须。他在 大熔炉狮鹫管理人右边的商店草须魔法用品店里。"
D.Strings[1389]="你想学习工匠的手艺吗？那你就得去工匠区找宾斯匹德。\n\n从铁炉堡大门一直往正东方向走，或者朝着传来爆炸声的方向走。"
D.Strings[1390]="急救是一种有价值的技能。我们的常住的培训师，尼莎·火石，会教你该怎么做。到大熔炉南边的铁炉堡医师协会可以找到她。"
D.Strings[1391]="格瑞诺尔·石印会告诉你说他曾经碰到许多脱钩的超级大鱼，但他仍是附近最好的渔夫之一。他在荒弃的洞穴开有一家叫做旅行渔具店的商店。"
D.Strings[1392]="花和种子以及类似的东西？那是雷纳·石枝的专业领域。你能在大熔炉南面的铁炉堡医师协会处看到她料理她的植物。"
D.Strings[1393]="哦，你想学习采摘雏菊是吧？哈哈！我只是开个玩笑，$g小伙子:姑娘;。\n\n这是个很好的职业，雷纳·石枝会教你的。她在大熔炉南边的 铁炉堡医师协会工作。"
D.Strings[1394]="费布·钢轴在大熔炉西北面开了一家商店。我打赌他能教你学会制作精良的装甲。"
D.Strings[1395]="这儿有采矿训练者吗？你认为你在哪儿！？\n\n你将在大熔炉北边深山珠宝矿业协会找到丹莫罗地区最好的矿工。吉尔弗拉姆·石趾将为你展示真正的采矿艺术。"
D.Strings[1396]="巴尔萨斯·裂石是一名剥皮师，他会教你如何剥皮的。去大熔炉北边的皮甲用品店找他吧。"
D.Strings[1397]="约莫德·石眉对缝纫有独到之处，真的。如果你想接受训练的话，就去大熔炉北边的石眉布衣店找他吧。"
D.Strings[1398]="我经受过痛苦，但是现在我能感觉到它正从我身上消退。我感到……自由了。"
D.Strings[1399]="安戈洛的水晶塔相当神秘。对这里少数的居住者来说，它们代表某种传奇，而其建造目的则更值得深思了。"
D.Strings[1400]="检查这座水晶塔。"
D.Strings[1401]="这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由蓝色、黄色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈蓝色水晶两侧分别有一小圈黄色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。"
D.Strings[1402]="这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由黄色、红色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈黄色水晶两侧分别有一小圈红色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。"
D.Strings[1403]="这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由红色、蓝色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈红色水晶两侧分别有一小圈蓝色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。"
D.Strings[1404]="A-Me回家！A-Me，好！回家。回家。回家。"
D.Strings[1405]="坏，$n。$n，坏！"
D.Strings[1406]="$n，不要伤害A-Me。A-Me，好。"
D.Strings[1407]="危险。危险！$n要伤害A-Me。"
D.Strings[1408]="我想喝更多的啤酒！给我更多的啤酒！"
D.Strings[1409]="喝空的！！"
D.Strings[1410]="啊，又空了！"
D.Strings[1411]="啤酒！"
D.Strings[1412]="我叫科琳，我实在没法告诉你我是怎么到这儿来的，但是我可以告诉你，这个营地现在就是我家了！$B$B我在这儿研究环形山里随处可见的奇怪水晶。你在来这里的路上一定已经看见不少这样的水晶了。你有没有拾取一些水晶？"
D.Strings[1413]="啊，太棒了！"
D.Strings[1414]="燃烧平原 - 七贤石板"
D.Strings[1415]="拓下石板上的文字。"
D.Strings[1416]="石板上的符号被小心翼翼地拓了下来……"
D.Strings[1417]="你好，$c。对于某些人来说，猎人是一种生活方式，是一种选定的职业。对于其他人来说，它是某种消遣，是勇气的象征，或是为了通过狩猎部族的仪式。$B$B对于我来说，种族和职业并不重要--我尊重的是你的灵魂和心智，而正是它们将要接受考验。当一个人独自面对自然的力量，竭力发挥其毕生所学之时，荣誉才会留下它真正的印记。$B$B如果你希望考验自己并赢得我的尊敬，那就跟我多谈谈。"
D.Strings[1418]="你正行进在一条光荣的道路上，$n。我的祖先尊敬你的意愿，但你在完成我所交付的任务之前我不会对你有任何认可的。$B$B如果你希望证明在精神层面是一个猎手的话你该知道你必须做什么。"
D.Strings[1419]="我和碎手都向你致敬，$c。$B$B别这么惊讶，$n。连奥格瑞玛最高的地方也会有阴影——一定有什么东西隐藏在那儿。碎手欣然接受了那项任务。萨尔也承认要确保兽人和巨魔的安全，他是不可缺少的。$B$B但是你到这儿来不是谈论我的事儿吧，你一定另有目的。"
D.Strings[1420]="安戈洛环形山在卡利姆多南部，位于塔纳利斯沙漠的西面。去寻找巨大的浮空石……它们是环形山入口的标志。但是要小心，那里可是很危险的，迅猛龙就在入口附近徘徊。"
D.Strings[1421]="谢谢你，现在我们能解开水晶和神秘的水晶塔的秘密了，$n。要是你需要更多信息，请随时回来找我！"
D.Strings[1422]="安戈洛的暴掠龙看起来与贫瘠之地的迅猛龙有些共同点--非常聪明，十分灵活，并且似乎具有着某种程度的行为智能，或者说遵循着某种行为准则。其中我所遇到的最强大的是拉克维。他是我所见过的最危险的动物之一。在牛头人语里，拉克维的意思是“锋利的爪子”，但这个名字并不足以恰如其分的描述他的可怕。$B$B如果你计划猎杀拉克维的话，千万不要低估他，但如果你决定要这样做，无论如何我都会帮你的。"
D.Strings[1423]="东方的水晶塔接受蓝色，黄色，还有绿色的水晶。$B$B它专注于使用蓝色水晶作为主要力量之源而产生的能量。有两种可能的效果：一种对精神有益，而另一种产生一种破坏性的护盾。$B$B精神水晶需要蓝色和绿色的水晶。这将会增加你的勇气。$B$B尖刺水晶需要蓝色和黄色的水晶。这会产生一个对攻击者造成伤害的护盾。"
D.Strings[1424]="北方的水晶塔接受黄红绿三种颜色的水晶构成。$B$B而关键是使用黄水晶所产生的能量作为主要的力量来源。有两种可能的效果：一种会制造破坏，一种会消除破坏。$B$B爆炸水晶需要红水晶和黄水晶。这将产生剧烈爆炸，足以震慑你的敌人。$B$B恢复水晶需要黄水晶和绿水晶。这将给你提供治疗光环。"
D.Strings[1425]="西方的水晶塔接受红色，绿色和蓝色的水晶。$B$B塔门关键是要用红色水晶作为力量源泉而产生的能量。可能有两种结果：一种能提高你的防御力，而另一种则是削弱敌人的防御。$B$B防御水晶需要红色和绿色的水晶。这将会使你的装甲更完备。$B$B破甲水晶需要蓝色和红色的水晶。这将会削弱即定目标的装甲防御。"
D.Strings[1426]="当然的事情，$n。还有一个给你。"
D.Strings[1427]="“牛头人语？”$B$B牛头人德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向南面的道路指了几下。$B$B或许她是在说那里有能跟你进行交谈的德鲁伊？"
D.Strings[1428]="这片美丽的森林受到了可怕的诅咒！腐化的力量将这儿变成了一片恐惧之地。如果你跟他们不是一伙的，或许你能帮助我夺回费伍德森林。"
D.Strings[1429]="“达纳苏斯语？”$B$B暗夜精灵德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向北面的道路指了几下。$B$B或许她是在说那边有能跟你进行交谈的德鲁伊？"
D.Strings[1430]="救命！！！！"
D.Strings[1431]="是谁派你来的？"
D.Strings[1432]="好吧，我们走。"
D.Strings[1433]="费伍德的某些植物或许能因为塞纳里奥植物药膏的效用而避免堕落。我知道如何从几种不同的东西中获取这种药膏，凭借你的能力，你会发现有多种方法可以协助我制造药膏。$B$B首先，你需要一盏塞纳里奥信标，它是一种能让你看到肉眼所看不到的堕落和腐烂力量的装置。"
D.Strings[1434]="我需要塞纳里奥信标。"
D.Strings[1435]="残骸上满是苍蝇和蛆虫。"
D.Strings[1436]="数年前居住在此地的暗夜精灵修建了这座神殿。$B$B它隐藏着什么秘密吗？"
D.Strings[1437]="继续……"
D.Strings[1438]="卡兰，门开了。你自由了。"
D.Strings[1439]="嘿，我的东西被偷了！"
D.Strings[1440]="好了！把这儿收拾好才能喝酒！"
D.Strings[1441]="哈！哈！哈！谢谢你们这些笨蛋放了我。现在让我吃掉你们的肉来报答你们吧。"
D.Strings[1442]="干得好！"
D.Strings[1443]="安戈洛环形山水晶塔的秘密现在已经被你破解了。你可以随时造访水晶塔，获取它们的力量。"
D.Strings[1444]="欢迎来到塔纳利斯，$n。我能为你提供什么服务？你看起来可不像铁匠，但是我知道，人不可貌相。"
D.Strings[1445]="我要离开这儿了！"
D.Strings[1446]="我不喜欢交谈。"
D.Strings[1447]="它们都失踪了，$r。在亡灵天灾入侵奎尔萨拉斯的时候，精灵族的圣契散落到世界各地。$B$B现在我们得搜寻这些圣契。寻找其中的秘密——并恢复其中蕴含的力量。$B$B我在寻找由卡里尔·温萨鲁斯书写的圣契。如果你找到了圣契，请允许我吸收它的魔法力量，而为你我可以制作一种力量的融合物……当然，所有的事情都是有代价的。这项任务的风险极大，但是我给予的回报也是相当丰厚的。"
D.Strings[1448]="<玛瑟迪斯目不转睛地盯着圣契。>$B$B你来寻求融合物的？你按照圣契的指示做了吗？"
D.Strings[1449]="给我奥术力量，然后我就会进行融合，凡人。"
D.Strings[1450]="确实是一项难得的发现。$B$B<玛瑟迪斯点了点头。>$B$B如果你希望继续的话，我会需要相应的材料。"
D.Strings[1451]="愿光明保佑你。"
D.Strings[1452]="我想接受更多的关于圣光的训练。"
D.Strings[1453]="你想让拆毁者干什么？"
D.Strings[1454]="我需要帮助来击败暗影蛛丝偷猎者。"
D.Strings[1455]="喝光它！我们还有很多酒！"
D.Strings[1456]="尽情享受吧！你找不到比这更好的啤酒了！"
D.Strings[1457]="你喝过黑铁啤酒吗？那可是最好的啤酒！"
D.Strings[1458]="尝尝野猪肉吧！这是我的新作！"
D.Strings[1459]="拍卖行"
D.Strings[1460]="拍卖行在哪儿？当你进入我们美丽的城市时它就在铁炉堡大门旁边。你会在银行的正对面找到它。"
D.Strings[1461]="达纳苏斯有无数令人惊异的地方，你想去哪儿？"
D.Strings[1462]="你可以在达纳苏斯银行找到你存放财物的地方，它就在我们神奇的城市中央。"
D.Strings[1463]="维斯派塔斯的角鹰兽会送你到达目的地的。穿过达纳苏斯西部入口，去鲁瑟兰村找他吧。"
D.Strings[1464]="要是你想要组建公会的话，你必须去见公会管理人琳沙娜。她在达纳苏斯东北部的工匠区。"
D.Strings[1465]="尽管我可以将覆盖着整个泰达希尔的草坪当作很好的床铺，但是工匠区中塞琳尼经营的旅馆对那些享受一下奢华生活的人来说再合适不过了。"
D.Strings[1466]="在达纳苏斯的东北部，也就是工匠区，你会在旅馆外面找到邮箱的。"
D.Strings[1467]="你很幸运来到达纳苏斯，因为你遇到了像祖卡斯特这样多才多艺的猎人作为你的培训师。我建议你到塞纳里奥区拜访她并寻求她的指导。"
D.Strings[1468]="在灰色年代，德鲁伊对周遭的人都很友好。你随便问塞纳里奥区的任何一个德鲁伊，他们会给出相同的说法的。"
D.Strings[1469]="月神殿是艾露恩的祭司们的家园。你会在那儿找到贾德莉亚和拉瑞亚，她们会对你的牧师生涯做出进一步的指导。"
D.Strings[1470]="月神的力量支配着你！月神的力量支配着你！\n\n出发吧！去达纳苏斯东部的月神殿中央大厅找贾德莉亚！"
D.Strings[1471]="要是你想做潜行者的话，就该去找塞尤娜。她居住在西部森林盘旋山道下的塞纳里奥区。"
D.Strings[1472]="很多人都试图追随潜行者的脚步，但是只有暗夜精灵能真正被黑夜接受。如果你想在阴暗的道路上前行的话，就去塞纳里奥区找塞尤娜吧。"
D.Strings[1473]="你会在战士区的护卫队中找到希达奈尔，她敏锐的眼睛扫视着森林，寻找着胆敢进入我们美丽的城市的敌人。"
D.Strings[1474]="达纳苏斯的工匠中传承着数千年的手艺知识，一定会对你有所助益的。告诉我，你对哪种工艺最好奇？"
D.Strings[1475]="如果你真的想做这个职业，就去达纳苏斯北部的工匠区找一个技艺纯熟的炼金士：安尼希尔。"
D.Strings[1476]="阿雷贡是一名技艺精湛的厨师，数个世纪以来，他都在完善着自己的厨艺。要是他愿意教你的话，你就得谢天谢地了。要是你相信自己的实力的话，就去工匠区找他吧。"
D.Strings[1477]="阿雷贡做的食物很受欢迎。他总是在工匠区忙于制作新的美食。要是有塞纳里奥绿色烹饪的话，你一定要尝尝。\n\n如果你不介意的话，我必须先去调查一下接二连三的鹿群失踪事件。"
D.Strings[1478]="没有具备天赋的附魔师，刀刃不可能如此锋利，护甲也不可能如此坚固。塔兰丹就是这样的附魔师，他可以教你如何给武器和护甲附魔。去工匠区找他吧。"
D.Strings[1479]="哦！$g小伙子:姑娘;，当你选择附魔时，你得非常小心。我让自己的杯子附魔，使杯中的水不洒出一滴，但是我也不能喝到里面的水了！这真是个悲剧。\n\n当你看到格瑞姆比时，必须记得我的叮嘱。他在大熔炉狮鹫管理人右边的商店中。"
D.Strings[1480]="当你没有医师来料理你的伤口时，急救知识可以救你的性命。我会请教工匠区的丹纳罗尔关于这门技艺的问题。"
D.Strings[1481]="它是一项耗时，但是会很有收获的技能。与贸易区的阿斯坦娅谈谈或许你能学到一些有用的东西。"
D.Strings[1482]="泰龙尼斯制作武器的技能无与伦比。他不会收学生的钱，你该为此感到庆幸。去吧，去达纳苏斯东北部的工匠区找他吧。"
D.Strings[1483]="我们种植蔬菜。野兔吃我们的蔬菜。狼群以野兔为食。我们捕杀狼群，从它们身上获得肉和兽皮。这就是神奇的生物链，或许你用别的什么词语来描述它。\n\n去塞纳里奥区找泰龙尼斯吧，我得继续执行自己的职责了。"
D.Strings[1484]="世间动物死时会将它们的生命和兽皮赐予我们。要是你能尊重它们的牺牲，或许剥皮者这个职业会适合你的。去达纳苏斯北部的工匠区，找艾拉迪尔谈谈，学习更多知识。"
D.Strings[1485]="如果你有希望学成一位裁缝的话你当然应该去找迈里恩。她住在达纳苏斯东北方的工匠区。"
D.Strings[1486]="费伍德森林有什么植物可能被污染了？"
D.Strings[1487]="我已经观测到有四种植物受到了腐蚀术的影响：轻歌花、迎风花、鞭根草和夜龙植物。轻歌花和迎风花是费伍德森林中常见的植物，而鞭根草和夜龙植物就不那么常见了。所有这些都是费伍德森林生态系统的重要组成部分。"
D.Strings[1488]="这儿就是那场声势浩大的战争的遗址。那些伟大的战争啊。"
D.Strings[1489]="和雷戈萨谈谈。他非常聪明，能帮你寻找东西。"
D.Strings[1490]="嗯，我不知道自己还能撑多久……我感到有些乏力……"
D.Strings[1491]="记住，如果我迷糊了，就抽我的耳光。如果我晕厥的话，就用这个水壶。现在，我们走吧！"
D.Strings[1492]="%s昏倒在地。"
D.Strings[1493]="啊啊啊啊……"
D.Strings[1494]="我有些不适……"
D.Strings[1495]="热……我受不了了……"
D.Strings[1496]="你……能不能背我一程？"
D.Strings[1497]="嗯，继续！"
D.Strings[1498]="我现在感觉好些了，谢谢你。"
D.Strings[1499]="我感觉怎么样？简直湿透了，谢谢你。"
D.Strings[1500]="斯普拉格！我简直不敢相信自己居然能活着回来！"
D.Strings[1501]="啊……有点晕……"
D.Strings[1502]="呃。"
D.Strings[1503]="林格！你没事了！"
D.Strings[1504]="林格？快醒醒！不要担心，我会照顾你的。"
D.Strings[1505]="有人吗？"
D.Strings[1506]="啊，没问题，$n！对不起……我还以为你已经搞定了。"
D.Strings[1507]="你必须给我一点时间，$c，纳迦正在攻击我们。搞定他们之后再来找我！"
D.Strings[1508]="好吧*嗝儿*……嗯，你看起来很眼熟*嗝儿*。我有跟你说过我和温德索尔一起跟，呃，一，一百万个兽人战斗的事儿吗？$B$B哦，坐下来吧，朋友，这个故事非常棒的！"
D.Strings[1509]="奥格瑞玛拍卖所位于力量谷。去火枪进口公司东面找它吧。"
D.Strings[1510]="你的嗓子喊哑了是吗？在力量谷就可以找到奥格瑞玛拍卖行。"
D.Strings[1511]="欢迎来到达纳苏斯银行。我们提供金融帐户和存储贵重物品的保险箱。你要开户吗$g先生:女士;？"
D.Strings[1512]="不可思议，不是吗？所有这些神器和残骸。$B$B我不清楚是什么给我留下了更为深刻的印象，它们的规模，还是它们背后的故事。要学习的东西还很多。我们能找到其中的关联……$B$B你知道那个传闻吗，听说许多种族与暗夜精灵有着相同的遗产。"
D.Strings[1513]="为国王欢呼吧，宝贝！"
D.Strings[1514]="嗨，我是派提亚。在我右边是科多兽达丹加。我们曾跟马歇尔探险队在一起——那已经是数年前的事儿了，那时达丹加还是只幼兽呢。$B$B要是你带有火炬或是任何火种，请尽可能地把它们藏起来。达丹加不喜欢烟。"
D.Strings[1515]="为了所有神圣高贵的爱，请告诉我你是来把我们从这片被遗忘之地带走的。虽然我是与马绍尔探险队一起的，我愿给你我口中的金牙，只要你让我爬进你的背包并离开这个地方。"
D.Strings[1516]="哦，你好！我是霍莱伊，马绍尔探险队的首席科学家和生物学家。我的兄弟和我，还有我们的同伴，一起到艾泽拉斯去探索荒野和未被驯化的雄伟景象。真是太激动人心了……但是，嗯……我想这次我们陷入了太多激动中了！"
D.Strings[1517]="你好，陌生人。欢迎你来到遍布丛莽的安戈洛环形山！$B$B我叫威利德·马绍尔。我、我的姐妹以及同伴组成了马绍尔探险队——致力于探索艾泽拉斯荒野和未知之地的科学家和探险家们。"
D.Strings[1518]="你因为反对黑铁王国的罪行而被宣判死罪！"
D.Strings[1519]="索瑞森的臣民将在秩序竞技场中看着你死去！"
D.Strings[1520]="释放你的怒气吧！"
D.Strings[1521]="哈！我敢打赌你以为自己能获胜！"
D.Strings[1522]="但是真正的惩戒还在后面呢。"
D.Strings[1523]="很好！"
D.Strings[1524]="看看这些样本！这意味着什么？这意味着什么？我需要时间来解读这些信息。我还需要更多我无法获得的信息……该死！好好想想，拉里斯，好好想想！$B$B你要做什么？什么？！$B$B必须得有解决的方法！"
D.Strings[1525]="不，我并不清楚。似乎那主要与地域有关。有些种类称为泥浆怪，有些称为软泥怪。似乎这属于个人偏好。$B$B每次我遇到软泥怪、淤泥怪或泥浆怪时，它们从根本上都是一种生物。不同之处在于它们的环境，这也是我们需要一份纯净的样本的原因。"
D.Strings[1526]="一个纯净的样品就是在非故意情况下未被腐蚀的样品。我们需要尽可能在最基本，最正常的环境中找到这样的生物。$B$B这意味着某个全无文明痕迹或是未受艾泽拉斯某个种族所影响的地方。某块……处女地。"
D.Strings[1527]="那绝不是东部王国的任何一个地方。$B$B一定是在卡利姆多大陆的某处，但是距离部落和其他种族仍有相当遥远的距离。还没有受到分裂影响的某个地方——远离暗夜精灵文明的地方。$B$B我猜有人守护在那儿……就像守护山谷或是环形山一样；我不确定。我只是猜测。很抱歉我不能提供更多的帮助了。"
D.Strings[1528]="草药的收集和与之相关的知识是菲罗迪恩·唤月的专长。去达纳苏斯西南部的神殿花园找他吧。"
D.Strings[1529]="一个新手采药师？那你该找神殿花园的菲罗迪恩·唤月聊聊。他或许有些专业诀窍要传授给你。"
D.Strings[1530]="我不知道你为什么想要离开这阳光灿烂的沙滩和蓝色晶莹的水域。这里就象是天堂。但是不要告诉我的哥哥萨匹塔这些，他整天被困在提瑞斯法已经够难过的了。这里的地精飞艇目的地是奥格瑞玛，所以你不用担心得听他发牢骚。但是如果你到了提瑞斯法，要留意我的警告并且不要让他开始抱怨。"
D.Strings[1531]="好好利用自然界的草药，它会成为你有力的助手的。去本娜的炼金店找她吧，接受更多训练。"
D.Strings[1532]="你可以到中部高地的底层的雷霆崖银行存放你的财物。"
D.Strings[1533]="和其他所有事物一样，金属应该被平衡的使用。卡恩·石蹄在中部高地的底层的池塘边设立了一处铁匠铺。去寻求他的指引吧。"
D.Strings[1534]="你没有浪费那些你必须杀死的动物，因此你赐予了这些动物的灵魂以荣誉。阿丝卡·迷雾行者将会给你演示怎么处理。她在高地上有个厨房。"
D.Strings[1535]="你好尊贵的客人。图拉克·符文图腾和其余的德鲁伊正在长者高地上的长者大厅等你。"
D.Strings[1536]="附魔体现了毁灭和新生的循环，这正是自然界的基本准则。晨行者附魔师将为你展示这一切。"
D.Strings[1537]="生活是一场竞争，“大难不死必有后福”这句俗语并不是始终正确的。有时伤口愈合得很慢，这就是我们需要绑带的原因。灵魂高地的潘德·缚石能教你急救的技能。"
D.Strings[1538]="山顶渔具店的卡尔·迷雾行者将为你指明如何实现内心平静的同时还能通过钓鱼为自己准备好下一餐。"
D.Strings[1539]="一个志趣相投的团体可以成为一支非常强大的力量。克拉姆会帮助你们达到这个目的。你可以在雷霆崖升降梯旁边中部高地的底层的公民信息中心找到他。"
D.Strings[1540]="自然会提供我们所需的一切。跟中部高地中层克米恩·冰蹄谈谈草药学吧。"
D.Strings[1541]="动物的朋友就是我的朋友。你要找的猎人大厅就在猎人高地的顶部。"
D.Strings[1542]="利用敌人的兽皮来保护自己这一想法运用了拟态学的知识。要进一步提高制皮技能，你得去雷霆崖防具店找库纳。"
D.Strings[1543]="想到这些可怜的亡灵灵魂的遭遇，我感到非常悲伤。你可以去灵魂高地之下的预见之池附近找大法师山姆。"
D.Strings[1544]="大地之母有许多秘密，布瑞克·石蹄能帮助你发现一些秘密。你会在 石蹄地质学会的中部高地的底层那找到他的。"
D.Strings[1545]="虽然亡灵受到重创，但是他们还是赶来帮助我们。我只希望我们也能对他们有所帮助。去灵魂高地下面的预见之池附近寻找柯布神父。"
D.Strings[1546]="大地之母发出召唤，你得做出应答。你可以在灵魂高地找到灵魂大厅。"
D.Strings[1547]="充分利用每块碎片会让我们更加节约并会拉近我们和大地母亲的距离。莫兰塔会教给你方法。到中部高地上的雷霆崖兵器库外面可以找到她。"
D.Strings[1548]="给部落做衣服与其余的工作同样重要。你该到雷霆崖防具店里面寻找坦帕。她对针线活有自己的天赋。"
D.Strings[1549]="强壮的身体和精神。没有比这更强大的组合了！去猎人大厅跟萨尔克·暴怒图腾找寻自己的命运吧。"
D.Strings[1550]="啊，和天空中的巨鸟一同翱翔。去双足飞龙巢穴顶端找塔尔吧。他会指引你完成你的梦想的。"
D.Strings[1551]="去中部高地的底层的雷霆崖银行以南的建筑物中可以找到旅店老板帕拉。"
D.Strings[1552]="旅店老板帕拉能帮助你得到身心的休息。他就在中部高地的底层的雷霆崖银行以南的建筑物中。"
D.Strings[1553]="你能在中部高地的底层的雷霆崖银行外面找到一个邮筒。"
D.Strings[1554]="我记得不久之前我有新邮件寄出。你可以在中部高地的底层雷霆崖银行外找到邮箱。"
D.Strings[1555]="你可以在雷霆崖的最低处寻找，就在离银行不远的地方。"
D.Strings[1556]="你可以在雷霆崖的中央高地找到拍卖行。在双足飞龙飞行点下方附近找找吧，愿你的先祖保佑你。"
D.Strings[1557]="或许这会令你震惊，但是近来的事情不是那么顺利……"
D.Strings[1558]="欢迎你来到塞拉摩，$n。$B$B我没时间跟你寒暄，我为自己的唐突向你道歉，但是我必须以城市为首。我们的生活和联盟的尊严受到了严重的威胁。要想使我的人民平安幸福，我就必须对不在我们控制之外的力量保持警惕。$B$B或许稍后我们能找时间谈谈。"
D.Strings[1559]="亨德尔已经被我们逮捕了，$n。谢谢你。$B$B尽管审讯的进展会比较缓慢，但我向你保证，他会告诉我们他所知道的一切。$B$B眼下还请你耐心等待。如果我需要你的帮助，就会马上联系你。$B$B在那之前，请享受塞拉摩之旅，我邀请你作为联盟的朋友来到我们城市，要待多久随便你。"
D.Strings[1560]="你认为达丹加如何？"
D.Strings[1561]="在城市的大门外有一处路标指向西部地精塔。"
D.Strings[1562]="去城外东南方找东部飞艇塔。"
D.Strings[1563]="我和我的兄弟效忠于希尔瓦娜斯。在最黑暗的时代，她是我们的指路明灯。我们日复一日地奉献着，希望使种族避免遭受厄运。$B$B我们不会一直软弱下去的。我们会取回自己应得的。我们将报复敌人，让他们尝到十倍于我们的痛苦。并且，我们将面带微笑报复敌人。"
D.Strings[1564]="希尔瓦娜斯女王已经下令对艾泽拉斯的某些自然现象进行调查。她觉得能从艾泽拉斯神秘的历史中学到更多的知识。$B$B我不知道要如何才能学到这些知识，但是我完全相信她，因此我会尽力而为的。所有的生物看起来很相似，但是周围的环境对它们的影响是不容忽略的。$B$B我需要你帮我收集生物样本。"
D.Strings[1565]="<你靠近沃科尔时，他一点都不理睬你。他好象集中精力关注他的绷带以防脱落。过了一会儿，他抬头看你，有一点惊诧。>$B$B噢，对不起，$c。现在不太合适。我希望你能理解。"
D.Strings[1566]="嗯，依我看来，$n，要离开这个洞穴有两种选择。$B$B我们可以秘密潜逃——我利用你给我的披风，你用你自己的办法；或者，我们一起杀出去，但是我受伤了，这个方法或许比较困难。$B$B你更了解自己的实力，因此我让你来做选择。"
D.Strings[1567]="你好，$g小伙子:姑娘;，如果你想要在铁炉堡之外找到最好的交易地点，那么你就算找对地方了。"
D.Strings[1568]="你看到我们湖中污浊的水元素了吗，$n？这个场景令人感到伤感，但是我不知道它们是从哪里来的。$B$B在我过去的谈话中似乎有人提起过你的名字，或许你可以帮我。$B$B我们必须了解的第一件事就是谁控制着这些元素。"
D.Strings[1569]="你好。我是古博·布拉普。"
D.Strings[1570]="古博, 我没有钓鱼竿。"
D.Strings[1571]="……油煎，油炸，还有爆炒……"
D.Strings[1572]="当你靠近时，那些液体和混合物剧烈地翻腾起来。设备旁边是一把巨大的钳子，似乎很适合用来夹起淤泥样本。$B$B还有安全齿轮装备，但是上面布满灰尘，似乎很久没有使用过了。$B$B你觉得什么东西都不碰为好。"
D.Strings[1573]="哇！*咳**咳*我要戒烟！"
D.Strings[1574]="问问基布雷尔关于宝藏的事情！哇！"
D.Strings[1575]="比修失败了！啊！*咳嗽*"
D.Strings[1576]="比修知道宝藏被藏在哪儿了。"
D.Strings[1577]="奥普斯想要一些科尔戈的黄金……和一些虫子。"
D.Strings[1578]="他们都去了黑石塔，但是跟比修一样……没有人活着回来。"
D.Strings[1579]="基布雷尔正在接受地精工程学协会的调查。"
D.Strings[1580]="龙控制着兽人！？不会吧！"
D.Strings[1581]="%s发出凄惨的低啸，轰然倒地。黑石塔大厅中紧接着传来令人毛骨悚然的咆哮声。看来有什么生物受到了刺激，变得异常愤怒。"
D.Strings[1582]="别担心斯奎尔图，$n。他不想这么粗鲁的，他只是非常繁忙。我们不如趁着等他完成侦察任务的时候做些更有用的事情？"
D.Strings[1583]="你好$n！$B$B我必须继续研究我的装置了，但是最终……我需要有人给我带来龙蛋！"
D.Strings[1584]="燃烧平原是个危险的地方，但是我这样的学者将不惜一切代价来获取新知识。"
D.Strings[1585]="愿你能得心应手地应用熔炼黑铁的技能，$n。但是不要让你的知识使你堕落……就像我们一样堕落了。"
D.Strings[1586]="终于……终于有人值得学到我的知识了。别担心——我已经了解你的想法，我不会伤害你的。"
D.Strings[1587]="听仔细了，要是你没有准备好的话，黑石统领会杀死你的。"
D.Strings[1588]="你好，$n。你看上去是个强壮的$c——你应该能够在这个地区有所作为。你可以去接触一下你不了解的东西，否则对你的长辈表现出失礼的行为将招致惩罚。$B$B你可以不尊重我或者我的同伴，但是如果你真的那么愚蠢的话，你就必然会学会尊重我们的力量。$B$B现在，闲聊够了，有什么事情我可以帮忙的？"
D.Strings[1589]="啊，一个术士同伴已经在某种程度上证明了$g他的:她的;价值。$B$B很高兴认识你。我的名字是梅纳拉·沃伦德……那是有原因的。$B$B你看上去强大并博学，其他的工具……你是更强大的工具……会很受欢迎而不是愚蠢地泄密。如果事实确实如此，那再与我更深入地谈谈。如果不是，那么你知道你该怎么回到码头然后回到海洋的另一边。"
D.Strings[1590]="%s开始恢复力量！"
D.Strings[1591]="%s几乎完全恢复了力量！"
D.Strings[1592]="%s恢复力量，摆脱了镣铐的束缚！"
D.Strings[1593]="很久以前——我们的种族经历了无数战乱和冲突，几乎到了灭绝的边缘。我们承受了太多灾难，$c。$B$B燃烧军团的进攻，恶魔之魂，巨龙军团的分裂，死亡之翼的崛起，我们的女王阿莱克丝塔萨受到龙喉氏族的奴役。$B$B经过种种磨难，我们拥有了不可动摇的意志——那是努力生存的大无畏力量。"
D.Strings[1594]="你们的种族？"
D.Strings[1595]="我以你所能接受的形态站在你面前。显然，你无法接受一条名叫瓦拉斯塔兹的龙。$B$B<维埃兰笑了起来。>$B$B我可以继续吗？"
D.Strings[1596]="拜托。"
D.Strings[1597]="或许我应该告诉你为什么我会在这儿。$B$B你知道死亡之翼或者他的后裔，奈法利安和奥妮克希亚吗？"
D.Strings[1598]="不，维埃兰，我不清楚。"
D.Strings[1599]="死亡之翼，曾被称为奈萨里奥，它是代表世界的力量的守护巨龙——世界的缔造者卡兹格罗斯赋予了他无尽的力量，让他保护这个世界。$B$B但是这个卑鄙的家伙欺骗了其他四条守护巨龙，让他们使用自己的力量制造了恶魔之魂——这使得他们的力量大为减弱，巨龙军团于是就分裂了。"
D.Strings[1600]="恶魔之魂？"
D.Strings[1601]="是的。最终恶魔之魂被摧毁了，剩余的四条守护巨龙联合起来，几乎取了死亡之翼的性命。没人知道死亡之翼现在到底在哪里。但是，我们知道他的一名后裔奈法利安正统治着这座要塞，希望能继续他父亲未竟的事业。"
D.Strings[1602]="未竟的事业？"
D.Strings[1603]="在被放逐之前，死亡之翼曾试图产下混血的后代。混血的龙不仅无法获得守护巨龙天生的力量，也无法被死亡之翼控制。$B$B似乎奈法利安在他父亲失败了的事情上取得了成功——至少是一些进展。$B$B梦境之神伊瑟拉预见到了这种混血龙类的存在，我们必须杀死那些“彩色”的龙。"
D.Strings[1604]="为什么巨龙们不联合起来消灭它们？"
D.Strings[1605]="这不是我们做事的方法，也不可能是。奈法利安受到远古结界的保护，这些结界与守护巨龙本身一样古老。正是它们阻止我进入这座要塞的内部。除非……除非得到授权，否则黑暗魔法会永远把我们挡在外面。"
D.Strings[1606]="除非？"
D.Strings[1607]="除龙族之外的任何人都可能获得晋升印章并通过那层保护屏障，但是这样的东西肯定会要了我的性命，或许你能使用它，想办法破除屏障。"
D.Strings[1608]="我很乐意尝试，但是我需要指导。"
D.Strings[1609]="你必须在这座要塞下层部分的那些邪恶生物里找到一个拥有原始晋升印章的家伙。对于那些劣等生物来说，得到这枚物品是一个至高无上的荣誉，这是迈入堡垒上层，进入奈法利安的精英军团——黑手军团的第一步。找到这么一件东西，把它交给我，让我来检查一下它，然后我就会知道下一步该怎么做了。"
D.Strings[1610]="我会尽力做到最好的，维埃兰。"
D.Strings[1611]="你要知道，这样的物品是非常罕见的。你可能需要进行数年的搜索才能找到一枚印章。我建议你对这些邪恶的生物毫不留情，把他们全都杀掉。"
D.Strings[1612]="我们会完成这个任务的。"
D.Strings[1613]="别再靠近我了，$n。我已经可以感觉到印章中流淌着的邪恶力量了。$B$B给我一点时间，让我来检查检查——你要紧紧地握住它。"
D.Strings[1614]="如你所愿，维埃兰。"
D.Strings[1615]="%s被反魔法屏障包围着。"
D.Strings[1616]="我已经看清了你要走的路。你准备好了吗？"
D.Strings[1617]="走开，凡人！你不配获得我的知识。"
D.Strings[1618]="这不是个游戏，伙计。你想使用斧子，就必须说那句话。说什么？“跟我的小朋友打个招呼。”"
D.Strings[1619]="$n，我已经查明魔苔在整个黑海岸的影响有多么的猖獗。泰达希尔和我们周围大地的堕落的确引起了塞纳里奥议会德鲁伊以及所有的暗夜精灵的关注。$B$B我的目标就是查出为什么会发生这样的事并将其制止。"
D.Strings[1620]="%s开始召唤黑铁恐法师！"
D.Strings[1621]="%s召唤出黑铁恐法师来帮助他！"
D.Strings[1622]="%s开始召唤黑铁老兵！"
D.Strings[1623]="%s召唤出黑铁老兵来帮助他！"
D.Strings[1624]="过奖了，但我真的不感兴趣……什么？你想知道在哪儿能学习附魔知识吗？哦，真令人为难！呃，你应该……我想你应该……去找那个，嗯……塔兰丹！对，去工匠区找塔兰丹！"
D.Strings[1625]="范克里夫出高价悬赏你！"
D.Strings[1626]="欢迎来到我的商店，$c。古斯提兄弟能为你做什么吗？"
D.Strings[1627]="啊，我最喜爱的顾客之一。你似乎是个有能力的术士，$n。很高兴认识你。要是我能帮上什么忙，请尽管开口。$B$B我和我的兄弟都认为你这样的人才能领导我们进入新纪元。一个拥有力量……和控制力的人……让军团臣服于你只是时间问题。$B$B我有些羡慕你了。"
D.Strings[1628]="很好……看起来好像这些爱管闲事的小人物来得正是时候。欢迎，凡人！！"
D.Strings[1629]="我的孩子，让他们的鲜血在地板上一滴也不要留下了。享受他们的灵魂大餐吧！"
D.Strings[1630]="走吧$n，前往白沙岗哨。"
D.Strings[1631]="这看上去很眼熟，要是我们一直朝东走的话，我想我们能做到的。啊！双足飞龙，备战吧！"
D.Strings[1632]="啊，$r……我了解很多关于这个世界的知识，以及如何制造巨大能量的符咒的方法。"
D.Strings[1633]="玛艾里知道你为什么找她……$B$B带给我你找到的魂精，我就会为你转换它。"
D.Strings[1634]="我要如何使用玛艾里的容器？"
D.Strings[1635]="使用冰冻喷吐，你这蠢货！"
D.Strings[1636]="蠢货……杀死穿那件衣服的人！"
D.Strings[1637]="孩子，别推我的手！我将用你的兽皮装饰我的靴子。"
D.Strings[1638]="你的努力都是白费心机。没有什么会阻止我们的！"
D.Strings[1639]="非常感谢你……从这里我能找到回白沙岗哨的路。记得跟莫特加·火鬃谈谈，也许你能阻止他送我回家。"
D.Strings[1640]="是的是的，我知道达丹加不喜欢烟。但从它身上的气味来看，达丹加好像还不喜欢洗澡。"
D.Strings[1641]="魂精是什么?"
D.Strings[1642]="玛艾里的容器有很多秘密……用来制作它的碎片是可以反光的，你可以使用它的反光面从其它事物身上吸取能量然后反射到自己身上。$B$B将护符放在你的背包里可以让你聚集魂精，也就是与你战斗的野兽的灵魂力量。一旦你找到魂精，你把它带给玛艾里。"
D.Strings[1643]="魂精是每个生物都有的能量。我为你做的护符使你能以物理形态来抓到它。$B$B我知道一个可以转换你发现的魂精的咒语，并把它转换成魂能。$B$B你然后可以得到玛艾里的容器，并使用它把魂能的能量转换到自己身上。$B$B来吧，试一下。把玛艾里的魂精带来我们开心一下。"
D.Strings[1644]="这不可能！！！雷德，解决掉这些家伙。"
D.Strings[1645]="凡人战败了！黑石军团的新时代即将来临！"
D.Strings[1646]="%s从他的座龙身上摔了下来！"
D.Strings[1647]="酋长会除掉你的，凡人。做好准备吧！"
D.Strings[1648]="很荣幸……"
D.Strings[1649]="你好，$g小伙子:姑娘;。我可以帮你什么忙吗？"
D.Strings[1650]="你是来接受训练的吗？我也是刚刚开始学习这方面的知识，但是我很乐意把我所知道的教给你。"
D.Strings[1651]="你学得很快，$g小伙子:姑娘;，快得我已经远远跟不上你了。如果你想继续学习的话，我建议你去见见我的导师。他的名字叫洛特加斯，嗯，洛特加斯·石须。你可以在铁炉堡的大锻炉那里找到他。"
D.Strings[1652]="尝尝我的力量吧！"
D.Strings[1653]="嗯？我没时间聊天，我父亲要我完成这个使命。"
D.Strings[1654]="你确实有点本事。我打赌你的技术足够让你学些东西了，我们来看看我有什么能教给你的，好吗？"
D.Strings[1655]="你知道的比我还多，这一点很肯定。我告诉你接下来该怎么办，去和我的爸爸谈谈。他是个好的老师，但是他会要求你证明自己的实力。他的名字叫洛特加斯，你可以在本古斯的铁砧旁边找到他。"
D.Strings[1656]="我的朋友，你所掌握的技艺远胜于我。你为什么不去找我的老朋友洛特加斯·石须继续深造呢？我离开铁炉堡加入了吉安娜的军队，而他留了下来。我想他能教你点什么，至少他会知道谁能教你。如果他还待在铁炉堡的话，我想他一定在大锻炉附近。"
D.Strings[1657]="从冬泉谷的生物开始应该不错。$B$B然而，或许还有别的地方你可以看看……"
D.Strings[1658]="当然，我可以帮你进行训练。我也只是一个新手，但是我想我还是能对你有所帮助的。"
D.Strings[1659]="我不会轻易承认这一点的，不过你的确是个比我出色得多的铁匠。如果你想要学习更多高级的技能，我建议你去暴风城的矮人区找一个名叫瑟鲁姆·深炉的矮人。"
D.Strings[1660]="很抱歉，我现在有些忙，我要为湖畔镇的弗纳·奥斯古打造马蹄。"
D.Strings[1661]="我看上去像是有时间和你闲谈的样子吗？"
D.Strings[1662]="你还不坏，但让我耍耍几个小把戏，你可能会觉得很方便实用的。"
D.Strings[1663]="你已经是一个比我好得多的铁匠，那是肯定的。尽管如果你告诉其他人这点我会否认我曾说过。你该去找瑟鲁姆·深炉谈谈。如果有人能教你，那就是他。"
D.Strings[1664]="再让我听到一句关于水鸟的废话，我就把你打得生活不能自理。"
D.Strings[1665]="仅仅会挥动铁锤是无法成为铁匠的。把铁锤给我，在你让大家感到窘迫之前让我教教你好了。"
D.Strings[1666]="还行。去跟斯纳尔谈谈，他刚前往奥格瑞玛向萨鲁求学。去萨鲁的铁匠铺附近的战士区找他吧。他会对你进行测试，你最好做好准备。"
D.Strings[1667]="斯纳尔因为我动作慢了所以叫我。我只是想做好工作罢了，这得花时间的。"
D.Strings[1668]="我可以告诉你你想知道的一切，但是你必须要有耐心。去练习打铁吧，摸索用锤的力度。当你熟练后，自然也就掌握啦。"
D.Strings[1669]="你学得很快，这是件好事。但要注意按照工作的要求适当地完成工作。现在，我恐怕必须要把你送到斯纳尔那里多学些东西。你要学会所有他能教的，但不要听他的气话。当萨鲁的女儿笑话他时他就变成那样了。"
D.Strings[1670]="我在听，我在听，但是听不见卡恩所说的那些灵魂的声音。"
D.Strings[1671]="卡恩说我们需要聆听熔炉和钢铁的灵魂之声，它们会指引我们的。我只听见一阵铃声。拿起铁锤，让我们一起试着听它们在说什么。"
D.Strings[1672]="我猜那些灵魂更加喜欢你，我还没有听到他们的召唤但是你看起来已经上过他们好多课程了。去找卡恩谈谈，他会很高兴看到一个像他一样听到它们声音的人。"
D.Strings[1673]="你的打扰在占用我的宝贵时间，你最好带来的是好消息。"
D.Strings[1674]="啊是的，另一个要烧炉火并锻造战斗武器的人。我当然会教你怎么操作。"
D.Strings[1675]="我的孩子，你学得很好。去幽暗城找一个名叫詹姆斯·范·布朗特的铁匠。他能传授给你更多的知识。我想他应该在战士训练大厅附近铸造武器。"
D.Strings[1676]="我希望有一天能用敌人的骨头制作武器。"
D.Strings[1677]="你不要用锤子傻乎乎地敲打铁砧，你应该是在制造一种可以杀死你的敌人的武器。让我给你演示一下你哪里做错了。"
D.Strings[1678]="你已经学得很多，我没什么能教你了。去找詹姆斯·范·布朗特，他会教给你我所不能的。"
D.Strings[1679]="魂精是超自然力量的一种尚未汇聚起来的形态，而魂能则是浓缩的精华。通过使用一种强大的咒语，我可以把魂精变成魂能。一旦它变成魂能，你就可以使用玛艾里的容器把能量反射到你自己身上。"
D.Strings[1680]="我把玛艾里的容器弄丢了。我该怎么办？"
D.Strings[1681]="我很惊讶一个如此粗心的人竟然能走到这里……$B$B是的，你可能还有一个符咒，但是玛艾里对你的行为很生气！$B$B现在赶紧离开。"
D.Strings[1682]="天哪！现在的温度是428,000克氏度！"
D.Strings[1683]="温度是564克氏度。"
D.Strings[1684]="温度是12克氏度。真令人激动。"
D.Strings[1685]="%s倒下了，但是它那破碎的躯体又挣扎着站了起来！"
D.Strings[1686]="这儿有活人！"
D.Strings[1687]="嗷！好吧，我回去工作，$n！"
D.Strings[1688]="你掌握一些关于锤头和铁砧的技艺，但还不够。去找丹恩·林德雷谈谈，他会让你做好准备学习我教给你的知识。"
D.Strings[1689]="我说过你有铁匠的血统，看来我是对的。去铁炉堡大熔炉找一个名叫本古斯·深炉的矮人铁匠。他是我的老师，是我知道的最伟大的铁匠之一。"
D.Strings[1690]="铁匠的生活可不轻松，但是它能让你体格健壮，充满热情。我的父亲是一名铁匠，我的祖父曾经在格瑞姆巴托的炼铁炉工作。现在，我的儿子也跟随着我们的脚步，他让我倍感自豪。"
D.Strings[1691]="很抱歉，$g小伙子:姑娘;，你还不够资格在我这儿求学。去找我的儿子 格鲁姆，他会收你做学生的。"
D.Strings[1692]="你的技艺不是一无是处，但我在接纳你之前还需进行最后一次测试。"
D.Strings[1693]="是的，很高兴能教你如何锻造。系上围裙，拿起铁锤，看看我们能锻造出什么来？"
D.Strings[1694]="你是个有天分的学生，而且还是个有潜质的铁匠。我可以在本周任何时候宣布你可以从我这里毕业了。但是我觉得你还有东西要学。去找本古斯·深炉谈谈，他是个严厉的人，但他也是最出色的。"
D.Strings[1695]="%s高声喊叫。"
D.Strings[1696]="不要那样从阴暗中走出来。下次你要先给女生一点警示。"
D.Strings[1697]="自从阴影占据了暮色森林我就一直无法入睡。我总是被风中传来的可怕尖叫声惊醒。那听起来好像羔羊的叫声，而且声音从不会停止。"
D.Strings[1698]="呣，你的工作还可以，但是离我期盼的学生素质还差太远。去找闪金镇的铁匠阿古斯谈谈，我敢肯定他能教你一些基础知识。当你学完后再来找我，我会给你一次小测试以确定你准备好了。"
D.Strings[1699]="是的，我曾听到传言说我迟早会见到你的。但我不会随便接纳任何人的，我需要首先确定你的水准。你愿接受我的测试吗？"
D.Strings[1700]="你干得很漂亮，但是刀口还有些粗糙。不要担心，多加练习就会好的。说到这里，我们看看你一直以来的工作怎么样？"
D.Strings[1701]="现在我真是力不从心了，我说实话真是没什么可教你的了。但你知道谁可以吗？铁炉堡的本古斯·深炉，现在有一个矮人很了解他。到铁炉堡的大铁炉去找他，看看他是否想收个新学徒。"
D.Strings[1702]="要是我向萨鲁证明了自己的实力，他将别无选择，只能让我为他的一个女儿而战。让我们看看谁是失败的那个吧。"
D.Strings[1703]="离苏米和图米远点。他们会……极力推销他们的东西的。"
D.Strings[1704]="再次给我带来这种劣质货我就把你装在用山羊尿回过火的小铁盒里送回家。现在去见见那个傻瓜乌格索克，他更加适合你的需要。"
D.Strings[1705]="你认为自己够资格向我学习吗？你不过是我脚下的一名卑微的小人物罢了。但是，收纳一名下属或许能增加我对苏米和图米的吸引力。让我看看你拥有什么技能。"
D.Strings[1706]="我没有什么东西可以教你了，现在你可以走了。不要想接近萨鲁，因为像你一样卑微的家伙，他只会用你们的血来炼钢。"
D.Strings[1707]="灵魂将你带到我这儿来，感谢他们。"
D.Strings[1708]="你需要多加留心灵魂的指引。你的道路取决于另一个人，雷霆崖的瑟拉格·石蹄。或许你们可以互相学习。"
D.Strings[1709]="告诉你，你准备好接受我为你安排的挑战了吗？幽灵告诉我你会通过的，但是你相信他们抑或是相信自己？"
D.Strings[1710]="我们的人生之路只是暂时相交，现在是我们分道扬镳的时候啦。很荣幸能传授你知识，现在我送你上路，去找下一个导师吧。去奥格瑞玛找萨鲁·钢怒，他会教你你想学的知识。"
D.Strings[1711]="你有巨大的潜能，但你首先要理解，你必须接受精灵们并听从他们的召唤。只有那时你才会准备好走你要走的路。去找瑟拉格谈谈，我想你们可能会互相学习很多东西。"
D.Strings[1712]="你已经学了很多，但我觉得精灵们还有很多要教给你。我可以给你引路但不能替你走路。去找到奥格瑞玛的萨鲁·钢怒，你的旅程的下一段从那里开始。"
D.Strings[1713]="你在浪费我的时间，去找我的学生巴兹尔谈谈吧。"
D.Strings[1714]="你制造的装备很不错，真的。去兽人的家园奥格瑞玛找一个名叫萨鲁·钢怒的铁匠吧。你必须给那些制造美丽的死亡器具的兽人一样东西。"
D.Strings[1715]="很抱歉$g小伙子:姑娘;，但是你基础不足，我不能教你。但是别烦恼，跟我的学生洛特加斯谈谈，他会帮助你的。"
D.Strings[1716]="我不能对你进行什么指导啦，你能用铁锤和铁砧做出如此令人称奇的东西。我建议你去找一个名叫布里克·基克拉夫的地精，你可别告诉别人,我最后一次听说他在藏宝海湾经营一家商店。"
D.Strings[1717]="这可不是一个年轻人玩的游戏！去外面找斯纳尔谈谈。他看上去或许有些阴险，但是他确实是使铁砧的好手。"
D.Strings[1718]="我发现你所掌握的炼钢知识已经比我多了。这很好，本该如此。现在你必须去人类领土南部的丛林，去地精城市藏宝海湾。你将在那儿找到一个名为布里克·基克拉夫的地精。我不喜欢地精，但他所掌握的炼钢知识却是无与伦比的。"
D.Strings[1719]="什么？我当然是一个铁匠。什么，你认为矮人是打铁最有效率的种族？好吧，可能是那样。去找一个矮人来帮你！"
D.Strings[1720]="你是在开玩笑吧？你一定是在开玩笑！你认为我是个取悦于你的小丑，是吗？我是小丑？嗯，是的！你认为我是小丑，是吧！"
D.Strings[1721]="好像这是我所见过的最好的垃圾。当然它还过得去，但我每天都看到这类‘还行’的东西。告诉你吧，你若能想办法让我叫好，我就会教给你能让矮人们在睡梦里都会笑的东西。"
D.Strings[1722]="你的胜利不会长久。联盟和部落的日子都不长了！下次我们见面就是最后一次了。"
D.Strings[1723]="尽管我不愿承认，但是熊确实打败了我。我的天，那是一只体型庞大的熊！$b$b但是，如果你能打败那只熊的话，那可是一件值得骄傲的事儿！既便是我们中最好的猎人，也为此头痛不已。$b$b<他拍着你的背。>$b$b打败熊吧，你将成为旅行者营地中一名合格的成员的。"
D.Strings[1724]="在旅行者营地，我们最推崇狩猎技能。想获得我的赏识吗？你得靠行动来证明。$B$B面对挑战吧，$G小伙子:姑娘;！"
D.Strings[1725]="你已经成为一个出色的猎手了，$n！你不但证明了你的技能，你还胜过了达瑞尔，这是你在我的名册中得到了额外的分数！$B$B欢迎你随时来到这里。"
D.Strings[1726]="是你召唤我来的，愚蠢的东西！现在受死吧！"
D.Strings[1727]="很愿意……只是让我再多回味一下这一刻。"
D.Strings[1728]="他们在魔法区。去那幢恐怖的骷髅楼中找他们吧。"
D.Strings[1729]="我们知道他们在哪儿！他们就在城市外环魔法区的骷髅建筑物中。"
D.Strings[1730]="银行就在贸易区中心的塔中。你不会找不到的。"
D.Strings[1731]="我们只有一只眼睛，但看得比你远！银行就在幽暗城中心！"
D.Strings[1732]="贸易区上层的蝙蝠管理员。"
D.Strings[1733]="噢，你在寻找贸易区的克里斯托弗·德库尔。他在东部的平台上。"
D.Strings[1734]="我们加入公会了？没有？好吧，去贸易区的东平台找公会注册员吧。"
D.Strings[1735]="你得去贸易区找旅店老板诺曼谈谈。"
D.Strings[1736]="不能让邪恶势力有喘息的机会，但是我想你还是需要一些休息。去贸易区的上层找旅店老板诺曼吧。"
D.Strings[1737]="在交易区中心就有的邮箱……就在旅馆旁边。"
D.Strings[1738]="我们得确认一下是否碎……碎……碎灵斧是不是卖掉了。去贸易区上层的旅馆旁找邮箱吧。"
D.Strings[1739]="中央地带有拍卖行，就在南边。"
D.Strings[1740]="中部区域，南侧。去吧！"
D.Strings[1741]="洛丹伦废墟北面的飞艇塔楼上有个叫萨匹塔的小个子地精。离开幽暗城以后去找他，就可以去奥格瑞玛了。"
D.Strings[1742]="我们经常会看到一个兴登堡运营的气球停在废墟北面靠右的那座塔楼边上。它可以把你带到遥远的地方去，比如荆棘谷格罗姆高的丛林。"
D.Strings[1743]="牧师训练者？去军事区的外圈找找看。"
D.Strings[1744]="哼。军事区的邪恶的生物站在城市外圈的主建筑物周围。"
D.Strings[1745]="这肯定会让达瑞尔大吃一惊。是他活该，这个傲慢又该死的混蛋。但是哈！把这个给他瞧瞧，我迫不及待地想看看他脸上的表情。"
D.Strings[1746]="欢迎来到旅行者营地，$n！"
D.Strings[1747]="潜行者都在盗贼区外环的建筑物中。"
D.Strings[1748]="他们教我如何“妙手空空顺手牵羊”。你可以在幽暗城外围的盗贼区找到他们。"
D.Strings[1749]="你在这里永远都受欢迎，$n。谢谢你带来的欢笑--还有不要担心达瑞尔，他就是这样一个人！"
D.Strings[1750]="术士训练者在法师区外环中的建筑物中，他们跟法师呆在一起。"
D.Strings[1751]="我们想让地狱犬成为宠物。我们喂养它、善待它并教它学会去拣我丢出去的木棒。去城市外环的法师区找术士吧。"
D.Strings[1752]="在城市外围军事区建筑中。"
D.Strings[1753]="战士训练师都是作战高手。你可以去幽暗城外环的军事区找他们。"
D.Strings[1754]="你可以去炼金房看看。那是赫伯特·哈尔希医生和马尔什医生练习的地方。"
D.Strings[1755]="在我们出生之地炼金房的赫伯特·哈尔希医生的医术高于我们，他会医好你的背部的。"
D.Strings[1756]="内环军事区的詹姆斯·范·布朗特。"
D.Strings[1757]="詹姆斯·范·布朗特的工作地点在军事区内环。他能为我们打造很好的锁链。"
D.Strings[1758]="贸易区的那个尤奈斯·伯奇。"
D.Strings[1759]="尤奈斯·伯奇卖剩下的零部件。你可以到贸易区找她。"
D.Strings[1760]="到炼金房的内环去。拉文尼亚就在那儿。"
D.Strings[1761]="拉文尼亚女士教你制作魔法物品。她就在炼金房的内环。"
D.Strings[1762]="幽暗城外环盗贼区的弗兰克林·洛伊德。"
D.Strings[1763]="嗨，炸弹，我们喜欢炸弹。格拉哈姆·范·塔伦会教你如何制造炸弹的。他居住在盗贼区的外层。"
D.Strings[1764]="我们很了解玛丽·艾塔斯。她就在盗贼区的内环。"
D.Strings[1765]="当我们受伤时，她总为我们医治。你可以在盗贼区找到她。"
D.Strings[1766]="你在魔法区不会找不到阿曼德·克伦威尔的。他就站在码头上。"
D.Strings[1767]="阿曼德·克伦威尔在魔法区的码头附近垂钓。试试去那儿找他。"
D.Strings[1768]="你寻找的是马尔萨·奥列斯塔。她在炼金房的内环上。"
D.Strings[1769]="你需要去内环的炼金房。那就是马尔萨·奥列斯塔教你如何摘花的地方。"
D.Strings[1770]="他居住在盗贼区内环。"
D.Strings[1771]="盗贼区内环的亚瑟·摩尔能教你制革技能。"
D.Strings[1772]="到军事区的内环去。布罗姆·基里安在那里。"
D.Strings[1773]="布罗姆·基里安教你如何为挖掘出闪光的东西。他在军事区的内环。"
D.Strings[1774]="基里安·哈根在盗贼区传授剥皮的技能。"
D.Strings[1775]="你寻找乔瑟夫·格里高利。他在绿色运河的内环边上的魔法区里。"
D.Strings[1776]="嗯，那是个好主意。或许我们该到那儿去换一下我们身上的线？他的针线活做得很好。你可以在魔法区的内环里找到乔瑟夫·格里高利。"
D.Strings[1777]="哦，好的！给你，$n。我只能这么报答你了！"
D.Strings[1778]="听一听长者的故事吧，$n。我有许多话要说……"
D.Strings[1779]="欢迎来到避难所，$n。有些人来这里是有目的，其余的是凑巧路过……但是每个到这里的人好像都有一个奇特的故事要讲。"
D.Strings[1780]="警惕些……阿纳克对恐怖图腾有一种奇怪的能力……他们看到我逃跑了是不会开心的。"
D.Strings[1781]="当心，恐怖图腾的成员快要过来了！"
D.Strings[1782]="他们来了。"
D.Strings[1783]="更多恐怖图腾的成员正在朝这边冲过来！"
D.Strings[1784]="终于自由了……我现在必须走了，谢谢你帮我逃脱。我自己会回到乱风岗去的。"
D.Strings[1785]="我想将堕落的猫交给温娜。"
D.Strings[1786]="谢谢你，$n。你安抚了我死去的妻子的灵魂，我将永远无法报答你的恩情。$B$B我想我会永远仇视野猪人，但是现在我已经得到了满足。$B$B我必须开始重建生活。"
D.Strings[1787]="看看这东西不牢靠的结构。你一定要念完咒语，否则你就只能召唤出这样的东西来。"
D.Strings[1788]="这个比上一个稍微好那么一点。但是它的骨架结构还是很脆弱。你能召唤出这样的东西，证明你还是在不断进步的。"
D.Strings[1789]="噢，这东西简直毫无用处。让我再试一次。"
D.Strings[1790]="嗯，这东西看起来做成风铃更合适。做好笔记，学生们……冲锋厮杀时你们可不能召唤出这样的玩意儿来。"
D.Strings[1791]="什么事情让你花了这么长的时间？"
D.Strings[1792]="挖掘一把野草需要多长时间？"
D.Strings[1793]="照这样的速度，我自己都能收集到足够的数量！"
D.Strings[1794]="如果你想要做什么事，就去做吧！"
D.Strings[1795]="好像我已经获得永生一样。"
D.Strings[1796]="啊，一定是他……不是？呸！"
D.Strings[1797]="或许我应该就从法鲁萨那儿购买一些？"
D.Strings[1798]="我必须去申请一个憎恶……一个憎恶！"
D.Strings[1799]="这具尸体属于一个女性兽人战士。$B$B很明显她是在战斗中死去的，或许是在对付这片地区的野猪人时死亡的。"
D.Strings[1800]="我将进一步检查尸体。"
D.Strings[1801]="你把尸体翻过来然后看到她武器上的标志——她的护甲已经都损毁了，她的头发披散在她的脸上。$B$B根据曼科里克对于她的描述，你可以确定这就是她的妻子。$B$B他一定会为这个消息而感到悲伤，但是你相信他还是希望知道真相的。"
D.Strings[1802]="欢迎来到十字路口，$c。我叫索克——以酋长的名义，我负责在这儿进行防御。$B$B请你在这里随意一些。在你处理生意的时候，没人会对你占用空间有所异议的。$B$B我们的安全存在许多威胁。如果你想熟悉周围的情况的话，就跟其他人谈谈吧——或许他们会派给你一些任务的。"
D.Strings[1803]="<高图斯啐了一口唾沫。>$B$B我是部落的勇士，$n。让我愤怒的是得知我们的敌人正坐在离卡加斯不到一天路程的堡垒中，密谋着要对我们发起攻击。$B$B我渴望摆脱责任的束缚，以酋长的名义将他们消灭。$B$B但是，我们都有各自必须承担的职责。"
D.Strings[1804]="你能以部落的名义冲锋陷阵，我可真羡慕你。我的职责是指挥部落的军队，而不是亲自上阵。$B$B当然，我年轻时也曾梦想着能安度晚年。现在，我痴迷于胜利的荣耀和失败的苦楚——这些都取决于我所指挥的士兵们。"
D.Strings[1805]="我做梦了，$n……对，我做梦了。在梦中，我以上千种不同的方式死去。有人会认为这是噩梦，但我不这样想！在梦中，我在战场上死去。每次死亡之前我都会让一万名部落的敌人倒在我的脚下。这是无上的荣耀！"
D.Strings[1806]="是的，看到你我就想起来了，$n。你让我想起往日的时光，我曾是部落的一名年轻的战士。$B$B毫无疑问，你将在你的一生中游历四方，征战沙场。$B$B<高图斯向你敬礼致意。>"
D.Strings[1807]="谦虚点吧……或许现在是时候了，$n。你做好进入黑石要塞的准备了吗？你做好发动一场战争，摧毁他们大本营的准备了吗？"
D.Strings[1808]="我绝不会怀疑你的，$n。$B$B这些是给你的命令，$n。我知道你是不会让我失望的。"
D.Strings[1809]="你好，年轻的$c。"
D.Strings[1810]="你好，伊崔格。我从黑石塔为你带来消息。"
D.Strings[1811]="雷德，是黑手的儿子，他是黑石氏族的酋长。他是一个十足的恶棍。$B$B当第二次大战结束时，雷德和他的兄弟麦姆逃往黑石塔要塞避难。雷德正是在那儿宣称自己为黑石氏族的酋长的。"
D.Strings[1812]="只有一个酋长，伊崔格！"
D.Strings[1813]="是的，年轻人，你不需要让我相信这些事情，酋长和我有很多过去的故事要说。然而你所做的贡献是众所周知的。$B$B就象我说的那样，雷德已经为他的人民找到了新的家园，我也是那些不知疲倦跟随他的人中的一员。$B$B那一次冲突激起了其它……其它无数的冲突。就是在黑石氏族和黑铁矮人为了黑石塔的战斗中我的两个儿子被杀害了。就在那时我意识到了我在黑石氏族的日子结束了。"
D.Strings[1814]="我走了。我不属于黑石。不，我的孩子不能白白死去。我不会在雷德这样无能、热衷于权利的疯子手下做事的。$B$B我隐居在壁炉谷附近洛丹伦的森林中。"
D.Strings[1815]="壁炉谷？？但是……"
D.Strings[1816]="<伊崔格笑了。>$B$B年轻人，世界不总是这么混乱不堪的。那只是亡灵天灾笼罩大地前的一段时间。在洛丹伦的那些地方在成为瘟疫之地之前。$B$B就是在那里萨尔从死亡之中拯救了我，也是在那里我加入了新的部落…但是我跑题了。这是另外一个时期的事。是的,另外一个时期……或许…"
D.Strings[1817]="伊崔格，我会帮你的忙的。"
D.Strings[1818]="我想你会的。或许有一天你能将消息传给我的一个老朋友。我听说他还在那片森林中。$B$B<伊崔格低下头，好像在做祈祷。>$B$B雷德，是的……雷德和他的兄弟麦姆统治了黑石塔，与黑铁矮人经常发生冲突。他们试图将黑铁矮人完全赶出城市的上层部分，但是只有在飞龙来到和麦姆死掉之后它才真正实现。"
D.Strings[1819]="啊，他们就是这样将黑铁驱逐到黑石塔下部的。"
D.Strings[1820]="事实上。奈法利安，死亡之翼的子嗣现在正统治着黑石塔。雷德受到龙的支配。$B$B只要你能设法穿过晋升大厅。$B$B<伊崔格叹息着。>$B$B此外，只有受到黑龙尊敬的人才有特权进入。"
D.Strings[1821]="或许还有别的方法进入？"
D.Strings[1822]="或许吧。年轻人，现在就出发吧。去找酋长，他肯定会乐意知道你的发现的。"
D.Strings[1823]="如你所愿，伊崔格。"
D.Strings[1824]="18克氏度。实际上有些冷……"
D.Strings[1825]="40克氏度。你觉得热吗？不觉得？我也不觉得。"
D.Strings[1826]="试炼谷能将最软弱的新兵锻炼成一名合格的部落战士。无法通过试炼者将被抛弃，独自忍受骄阳的煎烤。"
D.Strings[1827]="你好，$n。我是克罗诺姆，但是你可以叫我克罗米。我喜欢这种亲密感。$B$B现在——你问我是怎么知道你的名字的？我是青铜龙军团的一员，永远与时间的消长相合。你可以认为我们以前遇到过。从这个角度说，我们还会再见面。"
D.Strings[1828]="嗨，又见面了，$n。我感觉时间流仍处在强大力量的威胁之下。青铜龙始终欢迎你不断地提供帮助。$B$B虽然过去的事情已无法改变，但是将来却变化莫测。你此刻做出的决定将改变未来。"
D.Strings[1829]="听你的长辈的话，$n。要是你拥有强大的意志和热情，就没有不能控制的力量。"
D.Strings[1830]="并不是所有的被遗忘者都屈从于希尔瓦娜斯的意志，$n。我们中的某些人是被真正的力量驱动的——我们为自己赢得的力量。"
D.Strings[1831]="现在……不……是……最好的……时候，$n。我必须集中……精力。"
D.Strings[1832]="你的使命一定意义非凡，$c，它需要你深入沼泽……"
D.Strings[1833]="地狱火是术士在$G他:她;在战斗中所能使用最强大的恶魔。这个怪物很强大，护甲很厚，并能给任何敌人造成极大的伤害。如果你想把地狱火的灵魂加到你的武器上，你就会得到那些好处——更多的生命值和更快的生命恢复速度。$B$B如果你想了解更多关于地狱犬的事，那你就该与我对面的温图拉谈谈。"
D.Strings[1834]="地狱犬……确实是一个邪恶的生物。它不像地狱火那样强壮，但是聪明的术士知道蛮力不总是解决的办法——如果是，你就会选择战士了，不是吗？$B$B地狱犬利用敌人的法力，用它和它的迅速来战胜敌人。它的力量来自奥术并利用那种奥术能量为自己谋利。$B$B如果你想得知更多关于地狱火的事，那么你该找我对面的玛迦兹谈谈。"
D.Strings[1835]="你跟塔里的侍僧说过话了吗，$n？除非你能完成他们之中某个人的任务，否则我们就无法为你制作宝珠。如果你准备好了的话，就去跟他们谈谈吧。"
D.Strings[1836]="我的$g兄弟:姐妹;帮帮我吧……$B$B我很快就将离开这个世界了，虽然我饱受苦楚，但是我知道死了之后所有痛苦都将解除。但是，那些野生生物，我的$g兄弟:姐妹;……也历经折磨，永无止境。在我生命的最后一刻，我请求你的帮助。"
D.Strings[1837]="是的，我讲的语言你听得懂$r。我们不是动物，然而你们中大多数却仍然把我们像动物一样对待！可是我们的分歧比起降临到这片土地上的悲剧来显得微不足道。恳请你们把与我们存在的分歧搁置一边，倾听一下我临死前的请求。$B$B我来到这片土地尽我所能改善状况，而现在除非你能帮我，否则那即将要化为泡影。我用我生命的最后一息请你帮这个忙。"
D.Strings[1838]="“……”$B$B牛头人德鲁伊的尸体静静地躺着，看起来他好像终于离开了这个世界。"
D.Strings[1839]="没有人胆敢挑战兄弟会！"
D.Strings[1840]="蹲下来！"
D.Strings[1841]="你们都是些不值一提的渣滓！"
D.Strings[1842]="蠢货！我们的事业是正义的！"
D.Strings[1843]="胜利属于兄弟会！"
D.Strings[1844]="居住于塞纳里奥区的德鲁伊一直在大德鲁伊鹿盔的领导下警惕地保卫着自然界。你可以在达那苏斯北部找到他和别的德鲁伊训练师。"
D.Strings[1845]="我是这座城市的官员，从事幽暗城的人口普查工作。自从我们从亡灵天灾中解脱出来以后，我们就尽力对我们的城市人口做出精确的记录。通过一些奥术方式和聪明的方法，我才得以弄到这些记录。如果你需要有事找我的话，请继续。你应该知道你是否有事需要我的帮助。"
D.Strings[1846]="酋长指示我学习各种武器和护甲知识。他把我派遣到这兽人和牛头人文明的集合之地，接触尽可能多的旅行者，学习整个贫瘠之地的文明。$B$B他认为即使是最未开化的文明也有值得学习的地方——比如野猪人和半人马。"
D.Strings[1847]="你！$R！过来。<喷鼻声>$B$B时间短暂，而我的末日<喷鼻声>就要来临了。碎牙会赢；你会看到的。<喷鼻声>$B$B我的战利品还可以帮助<喷鼻声>我的人民。钢鬃部落要比刺背野猪人更加强大！$B$B部落正期望找出由谁来带领人民发动袭击。你<喷鼻声>作为回报要援助碎牙，告诉他只有我才知道的信息。碎牙能帮你！<喷鼻声>但你必须帮助碎牙。"
D.Strings[1848]="欢迎来到暴风城！我是城市的一名长官，帮助城市的人口调查局登记居民。如果你想找人的话，我也许能帮上你。我能运用奥术和智慧拿到这些记录。$B$B如果你找我有事的话，那就开口吧！"
D.Strings[1849]="我怀着深深的仇恨<哼>，但是是时候告诉你了，$r。$B$B很久之前，众神之间爆发了一场战争。我们伟大的野猪神阿迦玛甘在史前战争中战败，鲜血四溅，骨肉横飞。<哼>$B$B当他的鲜血流到地面上时，巨大的荆棘破土而出，他的徽记装饰着此地以南的洞穴。"
D.Strings[1850]="吆……我需要一根烟和找个好看的侏儒女人摸几下--倒不必非要按那个顺序！$B$B我被困在那个东西的肚子里已经有几个月了。今天几号了？啊，不要紧。重要的是我终于出来了。$B$B呜呼！"
D.Strings[1851]="怎么进去的？？嗯，这故事真长。"
D.Strings[1852]="好吧！我在熔岩大桥的熔岩坑测试熔岩服。一切进展顺利。我甚至能在熔岩中毫发无损地游泳！$B$B我在那儿做自己的事，有时仰泳一会，突然之间它把我一口吞没！若不是有了熔岩服和便携式食物机，我一定会就此交待了！"
D.Strings[1853]="我说，我感觉你对此充满怀疑——但是，那就是事情的经过。"
D.Strings[1854]="我才从这野兽的肚腹之中出来还不到两分钟，就有人问起我如厕的问题？？？$G先生:小姐;，如果你不是救我的那个人，我一定早就把你敲傻掉了！$B$B无论如何！我很感谢你的帮助。或许我能回报你？"
D.Strings[1855]="嗯，或许报酬这个词不是最合适的说法。当我在那东西的肚腹之中时，我在想：$B$B这家伙生活在灼热的岩浆中，火焰却不能伤害它一丝一毫！$B$B如果我能找到这样一块兽皮的话，我就把它交给我在永望镇的朋友玛雷弗斯·暗锤。如果说有人能处理这种兽皮的话，那个人就是他。"
D.Strings[1856]="帮我送个信怎么样？"
D.Strings[1857]="想买蟑螂吗？"
D.Strings[1858]="你不能唤醒沉睡者！"
D.Strings[1859]="死亡的纠缠会让你彻底湮灭！"
D.Strings[1860]="我是毒蛇之王！我无所不能！"
D.Strings[1861]="没有人能对抗毒蛇之王！"
D.Strings[1862]="%s发出懦弱的哭声。"
D.Strings[1863]="%s小心地瞄准目标……"
D.Strings[1864]="%s选择了兽人目标……"
D.Strings[1865]="我的时间不多了……我们的时间都不多了……"
D.Strings[1866]="我有很多要做的……在瘟疫来之前有很多……"
D.Strings[1867]="约翰，亲爱的，你在哪里？"
D.Strings[1868]="每个人都是怎么了？我感到……很冷……"
D.Strings[1869]="精灵用一种从前没有过的审视感觉看着你。$B$B“我感到一个大负担从我的灵魂中消除。很快我就可以永远平静的休息了。我现在知道这一点，而且我耐心的等待着这一时刻。$B$B谢谢你，陌生人。”"
D.Strings[1870]="你，也必将臣服在我的脚下！"
D.Strings[1871]="又倒下了一个！"
D.Strings[1872]="你对<猪哼声>碎牙的帮助比我想象的要大得多，$r。$B$B谢谢你。$B$B只要我还是这里的俘虏，你就可以从刺背野猪人那里给我拿血岩碎片来换取阿迦玛甘的力量。"
D.Strings[1873]="%s心不在焉地瞄准兽人靶子……"
D.Strings[1874]="%s瞄准了瓶子……"
D.Strings[1875]="%s再次瞄准了瓶子……"
D.Strings[1876]="%s只击中了盒子的侧面！"
D.Strings[1877]="%s迅速瞄准目标的要害并射击……"
D.Strings[1878]="瑟银兄弟会是不会在蚂蚁身上浪费时间的。快滚开！"
D.Strings[1879]="对我这样的工匠来说，制造的流程本身是很简单的。$B$B困难之处在于获得原料。如果你能为我取回一块完美的比斯巨兽的皮，我就能用它制作出一些强大的装备。"
D.Strings[1880]="我估计获得这样一件东西的概率是百万分之一！一件让你终身受用的兽皮！即使是技艺最高超的工匠也不一定能剥出一张完美的皮来！"
D.Strings[1881]="要是你真的带来了那张皮？嗯……让我为你展示一番吧……"
D.Strings[1882]="%s转向纸人靶子……"
D.Strings[1883]="%s迅速射击兽人模型……"
D.Strings[1884]="%s冒冒失失地朝着瓶子射击……"
D.Strings[1885]="%s没击中……"
D.Strings[1886]="%s又没击中……"
D.Strings[1887]="%s击中了！"
D.Strings[1888]="瑟银兄弟会的目录：$B$B你可以从中找到所有你冒险必需的最强装备！我们还将告诉你到哪儿去收集这些材料。"
D.Strings[1889]="注意！准备战斗！"
D.Strings[1890]="提米！"
D.Strings[1891]="这本书的标题是手写体：莫琳·达尔松的日记。"
D.Strings[1892]="一本打开的日记放在你的面前，发黄的书页上写着如下的文字：$B$B“哈洛德变成了这个样子，我不知道接下来会发生什么事。把他拖进我能找到的唯一可以关住他的地方之后，我已经心力憔悴了。我把钥匙藏在身上，祈祷能渡过这个难关……$B$B我希望能离开这里，但我需要钱。我想我们的东西都在那个柜橱里……现在我想起来了，哈罗德是不是把柜橱的钥匙藏在自己身上了？$B$B我要先休息一下，现在我实在是太疲倦了。”"
D.Strings[1893]="你们不该来这里！杀了他们！"
D.Strings[1894]="死不足惜。"
D.Strings[1895]="谁敢打扰我的冥思？"
D.Strings[1896]="尘归尘，土归土。"
D.Strings[1897]="篡位者！诺莫瑞根是我的！"
D.Strings[1898]="我的机器代表未来！它们会将你们统统摧毁的！"
D.Strings[1899]="站着别动！"
D.Strings[1900]="爆炸！更多爆炸！我需要更多爆炸！"
D.Strings[1901]="兄弟们，杀了他们！为了亡灵天灾而战！"
D.Strings[1902]="我闻到活人的臭气！"
D.Strings[1903]="我要把你们统统吃掉！"
D.Strings[1904]="你不会从这儿活着出去的。"
D.Strings[1905]="小菜一碟。"
D.Strings[1906]="到我这儿来，仆从们！"
D.Strings[1907]="来吧，帮助你们的主人！"
D.Strings[1908]="我是巫妖王的得力助手！"
D.Strings[1909]="啊——给我来一次真正的挑战吧！"
D.Strings[1910]="圣光，赐予我力量吧！"
D.Strings[1911]="哈！你们就这点本事吗？"
D.Strings[1912]="圣光会审判你！"
D.Strings[1913]="你不能玷污这些神迹！"
D.Strings[1914]="让正义的火焰吞噬你吧！"
D.Strings[1915]="我们渴望复仇。"
D.Strings[1916]="愤怒的死者是永远不会安息的！"
D.Strings[1917]="更多的……更多的灵魂！"
D.Strings[1918]="告诉我……告诉我所有的事情！"
D.Strings[1919]="让痛苦来净化你吧！"
D.Strings[1920]="在我面前没有秘密可言！"
D.Strings[1921]="我要从你的肉体中把秘密都挖出来！"
D.Strings[1922]="那是什么， $n？$B$B<玛雷弗斯指着你从包裹里拿出来的未淬火的板甲护手。>"
D.Strings[1923]="以索瑞森胡子的名义！杀死他们！"
D.Strings[1924]="我，格瑞姆洛克，是国王！"
D.Strings[1925]="死吧！死吧！"
D.Strings[1926]="鲁莽的蠢货！"
D.Strings[1927]="夺灵者来了！"
D.Strings[1928]="哈卡会重生的！"
D.Strings[1929]="回去！不要唤醒沉睡者！"
D.Strings[1930]="流沙会吞噬你的！"
D.Strings[1931]="倒下吧！"
D.Strings[1932]="让裁决开始执行吧！"
D.Strings[1933]="正义得到了伸张！"
D.Strings[1934]="这片沙漠是属于我的！"
D.Strings[1935]="死吧，外来者！"
D.Strings[1936]="感受沙漠的狂怒吧！"
D.Strings[1937]="沙怒部族拥有至高无上的统治权！"
D.Strings[1938]="欢迎来到前线，$c。那些只知道策划阴谋的政客们会发现，他们的那一套在这里是行不通的。这儿是亡灵壁垒，我们必须日复一日地为生存而战斗。$B$B如果你想证明自己是个英雄的话，你会在这儿找到数不清的机遇。"
D.Strings[1939]="欢迎来到前线，$c。暴风城及其盟国派我到这儿来对抗亡灵天灾。在寒风营地，我们日复一日在抗战中求生。$B$B如果你想证明自己是个英雄的话，机会是很多的……特别是在我们向安多哈尔和控制亡灵天灾的邪恶势力进军时，你可以好好把握。"
D.Strings[1940]="我们被出卖了！"
D.Strings[1941]="很高兴看到又有人在斯坦索姆城中和亡灵天灾作战，在这里，亡灵的力量是极其强大的。$B$B$n，你好，我是奥里克斯。我曾经是白银之手骑士团的一名圣骑士，但是与其他信念发生动摇的圣骑士一样……我堕落了。亡灵天灾诱惑了我，差点使我成为一名死亡骑士！$B$B最终，我感觉到自己的危险处境，逃到了这个教堂。这是一个神圣的地方，第一圣骑士乌瑟尔·光明使者就是在这里成为了白银之手骑士团的首领。"
D.Strings[1942]="我的时间不多了，但是圣光依然照耀着这个世界，它可以帮助我完成我的宿命。当你面对瑞文戴尔男爵时，我便与你同在。"
D.Strings[1943]="别管我。我伤得很重，可能会丢掉性命。谢谢你，$n。我将死在这儿，但是因为你……我能在平静中死去。"
D.Strings[1944]="凡人，别考验我的耐性。"
D.Strings[1945]="你一定要原谅我，罗拉克斯，我没有“疯狂”地说什么。"
D.Strings[1946]="咬住你的舌头，$r，以免我把它拽下来用来擦拭我的犄角。"
D.Strings[1947]="很抱歉，我没有意识到你可以理解我说的话。你在这儿做什么？"
D.Strings[1948]="事实是我当然那样做。我思考。我哀悼。我痛恨。我谋划。当那个周期结束后，我又一次陷入沉思。你想从我这儿得到什么？我脑子里可有很多东西。"
D.Strings[1949]="是吗？或许你该告诉我是什么让你烦恼。"
D.Strings[1950]="你?$B$B<罗拉克斯笑了。>$B$B这很令人怀疑。$B$B我站在这些废墟和梦想之中。梦想着我捉住那个可怜的贼——古拉鲁克的那一天。$B$B我们达成了一项协议，他和我。但他违背了我们的协议。他背叛了我。"
D.Strings[1951]="什么交易？"
D.Strings[1952]="我将教他如何去恶魔熔炉交换他的灵魂。黑石兽人的灵魂根本不值钱，但是在眼下这个艰难时代，有总比没有好。"
D.Strings[1953]="他是怎么破坏协议的？"
D.Strings[1954]="他拿走了那块未铸造的符文胸甲，用于制造魔铸胸甲，并且没有付钱就跑掉了。我不是傻瓜，但是……没有配方的话，那块未铸造的符文胸甲一文不值。$B$B我在想……他是否安全地呆在黑石塔里，试图制造点什么出来？我知道他不敢离开！"
D.Strings[1955]="或许我能帮上忙。萨特，我们来谈笔交易吧。我去取回这块未铸造的胸甲并杀死野兽古拉鲁克。作为交换，你要教我如何制造胸甲。"
D.Strings[1956]="离开这儿！"
D.Strings[1957]="从我们呆在环形山这里开始，达丹加就喜欢上了遍布这里的巨大的血瓣花苗芽。$B$B我敢肯定她会喜欢，如果你愿意带给她一大堆花苗芽的话……"
D.Strings[1958]="嗨，只要我手头的物资能够再多一些，我就能立刻给你修理好！"
D.Strings[1959]="在这里志愿工作就是我通过巫医学校课程的方式。既然你帮了我，我就免费帮你。需要修理什么吗？"
D.Strings[1960]="情绪低落"
D.Strings[1961]="我……我受了重伤……"
D.Strings[1962]="听着，$r。听好了……$B$B龙骑士骑着黑龙，趁着夜色而来。他们迅速出击，给予幼龙——像我这样经验不足的幼龙——致命而精确的攻击。$B$B我怀着极大的恐惧注视着我的兄弟姐妹被他们用在实验中。我们的精华能创造出多彩龙人。"
D.Strings[1963]="奈法利安已经下令立即杀死那些不合适的实验品，但是这些恶心的野兽在没有对我们反复摧残之前是不会这样做的。$B$B当我们被彻底折磨完了之后，他们会将我们丢给那些杀手。我们的身体将成为他们游戏的道具：被投掷到熔岩中，或是丢弃到开阔地带，等待着被嗜血如命的军团砍杀。"
D.Strings[1964]="就在他们要把我扔给下面的魔鬼时你来了——为此我感谢你。或许，我——更确切的说——我们，蓝龙是不是可以进一步帮你？$B$B你已经走到这一步，$r，冒了很多险。你还愿去参加抵抗奈法利安和他的黑石军团的战斗吗？"
D.Strings[1965]="坏的悬钉"
D.Strings[1966]="感到动力不足"
D.Strings[1967]="丛林热"
D.Strings[1968]="独眉"
D.Strings[1969]="鞭打"
D.Strings[1970]="我不想回去工作"
D.Strings[1971]="如果你到这儿来猎龙，那你就是我的客人了。我应该去哪里表示我的哀悼？"
D.Strings[1972]="你的臭气会把数英里内的所有龙都招来的。告诉我你想要什么，快些。"
D.Strings[1973]="灵魂告诉我说你会来的，你会出于某种原因来此寻找我，但是你也许自己都不清楚这个原因。那么，你知道你为什么会在这儿吗？"
D.Strings[1974]="哦你好！我的名字是萨拉。我能为你做什么吗？"
D.Strings[1975]="森林告知我你的存在，但是没有说你为什么在这里。那么，告诉我真相吧。"
D.Strings[1976]="你做得怎么样啦！"
D.Strings[1977]="翡翠议会欢迎你，$n。$B$B希望我们能一起恢复并保护这片曾经繁茂的森林。许多势力试图从外部和……内部毁灭它。$B$B不要被这里的邪恶力量打败——它会腐蚀你，就它腐蚀这片土地一样。"
D.Strings[1978]="他在法师区，那儿有一间名叫炼金材料店的小商店。你会在前往法师区的沿途看到各种各样奇怪的商店，但是如果你沿着外围走的话，你一定会找到它的。"
D.Strings[1979]="暴风城的暴风城会计室位于城中贸易区的前门处。当你厌烦细数你的金钱时，一定要在镶金玫瑰喝一杯。"
D.Strings[1980]="你说你不能在这儿闻到矮人煅炉的烟味？哦，如果你想学习锻造的话就该找瑟鲁姆·深炉。他就在大教堂广场北边的矮人区。"
D.Strings[1981]="%s惊骇地跳起来！"
D.Strings[1982]="啊！！！"
D.Strings[1983]="你个尖酸的刻薄鬼！谁把这个给你的？"
D.Strings[1984]="是乌米，是吗？？她总是跟我开玩笑，现在也让你参与到玩笑之中了！"
D.Strings[1985]="%s叹了口气。"
D.Strings[1986]="啊！！！那是什么东西？！"
D.Strings[1987]="乌米派你来的，是吗？！她告诉我会有一个惊喜，但是我从没想到她是这个意思！"
D.Strings[1988]="有一名优秀的厨师在旧城区的猪与哨声旅店工作。我曾在他身旁看他在烹饪时使用刀具，但是我可不认为他只是一名厨师。别误会我的意思……如果你想学厨艺的话，他会是你最好的老师。"
D.Strings[1989]="啊，你是在找鲁坎·考迪尔。他在魔法区外开了一家商店，你前往监狱时会经过那儿的。"
D.Strings[1990]="嗨，提醒我啦，我需要修理一下火箭靴。聪明人一点就通啦，不要把火箭靴和狮鹫混淆的。\n\n哦，让我为你指明方向……穿过矮人区，你就会找到利廉姆·火轴啦。"
D.Strings[1991]="要学急救的话，没有比光明大教堂的安吉拉·雷菲德更好的老师了。\n\n去找她吧，你只寻找黄色的屋顶或者教堂本身的尖顶就行了，在城中的任何角落都能看到这些标志。"
D.Strings[1992]="啊呀！把那东西从我这儿拿走！"
D.Strings[1993]="那个游手好闲的利兰……他整天就在贸易区外的码头边钓鱼。他在钓鱼上花费这许多时间，我想他的钓鱼技术一定很高。如果你想学的话，为什么不去跟他谈谈呢？"
D.Strings[1994]="与自然的交流沟通是其他任何事情都无可比拟的……至少暗夜精灵是这么告诉我的。我并不擅长跟花草树木交谈，但是我想塔尼莎能帮助你。她居住在法师区外侧的炼金材料店。"
D.Strings[1995]="你为什么要追我，机械雪人？！为什么？！"
D.Strings[1996]="%s迅速从乌米的机械雪人面前逃跑。"
D.Strings[1997]="一个猎人？好的，那么你会想跟矮人区的索尔芬·石盾谈谈。\n\n哦，你一定要告诉他如果我再次介入他的宠物生意，他就可以去培训那些监牢里的猎人了！"
D.Strings[1998]="我总是战战兢兢……人们还在不断吓我……但是下次，我会有所准备的！"
D.Strings[1999]="你想要穿皮革对吗？听起来你该与旧城区的西蒙·坦纳尔谈谈。他在那儿开了一家叫做护体皮甲的商店。"
D.Strings[2000]="%s看上去很轻松。"
D.Strings[2001]="让矮人从铁炉堡指派一名采矿专家来教教我们吧。使用锄头打碎岩石有多困难？嗯，只要他在这儿，你就只管问他好了。他名叫吉尔曼，居住在矮人区。"
D.Strings[2002]="你知道，我可以刺穿一个兽人或是把一个巨魔切成碎片。我甚至可以把我名字的大写字母刻在食人魔的肚子上，但我就是不能忍受给动物剥皮。想一下都让我觉得恶心。\n\n好的，如果你有这种兴趣，那就到老城的护体皮甲找马瑞斯·格兰治。"
D.Strings[2003]="一个裁缝是吗？哦，如果你在这儿呆的时间够长你就会最终听到关于乔吉奥·波利罗的谈论。他现在已经领导潮流几个月了。如果你希望跟他学习，你能在法师区的外圈找到他。"
D.Strings[2004]="术士，嗯。我先前并未对你提及，但是我听说他们聚集在法师区中一间名为已宰的羔羊的酒吧中。"
D.Strings[2005]="%s到处乱跑，大声喊叫，制造骚乱。"
D.Strings[2006]="啊啊啊啊啊啊！"
D.Strings[2007]="你不喜欢骑狮鹫，嗯。你很幸运，我们有一个替代品可以让你稳稳地立在地上。那就是侏儒们的公共交通工具，矿道地铁。在矮人区的后面，非常方便。"
D.Strings[2008]="你听说地铁了是吗？那可真是一样不错的交通工具！你会在矮人区的后部找到它。哦，一定记得在地铁行进时把你的胳膊和腿放到地铁里面。"
D.Strings[2009]="是的，每个人都想坐矿道地铁去暴风城，那真是酷毙了。嗯，你可以去铁炉堡大门以东的侏儒区找矿道地铁。"
D.Strings[2010]="哦，地铁，地铁……每个人都想坐地铁去暴风城。那些乘坐狮鹫的好时光，那种在高空中飞翔时紧握缰绳的情景，它们到哪儿去了？\n\n啊！你还是坐地铁去吧……地铁就在侏儒区，那儿还有侏儒的其他精妙设计呢。"
D.Strings[2011]="你是问我铁匠在哪儿？你没听说过大熔炉吗？所有最好的铁匠都聚集在那儿铸造武器和护甲！\n\n在铁炉堡中心都是敲打铁器的声音，你能在那儿找到最出色的铁匠本古斯·深炉。"
D.Strings[2012]="哦！达瑞尔·瑞克努索是个技艺高超的厨师！他的红辣椒如此辛辣，几乎可以锻造钢铁了！我想他不会将菜谱传给你的，但是他肯定能帮助你成为一名好厨师。你可以在大熔炉东北角的铜壶铁罐那找到他。"
D.Strings[2013]="哦，你是在找宾斯匹德吧。为什么那个小侏儒和他的装备……让我告诉你吧，如果你想去他在侏儒区的商店，管好你的手，别去抚摸他的机械绵羊！\n\n爆炸绵羊……为什么你要做这样的事情！？"
D.Strings[2014]="急救？但你看起来不象受伤的样子。如果你真的对学习急救有兴趣，那么就去找尼莎·火石。到铁炉堡医师协会去，就在大熔炉旁边。"
D.Strings[2015]="我听格瑞诺尔说他曾经钓起过一柄剑。或者那是一条旗鱼？这该死的格瑞诺尔，他对我讲了太多的关于鱼的故事，我都分不清了。嗯，你干嘛不去荒弃的洞穴找他，让他告诉你那究竟是什么呢……"
D.Strings[2016]="要建立公会的话是需要相应文件的，乔多·钢眉能帮助你处理这些程序。如果你都准备好了的话，就去铁炉堡访客中心找他吧。"
D.Strings[2017]="你具有成为一名熟练猎人的潜质吗？嗯，$g年青人:姑娘;，时间会告诉我们一切的。在与军事区的雷格努斯交谈之前，别对着别人的眼睛射击。"
D.Strings[2018]="你确定不想做铁匠吗？嗯，如果你真心想学制皮，最好去大熔炉西北角找费布·钢轴谈谈。"
D.Strings[2019]="呸！邮箱……最近我收到的全都是垃圾邮件！\n\n增加这个的尺寸……减少那个的尺寸……现在是免费的屠龙剑。我得每隔一个月就要更改邮箱号码才行！\n\n嗯，你可别说我没警告过你。邮箱就在石火旅店外面。"
D.Strings[2020]="嗯！说到学习采矿的话，你来对地方啦，$g小伙子:姑娘;！吉尔弗拉姆·石趾居住在深山珠宝矿业协会。没有比他更好的老师了。"
D.Strings[2021]="书中说很多条龙联合起来对付一条极其强大的、名为死亡之翼的龙。按照我们掌握的信息，多彩龙人差不多全部释放。守护者已经准备就绪。"
D.Strings[2022]="啊，没有谁比牧师更擅长治疗病痛了。当然喝得酩酊大醉也能解除痛苦，但是我想布莱纳·火崖并不懂得酿酒。我认为你该在神秘大厅进行一些牧师的培训。"
D.Strings[2023]="你或许不知道，除了是一个娴熟的裁缝之外，约莫德还是一个巨人杀手！为什么说当他大喊他一拳打死了七个的时候可以断定他一定偷听到我们在一起讲的东西！\n\n你应该到大熔炉北面他的店铺去拜访他一下，并看看他是否会在跟你讲他的传奇故事！"
D.Strings[2024]="剥皮？能不能学成只有看你自己了！哈哈！你为什么不去找巴尔萨斯·裂石呢，他能教你如何剥皮。他在大熔炉北面的皮甲用品店。"
D.Strings[2025]="一个术士，嗯……好吧，如果你想在附近继续做那种事情，你最好管好你的恶魔，$g小伙子:姑娘;。我不喜欢恶魔，但是我喜欢杀死他们。你明白我的话了吗？\n\n现在你不要再烦我了，马上消失去荒弃的洞穴。你会在那里找到那个术士，瑟斯哈特。"
D.Strings[2026]="克斯塔姆是个大嗓门、爱吹嘘的人……他也是你所能见到的技艺最为纯熟的战士之一！\n\n我告诉你，如果你想成为一名战士的话，就去找他谈谈吧。他肯定在铁炉堡大门以东的军事区中。"
D.Strings[2027]="炼金师？这没什么$c。安尼希尔通过不懈地努力，成为了工匠区技艺最纯熟的炼金术士。如果我是你的话，我会马上赶去那儿的。马上！出发吧！"
D.Strings[2028]="身上又多了一种材料$g小伙子:姑娘;，是吧？嗯，如果你携带的物品过多的话，可以将它们存储在城中心的达纳苏斯银行中。"
D.Strings[2029]="阿斯坦娅在她经常垂钓的地方钓起了一些古怪的财宝。去贸易区找她吧，让她给你看看。"
D.Strings[2030]="琳沙娜能为你提供所需要的文档，她居住在达纳苏斯东北部的工匠区。愿你的伙伴为暗夜精灵带来无比的荣耀吧！"
D.Strings[2031]="你要找的是维斯派塔斯。他负责看管在泰达希尔底部往返的角鹰兽。你可在穿过达纳苏斯西部的传送门，然后在鲁瑟兰村那儿找到他。"
D.Strings[2032]="祖卡斯特是她那个时代最伟大的猎人。最近，她在塞纳里奥区教那些猎人初学者。"
D.Strings[2033]="太阳已经升起来了吗？夜晚的时间总是太短！嗯，塞琳尼会好好照顾你的。她在达纳苏斯东北面的工匠区招待客人。"
D.Strings[2034]="一个邮筒？你要发信，或者也许你要收一封信？我希望是个好消息！在达那苏斯中心银行外面就有一个邮箱。"
D.Strings[2035]="不随意浪费东西是我们的传统文化。当我们不得不杀死某种生物时，我们会加以利用，不让它白白丧命。\n\n要是你想学习剥皮的话，就去工匠区找艾拉迪尔吧。"
D.Strings[2036]="穿着迈里恩缝制的衣服，人们可能会以为她的绣花针是被月神赐福过的。除非你的针也受过同样的祝福，否则你最好去拜访她一次并聆听她的教导。你可以在达纳苏斯东北方的工匠区找到她。"
D.Strings[2037]="希达奈尔训练出许多卫戍，他们守卫着我们心爱的城市。我相信她会使你成为一名战士的。去城门附近的战士区找她吧。"
D.Strings[2038]="贸易区刚刚开放了一座拍卖行。如果你沿着银行东南方的路走，很容易就能找到贸易区。"
D.Strings[2039]="哦，沉迷于物质财富，这很常见呢。呃，去贸易区的拍卖行吧，财富在对你微笑。"
D.Strings[2040]="又一个想要靠倒买倒卖发家的？拍卖所就在贸易区，离银行不远的地方。"
D.Strings[2041]="所有参与作战的人都各就各位！纳迦来了！"
D.Strings[2042]="旅行者，你好。很少有人以这种方式找到我。$B$B我叫雷沃，我在冬泉谷驯化这些霜刃豹，使它们成为坐骑。$B$B这些猫科动物非常凶猛，极难驯服。只有那些最值得信赖和最受人尊敬的人才可能骑上它们。$B$B我是不会随意出售这样的坐骑的，你必须用行动来证明，让我和霜刃豹都接受你。"
D.Strings[2043]="假设存在这种东西。只有体型更大的多彩飞龙才可能具有这样的外壳。"
D.Strings[2044]="通常在较小的多彩飞龙身上找到：幼龙，龙崽，较小的龙人。"
D.Strings[2045]="传说在战事极度激烈的地方，在现今被称为瘟疫之地的土地上；地表也许会涌出洁净而神圣的温泉。这些泉水被人们命名为‘英雄之血’——以纪念那些在对抗亡灵天灾的战争中牺牲的勇士。"
D.Strings[2046]="通灵学院的巴罗夫家族将它作为照耀他们不复存在的灵魂的镜子。那是一件贵重的纪念品。"
D.Strings[2047]="啊，镶金玫瑰？那柔软的床铺和温水沐浴……想想这一切吧。::打哈欠::如果你要前往那儿的话，你可真幸运。旅馆就在贸易区的西边……柔软的枕头、温暖的毛毯。::打哈欠::"
D.Strings[2048]="你好！我刚刚探索凯斯利尔废墟回来，就在西南方。现在我决定调查在这个山脉之上的枭兽，在枭翼树丛内。$B$B你与鲁瑟兰村的艾瑞拉斯·琥珀谈过话了吗？他要求我来这里，或许他还有任务给你。"
D.Strings[2049]="你见过守夜人巴库斯吗？很勇敢……$B$B我想他是所有守夜人中最凶猛的一个。我怀疑他是否看到我就在周围……"
D.Strings[2050]="想找这些？？？？你永远都不可能得到它们的！"
D.Strings[2051]="我要把你的皮当作便服来穿！长靴呢？你得将它们从那儿撬下来！！！！"
D.Strings[2052]="谢谢你！你让我自由了！"
D.Strings[2053]="哦，谢谢你！我已经深陷恶梦多时了……"
D.Strings[2054]="我的灵魂终于自由了。"
D.Strings[2055]="谢谢你！我注定会在达隆郡之战中身亡，但是你让我获得了自由！"
D.Strings[2056]="啊！如果你见到一个达隆郡的幸存者，请告诉他们我自由了！"
D.Strings[2057]="翡翠议会试图治愈费伍德森林受伤的大地。尽管这片大地是以腐蚀它的东西命名，我们还是希望有一天我们能从这片土地中将腐败清除。"
D.Strings[2058]="你好，$c。我是杰希尔·月弓。我从达纳苏斯来寻找两个朋友，他们是来寻找费伍德森林暗影议会的踪迹的。$B$B看起来那些宣称对兽人种族的苦难负大部分责任的卑鄙的生物正试图重获一些能量。$B$B我的两个朋友进入加德纳尔搜寻证据来证明有事情发生。$B$B我希望我来时他们在这里，但是他们已经晚了数天了。"
D.Strings[2059]="你好，勇敢的$c！我有世界上最训练有素的狼供你挑选。你到哪里都不会发现能与狼拥有同样的耐力和生存本能的动物！你亲自来看看它们吧。"
D.Strings[2060]="祝你好运，勇敢的$c。我知道你在寻找一匹好战马。告诉你吧$g兄弟:姐妹;，在你所在的区域没有什么比迅猛龙更好的坐骑了！看看我的这些迅猛龙吧——他们的祖先曾经是极其凶猛的野兽。"
D.Strings[2061]="自由了！！！"
D.Strings[2062]="诅咒结束了！"
D.Strings[2063]="赞美埃根！"
D.Strings[2064]="总有一天我们会对克尔苏加德进行报复的。"
D.Strings[2065]="瑞文戴尔必须死！"
D.Strings[2066]="他们将尸体交给了我，他将尸体投进了深坑。"
D.Strings[2067]="我想买些东西。"
D.Strings[2068]="别把邮件给弄乱了！"
D.Strings[2069]="你好，$n。我是米洛尔·怒斩，大熔炉的看守者。"
D.Strings[2070]="你在锻造方面的技术已经非常高超了，$n。该做出决定了。有两条路你可以选择：武器制造工匠或是装甲制造工匠。$B$B注意，当你做出决定以后，就不能回头了。每个方向的守则都不允许你三心二意。"
D.Strings[2071]="时机成熟了，我的$g兄弟:姐妹;们，武装起来，从亡灵天灾手中夺回属于我们的夜晚！"
D.Strings[2072]="承蒙月神的关照，我很高兴给你在整个泰达希尔找到的最好——甚至是这世上最好的坐骑，它们就是夜刃豹。数年来，哨兵部队一直倚赖这些同伴的价值。$B$B抓紧时间，朋友，挑选一匹你满意的。我敢肯定你不会失望的。"
D.Strings[2073]="如果你是为获得快速而安全的产品而来，那么这儿就是你的目的地了！今年的机械陆行鸟模型已经到了，我将为你展示其性能！"
D.Strings[2074]="当一个铁匠达到了你这样的专业水平的时候，我会提供给他们一个选择。$B$B虽然我并没有要求你必须做出选择，但我建议你最好还是做出抉择——毕竟，你想永远当一名新手吗？是大师级的铸甲师和武器铸造师给我们的军队提供补给，让我们赢得战争的胜利并获得荣耀！$B$B注意，$n，一旦你做出了决定并完成了指定的任务，就没有回头路了。一个人只能沿一条路走到底。"
D.Strings[2075]="我是克拉索克，这些工匠的监工。"
D.Strings[2076]="嗨，$c！"
D.Strings[2077]="我要接受训练。"
D.Strings[2078]="愿圣光与你同在，$c。我能帮上忙吗？"
D.Strings[2079]="一场猛烈的风就要来了——我可以通过我裸露膝盖的疼痛判断出来。我就是希望我们不要被狂风困住。"
D.Strings[2080]="费尔斯通农场的天灾之锅都需要什么？"
D.Strings[2081]="达尔松之泪的天灾之锅都需要什么？"
D.Strings[2082]="嚎哭鬼屋的天灾之锅都需要什么？"
D.Strings[2083]="盖罗恩农场的天灾之锅都需要什么？"
D.Strings[2084]="根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、六份骨质分离素和四块符文布。你可以使用玻璃放大镜从瘟疫之地的骸骨亡灵身上获取骨质分离素！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。"
D.Strings[2085]="根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、五份细胞增强剂和四块符文布。你可以使用玻璃放大镜从瘟疫之地的僵尸或食尸鬼身上获取细胞增强剂！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。"
D.Strings[2086]="根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、四份外膜震荡体和四块符文布。你可以使用玻璃放大镜从瘟疫之地的鬼魂或怨灵身上获取外膜震荡体！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。"
D.Strings[2087]="这份工作明显不值16500的年薪。"
D.Strings[2088]="好吧，$n，让我们来看看怎么对付这些天灾之锅！如果你要收集所需的成分，就带上一个玻璃聚焦装置吧。在鉴别从亡灵天灾的爪牙身上获取的资源时，你会用得着它的。$B$B你还需要找一份奥术催化剂。这东西可不便宜，而且也非常不稳定。一旦你得到药剂，就必须在15分钟内使用它，否则药剂就失效了。所以你可得留神别乱买。"
D.Strings[2089]="你已经被玛罗恩搞定了！"
D.Strings[2090]="我需要玻璃放大镜。"
D.Strings[2091]="复活吧，我的勇士！"
D.Strings[2092]="光明之刃！"
D.Strings[2093]="发泄你的愤怒吧！"
D.Strings[2094]="醒来吧！我的奴仆！保护圆盘！"
D.Strings[2095]="兄弟们，到我这儿来！为创世者而战！"
D.Strings[2096]="加入我们吧！"
D.Strings[2097]="嘘……你闻到什么了吗？"
D.Strings[2098]="利拉迪斯一直在梅伊瑟娜岗哨等我，我们得快些，$n。"
D.Strings[2099]="%s开始打瞌睡……"
D.Strings[2100]="%s在不经意间睡着了。"
D.Strings[2101]="嗷……"
D.Strings[2102]="哦，我太累了……"
D.Strings[2103]="如果我在这里稍微呆一会儿，你不会介意吧？"
D.Strings[2104]="亡灵天灾带来的灾难还在这片区域蔓延，在扭转局面，摧毁亡灵天灾之前，我们要走的路还很长。收集必要的资源，尽力帮助我们吧！"
D.Strings[2105]="亡灵天灾带来的灾难就快结束；一场难以控制的颠覆行动会将我们推向顶峰！你务必要帮助我们！"
D.Strings[2106]="我们已经开始反攻亡灵天灾了，但是我们撑不了多久了！去摧毁他们的锅炉吧！"
D.Strings[2107]="我们正控制着亡灵天灾——至少还会侵扰它们一整天时间！但是我们得对此有足够的把握，因此你要尽可能地破坏锅炉。"
D.Strings[2108]="猎人训练者名叫索塔尔。去剃刀岭西南部的洞穴中找他吧。"
D.Strings[2109]="你是个猎人？你会发现索塔尔为了躲避太阳就藏在城镇西南角上的洞穴里。"
D.Strings[2110]="去南方的森金村，找安苏瓦谈谈。"
D.Strings[2111]="那是巨魔的事儿。去南方的森金村找安苏瓦。"
D.Strings[2112]="你应该是在寻找泰金。在城镇东面的兵营里可以找到她。"
D.Strings[2113]="她名叫泰金，你可以在剃刀岭东面的兵营中找到她。她会教你如何尊敬神灵的。作为回报，你必须向她表示尊重。"
D.Strings[2114]="到村庄西南方的洞穴顶部找到卡普拉克。"
D.Strings[2115]="你为什么想找卡普拉克谈谈？没关系。到剃刀岭西南角的洞穴顶部找他。不过你一定不要把手放错地方！"
D.Strings[2116]="你应该去找斯瓦特。到剃刀岭东边的兵营里找找看。"
D.Strings[2117]="酋长进行的变革将帮助部落取得胜利！去城镇东边的兵营找斯瓦特吧。"
D.Strings[2118]="你能在剃刀岭东面的兵营后找到杜格鲁·血怒。"
D.Strings[2119]="杜格鲁·血怒在城镇东边的兵营后面。不要让我发觉你跟燃烧军团是一伙的！"
D.Strings[2120]="去城镇东面的兵营找塔绍尔·锯痕。"
D.Strings[2121]="到剃刀岭东面的兵营里找到塔绍尔·锯痕。给部落的年轻人带去骄傲和荣誉！"
D.Strings[2122]="去南方的森金村找米奥赞。"
D.Strings[2123]="我听说森金村的巨魔中有个名叫米奥赞的药剂师。去那儿找他吧。"
D.Strings[2124]="那是杜克。去城镇西北角炙热的熔炉附近找他。"
D.Strings[2125]="沿着北边的道路去奥格瑞玛。你可以问问那儿的守卫烹饪训练师在哪儿。"
D.Strings[2126]="嗯……食物。旅途并不遥远，你需要朝北走，去奥格瑞玛，问问那儿的守卫。"
D.Strings[2127]="在奥格瑞玛有你要找的人。那儿的守卫会为你指明方向的。朝着北方的道路走，应该不会错过的。"
D.Strings[2128]="据我所知，附近没有这些训练师。你最好去北方的奥格瑞玛看看，去问问那儿的守卫。"
D.Strings[2129]="在剃刀岭居住着一名工程学训练师。他名叫穆德拉克，你在熔炉附近就能找到他。"
D.Strings[2130]="呸，那是地精的东西！在剃刀岭有一个兽人可以教你如何制作这些物品。去熔炉附近找穆德拉克吧。"
D.Strings[2131]="拉乌克就在剃刀岭东边的兵营中。"
D.Strings[2132]="因为我们经常战斗，我们当然有一个急救训练师在剃刀岭。在城镇东面的兵营里可以找到拉乌克。"
D.Strings[2133]="我曾见到一个名叫劳迪克的巨魔在暗矛海滩南部钓鱼，就在森金村的外围。"
D.Strings[2134]="你在寻找劳迪克。你会在南面的森金村外的暗矛海滩找到他。"
D.Strings[2135]="你在寻找米什基。她在森金村南面有一间小屋。"
D.Strings[2136]="花？在这片荒芜的土地上？如果有人能教你如何找到它们，那就是南方的森金村的米什基。"
D.Strings[2137]="水之精灵，我赞美你，还有我想请你帮个忙。你听到$n的请求了，而我相信$g他的:她的;用意是高尚的。你愿意帮助我们吗？"
D.Strings[2138]="为此你需要到奥格瑞玛去。只需沿着从剃刀岭出去的路穿过峡谷就会到达那里。到了那里,你可以问问步兵以得到进一步的指引。"
D.Strings[2139]="要学习如何处理皮革，你得去北面的奥格瑞玛。那儿的守卫会告诉你如何找到制皮训练师的。"
D.Strings[2140]="当然，当然。城镇中有一名采矿训练师。在旅馆旁西北角可以找到克鲁恩。"
D.Strings[2141]="我听说杜隆塔尔的采矿业极为发达。我们在剃刀岭有一个采矿训练师，你可以去城镇西北角的大熔炉附近寻找克鲁恩。"
D.Strings[2142]="在奥格瑞玛有一名剥皮训练者。出了剃刀岭往北走，当你到达奥格瑞玛时问问那儿的守卫，他们会为你指明方向的。"
D.Strings[2143]="在奥格瑞玛有你要找的人。朝着北方走，跟那儿的守卫谈谈。"
D.Strings[2144]="你得去奥格瑞玛。出了剃刀岭沿着北面的道路走，就能到那儿了。跟那儿的守卫谈谈，他们会给你指明方向的。"
D.Strings[2145]="你可以试着在奥格瑞玛解决你的问题，就在这里的北方。或许某个奥格瑞玛步兵可以帮你。"
D.Strings[2146]="呃？你可以在奥格瑞玛找到银行。沿着道路往北走，跟那儿的守卫谈谈。"
D.Strings[2147]="是的，我自己也需要放置一些东西。要找到它你需要向北沿着去奥格瑞玛的路一直走，然后找那里的步兵询问一下。"
D.Strings[2148]="你会在奥格瑞玛找到双足飞龙管理员的。沿着公路向北走到那里去，并向一个奥格瑞玛步兵询问更多指示。"
D.Strings[2149]="你没看到我很忙吗?沿着路向北走到奥格瑞玛并询问那里的步兵。你不会错过的。"
D.Strings[2150]="谢谢你，伟大的精灵。谢谢你！"
D.Strings[2151]="我可以喝点东西，稍事休息。到剃刀岭西北角，替我向旅店管理人罗斯克问声好。"
D.Strings[2152]="那是剃刀岭的一幢大建筑，而不是兵营。去跟旅店老板格罗斯克谈谈。明白了？"
D.Strings[2153]="%s醒来了！"
D.Strings[2154]="因为大熔炉被打开了缺口，我们现在能够把反作用剂释放到外界。这应该能让亡灵天灾尝尝他们自己药物的滋味，可以这么说！$B$B向炼金师阿尔比顿询问一下有关在大熔炉中所需要使用的试剂这方面的信息。我会处理所有的信息报告，以便于我们决定怎样把瘟疫用来对付亡灵天灾！"
D.Strings[2155]="因为大熔炉被打开了缺口，我们现在能够把反作用剂释放到外界。这应该能让亡灵天灾尝尝他们自己药物的滋味，可以这么说！$B$B向炼金师迪瑟斯询问一下有关在大熔炉中所需要使用的试剂这方面的信息。我会处理所有的信息报告，以便于我们决定怎样把瘟疫用来对付亡灵天灾！"
D.Strings[2156]="哦，我能从这儿看见利拉迪斯……告诉她我在这儿，好吗？"
D.Strings[2157]="你好，年轻的$g主人:女主人;。我是艾瓦·萨克霍夫，这是我的丈夫卢森。很高兴认识你。"
D.Strings[2158]="我也很高兴遇见你们，女士。我能问问你在这儿干什么吗？"
D.Strings[2159]="当然，$g先生:小姐;。我们曾是巴罗夫家里的仆人：现在那里被称作通灵学院。$B$B我那时是女仆的领班而卢森是主人巴罗夫的男管家。$B$B我们为巴罗夫家族工作了数十年，直到……$B$B<艾瓦哭了。>"
D.Strings[2160]="直到什么时候，艾瓦？我必须知道这一点。"
D.Strings[2161]="啊，真是太可怕了，$g先生:小姐;。巴罗夫家族从前充满生机……充满活力。这个庄园是巴罗夫家族主要的住所。$B$B卢森和我注意到随着时间的流逝，巴罗夫家族变得低沉而沮丧。偏执妄想和暴怒笼罩着主人和小姐。在夜里，我们可以听到巴罗夫夫妇在卧房里争吵。根据我们了解，他们的贪婪毁了他们，可以这么说。"
D.Strings[2162]="我们猜想，巴罗夫家族为了保护自己的财宝以及生前死后对土地的所有权，他们与一个名叫克尔苏加德的人类法师达成协议，克尔苏加德拥有强大的法力。$B$B<艾瓦战栗起来。>$B$B协议中提及了通灵学院……这里将成为诅咒神教的地盘，变成他们的首府。$B$B随着时间的推移，巴罗夫家族变得渐渐衰老……甚至扭曲。$B$B黑暗开始笼罩整个家族……"
D.Strings[2163]="你们为什么不离开？"
D.Strings[2164]="去哪里？我们过去、现在和将来所知道的全部就是这些。$B$B最终，我们与巴罗夫失去了联系，并从房子里被赶了出来。我们不知道其他仆人出了什么事，只听到有尖叫声,痛苦的尖叫声。$B$B知道我们无路可逃，卢森和我被迫藏在了我们的住处。在白天，当学校相对安静时，卢森会溜出去弄点食物和喝的东西。"
D.Strings[2165]="我们这样持续了六个月，看到房屋经历了令人恐惧的变化。肮脏的怪物随意在庄园里漫游。随身携带着各种与仪式和祭祀相关的用具的黑暗信徒遍布在每一寸地方。我们知道我们躲不了多久了。$B$B正如所料想的那样，我们被发现并抓住了。他们剥掉了我们所有的衣服并把我们放到一滩鲜血中。我们坐在那里长达数天，赤身裸体，胆战心惊。"
D.Strings[2166]="没有任何限制？就在一圈鲜血之中？"
D.Strings[2167]="限制？这世上有些东西比栅栏和镣铐更加能够限制住人，年轻的$g主人:女主人;。亡灵包围着我们，不断恐吓我们。$B$B最终，他来了。他自我介绍叫瑟尔林·卡斯迪诺夫教授。我们都把他叫做“屠夫。”"
D.Strings[2168]="我们最后弄清喊声从哪里传来的了。屠夫让我们见识到闻所未闻的痛苦。他把我们用于无数试验中，试图研制瘟疫菌。$B$B日子过去了数星期。要不是那个残忍的混蛋用法术维系着我们的生命，我们熬不过第一天的。"
D.Strings[2169]="这真是残忍的行径。"
D.Strings[2170]="屠夫说起“无辜者的鲜血”和他的黑暗主人，“基尔图诺斯”。以及他会如何满足他主人的欲望。$B$B最后，这个怪兽完成了他的实验。我们被耗干了生命。我们的灵魂被打碎了。死亡的甜美的拥抱靠近了，我们张开双臂欢迎它。但是在他极端的残酷中，屠夫把我们从死亡之门中复活。$B$B我们要被活着扔进他贪婪的食尸鬼之中。他笑着看我们被魔鬼吞噬。"
D.Strings[2171]="我感到有些恶心。"
D.Strings[2172]="我们什么都没感觉到。我们的灵魂在这里，在地狱。在找到我们的尸体并让灵魂安息之前我们不能离开。"
D.Strings[2173]="啊，你必须去雷霆崖最高处拜访他们中的一人。沿着血蹄村北面的道路走。雷霆崖底有升降梯可达顶部。当你到达那儿时，可以询问雷霆崖守卫。"
D.Strings[2174]="村子里可没这样的地方，在高高的雷霆崖上应该有。出了血蹄村沿着北面的道路走，乘坐雷霆崖升降梯到达顶部，找那儿的守卫谈谈。愿你的祖先保佑你。"
D.Strings[2175]="在北方的雷霆崖，有一名双足飞龙管理员。乘坐升降梯到达雷霆崖顶部，问问那儿的守卫，他们会为你指明方向的。"
D.Strings[2176]="只有在天空自由翱翔时，灵魂才能得到真正的解脱。在我们伟大的部落中心雷霆崖就有这样一块地方。血蹄村外以北的道路就通往那儿。一旦你乘坐升降梯到达高处，就找雷霆崖守卫谈谈，他会做出进一步的指引。"
D.Strings[2177]="旅店老板考乌斯可以满足你的需求。你可以在村子西边的屋子中找到他。"
D.Strings[2178]="人总是要休息的。在血蹄村的西边，旅店老板考乌斯经营着一家很大的旅馆，为人们提供休息之所。你去那儿找他吧。"
D.Strings[2179]="你应该去听听根妮亚·符文图腾的忠告。她在村子东面的大营帐中。"
D.Strings[2180]="德鲁伊的生活方式跟萨满相差无几。根妮亚·符文图腾正在对此进行研究。去血蹄村东面的大营帐中找她吧。"
D.Strings[2181]="雅文·刺鬃在村庄北面等你。他能教你猎人之道。"
D.Strings[2182]="在大地之母心目中，学习如何与自然融合一体是件荣耀的事儿。如果你想成为一名猎人，你必须去血蹄村北部找雅文·刺鬃。"
D.Strings[2183]="在血蹄村的东边，有一座巨大的营帐。纳姆·逐星在那儿等着你呢。"
D.Strings[2184]="村子里居住着一位名叫纳姆·逐星的智者。他能继续训练你，使你成为一名真正的萨满。"
D.Strings[2185]="克朗·石蹄在村子东南角的训练圈里。"
D.Strings[2186]="要是你想成为一名战士，就得去找克朗·石蹄。你能在村子的东南角找到他，他通常就在那儿训练学生。"
D.Strings[2187]="虽然我们在血蹄村没有炼金术训练师，在北面的雷霆崖却有一位。沿着这条路去那儿，当你到达顶部时再向一位雷霆崖守卫询问具体方位。"
D.Strings[2188]="用大地之母的果实配制药水来帮助我们进行持久抗争是一件光荣的行为。如果你想学习配制药水，就得去北方的雷霆崖。当你到达雷霆崖顶部时，去问问那儿的守卫，他们会给你详细的指引的。"
D.Strings[2189]="在我的家乡雷霆崖，有一位铁匠训练者。如果你想成为一名铁匠的话，就朝北走，去雷霆崖，然后问问那儿的守卫吧。"
D.Strings[2190]="你希望把大地母亲的骨头设计成可以帮助部落的工具。好的，好的。沿着北边的路走出血蹄村直到一部可以上到雷霆崖顶部的升降梯那里。那里的守卫可以给你更多帮助。"
D.Strings[2191]="你可以在村庄西北角的大帐篷里找到派尔·沉默行者。他可以教给你你想要的。"
D.Strings[2192]="只是想想那美味，我就已经垂涎三尺了。派尔·沉默行者是血蹄村最好的厨师。你可以在村子西北角的大营帐里找到他。"
D.Strings[2193]="去北面的雷霆崖吧，从那儿开始你的旅程，朋友。一旦你到达雷霆崖，那儿的守卫会直接告诉你你要找的东西在哪儿。"
D.Strings[2194]="只有在雷霆崖上的神秘之地才能找到这样的智者。沿着血蹄村北面的道路一直走，直到你来到雷霆崖底的升降梯。乘坐升降梯到达顶端，询问雷霆崖守卫，您能获取到更多的帮助。"
D.Strings[2195]="维尔拉·幼蹄在村子西边的房子中进行训练。"
D.Strings[2196]="绷带、抗毒药品这些东西在草原生活中是不可缺少的必需品。维尔拉·幼蹄能教你如何制作它们。你可以在血蹄村西边的房子中找到她。"
D.Strings[2197]="你在寻找尤萨恩·静水。你可以在村子的西面找到他，他就在石牛湖钓鱼。"
D.Strings[2198]="授人以鱼不如授人以渔。尤萨恩·静水会教你如何钓鱼。到石牛湖岸边的血蹄村寻找他的智慧所在。"
D.Strings[2199]="要是你想学习草药学，就必须去雷霆崖。出了血蹄村，沿着北边的路走，然后乘坐升降梯到达山顶。你可以问问雷霆崖的守卫获取帮助。"
D.Strings[2200]="在北方的雷霆崖，你能学到草药学。沿着村外的道路走，乘坐雷霆崖升降梯到达顶部。那儿的守卫能为你指明方向。"
D.Strings[2201]="查尔·硬皮居住在村子西北角的大帐篷中。他能教你一些制皮的必要知识。"
D.Strings[2202]="当我们使用动物的皮革时我们必须热爱食物或带给我们的保护，我们给大地母亲以荣誉并尊敬动物。查尔·硬皮会教给你这些事情。你可以在血蹄村西北角的大帐篷找到他。"
D.Strings[2203]="嗯，我觉得你需要到雷霆崖去弄清楚。出了血蹄村沿着公路一直往北走。你会到达雷霆崖的底部。乘升降梯到顶部你就可以向雷霆崖的任何一个守卫寻求进一步的帮助。"
D.Strings[2204]="我听说北方的雷霆崖有个矿工训练师。沿着村外的道路前进，然后乘坐升降梯到达山顶。任何一名雷霆崖守卫都能帮助你。"
D.Strings[2205]="你可以在血蹄村西北角的大帐篷里找到姚恩·深刺。"
D.Strings[2206]="啊,是的，剥皮。没有人比姚恩·深刺还善于运用剥皮刀了。你可以在村庄西北角的大帐篷找到他。"
D.Strings[2207]="不幸的是，血蹄村中没人懂得裁缝技能，但是你可以在雷霆崖找到训练师。出了村子，沿着北面的道路走。乘坐雷霆崖升降梯到达顶部，然后问问那儿的守卫，他们会为你指明方向的。"
D.Strings[2208]="你是说裁缝？嗯。是的，当然。你得去正北方的雷霆崖。沿着村外的道路走。到达雷霆崖底后，乘坐升降梯去雷霆崖顶部，跟那儿的守卫谈谈。"
D.Strings[2209]="双足飞龙管理员"
D.Strings[2210]="布瑞尔镇没有银行，你得去幽暗城找找。在南方的洛丹伦废墟后面的升降梯能带你去幽暗城。你可以问问幽暗城守卫，他们会为你指明方向的。"
D.Strings[2211]="你需要银行做什么？好吧，你得穿越布瑞尔南部的洛丹伦废墟，乘坐升降梯到达幽暗城。当你到达那儿后，询问自称为幽暗城守卫的行动缓慢的憎恶，请求它给予更详细的指示。"
D.Strings[2212]="在幽暗城中居住着一位蝙蝠管理员。出了布瑞尔城朝南走，然后在丁字路口向西走。洛丹伦废墟就在你的右边，穿过废墟，然后进入幽暗城。你可以问问那儿的守卫，请求他们的帮助。"
D.Strings[2213]="想飞往某处？你得去幽暗城才行！沿着城镇南面的道路走，然后往西南方前进，到达洛丹伦废墟。你可以乘坐废墟后面的升降梯到幽暗城，问问幽暗城守卫，获取更详细的指示。"
D.Strings[2214]="你可以在穿过城镇的道路东南端的恐惧之末旅店里面找到旅店老板瑞尼。"
D.Strings[2215]="如果我是旅店老板瑞尼的话，我可能在哪儿？嗯？哦，也许在恐惧之末旅店中。是的，是那儿，我敢肯定。试着去布瑞尔的东南角……你认为自己能找到他吗？"
D.Strings[2216]="你可以在恐惧之末旅店楼上的平台找到法师训练师凯恩·火歌的，恐惧之末旅店就在布瑞尔的东南端。我猜你现在去的话有点晚了，他不会再登记给你房间了。"
D.Strings[2217]="你看我像个会施魔法的人吗？嗯，我确实听说 凯恩·火歌居住在城镇东南部的恐惧之末旅店的楼上。他那样站在格雷彻的房间之外可真奇怪。"
D.Strings[2218]="去镇子东南角的恐惧之末旅店，你可以在旅店楼上的阅览室中找到黑暗牧师贝里尔的。"
D.Strings[2219]="啊，你是在找黑暗牧师贝里尔。他在恐惧之末旅店楼上的阅读室。他一直在阅读、祷告，没人知道他在干嘛，也谁敢去问他啊？"
D.Strings[2220]="潜行者训练者名叫马里恩·考尔。她在城镇东南角的恐惧之末旅店的阅览室中。"
D.Strings[2221]="马里恩·考尔和黑暗牧师贝里尔一起在布瑞尔镇东南角恐惧之末旅店楼上的阅览室中。我只是想看看谁是这场对抗的胜利者。"
D.Strings[2222]="他名叫鲁伯特·鲍什。我听说他在城镇东南角的恐惧之末旅店楼上的某间房间里。"
D.Strings[2223]="你要找的是鲁伯特·鲍什。他和他的随从居住在布瑞尔东南角恐惧之末旅店的楼上。"
D.Strings[2224]="去恐惧之末旅店的主餐厅找奥斯蒂尔·德·蒙。酒馆就在布瑞尔城的东南角。"
D.Strings[2225]="是的，你应该去找奥斯蒂尔·德·蒙。他总住在城镇东南端的客栈里。它叫做恐惧之末旅店，你不会错过的。"
D.Strings[2226]="我们的炼金师名叫卡罗莱·安尼斯。她居住在布瑞尔镇西北角的房屋中。"
D.Strings[2227]="你会在城镇西北端发现卡罗莱·安尼斯正试图炸掉她的房屋。为什么你不去看看你能否帮她？"
D.Strings[2228]="很抱歉，朋友，在布瑞尔没有你想要的东西。你得前往幽暗城。幽暗城位于布瑞尔以南的洛丹伦废墟下。在废墟后面搭乘升降梯即可到达，去问问幽暗城守卫，他会为你指明方向的。"
D.Strings[2229]="铁匠？不，我们最后一名铁匠都转变成毫无头脑的亡灵天灾士卒啦。但是镇子南边的幽暗城中还居住着一名铁匠。幽暗城在洛丹伦废墟下面，好听的名字，是吗？乘坐废墟后面的升降梯抵达幽暗城，去跟那儿的守卫谈谈，他们会为你指明方向的。"
D.Strings[2230]="想要当厨师？到城镇南部的幽暗城去接受培训。你可以到洛丹伦废墟后面找到下行的升降梯。当你到达后向那些笨拙的幽暗城守卫寻求更多帮助。"
D.Strings[2231]="既然所有东西对你来说吃起来都象是灰烬，为什么还要做饭呢？如果你还有一样东西不是这样的，那很好，到布瑞尔南边的幽暗城去问一位幽暗城的守卫，以进一步了解如何找到他们的烹饪培训师。要到那里你可以从洛丹伦废墟的后方乘升降梯下去。"
D.Strings[2232]="你可以在布瑞尔东南边的恐惧之末旅店的楼上的一间房间找到范斯·安德格鲁姆。"
D.Strings[2233]="有消息说范斯·安德格鲁姆已经在城镇东南端的恐惧之末旅店楼上永久定下了一间房间。我想他刚刚离开了阅览室。"
D.Strings[2234]="虽然在布瑞尔没有工程学训练师，在幽暗城却有一位。要到那儿，朝村子的南边走，一直到洛丹伦废墟，然后坐升降梯下去。一旦你到了那里，向一位幽暗城守卫询问详细的方位。"
D.Strings[2235]="来复枪、炸药、炸弹、爆炸绵羊……这些可爱的东西。要学习如何制造这些物品以及其他工具的话，就去布瑞尔以南，洛丹伦废墟下的幽暗城吧。乘坐废墟后面的升降梯，当你到达幽暗城后，向一个幽暗城守卫询问训练者的确切位置。"
D.Strings[2236]="当人们进入城镇东南角的恐惧之末旅店时，妮拉会向这些未来的顾客致敬。"
D.Strings[2237]="你说屠夫？哦，急救训练师！一个样。当你看到护士妮拉站在城镇东南面的恐惧之末旅店里面时你就会明白为什么。"
D.Strings[2238]="克莱德·凯林，当地的钓鲈鱼高手，有他自己最喜欢的钓鱼地点，就在布瑞尔东部的澈水湖。"
D.Strings[2239]="是的，你总是能看到克莱德·凯林在布瑞尔东边的澈水湖岸钓鱼。但当你到那里后要当心那些带着面具的变态者。我们去年就被迫关掉了孩子们的夏令营。"
D.Strings[2240]="去找法鲁萨。我最后一次见到她时，她正站在马厩和西北方向的房间之间。"
D.Strings[2241]="实际上我更倾向于传统医学……水蛭，蛆，锯骨……那类东西。你可以看到我们本地的草药医学训练师，法鲁萨，就站在布瑞尔的马厩的附近。"
D.Strings[2242]="你一定是要找舍伦尼·洛巴尔特。沿着布瑞尔东南方的道路走，然后在十字路口向东走。她就居住在路边的某个营帐中。"
D.Strings[2243]="接近尸体时的感觉是独一无二的。你可以沿着城镇外东南方面的道路前进，到达十字路口后向东走，找到舍伦尼·洛巴尔特。她居住在离道路不远处的小营帐中。"
D.Strings[2244]="我听说幽暗城中有个矿工训练师。离开城镇往南走，穿过洛丹伦废墟，你就能到那儿了。然后乘坐升降梯下到幽暗城，去询问幽暗城守卫，你应该能获取更多指示信息。"
D.Strings[2245]="我猜想你最初的训练就是挖掘到幽暗城。嗨，明白吗？挖掘……没关系。要到幽暗城，你先要到布瑞尔南面的洛丹伦废墟后方，然后乘升降梯下去。向那里的一位幽暗城守卫寻求更多的帮助。"
D.Strings[2246]="兰德·洛巴尔特对制皮这样的技能相当精通。你可以在往布瑞尔东南角沿途的某个营帐中找到他。沿着城镇东南方的道路走，然后在十字路口向东转。"
D.Strings[2247]="你想成为一个标本剥制师？我不喜欢那些从我身上获得材料然后运走的人，因为他们认为我死了。难道不讨厌吗？好了！到城镇东南边的一个营地找寻兰德·洛巴尔特。要找到他需要走布瑞尔东南方的路，然后在十字路口左拐。"
D.Strings[2248]="那么你是在找博文·布里斯博埃斯了。他居住在炉灰庄园大桥另一边，布瑞尔城镇西南部。"
D.Strings[2249]="黑色、灰色和深紫色是规定的颜色。朋友，看仔细了，可别迷失方向。博文·布里斯博埃斯可以帮助你。你可以穿过镇子西南的桥梁，去炉灰庄园找他。"
D.Strings[2250]="蝙蝠管理员"
D.Strings[2251]="职业训练师"
D.Strings[2252]="专业训练师"
D.Strings[2253]="艾瓦，我的鬼灵精华不见了。我需要另外一个。"
D.Strings[2254]="真冷……我很饿。$B$B我可怜的朋友，希望你已经安息了。我不忍心去想他们会对你做什么。$B$B你！嘿，就是你！请你一定要帮我逃跑。他们之中的某个人身上肯定有钥匙，你能找到它吗？我知道他们有钥匙。如果你弄到钥匙，就可以帮我离开这里了。特雷可能已经死了，但是我还心存希望！求你了，帮帮我吧！"
D.Strings[2255]="你已经为我做了很多事情，$n。谢谢你。$B$B现在我至少可以告诉你，我是怎么来到这里的。我和我的好朋友特雷·莱弗治潜入加德纳尔调查暗影议会，然后就在毫无准备的情况下被他们抓住了。他们把特雷带到暗影堡的深处，并把我关在这里，他们把我们所有的装备都拿走了……我仍然可以听到他的惨叫，$n。他们……简直丧心病狂。我不知道他们都对他做了些什么，但他们会为此付出代价的。"
D.Strings[2256]="当你检查牢笼和关在里面的暗夜精灵时，你有一种奇怪的似曾相识的感觉。不知为什么原因，她的目光从未与你接触——好像你对她来说并不存在一样。"
D.Strings[2257]="%s看起来非常困乏……"
D.Strings[2258]="这儿看上去是个休憩的好地方。"
D.Strings[2259]="他们并未意识到自己已经死了，$r。他们受到诅咒，在头脑中保留了这个城镇被毁灭之前的记忆，大部分是这样，还有一部分人更为不幸。$B$B你认为是亡灵天灾所为？那时亡灵天灾还不存在呢，就算是它们的话，我们也会与它们展开一场恶战的。$B$B不，这场恐怖而极具破坏性的灾难源于通灵学院，它摧毁了整座城镇，无人生还。$B$B让我独自承受这悲伤吧。"
D.Strings[2260]="你没看到我们正在准备迎接乌瑟的访问吗？现在别妨碍我，我有许多工作要做！"
D.Strings[2261]="你尝过我们的面包吗？面包师玛斯特森是最具天才的烹饪师！"
D.Strings[2262]="陌生人，欢迎来到凯尔达隆。"
D.Strings[2263]="陌生人，我们并不是粗鲁的家伙，只是大家都忙于在乌瑟到来之前确保一切顺利。光明使者能来到我们的城镇，这可真难得。"
D.Strings[2264]="我们美丽的岛屿迎来了新的一天。"
D.Strings[2265]="小心点，陌生人。别在我们的镇子里惹事。"
D.Strings[2266]="我被你吸引住了，$r。"
D.Strings[2267]="我憋了一肚子的火，别让我朝你发火。"
D.Strings[2268]="哎呀，你看起来就像是一个普通的街头顽童！"
D.Strings[2269]="在凯尔达隆，你不能四处游荡、行乞、诅咒、斗殴，也不能随心所欲 。"
D.Strings[2270]="诅咒神教正在迅速壮大。从小型村落到首都，从部落到联盟，几乎每座城镇的居民中都有诅咒神教的信徒。$B$B别惊讶，他们只在仪式和庆典上面才身穿统一的服饰。你很可能已经跟他们的信徒碰过面了，只是你不知道而已。"
D.Strings[2271]="是吗？这是他们一贯的操作手法。对克尔苏加德和快速增长的亡灵天灾军队来说，什么东西拥有更大的价值？一个能成功潜入某个组织，然后使数千人丧命的狂热追随者，还是一个普通到掉渣的亡灵士兵？很明显你不是那么愚蠢。$B$B没错，$r，他们就在你周围，生活着，工作着，密谋着。"
D.Strings[2272]="停下来——不。放慢速度——或许这样比较好。$B$B通灵学院是他们接受初级训练和教育的地方。信徒们从那儿走出来，并最终进入我们的社会。$B$B这就是我们必须攻破通灵学院的原因。它是诅咒神教的中心！"
D.Strings[2273]="放慢速度，$c。你要杀的人已经死了，对着尸体狂砍是无济于事的。可以真正摧毁僵尸的方法极少，而且你我也无法使用这些方法。为此，我制定了一项计划，这项计划将对诅咒神教产生巨大的影响。"
D.Strings[2274]="这很简单，真的。从莱斯·霜语的身上夺走他的力量。将他变回普通的形态，然后果断地杀死他。"
D.Strings[2275]="啊，我想我说得太快了。莱斯·霜语是通灵学院的管理者，他负责训练所有的黑暗大师，他是克尔苏加德最欣赏的学生和下属。他曾经是激流堡的法师，一个从来没有接受过达拉然正规训练的流浪巫师。$B$B当克尔苏加德开设诅咒神教的时候，莱斯就是首批加入其中的人，因为他知道通过黑暗魔法可以获得不朽。"
D.Strings[2276]="他真的获得了不朽之身。他很快从众多信徒中脱颖而出，巫妖王随即授予了他永生的权力。巫妖莱斯·霜语因此而诞生。$B$B你明白吗？"
D.Strings[2277]="很好。为了实现我们的计划，我们必须首先制造一块生命徽章。你准备好了吗？"
D.Strings[2278]="有人没有受到记忆的折磨。"
D.Strings[2279]="巴罗夫家族让我忙个不停。总有一些垃圾从那儿出来。"
D.Strings[2280]="我的头衔是废物管理专家。"
D.Strings[2281]="也许你应该对着这些套在我愤怒的拳头上的扩音器讲话。"
D.Strings[2282]="啊，我心爱的白兰地，我太思念她了！"
D.Strings[2283]="保持警惕！这一带有许多黑木熊怪……"
D.Strings[2284]="真安静……太安静了……"
D.Strings[2285]="很高兴见到你，朋友。我是军官加鲁什，是银色黎明这一世界组织的光荣成员。我们的任务是毫不留情地消灭艾泽拉斯大陆上所有邪恶的势力。银色黎明不是一个政治机构，我们也从不愿意与政治沾上边儿。我们的目标只有一个，为此我们将部落和联盟都看作自己的朋友——以铲除邪恶为己任的朋友！$B$B我的$g兄弟:姐妹;，为十字军而战！"
D.Strings[2286]="你好，朋友。我是普尔哈特，隶属于银色北伐军这个世界性的组织。我们的目标非常简单——与艾泽拉斯的一切邪恶力量进行顽强而坚决的战斗。我们不是一个政治团体，也不想成为那样的团体。为了银色北伐军的伟大目标，为了剿除世界上的一切邪恶，我们将联盟和部落的成员都当作并肩作战的朋友来看待！$B$B为了黎明而战，我的$g兄弟:姐妹;！"
D.Strings[2287]="银色黎明向你致敬，$c。我是哈萨娜——银色黎明为数不多经过授权的装备和军品军需官之一。$B$B既然你在我们委任下作战——同时赢得我们的尊敬和信任——你会从加鲁什军官那里得到英勇勋章。它们有两个作用：在我们的队伍中赢得地位，或者作为交换得到某些特殊物品。$B$B随着你在银色黎明地位的升高，你会发现你能够得到更多物品。"
D.Strings[2288]="加入对抗邪恶的战斗中吧！今天就去获得银色黎明的委任徽章吧！"
D.Strings[2289]="我还需要一枚银色黎明委任徽章。"
D.Strings[2290]="银色北伐军向你致敬，$c！我叫莱斯巴克，是银色北伐军委派的装备和物资军需官。$B$B如果你愿意接受任命，同邪恶力量作战——以此赢得我们的尊重和信任——你就能在军官普尔哈特那儿获得勇气勋章。勋章有两个用途：提高在我们阵营内的地位，或是获取特殊物品。$B$B随着你在银色北伐军内阵营地位的提高，你会发现自己能获得更多的物品。"
D.Strings[2291]="你好，$c。我是军需官米兰达·布利洛克——银色军团为数不多的授权装备和军品军需官之一。$B$B既然你在我们的委任下与邪恶战斗——同时赢得我们的尊敬和信任——你会从尼古拉斯·瑟伦霍夫公爵那里得到勇气勋章。勋章有两个作用：用他们赢得在军队中更高的地位，或者作为交换得到特殊物品。$B$B随着你在军团中地位的升高，你会发现你会有更多的物品。"
D.Strings[2292]="你好，$c。$B$B那边的哨兵允许我住在他们的营地，只要我答应不会再有麻烦了——我敢肯定你能意识到对外交的需要，是吗？$B$B我来调查这片土地的紊乱状况，既然这也有助于他们的事业，他们同意我在这里 只能协助艾泽拉斯各族之间脆弱的联盟关系。如果你想帮我，那么我会很感激，但无论如何，请不要引起任何麻烦。"
D.Strings[2293]="欢迎来到钢架补给站！"
D.Strings[2294]="种族并不代表荣誉，$r。只要你呆在我的农场，就请你记住并尊重这个信条。$B$B我曾见过一些兽人，他们像最高贵的骑士那样可敬；我还见过某些人类，他们像最残忍的亡灵天灾那样邪恶。$B$B啊，我不该拿我年轻时的故事来烦你的！要做的事情还很多呢——如果你很想找些事情做的话。"
D.Strings[2295]="银行？哦，这附近最近的银行就是暴风城会计室。沿着暴风城大门不远的那条路向前走就是。"
D.Strings[2296]="哦，你一定是说暴风城会计室。走进城门之后，它就在贸易区的西南部。"
D.Strings[2297]="如果你想乘坐狮鹫的话，就去找暴风城的狮鹫管理员吧。当你进入英雄谷时，应该就能看见右边的狮鹫降落台。"
D.Strings[2298]="狮鹫管理员监管着飞进飞出暴风城的所有狮鹫。如果你想乘坐狮鹫的话，就去找他吧。"
D.Strings[2299]="我相信奥德文·拉弗林仍是暴风城的常驻公会注册员。当你进入暴风城的贸易区后，你的左手边就是他的居所。"
D.Strings[2300]="这些日子以来，所有的官方事务都是在暴风城处理的。如果你想要组织公会的话，就去暴风城接待中心吧。"
D.Strings[2301]="到闪金镇的狮王之傲旅店去吧。那儿有啤酒和柔软的床铺供你尽情享用，没有比那里更好的休息场所了。"
D.Strings[2302]="闪金镇的狮王之傲旅店是这个地区中最好的旅店了。在那儿歇一歇吧，旅店老板法雷会让你感受到家的温暖。"
D.Strings[2303]="在艾尔文森林只有少数职业的训练师。你在找谁？"
D.Strings[2304]="德鲁伊？我没看到过任何德鲁伊。不过在暴风城中有一块属于暗夜精灵的区域。"
D.Strings[2305]="我听说暴风城中有个矮人因狩猎技巧高超而闻名。或许你可以找他问问看。"
D.Strings[2306]="洁塞塔经常帮助镇子里的守卫，她是圣光赐予我们的礼物。如果你想学习牧师技能的话，可以去狮王之傲旅店找她。"
D.Strings[2307]="我敢打赌洁塞塔会很乐意教你学习新法术的。她就在狮王之傲旅店的房间内。"
D.Strings[2308]="扎尔迪玛可能会教你一些新的法术。他最近喜欢待在狮王之傲旅店，你可以去那里的房间看看他在不在。"
D.Strings[2309]="我对魔法知之甚少，但是在狮王之傲有一个名叫扎尔迪玛的法师，他也许能帮助你。"
D.Strings[2310]="你通常可以在铁匠铺的后面发现威尔海姆修士和里瑞亚互相讲故事。他总是很乐意向圣骑士们传授新的技艺。"
D.Strings[2311]="威尔海姆修士经常在闪金镇的锻冶场后面培训里瑞亚·杜拉克。你可能会从他那里学到一些圣骑士的知识。"
D.Strings[2312]="一个潜行者？嗯……我曾听说过那个科瑞恩·塞尔留斯在那些阴暗的地方游荡。找她谈谈，看看你能学到点什么。"
D.Strings[2313]="我打赌科瑞恩·塞尔留斯知道你在寻找什么东西。她通常在狮王之傲旅店里。"
D.Strings[2314]="这附近很少有人像科瑞恩·塞尔留斯一样精通于刀刃的使用技巧。到铁匠铺后面找她看一下她有没有心情教你些新东西。"
D.Strings[2315]="要是你想接受训练的话，就去找科瑞恩。她通常在铁匠铺外面等着铁匠打造武器。"
D.Strings[2316]="哦……好吧，玛克西米利安是这附近唯一一个了解黑暗魔法的人。你也许可以在狮王之傲旅店那阴暗的地下室里找到他。"
D.Strings[2317]="一个术士？好吧，如果我是一个术士，我可能会待在这附近最黑暗的地方……那就是狮王之傲旅店的地下室。你应该先到那里去看看。"
D.Strings[2318]="我知道有些人在这附近练习某些专业。你想要打听哪项专业技能的训练师？"
D.Strings[2319]="听说那个隐士玛洛瑞有时会为当地居民配制药剂，他居住在暴风城和北郡之间的小山上。"
D.Strings[2320]="居住在北郡和暴风城之间的山上的一位炼金师或许能帮上忙。你为什么不去找他呢？"
D.Strings[2321]="铁匠阿古斯居住在闪金镇。我想他能教你如何做一名铁匠。"
D.Strings[2322]="你一定是在寻找铁匠阿古斯。如果你需要接受训练的话，他通常在闪金镇监督铸造工作。"
D.Strings[2323]="托马斯也许不是最好的厨师，但是他确实能做一些精美的菜肴。如果你想学习厨艺的话，就去狮王之傲旅店找他吧。"
D.Strings[2324]="你为什么不到狮王之傲看看呢？那里的厨师可能会教你几道好菜。"
D.Strings[2325]="不，我不认为在艾尔文森林中有附魔师。但是，在暴风城中有个名叫鲁坎的家伙，他开了一家商店。你可以去找他，看他是否能训练你。"
D.Strings[2326]="嗯……这附近唯一有附魔训练师的地方就是暴风城了。你为什么不问一下暴风城的守卫呢？"
D.Strings[2327]="我通常将那种事情留给侏儒去做。要是你想学习这项专业的话，我想你可以在暴风城找到一些侏儒来训练你。"
D.Strings[2328]="暴风城中的某位侏儒肯定能教你，而且我相信暴风城的守卫能为你指明方向。"
D.Strings[2329]="我最近在这里附近遭遇过一些迪菲亚盗贼，但米歇尔·贝利帮我进行了治疗。到狮王之傲与她商量一下，看看她能否教你。"
D.Strings[2330]="米歇尔·贝利对病患的态度令人钦佩！她也许无法教你如何对待病人，但是她可以教你一些急救技巧。她现在居住在狮王之傲旅店。"
D.Strings[2331]="李·布朗整天都在水晶湖钓鱼。或许他能给你讲些故事，还能教你一些技巧。"
D.Strings[2332]="李·布朗在水晶湖中抓到过很多奇怪的东西。他说他数月前钓起过一个神秘的面具。但是照实说，我想他那晚一定在狮王之傲喝多了。"
D.Strings[2333]="草药师博米洛伊为居住在北郡和暴风城之间的山上的一名炼金师收集草药。去他的住所找草药师博米洛伊，看她是否能对你有所指引。"
D.Strings[2334]="有一名草药师跟炼金师一同居住在暴风城东面的山上。完美的搭配，不是吗？"
D.Strings[2335]="水晶湖边居住着一位名叫艾德勒·费欧德的女士。她利用从当地剥皮师海伦尼那儿得来的皮革为当地的守卫制作补丁。如果你想要学习这项专业技能，她也许就是你要找的人。"
D.Strings[2336]="艾德勒·费欧德的皮革手艺在艾尔文森林已经妇孺皆知了。她的家就在水晶湖旁边。"
D.Strings[2337]="如果你想学习挖矿的话，最好前往暴风城的矮人区。那里的某个矮人肯定会教给你这门技能。"
D.Strings[2338]="我认为你在暴风城会交到好运的。去问问那儿的守卫，他们会给你指明方向。"
D.Strings[2339]="海伦尼·派特斯金纳有着数年的剥皮经验，他一直为艾德勒·费欧德提供兽皮以制造皮革制品。你可以在水晶湖旁的房间里找到她。"
D.Strings[2340]="在水晶湖畔居住着一名技艺高超的剥皮师。她可以教你这项专业的入门技能。"
D.Strings[2341]="艾尔丁是艾尔文森林中唯一称得上裁缝的人。要是你对这个专业感兴趣，就去东谷伐木场找他吧。"
D.Strings[2342]="你想学习成为一个裁缝？嗯……我相信在东谷伐木场有一个裁缝可以教你。"
D.Strings[2343]="最近的银行就是铁炉堡银行，$g小伙子:姑娘;。"
D.Strings[2344]="铁炉堡银行是这一带最近的银行。"
D.Strings[2345]="丹莫罗一带是没有狮鹫管理员的，$g小伙子:姑娘;。如果你想骑狮鹫去什么地方的话，就必须去铁炉堡。"
D.Strings[2346]="最近的狮鹫管理员居住在铁炉堡的大锻炉附近。如果你想乘坐狮鹫的话，就前往铁炉堡吧。"
D.Strings[2347]="所有的官员都居住在铁炉堡。你得去铁炉堡访客中心领取公会登记表。"
D.Strings[2348]="要是你需要一些公会登记表的话，就前往铁炉堡，去拜访铁炉堡访客中心吧。"
D.Strings[2349]="雷酒家族在卡拉诺斯开了一家旅店，久负盛名。在那里喝杯酒休息一下吧。"
D.Strings[2350]="哦，旅店是吗？嗯，雷酒酿制厂是最棒的。你可以在那里稍事休息，但是你一定得尝尝那儿的啤酒。"
D.Strings[2351]="这附近只有一名猎人，那就是格瑞夫。他就站在卡拉诺斯的铁匠铺外。"
D.Strings[2352]="假如你问我的话，我想格瑞夫在动物身上花费的时间过多了。到目前为止，没人比他更精通于猎人之道。去卡拉诺斯的铁匠铺外面找他吧。"
D.Strings[2353]="住在雷酒酿造厂的一名法师或许能教你一些新的魔法。我想他名叫玛济斯·石衣。"
D.Strings[2354]="你肯定你不想当一名战士？那好吧，如果你真想学习动动手指的把戏，你最好去找雷酒酿制厂的玛济斯·石衣谈谈。"
D.Strings[2355]="哦……一个圣骑士？嗯，$g小伙子:姑娘;，你真走运！阿扎尔·战锤刚结束训练，他现在在卡拉诺斯的雷酒酿制厂。"
D.Strings[2356]="你需要接受些训练？好吧，阿扎尔·战锤总是愿意教给年轻的圣骑士一点东西。你为什么不去雷酒酿制厂找他呢？"
D.Strings[2357]="哦，是牧师吗？要是你想接受训练的话，就去雷酒酿制厂找马克萨恩吧，他一定在那儿喝酒呢。"
D.Strings[2358]="你肯定可以在雷酒酿制厂看到马克萨恩·安沃尔大口喝酒。为什么你不去喝一点，顺便看看他能教你点什么新鲜东西呢？"
D.Strings[2359]="那么，似乎我们都是来找霍格拉尔·巴坎的。他是个矮人，他迟早会去 雷酒酿制厂喝酒的，没准他现在已经在那儿了。"
D.Strings[2360]="你在寻找霍格拉尔？那你找过旅店吗？啊！如果你在找一个潜行者，而他同时还是一个矮人，你应该从旅店开始！先去看一下。"
D.Strings[2361]="术士……我可不在乎他们。就像那个在雷酒酿制厂外开设商店的吉姆瑞兹。都是他，那儿的啤酒可能都跑了气！术士……呸！"
D.Strings[2362]="我告诉你，掌握那种魔法可不是什么好事。我不知道为什么他们会允许吉姆瑞兹在雷酒酿制厂外面安营扎寨！离他远点！"
D.Strings[2363]="哦！这可是你说的！我敢打赌格兰尼斯·快斧会向你展示如何挥动武器的。他现在在卡拉诺斯的雷酒酿制厂。"
D.Strings[2364]="格兰尼斯·快斧能把一条鱼给喝趴下，而且还能把斧头抡得虎虎生风。如果你想接受训练的话，就去找他吧。"
D.Strings[2365]="不，在丹莫罗是没有炼金师的。你最好去铁炉堡……去工匠区找侏儒。"
D.Strings[2366]="我听说铁炉堡中有家由精通炼金术的侏儒所经营的商店。你该去看看。"
D.Strings[2367]="哦！这是一项极有价值的技能。托格努斯以你从未见过的方式敲击铁砧。为什么你不去跟他谈谈，看看他能教你什么？"
D.Strings[2368]="当你在卡拉诺斯的时候，你可能会听到托格努斯在铁砧上敲打。然而，如果你还没有把耳朵里的蜡清理掉，那你为什么不到铁匠铺去看看呢？"
D.Strings[2369]="一瓶雷霆啤酒外加格雷姆罗克做的菜就足以让你饱餐一顿。如果你想成为一名厨师的话，就该去参加他的培训。"
D.Strings[2370]="格雷姆罗克烹饪的手艺不一定是最好的，但他确实有些美味的食谱值得学习。到雷酒酿制厂找他聊聊，看看他能教给你什么。"
D.Strings[2371]="据我所知，丹莫罗是没有附魔师的。如果你想成为一名附魔师的话，就去铁炉堡吧。"
D.Strings[2372]="如果你一心想学附魔的话，你该到铁炉堡看看。我记得上次我到那里的时候曾看到狮鹫旁边有一家商店。"
D.Strings[2373]="你应该去钢架补给站找布隆克。当他不忙着修补一些奇怪装置的时候，他通常就在跟飞行员们聊些关于他们的蒸汽坦克的事。"
D.Strings[2374]="布隆克总是在敲敲打打，他擅长修理最为精密的机械。你应该到钢架补给站拜访他一趟。"
D.Strings[2375]="急救虽然不能代替牧师的治疗，但是它在紧要关头却很方便。我建议你去跟雷酒酿制厂的萨姆诺谈谈，并力所能及地学习一些东西。"
D.Strings[2376]="好心的萨姆诺前些天在我与一个肮脏的穴居人战斗后替我包扎了伤口。我现在已经完全痊愈了！我敢肯定萨姆诺会很高兴教你制作绷带的。"
D.Strings[2377]="这周围可不是钓鱼的好地方，但是你应该去找帕克斯顿问问看。他在涌冰湖钓鱼。"
D.Strings[2378]="这附近只有几处地方可以钓鱼。帕克斯顿对此了如指掌，但是他不一定都会告诉你。为什么不去涌冰湖找他谈谈呢？"
D.Strings[2379]="有些弱小的植物竟然能在丹莫罗的寒风中开花，这真令人惊奇……但是这儿没有草药师。你得去铁炉堡接受草药师的训练。"
D.Strings[2380]="不，这儿没人能教你草药学。你最好去铁炉堡碰碰运气。"
D.Strings[2381]="要是你想学习制皮的话，就去铁炉堡吧。我听说大锻炉附近有间商店，你可以那儿学到制皮的知识。"
D.Strings[2382]="铁炉堡是学习制皮的最佳场所。要是我没记错的话，你可以去大锻炉旁的商店。"
D.Strings[2383]="这么说，你以为在这个城镇里没有常驻矿工，是吗？错！在卡拉诺斯外的钢架补给站附近去找亚尔吧。"
D.Strings[2384]="矿工？你不需要问有没有，$g小伙子:姑娘;，只需问在哪里！亚尔就是你要找的家伙，我想他应该在钢架补给站那里。"
D.Strings[2385]="丹莫罗这里可没有剥皮匠，$g小伙子:姑娘;，如果你想要学习剥皮的话，就到铁炉堡去找找吧。"
D.Strings[2386]="剥皮匠通常会把所有的兽皮豆带到铁炉堡去风干。你为什么不去那儿看看是否能找人训练你呢？"
D.Strings[2387]="啊，石眉这些日子不怎么离开铁炉堡的，如果你想要学做一名裁缝的话，就去铁炉堡找他吧。"
D.Strings[2388]="嗯，似乎你在寻找裁缝时并不顺利。但是，有很多高明的裁缝都居住在铁炉堡。你为什么不去问问那里的守卫呢？"
D.Strings[2389]="泰达希尔有许多你需要去看看的地方。告诉我你在找什么。"
D.Strings[2390]="银行位于平静的达纳苏斯城。如果你想存储自己的财物的话，就得去那儿。"
D.Strings[2391]="要是你想找银行的话，就去达纳苏斯的中央地带。你可以在那儿存储自己的财宝。"
D.Strings[2392]="想要找到鲁瑟兰村的渡船，你得先去达纳苏斯，通过传送门进入鲁瑟兰村。"
D.Strings[2393]="官方事宜只能送交达纳苏斯处理。你必须前往那儿去创建自己的公会。"
D.Strings[2394]="诸如公会登记表等文档可从达纳苏斯的公会注册员那儿获得。"
D.Strings[2395]="旅店"
D.Strings[2396]="你可以在多兰纳尔旅店的老板凯达米尔提供的床上安稳地睡一觉。"
D.Strings[2397]="如果你需要通过休息恢复体力的话，多兰纳尔的旅店是你最佳的选择。旅店老板凯达米尔将帮你打点一切。"
D.Strings[2398]="你可以在多兰纳尔周围找到众多的训练师，他们有丰富的经验可以传授给你。你想要找哪一位？"
D.Strings[2399]="你在寻找一个德鲁伊的训练师？那么你应该到多兰纳尔旅店南面的月亮井去见见卡尔。"
D.Strings[2400]="德鲁伊训练师卡尔通常待在多兰纳尔的月亮井。我想他可以对你进行训练。"
D.Strings[2401]="要是你想找猎人的话，就去拜访达扎拉吧。他通常在多兰纳尔旅店的外面。"
D.Strings[2402]="达扎拉以他的狩猎技能在多兰纳尔小有名气。为什么不找他谈谈，看看他能教你点什么呢？"
D.Strings[2403]="一位名叫劳尔娜·晨光的女祭司住在多兰纳尔，我认为你可以在旅店北面找到她。"
D.Strings[2404]="劳尔娜·晨光为居住在多兰纳尔附近的居民们提供医疗服务。或许她能教你如何成为一名牧师。"
D.Strings[2405]="潜行者？我不习惯跟那些家伙打交道，但我相信詹诺克就是你要找的训练师。你可以在多兰纳尔的旅店找到他。"
D.Strings[2406]="你在找寻一个潜行者？我认为詹诺克很适合你的描述。你为什么不到多兰纳尔的旅馆里去找他谈谈呢？"
D.Strings[2407]="凯拉·风刃的战斗技能炉火纯青。她可以对你进行训练。到多兰纳尔的旅店中去找她吧。"
D.Strings[2408]="我以前曾有幸看到在凯拉·风刃作战，因此我相信她可以好好训练你。到多兰纳尔旅店去找她吧。"
D.Strings[2409]="从事某种专业的学习是一个长期的过程，但是回报很丰厚。你想选择什么样的专业？"
D.Strings[2410]="塞恩德拉的态度非常和蔼，她的药剂也很不错。你可以在多兰纳尔旅店的东边找到她。"
D.Strings[2411]="塞恩德拉在炼金术方面的知识有些局限，但是我相信那也足够领你入门了。她就在多兰纳尔旅店的东面。"
D.Strings[2412]="扎瑞恩看起来很了解烹饪行业。为什么你不去看看他是否会给你一些食谱呢？他通常在多兰纳尔的旅店旁边烹饪。"
D.Strings[2413]="我们当然欢迎多兰纳尔的厨师再多几个，但我并不是说扎瑞恩厨艺欠佳。你为什么不去找这个厨师看看他能教你什么？"
D.Strings[2414]="奥兰纳·鸦眼将她的天赋部分归结为与神谕林地的灵魂进行了交流。你应该能在那儿找到她的。"
D.Strings[2415]="阿兰娜大部分时间都在神谕林地练习技能。如果你想学做一名附魔师的话，就去那儿找她吧。"
D.Strings[2416]="拜恩希经常为在野外巡逻的哨兵服务。如果你想学习急救的话就该找她谈谈。"
D.Strings[2417]="拜恩希在急救方面的技巧已经很知名了。如果你想向她学习的话，你可以到多兰纳尔旅店的北面去找她。"
D.Strings[2418]="奥拉密斯湖近来遭受袭击，所有的渔夫都已经搬迁到达纳苏斯了。你应该去那儿看看。"
D.Strings[2419]="林精使渔民在多兰纳尔很难有所收获。你最好去达纳苏斯找找他们。"
D.Strings[2420]="不知道玛洛尼是如何采集到那些最为娇嫩的草药的。显然你得向他多多学习。他就住在多兰纳尔的旅店东边。"
D.Strings[2421]="要学习草药学，你得向玛洛尼好好讨教。去多兰纳尔旅馆东边找他吧。"
D.Strings[2422]="纳迪娅·织发离开自己的家园前往达纳苏斯进修去了。她精通制革，而且是一名优秀的老师。你该去向她求教。"
D.Strings[2423]="纳迪娅在数年的实践中掌握了制皮技术。沿着通往达纳苏斯的道路向西走，去拜访她，或许她能传授给你一些知识呢。"
D.Strings[2424]="你可以在去达纳苏斯的路上看到拉德纳尔在他的屋外练习手艺。你应该停下来看看他有什么可以教你的。"
D.Strings[2425]="我敢肯定在达纳苏斯有一个裁缝可以对你进行训练。当你到了那里之后，就向达纳苏斯的某个哨兵询问一下裁缝住在哪里吧。"
D.Strings[2426]="裁缝所需的多数物品都是从达纳苏斯获得的。他们都在那儿工作，这并不是件奇怪的事情。要是你想成为一名裁缝的话，你最好前往达纳苏斯。"
D.Strings[2427]="帮帮我！你一定要帮帮我！"
D.Strings[2428]="你好，$c。我在亡灵壁垒设立营帐，准备进入瘟疫之地。不久之前，谣传有一位伟大的人类巫师居住在壁炉谷。血色十字军强迫他为他们的战士和猎人制造新的弓箭和枪支。据说在十字军杀死他之前，他正在铸造一件非比寻常的武器。$B$B我猜想他们对奥术越来越不信任了。"
D.Strings[2429]="你好，$c。没有多少时间谈话——我在动身去壁炉谷之前只是把冰风营地作为暂留地休息一下。我曾听到传言在他们疯掉之前，血色十字军强迫一个法师为他们工作，为他们的士兵制造强大的弓箭和枪支。我不敢肯定他成功与否……十字军在他们的成品制成之前杀死了他。或许他们杀死他为了保密……也可能他们不太信任奥术。"
D.Strings[2430]="你……你好，$n。对不起，我正从伤势中恢复过来。$B$B那些血色十字军比我料想的要凶猛的多。他们几乎在里面干掉了我。$B$B你也应该多加小心。我不愿看到他们先发制人。"
D.Strings[2431]="我的家人过去在北山伐木场工作，那里现在被称作西瘟疫之地。他们曾忠于杜马家族，而现在血色十字军把一切连同壁炉谷全都占领了！$B$B在把那些狂热分子从艾泽拉斯驱逐出去之前，我是不会停止行动的。"
D.Strings[2432]="在最后一次大战之前，我父亲经营着北山伐木场。那是他的命根子，他把所有的精力都投到了伐木场。战争爆发时，我们忍痛逃到了暴风城。$B$B那些日子里，我们失去了无数朋友，而我们的伐木场也被血色十字军占领了，我对此感到非常心痛。$B$B这就是我回来的原因。"
D.Strings[2433]="修道院的那些傻子给我们送来了鲜肉。"
D.Strings[2434]="我们是熊怪家族仅剩的成员了……木喉部落还未堕落，但是其他部落对我们怀有相同的敌意；有熊怪能免于堕落……很多人都认为这是不可能的……$B$B我的兄弟们对那么急于与我们为敌的家伙非常生气，现在他们已经开始攻击任何靠近我们的生物；他们谁都不信任。$B$B但是，如何你能努力证明想要和他们和平相处的话，他们或许会把你当作盟友的。"
D.Strings[2435]="我怎么才能向木喉的熊怪证明我自己呢？"
D.Strings[2436]="你必须想办法来证明你们两个是在同一条战线上的。尽管现在木喉可能会攻击你，但如果你够勤奋的话，你就会找到办法的。$B$B你一定要记住，任何对木喉熊怪的攻击都会大大降低你们赢得与他们结盟的机会。$B$B有个不错的着手点就是在费伍德森林的许多部分都发现的死木熊怪。这些熊怪是木喉部落的敌人，杀了他们将会大大提高你在木喉中的地位。"
D.Strings[2437]="我们能让你安全通过这儿，但是，你得证明自己值得我们给予帮助。"
D.Strings[2438]="冬泉熊怪怎么样？"
D.Strings[2439]="居住在冬泉谷的寒水熊怪曾经是我们的盟友……但是有一天，这一切都改变了。$B$B他们听从高级首领的号令，开始攻击他们接触到的任何生物，包括我们的部族。他们现在几乎不与外界接触了……"
D.Strings[2440]="我只信任你所在种族中的少数人，$n。但是我把你当朋友。"
D.Strings[2441]="是的，是的。我看到你了。$B$B在去找你的路上。你可能已经赢得了一些人的信任，但要向我证明可并不仅仅如此！"
D.Strings[2442]="正在上课！"
D.Strings[2443]="如果你能证明自己是个真正的盟友，我或许会考虑训练你的……"
D.Strings[2444]="我想接受训练。"
D.Strings[2445]="别与圣光作对，$c，或许有一天它能拯救你。"
D.Strings[2446]="我相信圣光会与你同在，$n。我能帮忙吗？"
D.Strings[2447]="愿圣光与你同在，$n。我能为你做什么吗？"
D.Strings[2448]="你当心些，$c。尊重我们的方式，否则你和你的人们就会受到诅咒。"
D.Strings[2449]="我这个无足轻重的仆人能为你做什么，$n？需要训练吗？"
D.Strings[2450]="我的智慧就是你的智慧，我的知识也一样。我能为你做什么，$n？"
D.Strings[2451]="我想接受更多的牧师技能方面的训练。"
D.Strings[2452]="我在找人，$c。请不要打扰我……这对我很重要。"
D.Strings[2453]="我是来自东部王国的信使，$n。我到这儿来是确保来此的牧师已经受到正确指示。"
D.Strings[2454]="安静！你没听见主人在讲话吗？"
D.Strings[2455]="少说废话，认真听讲。"
D.Strings[2456]="如果要孵化出我们的龙的话，我们必须集中精力！"
D.Strings[2457]="肃静！我不能漏掉这次讲座任何一句话！"
D.Strings[2458]="你忘记自己的学生服了吗？你认为时尚比亡灵天灾的统治更重要吗？"
D.Strings[2459]="你完成了昨天的作业吗？要是完成了，就过来跟我坐一块吧！"
D.Strings[2460]="小心点，$g男孩:女孩;。主人能洞察一切……"
D.Strings[2461]="你带来了课本吗？我能和你一起看吗？"
D.Strings[2462]="我可以问，你在这里做什么吗？穿上你的学生服装，然后学习！"
D.Strings[2463]="肃静！你认为那些被感染的龙会自己孵蛋并哺育幼龙吗？"
D.Strings[2464]="你来自燃烧平原吗？你有黑龙蛋吗？"
D.Strings[2465]="你的精神不够集中。你对我隐瞒着什么吗?"
D.Strings[2466]="我感觉一场动乱潜伏在你周围……"
D.Strings[2467]="你的未来乌云密布。集中精力，再问一次。"
D.Strings[2468]="你看起来不像是个学生……"
D.Strings[2469]="这只科多兽显然不是我最初召唤的那只。我在想科多兽诱引器是否能为我所用。"
D.Strings[2470]="瘟疫之地是对付天灾亡灵绝佳的地方！"
D.Strings[2471]="我的箭用光了！如果还有来进攻的话，你们就要靠自己对付了，我的朋友。"
D.Strings[2472]="等等……你听到了吗？有东西从西面逼近了！"
D.Strings[2473]="赞美月神！要是没有你这个朋友，我不知道自己还能不能生还。"
D.Strings[2474]="我的腿现在感觉好多了，治疗肯定起作用了。请原谅我，我必须去向我的上级汇报这里发生的事情。"
D.Strings[2475]="很高兴见到你，$c。除非你和我的女主人玛加萨之间有直接交易关系，否则别找我说话。$B$B我帮她处理大部分的事务，让她能集中精力处理更重要的事情。或许在你拜见她之前我们可以谈谈。"
D.Strings[2476]="你好，$n。"
D.Strings[2477]="你随时都可以跟我交谈，$n。你对玛加萨忠心耿耿。我想将来她会召见你的。"
D.Strings[2478]="别把自己当我的同辈来跟我讲话，$c。希尔瓦娜斯是我的女王，我听从她的命令。$B$B要是你不表现出适当的尊重，我敢说我们将为你在扭曲虚空选个更为合适的位置。$B$B但是要是你愿意帮助黑暗女王的话，我们便无话可说了……"
D.Strings[2479]="在我眼中，部落的所有成员都是平等的，$n。我们的血液被恶魔玛诺洛斯污染了，人民承受着重负，如果不是为了学识和荣耀的话，我们几乎就快沦为亡灵天灾了。$B$B协助部落，让我们获得新生，这是你的职责。但是你也得明白什么时候应该对朋友同情，对敌人怜悯。$B$B好好理解。这是新生的部落，而不是缺乏自由意愿的恶魔军队。"
D.Strings[2480]="由于我的身份问题，我并未对你说实话，我必须为此向你道歉。我必须确定你是值得信赖的——很少有人能无私地为一个年老的隐士提供帮助。$B$B你已经证明了自己是个正直崇高的人。"
D.Strings[2481]="当我以叛国罪被放逐离开联盟过着流放的生活时，我的儿子泰兰还是个小孩。我呆在这儿就是为了看着他长大，让他成为一个可敬的人。$B$B正如我期望的那样，他接替我的位置，成为玛登霍尔德之王，但是命运是如此残酷，他加入了血色十字军的队伍。现在他成了十字军的高级统领，$r。"
D.Strings[2482]="真的。血色十字军是银手骑士团做出的错误决策。$B$B你必须相信我，$r；泰兰是个好人。他需要指导。他必须记起……记起高贵和荣耀的含义。我知道那信念就在他心中，他知道他所做的是错误的。你帮助他好吗？帮助他记起来？"
D.Strings[2483]="为什么像地精这样的小生物总是迷恋创造大的发明呢？"
D.Strings[2484]="你要仔细听好了，别轻易相信或怀疑你所听到的一切。因为即使是朋友也可能将自己送上死路，$c。$B$B我们伟大的酋长深知这一点，为了证明部落中有一些术士并不想从内部毁掉部落，或是为了获得权力，我自愿尽我所能帮助年轻的首领。"
D.Strings[2485]="吴平的精力真令人惊奇。我看着他连续练习了数小时技巧。他用双手击打练习用的假人，直到他的拳头沾满鲜血。我想不到还有谁比他更适合训练你的战斗技能。"
D.Strings[2486]="吴平大师几乎懂得人类所知的所有武器的用法。在徒手搏斗中，他的觉醒之拳技能具有致命的攻击力。要是你需要训练的话，就去找他吧，他一般都在维勒武器店等待新武器的运送。"
D.Strings[2487]="通过千百次的锤炼，伊琳尼雅·月火已经掌握了若干种武器的使用方法，现在她为别人提供训练。如果你想接受训练的话，就去战士区找她吧。"
D.Strings[2488]="我的大部分武器技能都是跟战士区的伊琳尼雅·月火学的。要是你想学习如何使用新武器，就去找她吧。"
D.Strings[2489]="武器训练师"
D.Strings[2490]="比克斯和布里维夫的武器沾满了兽人的鲜血。如果你想学习的话，就去密林武器店找他们吧。"
D.Strings[2491]="你想学习怎样使用一种新武器是吗？那么，你就应该与那边的密林武器店武器商店的比克斯和布里维夫谈谈，$g小伙子:姑娘;。他们对从斧头到……嗯……双手武器都非常了解。"
D.Strings[2492]="想学习如何使用新武器？去荣誉谷的传说中的装备店中找塞尤克和哈纳什吧。"
D.Strings[2493]="去荣誉谷的传说中的装备店中找塞尤克和哈纳什。注意你的言行，否则塞尤克也许会将你作为喂狗的美食。"
D.Strings[2494]="武器大师"
D.Strings[2495]="啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底层找他吧。"
D.Strings[2496]="在武器使用方面，没有人能胜过安塞瓦了。据说他接受过我们尊敬的祖先，最伟大的战士的灵魂的指导。去中部高地的底层寻找他，他会教你的。"
D.Strings[2497]="你要找的阿基巴德在战争区内环的武器商店外。"
D.Strings[2498]="小亡灵阿基巴德知晓所有武器。你可以在军事区内环找到他。"
D.Strings[2499]="我得向你解释，我们的敌人能安然地潜伏在我们的眼皮底下。$B$B首先要记住这一点：我们的敌人是暗影议会。无论我给你什么任务，或许无论我让你与谁对抗，你都必须明了这个事实。$B$B议会拥有许多信徒，但是其行动信息绝对不会透露给愚蠢的信徒。$B$B像火刃、阿古斯的觉醒和燃刃都是议会的工具。他们是一伙的。"
D.Strings[2500]="啊，是我们的人。很高兴看到我们的队伍增长如此迅速，以至于我都记不清每个人的容貌了。$B$B沃金那个傻子认为我正努力改善术士的形象并为他服务呢。白痴！燃烧军团在耗尽这世界的资源后会将它化为灰烬的。"
D.Strings[2501]="天真的傻子。火刃就是暗影议会！议会拥有许多信徒和组织，但是他们都服从于议会的意愿。我或许能领导火刃，但是我无非是议会手下的一名爪牙，就像你是我的爪牙一样！$B$B看看燃刃吧——他们中的大多数人认为自己会成为下一批极具潜力的术士，并成功替代暗影议会。"
D.Strings[2502]="哈哈！除了他们的领导人——萨特, 巴扎兰, 还有术士耶戈什——是的，他们所有人。这就是我不断的派沃金的信徒到他们那儿去的原因。这样会让沃金觉得我正在铲除他伟大城市中邪恶的人。事实上胜利是双重的：杀掉萨尔的信徒并测试一下那些燃刃的力量，看看他们是否真的有资格加入我的队伍。"
D.Strings[2503]="我会让你知道这一点的。很明显，你如此迅速地成为中尉，已经证明了自己的实力。或许稍后你回到我这儿时，我会派给你任务的。委员会崇尚那些能熟练运用魔法的人，但也欢迎各种族的仆从，无论该仆从从事何种职业。"
D.Strings[2504]="你就明说吧……"
D.Strings[2505]="很高兴看到火刃接管了那些暗影议会无力接管的地方。"
D.Strings[2506]="这么说，燃刃可以牺牲了？"
D.Strings[2507]="要是你能从我这儿拿走什么的话……"
D.Strings[2508]="作为探险者协会的一员，我曾在这片区域搜寻古代器物。据说冬泉谷有许多不可思议的物品……很多物品都受到严密的保护。"
D.Strings[2509]="部落的将军死了！"
D.Strings[2510]="联盟的将军死了！"
D.Strings[2511]="嗨，小心那头科多兽！你最好在我寄予你信任之前看好这头野兽！"
D.Strings[2512]="那只科多兽真美。等等，我的眼镜在哪儿？也许你该帮我照看这头野兽。"
D.Strings[2513]="啊……科多兽令人惊奇的声音。我喜欢它们震动地表的方式……帮我照看这些野兽。"
D.Strings[2514]="地精是如何把包裹放到这些野兽身上的，他们是怎么做到的？科多兽比他们大十倍！"
D.Strings[2515]="现在是危险时期，冒险者。多加小心。"
D.Strings[2516]="你好！是什么吸引你来到冬泉谷？这片寒冷广袤的土地或许显得有些凄凉，但是它蕴含着无数的秘密……"
D.Strings[2517]="真让人感到悲痛……但是覆水难收……"
D.Strings[2518]="跟灰谷梅伊瑟娜岗哨的哨兵奥奈雅谈谈，她将为你今天的勇敢行为给予相应的回报。"
D.Strings[2519]="联盟胜利了！"
D.Strings[2520]="部落胜利了！"
D.Strings[2521]="坐下来听听我的故事吧，$r。"
D.Strings[2522]="记住，我需要你的帮助来正确进行吟唱。我在我们前进的路上会请你帮好几次忙，所以请准备好。"
D.Strings[2523]="这蓝色的亮光……真奇怪。你认为它意味着什么？"
D.Strings[2524]="$g嗨，帅哥，你想去格罗姆高吗？我听说那里的丛林整日雾气腾腾的，也许我们可以一起度个短假，我让你看看真正的丛林虎怎么样？:来吧，参观一下奇妙绚丽的荆棘谷丛林。你可以在水晶般的蓝色海岸线上惬意地洗日光浴，而我却站在这难以忍受的高温下整天傻看着我的兄弟弗雷萨！尽情享受你的旅程吧！;"
D.Strings[2525]="将一枚硬币塞到首领手中，看看你会得到什么。我喜欢自己的工作。但是，如果我能设法让斯纳尔克重新分配给这个飞行点的话……那样就好了。但是我敢打赌，你到这儿来不是要帮我进行职业训练的，而是寻找地精飞艇前往幽暗城，对吧？那很好，因为它会停泊在我后面。如果你看见斯纳尔克，代我向他问好，行吗？"
D.Strings[2526]="请在我吟唱的时候点亮这个。"
D.Strings[2527]="就是这个地方。让我们点亮它。"
D.Strings[2528]="我们找到它了！"
D.Strings[2529]="现在该进行最后一步了，我们必须激活祭坛。"
D.Strings[2530]="我会阅读刻在石头上的字，而你必须想办法点亮它。"
D.Strings[2531]="发生什么了？看！"
D.Strings[2532]="已经很多年了……"
D.Strings[2533]="谁在女神的祭坛捣乱？"
D.Strings[2534]="女祭司,请原谅我们的闯入。我们不想造成任何伤害。"
D.Strings[2535]="我们只是希望知道枭兽为什么要守卫这片地区……"
D.Strings[2536]="Enu thora'serador。这是一片神圣之地。"
D.Strings[2537]="我们会给你看……"
D.Strings[2538]="恶梦终于结束了！达隆郡，原谅我吧！"
D.Strings[2539]="月爪枭兽逝去的灵魂专注地盯着你，就像等待发生什么事情一样。"
D.Strings[2540]="你战斗得很勇敢，精灵。我请你赐予我你身体和心灵的力量。"
D.Strings[2541]="灵魂专注地盯着你的眼睛，握紧你的双手。你感到一股热流抨击着身体，几乎无法站立。$B$B热流过后，你感觉身体中似乎充斥着熊的灵魂……让你更加坚定。"
D.Strings[2542]="我们都亲眼目睹了无数可怕的灾难，但是我们不能由此绝望。$B$B记住这些往事，总有一天，我们会进行报复的。"
D.Strings[2543]="我们再找下一个。"
D.Strings[2544]="我们必须继续前进。"
D.Strings[2545]="祭坛在发光！我们做到了！"
D.Strings[2546]="朝上看，Thara dormil dorah……"
D.Strings[2547]="这宝石曾允许与月神本人进行直接沟通。"
D.Strings[2548]="月神通过宝石传达着她无尽的智慧……"
D.Strings[2549]="宝石需要得到保护，于是我们就向女神求助。"
D.Strings[2550]="很快，我们眼前浮现出一种生物的幻象……它有猫头鹰的羽毛，同时也有熊的意志和力量……"
D.Strings[2551]="就在那天我们得到了枭兽。凶猛的守卫，女神派枭兽保护她所有的神圣之地。"
D.Strings[2552]="但是现在，枭兽已经变得更加凶猛，而且由于失去了女神的指引，它们很迷茫……"
D.Strings[2553]="它们毫无目的地游荡……但是很多枭兽又回到了它们曾经发誓要保护的神圣之地。"
D.Strings[2554]="枭兽天生具有魔力；这种力量是由女神赐予他们的。"
D.Strings[2555]="你要知道，无论身处何地，他们都会受他人委托，保护着某种重要的东西。"
D.Strings[2556]="记住我们向你展示的……"
D.Strings[2557]="谢谢你的帮助，$n。祝你探险顺利。"
D.Strings[2558]="我想呆在这儿，思考一下所见的事情。找到艾瑞拉斯并告诉他我们学到的东西。"
D.Strings[2559]="熊平静地注视着你，但是没说一句话。"
D.Strings[2560]="熊的灵魂平和的凝视着你。你听到了一个声音在对你讲话，好象是从熊那里传来，但是没有迹象表明这个动物在说话。$B$B“你好，我年轻的朋友。如果你是来找我寻求指引的，那么或许我能帮你找到你想要的东西。”"
D.Strings[2561]="我代表着使你成为一名年轻的德鲁伊的力量。年轻人，你得向我学习这力量，我也乐于传授给你。要是你愿意听从并理解的话，我将教你如何使用熊的灵魂。$B$B为了明白利用我的灵魂的含义，你需要了解躯体和心灵的力量的重要性。"
D.Strings[2562]="身体的力量能使动作充满力度，行动迅速。你必须在身体上和精神上一直保持就绪状态。熊的体型造就了它的力量，使它成为危险的对手。但是，熊的体型也限制了其身体的敏捷性和头脑的灵活性。你可以好好利用这点。$B$B你必须依赖熊的力量掌握利爪的使用方法。"
D.Strings[2563]="心灵的力量将给你采取行动的决心……基于明确的、直接的目的行动。保持平衡并不意味着自命不凡或是平庸陈腐。$B$B你必须表现出对信仰的决心，你必须愿意为此奋斗。母熊对幼仔有极强的保护意识，年老的熊也这样保护着它的洞穴。这就是决心，心灵的力量，如果你想要掌握利爪的使用方法，你就必须知道这一点。"
D.Strings[2564]="年轻人，还要看你是否准备就绪。当最终考验来临时，即使最聪明最年老的德鲁伊也无法真正地做好准备。$B$B你已经听到我的话了，你必须继续前进。记得我的嘱咐。某个时候你的能力将经受考验。你必须像熊那样勇敢面对自己的敌人——用身体和心灵的力量。年轻人，你得从战争中学习成长。去吧……带上我的祝福。"
D.Strings[2565]="你好，$c。欢迎你来到永夜港，还有整个月光林地。塞纳里奥议会欢迎所有尊敬大自然的权威和支配力的生灵。$B$B当你在这里的时候，请一定要保持所有事物的平衡。这里不喜欢受到打扰，而我们的看守所受的训练就是无条件地停止所有的敌对行为。"
D.Strings[2566]="你需要幻象吗？$B$B要是在执行任务的过程中幻象失效，回到我这儿来，我将重新对你进行伪装。$B$B如果你尽力而为还是失败了，别放弃！回到我这儿来。我将助你完成目标。"
D.Strings[2567]="努力保持所有事情的平衡性，$c。真正的和谐便在于此。"
D.Strings[2568]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B重申自己在这伟大的平衡中的地位总是无伤大雅的。作为这种平衡的守护者，我们必须努力保持清醒的头脑和坚定的信念。训练能使我们做到这一点。"
D.Strings[2569]="我想接受德鲁伊技能方面的训练。"
D.Strings[2570]="战争结束了，达隆郡的人民得救了。"
D.Strings[2571]="战争结束了，达隆郡的人民得救了。$B$B他们得救了，$n，这都归功于你。你是达隆郡的英雄。"
D.Strings[2572]="我的眼睛被黑暗所蒙蔽，但是你把我从邪恶的幻想中拯救出来。你救了我，$n。$B$B现在我求你……原谅我。"
D.Strings[2573]="塞纳留斯保佑你，$c。"
D.Strings[2574]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。"
D.Strings[2575]="即使在冰冷的石头墙内，就像庇护这座城镇的墙一样，人们仍旧可以找到宁静与和平。事实上，你可以在你所在的任何地方找到他们……只需在你体内寻找这种平衡。"
D.Strings[2576]="我们的工作就是保持平衡，如同塞纳留斯所教给我们的一样，$c。他就是指引我们前进的明灯，而我们必须竭尽所能保护它的光芒。"
D.Strings[2577]="欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，那我很高兴能训练你。$B$B如塞纳留斯教导我们的一样，我们一直都是平衡的保护者。永远不要忘记这点。"
D.Strings[2578]="再次感谢你，$n！我对我们所发现的东西感到很高兴。$B$B祝你好运！"
D.Strings[2579]="我准备出发了，$n。我需要一些帮助——你愿意跟我来吗？"
D.Strings[2580]="%s开始吟唱一个奇怪的法术……"
D.Strings[2581]="我不能训练你。"
D.Strings[2582]="我们代表的是黑暗，永恒而无形。"
D.Strings[2583]="你好，年轻的潜行者。你在找什么？"
D.Strings[2584]="我不能训练你。你必须去找你的职业训练师。"
D.Strings[2585]="我帮不了你，$n。我只训练潜行者。"
D.Strings[2586]="对不起，但是我只训练盗贼。"
D.Strings[2587]="啊……一名顾客！看看我最伟大的发明，贸易机器人1000型！它拥有你所需的一切商品……其中的一些稀有物品更是在卡利姆多的其它任何市场上都找不到……更不用说它的设计不支持任何讨价还价的废话了，因此你看到的价格就是你要支付的价格。"
D.Strings[2588]="毫无疑问，你是黑暗女王派来接受训练的又一个无能的白痴。$B$B<纳萨诺斯叹息着。>$B$B我每次都得把你们的尸体运回去给她，我想这次也不会有什么例外。$B$B但是，我并不会问什么，我只按照黑暗女王的吩咐办事。"
D.Strings[2589]="让我看看你提供的东西。"
D.Strings[2590]="今天碰巧是你的幸运日；我完成了超级商人680型的维护工作，因此有大量物品以超低的价格出售。你自己去看看吧……我的兄弟考克认为他的贸易机器人1000型会胜过我的。"
D.Strings[2591]="我可以为你效劳吗，$n？"
D.Strings[2592]="我想接受潜行者的训练。"
D.Strings[2593]="你能训练我使用潜行者技能吗？"
D.Strings[2594]="你是来学习的吗？"
D.Strings[2595]="当然，我有。教给我吧。"
D.Strings[2596]="你看我像是个$c吗？在我决定用你的血洗我的刀之前，赶紧逃吧。"
D.Strings[2597]="你好，朋友。愿黎明在这个乱世之中保佑你平安无恙。"
D.Strings[2598]="我的规划是不允许减少任何项目的成本的。"
D.Strings[2599]="我很好奇这样一台机器能为我提供什么。"
D.Strings[2600]="在驾驭过一头受过良好训练的山羊之前，就别夸口说你已经拥有了真正的坐骑，我的朋友。请随意看看这些杰出的坐骑吧。它们会让你满意的，相信我。"
D.Strings[2601]="我是自动售货商的最新形态……我们总有一天会统治这个世界的……别告诉老板我从他的商品中榨取钱财……"
D.Strings[2602]="多年的精心饲养和细致的品种培育使我能够有机会向你展示这些良种马。请慢慢挑选，马是你长期的伙伴，朋友。不要把自己低估了——今天就在这里找到你想要的马！"
D.Strings[2603]="在狩猎之前最好问问你要找什么猎物。"
D.Strings[2604]="看看这些科多兽，我的朋友！它们幼年时便开始接受训练，在莫高雷的金色平原长大，这些家伙就是我们出色的坐骑！看看它们吧，看看我们牛头人为什么会依赖于这些强大的生物！"
D.Strings[2605]="欢迎来到塞纳里奥议会，$c。"
D.Strings[2606]="让我传授你猎人的技艺吧。"
D.Strings[2607]="我有许多知识可以让你大开眼界，$c。你必须学会带着荣耀去狩猎。"
D.Strings[2608]="我是来接受培训的。"
D.Strings[2609]="我用祖先传下来的方法训练猎人。"
D.Strings[2610]="我需要培训。"
D.Strings[2611]="牛头人热衷于狩猎，这是流淌在我们血液中的灵魂。"
D.Strings[2612]="我是一名猎人，我想接受训练。"
D.Strings[2613]="很高兴我能代表皇家药剂师协会为你提供最好的战马。这些战马与我们一样经历过考验和磨难，现在它们已经远胜于那些血肉之躯所铸成的战马了，它们更为强壮，更易恢复精力！好好看看它们吧。"
D.Strings[2614]="来学习猎人之道吧。骄傲，荣誉，还有传统。"
D.Strings[2615]="我可以教你骑山羊的技巧，只要你有足够的金币支付学费！"
D.Strings[2616]="我按照传统一代代地训练、指导年轻猎人。"
D.Strings[2617]="我可以教你操纵机械陆行鸟的技巧，只要你有足够的金币支付学费！"
D.Strings[2618]="我可以教你骑马的技巧，只要你有足够的金币支付学费！"
D.Strings[2619]="我可以教你骑豹的技巧，只要你有足够的金币支付学费！"
D.Strings[2620]="我可以教你骑科多兽的技巧，只要你有足够的金币支付学费！"
D.Strings[2621]="我可以教你骑迅猛龙的技巧，只要你有足够的金币支付学费！"
D.Strings[2622]="我可以教你骑骸骨战马的技巧，只要你有足够的金币支付学费！"
D.Strings[2623]="我可以教你骑狼的技巧，只要你有足够的金币支付学费！"
D.Strings[2624]="谢谢你，$n。现在让我们离开这儿！"
D.Strings[2625]="我们成功了！再次感谢你！我先走了！"
D.Strings[2626]="要教你学会驾驶机械陆行鸟，那简直就是在浪费我的金钱和时间，$c。你的体形太庞大了！"
D.Strings[2627]="我想接受骑术训练。"
D.Strings[2628]="嗨，霍恩尼兹！我回来了！有些好心人帮我脱离了困境。"
D.Strings[2629]="我们不得不把玛洛迪半人马从我们的合作伙伴列表中划掉。他们太难共事了……"
D.Strings[2630]="好吧，我要到吉尔吉斯村去了。他们不像玛洛迪半人马一样蠢，而且他们更加通情达理。"
D.Strings[2631]="记住，所有的事物都是有关联的。如果陆地上的野兽灭绝，我们的种族将在孤独中死去，因为牛头人和野兽的命运是相通的，而艾泽拉斯的命运和所有艾泽拉斯上的生灵的命运也休戚相关。"
D.Strings[2632]="如果你是来接受狩猎技巧训练的，那你就来对地方了！"
D.Strings[2633]="嗨！?从来没有过深海潜水的经历吗？我告诉你一个小秘诀，嗯。在海洋深处有许多冒气泡的裂缝，当你在水下时可利用这些气泡进行呼吸。这个秘密只限于你我之间。对我来说，贝壳到处都是……如果你懂我的意思的话！"
D.Strings[2634]="不……不可能！等一下……我投降！我投降！"
D.Strings[2635]="请训练我吧。"
D.Strings[2636]="守护符文被摧毁了！兄弟们，杀掉这些入侵者！"
D.Strings[2637]="你不是德鲁伊！"
D.Strings[2638]="你想乘坐塞纳里奥议会的免费航线飞回鲁瑟兰村吗？"
D.Strings[2639]="要是你想要飞回雷霆崖，就该跟我的牛头人搭档布瑟恩·草风谈谈。"
D.Strings[2640]="你需要乘坐塞纳里奥议会的免费航线飞往雷霆崖吗？"
D.Strings[2641]="如果你想飞回鲁瑟兰村，就该找暗夜精灵希尔瓦·菲纳雯斯谈谈。"
D.Strings[2642]="我们所处的这个时期就像风云般变化无常，$c。大地正在痛苦中战栗，哀嚎。我们必须坚定地站稳脚跟，才能避免被这股混乱的漩涡吞噬。"
D.Strings[2643]="艾泽拉斯中没有哪一个种族经历过我们的人民所受的磨难，$c。面对死亡仍安之若素已经成为我们的第二天性了。"
D.Strings[2644]="准备好。今天，我们将以我们伟大的大地之母的名义，教导这些野猪人学会懊悔、悲哀和恐惧。"
D.Strings[2645]="啊，幽影谷的美景永远使我感到快乐！"
D.Strings[2646]="你看见一个穴居人，也就相当于看见了所有穴居人。"
D.Strings[2647]="你好！你看起来挺强壮的。我们这里的卫兵数量不太够，你愿意帮忙吗……"
D.Strings[2648]="艾萨拉地区。"
D.Strings[2649]="我对暗夜精灵的了解有限，但是据说很早以前——当暗夜精灵还掌握着神秘法术时——艾萨拉便是其中的佼佼者，她年轻美貌，是暗夜精灵的女王。不幸地是，正是她对魔法的痴迷才导致历史上最具破坏性事件的发生。"
D.Strings[2650]="埃达拉斯废墟。"
D.Strings[2651]="北方的魔法塔。"
D.Strings[2652]="我感到前方有危险。"
D.Strings[2653]="我的背部痛死了。"
D.Strings[2654]="这些命令必须传达到大将军阿比迪斯那里！"
D.Strings[2655]="要是我遇难的话，拿着我的背包。一定要将它送到大将军手上。"
D.Strings[2656]="木喉熊怪"
D.Strings[2657]="蓝龙现身"
D.Strings[2658]="你帮助了我，我会告诉我所知的这片土地和生物的情况。我所了解的并不多，但是我可以告诉你一些你可能感兴趣的事儿。"
D.Strings[2659]="上层暗夜精灵曾经统治这座城池，他们在此演练威力强大的奥术。现在他们受到诅咒，灵魂在这片土地上游荡，恶鞭军官纳迦侵占了精灵的城市。纳迦一定在废墟中搜寻那些上层精灵的神器。"
D.Strings[2660]="一个强大的人类魔法师传闻就在北部生活；他为了某种不为人知的原因一直在看守着那片大地。我自己没有亲自去过，但是据说访问者在那里很受欢迎，如果他们愿意为他办些差事的话甚至可以赢得他的好感。"
D.Strings[2661]="过去数年来，我目睹了熊怪所经历的种种可怕的事情——它们成为战场上的无辜受害者。但是我不清楚这个部落现在怎么样了。它们被席卷费伍德森林的天灾腐化了吗？或许它们对自己曾经和平的民族所遭遇的一切表示愤怒，正试图自我保护？无论如何，它们中的大多数对进入这片领域的人都会表现出敌意。"
D.Strings[2662]="蓝龙玛里苟斯不在那儿，但是他的信徒在。我不清楚这是怎么回事，但是我可以告诉你：蓝龙所在的地方都有希望找到神秘的魔法。如果说龙人在这儿保护某种东西的话，我是不会感到惊讶的……或许是上层精灵遗漏的物品。"
D.Strings[2663]="我应该寻求某些帮助；我不喜欢整天坐在这儿卖鱼。我更愿意去钓鱼，然后再卖掉。"
D.Strings[2664]="你好, $c。我今天情绪很差，所以除非你能帮我，否则我更愿意自己呆着。"
D.Strings[2665]="可笑的凡人！在烈焰之子面前灰飞烟灭吧！"
D.Strings[2666]="我不能训练你，$c。"
D.Strings[2667]="我是奥塞斯·拉克摩尔，豪侠轮船的船长。这是最近几天轮船的航行日志。$B$B我们的船只满载货物驶向羽月要塞，纳迦袭击了船只一侧。我们赶走了他们，但是我们知道他们会回来的。我担心纳迦会毁掉我最宝贵的财物，因此我将豪侠驶向远离凄凉之地的一座小岛，岛上全是古老的暗夜精灵建筑废墟。我将自己的宝箱放在了岛上。"
D.Strings[2668]="继续读下去……"
D.Strings[2669]="我的箱子设计独特，需要两把钥匙来开锁，一把金钥匙和一把银钥匙。我将银钥匙给了我的大副，自己保留了金钥匙。$B$B但是我们注定会失去它们。在一次纳迦发动的袭击中，我丢了钥匙；而后，龙虾人攻击了我们，将大副推入了深渊。$B$B我想钥匙一定在纳迦和龙虾人那儿。还好这两方是敌人，不会共享钥匙的。"
D.Strings[2670]="在龙虾人的进攻后，我们知道下一次豪侠是无法幸免于难的。于是我和几个幸存的水手弃船逃生。$B$B我们现在上岸了并很快就会向尼耶尔前哨站游去，但是在到达避难所之前我们还有很多危险，而且我害怕凄凉之地会吞噬我们。$B$B我现在写下这些是希望有人能知道我们的困境，有一天能把那些带给我们灭顶之灾的水中魔鬼杀死为我们报仇。"
D.Strings[2671]="对我们这些在月光林地塞纳里奥议会的人来说，雷姆洛斯神殿是个神圣的地方……所以请你的表现符合访客的身份。$B$B我想你不愿让我用弯刀杀死你，那就是了。"
D.Strings[2672]="愿塞纳留斯庇护你，我的$g兄弟:姐妹;。$B$B我是塔加里，神殿的保卫者。能够作为这片神圣大地的看守来服侍守护者雷姆洛斯是我的荣耀。"
D.Strings[2673]="在亡灵天灾来临之前，我是一名大商贩。我出售所有商品。所有！$B$B价钱都极其便宜！$B$B你随便问问那些没死的人，看看我说的是不是真的。"
D.Strings[2674]="嗨$n！你是来购物的，还是来出售物品的？$B$B如果有比这儿更便宜的物品，我就不叫被感动的奥古斯图斯！"
D.Strings[2675]="是的，奥古斯图斯。我想做生意。"
D.Strings[2676]="这是个危险的地方，$n。要小心。"
D.Strings[2677]="死吧，你这卑鄙的家伙！"
D.Strings[2678]="别浪费我的时间，$c。"
D.Strings[2679]="我不训练你这样的$c。在你惹恼我之前找你自己的训练师吧。"
D.Strings[2680]="放轻松点。我只训练战士。"
D.Strings[2681]="我可以为你效劳吗?"
D.Strings[2682]="由于职业的不同，因此我对你缺乏技能的现状无能为力。"
D.Strings[2683]="很好！你达到了要求的参数和规格。我可以为你做些什么吗？"
D.Strings[2684]="你为什么要唤醒我，埃克索图斯，为什么要打扰我？"
D.Strings[2685]="海格纳·重枪，愿为你效劳！"
D.Strings[2686]="虽然塞拉摩以它特有的武士培训闻名，我恐怕还是不能帮你。"
D.Strings[2687]="你与塞拉摩卫兵一起训练过吗？"
D.Strings[2688]="是的。"
D.Strings[2689]="我的孩子，我能为你做什么？"
D.Strings[2690]="我不能训练你这样的$c。"
D.Strings[2691]="我想接受猎人技能方面的训练。"
D.Strings[2692]="我不能训练你，年轻人。"
D.Strings[2693]="炎魔之王和他的兄弟们曾经统治整个世界。作为上古之神的一名仆从，他与泰坦争夺这个星球的统治权。获胜的泰坦将我的主人和他的兄弟们放逐到元素神域——他们被关押在那儿直到时间尽头。"
D.Strings[2694]="我不具备你想学的知识。"
D.Strings[2695]="我可以为你做什么?"
D.Strings[2696]="我无法训练你。你该去找$c训练者。"
D.Strings[2697]="不要浪费我的时间。"
D.Strings[2698]="嗨，你需要继续前进，去找$c训练师。"
D.Strings[2699]="拉格纳罗斯，炎魔之王！他比这个世界本身还要古老，在他面前屈服吧！在你们的末日面前屈服吧！"
D.Strings[2700]="教我灵魂的行事方法。"
D.Strings[2701]="灵魂引导你来到我这儿。我要怎么帮你？"
D.Strings[2702]="是因为这些入侵者，我的主人！他们闯入了您的圣殿，想要窃取您的秘密！"
D.Strings[2703]="蠢货！你让这些不值一提的虫子进入了这个神圣的地方？现在你还将他们引到了我这里来？你太让我失望了，埃克索图斯，你太让我失望了！"
D.Strings[2704]="灵魂与你永在，孩子。我能为你做些什么？"
D.Strings[2705]="愿灵魂保佑你。"
D.Strings[2706]="你去哪儿？如果你想快些到那里，那就别犹豫了！"
D.Strings[2707]="我会尽量保证哨兵岭物资供给的，要维持这项行动可不容易。"
D.Strings[2708]="啊，$g牧师:女牧师;，你来的正是时候。谢谢你。"
D.Strings[2709]="谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些鱼人了！"
D.Strings[2710]="仅在三百年前，一个叫作索瑞森的鲁莽的矮人从他炽热的领地中召唤出了魔王。他重返这个卑微的世界吞噬了周围的田地并形成了这个火山之核。从那以后，强大的拉格纳罗斯就沉睡在了这座山下。"
D.Strings[2711]="你还想说什么？"
D.Strings[2712]="作为忠实的仆从，我们会听从他的命令，执行他的铁血政策的。没有了强大的领域实权，拉格纳罗斯不过是他自身的傀儡罢了。但是，他拥有足够的力量与你抗衡。"
D.Strings[2713]="你好，$g先生:女士;。我想握你的手，但是如你所见，我正忙着做事。我可以帮忙吗？"
D.Strings[2714]="你有了一个好的开始，但是你要学的还有很多，$n。"
D.Strings[2715]="你已经学会了我能教给你的所有东西，$n。如果你还想继续学习的话，去找暴风城法师区的暗夜精灵莉琳希亚·夜风谈话。我听说她是个好老师。"
D.Strings[2716]="虽然我被关在这间小屋里，但是我梦想着加入城墙外激烈的战斗。然而，职责迫使我为替我战斗的那些人传授知识……"
D.Strings[2717]="Ishnu-alah，$g兄弟:姐妹;。你有外面的消息吗？我希望得到泰达希尔的消息。"
D.Strings[2718]="我很荣幸能够传授给你知识，$n。看得出来你用得不错。"
D.Strings[2719]="你必须找一个更有经验的老师，因为你已经超越了我的能力了。我建议你找这里的莉琳希亚·夜风谈谈：她有更多知识可以传授给你。"
D.Strings[2720]="现在轮到你们了！你们愚蠢地追寻拉格纳罗斯的力量，现在你们即将亲眼见到它！"
D.Strings[2721]="德鲁伊们说大自然把部落从卡利姆多赶出去只是个时间问题。然而堕落继续在我们的大地上蔓延，甚至在泰达希尔这里也是。"
D.Strings[2722]="干得好！你对药剂的理解进展不错。"
D.Strings[2723]="不幸的是，对于拥有像你这样经历的人来说我没有什么可教的，我的朋友。找到暗夜精灵希尔瓦娜·林月，她住在达纳苏斯的工匠区。"
D.Strings[2724]="赞美艾露恩，我的$g兄弟:姐妹;。欢迎来到这里。"
D.Strings[2725]="人们从森林植物中制造的东西难道不令人震惊吗？说真的，月神对我们已经很慷慨了。"
D.Strings[2726]="不幸的是，对于拥有像你这样经历的人来说我没有什么可教的，我的朋友。去找暗夜精灵希尔瓦娜·林月，她住在达纳苏斯的工匠区。"
D.Strings[2727]="是我亲爱的恋人卡利派你来找我的？她可是我的宝贝。"
D.Strings[2728]="没想到你会来这儿找我的可爱的卡利谈话。很好。这是药水。有没有人说过你是个头脑简单的家伙？"
D.Strings[2729]="我教不了你，$n。去找塔雷·浆泡；她是一个侏儒，住在铁炉堡的侏儒区。哦，既然你反正要去，请把我的爱带给卡利。"
D.Strings[2730]="别被那些天真的大眼睛欺骗了。塔雷是个专家，我每天都在学习新知识。你认为我为什么会在侏儒区？你看我像个工程师吗？啊，我可不这么想。"
D.Strings[2731]="$g小伙子:姑娘;，努力吧。苦干和决心——那就是成功之道！书本知识是远远不够的。"
D.Strings[2732]="哦，我不能教给你什么，$n。跟塔雷·浆泡谈谈。她几乎够不着桌子，但是当她在配制药水时，你得看仔细了！"
D.Strings[2733]="你看起来像是个喜欢冒险的人。而我，自从我们巨魔来到这里我就受够冒险了。现在我每天都是既来之则安之，而且我为自己训练其他家伙处理冒险的经历。"
D.Strings[2734]="准备好接受下一次训练了吗？好吧。首先，你得放松。随意搅动药水就可以了。"
D.Strings[2735]="你的问题我都回答不了，$n。你需要与奥格瑞玛暗巷区的兽人耶尔玛克谈谈。他会帮你的。"
D.Strings[2736]="桌上的所有瓶子中都盛有今天配制好的药水。心急吃不到热豆腐。哈哈！"
D.Strings[2737]="他们说我愚蠢，我要证明自己的实力。我要关注所有的罐子，证明它们都能煮东西。我的好运就要来了！谁是愚蠢的人，嗯？嗯！？"
D.Strings[2738]="不能帮你。你比我更懂药剂。还有，我还要看着罐子。去找那边的Yelmak谈谈。他懂得很多药剂的知识。"
D.Strings[2739]="本娜就像着魔一样工作。她日以继夜地调制这些药剂，不吃不睡。我知道我们的亡灵盟友需要帮助，但是我担心她这样会伤身体的。"
D.Strings[2740]="在我首次开始配制药水时，我一定打碎过成百个瓶子。我笨手笨脚，瓶子在我手中极易破碎。希望你比我更为小心。"
D.Strings[2741]="你学习的能力已经超过我了。你需要找那边的本娜·冰蹄谈谈以获得更多指示。但请不要占用她太多时间。她需要休息。"
D.Strings[2742]="能看到一张友善的脸真不错。我没有跟药剂师乔汉聊过很多，除非他想要什么东西。他离开坟墓太久了。有一天我也会像他一样，我听说。真可怕。或许到那时我就不在乎了。"
D.Strings[2743]="你是来学习配制药水的？我能传授给你很多知识。虽然我已年老力衰，但脑子还是管用的。"
D.Strings[2744]="我很珍惜我们之间的友谊，但是让我们面对现实吧：你对药水的了解比我多。要是你想得到训练的话，就找亡灵马尔什医生谈谈。他居住在幽暗城的炼金房。"
D.Strings[2745]="这是真的，我曾经是人类。缺点是可能转换为我们的优势的，$n，因为我对人类的劣势了如指掌。"
D.Strings[2746]="很好。从这些标本上再切下一块肉来。让我们看看你学到了什么，我们可以由此开始。"
D.Strings[2747]="你对药剂的知识已经远胜于我，但你还有很多要学的。上楼去到东南面见见马尔什医生。他会交给你真正的苦痛——啊咳。他是一个被遗忘者，他能进一步训练你。"
D.Strings[2748]="别那样看我。我也许跟你不同，我不是个冒险家，但是这并不意味着我的力量比你小。忙碌的生活会让你的手臂变得强壮的。"
D.Strings[2749]="我没有什么可教你的了。但是，我听说有位名叫安尼希尔的暗夜精灵也许能教你。她居住在达纳苏斯的工匠区。"
D.Strings[2750]="很抱歉，$n，但是我可不在新手身上浪费时间。你得找一个跟自己技能相近的人。去达纳苏斯的工匠区找一个名叫米拉·法拉科纳的暗夜精灵。"
D.Strings[2751]="你需要我的帮助？可以。你需要什么？"
D.Strings[2752]="别被沃萨亮晶晶的眼睛和浓密的胡须愚弄了。他是个很有才能的学徒，也是个很好的朋友，即使我在跟他谈话时颈部有些痉挛。"
D.Strings[2753]="嗯，我能教的你已经都学会了。或许你该找其他人谈谈了。试一下达纳苏斯工匠区的暗夜精灵安尼希尔。她确实很有智慧！"
D.Strings[2754]="那很好，$n。无论那是什么，去拿给那边的沃萨看看。他会回答你的任何问题。"
D.Strings[2755]="你是谁？为什么骚扰我？哦，是啦——你是学生吧。是的。我能为你做什么吗？"
D.Strings[2756]="和平也与你同在, $n。你是来寻求知识的吗？"
D.Strings[2757]="教学不只是一项单边活动，$n。当我教你时，我自己也在学习，而我的理解也在加深。"
D.Strings[2758]="虽然我很高兴听到你对我的能力充满信心，但我真的没法再教你了。你必须到达纳苏斯的工匠区去找暗夜精灵安尼希尔谈谈。她可以帮助你。"
D.Strings[2759]="即使轻微地改变药剂的成份也能使它发生根本的变化。耐心和精确，年轻人：他们会让你在所有行业都受益匪浅。"
D.Strings[2760]="我制造药剂的技能在你之下。你应该与那边的安尼希尔谈谈。她会明白你需要进一步的培训。"
D.Strings[2761]="啊，又回到年轻的时候了，还有第一次发现药剂的时候。谢谢你恢复我的记忆，$n。去跟那边的米拉·法拉科纳分享那份年轻的热情吧。"
D.Strings[2762]="我已经用多年学会了很多药剂知识，$n，而那些知识都由你支配。你只需提要求就可以。"
D.Strings[2763]="我很忙，$n。告诉伍特去处理一切。那个年轻人整天都焦虑不安的。他大部分时间都处于这种状态，像是要做些什么。"
D.Strings[2764]="见到你是我的荣幸，$n，但是你在配制药水方面比我厉害。去幽暗城 炼金房找亡灵赫伯特·哈尔希医生。他能帮助你。"
D.Strings[2765]="你找错兽人了。我不训练新手。去问问那边的小伍特……谦虚一点。"
D.Strings[2766]="另一名学生，是吗？好吧。我看看有什么能帮助你的。"
D.Strings[2767]="格里克斯和我达成一项共识：他给我供货，而我给他钱。这是很认真的！那个海盗为了一小袋皱皱巴巴的皇血草收我多少钱……足够把一个成年的地精弄哭了。"
D.Strings[2768]="我有许多处方可供选择，我还可以为你打折！"
D.Strings[2769]="你做得比我要好！你需要一个经验比我还要多的人。那就是安尼希尔，一个在达纳苏斯工匠区生活的暗夜精灵女士。"
D.Strings[2770]="第一次看见亡灵时，我哭了，我无法想象他们的恐惧和孤寂。大地之母在我耳边吟唱，她告诉我：“拯救他们吧。”"
D.Strings[2771]="你难道感觉不到大地母亲为了她所丢失的孩子，也就是亡灵们，而出现的苦恼吗？快些说，$n。每一秒对我都很珍贵。我们必须帮他们找到回归她身边的路！"
D.Strings[2772]="当我们的盟友，也就是亡灵们，在遭受可怕苦难时候，我如果还在这里训练新手，这会让我感到良心不安。请找那边的克瑞谈谈；他目前能够帮你。"
D.Strings[2773]="你制造药剂的技术已经在我之上。去幽暗城的炼金房找亡灵赫伯特·哈尔希医生。他可以继续你的训练，而你也可以亲眼目睹他的人民所遭受的苦难。"
D.Strings[2774]="又来打扰我了。像这样我还能做什么工作么？不用回答，我看起来像是很在乎你的回答么？如果我们要把这个地方打理干净，并继续扩展我们的帝国，我就需要绝对的安静！"
D.Strings[2775]="要我训练你？别开玩笑了——我们都知道这是不可能的。我可无法胜任。你要是想接受训练的话，就去幽暗城的炼金房找亡灵赫伯特·哈尔希医生吧。"
D.Strings[2776]="别浪费我时间。我从事研究的时间比你的年纪还要大。去跟幽暗城炼金房的亡灵马丁·费尔本谈谈。他或许能传授给你一些基础知识。"
D.Strings[2777]="又一个学生。棒极了。正因为如此，所以在林度恩进入管理阶层的时候，我仍然在坚持作一名教师。只要我再获得一枚教学奖章，我的美名便不会被人所遗忘了。"
D.Strings[2778]="有奥格诺恩提供所需的供应，我可以不用寻找一株草药就能完成在这里的任务。如果我永远都不用再次看到自然的奇迹，这就不会很快发生。"
D.Strings[2779]="我没有可传授给你的知识了。穿过拱门走下斜坡到东南方，找赫伯特·哈尔希医生谈谈。他是个被遗忘者，他能教给你更加高级的技术。"
D.Strings[2780]="你如此大胆地跑来找我，想要接受训练，我对此可不高兴。穿过拱道，沿着坡道向东南方走，跟亡灵马丁·费尔本谈谈。他能教你一些基础知识。"
D.Strings[2781]="到这儿来学习的吗？很好。我想要是我教你的话，你不会对我们的联盟造成太多的伤害。只要你一心对付我们的敌人。"
D.Strings[2782]="虽然每次我都使用了相同的成分，但配制出的药水似乎都达不到预期的治疗效果。这只能得出一个结论：植物发生了变化。我还不清楚具体原因。"
D.Strings[2783]="现在你该找一位更加渊博的老师了。在菲拉斯的羽月要塞居住着暗夜精灵凯兰娜·风语。她有聪明的头脑；毫无疑问她能继续教你。"
D.Strings[2784]="你制造药剂的技能需要再高超一些才能当我的学生。在此期间，在那边的希尔瓦娜·林月或米拉·法拉科纳可能会帮助你。"
D.Strings[2785]="你的培训进展很好。你该为你的成就感到自豪。"
D.Strings[2786]="我和我的同伴正在收集我们所知的素材，并测试它们的效果。一旦我收集齐备，我将制造出这世界前所未有的药剂。"
D.Strings[2787]="难以置信。你配制药水的技能已经能跟我匹敌了。我不能再训练你了，去悲伤沼泽找斯通纳德的兽人罗格瓦尔谈谈。他以他的宝刀而闻名。"
D.Strings[2788]="你的技术太差了，还不能跟我学习。去跟那边的马丁医生谈谈，或者爬上斜坡到东南方去看看马尔什医生。他们是被遗忘者，可以给你所需的训练。"
D.Strings[2789]="准备好接受训练了？保持速度，$n。我们要走的路还长着呢。"
D.Strings[2790]="从前我欢迎过黑暗，因为它是夜晚的姐妹。现在总是漆黑一片，甚至在白天也是这样，而森林迫切需要给养。除非我们快些行动，否则这扩散的瘟疫就会遍布整个世界。"
D.Strings[2791]="你是来接受药水配制这一技能的训练的吗？要是你认为能从我这儿不费吹灰之力地学到东西的话，你就大错特错了。走吧，在你没有掌握更高技能之前别来找我。"
D.Strings[2792]="你的技能显示你一直喜爱我们的艺术，但是我想看到你所做承诺的进一步证据。我会分配给你一项任务。完成它就会令我满意。"
D.Strings[2793]="卡拉然，我把火炬弄丢了。给我一个新的吧。"
D.Strings[2794]="萨尔酋长派我到这儿来，我感到非常荣幸。我并不奢求能被派往比斯通纳德更好的地方，我只想找些生长在这儿的草药。"
D.Strings[2795]="嗯，好吧，我看到你还懂一点做药剂的方法。然而，你是否配做我的学生仍有待察看。我有一项任务交给你。争取给我一个好印象。"
D.Strings[2796]="你胆敢让我培训你，你这可怜虫？你期望什么，你这个呆头呆脑的乡巴佬，一场关于如何正确使用银叶的讲演？滚出去！你浪费我的时间没把你打个半死算你走运。"
D.Strings[2797]="谢谢你！谢谢你，$g牧师:女祭司;。有了月神的庇护，我就可以对抗那些堕落的树精了！"
D.Strings[2798]="再见，愿月神与你同在。"
D.Strings[2799]="谢谢！谢谢你，$g祭司:女祭司;。有了你的力量我就可以继续作战了！"
D.Strings[2800]="再见了，愿我们的祖先永远保佑你！"
D.Strings[2801]="谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些雪怪了！"
D.Strings[2802]="再见，愿光明与你同在。"
D.Strings[2803]="谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些豺狼人了！"
D.Strings[2804]="再见，愿暗影永远保护你！"
D.Strings[2805]="只需做些小调整……搞定！"
D.Strings[2806]="要是我能的话，我是会训练你的，但是你需要找个稍微……怎么说，聪明点的人为你服务吧！去铁炉堡找特里克希吧。告诉他是布隆克派你去的！"
D.Strings[2807]="想成为工程师，是吗？嗯，穆拉丁保佑你，你来对地方了！"
D.Strings[2808]="我的旋转诱饵在哪儿？我刚刚还把它放在这附近的……"
D.Strings[2809]="你目前的智能超出了我的指导能力。你该找我在铁炉堡的侏儒同伴特里克希询问一下！"
D.Strings[2810]="我很高兴能在你事业开始的时候帮上忙，！让我们抓紧纺纱机，开始吧……"
D.Strings[2811]="我听说新型的极速6000型很快就要开下生产线了。我几乎不能抑制激动的心情！"
D.Strings[2812]="呃……虽然我不愿承认，但是你要想继续训练的话就必须跟我的姐妹谈谈。目前来说……我知道的没她多！她乘坐火箭车四处巡查。"
D.Strings[2813]="我愿意教你！要让我的姐姐看看她不是唯一了解工程学的人……"
D.Strings[2814]="你好！我的名字是洁娜！你呢？"
D.Strings[2815]="哦，你还有很多东西要学。我会教给你我所学的全部知识，但是我自己也在学习！你为什么不找铁炉堡的特里克希谈谈，她会帮你进修的！"
D.Strings[2816]="你想学习？跟着我？太棒了！唯一比装配子弹和炸药装置有趣的事情就是与别人分享那种知识！我们开始吧！"
D.Strings[2817]="啊，多么美好的一天啊！真该炸点什么东西。"
D.Strings[2818]="你需要开始学习一些我的专门技术之外的东西！跟那边帐篷前面的利廉姆·火轴谈谈。他会让你步入正轨的！"
D.Strings[2819]="这种工作胆小鬼做不了的。我有个叔叔丢了一只手！可怜的老胖子……无论如何，如果你还感兴趣我或许能给你看些东西？"
D.Strings[2820]="什么？你要什么东西？"
D.Strings[2821]="我不能帮助你！你会遇到比我更精于此道的人！你是联盟的人，你得跟暴风城的利廉姆·火轴谈谈。"
D.Strings[2822]="是的，我有些东西要给你看看。我们来看一下你做得怎么样，或许你会令我吃惊的！"
D.Strings[2823]="（吸气声，吸气声）你闻到了吗？你难道不是只喜欢油脂的气味吗？"
D.Strings[2824]="恐怕你得离开我了，朋友！你该去找奥格瑞玛的诺格，他将带你进入下一阶段!"
D.Strings[2825]="我希望组建队伍。当然，我更希望扩大队伍！"
D.Strings[2826]="你知道谁能真正让你开阔见识吗？诺格！去奥格瑞玛可以找到他。"
D.Strings[2827]="我知道一些。要我告诉你吗？"
D.Strings[2828]="谁说兽人不聪明？当工程师可是很费脑筋的！"
D.Strings[2829]="你知道谁是真正聪明的人吗？诺格！甚至比我还要聪明。你去告诉诺格是桑德派你来的！你可以在那边的控制台那里找到他。"
D.Strings[2830]="你认为你很聪明吗？你认为你得到了吗？让我们查明真相！"
D.Strings[2831]="黑暗女王说过，在这场战争中，知识是我们最强大的武器。"
D.Strings[2832]="你准备好迎接更大的挑战了！见见我右边的弗兰克林·洛伊德。从现在开始他会指导你。"
D.Strings[2833]="工程学能赋予你瓦解敌人的技能和知识！让我教你该如何做……"
D.Strings[2834]="我忙死了，不会跟陌生人讲话的！几乎从来不……"
D.Strings[2835]="你在努力上进……现在甚至已经超过我了！你应该与铁炉堡的宾斯匹德谈话！（他会？她会？）让你见识那些我所做不到的！"
D.Strings[2836]="我可以教你一些诀窍……如果你不介意先帮我做些事情的话。"
D.Strings[2837]="嗯……好吧，我现在还帮不到你！你必须先学习基础知识。你为什么不去见见暴风城的斯普莱特呢！"
D.Strings[2838]="太棒了！难道你不是一个勤奋的人吗？好的，让我们开始吧，行吗？"
D.Strings[2839]="让我看看……14加7，得1进2……是吗？"
D.Strings[2840]="嗯，你学得速度蛮快的！我没法教给你所有知识，但是宾斯匹德是可以的！你可以在铁炉堡中找到他。祝你好运！"
D.Strings[2841]="成交！我会将我所知的传授给你，但是你首先得执行一个小任务……"
D.Strings[2842]="你总有一天能跟我学习……但现在还不是时候！为什么不先跟站在我右边的斯普莱特聊聊呢。入门之后再来找我！"
D.Strings[2843]="你当然不会失望!现在既然我们已经把那个清除掉,你可以下达指令了!"
D.Strings[2844]="我的二十英尺高的火鸡烤肉架的计划快要完成了！现在我需要的就是一只二十英尺高的火鸡了……"
D.Strings[2845]="不要告诉任何人我说过，就当我什么都不知道！如果你还想学习，你应该与店主宾斯匹德谈谈。"
D.Strings[2846]="在我袒露秘密之前，你得证明自己的价值！我会对你进行测试的。"
D.Strings[2847]="靠近点，但是不要抽雪茄！我恐怕你必须得先跟我的妹妹洁娜谈谈。当她领你复习完基础知识再回来找我，我那时就会让你见识真正有趣的东西！"
D.Strings[2848]="对一个初学者来说还不坏！我猜给你看些东西也不会对我有什么损失……"
D.Strings[2849]="要是离天黑还有些时间的话……"
D.Strings[2850]="你赢得了到一个更高级的导师那里学习的权利。去见见我那边的朋友罗克希克。"
D.Strings[2851]="每天都是考验，这天也不例外。如果你通过这次测试，我会教你一些知识……"
D.Strings[2852]="你还没有资格接受我的培训。先去见见桑德，就在那张桌子旁边。当他说你可以了再来找我！"
D.Strings[2853]="你已经通过测试了，干得好！对你的培训可以继续了。"
D.Strings[2854]="我可没时间闲谈，我是个专业人士！"
D.Strings[2855]="你认为我能教给你什么？罗克希克比我更适合做你的老师。你可以在奥格瑞玛找到他。出发吧。"
D.Strings[2856]="让我们看看你的能力，好吗？要是你按要求完成任务，我会乐意教你的！"
D.Strings[2857]="我们彼此都在浪费时间！如果你想接受训练的话，就去找格拉哈姆·范·塔伦吧！他就站在右边。"
D.Strings[2858]="要是我计算正确的话，这车轮很快就会作废的！"
D.Strings[2859]="你的训练已经非常深入了，只有一个导师可以进一步地训练你。找到加基森的巴兹克·布拉斯温！"
D.Strings[2860]="我要教你的东西会让你头脑混乱的！当你学到足够的知识后再来找我吧！"
D.Strings[2861]="很好，你已经证明了你自己！现在进入下一阶段的授课……"
D.Strings[2862]="有时，连我自己都感到惊讶！"
D.Strings[2863]="我没有什么可以教你的啦！如果有人比我知道得多……等等，有啦！去加基森找巴兹克·布拉斯温吧。"
D.Strings[2864]="很好的尝试，但是在训练之前，你还需要进行更多的锻炼！回到战壕！"
D.Strings[2865]="很好！无论其他人怎么说，我想我对你的看法是正确的。哈哈！我是开玩笑的！好吧，开始上课……"
D.Strings[2866]="我一直在研究在大城市间通过地下通道运送石油的方法，但是每个人都认为我是在做白日梦。"
D.Strings[2867]="给你看看你得到了什么！我承诺，你不会有遗憾的！"
D.Strings[2868]="我从不拒绝那些已经准备好跟我一同训练的人。不幸的是，你不是！你还像个小孩！"
D.Strings[2869]="%s在主人遇到危险时是不会选择死亡的！"
D.Strings[2870]="欢迎，旅行者！是什么风把你吹来的？"
D.Strings[2871]="我担心对有你这样经验的人没什么可教的。但是你还有其他方法。去找那边柜台后面的鲁坎·考迪尔谈谈。他会指引你通过旅行的下一个阶段。"
D.Strings[2872]="嗯……你看起来很有能耐。如果你真想学习的话，那么没有什么能阻挡你！我会指引你通过漫长而硕果丰盛的道路上的第一步。"
D.Strings[2873]="年轻的流浪者，有比铁锤和熔炉更能使钢铁坚固的方法。想学学吗？"
D.Strings[2874]="你确实是个不错的附魔师！现在你该继续了。我想让你与楼上的吉布·草须谈谈。他人有些古怪，但是他会继续指引你！"
D.Strings[2875]="啊，你是个好奇的人，是吗？太好了！听仔细了，这也许能在恶劣的环境下保护好你的皮肤！"
D.Strings[2876]="女神已经赐予我智慧，陌生人。如果那是她的意愿，我将会把它传给你。"
D.Strings[2877]="你的技能已经非我能及。现在你该接受新的挑战了。塔兰丹会帮你准备。他就站在那里的桌子旁边。"
D.Strings[2878]="我会尽我所能教你。每一节课都是女神亲自给你的礼物。正确使用她的礼物，你就会无往不胜。"
D.Strings[2879]="月神的秘密很多，但是它们不能让任何人知道。"
D.Strings[2880]="你在魔法方面的知识真是很出色。如果你愿意的话，还有很多要学的。跟塔兰丹谈谈，他在达纳苏斯的工匠区。"
D.Strings[2881]="开阔你的视野，流浪者，我们马上开始。"
D.Strings[2882]="陌生人，我没有时间浪费啦。说说你的事儿吧，要么就离开！"
D.Strings[2883]="呃，你进展到这个程度了吗？去那边的书架找拉文尼亚·克洛文。要是你没把事情搞糟，或许你能学到更多知识。"
D.Strings[2884]="你看起来不怎么像我，但谁知道呢，可能有一个附魔师藏在那里的什么地方！"
D.Strings[2885]="我最喜欢在这样的日子里到开阔的大草原上去……但是，我的职责所在不容许我那样做。"
D.Strings[2886]="我不能再教你什么啦。但是，我父亲的知识远胜于我。进去跟他谈谈。祝你好运！"
D.Strings[2887]="只要有耐心和决心，很多秘密都是有可能解开的。现在，让我们开始吧……"
D.Strings[2888]="你好！陌生人，你在找什么？"
D.Strings[2889]="你来错地方了。去找那边的专家古丹谈谈。你可以从他那儿学到更多东西。"
D.Strings[2890]="战死沙场是件光荣的事儿！但是，若是你能利用我教你的东西，或许你不会死得那么快，嗯？"
D.Strings[2891]="你是谁？你想从我这儿得到什么？"
D.Strings[2892]="我看起来像什么，附魔师普巴尔？你的技能还需要附魔大师的指导！去阿祖拉之塔找基塔·费温德。"
D.Strings[2893]="太好了，我们开始吧……哈！你受骗了！你当然不会认为是那么简单吧。你需要像其他人一样证明你的勇气！"
D.Strings[2894]="你在开玩笑，是吗？我认为你在寻找那个矮家伙，索恩斯·火石。他就在楼下。现在快逃吧！"
D.Strings[2895]="好吧，嗯……别骄傲！既然你已经证明了自己的能力，我们可以开始了！"
D.Strings[2896]="如果你带着那东西，我会很高兴地为你指路的。"
D.Strings[2897]="一个真正的专家知道他的局限，而我并不羞于承认你的技能超越了我。我想让你到阿祖拉之塔拜访基塔·费温德。她很有声誉。"
D.Strings[2898]="你看起来很自信。我想你不会介意测试一下你的技术吧？"
D.Strings[2899]="你还没有准备好。找贝蒂·奎恩谈谈，他就站在那边的楼梯旁边。当你提高以后再来找我。"
D.Strings[2900]="旅行者，你有充分的理由让自己充满信心。现在你真正的培训开始了！"
D.Strings[2901]="如果你想猎杀纳迦，你需要所能获得的所有帮助。水底有裂缝，能产生足够的气泡供你在水下呼吸。向水面游动，就能利用这些气泡了。"
D.Strings[2902]="我确实有能力对那些有价值的人进行教学。你是这样的人吗？"
D.Strings[2903]="你是一个非常棒的附魔师。我恐怕已经超出我的才能了。到阿祖拉之塔找到基塔·费温德。现在只有她才配作你的导师。"
D.Strings[2904]="我相信你能胜任这项任务……你要接受挑战吗？"
D.Strings[2905]="你还没有学会基础知识，流浪者。你找我的助手拉琳娜·夏月谈话了吗？可能你需要跟她谈谈。"
D.Strings[2906]="真是细致的工作！你完全有资格获得我将授予你的知识！"
D.Strings[2907]="如果你在寻找一种真正回报丰厚的事业，那么附魔行业正在等待着你！"
D.Strings[2908]="我知道很多事，陌生人，但是你的知识与我的不相上下。想更深入研究的附魔师要去阿祖拉之塔，那里住着一个叫做基塔·费温德的工匠。"
D.Strings[2909]="为什么不让我们见识一下你的能耐呢？如果你完成任务，我很乐意教你些更深奥的东西！"
D.Strings[2910]="我的家族数代都从事附魔工作。我在很小的时候就学会了这项技能，就像我儿子现在在做的一样。"
D.Strings[2911]="赫加斯掌握的知识远胜于我。你得去石爪山脉的太阳石居所找他，继续训练。"
D.Strings[2912]="我会教你……很快的。可我需要你先证明自己的忠心。"
D.Strings[2913]="明显莫特并没有派你到我这儿来。他知道得很清楚。你还无法理解我能传授给你的知识。去外面找我的儿子莫特，他会对你进行训练的。"
D.Strings[2914]="啊，很好。你是个优秀的学生，我对你非常满意。现在，我可以开始训练你了……"
D.Strings[2915]="我很少有访客。你在寻找某种特殊的东西，是吗？"
D.Strings[2916]="如果我不是天天都陷在这里，我已经得到训练你们这些人的技能了！不幸的是事实不是这样。去找石爪山脉太阳石居所的赫加斯谈谈。"
D.Strings[2917]="嗯，你若帮我，我就帮你。如果找我要求的做，并做得很漂亮，或许我们可以谈谈你训练的问题。"
D.Strings[2918]="不，不，在你准备好跟我学习之前你还需要很多训练！去跟那个保守的业余人士玛考布·维恩谈谈。他就是那个埋在书里的人。"
D.Strings[2919]="好吧，我明白些了。但是，你有潜力，这点我不会否定。多加留心你或许就能学到什么东西！"
D.Strings[2920]="你好，旅行者！介意探索一下神秘世界的秘密吗？嗯？"
D.Strings[2921]="有些冒险家认为附魔术不起作用。我发现当我向他们挑战，要与他们作战时，他们的看法就改变了！"
D.Strings[2922]="你的技艺胜过我的水平了，陌生人。与石爪山脉烈日石居的赫加斯谈谈。他会传授你比我还要多的知识。"
D.Strings[2923]="你可能拥有它所需的。让我们查明真相！"
D.Strings[2924]="你现在没有资格接受我的培训，陌生人。先到我的助手夏格那里学习一段时间。"
D.Strings[2925]="干得好！在你眼中闪动的光芒……我很熟悉，我年少时也跟你一样！让我看看能不能教你点什么。"
D.Strings[2926]="是什么使你来到塔楼的？"
D.Strings[2927]="你差不多已经达到训练的顶峰了。为了成为你能做到的最伟大的附魔师，你还需见一位导师。她的名字叫做安诺拉，而你或许能在奥达曼找到她。"
D.Strings[2928]="你很热心，这很好。然而，你还不够资格接受像我这样的人的培训。"
D.Strings[2929]="你的技能正变得非同寻常。现在，继续你的训练……"
D.Strings[2930]="你是来学习赫加斯部落的知识的吗？"
D.Strings[2931]="安诺拉是唯一一个在技能上胜过我的人。你得去……奥达曼找她，学习更多知识。"
D.Strings[2932]="日复一日地坚持训练吧。当你熟练掌握所有技能的时候，再来找我。"
D.Strings[2933]="你在成为大师的旅途上又达到了新的高度。让我们看看能不能让你更上一层楼……"
D.Strings[2934]="向你致意，旅行者，你帮我驱散了这些可怕的生物，我将永远感激你！我还以为自己要躲藏一辈子呢！"
D.Strings[2935]="你的培训快结束了。完成一项最终的任务你就可以达到你成就的顶点了？"
D.Strings[2936]="在我传授你知识之前，你还必须从其他人那里学习一些课程。勤奋些，不要放弃希望。"
D.Strings[2937]="自从我的丈夫上了前线后，海伦尼便一直保护着我。她用善良的心肠和锋利的宝剑帮助我度过了无数艰难岁月。没有她，我真不知道会发生什么事。"
D.Strings[2938]="唉，对不起。我没什么新东西可以教你了。你去暴风城的老城区找西蒙·坦纳尔谈谈怎么样？他是一个肌肉发达有一头漂亮红发的人类。"
D.Strings[2939]="它怎么样了？我喜欢皮革的味道；你不喜欢吗？"
D.Strings[2940]="我已经了解到很多关于时尚的东西。现在那不过就是掌握制革技巧罢了。西蒙能帮助学习制革的。"
D.Strings[2941]="除了对色彩和细节的鉴别能力外，我没有什么可以教你的。跟西蒙·坦纳尔谈谈；他知道很多制皮的高级技能。"
D.Strings[2942]="这套装备真的让我眼前一亮，你觉得呢？显然，我有多种技能可以使用，我可以将贸易的一些诀窍与你分享。听好了。"
D.Strings[2943]="欢迎来到我们家，$n。拉德纳尔和我没什么东西拿给你，但是我们会尽最大盛情欢迎你。"
D.Strings[2944]="我很抱歉，但你已经学会我所知的一切了。然而，暗夜精灵法多恩可以提供给你进一步的培训。你可以到达纳苏斯的工匠区找他。"
D.Strings[2945]="你要把你的针法做得更小些，$n。这样你的箭袋和弹药袋就不会有东西掉出来。还有，没有人喜欢穿着鼓鼓囊囊的外衣的。"
D.Strings[2946]="如果你对皮革缝纫感兴趣，那你算来对地方了。法多恩和泰龙尼斯都是真正的艺术家，而我希望能从他们那里多学些知识。"
D.Strings[2947]="哦，我很抱歉，但是对于皮革你知道的比我要多。如果你想多学些知识的话去找那边的法多恩谈谈。"
D.Strings[2948]="在达纳苏斯这里真是太令人兴奋了，到处都是才华横溢的人们！我这才知道我会让我的家人感到骄傲的。或许如果我幸运的话，哨兵们会请我加入他们前线的军队的！"
D.Strings[2949]="还没准备好收拾这张皮。我希望做皮革不要花太多时间。肯定有办法削减等待的时间。这对我身体不太好，你知道吗？"
D.Strings[2950]="啊，运气真坏！我的技能对你来说一无是处。呃。跟那边的费布·钢轴谈谈吧。他接触皮革的时间比我长多了。"
D.Strings[2951]="哦，好啊，在我等待时找些别的事情做！你真是救命菩萨，$n！"
D.Strings[2952]="你喜欢这地毯吗？我亲自把动物杀死并剥皮的。但愿所有的半人马能被同样容易的击倒。"
D.Strings[2953]="我没有东西可传授给你了。要是你想进一步学习制皮技能，就找卡洛雷克交谈。"
D.Strings[2954]="我们不能剥下人类及其联盟的皮，这真糟糕。这些皮都白白浪费掉了。尽管如此，谁想穿着你由此制造出的质地极差的皮革？"
D.Strings[2955]="肤质很好。它将你包裹其中。你也许已经注意到我的皮肤不是那么好。我过去常常担心自己的毛孔。这些日子我几乎不担心皮肤了。在某种程度上，它得到了解放。"
D.Strings[2956]="你已经掌握了它的用法。我没有什么要教你的了，但是找亚瑟·摩尔谈谈，他是在幽暗城盗贼区工作的一位被遗忘者。告诉他是我派你去的。"
D.Strings[2957]="在瘟疫来之前，我对皮革一无所知。现在我的知识可以传授别人了。死亡让我有了很多时间供自己支配。"
D.Strings[2958]="肉、兽皮、骨头……好的猎人是不会浪费任何东西的。每块兽皮都有利用价值，也许能用来增强盟友的武器装备。单独来看，我们每个人都很强大，但是团结在一起我们就无敌了。"
D.Strings[2959]="我已经没什么可教你了。带着大地之母的祝福离开吧。在雷霆崖的中央高原西北方的商店找到牛头人塔恩。愿你得到他智慧的指引。"
D.Strings[2960]="我们在此繁衍生息，生生死死，数年来大地却亘古不动。因此，这片土地并不属于我们，$n。我们是属于大地的。因此，我们守护着它，没有它我们就无法生存。"
D.Strings[2961]="我们脚下的洞穴中有许多奇异的兽皮，如果你想深入其中探险的话，一定要非常小心，$n。要记住你自己的性命比那些兽皮有价值得多。"
D.Strings[2962]="你对皮革的理解比我要深刻。可能你应该拜访一下贫瘠之地陶拉祖营地的牛头人克鲁姆·满月。对你这么聪明的学生他有很多知识要教给你。"
D.Strings[2963]="凯恩自己住这儿，他们说。一旦我完成了制作一件合适的礼物，我就会把他找出来。或许他会有智慧的话要对我说。"
D.Strings[2964]="你的智慧胜于我，朋友。与这里的塔恩谈话；他对皮革的知识比我要丰富得多。我肯定他会欢迎新学生的。"
D.Strings[2965]="在你开始任何工作之前都要洗净双手。皮革被血或尘土玷污了会带走它的自然美。"
D.Strings[2966]="当我从墓穴中爬出来后，我本以为我的家人会热烈地欢迎我。相反，他们把我从村里赶了出去，用一种我听不懂的语言高声尖叫着。"
D.Strings[2967]="我不能帮助你，我无法胜任。跟棺材那边的亚瑟·摩尔谈谈。他会为你提供更多的训练的。"
D.Strings[2968]="记住我说的每句话。在打败敌人之前，我们绝对不能放弃学习知识、提高自身能力的机会。增强你的实力，绝不能放松警戒。"
D.Strings[2969]="你已经超越我有限的能力了。到达纳苏斯的工匠区寻找暗夜精灵安尼希尔。她可以教给你更多知识。我很希望我可以跟你一起去。"
D.Strings[2970]="对你来说，我的教学在这个阶段略显深奥了。要是你想学习有关药水的更多知识，就跟泰兰希尔谈谈。"
D.Strings[2971]="听仔细了，$n，我要传授给你的知识很多。"
D.Strings[2972]="即使我也有我的局限性！如果你想继续学习的话去找幽暗城的拉文尼亚·克洛文谈谈。"
D.Strings[2973]="还行……训练你是不成问题的。很好！我们开始吧……"
D.Strings[2974]="兰达尔打扮得有些像花花公子，但是他是个可靠的人，他比我向许多学生所说的那样更加值得信赖。尽管如此，我还是不能责备他们想要冒险的想法。"
D.Strings[2975]="很抱歉，我已经没有什么可以教给你的了。如果你还想学的话，就去达纳苏斯的工匠区找泰龙尼斯吧。我听说他相当有才能。"
D.Strings[2976]="当你接受更多训练以后再回来找我。在那边的兰达尔·沃斯可以帮你。"
D.Strings[2977]="嗯，我想我可以再收一个学生。好吧，不要傻站在那里。告诉我你想学什么。"
D.Strings[2978]="达丽亚娜答应了，但是她的精力如此充沛，很难让她安静下来仔细的聆听。她气力十足又机灵敏捷，我恐怕她不久就会被叫去参加战斗。我们必须快点教她。"
D.Strings[2979]="如果你来这儿是为了得到进一步的训练，那你是高估我的能力了。跟泰龙尼斯谈谈；他应该能帮助你。"
D.Strings[2980]="你得及时准备好接受我的教学，$n。到那时，找达丽亚娜谈谈，他会帮助你训练的。"
D.Strings[2981]="我们可以从死去的动物身上获得原料。别无视它们的牺牲，$n。带着尊敬来处理这些皮革。"
D.Strings[2982]="要做的事情很多！自从我的兄弟不小心蒸发了诺莫瑞根所有的衣料和皮革之后，事情便多起来了。我只能保持暂时通风！啊，$n，那些日子……"
D.Strings[2983]="不，恐怕我不能帮你。你的技能远胜于我！如果你想学习更多的知识，跟达纳苏斯工匠区的暗夜精灵泰龙尼斯谈谈。他拥有令人惊异的技能！"
D.Strings[2984]="嗯，我声明！他是个新学生！只要你再多掌握一点技能，我会很乐意将我所知道的一切都教给你的。去跟格雷塔谈谈，好吗？她会教你如何速成技能的。"
D.Strings[2985]="你的技术在进步,很快你就会拥有一家你自己的皮革商店。我很高兴能帮你，$n。我的速度就只能这么快了，你知道吗？有那么多工作要做！"
D.Strings[2986]="我知道，这块蓝色的皮革吸引了你的目光。你看，许多热情高涨的新兵都在这附近狩猎，像失去理智般砍杀动物。你必须提高警惕。"
D.Strings[2987]="我不能再教你啦：你所掌握的技能已经超过我了。去雷霆崖中央平原西北部的商店找牛头人犹纳吧。她会为你提供更多训练的。"
D.Strings[2988]="我不会给一个学徒训练。去贫瘠之地的哀嚎洞穴找牛头人瓦多尔吧，他会帮助你的。"
D.Strings[2989]="你来这里是为了进一步的训练？抖去你身上的尘土吧，让我们马上开始工作。"
D.Strings[2990]="我的斧头经历过多场战事，我喜欢将它带在身边。敌人曾数次入侵我们的首都，但是别怕：我们总能击退他们。"
D.Strings[2991]="我不能为你提供更多的训练啦：你的制革技能已经超过我啦。你应该去那儿找犹纳谈谈。如果需要的话我会为你担保的。"
D.Strings[2992]="你的技艺不足以学会我所教授的。去找那边的玛克谈谈。他可以帮你直到你准备好学习更高级的课程。"
D.Strings[2993]="我目前对你的进步感到很满意。很显然大地母亲已经赋予你的双手以灵感了。"
D.Strings[2994]="眼下，我们在这片大陆上只有一处立足之地，但是人类是永远不可能打败我们的。他们很快就会受到报复。我们会割下他们说谎的舌头，惩戒他们的背叛行为。"
D.Strings[2995]="要是我能的话，我会教你的，但我力所不及。去跟雷霆崖中央高地西北部的商店找牛头人犹纳谈谈。她拥有真正的才能。"
D.Strings[2996]="你没经过适当的训练就来找我，说明你勇气有余而智慧不足。去找个接近你的技术水平的人谈话，像兽人卡玛瑞，他住在奥格瑞玛的暗巷区。"
D.Strings[2997]="我忙吗？这话什么意思？你觉得我只是成天站在这儿玩弄手指吗？如果你想买些什么的话，跟罕杜尔谈谈。"
D.Strings[2998]="你在我这里学不到新的东西了；你知道的已经很多了。如果你想得到更多培训的话，去找雷霆崖中央高原西北方商店里的牛头人尤纳谈谈。替我向她致意，怎么样？"
D.Strings[2999]="你在学习好基础知识之前不能学我的技艺。如果你对训练感兴趣的话就去找卡玛瑞谈谈。"
D.Strings[3000]="奥格瑞玛地形迂回曲折，能有效地阻止入侵者。你能想象这些矮小的侏儒在多么短的时间内就迷失方向吗？哈哈！如果足够幸运的话，我会追踪到他们，将他们变成我的宠物。"
D.Strings[3001]="我生前是一名图书管理员，与战争和灾难无缘。我从未想过要变成现在这样。另一方面，现在我能主宰自己，我是不会不战而降的。"
D.Strings[3002]="你的能力已经超过我了。走吧。嗯，去雷霆崖中央高地西北部的商店找牛头人犹纳。她拥有强大的力量。"
D.Strings[3003]="要是我教新手的话，那会有无数的学生来拜访我，那还不得乱成一团了。去跟那儿的丹·戈萨斯谈谈。他有些过于热情了，但意图总是好的，而且他是个相当好的老师。"
D.Strings[3004]="起先，我在魔法区开设商店，但是那儿太嘈杂啦。尽管我进行了重新部署，除了有些学生坚持要向我求学之外，环境还是得到了相当的改善。"
D.Strings[3005]="月神已经赐予暗夜精灵很多礼物。作为回报，我们有职责保卫这些森林免受部落带来的恶魔的污染。"
D.Strings[3006]="继续培训你已经超越我的能力了。与达纳苏斯工匠区的泰龙尼斯谈谈。他总是很愿意帮助有才能的学生。"
D.Strings[3007]="我只教那些掌握基本指示的学生。你必须在达纳苏斯工匠区找到暗夜精灵达丽亚娜。她的技能与你的是完美的互补。"
D.Strings[3008]="在你开始切割皮革之前一定要仔细检查尺寸。我们可不能浪费材料。"
D.Strings[3009]="你必须去西部荒野的海洋搜寻，向正西方——金海岸矿洞与海岸交接处往西北方向。海岸边有一只锚，看来附近一定有艘沉船。水下的压力很大；如果游得太远的话，即使是最优秀的潜水者也可能死于疲劳。$B$B去找一处适宜的自然环境吧，$n——这附近有起泡的海底裂缝，能在深海潜水时提供氧气。"
D.Strings[3010]="在银松森林北流海岸边缘，海滩上搁着一艘废弃的船。船只以西有你要找的东西；游得太远的话，你会因疲劳无法游回海岸的。海床上有一只上了锁的箱子，等着你去取呢。$B$B要是没有人帮忙的话，潜到这样的深度会受到极大的压强，要小心；海床上有一道裂缝，能释放出气泡，有助于你寻找那半块坠饰。好好利用吧。"
D.Strings[3011]="在黑海岸的北面流淌着壁泉河，发源于现今的费伍德森林。随着河流流到并汇入薄雾海，一直蜿蜒到海洋北部最深处。在那儿有你要的石头，由于这种石头的形状酷似爪状，因此被称为石爪。$B$B要当心——蛇颈龙聚集在石爪那里，他们会攻击那些贸然入侵的人。"
D.Strings[3012]="在贫瘠之地的东北部，有一处受到严重污染的水池。当地人称它为淤泥沼泽；风险投资公司将水晶般幽蓝的水域变成工业副产品和废弃品的泥潭。在沼泽的中心有你要找的东西，$n。$B$B要小心，风险投资公司绝不容许有人入侵，他们将不为其工作的人都当作入侵者。你作为自然的保护者，更是他们极力对抗的目标。"
D.Strings[3013]="草地柔软青葱。空气清新，阳光明媚，歌声飘飘。泰达希尔的梦想终成现实。但是为什么我感到有种不详的预兆？"
D.Strings[3014]="你的进步已经超越了我能教授的技艺了。现在到辛特兰的鹰巢山去找矮人德拉克·石拳谈话。他的作品太棒了，比我的好多了。"
D.Strings[3015]="$g尊敬的先生:女士;，在你掌握制皮的更多知识之前，我还不能帮助你，对此我感到很遗憾。跟法多恩或达丽亚娜谈谈。他们能教你所需的技能。"
D.Strings[3016]="别试图将你的意愿强加到皮革上。而是让其天然的特性显示出自身的形状和功能。这不是一场战役。与皮革协同工作，而不是与其作对。"
D.Strings[3017]="针太细，线太粗，针脚倒还不错。我们与萨尔和其他人的合约将继续有效。部落不会被驱逐出这片土地的。"
D.Strings[3018]="我的才能有限，你也已经达到了。恭喜你，$n。你的下一站应该是菲拉斯的莫沙彻营地。牛头人哈拉纳·铁皮住在那里；她的技术很有声望。"
D.Strings[3019]="我自己不久前也是一个新手，所以我觉得我不太适合教你。试着跟那边的塔恩或是玛克谈谈。他们之中应该有人能回答你的问题。"
D.Strings[3020]="凯恩把我们带到了一片充满希望的大地。我们很幸运，因此我们再把好运带给别人。这就是我为什么开始教学的原因，$n。"
D.Strings[3021]="我可以利用在这儿找到的材料制作有趣的东西。这些山林中有许多奇怪的生物！去杀死它们，$n。"
D.Strings[3022]="我喜欢机会；你不喜欢吗？啊，当然你也喜欢。这就是你要按我说的去做的原因。"
D.Strings[3023]="我不是来教那些刚离开摇篮的宝宝的。你离我对学生的要求还差远了。你不过是个年幼的$g小伙子:姑娘;，你最好别在这儿烦我了。"
D.Strings[3024]="我所有的作品都必须由买主亲自来订购。奥尔文常常要我改变这个习惯，但是我就是不改。看看你周围吧，无数战士还指望我给他们打造装甲呢。"
D.Strings[3025]="我真希望有更多像你一样的学生。很少有人会冒险深入敌境。我佩服你的勇气。"
D.Strings[3026]="我不会在这场战争中让步。我不分昼夜的制造新装甲，还把旧的装甲修补好。我没时间做其他任务。你愿帮我分担一些吗？"
D.Strings[3027]="你来找我求学是浪费了你我的时间，$n。我没时间教授基础技能。我们在这里战斗，而这里是一处前线。在你准备充分之前不要再来找我。"
D.Strings[3028]="我觉得你的服饰急需维修。"
D.Strings[3029]="我对裁缝业知之甚少，但你需要更多的帮助。我听说有个暗夜精灵精通裁缝技术。他居住在暴风城的魔法区。"
D.Strings[3030]="你想学点东西吗？我会很乐意教你的！"
D.Strings[3031]="生活就像一幅小心编织的锦缎。"
D.Strings[3032]="嗯……你需要学的东西有点超出我的能耐了。去找那边的塞拉多斯谈谈。我会的东西全是他教的！"
D.Strings[3033]="很好，开始学习裁缝吧。"
D.Strings[3034]="缝纫需要娴熟的手法，以及……也是最重要的，耐性。"
D.Strings[3035]="现在是你去达纳苏斯跟迈里恩谈谈的时候了。她将对你进行指导。"
D.Strings[3036]="很高兴能将你收入麾下。让我们开始吧。"
D.Strings[3037]="欢迎来到我的商店。我能为你做什么？"
D.Strings[3038]="等一下，我只是一个助手。如果你想学那些花哨的东西，找那边的老约莫德·石眉谈谈。"
D.Strings[3039]="很好！我一直希望收个新学生。那么就让我们立刻开始吧！"
D.Strings[3040]="我们使用动物皮毛制作物品。"
D.Strings[3041]="我知道一些，但我不是专家。祝你好远，玛加尔也是。他就站在商店后面。看看他是否能帮助你，但是小心别惹恼他。他脾气有些暴躁。"
D.Strings[3042]="我会将我所知道的传授给你的。"
D.Strings[3043]="我们没有浪费狩猎而得的动物的任何一部分。"
D.Strings[3044]="你寻求更高级的知识。坦帕拥有这种知识。她应该就站在附近……"
D.Strings[3045]="带着大地母亲的祝福，我们要开始了。"
D.Strings[3046]="去结交朋友吧。我能帮你吗？"
D.Strings[3047]="我知识渊博，但我还不是专家。你知道你该去找谁谈话吗？雷安诺！她就在不远的地方。到幽暗城打听她的下落。"
D.Strings[3048]="这么说……你想当一名裁缝？很好，让我们看看你是否具有这样的潜质。"
D.Strings[3049]="到我们这儿来的客人可不多。你对我感兴趣？"
D.Strings[3050]="我只是个学生。雷安诺才是专家。她站在那边的箱子旁。你可以从她那儿学到很多东西。"
D.Strings[3051]="是的，我认为你有潜力。或许我可以给你看看一两样东西？"
D.Strings[3052]="没有比编织更好的宁神方法了。"
D.Strings[3053]="你的教育正在继续，而你的知识已超越了我。如果你还想继续学习你就必须找迈里恩谈谈。她会指引你的。"
D.Strings[3054]="你不会失望的，旅行者。裁缝是一种充满乐趣的工作。"
D.Strings[3055]="嗨，我能为你做什么呢？"
D.Strings[3056]="你所掌握的知识已经跟我差不多啦。或许你可以去奥格瑞玛找玛加尔。他虽然不是最好的裁缝，但是他一定可以帮助你。"
D.Strings[3057]="这就对了！拿起针线让我们开始吧！"
D.Strings[3058]="恐怕我已不再是个文雅谦逊的人了。年龄和无数战争让我的皮肤和灵魂变得坚硬无比。或许这就是凯恩派我来烈日石居的原因……和煦的暖风和温暖的阳光无法减轻我的痛苦。"
D.Strings[3059]="你好。我们的蝙蝠训练很严而且吃得不错。你不会找到比他们还快的了。"
D.Strings[3060]="我要如何效劳？"
D.Strings[3061]="你好，欢迎。我不太擅长微笑，但是相信我；我很高兴能为您服务。"
D.Strings[3062]="角鹰兽是一种高贵而迅捷的动物。这些训练有素的飞兽可以让它们的骑手以很快的速度旅行。"
D.Strings[3063]="为了与大陆保持联系，我们会定期派出角鹰兽在鲁瑟兰村和黑海岸之间传递信息的。"
D.Strings[3064]="泰达希尔海岸边的鱼儿又大又精神。有传言说那是因为我们新的世界之树的快速增长而引起的。"
D.Strings[3065]="尽管黑海岸比泰达希尔更危险，但是很多渔夫都在此谋生。"
D.Strings[3066]="为冒险家服务是我的荣幸，因为他们即将成为英雄。"
D.Strings[3067]="我这里的狮鹫是鹰巢山以南飞得最快的。想要乘坐吗？"
D.Strings[3068]="好吧！我们出发。"
D.Strings[3069]="你可以在北边的码头搭船前往鲁瑟兰村和达纳苏斯。南边的码头是穿越无尽之海通往暴风城港口的航线。西边的那座码头通往埃索达附近的秘蓝岛。祝你一路平安！"
D.Strings[3070]="这个码头？你可以乘船前往暗夜精灵的领地。地名？嗯，我想是奥伯丁。我不太确定，我只是一名搬运工。"
D.Strings[3071]="你是来帮助投递物品的吗？米兰就快准备好了。"
D.Strings[3072]="我的双足飞龙可以在贫瘠之地高速飞翔。"
D.Strings[3073]="贫瘠之地阳光灼热，那儿的居住者充满敌意，是考验你的力量和决心的最佳地点。"
D.Strings[3074]="要将这些桶运送到挖掘点非常困难，但是要获得火药，还得靠我们自己。$B$B我们必须竭尽所能地对抗黑铁！"
D.Strings[3075]="你好。如果你是来找皮件的，那么你会看到我的货品做工精细。"
D.Strings[3076]="当坐在一个驭风者背上时，你就会发现它的力量和速度的确不是徒有虚名。"
D.Strings[3077]="你操纵得比我要好！你需要一个经验比我还要多的人。那就是赫?特·哈尔希医生，一个在幽暗城炼金房工作的亡灵。"
D.Strings[3078]="看看我的肉，朋友。你不会想双手空空就进入贫瘠之地吧。"
D.Strings[3079]="在你从驭风者背上往下俯瞰这个世界之前，不能说你真正活过。"
D.Strings[3080]="你可以从这个码头找到去塞拉摩的路。记住我的话，那些地方对从联盟去的人们是非常不安全的。一定要小心谨慎。"
D.Strings[3081]="你好。"
D.Strings[3082]="你的技艺在我的技术水平之上了。可能你该见见我们商店的老板，乔吉奥·波利罗。他就站在那边的柜台附近。"
D.Strings[3083]="跟楼梯那儿的劳伦斯·瑟尼德交谈。他善于引导初学者。"
D.Strings[3084]="都是些有用的东西。你的教导可以继续进行了。"
D.Strings[3085]="啊，这件达纳苏斯织品质量最好！"
D.Strings[3086]="嗯，你这个聪明的家伙！我可以明确地告诉你，你知道的比我多！你可别为此自负，如果你想继续学习的话，就去暴风城找乔吉奥·波利罗谈谈吧。听说他是个很好的裁缝！"
D.Strings[3087]="我可没时间跟小孩子耗！去跟我的助手阿斯拉谈谈！"
D.Strings[3088]="嗯……看来还有点希望，我会把那个给你的。那好吧，我们在哪里？"
D.Strings[3089]="看看周围，$r。你应该为今天能看到的一切而心存感激。$b$b自从我第一次走进这片森林，这里的许多东西都已经改变了。这些都是奇妙的，出乎意料的改变……"
D.Strings[3090]="我能制造你在商店里看见的若干东西。你认为如何？小心回答，这也许能决定你的命运。"
D.Strings[3091]="你需要找一个比我懂得多的人。去找幽暗城的乔瑟夫·格里高利谈谈。那么，你还在这里干吗？"
D.Strings[3092]="什么？你为什么在烦我？哎呀，我打赌你甚至不能制造一件高质量的长袍！去找斯诺恩谈谈，等你水平提高以后再来找我！"
D.Strings[3093]="你那时给我看了某些结果！现在该我给你看看结果了！"
D.Strings[3094]="他们说小洞不补大洞……什么来着？啊，我记不得了。反正是愚蠢的说法。"
D.Strings[3095]="对一个业余者来说……这还行！你的知识量已经跟我持平了。要是你想学习更多知识，就去幽暗城找乔瑟夫·格里高利谈谈。"
D.Strings[3096]="嗯，嗯，还不坏。或许我能让你看点什么……"
D.Strings[3097]="多好的天气！它让我有了创造新设计的灵感。"
D.Strings[3098]="你的才能出众！你真是有灵性。你要想继续追求知识的话，找暴风城的乔吉奥·波利罗谈谈。他深受众人尊敬，而且他能深化对你的指导。"
D.Strings[3099]="必须首先学习一些基础知识。蒂安娜就站在旁边，找她谈谈然后回来找我。"
D.Strings[3100]="你干的很好，旅行者。我能收你当徒弟令感到很骄傲！"
D.Strings[3101]="欢迎来到我的帐篷。我可以帮你吗？"
D.Strings[3102]="你的知识很渊博，旅行者。你必须向一个比我更聪明的人学习。关于乔瑟夫·格里高利的智慧的故事广为流传。你可以在幽暗城找到他。"
D.Strings[3103]="完成得很熟练！现在，让我们继续你的教育……"
D.Strings[3104]="这些图案难道不漂亮吗？每一个都有自己的风格。"
D.Strings[3105]="我的知识有限，尽管我还在继续学习。现在该你继续了，旅行者。在幽暗城找到乔瑟夫·格里高利并告诉他你准备好了。"
D.Strings[3106]="在我帮你之前你必须学会一些基础的东西。与我的徒弟范恩谈谈。他很耐心而且愿意教你所需的知识。"
D.Strings[3107]="你真是一个意志坚定的学生。我很高兴给你提供指导！"
D.Strings[3108]="裁缝可以派得上大用场。我从前就不得不把我的胳膊缝上。"
D.Strings[3109]="你做得很好……是时候见见老板了。找到乔瑟夫并告诉他你准备好了。"
D.Strings[3110]="我怎么能把我的秘密告诉一个初学者呢？先试着跟博文谈谈。"
D.Strings[3111]="好极了，你很有勇气！我很满意。那么，我们就出发吧！"
D.Strings[3112]="是的，我现在已经经营这家店一段时间了。最近生意非常好。许多新的探险者来了……"
D.Strings[3113]="我只知道有一个人能在裁缝技能上胜过我。我最后一次听说他在塞拉摩岛。你该去找他。"
D.Strings[3114]="我恐怕在我可以教授你知识之前你要需要更多的训练。"
D.Strings[3115]="布料也可以。就我个人来说我更喜欢使用人皮。"
D.Strings[3116]="你需要一个真正大师的指导！到塔伦米尔的达瑞尔·斯塔克那儿去试试你的运气！"
D.Strings[3117]="当时机合适时，我会传授知识给你的……不是现在。你还得学习更多的知识！"
D.Strings[3118]="太好了！我能断定我的努力不会白费！"
D.Strings[3119]="我给国王提供过装备。如果有正确的训练，你也可以。"
D.Strings[3120]="你走了好远的路了，旅行者。还有一项工作要你完成……"
D.Strings[3121]="你要学习更多的基本技能，我才能帮助你。当你准备好了再来找我。"
D.Strings[3122]="这地方通风良好……但是我还在乎什么？我已经死了。"
D.Strings[3123]="你在缝纫艺术方面做得很好，我必须承认。现在，让我们看看你到底有多棒……"
D.Strings[3124]="谁派你来的？你还没有准备好接受我的指令！当你们准备好以后会得到通知的。"
D.Strings[3125]="我确实很喜欢坐在这里，听着大海的声音。哦，什么？是的，有一艘船会把你带到米奈希尔港。它有时会停在这里。"
D.Strings[3126]="记得我的话！你在东部王国是找不到比塞尔萨玛狮鹫更快的狮鹫的！"
D.Strings[3127]="要是你问我的话，没有比矿工更好的职业了，也没有比矮人更好的矿工了！"
D.Strings[3128]="蛮锤城堡的矮人也许有奔跑迅速的战马，但是这些鹰巢山的狮鹫能承受大熔炉的热量吗？我觉得不能！"
D.Strings[3129]="最好的矿工紧握$g他:她;的铁锄，拥有一颗坚定的心，头发上还散落着一层厚厚的黑灰。"
D.Strings[3130]="那个坚固的箱子在木材厂中间，周围推满了残骸和血色十字军的狂热信徒。"
D.Strings[3131]="将装有白蚁的桶放入箱中。"
D.Strings[3132]="%s伤得太重，放弃了追逐。"
D.Strings[3133]="你能告诉我关于那只熊——乌萨苟斯的情况吗？"
D.Strings[3134]="你能告诉我关于夜刃豹——猎影的情况吗？"
D.Strings[3135]="你能告诉我关于角鹰兽尖爪的情况吗？"
D.Strings[3136]="这只熊漫步在一条靠近石爪小径的路上，在密斯特拉湖和联盟的银风避难所正西方。虽然他是你在灰谷遇到的三个动物之中最好对付的一个，对他也不能掉以轻心。他的出现对于逗留在灰谷和石爪山脉之间的旅客来说是一个巨大的威胁。"
D.Strings[3137]="这只夜刃豹传言在暗夜精灵和他们的同盟面前很驯服，这使她成为一个更有价值的对手。猎影的猎杀路线把她从瑞恩伍德居所赶到了我们的西方，最终在那里的正西方登陆。她的皮毛是沥青一般的颜色，而她的速度也不能低估。"
D.Strings[3138]="作为灰谷猎场最强大的野兽，尖爪可以在这片大地自封的卫兵——暗夜精灵的陪伴下自由的漫步。尖爪在这里南部寻找猎物，尽情的撕裂着毫无防备的旅客。$B$B要想杀死这样一个野兽需要极大的努力，$n。我希望你在猎杀这个野兽时运气好一点！"
D.Strings[3139]="你好，$c。欢迎来到我们征服灰谷的前线！如果你在找事做的话，那么你算来对地方了。我总是在寻找体格健壮的$r去为部落赢得荣誉！"
D.Strings[3140]="%s为拉格纳罗斯做最后一次服务……"
D.Strings[3141]="龙族用高贵的表象掩饰自己。这些石板会将她的本来面目还原的……如果我所见到的幻象都是真的，朋友，我就在这场战斗中丧命。你必须完成我没能完成的事业。你准备好了吗？我们将听你的命令前进。"
D.Strings[3142]="如果你想知道碎木哨岗的商旅来往情况，我恰好就是你要找的兽人。不幸的是，我不喜欢人类。$B$B要是你想要什么的话，就快些。"
D.Strings[3143]="元素在跟我们讲话，$c。他们分享着我们必须掌握的知识以及不能泄漏的秘密。"
D.Strings[3144]="在严格的训练中，我必须除去那些学生先前所学的所有知识，以便传授新知识。我所提供的服务越来越难以完成。为此，每次训练的费用也越来越昂贵。你愿意除去你先前学习的技能吗？"
D.Strings[3145]="要是你愿意的话，除了训练之外，我还可以用自己的力量将天赋从你的头脑中抹去。我要警告你的是，你每经历一次这样的过程，执行这过程的难度就会增加一分，而且所需的费用也会随之上升。"
D.Strings[3146]="看看野兽的智慧和学识吧，这会帮助你你认清自己。你要学会像猫头鹰那样敏锐，像猎豹那样灵巧，像狼那样强韧。"
D.Strings[3147]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B来自翡翠梦境的召唤将很快占据你的心灵。你将休眠数年，在最纯净的环境中生活。你将在那儿接受最终的训练。"
D.Strings[3148]="我能为你做什么？"
D.Strings[3149]="我没有什么可以教你的啦！无论如何，不是每个人都像你能懂这么多知识！你需要跟奥格瑞玛的诺格谈谈。"
D.Strings[3150]="好吧，我们出去吧！"
D.Strings[3151]="银翼是我们的！"
D.Strings[3152]="去汇报说我们的前哨沦陷了。我们要留下。"
D.Strings[3153]="准备好了。银翼正在发狂呢。"
D.Strings[3154]="都准备好了吗？"
D.Strings[3155]="我不会伤害你的。我在监视野猪人并记录他们的活动。我的人民注意到了某些奇怪的事情……某种黑暗的气息从这个地区中散播出来。我是前来调查此事的，而我的发现很令人不安。$B$B似乎有一个很善于使用奥术魔法的亡灵外交官在附近。我不相信他也是被遗忘者……我认为情况比这更糟糕。"
D.Strings[3156]="真是走运。通常我必须离开窝才能找到食物。"
D.Strings[3157]="要明白你的处境，凡人！"
D.Strings[3158]="这毫无意义的行动让我很厌烦。我会从上空把你们都烧成灰！"
D.Strings[3159]="你知道的已经够危险了，但是对我来说你看起来还需要训练，$n。"
D.Strings[3160]="看起来需要再给你一次教训，凡人！"
D.Strings[3161]="你的意志不足以操纵我们控制的军队，$c。"
D.Strings[3162]="我喜欢学习更多的关于术士的知识。"
D.Strings[3163]="$n，我如何才能在大地母亲的心目中继续你的深造呢？"
D.Strings[3164]="你想学习更多的术士知识，那你还是放聪明点，在我面前表现得谦卑一些，$n。"
D.Strings[3165]="我没有时间浪费在像你这样的人身上$c。"
D.Strings[3166]="我服从安排接受进一步的训练，我的主人。"
D.Strings[3167]="从你的站姿我可以看出你不是战士。$B$B你为什么不做点安全的事，比如读书什么的。"
D.Strings[3168]="黑暗没有拥抱你这样的$c。别说废话，从我视线中消失吧！滚！"
D.Strings[3169]="恐怕你给我的份额太低了，我可不愿跟你废话了。请走吧。"
D.Strings[3170]="你不是战士……你为什么在我的训练课程中一天都坚持不下去！$B$B一个以为自己是战士的$c，哈哈！"
D.Strings[3171]="孩子，我看不出你具备战士的精神。我不会训练你这样的$c的。"
D.Strings[3172]="利斯塔，召唤亡灵俘虏。"
D.Strings[3173]="利斯塔，冲啊……憎恶！"
D.Strings[3174]="碎手已经在黑石的大本营中安插了数名间谍。尽管信息收集的过程已经慢了下来，但是我们发现了一些不容忽略的现象。"
D.Strings[3175]="似乎黑龙的势力范围已经超越了燃烧平原，扩展到暴风城了！人们揭下了篡位者的面具并将他流放出境。"
D.Strings[3176]="真的。黑龙之母运用幻象和欺诈术将自己伪装成贵族法庭的成员。更糟糕的是，眼下，她似乎已经控制了暴风城的伯瓦尔·弗塔根公爵。$B$B做出这样愚蠢的军事决定不足为奇。联盟军队最近的行动令我们头疼。现在我们知道，黑龙正试图分裂帝国——从内部分裂它。"
D.Strings[3177]="<萨尔笑了。>$B$B还有这么多要学的，$r。$B$B你太年轻了，记不得多年前的战争和流血。记不得我们的人民所承受的诅咒的重压。$B$B我们现在与联盟的形势很脆弱。小冲突和小规模战斗时常发生，但是仍有和平--我们的人民数千年来未有过的和平。你愿放弃这个并把我们再次投入这片混沌中去面对一个新的敌人吗？这个敌人在毁灭我们之前是不会停手的。"
D.Strings[3178]="不，$n，你没有。我没找你茬，但是你跟年幼的我非常相似：冲动、叛逆、思维缺乏连贯性！这些特点在我身上已经荡然无存。$B$B悲伤够了。$R，我有个任务要你完成；或许你会在执行任务过程中丧命。"
D.Strings[3179]="<萨尔笑了。>$B$B注意……现在专心些，$n。黑龙的母亲，奥妮克希亚，从她在暴风城的权位上被推翻了。她已经逃到她在尘泥沼泽的窝里。$B$B她不能生活在离我们的首都这么近的地方。我们必须先发制人！$B$B我想要消灭她，$n。"
D.Strings[3180]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。"
D.Strings[3181]="我看见一些有趣的人在港口进进出出。小心，$n。你永远不清楚谁值得信任以及跟这儿发生的所有事情的缘由……"
D.Strings[3182]="你是为战歌之斧而来的吧。嗯，是时候了，$n。那箱子已经放了好长时间了。$B$B你可以随时拖走它。"
D.Strings[3183]="石爪山脉在这片区域拥有许多危险的洞穴。若干冒险家愿意冒着生命的危险到这些洞穴中探险。$B$B$C，也许只要你全心全意地寻找，会找到财宝的。"
D.Strings[3184]="鱼肉真鲜美。你来学钓鱼的？还是来吃鱼的？呣……"
D.Strings[3185]="我需要训练，鲁玛克。"
D.Strings[3186]="对，我可以教你钓鱼。"
D.Strings[3187]="我需要训练，格瑞诺尔。"
D.Strings[3188]="请离开这个地方，$n。你对困扰我们的问题毫不知情……"
D.Strings[3189]="我到哪里可以找到魔化瑟银锭？"
D.Strings[3190]="我到哪里可以找到恢复水晶？"
D.Strings[3191]="魔化瑟银锭是一种很受欢迎的金属。你找到它的最好办法就是找个铁匠或是矿工谈谈。"
D.Strings[3192]="恢复水晶很难入手。$B$B我相信它来自安戈洛环形山，你最好去那儿看看。"
D.Strings[3193]="我们可能遇到了旱季，但是供给并不缺乏！想看看我的货物吗？"
D.Strings[3194]="我想看看你的货物，迪尔格。"
D.Strings[3195]="扎姆沙能帮你吗，$r？"
D.Strings[3196]="我需要训练，扎姆沙。"
D.Strings[3197]="我会喂养它们的，孩子。达瑞尔·瑞克努索，愿为你服务。"
D.Strings[3198]="对污林熊怪来说，你真是个小麻烦！死吧！"
D.Strings[3199]="不！你不可能比污林熊怪更强壮的！不！！"
D.Strings[3200]="我得救了！谢谢你，医生！"
D.Strings[3201]="万岁！我得救了！"
D.Strings[3202]="亲爱的，拥抱我……拥抱我……"
D.Strings[3203]="我需要训练，阿诺克。"
D.Strings[3204]="你是来学习医疗知识的吗？"
D.Strings[3205]="你为何来此，$c？"
D.Strings[3206]="我的人民，他们就像你试图修复的遗物一样支离破碎。"
D.Strings[3207]="虽说没有东西可以改变过去，时间可以治愈所有伤口。谢谢你让我看到那是可能的，$n。我祝你顺利。"
D.Strings[3208]="我的答案是伊瑟拉。"
D.Strings[3209]="啊，梦境之神伊瑟拉。"
D.Strings[3210]="我的答案是奈萨里奥。"
D.Strings[3211]="我的答案是阿莱克丝塔萨。"
D.Strings[3212]="我的答案是玛里苟斯。"
D.Strings[3213]="奈萨里奥，嗯？这是个很好的回答，是吗？"
D.Strings[3214]="阿莱克丝塔萨，生命的缚誓者。巨大的生物。"
D.Strings[3215]="玛里苟斯，是吗？"
D.Strings[3216]="你好，$c。有什么我能帮忙的吗？"
D.Strings[3217]="我想问你，$c：$B在泰坦创造的守护巨龙中，是谁后来变成了被称作死亡之翼的邪恶生物？"
D.Strings[3218]="有人找我谈话总是件高兴的事儿。事情进展如何，$c？"
D.Strings[3219]="不，回答我，$n：$B在洛丹伦天灾爆发之前，是谁变成了巫妖王？"
D.Strings[3220]="答案错误，$n。走吧。"
D.Strings[3221]="%s正在攻击旗帜！"
D.Strings[3222]="是的，你知道一些事情！如果你想学会更多的话就必须与暴风城的乔吉奥·波利罗谈谈。"
D.Strings[3223]="瑟银兄弟会懂得如何制造炎魔之王的神圣武器，但是我们缺乏人力，无法获得制造武器所需的材料。$B$B我，罗克图斯·暗契，兄弟会赋予我强大的力量，用珍贵的药方来交换从熔火之心收集的材料。$B$B给个价吧，$r。"
D.Strings[3224]="罗克图斯，哪些东西是我有权使用的。"
D.Strings[3225]="想让你的恶魔变得更强大吗？这需要花钱的，但是你来对地方啦。"
D.Strings[3226]="你不是术士而且我没时间理你。走开！"
D.Strings[3227]="你来接受训练为的是把它传递到你的宠物身上？"
D.Strings[3228]="啊朋友，我只帮助猎人和他们的宠物。"
D.Strings[3229]="现在我们必须等待。纳迦很快就会意识到我们干了些什么。"
D.Strings[3230]="皇家药剂师协会对愚蠢的家伙可没有耐心，我也一样。或许下次我们谈到战马的时候，你会被当作是幽暗城的贵族。到那时……"
D.Strings[3231]="保持警惕，$n！"
D.Strings[3232]="或许我们能休息一下。但是在打败沃尔沙之前我绝不放弃！"
D.Strings[3233]="我只跟那些被奥格瑞玛的兽人当朋友的人做生意。证明自己吧，然后再来和我谈那些强大的座狼。"
D.Strings[3234]="很抱歉$g兄弟:姐妹;，但是在确定买主是暗矛部落的贵族之前，我不会将迅猛龙卖给他的。当你证明自己是部落贵族之后，我才会把迅猛龙卖给你。"
D.Strings[3235]="你并不为我的人民所知。科多兽是强大的坐骑，它是我的人民爱心和关怀的产物；所以它不能给陌生人。在雷霆崖的长老认为你的品德高尚之前，我不能卖给你科多兽。"
D.Strings[3236]="唉$c，你不是达纳苏斯的贵族，也不是泰达希尔的上层精灵。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供马匹让你挑选的。"
D.Strings[3237]="后退！小孩子不应该在这儿的！回去吧，孩子们！"
D.Strings[3238]="入侵者！攻击入侵者！"
D.Strings[3239]="胆大的约翰森？我听说塔顶的赛场主管科鲁克莱德知道他在哪儿。"
D.Strings[3240]="你在寻找约翰森？哦，我不该说太多，不过……或许你该问问塔顶的科鲁克莱德，他会告诉你……"
D.Strings[3241]="很抱歉，如果你不是暴风城中的贵族，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人，当然……你只需赢得暴风城的信任，我就可以跟你做买卖了。"
D.Strings[3242]="现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡有着显赫的地位，那我会很乐意让你看看我出售的多种战羊的。"
D.Strings[3243]="呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟高贵的侏儒做生意。要是你是诺莫瑞根的侏儒贵族，我会很高兴地为你提供服务的。"
D.Strings[3244]="在我教你骑术之前，你必须达到被铁炉堡的矮人所崇拜的声望才行，$c。"
D.Strings[3245]="在我教你骑术之前，你必须达到被幽暗城的被遗忘者所崇拜的声望才行，$c。"
D.Strings[3246]="在我教你骑术之前，你必须达到被诺莫瑞根逃亡侏儒所崇拜的声望才行，$c。"
D.Strings[3247]="在我教你骑术之前，你必须达到被暴风城的人类所崇拜的声望才行，$c。"
D.Strings[3248]="在我教你骑术之前，你必须达到被达纳苏斯的暗夜精灵所崇拜的声望才行，$c。"
D.Strings[3249]="在我教你骑术之前，你必须达到被奥格瑞玛的兽人所崇拜的声望才行，$c。"
D.Strings[3250]="在我教你骑术之前，你必须达到被雷霆崖的牛头人所崇拜的声望才行，$c。"
D.Strings[3251]="在我教你骑术之前，你必须达到被暗矛部族的巨魔所崇拜的声望才行，$c。"
D.Strings[3252]="我不认为你具有掌握传送门魔法所必需的潜质。"
D.Strings[3253]="请教教我吧。"
D.Strings[3254]="我名叫蒙提，老鼠是我的玩物。"
D.Strings[3255]="这些栖息在这片荒地上的科多兽的兽皮最为坚韧。"
D.Strings[3256]="你的技巧已经超过我了，年轻人。去找尤纳，她在雷霆崖的中央高地上有一家商店。她能给你你需要的指导。"
D.Strings[3257]="你已经准备好学习科多兽制皮的要点。让我们开始吧……"
D.Strings[3258]="在光明与黑暗之间，还有阴影……而那些阴影有些你未曾见过的力量。"
D.Strings[3259]="你在卡兹莫丹不会找到更好的老鼠肉烧烤店的！"
D.Strings[3260]="你看起来能用一些机件，$g小伙子:女士;。你应该上地铁去拜访我的兄弟蒙提，他在铁炉堡矿道地铁库房。我肯定他有些事情是你能做的。"
D.Strings[3261]="陌生人，小心身后。"
D.Strings[3262]="你并未得到拉文霍德公爵的认可，$c。"
D.Strings[3263]="鲁莽的家伙。拉文霍德公爵可不喜欢这样的人。"
D.Strings[3264]="你好，$c。你找法拉德谈过了吗？"
D.Strings[3265]="辛迪加工会的成员都是些平庸的家伙——缺乏组织性、技能拙劣、懒惰……"
D.Strings[3266]="你敢踏入拉文霍德庄园，可怜虫？"
D.Strings[3267]="不借助刀具或是毒药离开这儿就算完成任务。"
D.Strings[3268]="你一直进行得不错，$n。我听到好消息了……"
D.Strings[3269]="你该与温斯顿谈谈。我听说他在寻找一个与你有相同技能的潜行者。"
D.Strings[3270]="愿月神与你同在，$c。月神殿已经来帮助奥伯丁饱受煎熬的公民了。"
D.Strings[3271]="苏亚米在旅馆前面。去吧，我正忙着呢。"
D.Strings[3272]="要照料宠物吗？你得确保它的清洁！去旅馆前面找苏亚米吧。"
D.Strings[3273]="到荣誉山谷去并在马厩附近找到克苏卡。"
D.Strings[3274]="克苏卡会把你多余的宠物圈养起来的。到荣誉山谷的竞技场和猎人大厅之间的畜栏里找到他，现在走吧！"
D.Strings[3275]="啊是的，你必须找到希克瓦。我记得我最后一次见她时她在旅馆前面站着。"
D.Strings[3276]="希克瓦能在你需要的时候帮你照看宠物。去旅馆前面找她吧。"
D.Strings[3277]="你需要布尔鲁格的帮助。他在旅馆和雷霆崖银行间较低的山上。"
D.Strings[3278]="你对自己的宠物伙伴表现出的关爱之情是值得赞扬的。矮山上的布尔鲁格能帮助你照看宠物。他居住在银行和旅馆之间的地方，去找他吧。"
D.Strings[3279]="说也奇怪，兽栏管理员莫加努斯就在马厩外面。"
D.Strings[3280]="你不算太聪明吧？嗯，如果我是兽栏管理员的话，我应该是在马厩附近吧？去那边找莫加努斯吧。"
D.Strings[3281]="兽栏管理员"
D.Strings[3282]="安雅·玛尔雷在贸易区上层的旅馆中。"
D.Strings[3283]="阿拉辛是个值得信赖的人，让他来悉心照料你的任何宠物。他就住在猎人们聚集的塞纳里奥区。"
D.Strings[3284]="数百年以来阿拉辛一直很关心我们猎人视作朋友的动物。他对动物的关心被周围的猎人所追随。如果你也来向他请教，那么就到塞纳里奥区找他。"
D.Strings[3285]="我们共同构成了一个巨大的拼图，$n。跟你一样，很多人都在进行小块拼图的整合工作。$B$B或许还有更强大的人正在将这些人当作拼图来玩。"
D.Strings[3286]="啊，友善的瑟里亚迪。在她的庇护下，所有动物都很安全。你可以在多兰纳尔的旅馆外找到她。"
D.Strings[3287]="你寻找一个喜欢动物的人？那么你应该到多兰纳尔旅馆的外面寻找瑟里亚迪。她就是你找的那个人。"
D.Strings[3288]="好心的旅店老板艾玛，她现在已经照顾当地的动物好些年了。我敢肯定她会很高兴照顾你给的任何动物。你可以在狮王之傲旅店的外面找到她。"
D.Strings[3289]="旅店老板艾玛照料着这周围的所有动物。要是你需要跟她交谈的话，就去狮王之傲旅店外面找她。"
D.Strings[3290]="矮人区的耶诺瓦·石盾是你要找的人。在猎人接受她父亲的训练时，她帮着照看猎人的宠物。"
D.Strings[3291]="如果你需要将宠物关在屋内，以便训练另一只宠物的话，就去矮人区找耶诺瓦·石盾谈谈。"
D.Strings[3292]="$g小伙子:姑娘;，你可以去卡拉诺斯雷酒酿制厂外找谢尔比·石火。她会好好照顾你的宠物的。"
D.Strings[3293]="谢尔比·石火帮当地猎人看管宠物。如果你想让她帮你照看宠物的话，就去雷酒酿制厂找她吧。"
D.Strings[3294]="乌布雷克·火拳总是极其认真地照顾动物。如果你想让他帮你照看宠物的话，就去武器大厅找他吧，他通常跟那些猎人在一起。"
D.Strings[3295]="你可以在武器大厅找到我们的常驻马厩管理人乌布雷克·火拳。他将替你喂养和照料宠物。"
D.Strings[3296]="我给你带来一些东西，$n。它们看起来挺重要的。"
D.Strings[3297]="欢迎来到军情七处总部，$n。"
D.Strings[3298]="$n，这是今天早上送来给你的。"
D.Strings[3299]="拉文霍德的信使今天早上将这封信交给了我。这是写给你的，$n。"
D.Strings[3300]="这将是一场艰难的战事，$n。跟我来吧！"
D.Strings[3301]="这是火盆，$n。熄灭它。沃尔沙是一头野兽，不值得任何人赞扬！"
D.Strings[3302]="我对你表示最深的感激，谢谢你。"
D.Strings[3303]="我会再巡视这片地区一会儿并确保一切安全。"
D.Strings[3304]="请回到佐拉姆加前哨站，向战歌信使汇报我们的成功。"
D.Strings[3305]="你确信自己已准备就绪？要是没有你的帮助，我们一定会失败的。"
D.Strings[3306]="我们成功了！"
D.Strings[3307]="什么事，$c？你在汇报吗？"
D.Strings[3308]="出现吧，我的奴仆！保卫你们的主人！"
D.Strings[3309]="你们不是烈焰之王的敌人！出现吧，火焰的奴仆！你们的主人在召唤你们！"
D.Strings[3310]="部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被狗头人控制着。"
D.Strings[3311]="联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被穴居人控制着。"
D.Strings[3312]="这座纪念碑是用于缅怀在暴风城保卫战中牺牲的勇士。我们的人民经受了难以想象的痛苦才得以恢复自由，重新掌握自己的命运。我们将永远铭记那些在第一次兽人战争中牺牲的同胞。"
D.Strings[3313]="联盟占领了冷齿矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[3314]="联盟夺取了深铁矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[3315]="部落占领了冷齿矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[3316]="部落占领了深铁矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[3317]="奥特兰克山谷中的作战物资总是非常缺乏。"
D.Strings[3318]="我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。"
D.Strings[3319]="干得好，士兵。我需要回到大本营！你愿意掩护我吗？"
D.Strings[3320]="你来的真是时候。怎么耽搁了这么久？啊，没关系。掩护我，士兵。我必须返回基地！"
D.Strings[3321]="还有很多工作要做，$n！继续消灭我们的敌人！"
D.Strings[3322]="是的，$n。元素很活跃。很快，我们就会将他们的能量释放到我们的敌人身上。他们会被彻底击垮的！"
D.Strings[3323]="我已经做过接触了，$n。那是冰雪之王洛克霍拉。他认为我们的事业很有价值--我们给大地的祭品十分充足。他很快就来了……做好准备。"
D.Strings[3324]="我需要一些增援来带我安全地飞离这儿，返回基地。"
D.Strings[3325]="日记中似乎记载了关于贸易、买主和其它商业事务的信息。"
D.Strings[3326]="绝不要直视指挥官的眼睛。"
D.Strings[3327]="我们直接受命于凯恩，$r。不要干预指挥官的工作。"
D.Strings[3328]="萨满指挥官可不能小瞧，$r。"
D.Strings[3329]="很快，洛克霍拉就会出现……很快……非常，非常快……"
D.Strings[3330]="空军部队整装待发，$n。你必须带上火炬，把它放在战场中心的东部环形山中。在空军部队进行定位时，你必须好好保护火炬！"
D.Strings[3331]="我是水元素公爵海达克西斯。你不是元素生物的一员，所以你不明白我们的困境，但是或许我们可以达成一项对双方都有益处的协议……"
D.Strings[3332]="$n，见到你真好。我们与其它的元素之间的战斗正酣，但是你的参与会确保我们的胜利。"
D.Strings[3333]="舰队整装待命，$n。你必须带着这个信号灯并把它放置在中央战区西部的凹地里。保护信号灯不被攻击，直到舰队能够锁定它的坐标！"
D.Strings[3334]="大地之母日夜监视着我们。让这火焰照亮我们的身体和灵魂吧，让我们想起尊敬的祖先，他们一直都在我们身边，指导我们前行。"
D.Strings[3335]="$n，你还在等什么？去征战平原找指挥官特拉瓦雷，将攻击指令交给他。一旦他得到指令，他和他的军队就能发动对部落的攻击，不留活口！"
D.Strings[3336]="如果你想在塞纳里奥议会中找寻某些档案的话，我就是那个你要交谈的人。你首先要知道要寻找的确切信息，那样我才能帮你。$B$B看看那个，真是光彩夺目呀！"
D.Strings[3337]="别聆听来自世界的心声——答案就在你心中，你知道真相的。"
D.Strings[3338]="死者在这片荒地长眠，$c。我们必须小心，别惊动他们。"
D.Strings[3339]="$n，你准备好完成终极任务了。刻在熔火之心地面上的炽热的符文是通向火海的导管,它们的存在既是对我们的侵犯，又是炎魔之王的力量源泉。必须把它们扑灭！$B$B要熄灭符文，拿一小瓶水之精华。把它倒在符文上,火焰就会熄灭,这会使其变得毫无用处并能削弱我们的敌人！"
D.Strings[3340]="欢迎来到幽暗城公会登记处。你需要什么帮助么？"
D.Strings[3341]="欢迎来到塞纳里奥议会，$c。我要怎么帮你呢？"
D.Strings[3342]="跟海达克西斯公爵交谈。"
D.Strings[3343]="你跟我没有关系，小家伙。"
D.Strings[3344]="闭上你的脏嘴！也只有海达克西斯公爵才受得了你。"
D.Strings[3345]="你好，小伙计。你跟水元素之王有关系吗？"
D.Strings[3346]="关于你的英雄事迹已经流传开来。我们没有听说过你的名字，$n。"
D.Strings[3347]="你已经把我们的敌人当成了你自己的敌人。我会很高兴能与你分享水的伟大。"
D.Strings[3348]="或许你能告诉我你的一些事情，$n。我非常想听听。"
D.Strings[3349]="海达克西斯公爵赞扬你。我的水就是你的水，朋友。"
D.Strings[3350]="当你下次去熔火之心时，请为我杀死一个火焰之王，行吗？"
D.Strings[3351]="你看起来像是那种手脚不干净的人。有什么我可以帮忙的吗？"
D.Strings[3352]="必须修复全视之眼！"
D.Strings[3353]="我们奉命从达纳苏斯来到这儿，帮助身处患难的卡尔·雷矛。"
D.Strings[3354]="大德鲁伊相信，一旦森林之王伊弗斯意识到山谷中的破坏性力量，他就会出现的。"
D.Strings[3355]="让伊弗斯来裁决这些暴行吧。"
D.Strings[3356]="我的信念指引着我的行动，$r。我知道伊弗斯会来的。"
D.Strings[3357]="我迷失在梦里了。我感觉到了他的生命力，但是我的力量还不够强大，无法进行沟通。"
D.Strings[3358]="是的。$n。我已经查到了森林之王的位置。我们必须加倍努力！需要更多的水晶！"
D.Strings[3359]="森林之王已经知晓了这个山谷的毁灭，$n。很快我们就要到召唤法阵去了。做好准备！"
D.Strings[3360]="我被穆维里克这个鲁莽的蠢货击中了。我担心要是我无法回到基地中去的话，一切都要玩完了！必须阻止穆维里克和他的飞行中队！"
D.Strings[3361]="真不敢相信……我在中央非军事区执行例行侦察任务时，事情变得一团糟。我看见部落中校穆维里克击倒了艾克曼和斯里多尔！我发怒了，冲出队伍将穆维里克打倒在地。不幸的是，他在倒下之前击中了我的狮鹫，我也随之跌下。我被这些野蛮的家伙抓住啦。$B$B我必须返回基地！帮帮我！"
D.Strings[3362]="当我的狮鹫坠落时，我听到了他们嘲弄的笑声，$c。$B$B“斯里多尔， 你太差劲了！”他们大声嚷道。$B$B没有人敢对斯里多尔那样说话！帮我离开这里，我会让他们知道我的厉害！"
D.Strings[3363]="这片森林容易使人迷路！要小心。"
D.Strings[3364]="储存下来的物资都给你和你的家属！"
D.Strings[3365]="这是刚从农场带来的新鲜货--这是烟林牧场的健康食品！"
D.Strings[3366]="现在是廉价货上市的时候！啦啦啦啦！"
D.Strings[3367]="尽情享受冬幕节吧！品尝来自烟林牧场的盛宴！"
D.Strings[3368]="请告诉冬天爷爷是什么秘密让你想要得到冬幕！"
D.Strings[3369]="别花钱购买那些铃当！为了你的冬幕盛宴，把烟林牧场买下吧！"
D.Strings[3370]="要是我有栗子的话，你最好相信我会将它们烤熟吃掉的。嗯！"
D.Strings[3371]="在假期里不要忘记储备包装纸！没什么能比包装精美的护甲和武器一样让你的朋友和家人感受到冬幕节的温馨快乐！"
D.Strings[3372]="让我看看你携带的食物。"
D.Strings[3373]="我们的军队已经升级到勇士，但是我仍需要收集更多的军需。"
D.Strings[3374]="到这儿是学习如何使用新武器，还是来浪费我时间的？"
D.Strings[3375]="我想进行一些武器方面的训练"
D.Strings[3376]="其他的武器大师能教给我什么呢？"
D.Strings[3377]="你想要学习哪种武器技能？"
D.Strings[3378]="穿过丹巴达尔以东的桥梁，雷矛墓地就在群山之中。$B$B联盟控制着这片土地。"
D.Strings[3379]="霜狼墓地就在离霜狼村北面不远的地方。$B$B部落控制着这片土地。"
D.Strings[3380]="祝你过一个神奇的冬幕节，小$G伙子:姑娘;！好孩子在任何烟林牧场小卖部都有特别优惠的哦。"
D.Strings[3381]="这轮结束后冬天爷爷会做什么呢，我有一个很好的主意。我在包里有一瓶冬幕啤酒，而且我想喝光它。"
D.Strings[3382]="不……你不能坐在我的膝盖上。"
D.Strings[3383]="是的，当然，去告诉冬天爷爷你都想从这个冬幕中得到什么。$B$B赶紧些。"
D.Strings[3384]="雷矛一族不会对任何人俯首称臣的，特别是部落！"
D.Strings[3385]="你的攻击太微弱了！去找些兔子练习一下，当你强壮些后再回来找我。"
D.Strings[3386]="你这样的乌合之众是不可能打倒我的！"
D.Strings[3387]="我们一定会完成使命的！"
D.Strings[3388]="联盟会胜利的！"
D.Strings[3389]="你不能击败霜狼部落！"
D.Strings[3390]="我想你的进攻因为寒冷减弱了！"
D.Strings[3391]="如果你不自动离开奥特兰克山谷，霜狼会强迫你离开的！"
D.Strings[3392]="你不是部落的力量的对手！"
D.Strings[3393]="你会在今天见到你的祖先的！"
D.Strings[3394]="他们说食物是行军的保障，这是真的。要想成功应对敌人的攻击，军队必须拥有足够的粮草和装备供应。"
D.Strings[3395]="有人说军队的成功靠的是力量和勇气。这是真的！但是军队同样需要充足的物资来维系士气，我的工作便是确保他们的物资需求。"
D.Strings[3396]="士兵，你好。你是来帮我的吗？"
D.Strings[3397]="士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑！"
D.Strings[3398]="嗨。你到这儿来学习如何使用新武器算是来对地方啦。"
D.Strings[3399]="啊，$n！你就是我希望见到的人！我们已经拥有足够的军备，可以对部落发动地面攻击！指挥官特拉瓦雷正在征战平原等待指令……$B$B你曾多次证明自己是一名勇敢且经验丰富的士兵。你想为特拉瓦雷传达指令吗？"
D.Strings[3400]="你对哪种武器感兴趣？"
D.Strings[3401]="如果你有能力学习的话，我是很荣幸教你如何使用武器的。"
D.Strings[3402]="$n！我们的军备正在减少，在我们获得更多的军备之前是无法发动对征战平原的地面攻击的！$B$B跟雷矛军需官谈谈，他会告诉你如何增加我们的军备。"
D.Strings[3403]="如果你想要进行更多训练，我可以告诉你该去哪里。你想要学习哪种武器呢？"
D.Strings[3404]="卡尔·雷矛，死吧！"
D.Strings[3405]="我猜想你到这儿来是训练如何使用新武器的？快点，我很忙的！"
D.Strings[3406]="$n，在战场上看到你这样经验丰富的家伙真好！很抱歉，我们军队的物资过低，无法发动对部落的大规模地面攻击。$B$B跟我们的军需官谈谈，他会给你供给任务的。"
D.Strings[3407]="你是来学习如何作战吗？"
D.Strings[3408]="我可没法教你战斗时如何保持优雅姿态，我只能教你如何使用武器。"
D.Strings[3409]="我可以告诉你该找谁进行训练。你对哪类武器感兴趣？"
D.Strings[3410]="你想学习如何使用武器，是吗？嗨，$g小伙子:姑娘;，别在站在那儿发呆啦，大声说吧！"
D.Strings[3411]="嗨！你是来这儿学习新武器的吗？"
D.Strings[3412]="你想要学习哪种武器？"
D.Strings[3413]="啊~~~！"
D.Strings[3414]="霜狼，死吧！"
D.Strings[3415]="等待上级命令！"
D.Strings[3416]="奥特兰克本地出产的山羊对我们的骑兵至关重要！"
D.Strings[3417]="再有一些坐骑我们的马厩就满啦。士兵，让我来保管它们吧。我会从这儿牵走一些。"
D.Strings[3418]="我想寄放我的宠物。"
D.Strings[3419]="很高兴遇见你，$n。要做的事情还很多，我们必须抓紧时间。"
D.Strings[3420]="愿塞纳留斯指引你，$c。$B$B我和我的姊妹身负重任，从塞纳里奥议会来到这片被污染的土地。而只有那些足够强大的人才能帮助我，毕竟让能力不足的人去完成任务是愚蠢的做法。"
D.Strings[3421]="我和我的姐妹从石爪山脉来到这儿，想要终止数年来的悲剧。不幸的是，我们还不够强大，无法独立完成目标，想向你这样的人寻求帮助。$B$B如果你足够强大，我们就谈谈任务的详细情况，$c。如果你还不够强大，那么，为了你的安全着想，就到此为止吧。"
D.Strings[3422]="向你致意，$r。"
D.Strings[3423]="在这世上，我已经不需要什么立足之地了，$c。部落……所有的部落成员将看见。他们相互交战，这是为了什么？遍地是秃鹫留下的骸骨……军团大肆侵犯我们的土地……呸！$B$B半人马应该为他们的遗产感到骄傲——这些遗产就跟暗夜精灵或兽人的遗产一样高贵——现在是我们效仿的时候啦！"
D.Strings[3424]="最后，我从将我禁锢在此的腐化中解脱了……"
D.Strings[3425]="感谢你所做的一切，$n。$B$B请保管好节杖，它可以帮你抵御那些入侵此地的邪恶力量。"
D.Strings[3426]="我的节杖……这么多年过去了……你终于重新得到它了！你真是这儿的救世主……$B$B请仔细听我说，$n。只有在玛拉顿之石才能将节杖的杖头和杖身结合在一起。"
D.Strings[3427]="在繁复的色彩中出现一条小路。$B$B被光线映衬得闪闪发光。$B$B你从水底浮上来。"
D.Strings[3428]="在玛拉顿大门附近的橙色和紫色通道之间还有一条道路。$B$B你手中的节杖便是钥匙。"
D.Strings[3429]="我越来越疲惫了……$B$B从这儿你可以看见瀑布，$n……要是你敢再次进入玛拉顿的大门，节杖将赋予你抵达那儿的能力。$B$B在玛拉顿的入口附近，你会看见一条通往洞穴之下的通道。在远古遗址处使用节杖创造传送门，你就可以进入玛拉顿了。"
D.Strings[3430]="很久以前，我和我的森林女神姐妹们曾进入这些洞穴，想释放我的叔叔扎尔塔倍受折磨的灵魂。但是，已经充斥了所有洞穴的腐化力量很快击败了我们。$B$B我们注定要在此迷失方向；毒素侵蚀了我们的头脑……$B$B尽管现在我的灵魂已经安息，但是我知道我没能完成任务。我要为此承担巨大的悲伤……"
D.Strings[3431]="啊，扎尔塔……<塞雷布拉斯把头扭了过去。>$B$B我的父亲雷姆洛斯试图阻止他……$B$B扎尔塔太顽固了，当他爱上一位土元素公主时，我父亲就知道他们的结合将受到诅咒，但是扎尔塔拒绝听从父亲的意见。$B$B他因此变成了半人马。他们生下来就带着畸形的躯体，并充满仇恨；我的叔叔扎尔塔被自己的亲戚所杀……$B$B那个邪恶的瑟莱德丝公主，还在水晶洞穴内守护着他的遗体。"
D.Strings[3432]="欢迎来到探险者联盟。如果你需要书面信息的话，我也许能帮你。"
D.Strings[3433]="潜伏在玛拉顿的毒素开始渗入我的头脑，我逐渐丧失对事实的判断力。我的树妖姐妹们担心我会被恶魔利用，她们悄悄地拿走了我的节杖，将节杖断成两截，藏在洞穴中。$B$B很快，她们也丧失了理智，两段节杖也因无人看守，成了维利塔恩的囊中之物。那个萨特将一截节杖交给邪恶的元素诺克赛恩看管，另一截则由他自己保管至今。"
D.Strings[3434]="没有结合节杖两部分所需的咒语，诺克赛恩是无法使用节杖的。但是，我已经从诺克赛恩的诅咒中解放啦，如果你能将节杖的两部分交给我——节杖的头部和棍身，我会帮助你的。"
D.Strings[3435]="你问到塞纳留斯的儿子雷姆洛斯和扎尔塔。$B$B我的父亲雷姆洛斯强壮英俊，我的叔叔扎尔塔矮小灵动。虽然两人受到大家的一致尊重，但是扎尔塔总认为自己无法得到雷姆洛斯所享受的荣耀和受到的关注。$B$B我和我的姐妹们出生后，扎尔塔在嫉妒心的驱使下，想要超越他的兄弟……他自作自受。即使事情已经过去了这么久，我心中仍悲恸不已……"
D.Strings[3436]="你好，$n。我是格里高利·维克托医生，部落的首席外科医生。"
D.Strings[3437]="很高兴再次见到你，$n医生。我看着你逐步成长，我敢说现在是你学习更高的绷带技能的时候啦。$B$B一旦你的技能得到提高，就回来找我，我会把我所知的一切都教给你的。"
D.Strings[3438]="你好，$n。我是古斯塔夫·范沃森医生，联盟的首席外科医生。"
D.Strings[3439]="嗨，$n！很高兴你来看我。我们正准备对征战平原发动一场规模浩大的地面攻击！等到霜狼突击队队长一声令下，他和他的部队将给予联盟致命的攻击！$B$B你想传达这些命令吗，$n？加瑞克在征战平原等着你呢……"
D.Strings[3440]="能在奥特兰克山谷找到你这样经验丰富的家伙真好，$n。我们的军需不够，无法发动对奥特兰克山谷的地面攻击……跟我们的军需官谈谈——他会告诉你如何增加我们的军需储备。"
D.Strings[3441]="你！$n！你在山谷这儿游荡什么呢？在奥特兰克到处都是联盟的敌人！我们必须赶走它们！$B$B我们的军需不够，无法发动大规模的地面攻击,跟我们的军需官谈谈.他会告诉你如何增加我们的军需。"
D.Strings[3442]="我负责霜狼氏族的军队招募工作。作为一名霜狼士兵，如果你的等级足够高的话，就来向我报到吧。$B$B在冰冷的战场上，你会获得荣誉和尊重的。"
D.Strings[3443]="你好，$r！我是哈格丁中尉，是负责招募雷矛卫兵的官员。$B$B你在雷矛军队中获得一定的威望后再来找我吧，我会升级你的徽章的。如果你丢失了徽章，我也能再给你一枚。"
D.Strings[3444]="小心$n！"
D.Strings[3445]="你会后悔遇见我的，$n。"
D.Strings[3446]="我们的祖先教诲说，集体的力量胜过个人的力量。你想要加入公会为了雷霆崖的荣誉而战吗？"
D.Strings[3447]="是的，你看起来是个领导者。你是来这里组织公会与联盟作战吗？"
D.Strings[3448]="你好，$c。我是罗卡鲁。"
D.Strings[3449]="你向蓝龙要求什么？"
D.Strings[3450]="奈辛瓦里要出去狩猎。我发现帮助他做丛林狩猎的准备工作比做战争准备的工作轻松多了。尽管我错过了战场上的光辉岁月。"
D.Strings[3451]="卡拉然，请为火炬附魔。"
D.Strings[3452]="我对这片森林非常熟悉，它们就像我身体的一部分……但是它们还蕴藏着很多值得学习的知识，当然也有很多危险。"
D.Strings[3453]="莱恩，我把达图尔的变形魔棒弄丢了。"
D.Strings[3454]="是的，我曾盼望你能回来。早些时候，我派科兰出去，她发现了达图尔的魔棒被遗弃在森林里。$B$B我们竭力想要找回它，$n。请你小心以后不要掉了它。"
D.Strings[3455]="你已经完成了泰洛尼斯的任务，感谢你所做的一切，$n。"
D.Strings[3456]="你好！这间工场不是我的，不是！但是终有一天当我完成训练后，我将成为一名发明家，就像我崇拜的英雄玛尔冯·瑞文斯克那样。$B$B你从来没有听说过他吗？哦，碰巧他已经离开好长一段日子啦，他去研究远古巨魔废墟啦，他是乘坐地精飞艇走的……我也不是很清楚他究竟去了哪儿……$B$B塔纳拉辛？坦克利斯？塔纳里萨尼？$B$B<莉芙摇着头。>$B$B不，名字不是这样……"
D.Strings[3457]="嗨。不，玛尔冯一定不在这儿，他还要好些时间才能回来呢。实际上，我有些担心他……$B$B我希望他能很快回来。有人寄了一只大箱子给他，我可没力气把这东西拖进去！我只能把它放在门口……"
D.Strings[3458]="你已经学会了我现在能教你的所有知识，$n医生。当你获得更多经验的时候再来找我吧，我会传授给你更多高级的医学知识的。"
D.Strings[3459]="这地方……受到了诅咒。$B$B我刚刚设法逃脱，我可不想再进入那些地道啦。$B$B但是，我的兄弟姐妹……就没这么幸运了。他们被困在里面，恶魔花园散发的堕落烟雾令他们疯狂。$B$B你一定要帮帮他们。"
D.Strings[3460]="哦，很高兴你已经回来啦，$n。$B$B我兄弟的灵魂已经从堕落中解脱啦，但是我得留在此地表示我的哀悼。$B$B非常感谢你的帮助，$n。"
D.Strings[3461]="需要物资供给吗？"
D.Strings[3462]="雷矛墓地被联盟占领了！"
D.Strings[3463]="雷矛墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[3464]="雷矛墓地被部落占领了！"
D.Strings[3465]="雷矛墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[3466]="雪落墓地被联盟占领了！"
D.Strings[3467]="雪落墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[3468]="雪落墓地被部落占领了！"
D.Strings[3469]="雪落墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[3470]="霜狼墓地被联盟占领了！"
D.Strings[3471]="霜狼墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[3472]="霜狼墓地被部落占领了！"
D.Strings[3473]="霜狼墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[3474]="你是来学习战斗的艺术的，$r？你来错地方了。"
D.Strings[3475]="你是来学习战役案例的吧？听好了，我会为你讲解那些显赫的胜仗和耻辱的败仗的。"
D.Strings[3476]="来吧，小家伙们。面对我！"
D.Strings[3477]="提起精神，士兵！雷矛智者报告说冰斧巨魔已经抓住了一名地精工程师。霜狼正试图解救他，以便利用他的工程学制品来摧毁我们！可别让这种事情发生。"
D.Strings[3478]="据报，辛迪加工会东部平原的一处洞穴人声鼎沸。去看看那儿发生了什么事，士兵！小心霜狼的活动！"
D.Strings[3479]="进入霜狼领土时要当心，士兵。这儿到处都是陷阱！还有无数的地雷！跟前线第一座塔楼的爆破专家谈谈。我想他会教你如何处理这些情况的。"
D.Strings[3480]="那么听好了，$c。$B$B你能感知到从我身上散发出的力量吗？你的士气不够？是的，对另一方来说也是这样。要破坏瓦解他们的军队并不容易，但是必须完成任务！胜利是属于我们的！"
D.Strings[3481]="六名中尉指挥着前线的防御事务。必须迅速解决他们！我们绝不能让他们的任何一名牧师活着逃回去。$B$B要是我们能很快结果掉所有的中尉，前线的士气将大跌！战线也会很快攻破！他们的军队将落荒而逃，留守的士兵将失去后援。"
D.Strings[3482]="搜索生命体……没有发现目标"
D.Strings[3483]="发现不明生物体……判断中……"
D.Strings[3484]="目标丢失……返回搜索模式"
D.Strings[3485]="无能为力……没有力气啦……恢复……必须恢复……瑟雷姆控制着……结束这痛苦的折磨吧……"
D.Strings[3486]="谢谢你，人类。在我重回梦境之前我只能帮助你一次。$B$B通往瑟雷姆的主人奥兹恩的大门阻挡了你前进的道路。我会充当你破坏的器械。我等待你的命令，帮你打开大门。"
D.Strings[3487]="石炉墓地就在征战平原的石炉前哨东面。$B$B联盟控制着这片土地。"
D.Strings[3488]="我们有很多物资储备啦，但是要发动对征战平原的地面攻击，我们还需要更多的物资。"
D.Strings[3489]="我们有一些物资，但是现在有很多啦。我们还需要一些来发动对征战平原的地面攻击。"
D.Strings[3490]="我们几乎没有物资装备。想要发动对征战平原的地面攻击的话，还需要很多物资！"
D.Strings[3491]="$n，我们已经具备了足够的物资来发动对征战平原的地面攻击。如果你想要传递指令，而且你的等级足够高的话，就跟霜狼村的亚斯拉·血矛谈谈。"
D.Strings[3492]="$n，我们已经具备足够的物资来发动地面攻击。如果您在雷矛守卫的声望够高的话，就跟诺雷格·雷矛中尉谈谈吧。"
D.Strings[3493]="我们的物资储备已经很多了，但是要发动对征战平原的地面攻击，我们还需要更多的物资。"
D.Strings[3494]="我们有剩余的物资，但是不太多。我们还需要更多的物资才能发动对征战平原的地面攻击。"
D.Strings[3495]="我们几乎没有多余的物资。要发动对征战平原的另一场地面攻击，我们还需要很多物资。"
D.Strings[3496]="发动地面攻击还需要多少物资供给？"
D.Strings[3497]="啊……这些家伙让我整天都不得安宁！你看见他们了吗？$B$B我真希望自己能藏到地下，避开他们……"
D.Strings[3498]="再升一级还需要多少物资供给？"
D.Strings[3499]="我差不多拥有足够的物资供给来升级部队了。"
D.Strings[3500]="我差不多拥有足够的物资供给来升级到精练部队了。"
D.Strings[3501]="我需要更多的物资来升级我们的军队。"
D.Strings[3502]="升级到精练部队所需的物资还差一半呢。"
D.Strings[3503]="升级到勇士军队所需的物资还差一半呢。"
D.Strings[3504]="我几乎没有任何可供升级的物资。"
D.Strings[3505]="我们的军队不能升级，军需不够，无法升级。"
D.Strings[3506]="我们的军队已经升级到经验丰富的军队，但是我没有足够的军需升级到老兵。"
D.Strings[3507]="我们的军队已经升级到精练部队，但是我没有足够的军需升级到勇士。"
D.Strings[3508]="我有足够的军需将我们的军队升级到有经验的军队。"
D.Strings[3509]="我有足够的军需将我们的军队升级到老兵。"
D.Strings[3510]="我有足够的军需将我们的军队升级到勇士。"
D.Strings[3511]="我不能再存储物资了。我的背包都满了！"
D.Strings[3512]="丹巴达尔南部碉堡受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3513]="丹巴达尔南部碉堡被部落摧毁了！"
D.Strings[3514]="丹巴达尔南部碉堡受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3515]="丹巴达尔南部碉堡被联盟占领了！"
D.Strings[3516]="丹巴达尔北部碉堡受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3517]="丹巴达尔北部碉堡被部落摧毁了！"
D.Strings[3518]="丹巴达尔北部碉堡受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3519]="丹巴达尔北部碉堡被联盟占领了！"
D.Strings[3520]="冰翼碉堡受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3521]="冰翼碉堡被部落摧毁了！"
D.Strings[3522]="冰翼碉堡受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3523]="冰翼碉堡被联盟占领了！"
D.Strings[3524]="石炉碉堡受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3525]="石炉碉堡被部落摧毁了！"
D.Strings[3526]="石炉碉堡受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3527]="石炉碉堡被联盟占领了！"
D.Strings[3528]="西侧霜狼哨塔受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3529]="西霜狼哨塔被部落占领了！"
D.Strings[3530]="西侧霜狼哨塔受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3531]="西侧霜狼哨塔被联盟摧毁了！"
D.Strings[3532]="东侧霜狼哨塔受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3533]="东霜狼哨塔被部落占领了！"
D.Strings[3534]="东侧霜狼哨塔受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3535]="东侧霜狼哨塔被联盟摧毁了！"
D.Strings[3536]="哨塔高地受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3537]="哨塔高地被部落占领了！"
D.Strings[3538]="哨塔高地受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3539]="哨塔高地被联盟摧毁了！"
D.Strings[3540]="冰血碉堡受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
D.Strings[3541]="冰血哨塔被部落占领了！"
D.Strings[3542]="冰血哨塔受到攻击！如果我们不尽快采取措施，联盟会摧毁它的！"
D.Strings[3543]="冰血哨塔被联盟摧毁了！"
D.Strings[3544]="雷矛急救站被部落占领了！"
D.Strings[3545]="雷矛急救站受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[3546]="雷矛急救站被联盟占领了！"
D.Strings[3547]="雷矛急救站受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[3548]="霜狼急救站被部落占领了！"
D.Strings[3549]="霜狼急救站受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[3550]="霜狼急救站被联盟占领了！"
D.Strings[3551]="霜狼急救站受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[3552]="我没什么可以教你的了。我听说藏宝海湾有个名叫海明威的老头，他在出售《鲈鱼与你》这本书，它对你提高钓鱼技能大有帮助。"
D.Strings[3553]="看到那边坏掉的陷阱了没？愚蠢的食人魔对此感到束手无策。很明显，只要略做修理就能恢复原状！要是你能修好它，我敢打赌斯里基克一定会中圈套。哈哈——食人魔卫兵掉入陷阱！"
D.Strings[3554]="石炉墓地被部落占领了！"
D.Strings[3555]="石炉墓地受到攻击！如果我们不尽快采取措施的话，部落会占领它的！"
D.Strings[3556]="石炉墓地被联盟占领了！"
D.Strings[3557]="石炉墓地受到攻击！如果我们不尽快采取措施的话，联盟会占领它的！"
D.Strings[3558]="冰血墓地被部落占领了！"
D.Strings[3559]="冰血墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[3560]="冰血墓地被联盟占领了！"
D.Strings[3561]="冰血墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[3562]="在奥特兰克山谷中两处矿洞：联盟领地上的深铁矿洞和部落领地上的寒齿洞穴。两处矿洞都有丰富的矿产资源，在过去，它们用于存储过剩的物资。$B$B现在，部落、联盟和当地居民常常争夺矿洞。"
D.Strings[3563]="奥特兰克山谷的哨塔和碉堡都是至关重要的战略性据点。要是我们能控制哨塔，就能展开远程攻击啦。"
D.Strings[3564]="逝者的灵魂在奥特兰克山谷的墓地安息。如果你死了，你的灵魂将被送往最近的墓地。"
D.Strings[3565]="雷矛急救站在丹巴达尔，就在丹巴达尔军营外。$B$B联盟控制着这片土地。"
D.Strings[3566]="雪落墓地就在征战平原的高山顶部，就在冰斧要塞以东。$B$B联盟和部落还在争夺这片土地。"
D.Strings[3567]="霜狼急救站在霜狼城堡中，就在霜狼哨塔以南。$B$B部落控制着这片土地。"
D.Strings[3568]="冰血墓地位于征战平原南面，就在冰血哨塔以东。$B$B部落控制着这片土地。"
D.Strings[3569]="看看这片被蹂躏的土地，你就知道元素的力量了，$r。"
D.Strings[3570]="丹巴达尔南部碉堡保护着丹巴达尔要塞的东南侧。$B$B联盟控制着这片土地。"
D.Strings[3571]="丹巴达尔北部碉堡保护着丹巴达尔要塞的东部入口。$B$B联盟控制着这片土地。"
D.Strings[3572]="冰翼碉堡是联盟领地和征战平原之间的要塞。$B$B联盟控制着这片土地。"
D.Strings[3573]="石炉碉堡是征战平原东侧的要塞。$B$B联盟控制着它。"
D.Strings[3574]="东部哨塔高地守护着征战平原和南部部落领土之间的要塞。$B$B部落控制着这片土地。东部霜狼哨塔守护着霜狼村和霜狼城堡之间的大门。$B$B部落控制着这片土地。"
D.Strings[3575]="西侧防御塔点是征战平原和南部部落领土之间的要塞。$B$B部落控制着这片土地。"
D.Strings[3576]="西侧防御塔点是征战平原和南部部落领土之间的要塞。$B$B联盟和联盟还在争夺这片土地。"
D.Strings[3577]="冰血哨塔保护着冰血要塞。$B$B部落控制着这片土地。"
D.Strings[3578]="西侧霜狼哨塔是霜狼村和城堡之间要塞。$B$B部落控制着这片土地。"
D.Strings[3579]="你对此了解多少？"
D.Strings[3580]="我知道很多，好好听着吧，$r。"
D.Strings[3581]="我在听，德米提恩。"
D.Strings[3582]="很久以前，在篡位者称为创世之年代的时候，我的主人和他的同胞们统治着整个世界。是他们，是远古的神灵创造了一切。$B$B他们最终被那些称他们为缔造者的家伙推翻了。"
D.Strings[3583]="他们庞大的身躯在多年的战乱中渐渐衰弱，被禁锢在地下世界——他们自己创造的地下世界中——堕落的泰坦缔造者能渗透地表，污辱古老的神灵。$B$B兄弟反目。一场持续五千年的战争在世界的核心展开。"
D.Strings[3584]="部落和联盟的队长都已经进入战场啦。$B$B我们的队长巴琳达·斯通赫尔斯现在带领着来自石炉哨站的雷矛军队，而对方的队长加尔范上尉也从冰血要塞发出了指令。$B$B战斗开始啦！"
D.Strings[3585]="不！！！把鞣酸放进篮子，否则我打扁你！"
D.Strings[3586]="部落和联盟的队长都已经进入战场啦。$B$B我们的队长加尔范上尉现在带领着来自冰血要塞的霜狼军队，而对方的队长巴琳达·斯通赫尔斯正躲在石炉哨站。$B$B战斗开始啦！"
D.Strings[3587]="加尔范上尉已经被杀死啦，德雷克塔尔现在领导着来自霜狼城堡的军队。$B$B为了死去的队长的荣耀，向联盟进攻！"
D.Strings[3588]="奥特兰克山谷很久以前就已经成为霜狼氏族的家园了，我们不会让矮人和他们的联盟侵犯这片土地！因此我们不断地战斗！$B$B要赢回奥特兰克山谷，就必须打败他们的首领范达尔·雷矛。$B$B为了部落而战！"
D.Strings[3589]="雷矛部族在奥特兰克山谷中发现了远古的神器，但是霜狼兽人对探险者们可不那么友好。要是矮人想要保护祖先的文化遗产，一场恶战是不可避免的！$B$B要在战争中获胜，就必须打败霜狼将军德雷克塔尔。祝你好运，$c！"
D.Strings[3590]="巴琳达·斯通赫尔斯领导着联盟的前锋军队。她以征战平原以北的石炉哨站为基地。$B$B如果她死掉的话，上层首领范达尔·雷矛将进入丹巴达尔的奥特兰克山谷。$B$B巴琳达现在在石炉哨站。"
D.Strings[3591]="德雷克塔尔是奥特兰克霜狼氏族的军事和精神领袖。在奥特兰克的时候他领导着霜狼城堡的兄弟们作战。$B$B如果他被打败，奥特兰克的部落军队将溃不成军，但是现在他只会在下属加尔范上尉死后露面。$B$B德雷克塔尔现在在霜狼城堡里。"
D.Strings[3592]="加尔范上尉是德雷克塔尔值得信赖的助手。他领导着来自征战平原以南的冰血要塞的部落军队。$B$B如果加尔范上尉的话，德雷克塔尔将进入霜狼要塞的奥特兰克山谷。$B$B加尔范上尉现在在冰血要塞里。"
D.Strings[3593]="范达尔·雷矛是驻守在奥特兰克山谷的联盟将军，他指挥着来自丹巴达尔的军队。$B$B如果他被打败，联盟将在奥特兰克一役败北；但是只有在巴琳达·斯通赫尔斯阵亡后他才会出现。$B$B范达尔目前不在奥特兰克山谷。"
D.Strings[3594]="一场战斗？"
D.Strings[3595]="炎魔之王拉格纳罗斯在元素大灾变中想要杀死我的主人桑德兰，空气的王子。$B$B<德米提恩低下头，面部肌肉因愤怒而扭曲。>$B$B一旦你说出他的名字，我就会用你的内脏装点这座被破坏的营帐。保持安静，听好了。"
D.Strings[3596]="<点头>。"
D.Strings[3597]="拉格纳罗斯、迦顿和加尔背叛了我的领主。桑德兰王子在毫不知情的情况下被捕了。"
D.Strings[3598]="在毫无觉察的情况下碰到的？怎么会？"
D.Strings[3599]="桑德兰王子对炎魔之王的进攻毫不知情。在王子做出反应之前，传说中拉格纳罗斯使用的大锤萨弗拉斯就会无情地痛击王子。桑德兰倒下了，他完全被打败了。$B$B炎魔之王吸取了王子的精华，但这仍然不能满足他的贪欲。"
D.Strings[3600]="那么，拉格纳罗斯接下来做了什么？"
D.Strings[3601]="桑德兰的精华的些许残留物存储在元素绑定护符中。拉格纳罗斯将护符打碎成两块，分给了他的两名士官……"
D.Strings[3602]="丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔现在完好无损。"
D.Strings[3603]="霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞完好无损。"
D.Strings[3604]="你找到钥匙啦？嗯，是那把钥匙吗？我指的是能打开这些枷锁的钥匙。$G先生:女士;，只有一种方法能证明！"
D.Strings[3605]="你现在是首领啦！你是我们的王！向戈多克王$n致敬！$B$B既然你是首领，所有的手下都会为你上贡的！你留下一些活口的，是吗？"
D.Strings[3606]="哦不！国王死啦！呃……向新国王致敬！啊！"
D.Strings[3607]="想要钥匙的话，就来追我吧！"
D.Strings[3608]="你想玩个游戏吗，自以为是的人？"
D.Strings[3609]="我拥有通往那里的钥匙！跟着我来吧，你会看到的！"
D.Strings[3610]="游戏？你疯了吗？"
D.Strings[3611]="如果你敢的话就来追我吧！我会毫不犹豫地奔跑的！"
D.Strings[3612]="还活着吗？惊讶吧。眼睁睁看着我逃跑吧！"
D.Strings[3613]="为什么你这么矮小……"
D.Strings[3614]="记住我的话，我会抓住你的，小鬼。我会的！"
D.Strings[3615]="为什么你想要伤害我！？我们可以成为朋友的！"
D.Strings[3616]="皱皱眉头！"
D.Strings[3617]="死？！你把普希林弄哭啦！"
D.Strings[3618]="这是底线，你不再是我的朋友啦！"
D.Strings[3619]="准备跟你的缔造者见面吧。"
D.Strings[3620]="跟我的小朋友问声好！"
D.Strings[3621]="我是新国王？你在说什么？"
D.Strings[3622]="老大手下的所有下属——践踏者克雷格、三名守卫、克罗卡斯和观察者——都为新的国王献上贡品。如果你杀死了一名下属，这名下属就不能为新国王上贡啦！留下的活口越多，你得到的贡品就越多。别杀他们，你会得到很多东西的！$B$B就是这样的！"
D.Strings[3623]="那么……把贡品给我吧！"
D.Strings[3624]="嗯，从我跟食人魔的交战情况来看……你不必逐一杀死这儿的所有食人魔。$B$B就在前几天戈多克大王恢复权力，杀死以前的国王取而代之的时候，食人魔纷纷离开此地。嗯，国王的追随者们——戈多克没有要他们的命——立即发誓效忠新国王。$B$B谁知道呢——你饶恕的食人魔说不定会效忠于你呢……当然，这是打个比方！"
D.Strings[3625]="你现在是首领了，对吗？祝新国王长命百岁！$B$B克雷格让你看看戈多克酒。食人魔酒是所有酒中的极品，戈多克酒则是食人魔酒中的极品！你能从我这里买一些，是不是国王？！"
D.Strings[3626]="好吧老大，当你想要下属为你上贡的时候，就告诉我！"
D.Strings[3627]="陌生人，离开这儿吧，免得送命，它会吃掉它接触到的一切东西的。"
D.Strings[3628]="精灵，这儿发生了什么事？"
D.Strings[3629]="你知道上层精灵吗？你知道辛德拉古吗？"
D.Strings[3630]="我对上层精灵知之甚少，对辛德拉更是一无所知。"
D.Strings[3631]="辛德拉古是艾萨拉女王最器重的奥术学家。女王最重要的物品都在这些高大的城墙内秘密制造完成。$B$B永恒之井被破坏后，上层精灵陷入浑浑噩噩的境地，一支较小的暗夜精灵氏族，埃雷萨拉斯的王子托塞德林开始建造水晶塔，你可以在西侧的城墙那儿看到那些分散在各处的水晶塔。"
D.Strings[3632]="王子策划将拥有巨大力量的恶魔伊莫塔尔禁锢到一个巨大的力场中。水晶塔能将潜在的能量汇集到这个力场中。$B$B一旦被囚禁，恶魔将成为埃雷萨拉斯人民的能量来源。"
D.Strings[3633]="真令人着迷啊。请继续。"
D.Strings[3634]="汲取的能量能维持上层精神的魔力，使埃雷萨拉斯的人民满足他们对魔法无尽而持续增长的渴求。$B$B数千年过去了，用于监禁恶魔伊莫塔尔以及维系埃雷萨拉斯人民生命的力量开始减弱。监禁恶魔所需的魔法就要超过所能汲取的魔法。曾经的能量机制已经不复存在。"
D.Strings[3635]="我要杀一些东西，是吗？"
D.Strings[3636]="你所见到的那些在埃雷萨拉斯的庭院和城墙附近游荡的上层精灵灵魂不是被戈多克食人魔或萨特所杀，而是死于王子之手！"
D.Strings[3637]="我们生活在无尽的悲剧中。"
D.Strings[3638]="王子为了获得永恒的生命和无尽的力量，杀死了许多人。数千人的力量全部汇集到王子和辛德拉狂热者身上。那些少数的幸存者不停地向水晶塔输送能量来禁锢恶魔伊莫塔尔。$B$B如果恶魔挣脱束缚，它一定会毁掉这座曾经繁荣辉煌的魔法都市。"
D.Strings[3639]="很悲伤的故事。谢谢你，灵魂。"
D.Strings[3640]="卑微的家伙，你现在是个男人啦！"
D.Strings[3641]="卫兵芬古斯令你变得凶残！疯狂！啊！"
D.Strings[3642]="你可找到我啦，头儿！斯里基克陷入的大块的冰块中！好在我动作敏捷，很快就逃了出来！哈哈！$B$B或许冰块很快就会融化……"
D.Strings[3643]="是，你真是个笨蛋。斯里基克，你认为自己有多聪明？"
D.Strings[3644]="头儿，我会让你看看我有多聪明的！有了这些强大的魔精，你会更聪明的！$B$B嗯……我应该用在自己身上……"
D.Strings[3645]="你是戈多克的国王！你是至高无上的王！"
D.Strings[3646]="叫我“国王”。你为我带来了什么！"
D.Strings[3647]="我听说你已经死啦……嗯，以后你想要装死的话就不那么容易啦！"
D.Strings[3648]="我统治这个王国已经有一万年啦。在那时，我从那些神圣的辛德拉家族成员那儿听到很多令人着迷的故事。$B$B由于我必须呆在这儿，所以我常常和访问者沟通交谈。你可以为我讲个故事吗，或许你想听听我的故事？"
D.Strings[3649]="谁敢破坏埃雷萨拉斯的圣洁？懦夫，面对我！"
D.Strings[3650]="我们可不能惹恼了他。他发起火来就没有节制啦。"
D.Strings[3651]="陌生人，把你的声音放小一点。你不是想打扰主人的沉思吧。"
D.Strings[3652]="许多人来到这个避难所，少数人却离开了。"
D.Strings[3653]="他真的死了。你成了新国王……嗯，就是你！戈多克是你的啦，国王！你应该跟我谈谈，了解这儿的一切！我是……我是他的助手！是的，这就是我为什么被称为狡猾的家伙的原因！"
D.Strings[3654]="博学者是个古老的学者。他为我们伟大的女王服务！"
D.Strings[3655]="嘿，芬古斯说谁是恋豺狼人癖？！把囚犯交给国王吧，他们携带着武器，对国王来说是个威胁。我倒要看看当我把芬古斯打趴下的时候他还敢说什么！哈！"
D.Strings[3656]="没有人能打败我，没有人敢威胁国王！死吧！"
D.Strings[3657]="你在附近闲逛什么？为什么不把那些小家伙锁起来？！"
D.Strings[3658]="现在你变得强大了！向戈多克的新国王致敬！"
D.Strings[3659]="嗯，我要把这些人带到国王那里去听候发落。"
D.Strings[3660]="为什么他们身上还有武器？你为什么不拿走他们的武器？！"
D.Strings[3661]="呃……我就是这样找到他们的。我想告诉国王他们是个威胁！我跟你说啊，头儿……我无意中听到卫兵芬古斯说你是个肥胖无用的恋豺狼人癖！"
D.Strings[3662]="好吧，芬古斯，你什么意思？！你敢叫我恋豺狼人癖，看我一锤打得你找不到北！"
D.Strings[3663]="尘归尘，土归土！"
D.Strings[3664]="让火焰净化一切吧！"
D.Strings[3665]="感受萨弗隆的烈焰吧！"
D.Strings[3666]="追随者？贡品？"
D.Strings[3667]="当国王真好！现在，让我们继续谈谈你刚才说的事儿……"
D.Strings[3668]="嗯，你杀死了国王，是吗？这就是说你取代了他的位置。你成为了新的头目！向国王致敬！"
D.Strings[3669]="哦，真恐怖！这是个悲剧！我们就要突破啦，但也有可能遭遇全军覆灭的惨剧。"
D.Strings[3670]="呃……很抱歉我袭击了你。不要杀我，求你了！？你是国王啦，我会为你提供更多的贡品的！"
D.Strings[3671]="粗略地检查一下骸骨，上面的肉已经干枯了。真是令人毛骨悚然的场景。"
D.Strings[3672]="我很怀疑他有什么话可说，陌生人……"
D.Strings[3673]="我个人并不在意他。王子从未如此对待过他领地中的高等精灵。唉，我还没资格质疑王子。不过至少,他并没有立即把温萨鲁斯烧成灰。"
D.Strings[3674]="我们再也不想得到什么关注啦，陌生人。回到那些让你来找失踪的管理员的家伙那儿去吧，告诉他们什么都找不到。然后回到我这儿来，我会告诉你一个失传的秘密。"
D.Strings[3675]="向阵亡者默哀。"
D.Strings[3676]="那么，现在我是国王啦……你给我带来了什么？！"
D.Strings[3677]="从可怕的上层精灵王子那儿取回戈多克的遗物，或许你能比老头目做得更好！"
D.Strings[3678]="向新国王致敬！"
D.Strings[3679]="在你成为新国王之前，我曾对你横眉竖眼……嗯……我那是在开玩笑。$B$B是的！"
D.Strings[3680]="其他的食人魔居然攻击你，他们太笨了，国王！这就是我还活着的原因——我既聪明又结实！"
D.Strings[3681]="我们可比塔纳利斯的食人魔干净多了。那片沙漠中到处都是食人魔。这儿可不是，$g先生:女士;！"
D.Strings[3682]="只要你跟我们呆在一起，你就是国王。你离开的话，会有其他食人魔取代你的位置的。这就是戈多克的行事之道！"
D.Strings[3683]="我很聪明！我知道二加二等于五！"
D.Strings[3684]="老国王死了吗？那不可能！"
D.Strings[3685]="国王陛下，我可没有给你带来什么麻烦。"
D.Strings[3686]="最近书本丢失甚多。博学者和他的助手非常恼怒。他们怀疑在埃雷萨拉斯有人妄图不轨。"
D.Strings[3687]="王子不再讲述灰烬使者的故事了吗？在他的诸多故事中，我们最喜欢这个。他的爱好则是寻找灰烬使者的下落。当然，没人能从他口中得知那个故事。"
D.Strings[3688]="我猜想那些小鬼在偷学知识。"
D.Strings[3689]="王子对奈法利安的巢穴非常感兴趣。如果有谁能杀死巨龙及其属下，并将战斗经过告诉王子，我敢打赌王子会非常满意的。找到灰烬使者之日可待啦！"
D.Strings[3690]="你不跟米兹勒谈话的话是当不了国王的！跟他谈谈！"
D.Strings[3691]="那么……你杀死了国王？我就知道这些家伙会拥戴你成为新国王的。我就知道！那些家伙只知道力量。$B$B似乎你赦免的跟随者越多，献殷勤的人也就越多。别这么不公平——我是说来一次有趣的挑战。如果你离开，我可不希望继续当国王。这些家伙肯定有人趁机取代你的地位。$B$B还有……你找到了我的钥匙，是吗？"
D.Strings[3692]="你必须明白，像我这样活了一万年的人，对生命有独特的看法。眼下你经受的考验和磨难都是毫无意义的。"
D.Strings[3693]="哦，年轻的主人制造的这一系列事件和慌乱。可以想象，世界的命运就掌控在他手中。只有人类才会对世界产生这种扭曲的看法。$B$B唉，他将奥术的秘密都告诉了我……圣契之类的无用之物。这种东西对我来说是一无是处，但是或许你对它们感兴趣。"
D.Strings[3694]="被偷啦，$r！我们最珍贵的三卷卷轴。如果你能找回来的话，一定会得到丰厚的报酬的。"
D.Strings[3695]="%s开始反击，展开报复！"
D.Strings[3696]="帮我粉碎这些微不足道的家伙！"
D.Strings[3697]="别向我挑战，矮小的家伙！现在我是国王啦，永远都是！！！"
D.Strings[3698]="<你无法理解这份卷轴上记载的任何技术。>"
D.Strings[3699]="<羊皮纸上画着的是修理机器人的结构示意图。>"
D.Strings[3700]="<将这份结构示意图复制到你的工程学书本中。>"
D.Strings[3701]="<依你目前的工程学技能是看不懂这张复杂的结构示意图的。>"
D.Strings[3702]="<你精通制造和操作这个机器人。>"
D.Strings[3703]="世界的构造精妙细致。只靠某些知识和对已知知识的应用是不可能破坏世界构造的。裂缝也由此产生。"
D.Strings[3704]="盯着敌人，$r。看吧，强大的部落足以对付巨龙！所有跟我们做对的人都是这种下场！"
D.Strings[3705]="我们都是部落的一份子。牛头人，兽人，巨魔以及其他所有种族。永远别忘了，我们都是部落的成员。"
D.Strings[3706]="我活着就是为了为国王服务。"
D.Strings[3707]="或许有一天，你对联盟的贡献会跟你今日所见的英雄一样伟大。尊重英雄吧，$n。"
D.Strings[3708]="主人，您的到来令我们倍感荣幸。"
D.Strings[3709]="拥有万年历史的知识卷轴将那些邪恶的家伙吸引到图书馆。大量的书籍被盗，被找回之后再次被盗。"
D.Strings[3710]="基尔达斯总是过分夸大。比如，“迦罗娜：潜行与诡计研究”已经被偷过400多次啦。$B$B神殿的标志保护着这本卷轴，防止任何人偷看。"
D.Strings[3711]="我可没时间停下来。"
D.Strings[3712]="是的，我知道它真正的名字——埃雷萨拉斯。许多许多年前，那儿曾是暗夜精灵的魔法研究基地。$B$B你知道埃雷萨拉斯吗，年轻的$c？也许有人会说这跟我目前的处境很巧合……但是我可不相信巧合这回事。"
D.Strings[3713]="塞纳里奥议会的人已经了解到埃雷萨拉斯的近况了。我陷入了僵局，不知如何是好。我很可能要向那些体格强健、善于作战的冒险者寻求帮助。$B$B但是，要对埃雷萨拉斯采取行动，就要了解关于丰饶之果的知识。"
D.Strings[3714]="多年前，埃雷萨拉斯是魔法师的集中地，居住在那些神圣的大厅中的人都能使用强大的魔法。米琳丝特·塞雷恩就是这样一名暗夜精灵——她是个博学者，她可以将大自然的力量灌输到她铸造的神器中。$B$B丰饶之果就是她的杰作……她利用特殊的月亮井制造出一种奇异的、具备保护和生长效力的藤蔓来。埃雷萨拉斯在藤蔓的滋养下日益繁华起来。"
D.Strings[3715]="唉，事情似乎总是这样。和塞纳里奥议会的其他人一样，我也认为米琳的杰作在上古战争时就被毁掉了。但是我最近认识到，这种观点是错误的。$B$B丰饶之果并未被摧毁……尽管现在它被称为魔藤。它被埃雷萨拉斯的恶魔领主，荒野变形者奥兹恩污染了。"
D.Strings[3716]="我……我无法想象，$n。我只知道我不能让这件事发生。它必须被摧毁的——就算不是为了阻止那些恶魔，也要为了米琳丝特·塞雷恩……米琳……$B$B我的朋友，这就是我希望你伸出援手的事情。"
D.Strings[3717]="<德米提恩跪倒在地。>$B$B你已经找回了主人的牢笼！$B$B我期待这一天已经很久很久了，我的愿望终于实现了。$B$B必须解放我的主人！"
D.Strings[3718]="我这里有他的重生之瓶。如果你决心接受这项任务，就必须保护好这只小瓶，并击败拉格纳罗斯！"
D.Strings[3719]="必须使用源质对重生之瓶进行加固。我只知道这种矿物的一种原料：位于这个世界核心中的元素领域。$B$B塑地者对这种东西的了解比我多得多。你必须找到塑地者！"
D.Strings[3720]="向你致敬，英雄！我有来自大陆和岛屿的最新消息，供你参考。"
D.Strings[3721]="你必须摧毁拉格纳罗斯的肉身，他的精华将在尸体的残骸中出现。在他极度虚弱的时候，他对桑德兰的控制将被大大减弱。精华本身就是一把钥匙……"
D.Strings[3722]="你需要去尘泥沼泽找纳特·帕格接受训练，提高自己的能力。"
D.Strings[3723]="我可以教你一些钓鱼技能。"
D.Strings[3724]="海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝腮沼泽中。"
D.Strings[3725]="凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。"
D.Strings[3726]="悲伤沼泽泪水之池有许多带锁的上个世纪丢失的盒子。"
D.Strings[3727]="灼热峡谷熔渣之池的黑铁矮人有许多带锁的箱子。"
D.Strings[3728]="塔纳利斯的落帆海湾和艾萨拉的风暴海湾都有许多上锁的箱子，打开之后即可提高你的技能。"
D.Strings[3729]="东瘟疫之地蒂尔引领的血色十字军有许多带锁的箱子，这对你的技能可是个挑战。"
D.Strings[3730]="兽人将许多带锁的物资箱沉入了赤脊山的止水湖。"
D.Strings[3731]="在纳迦侵袭灰谷佐拉姆海岸时，许多带锁的物资箱都丢失啦。"
D.Strings[3732]="以石爪山脉狂风峭壁为基地的风险投资公司将他们的物资存储在带锁的箱子里。"
D.Strings[3733]="辛迪加工会在希尔斯布莱德的敦霍尔德城堡有许多带锁的箱子。"
D.Strings[3734]="<德米提恩笑了。>$B$B愚蠢的家伙，你的奖励就是痛苦地死去！"
D.Strings[3735]="我研究这个世界上的已知和未知的元素。"
D.Strings[3736]="我们陷入生存危机。我们陷入困境，寻找答案，希望在黑暗中闪闪发光。$B$B那时，$n，就是我们迈向自由的第一步。"
D.Strings[3737]="你有蜘蛛或是甲虫吗，$c？它们速度很快，但是如果你的速度更快的话，你会发现拥有它们是件乐事！"
D.Strings[3738]="戈瑟奇，我想买点东西。"
D.Strings[3739]="你刚从地下城出来吗？有什么东西给我的吗？"
D.Strings[3740]="你的护甲看起来很破旧。你为此感到胆怯吗？"
D.Strings[3741]="我不允许你进入神庙！我会摧毁你的！"
D.Strings[3742]="如果我要落入地狱，那么你们这些凡人也要跟我同去！"
D.Strings[3743]="我长大后想成为暴风城的王！"
D.Strings[3744]="我以前去过铁炉堡。那儿闻起来怪怪的。"
D.Strings[3745]="蘑菇总是生长的阴暗的地方，因此它们长得像雨伞。"
D.Strings[3746]="如果罩衫是由顶部的摁扣固定的，那为什么还需要袢带呢？"
D.Strings[3747]="要是你的鼻涕在鼻子里结冰了怎么办？"
D.Strings[3748]="鱼不会口渴吗？"
D.Strings[3749]="如果你想要失败，但是却成功了，你做了什么？"
D.Strings[3750]="要是你真是部落的英雄，我想看看你屠龙！啊！"
D.Strings[3751]="当闪电击中海洋的时候，为什么所有的鱼都没有死？"
D.Strings[3752]="没有翅膀的鸟可以被称为步行生物吗？"
D.Strings[3753]="我的鼻子里有块石头。"
D.Strings[3754]="要是海龟没有壳的话，那不就成无家可归或是裸体啦？"
D.Strings[3755]="“咔咔”是什么意思？"
D.Strings[3756]="要是你的手套太大的话，还算是合手的手套吗？"
D.Strings[3757]="你离家还远着呢，$r。"
D.Strings[3758]="你来了。你是来学习镇压和控制之道的吧。$B$B我会教你更多的东西……你将学会牺牲。$B$B<戴奥咧嘴而笑。>"
D.Strings[3759]="你得选择自己要召唤和驱使的恶魔。我们运用黑暗力量并为此付出巨大的代价。"
D.Strings[3760]="要是你还想继续前进的话，我们必须首先找人对付野兽。"
D.Strings[3761]="卑微的家伙，在我面前鞠躬吧！你能感受到我那强大的力量。"
D.Strings[3762]="这么说，你是来找尼比学习如何从虚空中召唤地域火仆从的。$B$B安静！尼比什么都知道！$B$B他可不会这么轻易地将知识传授给你。首先，你必须帮助尼比完成一项至关重要的任务。"
D.Strings[3763]="在这座营地的东北面有一个名叫克罗苏斯的强大的地狱火。这就是尼比待在这儿的原因。克罗苏斯极其强大，前所未闻。你瞧，菜鸟，地狱火以极高的速度坠落在地面上，但是它的生命却很短暂。一旦火焰熄灭，地狱火便崩溃了。"
D.Strings[3764]="别打断我，你这个蠢货！我会把你身上的肉刮下来，把你的骨头做成衣架。我说到哪儿了？哦，对，克罗苏斯的存活时间是普通地狱火的10倍。我不知道为什么会这样，但是我想只要进行足够的研究，我一定可以查明真相。$B$B你必须帮我找到克罗苏斯的火焰核心。"
D.Strings[3765]="要想让我教你召唤地狱火仆从，你必须杀死克罗苏斯，然后从他燃烧的尸体中取出恶魔之核交给我。但是这项任务并不简单，克罗苏斯几乎已经烧尽了。你必须重新点燃他的尸体，令他复活。所以你必须从其它恶魔那儿收集一些东西才能令他复活。$B$B我的孩子，准备上路吧。"
D.Strings[3766]="克罗苏斯活了？克罗苏斯要摧毁一切！"
D.Strings[3767]="退后！退后！与地狱火保持安全距离！"
D.Strings[3768]="向全能的主鞠躬吧！满怀敬畏之情看着我所召唤出来的毁灭一切的地狱……小鸡？"
D.Strings[3769]="%s笑得在地上打滚。"
D.Strings[3770]="尼比，你是个白痴。"
D.Strings[3771]="肃静，仆人们！复仇吧！摧毁暴风城！让他们全军覆灭！"
D.Strings[3772]="战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B部落将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。"
D.Strings[3773]="战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B联盟将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。"
D.Strings[3774]="吉安娜女士，这听起来像是个奇怪的请求……但是我正在照顾一个非常害羞的孩子。对他来说，你是个英雄，他想要你的签名。"
D.Strings[3775]="哎呀……你可真是好人。我听说你是儿童周的志愿者，是吗，$c？嗯，你会受到赞扬的。我们必须记得那些不幸的人——特别是那些孩子。$B$B我很高兴能给他签名。给你。"
D.Strings[3776]="年轻人，欢迎你来到雷霆崖。在这儿你能卸下负担，享受庇佑。我们欢迎所有的部落居民来到雷霆崖。$B$B我的朋友，灵魂都会来这个神圣的地方复活。尊敬他们吧，这也是尊敬你自己。"
D.Strings[3777]="啊，毫无疑问，他一定是想要成为一名战士！我想你是来参加儿童周的，是吗？你的行为堪称楷模，其他人必定会以你为榜样的，这令那些疲惫不堪的灵魂倍感欣慰。$B$B我很乐意帮助你和这位年轻的男子。嗯……我要给他提些什么建议呢？听听灵魂怎么说吧，是的……或许是关于吃掉所有蔬菜……"
D.Strings[3778]="看护者之周还没有结束……我能再拿一个孤儿哨吗？"
D.Strings[3779]="去银风避难所找珊蒂瑞亚吧。她可以卖给你“中级烹饪教材”。"
D.Strings[3780]="加基森的迪尔格·奎克里弗对厨艺非常精通。要想提高自己的能力，你就去找他吧。"
D.Strings[3781]="葬影村的乌兰可以卖给你“中级烹饪教材”。如果你想要提高烹饪技能的话，就需要这本书。"
D.Strings[3782]="我可以教你如何烹饪！"
D.Strings[3783]="现在，只有著名的格里高利·维克托医生能提高你的技能啦。你可以在阿拉希高地的落锤镇找到他。"
D.Strings[3784]="尘泥沼泽蕨墙村的格鲁克卡恩在卖指南书，你需要好好研究它来提高自己的技能！"
D.Strings[3785]="倍受尊敬的古斯塔夫·范沃森医生能进一步训练你。他在塞拉摩的兵营里治疗伤兵。"
D.Strings[3786]="我听说居住在激流堡的德尼布·沃克有一本书，这本书一定能帮助你提高急救技能。"
D.Strings[3787]="我可以教你急救技能。"
D.Strings[3788]="恐怖战马的灵魂散发出愤怒的气息。"
D.Strings[3789]="啊，我亲爱的朋友们！我在古拉巴什竞技场放了一些宝贝！你们要做的只是去竞技场中央，打开箱子，然后拿到里面的财宝！"
D.Strings[3790]="开始厮杀吧！"
D.Strings[3791]="加德纳尔的行事准则是隐晦奸诈。别在这儿探头探脑，$C，否则你的灵魂就会被永远禁锢在此……"
D.Strings[3792]="滚！我只和恐惧魔王打交道，你没资格来跟我说话！"
D.Strings[3793]="来自贝恩霍勒的消息？是什么消息？他需要伟大的导师和仆人乌拉泰克吗？他需要我吗？"
D.Strings[3794]="什么？但是怎么可能呢？不！这不可能！我已经很小心了……他不可能知道的！$B$B你撒谎！你撒谎，你欺骗了我，去死吧！"
D.Strings[3795]="多么幸福的活着的一天啊！朋友，看看你周围的美景吧。享受自然赋予你的一切！"
D.Strings[3796]="*呜噜噜* *汪* *汪汪*"
D.Strings[3797]="熔岩？朋友，别在意那个。看看你周围吧。享受自然赋予的一切欢乐。"
D.Strings[3798]="每年的这个时候我都会来希利苏斯。这里的气候对治疗我的拇趾囊肿很有帮助。$B$B你应该跟我四处逛逛，朋友。欣赏一下风景什么的。"
D.Strings[3799]="在这么偏远的地方遇到人可真好啊。来吧，跟我一起。让我们用身体互相取暖。"
D.Strings[3800]="军官的休息室"
D.Strings[3801]="去力量谷西边的山顶找找看。"
D.Strings[3802]="你要去传说大厅？它就在西边的力量谷上边。"
D.Strings[3803]="突然之间，你成为了“联盟的保卫者”，是吗？！嗯，我猜你一定是想去勇士大厅。大厅就在旧城区。"
D.Strings[3804]="在旧城区的东南角落，你可以找到勇士大厅。"
D.Strings[3805]="%s变得极为狂暴！"
D.Strings[3806]="跟着我吧，圣骑士。我制造马饰比我喝矮人烈酒要快。嗯……烈酒。"
D.Strings[3807]="嗯，这能应该就行了。来吧，回到商店，完成我们的交易！"
D.Strings[3808]="要是你是来找世界上最富经验的工匠，你就找对地方啦！$B$B格瑞曼德·艾尔默，愿为你效劳！"
D.Strings[3809]="要召唤恐惧战马，你必须首先开启一道强大的法阵。通往克索诺斯世界的传送门只可能在这种法阵中打开。$B$B而开启法阵，你就需要三种魔法器具：达斯莫拉的铃铛、黑色战车之轮和末日蜡烛。"
D.Strings[3810]="%s的皮肤闪着微光，它畏缩了。"
D.Strings[3811]="啊……英雄们。你们都会坚持不懈的，是不是？你们这群凡人想要与我的力量相抗衡——那么你们就要付出代价。现在他将为我而战……他的任务就是干掉你们。"
D.Strings[3812]="啊！没有比看人们在竞技场中互相厮杀更好看的东西了。如果你来得是时候的话，那你也将是他们中的一员！"
D.Strings[3813]="是的，那是真的，我好像一只蝙蝠一样瞎了！而且还醉得……呃，醉得好像喝了很多酒。$B$B我会告诉这个感受的，$r。是酒让我感觉灵敏。人人都知道如果你丧失了一种感觉，那么另外一个感觉会变得更加灵敏。我的饮酒感觉这两天非常灵敏。"
D.Strings[3814]="我们选择了离开黑石深渊的保护出来探险……呃，我是说……嗯，我们这么做是对的，我们要探索整个世界。"
D.Strings[3815]="博恩奈特是我的名字，我把铁匠作为我的兴趣……另外，呃……我还卖一些食物和水。来点肉类怎么样？"
D.Strings[3816]="很高兴再见到你，$n！我不知道我还可以坚持多久来创建这样一个店。现在，由于你对我的帮助，我会给你看一些你会感兴趣的东西！"
D.Strings[3817]="当洛洛尔不想撒掉他宝贵的酒或者弄脏他衣服的时候，我就被召唤而来。是的。汉瑟尔就是别人口中正义和痛苦的结合体。"
D.Strings[3818]="作为驻扎在这里的工头，我的职责就是确保在这里所进行的所有事情，从工作到休息和放松都包含着一定的令人厌烦的成分。$B$B如果你发现某件你被要求去做的事情过于简单或者没有什么好抱怨的话，请立即向我报告。"
D.Strings[3819]="你已经完成我要求你做的事情，$n。我这里没有什么需要你做的了。如果你想继续为瑟银兄弟会服务的话，和黑石深渊的黑铁酒吧的罗克图斯·暗契谈谈。$B$B再见！"
D.Strings[3820]="我发誓……如果奎恩提斯胆敢再乱栽食虫花，我就马上把他的树给砍了。"
D.Strings[3821]="不管我是不是瑟银兄弟会的，只要有个黑铁矮人敢靠近我，我一定会让他们尝尝我的厉害！现在，你想去哪里呢，$g小伙子:小姑娘;？"
D.Strings[3822]="只要那些矮人一直待在那里，我们就不会有麻烦。你现在要去哪里，$n？"
D.Strings[3823]="你是不是想要我在强大的$n所率领的军团之前畏缩？$B$B你对我来说不算什么。什么都不是。取你的性命对我来说是易如反掌的事情。$B$B你犯了所有凡人都会犯的错误。$B$B<维克多·奈法里奥斯叹了口气。>$B$B如果你像花钱一样花费你的时间，那就会发生一些奇怪的事情。"
D.Strings[3824]="我做不到，瓦拉斯塔兹！一定有什么办法可以拯救你！"
D.Strings[3825]="牧师们！如果你们要继续这么治疗的话，那我们就来玩点有趣的东西吧！"
D.Strings[3826]="猎人们，还有你们那些讨厌的玩具枪！"
D.Strings[3827]="你们也是法师？小心别玩火自焚……"
D.Strings[3828]="德鲁伊和你们愚蠢的变形法术。让我们看看有什么事情会发生吧！"
D.Strings[3829]="术士们，不要随便去尝试那些你们根本不理解的法术。看到后果了吧？"
D.Strings[3830]="圣骑士……听说你们有无数条命。让我看看到底是怎么样的吧。"
D.Strings[3831]="萨满祭司，让我看看你们的图腾到底是干什么用的！"
D.Strings[3832]="战士们，我知道你们可以更加勇猛！让我们见识一下！"
D.Strings[3833]="潜行者？不要躲躲藏藏了，勇敢地面对我吧！"
D.Strings[3834]="一个巨大的人类手印出现在宝珠的表面。除了看上去的那些处理过的痕迹，宝珠并没有损坏。"
D.Strings[3835]="宝珠的印记和你的手正好适合。"
D.Strings[3836]="我……我失败了，$n。黑石……黑石山脉的领主实在是太强大了。他轻易地……轻易地吸收了我的力量。我已经……我……请你一定要……一定要杀了我。"
D.Strings[3837]="我是联军的指挥官。我是惩戒之拳。我的职责就是扫清其拉虫人的势力。你敢挑衅酋长的权威吗？你敢直面我无情的审判吗？"
D.Strings[3838]="你没看到我在这里钓鱼吗？"
D.Strings[3839]="你把我的鱼吓走了！你到底要怎么样？"
D.Strings[3840]="我可以为你做什么吗，$c？"
D.Strings[3841]="我要一直待在这里直到钓到68磅重的石斑鱼！你却要离开到什么地方去，是不是？"
D.Strings[3842]="看看这条被干掉的龙的脸，$r。部落的强大是毋庸置疑的！"
D.Strings[3843]="怒焰裂谷是由许多火山洞穴所组成的，它位于部落的新都城奥格瑞玛中。最近，有传言说一群忠于阴影教会的教徒占据了那个地方。这群被称为火刃得教徒威胁了杜隆塔尔的安宁。许多人相信兽人酋长萨尔已经意识到了火刃的存在，他并不想着急于摧毁他们，因为萨尔希望这个教会能够将他带往阴影教会。"
D.Strings[3844]="黑石领主从灰烬中升起！"
D.Strings[3845]="快点离开，市民。没有什么好看的。"
D.Strings[3846]="你有兴趣探索这些地下城中的一个吗？"
D.Strings[3847]="这里散乱着放着一堆堆的图纸和设计图。"
D.Strings[3848]="这些图纸被守卫着。和扎米克谈谈来引开守卫的注意！"
D.Strings[3849]="最近一个名叫纳拉雷克斯的暗夜精灵德鲁伊在贫瘠之地中的地下发现了一个错综复杂的洞穴网。这个被称作“哀嚎洞穴”的地方有很多的蒸汽缝隙，所以当蒸气喷射的时候发出的声音就犹如哀嚎一般，其因此而得名。纳拉雷克斯可以利用洞穴中的温泉来恢复贫瘠之地的生态，让这里重新获得生机——但是这样做需要吸收传说中的翡翠梦境的能量。一旦和翡翠梦境相连接，德鲁伊的视线中就变成了一场噩梦。不久之后，哀嚎洞穴开始变化——洞中的水开始腐化——曾经温顺的生物开始变成狂暴，致命的捕食者。据说纳拉雷克斯自己还居住在这个迷宫的最深处，他被翡翠梦境的边缘所困扰着。即使他以前的随从也被他们的主人所经历的噩梦所腐化——他们都变成了邪恶的毒牙德鲁伊。"
D.Strings[3850]="不可能！出现吧，我的仆人！再次为你们的主人效力！"
D.Strings[3851]="在第三次大战中，肯瑞托的法师和亡灵天灾进行了殊死的战斗。大法师阿鲁高召唤了异世界中的狼人来增强达拉然守备部队的力量。这些狂暴的狼型生物踏平了来犯的亡灵天灾，然后迅速将目标转向达拉然的法师，并开始围攻席瓦莱恩男爵的城堡。这座位于焚木村的城堡不久之后就变成了黑暗势力的聚集地，并从此荒废。因为对于自己罪过的愧疚，阿鲁高将那些狼人当作自己的孩子并隐居在“影牙城堡”中。"
D.Strings[3852]="太晚了，朋友们！奈法利安的堕落力量已经生效……我无法……控制自己。"
D.Strings[3853]="求求你们，快跑吧！在我丧失所有理智之前快逃命吧！黑色的火焰在我的心中燃烧！我必须——释放它！"
D.Strings[3854]="火焰！死亡！毁灭！你们这些凡人，让奈法里奥斯大人的力量……不——我要抗争！阿莱克丝塔萨，帮帮我，我必须抗争到底！"
D.Strings[3855]="啊，你！如果你想要赢得暗矛部族的尊重，那你可以向我们捐赠那些急需的资源！你要知道，布料和绷带不会从树上长出来。$B$B我们需要你在冒险中得到的那些布料，把它们捐给我们吧！这样你就可以得到暗矛部族的青睐！"
D.Strings[3856]="在这个艰难的时期，捐赠布料对于那些不幸的人是非常重要的帮助手段。布料还可以制作装备和绷带——这对于战争十分重要！$B$B如果你想要为奥格瑞玛的兽人捐赠布料的话，我会欣然接受它们，你一定会受到我们的青睐。$B$B为了部落！"
D.Strings[3857]="嘿，$g兄弟:姐妹;……我希望可以打扰你一下，如果可以的话。$B$B我们在通过试炼和进行家园重建中经历了很多。我们现在极度缺乏布料。如果你有一些多余的话，我希望你可以捐献给我们。你一定会为此赢得所有牛头人的尊重的！"
D.Strings[3858]="这里曾经是人类最主要的产金地，希望矿井在部落第一次大战期间席卷暴风城的时候被废弃。现在迪菲亚兄弟会的人占据了那里并将这个黑暗的通道转变成他们的避难所。据说那些盗贼已经劝说了聪明的地精帮助他们在矿井的深处建造一些可怕的东西——但是没有人知道这是真的还是假的。有传言说，死亡矿井的入口在安宁的月溪镇中。"
D.Strings[3859]="你……现在是你帮助被遗忘者最好的时机。好好听着，我不喜欢重复我说过的话。$B$B我们现在极度缺乏布料。绷带和任何布料储存量都很低，我们希望接受捐赠来补充库存。你的捐赠不会有任何经济补偿——这就是捐赠的含义——你的捐赠一定会为我们所赏识。"
D.Strings[3860]="朋友——暴风城需要你的协助和慷慨解囊！$B$B我们曾经储藏丰富的布料已经所剩不多了。暴风城现在需要大量的布料和绷带！你的捐赠将能够帮助暴风城度过难关，你还能赢得我们对你的尊重！"
D.Strings[3861]="啊，你！如果你想要赢得铁炉堡矮人的尊重，那么你可以为我们捐赠有价值的资源！铁炉堡现在的布料和绷带的存储量很低！$B$B你可以捐赠各种你在冒险中得到的布料！这样一来，你就可以赢得铁炉堡矮人对你的尊重！"
D.Strings[3862]="怒焰裂谷位于奥格瑞玛中心的暗影裂口。"
D.Strings[3863]="诺莫瑞根的流亡者需要大量的布料资源！也许你可以帮帮我们，是不是？$B$B把你多余的布料资源带给我们。通过捐献它们，你可以获得所有侏儒的尊重。这是金钱无法换得的！好吧，布料可以帮助我们，但是它们意义绝不限于这些……"
D.Strings[3864]="哀嚎洞穴的入口位于贫瘠之地十字路口西南边的甜水绿洲。"
D.Strings[3865]="嘿，朋友——请等一下，如果可以的话……$B$B我们在重建泰达希尔的过程中经历了很多的痛苦。现在，我们不仅要忍受这些痛苦，而且我们还发现我们的布料存储已经很少了。如果你有多余的布料，那我希望你可以捐赠出它们。你一定因为帮助暗夜精灵赢得我们的尊重！"
D.Strings[3866]="影牙城堡位于南部银松森林，就在焚木村的北面。"
D.Strings[3867]="我从不犯错。"
D.Strings[3868]="在你匆忙追寻荣耀的过程中，你有没有想过你的行动对于这场竞赛的节奏有什么影响？你有没有想过你们的行为对我来说是多么可笑而荒谬？我对你来说是个难以理解的存在，这让你那花生大小的脑子感到十分迷茫。"
D.Strings[3869]="你已经失去理智了，奈法里奥斯。你在胡言乱语。"
D.Strings[3870]="这是真的。请允许我总结一下……"
D.Strings[3871]="在这个世界中，时间是你的敌人，但是它是我的战友。这段你自以为在你掌握之中的时光实际上是你的主宰。因此我会说……"
D.Strings[3872]="黑暗深渊位于灰谷海岸佐拉姆海岸的最北部。"
D.Strings[3873]="位于灰谷佐拉姆海岸的黑暗深渊曾经是为供奉暗夜精灵月神艾露尼尔建造的。然而，在大分裂中，神庙受到极大的冲击然后沉入了海中。它一直保持着原样——直到，其蕴含的古老的力量吸引来了纳迦和萨特。传说，古代怪兽阿库麦尔就居住在神庙遗迹中。作为古代之神最喜欢的宠物之一，阿库麦尔就一直生活在这个地区进行捕食。在阿库麦尔的吸引下，一群被称作幕光之锤的教徒也聚集在这里从事邪恶的勾当。"
D.Strings[3874]="诺莫瑞根在丹莫洛的西边。"
D.Strings[3875]="位于丹莫洛的科技奇迹城市诺莫瑞根世代以来都是侏儒的主城。最近，一群邪恶的变异食鄂怪侵入了包括侏儒主城在内的多处丹莫洛地区。为了做出殊死一搏来干掉入侵的食腭怪，大工匠梅卡托克命令打开城市中的紧急辐射水箱。侏儒在等待那些食腭怪死亡或者逃跑的同时也在寻找躲避辐射的方法。不幸的是，虽然食腭怪在经过辐射之后感染了毒性——但是它们的攻击没有停止，也没有丝毫的减弱。那些没有被辐射杀死的注入被迫逃离，他们在附近的矮人城市铁炉堡找到了安身之处。大工匠梅卡托克组建了一个智囊团来商议重新夺回他们挚爱的城市的计划。"
D.Strings[3876]="剃刀沼泽位于贫瘠之地最南端的大路西边。"
D.Strings[3877]="在上古之战中，强大的半神阿迦玛甘和燃烧军团进行了激战。这头巨大的野猪在战斗中倒下，在它血液流淌过的地方逐渐长出了巨大的荆棘藤蔓。野猪人占领了这些地方，并将其奉为圣地。这些荆棘地的中心被称为剃刀岭。剃刀沼泽被一个老丑婆卡尔加·刺肋所占据。她是一个强大且经验丰富的地卜师。在她的掌权之后，野猪人部族中迅速滋长的暴虐情绪只会带来一个后果：战争。"
D.Strings[3878]="血色修道院位于提瑞斯法林地东北部的山坡上。"
D.Strings[3879]="血色修道院曾经是洛丹伦王国牧师的荣耀之地——那里是学习圣光知识和膜拜的中心。随着在第三次大战中亡灵天灾的崛起，宁静的修道院成为了疯狂的血色十字军的要塞。十字军对于所有非人类都有着偏激的态度，无论他们是自己的盟友还是对手。他们相信所有任何外来者都带着亡灵的诅咒——他们必须被摧毁。"
D.Strings[3880]="剃刀高地位于贫瘠之地最南端的大路东边。"
D.Strings[3881]="剃刀高地和剃刀沼泽一样由巨大的藤蔓组成，剃刀高地是野猪人的传统都城。在那错综复杂的荆棘迷宫中居住着大群忠诚的野猪人军队，以及他们的高等祭司——亡首部族。然而最近，一股黑暗的力量笼罩了这座原始的洞穴。亡灵天灾的爪牙在巫妖寒冰之王亚门纳尔的带领下控制了野猪部族，并将布满荆棘的迷宫变成了亡灵力量的堡垒。现在野猪人正在奋力战斗来夺回他们的城市，并阻止亚门纳尔继续控制贫瘠之地。"
D.Strings[3882]="奥达曼位于荒芜之地最北端。"
D.Strings[3883]="拉尔德在这里维持和平。拉尔德还在这里钓鱼。想要一些鱼吗？"
D.Strings[3884]="奥达曼是古代泰坦创世之时所留下的深埋于地下的城市。矮人探险队最近发觉到了这块被遗忘的城市，将泰坦一款失败的创造物：食腭怪唤醒了。传说泰坦是从石头中创造了食腭怪。但事实证明这次试验很失败的时候，泰坦把食腭怪锁了起来并进行了第二次的尝试——最终创造了矮人这个种族。矮人创造的秘密被记录在精密的诺甘农圆盘中——那是位于古代城市最底部的大型泰坦遗迹。"
D.Strings[3885]="祖尔法拉克遗迹位于塔纳利斯沙漠最西北角。"
D.Strings[3886]="日光暴晒下的这座城市是沙怒巨魔的家园，他们一向以来都以其无情和黑暗魔法而闻名。巨魔传说中有一把强大的名叫鞭笞者苏萨斯的武器能够让最弱小的人可以击败最强大的敌人。很久以前，这把武器被分成了两半。然而，有传言说这两半可以在祖尔法拉克任何地方找到。"
D.Strings[3887]="玛拉顿位于凄凉之地西部中间的长矛谷中。"
D.Strings[3888]="玛拉顿是凄凉之地最神圣的地方。这座建造在岩窟中的神庙是扎尔塔的陵墓。半神塞纳留斯有两位不朽的儿子，扎尔塔正是其中之一。传说中扎尔塔和大地元素公主瑟莱德丝的私生子成为了半人马的祖先。据说半人马这个野蛮的种族在诞生之后就背叛了他们的父亲并将其杀死。有些人相信瑟莱德丝在悲伤中将扎尔塔的灵魂困了起来，并将其藏在了蜿蜒的洞窟中——以利用它的能量来达到一些不可告人的目的。"
D.Strings[3889]="沉没的神庙位于悲伤沼泽东部的一个大湖的中心。"
D.Strings[3890]="黑石山脉位于灼热峡谷和燃烧平原的中间。"
D.Strings[3891]="黑石深渊曾经是黑铁矮人的伟大都城，这个火山中的迷宫现在成为炎魔拉格纳罗斯的王座所在地。拉格纳罗斯找到了特殊的方法，可以使用石头来创造一支无敌的石头人军队，帮助它征服黑石深渊。为了打败奈法利安和他的龙子龙孙，拉格纳罗斯会不惜一切代价达到最后的胜利。"
D.Strings[3892]="黑石深渊深处的巨大堡垒是由矮人建筑大师弗兰克罗恩·铸铁所设计的。这个堡垒是矮人力量的象征并被邪恶的黑铁矮人占据了数个世纪。然而，奈法利安——死亡之翼狡猾的儿子——对这个巨大的堡垒别有意图。他和他的黑龙军团占据了上层黑石塔并向占据着黑石深渊的黑铁矮人宣战。奈法利安知道矮人是由强大的火元素拉格纳罗斯所领导的，所以他立志要摧毁他的敌人并将黑石深渊全被占为己有。"
D.Strings[3893]="厄运之棰位于菲拉斯的中部。"
D.Strings[3894]="通灵学院这个学习亡灵术的学校位于西瘟疫之地的凯尔达隆那个废弃的小岛上。"
D.Strings[3895]="斯坦索姆位于东部瘟疫之地瘟疫林的北部。"
D.Strings[3896]="斯坦索姆曾经是洛丹伦北部一颗璀璨的明珠，但是就是在这座城市中，阿尔萨斯王子背叛了他的导师乌瑟尔，并屠杀了数百个被认为受到感染的臣民。阿尔萨斯不久之后就向巫妖王臣服。这座破碎的城市也被巫妖克尔苏拉德领导的亡灵天灾所占据。一直由大十字军战士达索汉领导的血色十字军分遣队也占据了这个城市的一部分。这两方力量在城市中进行着激烈的战斗。"
D.Strings[3897]="暴风城监狱位于暴风城靠近法师区附近。"
D.Strings[3898]="监狱是位于暴风城运河区戒备森原的牢房。那里由典狱官塞尔沃特看守着，监狱是那些小偷，政治犯，谋杀者和许多最危险的罪犯的家园。最近，异常暴动导致了监狱的混乱——所有的守卫都被赶了出来，里面的罪犯可以自由的活动。"
D.Strings[3899]="入侵者闯进了孵化间！我们要不惜一切代价保护龙蛋！"
D.Strings[3900]="不要使用破碎的武器和护甲参加战斗！我这里可以在你等待的时候进行专家级的武器和护甲修理！"
D.Strings[3901]="你要为强迫我这么做而付出代价！"
D.Strings[3902]="蠢货！这些蛋比你认为的要珍贵的多！"
D.Strings[3903]="不！住手！我要会让你来弥补自己的罪行！"
D.Strings[3904]="原谅我，$n！你的死亡让我的失败更加沉重！"
D.Strings[3905]="奈法里奥斯的仇恨让我变得空前强大！赶快逃跑吧，凡人！黑石之王的怒气涌动在我的血脉中！"
D.Strings[3906]="你怎么进来的？你们这种生物不能进来！我要毁灭你们！"
D.Strings[3907]="你们很聪明，凡人——但是我不会那么轻易地离开我的圣地！"
D.Strings[3908]="这不可能！我是这里的主人！你们这些凡人对于我来说一无是处！听到了没有？一无是处！"
D.Strings[3909]="没用的$n！你的朋友不久之后就会去找你的！"
D.Strings[3910]="干得好，我的手下。凡人的勇气开始消退了！现在，让我们看看他们如何应对黑石塔的真正主人的力量！！！"
D.Strings[3911]="燃烧吧！你们这些悲惨的家伙！燃烧吧！"
D.Strings[3912]="我这里有你所需要的所有烹饪材料，伙计！"
D.Strings[3913]="欢迎来到恶齿村，陌生的$c。我是断齿族长，这里的领袖。"
D.Strings[3914]="如果它坏了，那么斯拉提可以修理它！"
D.Strings[3915]="别踩到我的货物，小心。"
D.Strings[3916]="钓鱼只是为了娱乐，伙计。你知道吗？我是在向我的导师学习，世界上最伟大的钓鱼者——纳特·帕格。你听说过他没有，伙计？$B$B如果你想要寻求启迪，那么纳特·帕格会指引你前进的道路。"
D.Strings[3917]="你可以教我什么？"
D.Strings[3918]="祖尔金总有一天会回来的，$r。记住我的话。在那一天到来之前，我们会尽我们的所能保证森林巨魔族群的昌盛。$B$B作为恶齿村的猎人头领，我的责任就是保证我们的安全。$B$B我必须对这一带的野兽进行监控。$B$B你是不是来找活干的？"
D.Strings[3919]="我是基尔拉姆，斧系大师。"
D.Strings[3920]="啊，一个经历丰富的冒险者。基尔拉姆又让你来这里了。我知道你具有相当的能力，你只需要询问我，我就会教你斧系铁匠的知识。"
D.Strings[3921]="不要靠得太近，$n。我手中的铁锤可能会敲到你。"
D.Strings[3922]="我会教你锤系专精之道。你只需要恭恭敬敬地问我就可以了。"
D.Strings[3923]="退后，否则我会把你一下子砍成两半的。"
D.Strings[3924]="如果你希望成为一名铸剑师，那就问问我吧。"
D.Strings[3925]="我刚刚完成了一个新的空间爆破器，它可以让我变成最最富有的技师，我做梦都不曾想过的富有！我所需要的就是找到一个熟练的地精技师，让$g他:她;来制作一个空间撕裂器，然后将两者连接起来！"
D.Strings[3926]="通过在诺莫瑞根中进行的探险行动，我找到了制作一种伟大发明的方法：物质传送器！我所需要的就是一个熟练的侏儒技师，让$g他:她;制造一个信标连接在这个传送器上。"
D.Strings[3927]="一旦你建造了这个装置，你就将被传送到可爱的加基森！几乎使用这个装置的人都发现在其立即到达了这里！$B$B有报告说，有别人试图用一种坏的版本来替换我们的产品，但是我相信我们不久之后就可以解决这个问题……"
D.Strings[3928]="如果你有办法改进这个装置，那就告诉我！"
D.Strings[3929]="我要作最后一次努力。希望它能有效……"
D.Strings[3930]="瓦拉斯塔兹，不！！！"
D.Strings[3931]="拿到钥匙，打开这些锁链！钥匙在守护者希坦亚手里……就在洞的后面……"
D.Strings[3932]="工作/遗失和找到物品/悬赏："
D.Strings[3933]="你好，我的朋友！我是哈古斯，战歌前锋部队的军需官。随着你在战歌氏族中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。"
D.Strings[3934]="愿夜之祝福永远与你同在，我的朋友！我是艾蒂尔·月火，我是灰谷银翼哨兵部队的军需官。随着你在银翼哨兵中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。"
D.Strings[3935]="斯尼维尔在此！冷齿矿洞是斯尼维尔的！"
D.Strings[3936]="让复仇的毒蛇吞噬你们吧！"
D.Strings[3937]="希里克，赐予我复仇的翅膀！"
D.Strings[3938]="欢迎！欢迎来到亚布·尼比盖尔的暗月珍奇馆——这儿有来自世界各地的奇珍异宝！朋友，尽情参观吧！$B$B但是不要动手触摸！神圣的神器和可怕的野兽守护着这些展品！随意触碰的话，它们可能会烧伤你的手……"
D.Strings[3939]="今天要我送你去哪里，$c？"
D.Strings[3940]="虽然十字路口似乎是贫瘠之地的中心地带，但是我更喜欢陶拉祖营地的安静。你想去哪儿？"
D.Strings[3941]="这些道路都是大地之母走过的道路。无论你决定前往何方，愿大地之母与你同在。"
D.Strings[3942]="当双足飞龙将你送达目的地之后，请好好款待它。愿你的祖先与你同在，$n。"
D.Strings[3943]="你好，我的朋友，欢迎来到艾择拉斯最伟大的展览会！$B$B请尽情浏览我们展出的东西吧。来看看这些暗月马戏团在广袤而又神秘的艾泽拉斯世界中找到的各种千奇百怪的东西！我们不收取任何费用，我们为你带来无限惊喜，为孩子们带来让他们兴奋的东西！"
D.Strings[3944]="朋友，欢迎回到艾泽拉斯最盛大的展览！很高兴再次看到你。$B$B请接受我们的盛情邀请吧。请四下看看，我们暗月马戏团中有许多新奇的事物！看看我们带来的各种货物吧！我们会继续免费为大家带来更多惊喜的，孩子们都乐意参加！"
D.Strings[3945]="希拉斯，为什么马戏团里的大部分设施都是免费的？那你是怎么赚钱的？"
D.Strings[3946]="这不是钱的问题，伙计！虽然我们接受慷慨的捐赠——有一些捐赠量还很大——我们旅行车队的信念是为这个战火纷飞的世界带来爱与曙光！不要担心我们，让我们来为怎样取悦你们而操心吧。"
D.Strings[3947]="兑换奖券啦！换取礼物啦！快来啊！"
D.Strings[3948]="闪开，乡巴佬。"
D.Strings[3949]="这不是一匹坐骑，伙计。"
D.Strings[3950]="如果你想表示友好的话，就请屏住呼吸。最好停止呼吸。"
D.Strings[3951]="事先说明，我来这里不是来搞客户关系的。"
D.Strings[3952]="你打扰希拉斯，又打扰我。祝你开心。"
D.Strings[3953]="我需要第二个头，就像我需要把第一个砍掉一样。"
D.Strings[3954]="我在厄运之槌里住过一段时间，真令人难忘。真的。"
D.Strings[3955]="和大多数的食人魔不一样的是，我知道厕所是干什么用的。"
D.Strings[3956]="我早知道你会找到我的，$n。$B$B世间众生都被他们所做出的选择驱动着。一个选择导致另一个选择，最终这些选择决定了你的一切。而这一切——如你的身份，及你所做的选择，也勾勒出了你的命运。$B$B你准备好直面自己的命运了吗？"
D.Strings[3957]="快告诉我吧！"
D.Strings[3958]="好吧……$B$B假设你从你的主人那里接受了保护玉米田并清除小偷的任务。一天晚上，在你巡逻的时候发现了一个穿着破烂布衣的人正在田里偷窃玉米。你马上上前，而他立即跪在你的面前求你不要杀他。他说他偷玉米是为了养活他一家，因为这块土地的主人——也就是你的主人向他们征收重税。你的主人一向以此而闻名。$B$B你该怎么办？"
D.Strings[3959]="我按照命令把他杀掉，反正他不过是个小偷和骗子而已。"
D.Strings[3960]="我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。"
D.Strings[3961]="我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。"
D.Strings[3962]="我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。"
D.Strings[3963]="你的下一个选择在等着你。$B$B你是一个效忠于主人的刽子手。有一个背叛了你的主人和人民的人被送到你这里来受刑。可你以前认识他，他曾是你非常要好的朋友，并且非常善良，但是有一天他突然消失了。你还知道他所犯下的罪行导致很多无辜的平民的死亡。当你看到他的时候，他求你饶命，并且说他是被一个高官所陷害的。$B$B你该怎么办？"
D.Strings[3964]="去死吧，渣滓！联盟会获得胜利的！"
D.Strings[3965]="去死吧！你们别想在奥特兰克山谷站住脚！"
D.Strings[3966]="把这些渣滓赶出奥特兰克！"
D.Strings[3967]="准备发动攻击！为部落而战！"
D.Strings[3968]="狂欢开始啦！"
D.Strings[3969]="没错！暗月马戏团很快就要来了！只要我把这些东西从车上卸下来，搭好帐篷弄好场地，就马上开工！别忘了届时过来看看哦！"
D.Strings[3970]="暗月马戏团不久就会开张啦。别忘了待会回来，看看我们是否已准备停当。"
D.Strings[3971]="年轻人，欢迎来到暗月马戏团！我们从世界各地收集到不少神奇的东西，你可以随便看。啊，如果你能设法收集一套次级暗月卡片，就赶紧告诉我，因为主人……我是说我对这东西很感兴趣。"
D.Strings[3972]="告诉我更多关于暗月卡片的信息。"
D.Strings[3973]="我们在世界各地散发暗月卡片，看看有没有谁能集齐八套暗月卡片中的任何一套。若你设法集齐一套八张的卡片，我们就会奖励你一张强力暗月卡片，它不仅是强大的饰品，也可以作为暗月马戏团的纪念。"
D.Strings[3974]="告诉我更多关于野兽套牌的信息。"
D.Strings[3975]="如果你集齐一套野兽卡片，我们会奖励你一张高级暗月卡片：蓝龙。这张卡片对恢复魔法能量非常有用。"
D.Strings[3976]="告诉我更多关于入口套牌的信息。"
D.Strings[3977]="如果你集齐一套入口卡片的话，你将获得一张暗月卡片：虚空。这张卡片将有可能在你死亡之后让你复活。"
D.Strings[3978]="告诉我更多关于元素套牌的信息。"
D.Strings[3979]="如果你集齐一套元素卡片，我们会奖励你一张高级暗月卡片：漩涡。这张卡片可能会对你的敌人造成严重的伤害。"
D.Strings[3980]="告诉我更多关于督军套牌的信息。"
D.Strings[3981]="如果你集齐一套督军卡片的话，你将获得一张暗月卡片：英雄。这张卡片将有可能在你进行近身作战的时候对你进行治疗。"
D.Strings[3982]="我按照王上的命令处决他，这样才能偿还他对我的同胞犯下的罪孽。"
D.Strings[3983]="我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。"
D.Strings[3984]="我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。"
D.Strings[3985]="你的下一个选择在等着你。$B$B你奉王上之命，出使交战中的敌国。战争让双方都元气大伤，你的使命是确保两国进行和平谈判。$B$B在外交宴会上，你无意中听到敌国的统治者恶意中伤你的君王。你断定他原本是想背着你说的，但他还是辱及了你的王上的威名。$B$B做个选择吧。"
D.Strings[3986]="我挑战他的邪恶与蛮横，不惜一切代价捍卫王上的荣耀。"
D.Strings[3987]="我平静但略有表示地对这种冒犯一言不发，让他对自己犯下的错心怀恐惧。回去之后，我会把这一切禀报王上。"
D.Strings[3988]="我默不作声，忽略了这种侮辱。我不会告诉我的王上，因为我将不惜一切代价保护和平。这只是一次侮辱——而不是一次完全的宣战。"
D.Strings[3989]="你的下一个选择在等着你。$B$B你的兄弟想要加入你所在的享有盛名的军队。虽然你对他的热情和忠诚毫不怀疑，但是你担心他的能力还不足以执行军队艰巨的任务。当你无法肯定定他能否应对挑战——这可能会让你和其他人陷入危机——而你的意见将决定他的去留。$B$B做个选择吧。"
D.Strings[3990]="我会反对我的兄弟加入军队，即使我们的关系会因此产生永久的裂痕。对他自己和周围的人来说，他无疑是个危险，要想指望他会逐渐进步可就太冒险了。"
D.Strings[3991]="我会支持我的兄弟加入军队，虽然这或许会威胁到军队的安全。我和军队的其他成员会帮助他，我相信他能够适应这儿的生活并且学会生存之道。"
D.Strings[3992]="我会想办法让他不参加危险的任务，完全不需要他做任何事情，以此来保存我的家族的血脉。"
D.Strings[3993]="你的下一个选择在等着你。$B$B你凭借自己的力量杀死了一头破坏农田的可怕野兽，并且割下它的耳朵作为战利品。后来你听说你的王上在悬赏这头野兽的性命，有一位贫穷的骑士为了养家糊口，说是自己杀死了这头野兽。你自己并不需要钱，但是你知道这家伙谎报实情，牟取私利。$B$B做个选择吧。"
D.Strings[3994]="我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的——毕竟，我确实杀了它。然后我会用一部分奖励接济贫困的骑士，用以养家糊口。"
D.Strings[3995]="我将对这件事情只字不提，并允许那个骑士拿到奖励来帮助他的家庭。"
D.Strings[3996]="对你的占卜已经完成，$c。在接下来的几个小时中，你将发现你的精神与你真正的天性保持一致。你要小心，因为你的命运并不是你所想得那么条理清晰。$B$B如果你想要对你的未来有所了解，那么尽管告诉我。我会很乐意给你一张手写的占卜结果，当然，你的背包中必须留有足够的空间。这个结果是你回答我的问题时所表现出来的。"
D.Strings[3997]="我想要你说的这些塔罗牌！我有足够的空间来存放。"
D.Strings[3998]="$n，这是你的塔罗牌。愿你能好好利用它。"
D.Strings[3999]="暗月马戏团来了！不要错过啊！"
D.Strings[4000]="暗月马戏团来了！所有的孩子都可以在这里找到好玩的东西！来吧，都来吧！"
D.Strings[4001]="快来吧，听说艾泽拉斯最盛大的集会——暗月马戏团开张啦！哈哈！"
D.Strings[4002]="一定要来看看暗月马戏团带来的千奇百怪的东西！"
D.Strings[4003]="看这边！暗月马戏团开市啦！记得来看看艾泽拉斯最激动人心的集会！"
D.Strings[4004]="暗月马戏团已经来了！不要错过有史以来最华丽的表演！"
D.Strings[4005]="暗月马戏团只会停留一小段时间，别错过今天的大好机会！"
D.Strings[4006]="男孩们女孩们——所有的孩子们——暗月马戏团已经到啦！哈哈！"
D.Strings[4007]="暗月马戏团会在哪儿开张呢？"
D.Strings[4008]="你是说暗月马戏团已经来了？它在哪里？"
D.Strings[4009]="暗月马戏团到艾尔文森林来了，就在闪金镇的南边。走过路过不要错过！"
D.Strings[4010]="当暗月马戏团开始展览的时候，他们会出现在艾尔文森林。我们的帐篷将驻扎在闪金镇的南边！"
D.Strings[4011]="暗月马戏团到莫高雷的金色平原来了，就在雷霆崖的西南边。走过路过不要错过！"
D.Strings[4012]="暗月马戏团将会在莫高雷开张，我们就在雷霆崖的西南方安营扎寨！"
D.Strings[4013]="你好，朋友。"
D.Strings[4014]="这附近有很多乱扔垃圾的家伙。"
D.Strings[4015]="玩得开心吗？"
D.Strings[4016]="别忘记买点饮料和纪念品！"
D.Strings[4017]="暗月马戏团是全艾泽拉斯最华丽的！"
D.Strings[4018]="欢迎来到暗月马戏团，$c！$B$B我叫克莉·希克斯，我应该跟你握手致意的，但是恐怕我会把你的手捏碎，因为我是当今世上最强的女人！"
D.Strings[4019]="快来吧！来买热辣烤翅啊！"
D.Strings[4020]="现烤现卖的暗月热狗，新鲜热烫！大家赶快趁热来买啊！"
D.Strings[4021]="你有金钱，我们有食物。那么你还在等什么？！"
D.Strings[4022]="限时供应！暗月马戏团独家美味，脆青蛙肉！机会难得！"
D.Strings[4023]="我出售的每项物品都是我自己的劳动所得。我向你保证。"
D.Strings[4024]="暗月卡片？去找教授问问吧。"
D.Strings[4025]="趁现在还有机会，过来看看我的货物吧。我们要在这儿呆上一周，然后就要动身去远方啦。"
D.Strings[4026]="我历尽艰辛才将这些无价之宝带来此地销售，你知道吗？来看看吧。"
D.Strings[4027]="嗨，谁来帮我抓住这个东西！"
D.Strings[4028]="它跑开了！"
D.Strings[4029]="回来！"
D.Strings[4030]="出售青蛙和皮球啦！"
D.Strings[4031]="每个人都还玩得开心吧？棒极了！欢迎来到暗月马戏团，艾泽拉斯最盛大的展览！当你在尼比盖尔的珍奇馆购物时记得跟亚布和他的朋友谈谈。"
D.Strings[4032]="来啊，大家都来啊。欢迎来到暗月马戏团！不要害羞。到兰拉这里购买来自遥远大陆的奇特东西。如果你是个拥有暗月卡片的幸运儿，那么就去找萨杜斯·帕雷教授吧。渴了？饿了？你很幸运！你可以从塞兰妮亚和斯塔姆那里获得让你倍感清新的食物和水。我建议你去尝尝暗月特殊储备那里的热辣烤翅，绝对不容错过！如果你想要了解自己的未来，那么快点去找塞格谈谈。"
D.Strings[4033]="欢迎所有人来到暗月马戏团，世界上最盛大的事件！我们拥有……可口的美食、烈性饮料、异地的神器、寻宝书、丰厚的奖品和无尽的刺激！别忘记将你的暗月马戏团奖券交给吉瓦斯·格里加特！只需要5张奖券你就可以领取一份艾泽拉斯最丰厚的奖品。每个人都是赢家！"
D.Strings[4034]="唉……很抱歉，我现在还不能告诉你什么，你近来刚从我这儿获得了关于命运的信息。$B$B过几个小时你再来找我吧。命运的力量或许会有所改变，我会洞察你的未来。"
D.Strings[4035]="我们回来啦，感觉棒极了！暗月马戏团的朋友们，今儿是你们的幸运日！不要吝惜你的钱财，我们出售的都是来自世界各地的稀罕之物。无论你年方几何，无论你是贫穷还是富有，都能在暗月马戏团上买到称心如意的东西！请记得将你们的暗夜集市奖券交给吉瓦斯·格里加特，挑选一份丰厚的奖品！"
D.Strings[4036]="$n，很高兴再次见到你！你玩得开心吗？$B$B想要来掰手腕吗？不，当然不……你想要保护好自己的手臂！"
D.Strings[4037]="你好。我是克洛诺斯——记忆力天下第一的克洛诺斯。我是不会忘记任何微小的细节的。$B$B相信我。"
D.Strings[4038]="你好，$n。你认为我会忘记你？$B$B我知道你不会这么认为的。你是个聪明的$c，你所认识的我一看到任何人就可以立即认出他。"
D.Strings[4039]="$n，你回来啦！我上次吃掉的那些灵魂说你会来看我的，而且我们还会谈谈生意。$B$B他们说对了吗？"
D.Strings[4040]="嗨，$n！很高兴见到你！暗月马戏团是一场盛大的展览，不是吗？$B$B有很多值得一看的东西！看吧！或许有一天会有更多的东西呈现在你面前……"
D.Strings[4041]="我找不到我的宠物青蛙加布加布啦。她爱喝黑铁啤酒，她总是喝这种酒，但是这种酒很不容易得到的！现在我没有黑铁啤酒了……加布加布一定是自己跑出去找酒喝啦！$B$B真希望她回到我身边……"
D.Strings[4042]="我们必须不惜一切代价保护这个营地的安全，$c！我们不能允许敌人再前进一步了！"
D.Strings[4043]="现在是危险时分，$r。远古的邪魔复活了，他可不管你是部落还是联盟。"
D.Strings[4044]="出售可口的饮料啦！暗月马戏团最好的酒，生津止渴！"
D.Strings[4045]="别害羞，请这儿的每个人喝上一杯吧！"
D.Strings[4046]="朋友，招待生总是乐意收到小费的。"
D.Strings[4047]="就在……另一批暗月储备物资中。取回属于你自己的那份，它们很快会被抢光的！"
D.Strings[4048]="给我饮料！"
D.Strings[4049]="呱呱。"
D.Strings[4050]="吻我。"
D.Strings[4051]="嗯……食物。"
D.Strings[4052]="你想要出售青蛙？"
D.Strings[4053]="你好，年轻的$c。就是在这里，你的酋长挑战了奥格瑞姆·毁灭之锤！虽然这事情已经过去了很久，但是在我的记忆中，它依然犹如刚刚发生过一样。"
D.Strings[4054]="$966w，年轻的$c。"
D.Strings[4055]="你是来学习的？嗯，我或许会给你一些事儿做的。"
D.Strings[4056]="<雷矛中士向你敬礼。>$B$B姓名，军阶和编号，士兵！这是你唯一需要提供给那些肮脏的霜狼走狗的信息！"
D.Strings[4057]="$964w，年轻的$c。"
D.Strings[4058]="$962w个雷矛指挥官和$950w个雷矛上尉。"
D.Strings[4059]="我向你保证：这座峡谷必将是我们的囊中之物。"
D.Strings[4060]="$962w，士兵。"
D.Strings[4061]="$950w，士兵。"
D.Strings[4062]="$966w个霜狼指挥官和$964w个霜狼上尉，士兵。"
D.Strings[4063]="雷矛士兵，你们的将军受到攻击！我需要援助！快！快！杀死这些卑鄙的霜狼氏族的成员。"
D.Strings[4064]="雷矛的渣滓！在我的要塞？！杀光他们！"
D.Strings[4065]="救命！一群蜜蜂在追我！"
D.Strings[4066]="我讨厌跑步，但是这些蜜蜂追个不停！"
D.Strings[4067]="为什么它们不喜欢火？"
D.Strings[4068]="卡鲁斯能不能帮我把这些蜜蜂赶走？它们在蜇我！"
D.Strings[4069]="如果你是来拯救世界的，那么你来对地方了。无面者——血神哈卡——已经被带回到我们的世界来了！"
D.Strings[4070]="你决心的力量正在闪光，$n。你需要继续证明你对我们的人民来说是一笔宝贵的财产。有一天世界将会意识到你的所做所为是多么的重要。"
D.Strings[4071]="菜鸟英雄又回来啦！很高兴见到你，$n，欢迎回到我们村！"
D.Strings[4072]="真是漫长而艰辛的旅途啊。很少有谁能取得你这样的成就。你是赞达拉帝国的朋友，$n。$B$B传说中的，或许是……是的……或许。"
D.Strings[4073]="爸爸，我能出去收集更多的石头做条项链吗？"
D.Strings[4074]="当然，奥克拉。但是不要离家太远了。"
D.Strings[4075]="好的！我会小心的，爸爸！"
D.Strings[4076]="哦……这块漂亮的岩石。看看我能不能找到更多这样的石料……"
D.Strings[4077]="嗯……那块石头很不错，但是太小了一点。"
D.Strings[4078]="这是块相当不错的岩石，我得把它放到桶里去。好啦，我还需要一些……"
D.Strings[4079]="这石料很适合制作长矛，我敢打赌，我的朋友格鲁克会喜欢的！非常锋利……希望他喜欢。"
D.Strings[4080]="那儿……那儿的石头足够做一条项链啦。无论如何，我现在得回家啦。"
D.Strings[4081]="让我来对付他们，$n！只要一声令下，我就会冲出去攻击他们的大桥！"
D.Strings[4082]="我会在去霜狼要塞的路上巡逻。只要你一声令下，我就起飞，指挥官。"
D.Strings[4083]="你好，$c。你愿意帮助战歌峡谷的银翼哨兵作战吗？"
D.Strings[4084]="我想去战场。"
D.Strings[4085]="战场军官"
D.Strings[4086]="赞美月神！你在寻找我们的战歌峡谷军官？她的名字叫做伊萨拉斯，她就在战士训练师的旁边等着你。"
D.Strings[4087]="你要做的事情需要很大的勇气，$n。要进入战歌峡谷，你就得跟银翼哨兵的军官艾萨拉斯谈谈。她会为你指引方向的。愿女神的祝福与你同在！"
D.Strings[4088]="那么$g小伙子:小姑娘;，你认为你具有在奥特兰克山谷帮助联盟抵御部落的能力？非常好，那么你一定希望和铁炉堡的格罗杜姆·钢须谈谈。你可以在武器大厅的战略沙图之前找到他。"
D.Strings[4089]="啊，奥特兰克山谷，我的美好回忆啊。<叹息>嗯，我不能与你同行，但我同样感到骄傲！你得跟铁炉堡武器大厅的格罗杜姆·钢须谈谈。"
D.Strings[4090]="如果你想要去奥特兰克山谷，去和卡尔特拉·血喉谈谈。你可以在荣耀谷的勇者大厅去找她。"
D.Strings[4091]="我多想和你一起加入伟大的战斗，但是我不得不待在这里值勤。去奥格瑞玛荣誉谷的勇者大厅找卡尔特拉·血喉，她将会帮助你进入奥特兰克山谷。为部落带来荣耀，$n！"
D.Strings[4092]="我命令你把这些入侵者烧成灰烬！"
D.Strings[4093]="你们永远无法将我赶出我的工事！"
D.Strings[4094]="为什么你们不再试验一次你们那些低贱的手段，娘娘腔？！你们是不是一群懦夫？？"
D.Strings[4095]="可恶的霜狼懦夫！如果你们想要一战的话，就放马，不，放狼过来吧！"
D.Strings[4096]="雷矛的渣滓们，如果你们真的有这么大胆的话，就来我的堡垒中挑战我吧！"
D.Strings[4097]="你们想要把霜狼的将军引出他的要塞？可笑！"
D.Strings[4098]="我永远不会被你那点伎俩算计到，蠢货！如果你想要一战的话，那就到我的地盘来挑战我吧！"
D.Strings[4099]="我是击碎者金罗克，穆贾巴的特使，拉斯塔哈之拳！$B$B我通常只和战士以及异教徒打交道。"
D.Strings[4100]="我是全知者阿塔比姆，拉斯塔哈的特使。$B$B我通常只和牧师、法师和术士打交道。"
D.Strings[4101]="阿拉索联军发誓为激流堡和联盟夺回阿拉希。这将是一场恶战，但是是一场值得打的战争。"
D.Strings[4102]="要赢得这场战争，我们不能坐在这里，静待战争之潮将我们淹没。我们必须果断出击，否则阿拉希永远也不会成为我们的囊中之物。"
D.Strings[4103]="你应该去战士区找布洛冈·石盾，$c。"
D.Strings[4104]="雷矛卫队需要你的帮助，赶快去参加对抗霜狼氏族的战斗吧，$n！和战士区的布洛冈·石盾谈一谈，他会帮你抵达奥特兰克山谷。赞美艾露恩！"
D.Strings[4105]="有许多战场可供选择，你要去哪一个呢？"
D.Strings[4106]="银翼哨兵算不上是个可敬的对手，但是如果你对屠杀他们感兴趣，那么就去勇者大厅找布拉古尔吧。"
D.Strings[4107]="你要找哪个战场？"
D.Strings[4108]="你一定是在说泰姆·暴怒图腾。去猎人高地找他。"
D.Strings[4109]="我知道在雷霆崖有人可以帮助你进入奥特兰克山谷。去猎人高地找泰姆·暴怒图腾。希望你找到你希望找的人，$n。"
D.Strings[4110]="猎人大厅的克古尔·血斧将会帮助你进入战歌峡谷。"
D.Strings[4111]="真是无谓的攻击，但是如果银翼要塞的家伙不想要和我们和平相处的话，那么他们还能留给我们什么？去猎人大厅找克古尔·血斧，他将会帮助你进入战歌峡谷。"
D.Strings[4112]="你想要加入哪个战场？"
D.Strings[4113]="那里很冷！你应该去皇家区找格里兹尔谈谈。"
D.Strings[4114]="他的名字叫格里兹尔。他在皇家区和女妖之王和恐惧魔王在一起。"
D.Strings[4115]="小兽人库尔丁·血爪应该在皇家区。"
D.Strings[4116]="战歌峡谷中的精灵们会在你的打击下发出骨头碎裂的声音。去跟皇家区的库尔丁·血爪谈一谈吧。"
D.Strings[4117]="你想去哪个战场？"
D.Strings[4118]="战歌峡谷？好吧，你应该去跟武器大厅的莱兰迪斯谈一谈。"
D.Strings[4119]="任何与部落——特别是兽人——交战的机会都是不容错过的。你可以在战歌峡谷中得到充分的历练，到武器大厅去找莱兰迪斯谈一谈吧，她会送你去战歌峡谷的。"
D.Strings[4120]="嗯，你在找哪个战场？"
D.Strings[4121]="真希望与你同行，$n。去暴风要塞吧，跟国王觐见室的塞尔曼·岩拳谈谈，他会帮助你前往奥特兰克山谷的。"
D.Strings[4122]="银翼要塞需要你的援助。跟暴风要塞觐见室的艾弗拉兰谈谈。"
D.Strings[4123]="银翼哨兵运用一切援助对抗战歌前锋。$n，如果你想要帮助他们的话，就去暴风要塞找艾弗拉兰谈谈。"
D.Strings[4124]="你对哪个战场感兴趣？"
D.Strings[4125]="%s完全被烈焰吞噬了，他的双眼射出了疯狂的光芒！"
D.Strings[4126]="你想要什么？$B$B梅维克只跟德鲁伊和萨满祭司往来。"
D.Strings[4127]="你好，$c。眼下正是收获节——感恩与追思的季节。我们举办盛宴感激所有我们应该感激的人，追忆我们的祖先和英雄，感谢他们给我们留下的宝贵遗产。$B$B请尽情享受这盛宴吧。我还会燃放焰火助兴。"
D.Strings[4128]="让我看看你的焰火。"
D.Strings[4129]="我们绝不能让联盟在阿拉希扩张势力！既便是小小的避难谷地，在将来也可能对我们形成威胁。"
D.Strings[4130]="阿拉希盆地的战斗是一场谋略战。木材、矿石、食物……所有这些物资对战斗来说都是必需品。$B$B销毁敌方的物资跟在战场上杀死他们一样重要。"
D.Strings[4131]="我眼睛瞎了，但是我还拥有洞察力。$B$B我主要跟猎人和潜行者打交道，$r。"
D.Strings[4132]="你很快就会没命了！"
D.Strings[4133]="我要把你的魔精抽干！"
D.Strings[4134]="你的头骨将用于装饰我们的祭坛！"
D.Strings[4135]="巨魔的魔精是最好的！"
D.Strings[4136]="尝尝巫毒的力量！"
D.Strings[4137]="冒险者，你好。我是赞达拉的商人林沃斯。我来自南海，从我的家乡带来了许多新奇的货物。$B$B如果你能证明自己的价值，我会乐意与你交换物品的。如果你有我们部族的荣誉勋章，我这里还有些更好的东西……"
D.Strings[4138]="沙德拉，让我成为你的化身！"
D.Strings[4139]="骄傲会将你送上绝路。来吧，凡人！品尝夺灵者的愤怒吧！"
D.Strings[4140]="来为我作战吧，我的孩子们！"
D.Strings[4141]="朋友，欢迎参加这场盛宴。来吧，狂欢至死吧！"
D.Strings[4142]="我终于摆脱了夺灵者的束缚！"
D.Strings[4143]="哈卡再也不能束缚我了！我终于可以安息了！"
D.Strings[4144]="必然的结局……死亡！诅咒你，哈卡！诅咒你！"
D.Strings[4145]="%s死了。"
D.Strings[4146]="西瓦尔拉，让我感受你的愤怒吧！"
D.Strings[4147]="我祝福你，凡人。你给了我自由……哈卡再也无法控制我了！"
D.Strings[4148]="宁静……终于来临了！"
D.Strings[4149]="贝瑟克，你的祭司在召唤你的力量！"
D.Strings[4150]="我是赞达拉的赞扎。我以灵体形态从赞达拉赶来帮助我的人民。哈卡不能控制我的灵魂。$B$B我是来帮助那些曾经有恩于赞达拉的朋友的。"
D.Strings[4151]="赞达拉的朋友！你已经去过了血神巢穴的深处，$c。你最好仔细听我说。$B$B数千年前，当祖拉曼帝国的巨魔与入侵的高等精灵异教徒作战时，高等精灵盗取了赞扎的强大魔法，在自己的武器和护甲上附魔，以此征服当地的巨魔。"
D.Strings[4152]="我想我听说过这种魔法。"
D.Strings[4153]="是吗？这么说你已经知道高等精灵所掌握的巨魔魔法有多么浅显了？$B$B高等精灵怎么都想不明白，作为一个与魔法密切相关的种族，他们为何无法驾驭巨魔巫毒的力量。对这些白皮肤的生灵而言，这简直难以置信。他们只好使用一种不纯的巨魔法术来增强他们的魔法力量。我想他们称其为“秘药”。"
D.Strings[4154]="秘药？听起来很耳熟呢。"
D.Strings[4155]="赞扎能制造古老的附魔物品。这种魔法可以帮助你打败哈卡和他的爪牙。$B$B我只要你帮我找3种东西。我承认有一样东西不是必需的，但是我想净化那些高等精灵的魔法。"
D.Strings[4156]="我需要些什么？"
D.Strings[4157]="首先，必须要有一个从最强大的哈卡莱信徒那里夺来的原始哈卡莱神像，去打败金度和血领主曼多基尔吧！$B$B然后，还要有一个打孔的巫毒人偶。你可以在这一带的垃圾堆中找到它们，多留意一下那些厄运巫毒堆。把这些东西都给我拿来，我就给你一种强大的附魔！"
D.Strings[4158]="很抱歉，$c，在你变得更加强大之前，我不能让你去战歌峡谷送死。"
D.Strings[4159]="吞噬$n的躯体吧！"
D.Strings[4160]="欢迎参加藏宝海湾钓鱼比赛，每周我们都会向全艾泽拉斯最好的渔夫发放奖励。\n\n钓鱼比赛开始后，你在荆棘谷的任何渔点都可以钓到可口鱼。"
D.Strings[4161]="你好，$c。我是拉斯塔哈的仆从伊克萨尔。"
D.Strings[4162]="很抱歉，$c，在你变得更加强大之前，我不能让你去奥特兰克山谷送死。"
D.Strings[4163]="权力珍宝是古代古拉巴什帝国的遗物。赞达拉部族正在寻找它们——它们不仅有着极大的收藏价值，而且我们相信它们还蕴藏着远古帝国的魔法。$B$B你可以在祖尔格拉布找到三种权力珍宝：硬币、珠宝和原始神灵的物品。收集到一定数量之后，把这些东西交给我们，我们就会送你一些赞达拉最好的工艺制品。"
D.Strings[4164]="石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量，但是你无法理解它们的意思。"
D.Strings[4165]="石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量，用来制造Gurubashi Mojo Madness……"
D.Strings[4166]="在我看来，钓鱼的美妙之处在于其缓慢的节奏。人们可以在钓鱼的过程中思考、回想过去和计划未来。$B$B哦，当然这也是大醉的托辞。"
D.Strings[4167]="再次感谢你找回了我的幸运卷尺，$n。这东西能帮我捕到更大的鱼呢！"
D.Strings[4168]="你需要一种特殊的臭泥鱼诱饵来捕捉加兹兰卡，这些鱼饵是我亲自制作的！$B$B但是除了鱼饵之外，你还需要臭泥鱼……你得把臭泥鱼放入诱饵，让它充满臭味！$B$B将做好的诱饵放到祖尔格拉布中的帕格渔点……然后就坐下来喝酒等待……你无需等太久，因为加兹兰卡肯定会迫不及待地上钩！"
D.Strings[4169]="*吱吱**叮当*\n\n我奉命收购肥美的稀有鱼类，用纳特·帕格的钓鱼用品来交换哦。收购鱼类啦。\n\n*砰**嗡嗡*"
D.Strings[4170]="很抱歉，$c，在你变得更加强大之前，我不能让你去阿拉希盆地送死。"
D.Strings[4171]="钢铁之血格里雷克$B$B游荡者。愿他的力量和对战争的渴望生生不息。$B$B格里雷克正在遥远的地方徘徊。总有一天，他会回来的……"
D.Strings[4172]="去勇者大厅找污染者迪兹·斯诺班，他会帮助你进入阿拉希盆地的。"
D.Strings[4173]="你想要帮助阿拉希盆地的被遗忘者打败人类吗？那就去勇者大厅找迪兹·斯诺班谈谈。"
D.Strings[4174]="臭泥鱼是一种散发着特殊臭味的鱼，它们生活在热带水域中。祖利安臭泥鱼则是其中最臭的一种，只有在祖尔格拉布的水域中才能找到。$B$B我想一定是祖利安臭泥鱼引来了加兹兰卡，尽管巨魔会告诉你它是巨魔膜拜的众多神灵之一，但是……$B$B相信自己——用祖利安臭泥鱼制成的诱饵去捕捉加兹兰卡吧，那家伙肯定会上钩的！"
D.Strings[4175]="去圣殿区找玛洛维尔爵士。"
D.Strings[4176]="阿拉希盆地是从人类手中夺来的。玛洛维尔爵士会把你送到那儿的。"
D.Strings[4177]="锵锵！"
D.Strings[4178]="去灵魂高地下面的预见之池找马丁·林塞。他会帮助你前往阿拉希盆地。"
D.Strings[4179]="你想要帮助阿拉希盆地的污染者打败阿拉索联军吗？很好，去预见之池找马丁·林塞寻求帮助吧。"
D.Strings[4180]="在阿拉希盆地跟被遗忘者作战的人类需要你的帮助。去武器大厅找他们的代表杜纳尔·奥斯古德谈谈。"
D.Strings[4181]="阿拉索联军试图从被遗忘者手中夺回自己的失地。$n，如果你想要帮助他们的话，就跟武器大厅的杜纳尔·奥斯古德谈谈。"
D.Strings[4182]="你可以在国王的觐见室中找到赫塔希姆。她能帮助你前往阿拉希盆地，阿拉索联军需要援助来打败污染者。"
D.Strings[4183]="阿拉索联军在阿拉希盆地所做的一切令人敬佩。可惜亡灵憎恶和他们的部落盟友挡住了去路。去暴风要塞国王的觐见室找赫塔希姆吧，她会帮助你前往阿拉希盆地。"
D.Strings[4184]="阿拉希盆地的人类急需我们的帮助。你得找战士区的克拉斯·沃夫哈特谈谈，他会帮助你的。"
D.Strings[4185]="$c，如果那就是你的愿望，那么去战士区找克拉斯·沃夫哈特谈谈。他是阿拉索联军的代表，能帮助你到达阿拉希盆地。"
D.Strings[4186]="你好，$c！你准备参加战歌峡谷的战斗了吗？为了部落！"
D.Strings[4187]="你好，$n。让我帮你前往战歌峡谷，好吗？"
D.Strings[4188]="$n，必须消灭银翼哨兵！你做好进入战歌峡谷的准备了吗？"
D.Strings[4189]="你是来帮助我们在战歌峡谷作战的吗？为了部落，$c！"
D.Strings[4190]="$C，战歌峡谷需要援助。你能帮助我们攻打战歌前锋吗？"
D.Strings[4191]="$g小伙子:姑娘;，你准备好动身前往奥特兰克山谷了吗？让部落尝尝失败的滋味！"
D.Strings[4192]="$n，你对我们在奥特兰克山谷的处境有什么想法？你准备好跟霜狼氏族作战了吗？"
D.Strings[4193]="必须杀死雷矛卫兵！准备在奥特兰克山谷开战，准备好了吗，$c?"
D.Strings[4194]="为了部落，$c！奥特兰克山谷需要你。"
D.Strings[4195]="我们在奥特兰克山谷的军队需要运用谋略获胜，$c。你看起来是个不错的领导者。"
D.Strings[4196]="希望你是来奥特兰克山谷作战的，$n。我们会竭尽所能，利用一切援助。"
D.Strings[4197]="人类和他们所谓的阿拉索联军想把我们赶出阿拉希盆地。我可不这么想，$c！你得动身前往那儿，证明该离开阿拉希盆地的是他们而不是污染者，准备好了吗？"
D.Strings[4198]="阿拉希盆地曾经是我们的家园，有了你的帮助，我们会收复失地的！你愿意帮助我们吗，$c？"
D.Strings[4199]="希望你是来帮助我们从污染者手中夺回阿拉希盆地的，$n？"
D.Strings[4200]="我一直在盼着你呢，$n。我们在阿拉希盆地的战斗需要你的帮助，你准备好了吗？"
D.Strings[4201]="你认为你能摧毁阿拉索联军吗，$c？希望如此。你究竟是想要干些什么呢，还是根本就是来浪费我的时间的？"
D.Strings[4202]="看看四周，$c。你身边的朋友并不多，我想你需要证明自己的价值。嗯，或许我应该同意你帮助我们在阿拉希盆地作战。你愿意吗？"
D.Strings[4203]="钢铁之血格里雷克$B$B游荡者。愿他的力量和对战争的渴望生生不息。$B$B格里雷克就在疯狂之缘那边……"
D.Strings[4204]="织梦者哈扎拉尔。$B$B他他拥有噩梦的力量，愿他的敌人永远沉睡。$B$B哈扎拉尔正在遥远的地方徘徊。总有一天，他会回来的……"
D.Strings[4205]="千刃之王雷纳塔基。$B$B痛苦是他的生命。恐怖是他的伙伴。愿他早日重返世间。$B$B雷纳塔基就在疯狂之缘那边。"
D.Strings[4206]="雷巫乌苏雷。$B$B她拥有天空、雨水和大地的力量。愿她再次统治古拉巴什。$B$B乌苏雷正在遥远的地方徘徊。总有一天，她会回来的……"
D.Strings[4207]="%s看到他的迅猛龙在战斗中丧命后勃然大怒！"
D.Strings[4208]="哈卡的仆从，听从主人的召唤！圣洁的神庙已经受到威胁。神圣的土地已经被入侵者占领！誓死保护血神祭坛，杀死所有的入侵者！"
D.Strings[4209]="嘿嘿嘿！我在这里是为了推广荆棘谷的超级无敌钓鱼锦标赛的。不过你首先得有足够的生存能力在这里活下去，然后还需要足够在这里钓鱼的精湛技巧。$B$B当你更符合以上条件的时候再回到这里来吧！"
D.Strings[4210]="嗨！嗨！嗨！如果你想要试试自己的钓鱼技能，那么你来对地方啦！本周日荆棘谷将举办一场钓鱼大赛！"
D.Strings[4211]="你还不够强大，$C。继续努力吧。"
D.Strings[4212]="$n，阿拉希盆地急需增援。在这危急时刻，正是获得荣誉、提升声望的大好机会。我恳求你去城中寻找阿拉希盆地的军官。"
D.Strings[4213]="我想参加战斗！"
D.Strings[4214]="你能这么问我很高兴。你可以在黑暗女王所在的皇家区找到玛洛维尔爵士。"
D.Strings[4215]="当然，当然。$C，跟荣誉谷勇者大厅的迪兹·斯诺班谈谈吧。"
D.Strings[4216]="你需要变得更强大，才能帮助我们在奥特兰克山谷作战，$c。"
D.Strings[4217]="嗨，$C。眼下奥特兰克山谷急需援助，这是获得荣誉、提升声望的大好机会。你愿意加入我们，共同对抗雷矛卫队吗？"
D.Strings[4218]="向你的先祖致敬，$C！你可以去荣誉谷的勇士大厅找卡尔特拉·血喉。"
D.Strings[4219]="很好，$n。你可以在幽暗城的皇家区找到格里兹尔。愿你在奥特兰克山谷获得更多的荣耀。"
D.Strings[4220]="很不幸，你还很年轻，无法在战歌峡谷中存活，$C。"
D.Strings[4221]="$C，战歌峡谷急需增援，帮助我们对抗银翼哨兵吧。在那里你可以赢得战歌前锋部队的尊敬！你有勇气加入战斗吗？"
D.Strings[4222]="我要骄傲地告诉你，布拉古尔就在武器大厅，他可以帮助你前往战歌峡谷。去荣誉谷找他吧。"
D.Strings[4223]="你的选择很明智，$n。去猎人高地找克古尔·血斧。他会帮助你前往战歌峡谷的。"
D.Strings[4224]="$C，荣誉和荣耀都将属于你！去皇家区找库尔丁·血爪吧。"
D.Strings[4225]="恐怕你在奥特兰克山谷中活不了多久，$C。等你更加强大一些再回来吧。"
D.Strings[4226]="$n，眼下，奥特兰克山谷的雷矛卫队需要你助战，共同打败霜狼氏族。这是个获得荣誉、提升声望的大好机会！你想要参加战斗吗？"
D.Strings[4227]="钓鱼大师巴斯贝特已经在这片水域中放入了美味的可口鱼，钓鱼比赛可以开始啦。\n\n一旦决出了获胜者，我就会按五条可口鱼换一银币的价格收购其余的可口鱼！"
D.Strings[4228]="你做出了正确的选择，$C。你可以在武器大厅找到军官格罗杜姆·钢须。祝你好运，$n！"
D.Strings[4229]="感谢你的帮助，$C。不幸的是，你的经验不够丰富，无法承受阿拉希盆地的险恶环境。"
D.Strings[4230]="阿拉希盆地急需增援，你能帮助我们吗，$C？这是个获得荣誉、提升声望的大好机会。你的帮助定能扭转局势，帮助我们打败污染者。我们能将希望寄托到你身上吗？"
D.Strings[4231]="谢谢你，$n！你可以在战士区的训练师附近找到克拉斯·沃夫哈特。他会指引你前往阿拉希盆地。祝你好运，那会是一场荣誉之战。"
D.Strings[4232]="我们欠你一个人情，$C。去武器大厅找杜纳尔·奥斯古德，他会乐意帮助你前往阿拉希盆地的。"
D.Strings[4233]="太好了！在阿拉希盆地一役中，你将帮助阿拉索联军战胜污染者和部落那群乌合之众。去暴风要塞的皇家觐见室找赫塔希姆吧。她正等着你呢，$n。"
D.Strings[4234]="四季轮回变幻，但是你年纪尚轻。当你经历更多之后再来找我们吧，$C。"
D.Strings[4235]="$C，战歌峡谷迫切需要增援。如果你愿意助我们一臂之力的话，你将获得前所未有的荣誉。银翼哨兵对你的所做所为也会表示敬意。你愿意加入战斗吗？"
D.Strings[4236]="愿月神之光照耀你，$n！你可以在战士区找到军官伊萨拉斯。她将帮助你前往战歌峡谷。"
D.Strings[4237]="你显示出与你的年龄不相符的智慧，$C。谢谢你。你可以在武器大厅找到军官莱兰迪斯，她能帮助你前往战歌峡谷。"
D.Strings[4238]="权力珍宝是古拉巴什帝国的遗物。赞达拉氏族正在寻找权力珍宝——它们不仅具富收藏价值，赞达拉氏族还相信它们含有远古帝国使用的强效魔精。$B$B你可以在祖尔格拉布找到三种权力珍宝：硬币、宝石和原始物品。一旦你收集到一定数量的权力珍宝，你将获得赞达拉氏族制作的最好的物品。$B$B奖励丰厚，值得一试！"
D.Strings[4239]="银翼哨兵欠你一份情，$C。你可以在暴风要塞的皇家觐见室找到军官艾弗拉兰。愿女神保佑你！"
D.Strings[4240]="你胆敢踏足哈卡莱的圣地？哈卡的属下们，摧毁这些异教徒！"
D.Strings[4241]="很高兴遇到你，渔夫！如果你想要在钓鱼比赛中一展自己的钓鱼技能，那么就听好了！在本周日，荆棘谷将举办一场钓鱼大赛，选出一名真正的钓鱼大师！"
D.Strings[4242]="你好！我在这里是为了推广荆棘谷的超级无敌钓鱼锦标赛的。不过你首先得有足够的生存能力在这里活下去，然后还需要足够在这里钓鱼的精湛技巧。$B$B当你更符合以上条件的时候再回到这里来吧！"
D.Strings[4243]="权力珍宝是强大的魔精，是古拉巴什帝国的魔精。我们赞德拉部族必须得到魔精，必须把魔精占为己有。血神将无法毁灭我们。$B$B在祖尔格拉布有三种权力珍宝。去找到硬币，找到珠宝。找到原始神灵的物品。这些都是权力珍宝。$B$B现在就去祖尔格拉布，杀戮……然后拿到权力珍宝。把它们带给部族，获得我们的尊敬，赢得我们对你的奖励，得到真正的力量。"
D.Strings[4244]="钓鱼大赛的赢家已经胜出，但是贾恩愿意收购你们钓到的可口鱼！\n\n每周日都会有一场钓鱼大赛，你尽可再来展示自己的钓鱼技能！"
D.Strings[4245]="嘿！恭喜你，朋友！"
D.Strings[4246]="在我身后是赞扎祭坛，赞达拉部族的神圣之地。我们在此祷告，希望能充分做好对抗血神哈卡的准备工作。$B$B利用祭坛摧毁你在祖尔格拉布找到的任何哈卡莱宝石，以此证明你对部族的价值。我会用赞达拉荣誉硬币跟你交换祖尔格拉布的硬币。找到我需要的硬币，你将获得丰厚的奖励！"
D.Strings[4247]="赞达拉巨魔长途跋涉，历经艰险才来到此地，但是这一切却招致我们的厄运……"
D.Strings[4248]="我们赞达拉巨魔长途跋涉来自此地，因为我们不能对威胁整个世界的危机视而不见。$B$B我们的远征队首领莫托尔带领我们来到荆棘谷海岸以北的尤亚姆巴岛，招募勇敢的英雄深入古老的巨魔城市……祖尔格拉布。"
D.Strings[4249]="我们赞达拉巨魔长途跋涉来自此地，因为我们不能对威胁整个世界的危机视而不见。"
D.Strings[4250]="我想我能凭借自己的力量回到要塞。你为我赢得了宝贵的时间，我应该能悄悄离开这儿。无论你是谁……我都感谢你。愿月神永远保佑你！"
D.Strings[4251]="我想要让宠物遗忘技能。"
D.Strings[4252]="老狗学不会新把戏。至少我听人这么说过。你运气真好，因为我发现这种说法是错误的。$B$B现在，你打算让宠物遗忘天赋吗？"
D.Strings[4253]="我是驻扎在阿拉希盆地的污染者物资供应商卢瑟弗·图恩。随着你在污染者中的声望不断提升，我可以出售给你一些非常有用的物品。如果你需要修理装备，我也乐意为你服务。"
D.Strings[4254]="我是驻扎在阿拉希盆地的阿拉索联军物资供应商萨缪尔·霍克。随着你在阿拉索联军中的声望不断提升，我可以出售给你一些非常有用的物品。如果你需要修理装备，我也乐意为你服务。"
D.Strings[4255]="是的，就这样吧。"
D.Strings[4256]="战歌峡谷一役至关重要，我们必须获胜。我们为了荣誉和土地而战，兽人或是他们那些误入歧途的盟友是无法打败我们的！"
D.Strings[4257]="要保护部落在灰谷的木材收集工作并不容易，但是我们从不畏惧战斗！暗夜精灵和他们的盟友必将失败！"
D.Strings[4258]="凡人，逃跑是无济于事的！"
D.Strings[4259]="我向要塞提供各种施法所需的碎片和其它炼金材料。"
D.Strings[4260]="一股强大的邪恶力量正在蠢蠢欲动，$R。你感觉到了没？$B$B啊！当然你无法感觉到。把你的护甲和武器给我吧，我会让它们恢复活力。"
D.Strings[4261]="唉，我现在的补给品储量已经非常少了！是什么耽搁了那个该死的地精那么长时间？"
D.Strings[4262]="看看你身后，$R。虫巢中的异动使我们周围的土地震动起来。$B$B现在是我们实现一千年前许下的诺言的时候了。沙土飞扬，似乎其拉虫人是在计划开战了。"
D.Strings[4263]="为什么是现在，$R？我不明白。要做的事情还有很多……"
D.Strings[4264]="指挥官最近一直心不在焉。他的妻子在最近的一次南部沙漠考古挖掘中失踪了——一下子消失地踪影全无！真的非常奇怪。$B$B我想你是不是想要找份工作？我是不是可以给你一些提示？"
D.Strings[4265]="你可以听到吗，陌生人？嗡嗡的声音一天比一天响。这些水晶一定是把那些虫子逼疯的元凶。"
D.Strings[4266]="仰望天空吧，$C。这片区域已经有一千年没有见过龙族了！我就知道，那些其拉虫人在策划着什么阴谋！"
D.Strings[4267]="铜须再次失踪了！那家伙跟他的兄弟不一样，一点判断力都没有。"
D.Strings[4268]="燃烧稻草人产生的灰烬散发出了魔法的力量。"
D.Strings[4269]="将我脸上的灰尘抹去！"
D.Strings[4270]="燃烧稻草人产生的灰烬散发出了魔法的力量。你把这些灰烬抹在了脸上。"
D.Strings[4271]="万圣节快乐，$C！"
D.Strings[4272]="你喜欢糖果吗？我喜欢糖果。"
D.Strings[4273]="走吧，被遗忘者！走吧！"
D.Strings[4274]="欢迎来到稻草人庆典，$c！$B$B按照万圣节的习俗，被遗忘者要焚烧一个稻草人来纪念这个最崇高的时刻。就是在这一天，女妖之王将我们从巫妖王和天灾军团的魔掌中解救了出来，从那以后，我们就成了自由之身，直到今天。那些想要毁灭我们的敌人终将为他们的罪行付出代价，承受我们复仇的怒火！$B$B如果你想加入我们的狂欢，就请在稻草人焚烧的时候，将掉落的火灰抹在你的脸上吧！"
D.Strings[4275]="你！你看起来身体强健……南海镇需要你的帮助！$B$B万圣节到了，那些受诅咒的被遗忘者蠢蠢欲动。他们把所谓的庆典开到我们家门口来了。如果你有时间的话，我们真的需要你的帮助！"
D.Strings[4276]="啊哈！我痊愈了！我痊愈了……啊，起身太快了！"
D.Strings[4277]="感谢你找到了我的材料！*打呵欠*这毒药令我……感到疲倦……"
D.Strings[4278]="我们必须先发制人，绝对不能重蹈覆辙……"
D.Strings[4279]="受死吧，异教徒！愿深渊的力量毁灭你！"
D.Strings[4280]="你这怪物，我可不是什么教徒！来吧，受死吧！"
D.Strings[4281]="赤红圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！"
D.Strings[4282]="深渊议会绝不容许欺骗行为！尝尝我们的怒火吧，$R！"
D.Strings[4283]="你好，$c。欢迎来到塞纳里奥要塞。我们在这个异种生物最强盛的地方对抗他们。我希望你可以助我们一臂之力。"
D.Strings[4284]="我很高兴再见到你，$n。你的帮助为我们保证了补给线的安全。我希望你可以理解在如此一场大战中，物资补给的重要性。"
D.Strings[4285]="暮光之锤的事情没有什么进展？去搜索一下东南面的山岭吧。传言说那里居住着一个神秘的隐士。"
D.Strings[4286]="苍白圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！"
D.Strings[4287]="土色圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！"
D.Strings[4288]="碧蓝圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！"
D.Strings[4289]="没有糖果就捣乱！"
D.Strings[4290]="你这渺小的虫子，你竟敢跟议会公爵交谈！"
D.Strings[4291]="卑鄙的公爵，听好了！我可不是暮光之锤的走狗！我是来向你提出挑战的！来吧，受死吧……"
D.Strings[4292]="灰烬公爵！我手中握着你的徽记！响应我的召唤吧！"
D.Strings[4293]="微风公爵！我手中握着你的徽记！响应我的召唤吧！"
D.Strings[4294]="碎石公爵！我手中握着你的徽记！响应我的召唤吧！"
D.Strings[4295]="深渊公爵！我手中握着你的徽记！响应我的召唤吧！"
D.Strings[4296]="你是在猎杀死亡弯钩吧，$n？我记得很清楚。这周我手下的两个家伙就是被她杀死的。希望你的运气比他们好。"
D.Strings[4297]="嗨！谢谢你手下留情，没有惩罚我！我想我得躺一会儿恢复体力。"
D.Strings[4298]="你是谁？我在哪儿？我感到……非常虚弱……"
D.Strings[4299]="从石头中传来雷鸣般的声音……$B$B你好，指挥官。你从希利苏斯给议会领主带来了什么消息？"
D.Strings[4300]="审判之日已经来临了，恶魔！我向你挑战！"
D.Strings[4301]="斯卡德诺克斯！我手中握着你的节杖，我召唤你进入这个世界！"
D.Strings[4302]="维拉希斯！我手中握着你的节杖，我召唤你进入这个世界！"
D.Strings[4303]="卡苏姆！我手中握着你的节杖，我召唤你进入这个世界！"
D.Strings[4304]="斯古恩！我手中握着你的节杖，我召唤你进入这个世界！"
D.Strings[4305]="你好，鲁特加尔。指挥官派我来这里收集他失踪的妻子的信息。"
D.Strings[4306]="你最好坐下，这是个很长的故事。$B$B当我们第一次来到希利苏斯时，玛尔利斯女士是塞纳里奥要塞中第一位加入远征队的暗夜精灵。我们的行程没有什么特别的：组队进入虫巢探险，寻找失落的神器。"
D.Strings[4307]="那听上去很危险。"
D.Strings[4308]="很明显！居住在虫巢中的异种虫并不欢迎我们的到来。$B$B一切进展顺利，直到我们在雷戈虫巢中发现了一块雕文水晶。她象飞蛾扑火一般急切地抓起水晶，把脸凑上去，精神也变得恍惚起来。队友们都很担心她。我们以最快的速度将她带出了虫巢！"
D.Strings[4309]="她后来怎么样了？"
D.Strings[4310]="我们把她交给了指挥官，希望议会的德鲁伊能医好她。我们相信德鲁伊们能让她清醒过来。我们跟议会之间已经两清，该回去做自己的事情了。$B$B过了好几周，一切看来进展顺利。布莱恩仍然四处奔波，我们也正常地工作着。有一天，她突然出现在我们的营地里。"
D.Strings[4311]="纳塔莉亚？"
D.Strings[4312]="你聋了吗？我还能指谁？当然是玛尔利斯女士。无论如何，她已经回来了，但是她的心情似乎不太好。她需要我们帮个忙。"
D.Strings[4313]="帮什么忙？"
D.Strings[4314]="她要我们立即返回雷戈虫巢！布莱恩拒绝了她。他认为我们在没有军队支援的情况下是无法进入虫巢的。那样太危险了。跟我们首次进入虫巢相比，这些虫子的数量似乎膨胀了3倍。$B$B纳塔莉亚就是在那时得了失心疯的！"
D.Strings[4315]="失心疯？你说的是什么意思？"
D.Strings[4316]="你认为我说的什么意思？她变得十分疯狂！那个女孩就在我们面前变疯了。一般来说我不会动手，但是当我从震惊中清醒过来的时候，我变得非常气愤。布莱恩，鲁特加尔，我，当然还有猴子，一起向她扑去！我们能挡开她真是一个奇迹。她好像完全被占据了！"
D.Strings[4317]="被什么占据了？"
D.Strings[4318]="谁知道呢？无论如何，那是我最后一次见到她。或许弗兰卡能告诉你更多信息。$B$B别转移话题，我想指挥官给你的工作相当重要吧，但是我们也是来执行重要任务的！铁炉堡对我们请求军队增援的要求置若罔闻。很明显，以我们的力量难以保护这片土地。一旦你将报告交还给指挥官，就跟你的朋友一同回到这儿来。我们需要你的帮助！"
D.Strings[4319]="等我把这些搞定了就会立刻回来。"
D.Strings[4320]="你好，弗兰卡。我听说你知道纳塔莉亚的下落。"
D.Strings[4321]="哦，就是这样了……先找个椅子，$g小伙子:小姑娘;。$B$B我肯定鲁特加尔已经告诉你一些事情了，因此我将省略一些细节，让你直奔主题。"
D.Strings[4322]="这就是我希望听到的。"
D.Strings[4323]="好吧！她从虫巢回来过，但是布莱恩一点都没有察觉到！混战之前，她开始跟什么人交谈起来。奇怪的是，她用了一种我们从未听过的语言谈话。"
D.Strings[4324]="那真奇怪。"
D.Strings[4325]="那还用说！布莱恩、鲁特加尔、猴子和我都对此感到陌生，我们懂38种语言，还略懂一点泰坦语——连瓦尼尔和艾斯尔都不例外。$B$B总之，她嘴里叽里咕噜说的话没人能懂。“礼物”？她点点头，就开始攻击我们！直接攻击我们！"
D.Strings[4326]="你连一个落单的暗夜精灵女祭司都没法摆平？"
D.Strings[4327]="听着，$G小家伙:小姑娘;，你要知道，攻击我们的不是女祭司！她口吐白沫，眼睛闪着邪恶的光芒！她进来之后发出尖啸，我们被迫四下逃离，然后她便一个个地鞭荅我们的灵魂。我听见暗言术的声音，看着其他人不断倒下。要不是那该死的猴子，我们就全都玩完了！"
D.Strings[4328]="我想要问问你关于那只猴子的情况。"
D.Strings[4329]="你要问些什么？你这个愚蠢的家伙，它是只猴子。在它看到布莱恩跌倒在沙土上时，它就发疯了。格里布狠狠教训了暗夜精灵一顿。"
D.Strings[4330]="然后呢？"
D.Strings[4331]="我会告诉你接下来发生了什么事。她直奔虫巢去了。还有什么比这更疯狂的事儿了吗？没有一支虫子阻挡她的去路。她直接从虫子身边跑过，就好像他们是交情很深的老朋友一样。"
D.Strings[4332]="真是一个有意思的故事！那么说来她进入了雷戈虫巢，然后这就是你最后一次见到她了？"
D.Strings[4333]="是。"
D.Strings[4334]="感谢你提供的信息，弗兰卡。"
D.Strings[4335]="你是个不错的祭品！"
D.Strings[4336]="水晶上布满了神秘的雕文和符文。你无法理解。"
D.Strings[4337]="从石头中传来很轻的声音……$B$B你好，渺小的凡人。你为圣殿骑士带来了什么消息？"
D.Strings[4338]="从石头中传来清晰的声音……$B$B你的身份勋章在哪里？没有身份勋章的话，你就无法和公爵对话……"
D.Strings[4339]="从石头中传来清晰的声音……$B$B你带着你的头衔来找我们，我们将会聆听，但是不要试图考验我们的耐心，$c。议会没有时间来和你这样的凡人闲聊。"
D.Strings[4340]="议会领主面前出现了一只虫子？没错，无疑是一只想要被碾碎的虫子！"
D.Strings[4341]="从石头中传来雷霆般的声音……$B$B这是什么？我感觉到一个小小的信徒在窜来窜去！快点走开，苦力，否则你将面对议会领主的愤怒！"
D.Strings[4342]="你总是家族中最爱惹麻烦的家伙，诺格。总是！"
D.Strings[4343]="<使用抄写工具来收集一份拓文。>"
D.Strings[4344]="你想要飞往什么地方？"
D.Strings[4345]="希利苏斯的灵魂召唤我们，$n。土地在哭泣，它有个悲惨的故事要告诉我们……"
D.Strings[4346]="%s发出奇怪的声音。"
D.Strings[4347]="你好，$C。看来你最近在进行一项秘密的收集工作？你还是老样子，但是这是个繁忙的城市。$B$B如果你参加了那场会议，你就该得到一段神秘兑换码。把神秘兑换码告诉我，我就会给你一份特殊的奖励作为回报。"
D.Strings[4348]="$n！我希望你已经准备好开始工作了，因为逐日岛这里有很多事需要你来做。$B$B自从阿尔萨斯和天灾军团破坏了太阳之井以后，我们就一直笼罩在命运的迷雾中，在毁灭的边缘挣扎着。$c，一切都会改变。怀着血精灵一族必将再次崛起的信念，伸出援手帮助我们走上复兴之路吧。$B$B外域等待着我们！"
D.Strings[4349]="塞纳里奥议会是睿智的，他们发现了很多有关大地的秘密。愿意聆听这些德鲁伊的教诲的工匠总是会得到许多宝贵的知识。"
D.Strings[4350]="这个鬼魂一样的身影不信任地看着你，并且保持着沉默。"
D.Strings[4351]="太阳之塔曾经被太阳之井滋养着……但是现在，我们的生活完全被颠倒了，$n，即使是这样，我们还是坚持了下来。这是我们的出路，我们是幸存者。$B$B如果你是从这巨变中幸存下来的……如果你想要继续把握自己的命运，那么你必须学会怎么去生存。所有的血精灵都必须这么做。你必须在魔法控制你之前控制住你对它的渴望。"
D.Strings[4352]="你为血精灵作出的贡献对我们的生存来说是十分重要的！我们必须尽全力把自己从泥潭中拔出来。$B$B如果你已经准备好了，那么就让我们开始吧。"
D.Strings[4353]="知识就是力量——真正的力量，我年轻的朋友。尽你所能地学习新知识吧，同时虚心向那些学有所成的智者请教，这才是明智的做法。$B$B在太阳之井被夷为平地之前，我们曾经愚蠢地认为自己的文明已经达到巅峰。在与亡灵天灾的战斗中，血精灵却遭遇惨败……这才让我们看清自己的处境。"
D.Strings[4354]="你在我研究的关键时刻帮了我一把！不用担心，如果你不介意的话，我欢迎你安静地投以注视……一定要“安静”哦。"
D.Strings[4355]="要是你正准备去城里，那么我有些重要的事情需要你来做！"
D.Strings[4356]="欢迎！上前来，不要害羞。$b$b这就是我最自豪的发明……雷管5000型超级大炮！她很漂亮，是不是？"
D.Strings[4357]="很简单！你只要给我一个暗月游戏代币，我就把你装进炮管，然后点燃引线。$B$B你被发射出去之后，能够在空中“漂浮”一会儿，但是这种情况不会持续很久。当然，你也可以脱掉我给你的“翅膀”，来加速下坠。$B$B你的目标就是码头边水面上的一个大型浮标。$B$B可不要在进入水域上空之前脱掉翅膀，否则……呃……我可不出售人身保险。"
D.Strings[4358]="我可以购买什么？"
D.Strings[4359]="问得好！我们马戏团有很多东西出售。如果您对食物和饮料感兴趣的话，那么您可以去斯塔姆和塞兰妮亚的小店看看。\n\n如果您想要购买一些特别的东西，那么兰拉出售的货物会很适合您。她专门出售来自世界各地的珍稀物品。\n\n另外从到处跑来跑去的弗里克那里购买可以用于投掷的球和宠物青蛙。"
D.Strings[4360]="暗月马戏团奖券？"
D.Strings[4361]="很高兴您问到这个问题。暗月马戏团奖券就是您兑换一些特别的奖品时所需要的货币！\n\n您可以通过完成每月任务，以及玩马戏团内的各项游戏来获得奖券。$b$b每月任务奖励的奖券最多，但是每天玩游戏也是一个积累奖券的好方法。$b$b当您集满足够的奖券时，就可以到马戏团的各个商人处消费了。"
D.Strings[4362]="暗月卡片是什么？"
D.Strings[4363]="没有人知道谁制作了暗月卡片，或者他们真正的意图是什么，但是我可以告诉你，在艾泽拉斯各地都可以找到它们，那些试图揭开它秘密的邪恶怪物手中都可能有卡片。"
D.Strings[4364]="马戏团有哪些游乐设施？"
D.Strings[4365]="在希利苏斯，我们的敌人不止一个，$n。$B$B虽然每个人的注意力都集中到异种虫类身上，但是我和我的兄弟密切注视着暮光之锤的一举一动。"
D.Strings[4366]="哈哈哈！万圣节快乐，$n！"
D.Strings[4367]="我或许有99种问题，但是跳舞绝对不是问题！万圣节快乐，$n！"
D.Strings[4368]="恰－恰，喔－喔！万圣节快乐，$n！"
D.Strings[4369]="哦，太强壮了！万圣节快乐，$n！"
D.Strings[4370]="你好，旅行者。大约1000年前，其拉虫人开始了对卡利姆多大陆的战争。$B$B在那场战争中损失了数以千记的生命，大多数都是在战争爆发初期丧身在这片该死的沙漠中的。$B$B我是少数幸存下来的人，我连接了过去和现在。我不知道我为什么还留在这里，但是我知道我必须这样做。"
D.Strings[4371]="你怎么知道？"
D.Strings[4372]="我被杀死过无数次。我总是发现我会在这里醒来。有些人说我遭受了诅咒，还有些人……"
D.Strings[4373]="他们说什么？"
D.Strings[4374]="他们说我被祝福了：新世纪需要被聆听的传讯者。"
D.Strings[4375]="你说了什么？"
D.Strings[4376]="上古的力量被数千年来从未活动过的虫子所震撼。世界在哭泣，$r。也许一次新的灾变正在开始。其中孕育的是痛苦……$B$B那些可恶的家伙开始渗透入我们的土地。噩梦来自于睡眠。噩梦开始在我们醒着的时候纠缠我们……"
D.Strings[4377]="什么？你这样的家伙也敢召唤我？你会受到惩罚的！"
D.Strings[4378]="背叛只会加速你的灭亡。世界将陷入黑暗！"
D.Strings[4379]="万圣节快乐！你喜欢我的面具吗？非常吓人呢！"
D.Strings[4380]="我要错过“不给糖果就捣乱”了！"
D.Strings[4381]="我太伤心了！万圣节到了，我却没法出去，不能玩要糖果的恶作剧游戏！"
D.Strings[4382]="你真好，$n——谢谢你陪我玩要糖果的恶作剧游戏！"
D.Strings[4383]="这是一场肆无忌惮的狂欢！$B$B世界各地的旅店老板都会为“不给糖就捣蛋”准备好各种糖果，许多城镇都将装饰一新，欢度节日！此外，幽暗城外还会在夜间举办稻草人庆典。"
D.Strings[4384]="怎么玩？！$B$B世界各地的旅店老板都会将糖果分发给孩子们，许多城镇都将装饰一新，欢度节日！此外，南海镇的哈特曼中士需要帮助，他想要攻击那些被遗忘者，破坏他们的稻草人庆典。$B$B对了，我听说暴风城孤儿院里有个生病的小男孩，他想找人陪他玩要糖果的恶作剧游戏……或许你能帮帮他？"
D.Strings[4385]="有人叫我……伊普斯？"
D.Strings[4386]="陌生人，赶快离开！我跟你没有关系。"
D.Strings[4387]="你已经回来了！现在，我能为你做什么呢？"
D.Strings[4388]="与部落之间的战争已经到了白热化的阶段，$n。联盟需要大量的物资，我们应竭尽所能，提供帮助。"
D.Strings[4389]="战争即将来临，$n。每个部落成员都要响应号召，并肩击溃懦弱的联盟。"
D.Strings[4390]="你是个皮革商吧？我对兽皮的味道再熟悉不过了。$B$B我的父亲过去常常跟我谈起数世纪前一位居住在南风村的著名工匠。很遗憾，那儿已是一片废墟了。"
D.Strings[4391]="生命的希冀已被切断！梦游者要展开报复！"
D.Strings[4392]="来吧，梦游者——复仇！"
D.Strings[4393]="让我吞噬你的灵魂吧！"
D.Strings[4394]="我能感受到你内心的阴影。邪恶的侵蚀永远不会停止！"
D.Strings[4395]="尝尝堕落的滋味吧！"
D.Strings[4396]="希望是灵魂染上的疾病！这片土地应该枯竭，从此死气腾腾！"
D.Strings[4397]="和平不过是短暂的梦想！让梦魇统治整个世界吧！"
D.Strings[4398]="疯狂的种子——我将你释放到这个世界！"
D.Strings[4399]="啊，$n——很高兴再次见到你。我相信你的事业进展得很顺利。"
D.Strings[4400]="我们已经集齐了所需的铜锭。谢谢你的帮助，$C。你还可以帮帮其他正在收集作战物资的人。"
D.Strings[4401]="$C，我需要更多的铜锭！安其拉之战迫在眉睫，我们需要战争物资！联盟已经收集到$1997w块铜锭了，总的需求量是$1998w块。如果我不能完成任务，我就会被砍头的！"
D.Strings[4402]="你在水晶中看到了巨大的通道和走廊。你认得这个地方：熔火之心。"
D.Strings[4403]="让他们感受蓝龙的愤怒吧！愿玛里苟斯庇护我！"
D.Strings[4404]="阿莱克丝塔萨，赋予我坚定的信念，让我击退敌人！"
D.Strings[4405]="渺小的凡人，在无尽的噩梦中沉睡吧。让噩梦吞噬你！"
D.Strings[4406]="阿纳克洛斯，声东击西的战术能让你和年轻的德鲁伊有足够的时间来封印大门。不要犹豫。现在，让我们看看它们如何对付这些混乱的魔法。"
D.Strings[4407]="暗夜精灵，不要忘记今天牺牲的人们。这些野兽让我们蒙受了巨大的损失。"
D.Strings[4408]="阿纳克洛斯，我们会击退他们的。我发誓会支持你完成这项任务。当你动手封印这股毁灭的力量时，千万不要出错。"
D.Strings[4409]="我们必须赶快，否则就一切都太晚了！"
D.Strings[4410]="我的军队不足以抵抗安其拉的部队。我们无法走到足够近的地方，启动你那宝贵的魔法屏障。"
D.Strings[4411]="还有一个办法……"
D.Strings[4412]="%s看了一眼她的同胞。"
D.Strings[4413]="%s心照不宣地点了点头。"
D.Strings[4414]="范达尔，记住我的话：别让悲痛动摇了你的信念。你的思想……将把你引入黑暗，暗夜精灵。误入歧途的复仇是不能被赦免的。"
D.Strings[4415]="鹿盔！我们走吧！准备好你的魔法！"
D.Strings[4416]="完成了。你来带路吧。"
D.Strings[4417]="靠近些……"
D.Strings[4418]="你好，$r。活着真好，不是吗？"
D.Strings[4419]="并不是所有牛头人都藐视你们$r。不过，我无法向你提供服务。"
D.Strings[4420]="鹿盔，赶快完成施法！我没法让节界雕文继续维持原位了！召唤自然的力量！"
D.Strings[4421]="远古的神灵，指引我……从沉睡中苏醒吧！醒来，封印这片被诅咒的地方！"
D.Strings[4422]="%s双腿一软，筋疲力尽地跪倒在地。"
D.Strings[4423]="鹿盔，结……结束了。我们胜利了。虽然我们为此付出了惨痛的代价。"
D.Strings[4424]="还有一件事要解决……"
D.Strings[4425]="在我离开之前，鹿盔，我还要再送一件东西给你。如果有一天，因为某些原因，你必须进入这座被诅咒的堡垒，就在神圣的铜锣上使用流沙节杖。屏障上的魔法将被驱散，而安其拉的恐怖气息也将再次传遍世界。"
D.Strings[4426]="%s将流沙节杖交给了范达尔·鹿盔。"
D.Strings[4427]="在我的人民目睹并经历了那场暴行之后，你还指望我能挑起这个沉重的负担？很明显，你疯了。"
D.Strings[4428]="我不想再跟希利苏斯、其拉虫人和该死的龙类有任何关系了！"
D.Strings[4429]="%s将流沙节杖扔向魔法屏障，节杖顿时碎裂开来。"
D.Strings[4430]="时间之沙将停止流动，但只有片刻的时间！我现在要召唤屏障。"
D.Strings[4431]="鹿盔，你要去哪儿？为了自尊和高傲，你就要切断我们的联系？"
D.Strings[4432]="虚假的胜利无法告慰我儿子的灵魂，巨龙。我会把他找回来的。尽管这或许需要数千年，但是我会把他找回来的！"
D.Strings[4433]="%s失望地摇着头。"
D.Strings[4434]="%s蹲下身去捡起被摔碎的节杖碎片。"
D.Strings[4435]="凡人，现在你已经知道一切了……"
D.Strings[4436]="听着，我们是在赌上性命跟安其拉的虫人战斗，因此需要做好充分的战斗准备。我在此地收集铁锭。目前，联盟只收集到$2002w块，而总的需求量是$2003w。"
D.Strings[4437]="在大家的努力下，我们已经集齐了必需的铁锭。问问其他人，看他们是否需要你帮忙收集作战物资。至于我，我得瞧瞧我能不能早点离开，去玩几局牌。"
D.Strings[4438]="如果你能帮帮忙的话，那真是太感谢了。你看，我正在收集战争所需的瑟银锭。我们总共要收集$2012w块瑟银锭，但是我们有$2011w块。"
D.Strings[4439]="谢谢你，$C。我们已经集齐了所需的瑟银锭了，但是你可以问问这儿收集其他作战物资的负责人。"
D.Strings[4440]="真的，就连荆棘藻也会成为战争中的重要资源！它有许多用途，比如用来制作可以在希利苏斯的炎炎烈日下品尝的冰淇淋，清除一些非常难以清除的植物，水下呼吸，硬化皮肤，让你的行动变得更迅速，恢复魔法能量，太多了，我简直没法一一历数！我有没有说冰淇淋？$B$B总之，我手头上总共有$2047w份的存货，而需求总量是$2048w！"
D.Strings[4441]="我不是置疑你收集荆棘藻的能力，但是我们似乎已经拥有足够的荆棘藻了。至少我是这么听说的。这儿的其他人需要你帮忙收集战争物资。收集其他的作战物资可没有收集荆棘藻那么有趣，我能理解你这种想法。"
D.Strings[4442]="紫莲花的用处很多，年轻的$C。联盟派我收集这种花，为安其拉之战做好准备。我答应帮助他们收集$2055w份紫莲花，目前我们已经收集到了$2053w份。"
D.Strings[4443]="我们正在为战争作准备，$c。我们一定要彻底消灭安其拉的威胁，为了战备的需要，我在这里收集阿尔萨斯之泪这种材料。我不清楚这些草药是用来做什么的。如果你问我的话，我可不想跟那个疯子扯上关系，即使这不过是一种以他命名的花而已。不过，我不仅是个联盟的公民，还是一名军人，因此我会遵守上级的命令。现在我们已经收集到$2057w份阿尔萨斯之泪了，总的需求量是$2058w份。"
D.Strings[4444]="我想是这样的。我们已经收集到足够的阿尔萨斯之泪了。你可以四下问问。肯定还有人在收集其它作战物资。"
D.Strings[4445]="我得到报告说，你对深渊议会的战果卓著，$n。你干得很好！$B$B继续保持斗志，我们会奖励你的！"
D.Strings[4446]="联盟让我的家族在这儿收集大量的轻皮以供作战准备。我们已经收集到$2060w张轻皮了，而总的需求量是$2061w张。或许你愿意帮帮我们。"
D.Strings[4447]="你胆敢在中立领地动手？！出去！"
D.Strings[4448]="我们不会对犯错者手软，$r。"
D.Strings[4449]="看招，混帐！"
D.Strings[4450]="请告诉我你没有做那件我认为你刚刚做了的事情。请告诉我……我不必对你动手……"
D.Strings[4451]="难道我们的麻烦还不够多吗？你还要火上浇油？！"
D.Strings[4452]="说真的，你等一下就会情愿自己根本没生出来，混蛋！"
D.Strings[4453]="你的行为让我们蒙羞，$c。我感到深深的耻辱，所以你死定了。"
D.Strings[4454]="谢谢你的关心，$C。但是我们已经集齐轻皮了。或许这儿负责收集物资的其他人需要你的帮助。"
D.Strings[4455]="长官！列兵波特向您报告，随时准备帮助您收集中皮。安其拉之战迫在眉睫，我们需要做好充分的准备。$B$B我们已经收集到$2063w块中皮了，总的需求量是$2064w块。"
D.Strings[4456]="啊，呃，是的，$G先生:女士;。我们已经集齐联盟在战争中所需的所有中皮了。我听说这儿的其他人需要你的帮助。"
D.Strings[4457]="嗨，$C！今天真是个收集厚皮的好日子，不是吗？我收集到一堆厚皮了，似乎已经有$2069w块啦。需求量是$2071w块。你想要帮帮我们吗？"
D.Strings[4458]="哇！似乎我们已经集齐厚皮了。速度很快呢。你可以问问这儿的其他人，看他们是否需要帮助。"
D.Strings[4459]="你好，$C。我正在为安其拉之战收集亚麻绷带。这场战争对我们来说是一次严酷的考验和锻炼，你捐献的绷带将在战争中挽救士兵们的生命。我需要收集$2077w根亚麻绷带，到目前为止已经有$2076w根了。你愿意帮助我们吗？"
D.Strings[4460]="谢谢你，$C。但是我们已经集齐联盟在安其拉一战中所需的亚麻绷带了。你可以帮帮其他人收集战争物资。"
D.Strings[4461]="你好，$C，你今天感觉怎么样？希望你一切都好。联盟派我来监督收集丝质绷带的工作；到目前为止，我们已经设法收集到$2082w根丝质绷带，而需求量是$2083w根。你想要帮助我们吗？"
D.Strings[4462]="谢谢你的关心，但是我们已经集齐丝质绷带了。你可以四下问问，看看他们是否需要帮助。"
D.Strings[4463]="$C，在即将来临的战争中，即使最勇敢的士兵也需要治疗。当无法运用魔法治疗时，士兵们必须依赖于我们收集的战争物资了。到目前为止，我已经收集了$2088w根符文布绷带，总需求量是$2090w根。$B$B让我们谈谈你能我们做什么吧。"
D.Strings[4464]="$C，在许多人的帮助下，我们已经设法集齐了联盟所需的战争物资符文布绷带。如果我是你的话，我会问问这儿的其他人，看他们是否需要帮助。"
D.Strings[4465]="唉，$n，我太忙了，没时间来闲聊。就像我提到过的那样，我需要时间来考虑当前的处境。$B$B祝你的旅途好运，祝你度过愉快的一天。"
D.Strings[4466]="嗯，嗯，嗯。你闻到了吗？！这儿有好吃的东西，$C。彩鳍鱼实在是道绝佳的美味。美食家斯里克对品尝鱼类非常在行。联盟认为在收集战争物资时带上一位专家是个明智的决定，因此，我就被派到这儿来了。我们需要$2093w条彩鳍鱼，到目前为止已经收集到$2092w条了。"
D.Strings[4467]="呃，看来我们拥有的烤彩鳍鱼已经能满足安其拉一战的需求了。谢谢你的关心，$C。如果你想帮忙的话，就在附近问问。我敢打赌这儿有人需要你帮忙收集战争物资。"
D.Strings[4468]="来吧！你的朋友不会为你哀悼太久的！"
D.Strings[4469]="嗨，$C。联盟派遣我来到此地监管烤肉的收集工作。这听起来很有趣吧？我想你一定想知道我们收集到多少烤迅猛龙肉了。我上次数了数，我们已经有$2098w块了，总需求量是$2099w块。"
D.Strings[4470]="看来你来得太晚了，$C。我们已经集齐所需的烤迅猛龙肉了。但是，似乎还有人需要帮助。你可以跟他们谈谈。我得看看他们会不会现在就让我回家。"
D.Strings[4471]="对那些在战场上负伤的士兵来说，食物可以维持他们的生命，$C。安其拉一战我们需要准备足够的物资。我在这儿负责收集并装运斑点黄尾鱼。到目前为止，我们已经收集到$2101w条了，要满足整个军队的需求的话，我们总共需要收集$2103w条。"
D.Strings[4472]="散开，$c！"
D.Strings[4473]="走开，$n！"
D.Strings[4474]="不要找茬，公民！"
D.Strings[4475]="我们需要大量铜锭，$C。安其拉一战迫在眉睫，我们需要准备足够的金属来制造武器、护甲和其他器物。部落需要收集$1998w块铜锭。到目前为止，我们已经收集到$2018w块了。"
D.Strings[4476]="$n，很高兴再次遇到你。$B$B记住在你的学习上保持专注。你代表了我们的未来，如果你遭遇了失败，我们的未来无疑会变得更加黑暗。"
D.Strings[4477]="你好，$C。你是来帮助我收集锡锭的吗？我需要收集$2006w块锡锭，以用于制造安其拉一战所需的武器和护甲，但是到目前为止我只收集到$2005w块。你得再帮我收集一些！"
D.Strings[4478]="欢迎来到鹰翼广场旅店。需要给您准备一顿美食，还是准备一间房间？"
D.Strings[4479]="嗨，$C。铁炉堡军团驻扎在此地，密切注视着佐拉虫巢的动静。塞纳里奥要塞的德鲁伊们一直监视着异种虫类的一举一动，他们预计这儿将发生大事。"
D.Strings[4480]="上尉现在很忙。我们最近刚得到一份异种虫类的虫巢地图，他正在研究这张地图。如果你想要帮忙的话，就跟我们待在一起，他随时都会出来的。"
D.Strings[4481]="嗨，你到这儿来一定是带秘银锭给我的吧。我需要收集$2009w块秘银锭，但是现在只收集到$2008w块。你愿意帮帮我吗？"
D.Strings[4482]="它们来了。尽量别被它们干掉，新兵。"
D.Strings[4483]="你好，年轻的$C。你到这儿来是带宁神花给我的吗？我们正在为安其拉之战做准备，收集宁神花，制作药水和药剂。如果我们准备得不够充分的话，将会产生非常严重的后果。$B$B部落派我来此收集$2020w株宁神花，到目前为止我们已经设法收集到$2021w株了。如果你力所能及的话，就请帮帮我们，把宁神花带给我。"
D.Strings[4484]="你想要伤害我吗，$R？"
D.Strings[4485]="我将永远在此守护，凡人。"
D.Strings[4486]="魔法不仅仅是做几个神秘的手势……你应该已经明白这个道理了，对吗？$B$B你是来学习知识的，只要你用心领悟，并听从我的指导，那么你就能学到知识……只有头脑愚钝的家伙才不愿意探究恶魔的秘密，当然我也不会在意这样的蠢材。"
D.Strings[4487]="<安多洛夫严肃地看着你。>$B$B如果它会流血，我们就能杀了它。"
D.Strings[4488]="拉贾克斯，还记得我说过要杀光其它虫子之后再干掉你么？"
D.Strings[4489]="你是来寻找守护蓝龙的节杖碎片的？$B$B<艾索雷苟斯的表情似乎是在微笑。>"
D.Strings[4490]="你是怎么知道的？我是说，是的……我正在寻找碎片。你有吗？"
D.Strings[4491]="我当然没有碎片。把那东西带在身上是极其愚蠢的做法。我生活在这片被诅咒的蛮荒之地上！我走不到五步，就必然有疯子一般的兽人或是人类想要攻击我。我随时都可能命丧黄泉。$B$B总之……我把那东西藏起来了。$B$B继续吧……问问我把碎片藏在哪儿了。"
D.Strings[4492]="好吧。在哪儿？"
D.Strings[4493]="你会喜欢这个故事的，$R。听着吧。当玛里苟斯让我保护节杖碎片时，我就知道我会为此头痛的。$B$B我只想在这片满是魔法遗物的海岸线上进行研究工作，寻找那次世界分裂时留下的神器。要知道，这儿是艾萨琳城的废墟，女王艾萨拉的家园！你不需要告诉我这附近有魔法器物，$R。我能闻到它们的味道！"
D.Strings[4494]="你究竟……在说什么……？"
D.Strings[4495]="正如我所说的，我保存节杖碎片已经有500年了，这东西真麻烦。所有生物都不怀好意地觊觎这块碎片。我希望能专心研究，不受打扰。因此……我把它扔给了一条鱼。"
D.Strings[4496]="鱼？你是说你把这件可能关系到整个卡利姆多命运的东西交给了一条鱼？"
D.Strings[4497]="不是别的鱼类，凡人。我说的是米诺鱼，一种非常特别的米诺鱼。"
D.Strings[4498]="米诺鱼？海里到处都是米诺鱼！有上亿条呢！"
D.Strings[4499]="正是！"
D.Strings[4500]="这是个天才的想法，我知道……它永远都不会被找到的。为了确保这一点，我赋予了这条米诺鱼某些特殊的能力。"
D.Strings[4501]="你把那东西绑到一条米诺鱼身上，然后将那条鱼放到这片大陆与东部王国之间的水域中，而且这条鱼拥有特殊的能力？"
D.Strings[4502]="没错。你一直在认真听我说话！在我创造的生物当中，这条米诺鱼算得上是一个相当可怕的家伙了。每当我放松休息的时候，我就喜欢想象那些不幸的渔民，想象他们碰到这条鱼，然后被完全吞掉的样子。我敢打赌他们会对此惊讶万分的！$B$B<艾索雷苟斯大笑起来。>"
D.Strings[4503]="你疯了。"
D.Strings[4504]="天才总是被人误解，$R。关于节杖碎片……如果你想要很快得到那块碎片，而不是耗费数万年时间盲目寻找的话，就要仔细听好了。"
D.Strings[4505]="我在全神贯注地听你说呢。"
D.Strings[4506]="四个字：奥金鱼漂。"
D.Strings[4507]="再说一遍？"
D.Strings[4508]="好吧……你需要制作一个奥金鱼漂，把它放进海水中。米诺鱼会被奥金鱼漂所吸引，当它接近鱼漂时——砰！奥金鱼漂将释放出神秘的力量，使它现出原形。不过这么一来，你有可能招致耐普图洛斯的仇恨，几率大概是50%吧。"
D.Strings[4509]="好吧，让我们打开天窗说亮话吧。你把阿纳克洛斯交给你们蓝龙军团保管的节杖碎片给了某条你造出来的米诺鱼；现在你希望我制造一个……奥金鱼漂什么的玩意，用它来追踪你的那条鱼？另外这还可能引发元素领主的愤怒？我说漏了什么没有？或许我得找个闰年，在日食时分，赤身裸体地帮你干这件事儿？"
D.Strings[4510]="如果我不明事理的话，我会认为你是在嘲笑我，凡人。但是，那基本是最正确的做法，不过你得把全身裹起来。"
D.Strings[4511]="好吧！我斗胆问一句，我怎么才能弄到奥金鱼漂呢？"
D.Strings[4512]="将这个账本交给我在塔纳利斯的老朋友。他名叫纳瑞安，是个精神极度癫狂的伟大技师！他应该能读懂这东西。$B$B不用谢谢我，$n。这是我唯一能做的。$B$B祝你好运！"
D.Strings[4513]="当心点，凡人。那些强大的生物就是在此地葬生的。"
D.Strings[4514]="一千年前，阿纳克洛斯和鹿盔封印安其拉大门时，三位族人牺牲了自己的性命，将其拉虫人禁锢在这些大墙内，流沙之战宣告结束。$B$B他们曾立下誓言，一旦甲虫之墙开启，他们就将召唤麦琳瑟拉、阿瑞苟斯和凯雷斯特拉兹。$B$B因此……我们来了。"
D.Strings[4515]="你难道不应该马上动身去拯救世界吗？"
D.Strings[4516]="<纳瑞安将一封未打开的信贴到他的前额。>$B$B这是什么……嗯……天鹅绒！$B$B是吗？$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……"
D.Strings[4517]="别说话！让我猜猜！你是为灰烬使者而来的吗？！对……呃……不对！不好意思。$B$B我能帮你什么忙吗，$R？$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……"
D.Strings[4518]="纳瑞安为您效劳！退隐的工程学专家和占卜大师！我敢打包票！$B$B如果你来这里是为了遗忘某个专业技能专精以便重新选择，就用那边的书……"
D.Strings[4519]="你真烦人，$n。"
D.Strings[4520]="你所选择的道路和我的不一样。$c，你必须去别的地方训练。"
D.Strings[4521]="我会以牧师的方式来训练你，如果那是你到这里来的原因的话。"
D.Strings[4522]="我需要潜行者训练。"
D.Strings[4523]="%s凝视着$n！"
D.Strings[4524]="哈哈哈，你过得怎么样。你可帮了比雷凯基的大忙。我们需要大量的火焰花。他们说，嘿，比雷凯基，你得马上集齐$2051w份火焰花。到目前为止他只收集到$2050w个，但是你能很快帮我们完成任务，是吗？"
D.Strings[4525]="啊，你来了。我被告知在这儿等候帮助，请仔细听我说。目前的状况是：安其拉之战即将展开，我奉命收集$2055w份紫莲花，现在已经收集到$2054w份了。事实上，收集紫莲花的工作只能交给你和那些愿意帮助我的人，因为我必须在这儿做好紫莲花的入库存储工作，并研究它的新用途，以便对抗异种虫和安其拉高墙后的神秘生物。"
D.Strings[4526]="你是来帮助我们收集重皮的吗？很好，很好。你看，我已经收集到$2066w块重皮了，总的需求量是$2067w。我的朋友，这儿有很多皮可以剥，希望你的小刀足够锋利。重皮的用途很广，包括在战争打响之后修补地精飞艇。"
D.Strings[4527]="凡人，这儿充斥着一种难以言说的恐怖。克苏恩和他的追随者们不仅公然藐视自然的力量，他们的存在更预示着艾泽拉斯的毁灭。$B$B一千年前，麦琳瑟拉、凯雷斯特拉兹和阿瑞苟斯都牺牲了自己以保全这个世界。我们来这里不仅仅是要报仇，还因为我们必须阻止克苏恩！"
D.Strings[4528]="$C，我有个重要的消息！安其拉即将爆发一场战争，我们需要为此做准备。我是来收集厚皮的，现在我们已经收集到$2070w块厚皮了，但是酋长要求我收集$2071w块。你看，我就差那么一点了。"
D.Strings[4529]="你好，$C。我想你一定是来帮助我们进行备战工作的。我负责为部落收集硬甲皮，我认为这任务简直非我莫数。不要低估锋利的剥皮小刀的作用。$B$B我们已经收集到$2073w块硬甲皮了，总的需求量是$2074w。"
D.Strings[4530]="我发现大海是如此平静。"
D.Strings[4531]="很高兴再见到你，$n！你替我带信给亲爱的小侏儒，我真的很感谢你。$B$B你想听一首歌吗？它或许能使你的航海之旅变得轻松一些！"
D.Strings[4532]="啊，$C，很高兴见到你。我们正在为安其拉之战收集物资，当然，我们需要你的帮助。我得收集大量的急救物品，主要是绒线绷带。我已经收集到$2079w根绷带了，总的需求量是$2080w。"
D.Strings[4533]="你好，$C，很高兴你露面了。我长话短说，我们正在为安其拉之战收集战争物资。我需要收集$2086w根魔纹绷带。到目前为止，我们已经收集到$2085w根了。你愿意帮忙吗？"
D.Strings[4534]="大地母亲为我们提供了生存物资，但是有时候，士兵们需要一些额外的帮助才能存活。安其拉之战迫在眉睫，我正在收集符文布绷带。到目前为止，我们已经收集到$2089w根符文布绷带，总的需求量是$2090w。"
D.Strings[4535]="感谢你对我们的关心，$C。但是我们已经集齐备战所需的符文布绷带了。你可以问问其他的收集者，为他们提供帮助。愿你的祖先保佑你。"
D.Strings[4536]="呃，你想要什么，$R？哦，你一定是为瘦狼排来的吧。没错，你的消息没错，我正在收集瘦狼排。你有吗？我只需要$2096w块，现在我们已经收集到$2095w块了。"
D.Strings[4537]="嗨，我正在为部落收集食物。安其拉沙漠中即将发生一场恶战，我需要收集$2103w条斑点黄尾鱼。到目前为止，我们只有$2102w条。"
D.Strings[4538]="你好，$C。你乐意帮助我们收集作战物资，这真好。收集者们在此收集多种物资储备。我负责收集$2106w条烤鲑鱼，供给参与安其拉之战的士兵们。目前我们已经收集到$2105w条了。"
D.Strings[4539]="谢谢你的关心，$C，但是我们已经集齐战争所需的烤鲑鱼了。或许你可以跟其他收集者谈谈，他们也许会需要你的帮助。"
D.Strings[4540]="新的一年来临了，月光洒满大地。$B$B这是属于我们的日子……远古的生命苏醒了。"
D.Strings[4541]="在过去的岁月里，我们以狩猎为生。我们为了荣誉而狩猎……$B$B现在有什么不同吗？"
D.Strings[4542]="凡人，你想要学习龙人语言，这简直是异想天开。为什么你想要学习这种古老的语言呢？真是不可理喻……"
D.Strings[4543]="<为了艾泽拉斯，拿上这本书吧！>"
D.Strings[4544]="你好，$R。我是部落大使佐格将军。我是来向你通报部落关于安其拉一战的准备工作的进度的。你想知道什么？"
D.Strings[4545]="你说有多少金属锭？我得到的最新消息是联盟已经收集到$2018w块铜锭、$2005w块锡锭和$2008w块秘银锭了，而总的需求量分别是$1998w、$2006w和$2009w。"
D.Strings[4546]="我得到的最后的消息称，部落已经收集到$2021w份宁神花、$2050w份火焰花和$2054w份紫莲花，而总的需求量分别是$2020w、$2051w和$2055w。"
D.Strings[4547]="皮革？哦，我刚收到消息。似乎部落已经收集到$2066w块重皮、$2070w块厚皮和$2073w块硬甲皮，而总的需求量分别是$2067w、$2071w和$2074w。"
D.Strings[4548]="部落正在收集绷带。到目前为止，我们已经收集到$2079w根绒线绷带、$2085w根魔纹绷带和$2089w根符文布绷带，而总的需求量分别是$2080w、$2086w和$2090w。"
D.Strings[4549]="你想知道收集工作的进度吗？很好。我得到的最新消息称，部落已经收集到$2095w个瘦狼排、$2102w条斑点黄尾鱼和$2105w条烤鲑鱼，而总的需求量分别是$2096w、$2103w和$2106w。"
D.Strings[4550]="你好，$R$C。我是此地的联盟大使汉默·石锤。$G小伙子:姑娘;，如果你想要了解联盟战争物资的收集情况，问我好了。"
D.Strings[4551]="问得好，$C。联盟共需要$1998w块铜锭、$2003w块铁锭和$2012w块瑟银锭。到目前为止，他们已经设法收集到$1997w块铜锭、$2002w块铁锭和$2011w块瑟银锭了。"
D.Strings[4552]="让我看看，让我看看。我有做过记录的。啊，找到了！到目前为止，联盟已经收集到$2047w份荆棘藻、$2053w份紫莲花和$2057w份阿尔萨斯之泪，而总的需求量分别是$2048w、$2055w和$2058w。"
D.Strings[4553]="嗯，这个问题很有趣……我收到的最新消息是，到目前为止，联盟已经收集了$2060w张轻皮、$2063w张中皮和$2069w张厚皮了，而总的需求量分别是$2061w、$2064w和$2071w。"
D.Strings[4554]="你是说绷带吗？哦，如果我没有记错的话，联盟已经收集到$2076w根亚麻绷带、$2082w根丝质绷带和$2088w根符文布绷带了，而总的需求量分别是$2077w、$2083w和$2090w。"
D.Strings[4555]="这倒提醒我了，我得去找点吃的。据说联盟已经收集到$2092w条彩鳍鱼、$2098w块烤迅猛龙肉和$2101w条斑点黄尾鱼，而总的需求量分别是$2093w、$2099w和$2103w。一旦收集完毕，这些食物就将被运往希利苏斯的塞纳里奥要塞。"
D.Strings[4556]="星光指引着新的道路，未来燃起希望和力量的灯塔。"
D.Strings[4557]="时局紧张，所有的战争物资都在运往希利苏斯塞纳里奥要塞的途中，预计将在$2113w天内全部抵达。一旦有人修复节杖，离战争也就不远了。"
D.Strings[4558]="哈哈，一切准备就绪！收集工作结束了，物资将如约由地精飞艇运往希利苏斯。预计最后一批将在$2113w天内抵达。一旦节杖复原，与那些肮脏的虫子的战争也就开始了。现在，开始装运吧！"
D.Strings[4559]="你好，$C。我听说所有的物资都已经收集完毕，将如约运往希利苏斯。货物将在$2113w天内到达，在那之后，流沙节杖的持有者将敲响铜锣，战争也就开始了。"
D.Strings[4560]="好极了，双方都完成了收集工作。现在这些物资都已经运往希利苏斯了，所有的货物预计将在$2113w天内抵达。一旦准备就绪，就会有人使用流沙节杖敲响甲虫之台的铜锣，战争也就开始了！"
D.Strings[4561]="伙计，欢迎来到藏宝海湾。希望你在这儿度过一段快乐而……嗯，平静的日子。如果你口渴的话，我们这儿有很多饮料；如果你担惊受怕的话，我们这儿还有很多保镖。$B$B现在，我这个卑微的地精仆从能为你做些什么呢？呃，你又能为我做些什么呢？"
D.Strings[4562]="任务都完成了，年轻的$C。就如我们先前约定的那样，部落和联盟必须将所有的战争物资都运往希利苏斯的塞纳里奥要塞附近，货物将在$2113w天内运达。在那之后，安其拉大门的铜锣将被敲响，战争也就拉开序幕了。"
D.Strings[4563]="你是来这儿报到的吗，$C？部落和联盟所需的所有战争物资都已经收集完毕，如约运往希利苏斯了。货物在$2113w天内就会抵达。希望有人能找到流沙节杖的碎片，将它们组合到一起。"
D.Strings[4564]="我听说所有的物资都已经收集完毕并且运往塞纳里奥要塞了。货物将在$2113w天内抵达。一旦我们的装备和军队准备就绪，流沙节杖的持有者就可以敲响安其拉附近的铜锣，打开大门。那时，战争也就开始了。"
D.Strings[4565]="安其拉之战所需的物资正在准备运往塞纳里奥要塞！据说最后一批货物会在$2113w天内抵达。在那之后，我们就能敲响铜锣，打开安其拉的大门了。我打赌我们会给那些虫子迎头痛击的！"
D.Strings[4566]="嗨，$C！似乎部落已经集齐所有的战争物资了，现在部落和联盟的物资都将如约运往希利苏斯。据说货物在$2113w天之内就能到达，那时就能敲响安其拉大门附近的铜锣，战争也就开始了。"
D.Strings[4567]="$C，所有的战争物资将如约运往希利苏斯。按照目前的情况来看，货物将在$2113w天内全部抵达。然后，某位英雄将敲响甲虫墙上的铜锣，战争也就开始了。"
D.Strings[4568]="似乎所有的物资都将在接下来的$2113w天内运抵希利苏斯。一切就绪后，某位英雄将敲响甲虫墙上的铜锣，打开安其拉的大门。那时，我们收集的绷带就能派上用场了。"
D.Strings[4569]="$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在$2113w天内抵达。整装待发的大军将等待一位英雄修复流沙节杖，敲响铜锣，拉开安其拉一战的序幕。"
D.Strings[4570]="所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在$2113w天内抵达。一旦有人使用流沙节杖敲响铜锣，安其拉一战也就拉开序幕。"
D.Strings[4571]="我们已经收集了所有的战争物资，现在只等部落完成他们的收集任务了。那时，我们就能将所有的物资运往希利苏斯，战争也就开始了。"
D.Strings[4572]="我们收集的所有食物和战争物资都在运往希利苏斯的途中。似乎在$2113w天内货物就可全部抵达。有人告诉我说物资一旦到达塞纳里奥要塞，就会有人敲响甲虫墙上的铜锣，打开安其拉的大门，战争也将拉开序幕。"
D.Strings[4573]="你好，$R。战争物资正在运往塞纳里奥要塞的途中，货物将在$2113w天内抵达。我们只希望那时会有一位拿着流沙节杖的英雄敲响铜锣，打开安其拉的大门。"
D.Strings[4574]="没想到你竟如此精通协调管理。安其拉一战迫在眉睫，联盟和部落都已经做好了充分的准备工作。所有的战争物资将如约运往希利苏斯，预计将在$2113w天抵达。那是，会有一位英雄使用流沙节杖敲响甲虫之台的铜锣，打开安其拉之门。那时战争就真正打响了！"
D.Strings[4575]="不出所料，部落比你们这帮所谓的联盟提前完成了收集任务。只有等你们集齐物资，我们才能进行最后的装运工作，是你们拖累了我们。$B$B现在，快去做好你的本职工作吧，$R。"
D.Strings[4576]="$C，所有的战争物资都已经收集完毕，并且在运往希利苏斯的途中了。预计货物将在$2113w天内抵达。我只希望铜锣敲响，安其拉之门打开后，我们的努力会有所回报，挽救更多的生命。"
D.Strings[4577]="我们似乎只须再等$2113w天了，所有的战争物资将被运往希利苏斯沙漠。一切准备就绪之后，将会有人敲响塞纳里奥要塞南边的铜锣，打开安其拉之门，拉开战争的序幕。"
D.Strings[4578]="部落和联盟的收集任务都完成了，没错，$C。所有的战争物资都在运往希利苏斯塞纳里奥要塞的途中，预计在$2113w天内就可全部抵达。我想我们只需等待有人修复流沙节杖，敲响铜锣，打开安其拉的大门，拉开战争的序幕。"
D.Strings[4579]="梦魇是不可抵挡的！"
D.Strings[4580]="%s夺走$n的最后一丝气息，吞噬了他们的灵魂。"
D.Strings[4581]="来吧，$n。看看梦魇给你带来了什么……"
D.Strings[4582]="我们以能为萨尔效劳而感到骄傲。我们将不惜一切代价，消灭我们的敌人！"
D.Strings[4583]="你来得正是时候，$C。你感觉到脚下的大地在颤抖了吗？$B$B虫巢里的敌人正在逼近我们。站到步兵旁边去，$n。我就指望你了！"
D.Strings[4584]="异种虫类根本不是奥格瑞玛的勇士们的对手。很快，它们支离破碎的躯壳和翅膀就会洒满我们脚下的土地，$n。"
D.Strings[4585]="你算错了一招，野兽。你不曾料到我们会在玛法里奥的身边召唤你吧？伊兰尼库斯，你的救赎就要来临了。你将得到净化——堕落之源将被清除。"
D.Strings[4586]="%s疯狂地咆哮起来。"
D.Strings[4587]="如此近距离地接近异种虫类而不被察觉需要相当的技巧。如果可能的话，我不建议你做这样的尝试。"
D.Strings[4588]="别误解我的意思，我可不想没日没夜地跟异种虫类呆在一起，但是如果隐藏在此地监视这些生物的动静对我们有帮助的话，我会一直呆下去的。"
D.Strings[4589]="很快我们就能让那些可憎的异种虫类从艾泽拉斯世界消失了。它们可能造成的破坏比你先前所见的要恐怖得多，$n。他们背后是更可怕、更黑暗的力量。"
D.Strings[4590]="我是来拿你的报告的。"
D.Strings[4591]="我们团结一致，为共同的目标而努力，$R。来自上古的邪灵威胁着卡利姆多，他妄图让整个世界陷入无尽的堕落……他仇视生命的缔造者——永恒的泰坦所创造的一切生物。$B$B我们是惟一能与克苏恩的大军抗衡的军队。如果我们不振作起来同仇敌忾的话，敌人一定会摧毁一切。$B$B为我们的作战物资储备尽自己的力吧！"
D.Strings[4592]="%s的速度慢下来了！"
D.Strings[4593]="%s冻结了！"
D.Strings[4594]="%s突然裂开了！"
D.Strings[4595]="%s看起来就要碎裂了！"
D.Strings[4596]="在这头驯鹿的脖子上挂着一个小牌子，牌子上印着烟林牧场的标志和一个名字：“梅森”。$B$B梅森用悲哀而孤独的眼神看着你，它似乎被某种无形的力量困住无法动弹了。"
D.Strings[4597]="梅森的眼睛里亮起了喜悦的光芒。"
D.Strings[4598]="即使你能设法不打败克苏恩而解救我们，我们也会不惜一切代价将他驱逐回地狱。不惜一切代价。"
D.Strings[4599]="龙类指派的英雄？必须除掉克苏恩！我们可以帮助你，凡人！"
D.Strings[4600]="我真不敢相信自己的眼睛，这简直是个奇迹！一千年来，除了那些肮脏的其拉虫人和异种虫类，我都不曾见过有活人进入这些房间。"
D.Strings[4601]="别忘了观看下一场焰火表演！每天下午6点开始，每小时整点都会有一次！"
D.Strings[4602]="我不知道他们给那些酒桶里放了什么，但闻起来很香甜！"
D.Strings[4603]="你好啊，朋友！"
D.Strings[4604]="你好，$C。我是大元帅斯诺·落雪。$G小伙子:姑娘;，我们面前的道路充满艰辛，如果你想要帮忙的话，请尽量帮助我们。有什么问题尽管问吧。"
D.Strings[4605]="我们成功了，$G小伙子:姑娘;！联盟和部落已经集齐了安其拉一战所需的所有物资。现在这些物资都在运往希利苏斯塞纳里奥要塞的途中，预计将在$2113w天内达到。然后，会有一位勇敢的英雄使用流沙节杖敲响甲虫之台的铜锣，打开安其拉之门。那时，战争也就开始了！"
D.Strings[4606]="你听到那条好消息了吗，$C？联盟已经集齐战争物资了！现在只等部落完成他们的收集任务。那时，所有的战争物资将被运往希利苏斯，安其拉之战就也开始了。"
D.Strings[4607]="问得好，$C。我得到的最新消息称我们已经收集到$1997w块铜锭、$2002w块铁锭和$2011w块瑟银锭了，总的需求量分别是$1998w、$2003w和$2012w。"
D.Strings[4608]="草药，草药，嗯，让我看看。啊，是的。到目前为止我们已经收集到$2047w份荆棘藻、$2053w份紫莲花和$2057w份阿尔萨斯之泪，而总的需求量分别是$2048w、$2055w和$2058w。"
D.Strings[4609]="我刚刚得到最新的消息。似乎我们已经收集到$2060w张轻皮、$2063w张中皮和$2069w张厚皮，而总的需求量分别是$2061w、$2064w和$2071w。"
D.Strings[4610]="收集绷带的工作正有条不紊地按计划进行着。我们已经收集到$2076w根亚麻绷带、$2082w根丝质绷带和$2088w根符文布绷带了，总的需求量分别是$2077w、$2083w和$2090w。"
D.Strings[4611]="我们已经收集到了$2092w条彩鳍鱼、$2098w块烤迅猛龙肉和$2101w条斑点黄尾鱼，而总的需求量是$2093w、$2099w和$2103w。"
D.Strings[4612]="你好，部落的$C。我是督军格尔库克，部落物资收集行动的指挥官。艰难的岁月就要来临，但我们还是会获胜的，胜利永远属于我们。$B$B如果你有什么问题，就去问问他们吧。"
D.Strings[4613]="战争犹如箭在弦上，$C！部落和联盟都做好了充分的准备。所有的战争物资都将如约运往希利苏斯。预计货物将在$2113w天内抵达。当军队准备就绪时，那位完成修复流沙节杖的艰巨任务的英雄将敲响甲虫之台上的铜锣，打开安其拉之门。一场旷世之战也将随即拉开序幕！$B$B部落万岁！"
D.Strings[4614]="我们已经收集到$2018w块铜锭、$2005w块锡锭和$2008w块秘银锭，而总的需求量是$1998w、$2006w和$2009w。"
D.Strings[4615]="我刚得到消息说，我们已经收集到$2021w份宁神花、$2050w份火焰花和$2054w份紫莲花，而总的需求量分别是$2020w、$2051w和$2055w。"
D.Strings[4616]="给我点时间，要记录的数据很多。看来我们已经收集到$2066w块重皮、$2070w块厚皮和$2073w块硬甲皮了，总的需求量分别是$2067w、$2071w和$2074w。"
D.Strings[4617]="绷带？为什么，你需要绷带救命吗？哈哈！很好，$R，我会告诉你的。我们已经收集到$2079w根绒线绷带了，总的需求量是$2080w根。另外，到目前为止，我们拥有$2085w根魔纹绷带和$2089w根符文布绷带，总的需求量分别是$2086w和$2090w。"
D.Strings[4618]="收集食物是眼下我惟一的工作！我们已经收集到$2095w块瘦狼排、$2102w条斑点黄尾鱼和$2105w条烤鲑鱼了，总的需求量分别是$2096w、$2103w和$2106w。"
D.Strings[4619]="你好，$C。我是塞纳里奥要塞的兽栏管理员莱欧伦。"
D.Strings[4620]="这里有一大堆精心包裹的礼物。"
D.Strings[4621]="这件礼物的卡片上写着：“40岁以上适用。”"
D.Strings[4622]="整个世界都感激你和你的同伴们所做的一切，$n。"
D.Strings[4623]="如果克苏恩还活着的话，我们的自由将变得没有意义。你真是个预言中的勇士。"
D.Strings[4624]="很快人们就会知道这座被诅咒的神殿背后的秘密，英雄。它将被载入史册，跟那些从扭曲虚空到艾泽拉斯的传说一起，被永远传诵。"
D.Strings[4625]="战争犹如箭在弦上，蓄势待发；部落和联盟都有着无数强大的勇士。$B$B但愿他们不会互相争斗……"
D.Strings[4626]="这件礼物的卡片上写着：“20岁以上适用。”"
D.Strings[4627]="这件礼物的卡片上写着：“10岁以上适用。”"
D.Strings[4628]="詹迪斯·巴罗夫的日记充斥着被遗忘者疯狂的怨念。在日记的结尾似乎有一份制作背包的裁缝图样。按你对裁缝技能的掌握程度，还不足以解读这张图样。"
D.Strings[4629]="只有那些对木喉没有敌意的人能通过安全通过要塞。陌生人，你赢得我们的信任了吗？"
D.Strings[4630]="你在找什么，$C？"
D.Strings[4631]="本年度新品：PX-238型欢乐制造器。请上前来尝试一下！不要害羞！$B$B在尝试之前请填写这些表格，我们还在修正这台机器的某些问题……"
D.Strings[4632]="你好，$C——我是达纳苏斯的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在达纳苏斯的声望也会因此提高。"
D.Strings[4633]="你好，$C——我是诺莫瑞根流亡者的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在诺莫瑞根流亡者中的声望也会因此提高。"
D.Strings[4634]="你好，$C——我是铁炉堡的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在铁炉堡的声望也会因此提高。"
D.Strings[4635]="你好，$C——我是暴风城的嘉奖官。我的职责就是帮助那些获得联盟荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在暴风城的声望也会因此提高。"
D.Strings[4636]="你好，$C——我是奥格瑞玛的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在奥格瑞玛的声望也会因此提高。"
D.Strings[4637]="你好，$C——我是暗矛部族的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在暗矛部族的声望也会因此提高。"
D.Strings[4638]="你好，$C——我是雷霆崖的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在雷霆崖的声望也会因此提高。"
D.Strings[4639]="你好，$C——我是幽暗城的嘉奖官。我的职责就是帮助那些获得部落荣誉徽章的冒险者们。$B$B我一次可收取不同数量的徽章，但是对你来说，一次缴纳10枚徽章可获得最高收益。我会保留你缴纳徽章的记录，你在幽暗城的声望也会因此提高。"
D.Strings[4640]="很快你就会知道多管闲事的后果了，凡人……我的主人很快就能恢复力量……当他站起来的时候，就是你的世界毁灭的时候。"
D.Strings[4641]="每个人都有礼物！冬天爷爷的礼物就放在树下！"
D.Strings[4642]="纳命来！"
D.Strings[4643]="战士们，军官们，继续战斗！"
D.Strings[4644]="无礼的蠢货！我会亲自要了你们的命！"
D.Strings[4645]="范达尔！你的死期到了！藏到翡翠梦境里去吧，祈祷我们永远都找不到你！"
D.Strings[4646]="鹿盔将会呜咽着哀求我饶他一命，就像他那懦弱的儿子一样！一千年来的屈辱会在今天洗清！"
D.Strings[4647]="让敌人胆战心惊吧！让他们在恐惧中死去！"
D.Strings[4648]="我们不用再呆在这座石墙里面了！我们很快就能报仇了！在我们的怒火面前，就连那些龙也会战栗！"
D.Strings[4649]="我们复仇的时刻到了！让敌人的内心被黑暗吞噬吧！"
D.Strings[4650]="%s察觉到了你的恐惧。"
D.Strings[4651]="你们玷污了这片神圣的土地，会因此受到惩罚的！上古之神的律法不容藐视！入侵者要付出生命的代价！"
D.Strings[4652]="我宣判你死刑！"
D.Strings[4653]="我战斗到了最后一刻！"
D.Strings[4654]="你这么想死吗？我很乐意满足你的愿望……"
D.Strings[4655]="就用你的死做个警示吧！"
D.Strings[4656]="你是在逃避必然的命运！"
D.Strings[4657]="沙漠，扬起你的沙砾，遮蔽太阳的光芒吧！"
D.Strings[4658]="你被终结了。"
D.Strings[4659]="我……败……了。"
D.Strings[4660]="每天下午6点钟，雷霆崖都会有华丽的焰火表演！"
D.Strings[4661]="美酒良辰！尽情地喝吧，我的朋友，尽情地狂欢吧！"
D.Strings[4662]="听说在焰火表演之后，桌子上就会摆满高脚杯，然后我们就可以喝酒庆祝了！"
D.Strings[4663]="嗨，$c！欢迎你！"
D.Strings[4664]="哈！来亲一个吧！"
D.Strings[4665]="冬幕节快乐，朋友！"
D.Strings[4666]="节日快乐！"
D.Strings[4667]="祝你节日快乐，朋友！"
D.Strings[4668]="啊，槲寄生……"
D.Strings[4669]="%s的力量被削弱了！"
D.Strings[4670]="这里的天气真不错，你说呢？"
D.Strings[4671]="为什么当你要用到发条式同步协调陀螺仪的时候它们总是无影无踪呢？"
D.Strings[4672]="我是最后的大赢家……他们会看到的！啊，你好啊，$c，我刚才没看到你。"
D.Strings[4673]="发明创造，我亲爱的$c，就是百分之二的灵感，百分之四的日光浴，百分之六的雷阵雨之后的清新，以及百分之九十三的鬼点子。$B$B等等，这加起来好像不是百分之一百？我的笔记本去哪里了……"
D.Strings[4674]="我们得看看其拉虫人到底给这些怪物吃的是什么！看看它们的个头！"
D.Strings[4675]="研究并了解这些巨甲虫，可以让我们更有把握打败其拉虫人！"
D.Strings[4676]="巨甲虫的能量所隐藏的秘密将引发科学界的一场大变革！"
D.Strings[4677]="灰石长者在哪里？"
D.Strings[4678]="灰石长者在提瑞斯法林地的布瑞尔附近打发时间。"
D.Strings[4679]="袭月长者在哪里？"
D.Strings[4680]="袭月长者在西瘟疫之地的通灵学院里。"
D.Strings[4681]="暗灵长者在哪里？"
D.Strings[4682]="暗灵长者在幽暗城。"
D.Strings[4683]="黑曜石长者在哪里？"
D.Strings[4684]="黑曜石长者在银松森林的瑟伯切尔附近游荡。"
D.Strings[4685]="雪冠长者在哪里？"
D.Strings[4686]="雪冠长者在东瘟疫之地的圣光之愿礼拜堂。"
D.Strings[4687]="雪峰长者在哪里？"
D.Strings[4688]="雪峰长者在辛特兰中部的一座山丘顶部。"
D.Strings[4689]="风路长者在哪里？"
D.Strings[4690]="风路长者在东瘟疫之地的皇冠哨塔里。"
D.Strings[4691]="远风长者在哪里？"
D.Strings[4692]="远风长者在斯坦索姆的街道上徘徊。"
D.Strings[4693]="铁环长者在哪里？"
D.Strings[4694]="铁环长者生活在灼热峡谷的黑炭谷中。"
D.Strings[4695]="金井长者在哪里？"
D.Strings[4696]="金井长者在丹莫罗的卡拉诺斯歇脚。"
D.Strings[4697]="铜须长者在哪里？"
D.Strings[4698]="铜须长者在他们家族的老家铁炉堡里。"
D.Strings[4699]="银脉长者在哪里？"
D.Strings[4700]="高阶女祭司现在不能离开达纳苏斯。范达尔的情绪非常奇怪。"
D.Strings[4701]="泰兰德送来了她的问候。月神与我们同在。"
D.Strings[4702]="银脉长者就在洛克莫丹的塞尔萨玛附近。"
D.Strings[4703]="黎明长者在哪里？"
D.Strings[4704]="黎明长者在黑石深渊的秩序竞技场打发时间。"
D.Strings[4705]="石墙长者在哪里？"
D.Strings[4706]="石墙长者到黑石塔去了。"
D.Strings[4707]="巨石长者在哪里？"
D.Strings[4708]="巨石长者在燃烧平原的巨槌石顶部的一座山洞里。"
D.Strings[4709]="星歌长者在哪里？"
D.Strings[4710]="星歌长者应该是在悲伤沼泽的沉没的神庙中。"
D.Strings[4711]="雷眉长者在哪里？"
D.Strings[4712]="雷眉长者眼下应该正在艾尔文森林的闪金镇停留。"
D.Strings[4713]="冰蹄长者在哪里？"
D.Strings[4714]="冰蹄长者？我听说他在藏宝海湾。"
D.Strings[4715]="逐星长者在哪里？"
D.Strings[4716]="逐星长者每天都在哨兵岭上俯瞰西部荒野。"
D.Strings[4717]="晨行者长者在哪里？"
D.Strings[4718]="晨行者长者在燃烧平原的烈焰峰。"
D.Strings[4719]="雷锤长者在哪里？"
D.Strings[4720]="雷锤长者就在暴风城城墙外。"
D.Strings[4721]="风怒长者在哪里？"
D.Strings[4722]="风怒长者在诅咒之地的一座高山上眺望着黑暗之门。"
D.Strings[4723]="迅刀长者在哪里？"
D.Strings[4724]="迅刀长者在达纳苏斯的街道上闲庭信步。"
D.Strings[4725]="夜光长者在哪里？"
D.Strings[4726]="夜光长者就在艾萨拉地区的拉文凯斯雕像附近。"
D.Strings[4727]="刃叶长者在哪里？"
D.Strings[4728]="刃叶长者的家在泰达希尔顶部的小村庄多兰纳尔。"
D.Strings[4729]="星纹长者在哪里？"
D.Strings[4730]="星纹长者在黑海岸洛达内尔附近的海滩上。"
D.Strings[4731]="%s的眼睛有些发红。"
D.Strings[4732]="夜风长者在哪里？"
D.Strings[4733]="夜风长者最近在费伍德森林的加德纳尔神殿里。"
D.Strings[4734]="水歌长者在哪里？"
D.Strings[4735]="水歌长者目前住在灰谷的阿斯特兰纳。"
D.Strings[4736]="石塔长者在哪里？"
D.Strings[4737]="石塔长者眼下应该是在冬泉谷的永望镇。"
D.Strings[4738]="金矛长者在哪里？"
D.Strings[4739]="金矛长者在冬泉谷的凯斯利尔废墟到处游荡。"
D.Strings[4740]="血蹄长者在哪里？"
D.Strings[4741]="血蹄长者在莫高雷的血蹄村里。"
D.Strings[4742]="风之图腾长者在哪里？"
D.Strings[4743]="风之图腾长者在贫瘠之地的棘齿城和地精为伴。"
D.Strings[4744]="高山长者在哪里？"
D.Strings[4745]="高山长者在南贫瘠之地的世仇哨站。"
D.Strings[4746]="月卫长者在哪里？"
D.Strings[4747]="月卫长者在守望北贫瘠之地的十字路口。"
D.Strings[4748]="麦蹄长者在哪里？"
D.Strings[4749]="麦蹄长者正在莫高雷的雷霆崖欣赏那里的风光。"
D.Strings[4750]="暗角长者在哪里？"
D.Strings[4751]="暗角长者在遍布红色巨岩的奥格瑞玛城中。"
D.Strings[4752]="晨露长者在哪里？"
D.Strings[4753]="晨露长者在千针石林监视菲兹尔和普兹克赛艇平台上的骚乱。"
D.Strings[4754]="符文图腾长者在哪里？"
D.Strings[4755]="符文图腾长者应该是往杜隆塔尔的剃刀岭去了。"
D.Strings[4756]="恐怖图腾长者在哪里？"
D.Strings[4757]="恐怖图腾长者在菲拉斯的拉瑞斯小厅那里。"
D.Strings[4758]="迷雾行者长者在哪里？"
D.Strings[4759]="迷雾行者长者在菲拉斯的厄运之槌竞技场观看角斗。"
D.Strings[4760]="星眼长者在哪里？"
D.Strings[4761]="星眼长者在千针石林的乱风岗。"
D.Strings[4762]="碎石长者在哪里？"
D.Strings[4763]="碎石长者到凄凉之地的玛拉顿去了。"
D.Strings[4764]="梦言长者在哪里？"
D.Strings[4765]="梦言长者在塔纳利斯沙漠的加基森。"
D.Strings[4766]="暴怒图腾长者在哪里？"
D.Strings[4767]="暴怒图腾长者在塔纳利斯沙漠的守卫之谷打发时间。"
D.Strings[4768]="蛮鬃长者在哪里？"
D.Strings[4769]="蛮鬃长者的家在塔纳里斯沙漠的祖尔法拉克。"
D.Strings[4770]="雷角长者在哪里？"
D.Strings[4771]="雷角长者到安戈洛环形山的巨痕谷去了，天知道他要干什么。"
D.Strings[4772]="刃歌长者在哪里？"
D.Strings[4773]="刃歌长者就在希利苏斯的塞纳里奥要塞。"
D.Strings[4774]="棱石长者在哪里？"
D.Strings[4775]="棱石长者在希利苏斯的水晶谷生活了许多年。"
D.Strings[4776]="尊重你的长辈同样也是尊重你的文化与人民，$c。而先祖硬币则是对遵循这样一条古老礼仪之道的人的赞许。$B$B在春节期间，你可以拜访许多长者，对他们表达你的尊敬。如果你这样做了，你将会得到先祖硬币。将这些硬币带回来，我会因你的勤奋而允许你从一些特殊的物品中选择一个作为奖励。"
D.Strings[4777]="我想要获得一份新的春节邀请函。"
D.Strings[4778]="你好，$n。我们从月光林地来这里，要将新年的喜悦传播到世界的各个角落。$B$B你难道不想与我们一起庆祝新年吗？"
D.Strings[4779]="我们奉命消灭拉贾克斯。你可以使用任何手段来达到这一目的。"
D.Strings[4780]="我们和联盟并肩作战，共同进退，$r。一个古老的邪恶力量正在准备将我们全部吞噬，首先是卡利姆多，然后是整个艾泽拉斯。这股邪恶是如此地古老，我们都已经忘记了它的存在。驱动它的力量的源泉，乃是对于造物之神泰坦以及一切由泰坦创造的事物的仇恨。$B$B我们是唯一能阻挡克苏恩的力量。我们要先发制人，击溃安其拉的虫人。让艾泽拉斯在部落和联盟的力量面前震撼吧。$B$B战备工作需要你的帮助！"
D.Strings[4781]="幽林长者在哪里？"
D.Strings[4782]="幽林长者在西瘟疫之地的哭泣之洞外面。"
D.Strings[4783]="星林长者在哪里？"
D.Strings[4784]="星林长者在荆棘谷的祖尔格拉布大门外面。"
D.Strings[4785]="“在为战争采集资源这方面，你做得太棒了！”他们说，“你一定会得到晋升的！”然而他们真正的意思是，“你会和一群小不点的矮人一起被部署在希利苏斯的某个虫巢外面，卡恩斯！”$B$B多谢提携，中尉！"
D.Strings[4786]="我，就像我的哥哥一样，以那些尊重祖先的人为荣。对我来说，与欢度春节的人们一起分享我的秘密手艺是极大的快乐。"
D.Strings[4787]="就像其他人一样，我在开战初期就来帮助我的德鲁伊同胞。$B$B现在安其拉的大门已经打开，但我意识到许多工作还没有完成。因此我决定留在希利苏斯，尽我所能地帮助他们，$n。"
D.Strings[4788]="异种虫看起来已经够可怕的了，可是和它们的其拉主人比起来，它们可以算是温顺的了。"
D.Strings[4789]="这场战争还没有结束，它才刚刚开始！勇敢的士兵日日夜夜在安其拉与敌人血战，很快，这座其拉虫人的城市就要陷落了。"
D.Strings[4790]="目前我们对其拉战争的节节胜利可以说是全卡利姆多大陆各个种族共同努力的结果。$B$B但除了士兵之外，我们还需要更多的东西来支撑这场战争，$n。许多商贩和工匠其实都是这场战争中的无名英雄，正是他们一直源源不断地将物资送到前线。"
D.Strings[4791]="他们真能想，居然在月光林地搞聚会，真棒！"
D.Strings[4792]="试试这些烟花发射器，非常棒！"
D.Strings[4793]="这道月光会把你送到暴风城去。当你想要离开庆典的时候，就在这里使用你的邀请函。"
D.Strings[4794]="别想要传送到你的敌人的城市去……那根本不可能。我们可能在这里是朋友，但出了月光林地就不好说了……"
D.Strings[4795]="永夜港的人们真有点子！"
D.Strings[4796]="这些烟花真华丽，你不这么认为吗？"
D.Strings[4797]="这道月光会把你送到铁炉堡去。但你难道真的想要离开吗？"
D.Strings[4798]="今年的庆典太棒了！"
D.Strings[4799]="有人说这些烟花带着月神的力量！"
D.Strings[4800]="这道月光会把你送到达纳苏斯去。"
D.Strings[4801]="换了别人，也许会以为这次庆典是兽人举办的呢！"
D.Strings[4802]="看到了吗？刚才的烟花差点把那个矮人的衣服给点着！哈哈哈！"
D.Strings[4803]="这道月光会把你送到奥格瑞玛去。当你想要离开庆典的时候，就在这里使用你的邀请函。"
D.Strings[4804]="没什么能比新年的庆典更让人高兴了！"
D.Strings[4805]="点烟花的时候要多加小心，手指头是很宝贵的……"
D.Strings[4806]="这道月光会把你送到幽暗城去。当你想要离开的时候，就到这里来吧。"
D.Strings[4807]="我爱春节！这是个让你的蹄子跳起舞来的日子！"
D.Strings[4808]="我不知道这些烟花的工作原理，但它们真的很漂亮！"
D.Strings[4809]="这道月光会把你送到雷霆崖去。当你想要离开庆典的时候，就到这里来吧。"
D.Strings[4810]="年兽沉睡在月神湖底的深处，但你可以在湖东南岸，也就是靠近怒风兽穴的地方召唤它。你可以在那里找到特殊的烟花束发射器……$B$B在发射器那里使用你的烟花，年兽的爪牙就会出现。发射更多的烟花，大约三十组，或者朝它的爪牙投掷艾露恩的蜡烛，年兽就会醒来。"
D.Strings[4811]="%s变成了坚硬的固体！"
D.Strings[4812]="多年来我们为了保护我们的领土艰苦地战斗着，期盼恢复它往日的荣耀，$c。无论什么时候，我们都会继续警惕着那些侵略和污染奎尔萨拉斯的家伙。我们不会休息，直到他们被彻底赶出我们的视野。$B$B辛多雷是不可战胜的！"
D.Strings[4813]="一切都糟透了，$c，这一切都是我的错！当时间还不算晚的时候，我被告知最好立即离开码头，但是我听了吗？没有。$B$B现在我要干什么？那些病态的失心者偷走了我的魔法货物，我想他们已经把这些东西都吃了。我很确信这意味着它们再也没法拿回来了。而暗鳞鱼人在一个死寂的夜晚抢夺了我剩余的货物！另外，对于我这样正直的商人来说，雪上加霜的事情是，我的船员都逃走了！$B$B我真是欲哭无泪。"
D.Strings[4814]="你好，$c。现在是最艰难的时刻，我们心爱的奎尔萨拉斯居然变成了这个样子。"
D.Strings[4815]="$n，失心者是非常棘手的麻烦。在他们通过汲取不稳定的奥术能量满足自己对魔法的渴求、解决了嗜魔之瘾后，他们便开始挖空心思地计划对我们发动攻击，不过这帮渣滓的作战方案还真是……"
D.Strings[4816]="谢天谢地……现在没有人会重复我的错误了！"
D.Strings[4817]="我希望罗拉塔利斯是对的，$c。也许我应该亲自去达斯维瑟之塔？也许我当初就应该立即赶去那里？"
D.Strings[4818]="$c，一个人在纠正了他所犯下的错误之前只能生活在羞耻中。"
D.Strings[4819]="混乱，一片混乱！这些生物满地都是，失控地跑来跑去！还有魔导师和他的学徒们都去哪里了，逃走了？把我单独留在这里，甚至连一句“你好啊维林森，你愿意一起走吗？”都没留下。$B$B胆小鬼！"
D.Strings[4820]="你的这些奥术圣殿真的……很有意思，凯丹尼斯先生。我对你今天给予我的信息表示感激。"
D.Strings[4821]="城墙被攻陷了！"
D.Strings[4822]="真是一场恶战。让我们休息一下……"
D.Strings[4823]="嘿，$g先生:小姐;。看上去你是个对酒很有品位的$C。我需要你帮一个忙，我也会出一个你绝对无法拒绝的价格……还是算了吧。"
D.Strings[4824]="你在看什么，$g伙计:小姑娘;？没见过矮人吗？$B$B如果你不想惹麻烦的话，那么你最好走开。"
D.Strings[4825]="我需要占用一点你的时间，先生。"
D.Strings[4826]="啊，你肯定是那个被派来带我参观永歌森林的$g小伙子:小姑娘;。到这里来花了你不少时间吧？$B$B很好，出发吧。我们不要再浪费时间了。"
D.Strings[4827]="啊……是的，当然。不过首先我在这间房子里准备了一些东西要让你看看，安威瓦尔德先生。"
D.Strings[4828]="好吧。让我们看看你说的是什么，$n。"
D.Strings[4829]="这是什么诡计，$r？如果你想要偷袭我的话，就来试试看吧！"
D.Strings[4830]="战争压得我们喘不过气来，让我们忘了给爱情一点空间。"
D.Strings[4831]="我一看就知道，你已经找到了自己的真爱。你可以给我一件爱情信物，但我没什么可以给你的。我正在等待一个特殊的人……"
D.Strings[4832]="我不知道自己是怎么了，我的心就像新铸成的钢条一样炽热！"
D.Strings[4833]="你和机器共处的时间太久了，久到让你忘了真正的爱情。"
D.Strings[4834]="如果你像我一样活了这么久的话，就会很容易把爱情的感觉遗忘。有人提起这种感觉来总是好事情。"
D.Strings[4835]="我们兽人通常不喜欢过多谈论自己的感情问题，但今天可不是遮遮掩掩的时候。"
D.Strings[4836]="我要输入神秘兑换码，领取我的小鱼人宠物！"
D.Strings[4837]="虽然这不是我的心，但它同样会破碎。"
D.Strings[4838]="拉文霍德庄园欢迎你的光临，冒险者。"
D.Strings[4839]="你看起来好像伤心欲绝。等你心情好一点之后再回来吧。"
D.Strings[4840]="如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？"
D.Strings[4841]="如果你能洒些香水的话，我会更喜欢你的。"
D.Strings[4842]="什么？你没有可以给我的纪念品？你不爱我了？"
D.Strings[4843]="什么？！你是怎么跑进这里的……哦，外面带了伴当？好吧，我就算你没有恶意好了。今年我的销售势头似乎不行呀。$B$B你看你要我这里的什么货吧，$c？"
D.Strings[4844]="我的任务就是竞争。我这里还有些剩余补给，不知你是否需要。"
D.Strings[4845]="没有啊，不过许多其他人都在寻找爱情。你应该从我这里买些爱情信物，洒上一些香水，然后勇敢地出击！"
D.Strings[4846]="爱情信物是用来向你中意的某个城中的居民表达爱意的小东西。如果对方也对你感兴趣的话，你就可以收到一份爱情的礼物。$B$B如果你已经和别人相爱了，那么至少对方会给你一份代表友谊的礼物。"
D.Strings[4847]="如果你洒上一些香水，就可以找到对你有好感的人。他们会接受你的爱情信物……并给你一件礼物作为回报。$B$B但是，你要记住：要让别人接受你的爱情信物，你必须闻起来很迷人！男人喜欢香水的味道，而女人会为古龙水陶醉！"
D.Strings[4848]="当你把爱情信物交给城镇里的居民时，你可以收到各种礼物作为回报。一些礼物最好留起来用，另一些则最好放在一起做成一个大礼品包！$B$B去找匹德菲特为你喜欢的英雄投票吧。$B$B你可以在伯瓦尔、麦格尼或者泰兰德身边找到匹德菲特。"
D.Strings[4849]="你想知道谁是人气最高的英雄？目前的排名是这样的！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B瓦里安：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B如果你想参加投票，就拿出你的礼品包吧！"
D.Strings[4850]="嗨！我是匹德菲特！我在这里统计谁是艾泽拉斯最受欢迎、人气最高的英雄！$B$B看到这么多人为他们崇拜的英雄投票，这可真让我高兴，但你知道什么可以让我更高兴吗？$B$B一个吻！"
D.Strings[4851]="最终的排名是！$B$B萨尔：$2200w$B$B凯恩：$2201w$B$B希尔瓦娜斯：$2202w$B$B部落总计：$2207w$B$B$B伯瓦尔：$2203w$B$B麦格尼：$2204w$B$B泰兰德：$2205w$B$B联盟总计：$2206w$B$B联盟的英雄人气最高！"
D.Strings[4852]="哇，你居然进来了，很聪明呀，$n。$B$B什么？我怎么知道你的名字？嘿，朋友，你看我虽小，却也是个恶魔了，这就是我们恶魔的能力。我还知道你的真名呢，所以你最好只买贵的，不买对的。"
D.Strings[4853]="想要买魔杖？或者你只是想要囤积一些符文？$B$B等等！你该不是想把这堆垃圾扔给我吧？！该死，我怎么就控制不了自己的购买欲呢！"
D.Strings[4854]="啥？我才不做盔甲维修的生意呢。永望镇就离这里不到一里地，$g伙计:小姐;。$B$B现在，赶紧买点什么吧，不然我就把我的术士召唤出来，把你给秒了！"
D.Strings[4855]="想看看我出售的货物吗？"
D.Strings[4856]="当你把爱情信物交给城镇里的居民时，你可以收到各种礼物作为回报。一些礼物最好留起来用，另一些则最好放在一起做成一个大礼品包！$B$B去找匹德菲特为你喜欢的英雄投票吧。$B$B你可以在凯恩、希尔瓦娜斯或者萨尔身边找到匹德菲特。"
D.Strings[4857]="这本书的内页已经被毁了。"
D.Strings[4858]="无数的图象、幻影与标记同时出现在你的脑海中。这本书似乎知道你在制皮方面的技术成就一般，并给了你一个选择的机会，但是请注意，你只能选择一次！"
D.Strings[4859]="我不能教你龙鳞制皮，$n。你得前往塔纳利斯寻找纳瑞安的家。那本名叫《傻瓜预言书》的书会对你有所帮助的。"
D.Strings[4860]="请尽量不要引起太多注目，我正在等待议会的召见。我并不介意多等一会儿，这儿到处是身材魁梧的守卫，我感到非常安全。"
D.Strings[4861]="面对危险时我选择了妥协并由此送了命。但是即便是死了，我也无法承受失去伊思达的悲痛。"
D.Strings[4862]="你好，朋友！你对灵质装载器感兴趣吗？或者是看看全向鬼灵同化器？"
D.Strings[4863]="什么事？你没看见我很忙吗？"
D.Strings[4864]="我似乎将提纯器弄丢了，穆克斯。我是不是把它放这儿了？"
D.Strings[4865]="嗨，维尔，让我看看你出售的货物！"
D.Strings[4866]="我感觉好多了，别担心我。我要在这间房间里进行净化仪式，在那之后我自然会设法离开的。这儿被邪恶的魔法力量污染了，$n。"
D.Strings[4867]="蒸汽坦克？"
D.Strings[4868]="我们新近发现，马戏团中随处可见的蒸汽车控制台能操纵这些被称为蒸汽车的迷你坦克，我可是很慷慨地跟你分享这一信息。$B$B你只需激活控制台就行了。每辆坦克都配备了常用的弹药和某种秘密武器，向你的敌人开火吧！$B$B和朋友一起参加史诗般的战斗、巡逻、或者仅仅是进行野蛮的破坏……一切都由你自己选择！"
D.Strings[4869]="大炮？"
D.Strings[4870]="雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去雷霆崖的猎人高地南部找玛克希玛·雷管吧。听说它可以把人发射到石牛湖以南呢！"
D.Strings[4871]="听说克尔苏加德正在研究传说中的埃提耶什，守护者的传说之杖。$B$B是的，就是那件曾属于麦迪文的神奇法杖。"
D.Strings[4872]="当面对那些妄图危害这个世界的邪恶势力时，我们圣光兄弟会可远没有其他同胞那样和善。"
D.Strings[4873]="巫妖王正试图要将他的存在传达给整个世界，让这个世界陷入恐慌与噩梦之中。绝对不能让这一切发生。"
D.Strings[4874]="什么是圣光兄弟会？好吧……从本质上说，我们都是银色北伐军的核心成员——一群不受道德、内疚这类毫无用处的人类感情所限制的人。"
D.Strings[4875]="我的头衔可能有会让人误解我。与我相处久了，你就会知道我其实是一个很好相处的人。"
D.Strings[4876]="他们差点把我的兄弟洛克希给派来了。他连自己的狗都照顾不了，还是让那些能够展现血色十字军实力的人来这里吧。"
D.Strings[4877]="我一直在等……$B$B<雷布拉特干咳了几声。>$B$B抱歉，老毛病了。我是大地之环的雷布拉特。"
D.Strings[4878]="你好，$c。请尽量别引起太多注意。"
D.Strings[4879]="你想干什么，小松鼠？赶快从我眼前消失，不然你就有机会搞明白为什么他们叫我愤怒者了。"
D.Strings[4880]="你要战？便来战！"
D.Strings[4881]="我要把你彻底打败！"
D.Strings[4882]="我厌恶你这样的懦夫！放马过来吧！"
D.Strings[4883]="世上第一套无畏护甲是专为血色十字军领袖莫格莱尼设计并锻造的。当穿上全套的无畏护甲之后，这位大领主看上去就像是一位来自扭曲虚空的恶魔。$B$B哎……我至尽还忘不了那时的情景，莫格莱尼高举着灰烬使者，在成百上千的天灾军团士兵中穿入穿出，燃烧着敌人与自己的生命，带起一阵阵烈炎与烟尘，身后留下敌人被烧成灰烬的尸骸。"
D.Strings[4884]="在他不幸运遇难之后，全洛丹伦的骑士与战士都开始穿着相同式样的铠甲，以纪念这位倒下的英雄。尽管莫格莱尼的死可以算是克尔苏加德的一场大胜，但英雄之死的影响，却改变了整个战争最终的走势。$B$B一个人倒下了，但更多的人站了出来，为反抗天灾军团的入侵而战……"
D.Strings[4885]="我就是你所说的财主，$R。"
D.Strings[4886]="你好……嗯，你叫什么？$B$B没关系，你来这个小村庄做什么？这个美丽的地方是我的第二故乡。"
D.Strings[4887]="你好，$c。我希望你玩的很高兴，你觉得聚会怎么样？我希望我们的食水都还有剩余。没有什么比吃喝全部耗尽更让人扫兴的了，你说呢？$B$B啊，好吧。我必须去照顾一下我的其他客人了。玩得开心点。"
D.Strings[4888]="你好，尊敬的$g先生:女士;。我相信你一定过得很愉快？"
D.Strings[4889]="这不是很有趣吗？我很高兴萨瑟利尔男爵每晚都举办这样的聚会，特别在南部发生着些令人不愉快的事情时，聚会可以让我们忘记那一切，你觉得呢？"
D.Strings[4890]="什么？啊呀，又来了！"
D.Strings[4891]="你不能这样对我！我们事先说好了的！"
D.Strings[4892]="埃提耶什是什么？"
D.Strings[4893]="与克尔苏加德一样，我也是一个来自肯瑞托议会的法师，更相似的是，我与他都在寻找着埃提耶什，守护者的传说之杖。我们的命运似乎就这样交织在一起了，$c。"
D.Strings[4894]="艾格文的唯一子嗣，最后一任提瑞斯法的守护者……麦迪文。"
D.Strings[4895]="有关他的传说，我想我没有时间也没有兴趣重述一遍给你听。你只要知道麦迪文是最后一位守护者。而埃提耶什这把传说中的法杖，既是他力量的焦点，也是腐蚀的焦点。"
D.Strings[4896]="什么腐蚀？"
D.Strings[4897]="一位堕落泰坦的腐蚀。毁灭者的腐蚀。总之，这根法杖发源于仇恨的种子。当然，这也是我来到这里的原因……"
D.Strings[4898]="在卡拉赞陷落之后，肯瑞托议会派遣了一队法师搜索了整座塔，收集到了所有重要的东西……目的？或许是研究吧。总之不知道是否真的，据说这根法杖被带到了达拉然。"
D.Strings[4899]="请继续说下去。"
D.Strings[4900]="接着，达拉然那边发生了一系列不幸的事件，所有碰过埃提耶什——甚至是仅仅做过与之相关工作的肯瑞托法师都离奇地死亡了。$B$B你看，它似乎是一种有感知的神器，这感知能力想必是萨格拉斯所授予的……"
D.Strings[4901]="<安吉拉点了点头。>$B$B在他们死后，六人议会做出了决定。他们认为对这根法杖最好的处理方法无非是用牢固的魔力监牢封印起来，并委任一名看守者……原本应该是我。"
D.Strings[4902]="这确实挺可怕的，请继续。"
D.Strings[4903]="后来也没什么可说的了。达拉然几乎完全被阿克蒙德摧毁，法杖也遗失了。据说，在那时，禁锢法阵启动了某种保护机制，将法杖击碎了。$B$B也有人说，禁锢了这根法杖是导致阿克蒙德毁灭达拉然的原因，是他为萨格拉斯所做的复仇。"
D.Strings[4904]="请再多告诉我一些。"
D.Strings[4905]="在达拉然沦陷以后，我离开了肯瑞托议会，用了好几年的时间来搜寻埃提耶什的下落，只是为了履行我在肯瑞托未尽的责任。我会找到这根法杖，即使这要用去我一生的时间。这也是我加入银色黎明并站在这里的原因。"
D.Strings[4906]="还有别的什么吗？"
D.Strings[4907]="最近几年来，我一直在世界各地搜寻着法杖碎片的下落，并且发现克尔苏加德正试图重铸它。他已经收集到了其中的几块碎片，并交给几位深得他信赖的军官保存着。$B$B我无法再用什么语言来强调从克尔苏加德手中抢回法杖的重要性了。坦诚地讲，如果让他拿到了完整的法杖，我不知道这个世界除了被灾难彻底淹没之外还能有什么其它结局。"
D.Strings[4908]="那就是力量的化身，你这白痴。$B$B<玛塔乌斯的眼神变得黑暗了。>$B$B这帮白痴把你这样更白的白痴送进纳克萨玛斯里去回收那些被亵渎的护甲碎片，然后净化，重新附魔，来恢复以前的荣光。$B$B<玛塔乌斯不屑地吐了一下口水。>$B$B光是想到这群超级白痴就能让我感到不舒服。$B$B我也在寻找这些护甲碎片，不过我会把它进一步加工成为最邪恶的形态。"
D.Strings[4909]="那又怎样，白痴。这些蕴涵着黑暗力量的物品或许能把我们全都毁灭掉。这是我们在获取力量时所必须付出的代价。如果我必须要死，那也要死在这样伟大的仪式与实验中。$B$B至于你……如果你在为我完成这一切的过程中死了……那我就会以豺狼人的方式嘲笑你的孱弱。把我要的东西带回来，这样我们两个都能获利益，要么就去死吧，我已经解释过结果了……"
D.Strings[4910]="您好，旅行者。我奉命在此接待主人的贵客，所有携带着卡拉赞钥匙的人都会被奉为上宾。如果您有什么疑问，请尽管开口。有什么需要我帮忙的吗？"
D.Strings[4911]="我们对那些失心者太仁慈了，要我说，我们应该拔出剑刺向他们。$B$B他们在阳帆港的大胆行径是不可饶恕的。"
D.Strings[4912]="消灭在死亡之痕徘徊的愚蠢的天灾士兵，这可真是个单调的工作。我希望你能在这里助我们一臂之力，而不是把我的时间浪费在闲聊中。"
D.Strings[4913]="啊，主人的贵客。希望您在这里没有到处乱走。"
D.Strings[4914]="这些该死的歹徒！我能指望你助我一臂之力吗？"
D.Strings[4915]="我不能教牛头人骑乘迅猛龙。"
D.Strings[4916]="我在哪里才能找到地穴恶魔的碎块，雷奥普德？"
D.Strings[4917]="这些污秽的野兽爬满了四处。$B$B如果你喜欢户外狩猎的话，你可以轻松地在病木林和恐惧谷找到它们的，恶蛛隧道里也有大量生存。当然，任何东瘟疫之地的天灾营地里也都会有它们的身影。$B$B此外，如果你真是一个特别优秀的地下城冒险专家的话，你还能在斯坦索姆找到一些，而通灵学院里也有一些通灵魔。"
D.Strings[4918]="我在哪里才能找到白骨碎片？"
D.Strings[4919]="你傻了吗？你一路上竟然没有看到任何邪恶的玩意？$B$B<洛汉叹了一口气。>$B$B如果在户外的话，你很容易就能在东西瘟疫之地发现各类骷髅生物。相信我，你一定不会错过它们的，当然，它们要是看见了你，也不会错过你……$B$B如果你喜欢地下城，那就去斯坦索姆或者通灵学院，那里也能拿到白骨碎片。"
D.Strings[4920]="又是一个在塔奎林度过的可爱的、阴暗的日子，你不觉得吗，$c？$B$B我能为你做些什么？"
D.Strings[4921]="没有什么比在天空中翱翔更自由的了，$c。我能为你做些什么吗？"
D.Strings[4922]="你好，朋友。今天有什么我可以为你效劳的吗？"
D.Strings[4923]="是要去塔奎林，还是有什么其它事情我可以帮忙的？"
D.Strings[4924]="是的，我要飞去幽魂之地。"
D.Strings[4925]="我在哪里才能找到元素之核？"
D.Strings[4926]="啊，这个问题问得好。$B$B如果你喜欢在户外狩猎，那么在瘟疫之地，艾萨拉，燃烧平原，费伍德，希利苏斯，冬泉谷，甚至是安戈洛环形山都有元素生物的存在。$B$B如果你更喜欢直接挑战危险，那么就去厄运之槌吧。我听说大量变异元素都躲在厄运之槌的高墙之后。当然，你也可以在黑石深渊那里找到大量被黑铁矮人所雇佣的元素生物。"
D.Strings[4927]="科尔法克斯，我在哪里才能找到黑铁碎片？"
D.Strings[4928]="能问些不这么愚蠢的问题吗？你真不知道吗？$B$B要是你胆子小，怕死的话，就去燃烧平原和灼热峡谷的生物身上去找黑铁碎片。$B$B要是你够狠够胆大，干脆杀进黑石塔和黑石深渊算了，那里的黑铁碎片更多。"
D.Strings[4929]="莱茵，我在哪里才能找到蛮荒之叶？"
D.Strings[4930]="如果你喜欢在户外狩猎的话，那么无论是费伍德的树人还是环形山的鞭笞者都是不错的目标，可以提供大量的叶子。$B$B如果你更喜欢冒险，那么厄运之槌东西两翼内都有大量的植物，可以供应足够的叶子。"
D.Strings[4931]="$C，瞧瞧他们把我们的家园搞成了什么样子。我们必须消灭天灾军团！"
D.Strings[4932]="这可能比较麻烦，但是我想我们能够拯救这个血精灵的生命。"
D.Strings[4933]="你是谁？我感觉……好……冷。"
D.Strings[4934]="真让人感到羞耻，我们辛多雷在这个曾经被我们称为家的地方失去了很多东西。很快，我们就将重新获得力量，并把我们南方的领土从天灾手里夺回来。"
D.Strings[4935]="我太忙了，根本没有时间来陪你玩什么游戏， $r。有事就说，没事就从我眼前消失！"
D.Strings[4936]="高级执行官和奥莉菲洛丝夫人要我在一旁候着，我可没那么多时间！我的朋友已经奄奄一息了，$C！"
D.Strings[4937]="我在几天前派了游侠萨尔莉莎去南面的营地，派游侠莱瑟瓦林去了西面的塔奎林！你遇到过他们两个吗？你是不是他们派回来的援兵？"
D.Strings[4938]="有时我会觉得，我永远也不能再像以前那样单纯地为奥莉菲洛丝夫人服务了。战争完全扰乱了我的生活。$B$B好在还有你这样的人物，致力于使奎尔萨拉斯恢复它原有的平静。消灭亡灵天灾，$C！竭尽全力消灭他们！"
D.Strings[4939]="瞧，当世的英雄！很高兴再次见到你，$n！一旦发现天灾士兵，你是绝不会手下留情的，对吗？"
D.Strings[4940]="我得到消息说你帮助了游侠瓦兰娜和派往塞布索雷的上尉。$B$B感谢你，$c。我想我现在应该回远行者营地了。"
D.Strings[4941]="什么风把你吹到这里来的，$c？"
D.Strings[4942]="啊，你好啊，$r。就像你所看到的那样，我还没开张。对不起，我现在很忙。"
D.Strings[4943]="很高兴再次看到你，$c。不，真的，你是我能在这里发大财的原因。$B$B现在，有什么我可以出售给你的吗？"
D.Strings[4944]="欢迎来到塔奎林，$c。我对你所看到的状况感到抱歉。就像你所看到的那样，我们有一些麻烦，但是遗忘者和他们的女王希尔瓦娜斯·风行者在我们需要的时候高尚地给了我们大量的帮助。$B$B如果你能帮忙的话，请不要犹豫不决。我们需要所有可以借助的力量。"
D.Strings[4945]="部落与联盟远征诺森德，抵御巫妖王的入侵的时刻已经降临。这些日子依赖，卡利姆多和东部王国都遭到了攻击。你愿意拿起武器，保卫自己的家园吗？"
D.Strings[4946]="剑而已，不用害怕。要小心羊肉才是真的！"
D.Strings[4947]="太可怕了，这些骡子到底怎么了……要是这样下去，梅兹会把我剥了皮的。"
D.Strings[4948]="你对暗夜精灵们采取的行动让我们感到非常高兴。你揭开了他们利用魔网能量线的阴谋，以及他们使用所谓的月亮水晶来监视我们的计划。这些都坚实地巩固了我们在这里的地位。$B$B我们非常感谢你，$n。"
D.Strings[4949]="你是来增援的吗？"
D.Strings[4950]="你破坏了安欧维恩的月亮水晶，干得很好，$C！如果你对我的研究工作感兴趣的话，可以随时来找我。"
D.Strings[4951]="这种环境让我怎么做事？！这地方到处都是恶心的被遗忘者！我真为塔奎林和奎尔萨拉斯感到悲哀！"
D.Strings[4952]="$R，快说！你带来了什么重要的消息？快点去做你该做的事情……奥莉菲洛丝夫人和我正在进行一次战略讨论。"
D.Strings[4953]="欢迎来到圣光之愿礼拜堂，陌生人。"
D.Strings[4954]="我们的大篷车队会往前线运送物资，每天两次。要是不能帮助负责运送的迪迪尔和他的骡子清理掉路上骚扰的天灾士兵的话，我就得挨罚了。那可是我所见过的最疯狂的事。看来我们得像英雄那样冒险保护货物了。"
D.Strings[4955]="太痛苦了……我……我渴望更多……"
D.Strings[4956]="多点，再多点！我必须马上吃点什么。"
D.Strings[4957]="我不能忍受这痛苦了。我必须找到新的魔法源。"
D.Strings[4958]="事情太多，时间太少，$r！拜托，别挡我的道。"
D.Strings[4959]="事情太多，时间太少，$r！拜托，别挡我的道。$B$B但如果你中了蛆毒或食尸鬼疫病的话，我可以帮助你。"
D.Strings[4960]="%s被猛烈的电击复活了！"
D.Strings[4961]="%s的连接中断了。"
D.Strings[4962]="不要感到诧异，$n，请过来。我有东西需要你帮我处理下。"
D.Strings[4963]="<在你把药膏倒入血精灵口中后，他很快恢复了知觉。>$B$B谢谢你救了我的命，$c。没有你的帮助，我早就在天灾的折磨下屈服了。"
D.Strings[4964]="<给病人使用疗伤药膏。>"
D.Strings[4965]="<血精灵慵懒地躺在桌子上。>"
D.Strings[4966]="你好，$R。我是辛多雷——也就是血精灵一族的大使欧诺·炎伤。我忠心希望我们与部落新建立起来的友好关系对双方都有好处。"
D.Strings[4967]="现在你可以走了。出去的路很安全。"
D.Strings[4968]="<这个女遗忘者痛苦地蜷曲在地上。她看上去已经不能自己爬起来了。>"
D.Strings[4969]="啊啊啊……头痛欲裂！$B$B肯定是他们派你来救我的。拖了太久了！你知道他们都对这里的战俘做了些什么吗？"
D.Strings[4970]="有点不舒服？出去的路很安全，快点跑吧！"
D.Strings[4971]="<虚弱的血精灵躺在桌上。>他气若游丝，似乎毒药已经发作了。"
D.Strings[4972]="你好，$R。我是代表高级执行官来传达忠告的。我相信只要我们联起手来，部落必将变得更加强大，一举击溃亡灵天灾！"
D.Strings[4973]="<瓦尼斯剧烈地咳嗽起来，看来治疗药膏生效了。>$B$B谢谢你救了我一命。我必须立即返回塔奎林！"
D.Strings[4974]="从永歌森林时不时吹来的新鲜空气让我的胃感觉很不舒服，如果你知道我是什么意思的话。"
D.Strings[4975]="我想要一份你的疗伤药膏的样本，药剂师。"
D.Strings[4976]="如果你有非常重要的事情汇报，最好去找奥莉菲洛丝夫人谈谈。我提醒你，她非常繁忙，恐怕你得等上一会儿。"
D.Strings[4977]="通常来说我是不会和你直接谈话的，你应该直接去找夫人。不管怎样，既然我直接给你下达了命令，那么我们需要讨论的事情是……？"
D.Strings[4978]="$c，奥莉菲洛丝夫人向我转达了她对你的欣赏之情。她想告诉你，她希望你能继续作为一个辛多雷的勇士，在幽魂之地奋战。"
D.Strings[4979]="%s超载了！"
D.Strings[4980]="我们有重要的工作要做，$n。让我们在敌人疏于防守的时候进攻他们吧。告诉他们辛多雷永远都不会忘记复仇，永远不会宽恕敌人。"
D.Strings[4981]="战争之潮再度降临。巫妖王的浮空城正在从北方向我们的陆地一路侵袭而来。他的浮空要塞正在进犯世界各地。"
D.Strings[4982]="这可真麻烦！如果那些豺狼人垃圾在矿井里到处跑，我该怎么才能帮魔导师收集到矿石样本呢？"
D.Strings[4983]="她会在哪里呢？我派了我的学徒沙塔瑞亚到西面的幽光矿洞去，已经有段时间了。我需要拿回那些矿石样本，越快越好，否则我们的实验就要失败了。"
D.Strings[4984]="如果你没有及时把那些幽光矿石送回来的话，我们的研究可能已经失败了。$B$B现在就等沙塔瑞亚再次出现了。我有一些有趣的任务要交给她，我想你肯定也会有兴趣。"
D.Strings[4985]="辛多雷在过去的日子里失去了太多。我们的领土，我们的家园，甚至我们的自我……$B$B是时候把一切都夺回来了。"
D.Strings[4986]="要打败亡灵天灾和阿曼尼巨魔这样的外敌，首先必须解决我们内部的纷争。长期以来，失心者都在不断骚扰滋事，现在是消灭他们的时候了。"
D.Strings[4987]="$n，我们从右边的前厅走。"
D.Strings[4988]="我能看到通道那头的亮光了！"
D.Strings[4989]="那里就是远行者营地了，$c。就在前面……小心！有埋伏！"
D.Strings[4990]="赫里奥斯中尉，我从阿曼尼墓穴逃出来了。报告，长官！"
D.Strings[4991]="感谢你救了我的命，并把我带回安全的地方，$n！"
D.Strings[4992]="莉拉恩萨，找个人来看看这些伤口。谢谢你把她安全地带了回来。"
D.Strings[4993]="你觉得你能帮我离开这里吗？"
D.Strings[4994]="在各种由羊皮纸拼凑起来的名单和其它信息之中，有一条特别醒目。这是一个丑恶的巨魔的画像，也许是你曾经看到过的最可怕的生物！"
D.Strings[4995]="事实上，冬泉谷北部的丘陵地区正在遭到新一批天灾军团士兵的攻击。你的援手将给予我们很大的帮助。$B$B剩余浮空要塞数量：$2284W"
D.Strings[4996]="目前，这片土地还没有受到天灾军团的影响。我担心他们杀回来只是个时间问题。"
D.Strings[4997]="如果增援部队没法快些赶到燃烧平原的话，我怕天灾军团会在这里建立一个行动基地。要是可以的话，你应该去那里帮助防御。$B$B剩余浮空要塞数量：$2281W"
D.Strings[4998]="了解你的敌人可以给你带来更多的优势。请牢记在心，$n。$B$B更多地了解天灾可以让我们有更好的准备，这样才能打败他们。"
D.Strings[4999]="天灾军团在这边建立起了一处据点，用于与天上的浮空城联络并接受支援。根据我们所知的情报，唯一根除的他们的办法就只有杀死据点附近的所有地面部队。"
D.Strings[5000]="只要你喜欢，你在远行者营地待多久都可以，$c。我们欢迎任何愿意尽全力在幽暗之地帮助我们的人。"
D.Strings[5001]="堕落的奥术能量可以对大地、元素甚至是死者的灵魂都产生奇怪的影响。"
D.Strings[5002]="高级执行官公务繁忙，$C。或者我能帮得上你的忙？"
D.Strings[5003]="你为我们做的一切都堪称是榜样，$n。在解决了幽光矿洞的豺狼人和阿曼尼墓穴的那些木乃伊巨魔后，你已经对我们的敌人进行了强有力的打击。$B$B$G干得好！:我们应该找个时间一起喝上几杯，你觉得呢？;"
D.Strings[5004]="很高兴再次看到你，和你在一起工作很开心。"
D.Strings[5005]="人们对你将项链归还给希尔瓦娜斯女王一事议论纷纷。我坚持认为你做了件好事，不要担心女王会对此做何反应。$B$B去做你自己的事好了。"
D.Strings[5006]="我能说什么，$C？你是个真正的英雄！你不仅挽救了很多游侠的性命，还狠狠地打击了暗松巨魔的嚣张气焰。你确定你不想留下来，在我手下做一名远行者？$B$B再见，$n。"
D.Strings[5007]="你给予了暗松巨魔巨大的打击，$C。请继续保持，这样我们或许就能抽出时间来对付亡灵天灾。"
D.Strings[5008]="你对暗松巨魔们造成了决定性的打击，$n。我只希望我们可以尽快聚集力量，在他们得到祖阿曼的增援前解决掉他们。$B$B要是塔奎林能帮助我们就更好了。"
D.Strings[5009]="谢谢你，我永远都不会再离开银松森林了。"
D.Strings[5010]="谢谢你！"
D.Strings[5011]="谢……谢谢你。我原以为我会死的。"
D.Strings[5012]="死亡就是你为这种傲慢付出的代价！"
D.Strings[5013]="米兰达，你能告诉我，在其它声望级别的情况下，你所提供的物品需要多少徽记吗？"
D.Strings[5014]="当然，$n。你只需要先告诉我你想知道关于哪个声望等级的信息。"
D.Strings[5015]="当然，$n。$B$B在银色黎明组织中拥有尊敬级别声望的冒险者需要上缴40个徽记以获得优秀品质的物品。若想获得更加强大的物品，他们需要上缴150个徽记。$B$B我承认，这个价格即便是对尊敬级别的冒险者来说，也确实有些高了。"
D.Strings[5016]="奥术师范迪瑞尔，被遗忘者在这儿做什么？"
D.Strings[5017]="当然，$n。$B$B在银色黎明组织中拥有崇敬级别声望的冒险者需要上缴14个徽记以获得优秀品质的物品。若想获得更加强大的物品，他们需要上缴90个徽记。$B$B这个价格对崇敬级别的冒险者来说，可是说是完全合理的！但最强大的物品仍然是高价的。"
D.Strings[5018]="情况比人们想象的要严峻得多。被遗忘者来这里是为了与我们组成同盟，共同对抗亡灵天灾。$B$B相信我，没有他们的帮助，我们将失去幽魂之地，而整个永歌森林也将被亡灵天灾侵占！$B$B但是我们仍然需要你伸出援手，帮我们夺回土地！"
D.Strings[5019]="当然，$n。$B$B在银色黎明组织中拥有崇拜级别声望的冒险者需要上缴12个徽记以获得优秀的物品。若想获得更加强大的物品，他们需要上缴54个徽记。$B$B只有在银色黎明眼中被崇拜的人，才能获得最大的折扣。"
D.Strings[5020]="当然，$n。$B$B在银色黎明组织中拥有友善级别声望的冒险者需要上缴60个徽记以获得优秀的物品。若想获得更加强大的物品，他们需要上缴220个徽记。$B$B对于那些银色黎明尚不眷顾的冒险者来说，这个价格是非常之高的。"
D.Strings[5021]="友善。"
D.Strings[5022]="尊敬。"
D.Strings[5023]="崇敬。"
D.Strings[5024]="崇拜。"
D.Strings[5025]="%s准备吞噬一个僵尸！"
D.Strings[5026]="这些符石保护着永歌森林不被天灾所污染。西面的符石很久以前就失效了，迫使我们焚烧它周围的土地。$B$B我发誓，只要我还活着，我就不会允许剩余的符石失效。"
D.Strings[5027]="嗯，你显然不是到这里来一边喝茶一边聊天的。让我们看看你能帮什么忙吧。"
D.Strings[5028]="有些人认为银色黎明已经是明日黄花。我也持相同的观点，但不是因为天灾军团的威胁已经消除。$b$b不……真正的原因是他们因循守旧的行事风格。他们变得和其努力摆脱的教会越来越像——太过刻板，太过受制于荣耀与秩序。总之，这正是我想要说给巴萨罗梅听的。$b$b当然，这听起来有些过于激进，不过应该会激发一次有意义的辩论。"
D.Strings[5029]="这就是他们的最高水平了吗？$B$B<奥玛里恩大笑起来。>$B$B看来你还没有对抗一个像克尔苏加德这样的怪物的决心呀。别说他本人，你连他的仆人都会打不过的，就像之前那些去白白送命的人一样……$B$B别管我了，让我死吧，活在一个你这样的家伙就能被称作勇士的世界里真是伤心伤肺。"
D.Strings[5030]="告诉我可以飞到哪里去。"
D.Strings[5031]="%s将最后的力量灌注到附近的符石中，成功地激活了它。"
D.Strings[5032]="大工匠奥玛里恩某个晚上消失了。就像是风中的柳絮一样……呼地一声就没了！好吧，现在我就是唯一能够为前线的那帮家伙打造装备的人了。"
D.Strings[5033]="让我看看你的货物，威尔海姆。"
D.Strings[5034]="$n，辛多雷和被遗忘者在幽魂之地的目标是一致的。我们将共同击败亡灵天灾，或许在我们进军外域的过程中，被遗忘者也将成为最有价值的盟友……谁知道呢。"
D.Strings[5035]="<奥玛里恩一边喘息着一边叙述着什么。>$B$B当然，我可以帮助你，亲爱的$g小伙子:姑娘;。这是我死前……最后一个愿望了。请拿走这本手册吧。上面的信息是我三十年来所继承并学习到的全部家学。把它带给我那个傻得可爱的学徒，他或许还傻傻地坐在圣光之愿礼拜堂门口等我回去呢。"
D.Strings[5036]="<塔希斯呻吟着>$B$B或许还有时间……听仔细了，凡人。$B$B我穿越了虚空，我探索了未知的世界……我与一个强大的邪恶存在定下了微妙的协议……$B$B<塔希斯咳出了鲜血。>$B$B你……你是否能相信，即使是艾露恩也不再怜悯我，$r？现在我要死在这里了，要以这种方式……"
D.Strings[5037]="我所犯下的错误……多么可怕的错误……$B$B<塔希斯的声音呜咽了起来。>"
D.Strings[5038]="我是一名上层精灵，$r。虽然这个词语现在已经不能代表什么了，但很久以前，这个世界曾被上层精灵所统治。一万年过去了……"
D.Strings[5039]="我一定会把它找回来的，凡人。埃提耶什……有了它，我就可以重建上层精灵社会。我一定会把它找到的。就算是女王……"
D.Strings[5040]="<塔希斯抓住了你的领子，他显得十分虚弱。就算是这样一个虚弱的人，你仍能从他眼中看见令人难以想象的光芒。>$B$B妄想症？仔细给我听好了，更没有意义的妄想就被我说出来了。这座城堡中拥有我毕生追寻的东西，我已经知道了每一块法杖碎片的确切位置。"
D.Strings[5041]="埃提耶什，守护者的传说之杖。这把法杖是提瑞斯法守护者历代相传之物。但它已被萨格拉斯所污染。它是最后一任守护者的武器，麦迪文的法杖。"
D.Strings[5042]="<塔希斯的眼神亮了起来。>$B$B我曾拥有过它……我曾不顾肯瑞托议会的警告而拥有过它。我拥有过它啊，凡人……那无尽的力量。足以让我为所欲为的力量。虽然它稍纵即逝，但我确实……曾拥有过它，品尝过力量的甘美……"
D.Strings[5043]="<塔希斯的伤势非常严重。>"
D.Strings[5044]="战役进行良好。天灾军团的实力已经被大大削弱了。我相信我们完全能够把他们都赶进海里，这只是时间问题了。我会尽可能地帮助你进行战斗。"
D.Strings[5045]="我们针对天灾军团的第一步战役进行得非常良好。我们已经获得了一些胜利，希望我的协助能让你取得更多的胜利。"
D.Strings[5046]="当紫罗兰城堡陨落时，它丢失了，破碎成了四十二块碎片。"
D.Strings[5047]="克尔苏加德为了重铸这根法杖，投入了令人难以想象的代价。那些碎片当时被弹射到了世界各地，从卡利姆多到南海。我亲自曾有最多持有过其中的二十块，但最终都被克尔苏加德的手下偷走了。这也是我来到此地的原因。"
D.Strings[5048]="你没听明白吗？不，至少在我们在这里谈话时，克尔苏加德还无法重新铸成法杖。克尔苏加德拥有法杖的头，他的手下分别持有着埃提耶什的四十块碎片。可杖尾却被布莱恩·铜须拿走了。他最后一次出现应该是在希利苏斯的沙漠；很显然他是为了尽量躲避克尔苏加德派出的那些残忍的杀手与刺客才这么做的。"
D.Strings[5049]="我们的圣殿正从魔网中吸取着奥术能量，那些能量线贯穿我们的大地，是肉眼无法看到的。$B$B由于太阳之井的毁灭，它们为我们提供了一个稳定而又可靠的能量来源。"
D.Strings[5050]="晴风村仍然存在，这是对我们种族坚韧不屈的精神的证明。我们绝不让步，直到永远地击败天灾军团。"
D.Strings[5051]="让开，你这败狗！就算是里维加兹饶恕了我，不送我上绞刑架，我也感觉我的报应就快要来了。"
D.Strings[5052]="你最好别找麻烦，$n！"
D.Strings[5053]="我能为你做些什么吗，$n？快说，我时间可不多。"
D.Strings[5054]="我能为你做些什么吗？不，等等！你能为我做些什么？"
D.Strings[5055]="%s吞食了周围所有的僵尸！"
D.Strings[5056]="不留俘虏！把这些异教徒都杀光！"
D.Strings[5057]="不留活口！"
D.Strings[5058]="你做得很好，并体现出了极大的忠诚，$n。请允许我向你展示我们的永恒精萃。"
D.Strings[5059]="欢迎回来，$n。你已经在对抗拉格纳罗斯的战争中向我们展示了你的价值，你将永远受到我们的欢迎。"
D.Strings[5060]="看见克尔苏加德倒下，%s转身便逃！"
D.Strings[5061]="达尔坎认为亡灵天灾不费吹灰之力就能击败我们。他错了，$n。"
D.Strings[5062]="没瞧见我正准备跟这位女士讲话吗？哦，好吧，她似乎很忙。$B$B我出售来自本土和异域的葡萄酒。要看看吗？"
D.Strings[5063]="从萨瑟利尔庄园来的订单？显然，萨瑟利尔大人需要一瓶我的美酒。而且，男爵的朋友都能享受特别的折扣。"
D.Strings[5064]="我们已经赢得了$2219W场对天灾军团战役的胜利。要有心理准备，$n！战争还远未结束。"
D.Strings[5065]="如果你有钱，我保证你对我提供的食品和饮料都很满意，每个铜币都物有所值！"
D.Strings[5066]="你拿着的是萨瑟利尔男爵的清单？当然，我可以卖给你一些刚出炉的新鲜美味。"
D.Strings[5067]="我出售各种货物，$c。过来看看吧。"
D.Strings[5068]="订单……真有趣。哦，这是萨瑟利尔男爵的焰火订单吧。他还没付钱呢。你要替他先付清吗，$c？"
D.Strings[5069]="是不是那些亡灵永远都杀不光？好像我们每干掉一个骷髅和食尸鬼，就会有两个补上来。"
D.Strings[5070]="$C，你过来的路上有看到一个信使吗？我们正等着从银月城传来的消息，但他们的信使迟迟未到！"
D.Strings[5071]="有时候我站在这里，看着河对岸的森林，我仿佛看到了这片土地曾经的容貌……一片充满生机的绿色。"
D.Strings[5072]="我们必须设法对付那些臭气熏天的暗松巨魔！"
D.Strings[5073]="投毒成功，那些巨魔要倒大霉了，$C。你真是个有前途的$G小伙子:姑娘;！"
D.Strings[5074]="我们必须保持警戒的状态，$c！在背叛者达尔坎的天灾部队和祖阿曼的暗松巨魔的夹击下，我们几乎喘不过气来。我们真的不该分散注意力！$B$B我希望你是来这里帮忙的。"
D.Strings[5075]="我很高兴你来这里帮忙，$c。我们越早解决这些巨魔，就能越早去把天灾军团赶回他们来的地方。"
D.Strings[5076]="解决掉一批巨魔，下一批就已经来了。你不知道我对你所做的事情有多么感激，$n！在你来之前，我甚至觉得我们根本无法把这些暗松巨魔给控制住。"
D.Strings[5077]="你简直无法想象最近我们都是和怎样一群乌合之众共同渡过的，大部分人简直是来找麻烦而不是帮忙的，完全不像你那样能干。$B$B你确定你不想加入远行者吗？"
D.Strings[5078]="对于艾泽拉斯的各大主城，巫妖王都只派出小股部队进行牵制和骚扰，其主力部队则主要进攻以下地区：$B$B艾萨拉、诅咒之地、燃烧平原、塔纳利斯沙漠、东瘟疫之地和冬泉谷。"
D.Strings[5079]="是什么风把你吹到这里来的，$n？没有什么人会在这附近出没。我想应该是有什么事吧。"
D.Strings[5080]="你想学习锻造专业还是有什么其它事情想告诉我？"
D.Strings[5081]="我和你，我们非常幸运地活下来了！"
D.Strings[5082]="你在这附近没看到太多的学徒吧？我开始想，这是不是因为魔导师把所有连他们都不愿意亲自做的危险任务都交给我们的缘故。"
D.Strings[5083]="$C，你救了我的命！你的恩情真是没齿难忘。我最好返回坠毁点，看看有什么需要帮忙的。"
D.Strings[5084]="我们在圣光的庇护下追求纯净和正义。"
D.Strings[5085]="$G兄弟:姐妹;，我们都受圣光庇护，但是我不能训练你。"
D.Strings[5086]="猎人，你是来接受训练的吗？"
D.Strings[5087]="我是猎人训练师。你要找的是$c训练师。"
D.Strings[5088]="你想要学习更多的战士技能吗？"
D.Strings[5089]="我非常愿意训练你，但你不是战士。"
D.Strings[5090]="我们的研究奥术和自然之力的专家们正在沿着一条永无止尽的探索之路前行。这就是你要寻求我的建议的原因吗？你希望获得更进一步的训练吗？"
D.Strings[5091]="以纳鲁的名义，你不是个法师！如果你在寻求训练，你必须找$c训练师才行。"
D.Strings[5092]="我的$G兄弟:姐妹;，我们都受圣光的庇护。你是来寻求更多指引的吗？"
D.Strings[5093]="年轻的$C，虽然我没法训练你，可我依然祝福你。在圣光的庇护下大胆前进吧！"
D.Strings[5094]="%s感激地点了点头。"
D.Strings[5095]="%s有些兴奋过头了。"
D.Strings[5096]="%s困惑不已。"
D.Strings[5097]="%s茫然不知所措。"
D.Strings[5098]="%s似乎对疫苗水晶毫不在意。"
D.Strings[5099]="%s对刚才发生的事感到不快。"
D.Strings[5100]="圣光为我们指引了许多道路，$C。你必须决定要走哪一条。"
D.Strings[5101]="$C，你的名声越来越响，因此我可以为你提供更多的货物。在物资短缺的情况下，我只能为那些获得我们信任的人服务。"
D.Strings[5102]="让我看看我可以买什么，弗雷迪加。"
D.Strings[5103]="我尽量在这块破碎的大地上提供庇护所。"
D.Strings[5104]="$G兄弟:姐妹;，很高兴见到你！这地方令人毛骨悚然。去帮助那些所谓的被遗忘者吧，别错过这样的好机会。"
D.Strings[5105]="这不是我的错……这不是我的错！$B$B如果他们按照我所说的去做，那么一切都会如预期那样的。但是，不。他们不听。$B$B现在他们全都死了。$B$B我只想回家，回银月城的家。我太累了。"
D.Strings[5106]="你们的食物好了。过来拿吧……"
D.Strings[5107]="要是我再听说你们这些差劲的家伙向纳兹格雷尔抱怨的话，那么下次我就会用你们中的一个来做菜……"
D.Strings[5108]="我是不是尝到了肉桂？还是肉豆蔻？不管是什么，有一件事是肯定的——没有人会像你那样烹驴肉的，曲奇。"
D.Strings[5109]="要不是我的胃在咕咕叫，我才不会碰这些给犯人吃的……食物。"
D.Strings[5110]="扎着马尾巴辫的侏儒小姑娘工作起来都比你们这些苦工努力！！给我快一点！快一点！"
D.Strings[5111]="我将提供舒适的服务……放松你紧张的神经，$r。我的旅店就是你的家……"
D.Strings[5112]="你好，$c。如果你还没有去和远行者索兰娜谈谈的话，就赶快去吧。"
D.Strings[5113]="那时，我和其他士兵就在荣耀之路上巡逻，这是我们日常的职责之一。我们派了侦察兵去前面察看情况，以防发生任何危险状况。"
D.Strings[5114]="果然，侦察兵急匆匆地跑了回来，说荣耀之路的另一端有一些兽人出没。他们尚未发现我们，因此我们决定立即将这一消息通传到荣耀堡。"
D.Strings[5115]="什么样的兽人？"
D.Strings[5116]="巨大的红色混蛋！比我看到过的任何兽人都要大。肌肉有这么大，獠牙一直到这儿……"
D.Strings[5117]="你指的是……"
D.Strings[5118]="邪兽人……"
D.Strings[5119]="但是怎么会这样，头儿？诅咒不是已经被消除了吗……"
D.Strings[5120]="我不知道，士兵。我——不——知道……"
D.Strings[5121]="但那还不是最糟糕的。我们还没来得及撤退，他们就发现了我们，并且发起了进攻。"
D.Strings[5122]="那天我失去了许多最棒的士兵……"
D.Strings[5123]="金罗克，我不小心弄丢了我的赞达拉辩护者胸甲，你能给我一件备用的吗？"
D.Strings[5124]="金罗克，我想我需要你帮忙重铸一件赞达拉辩护者套装。"
D.Strings[5125]="我弄丢了我的赞达拉辩护者腰带，你能帮帮我吗？"
D.Strings[5126]="金罗克，我的赞达拉辩护者护臂被搞丢了，你这里还有备用的吗？"
D.Strings[5127]="金罗克，我不小心弄丢了我的赞达拉思考者胸甲，你能给我一件备用的吗？"
D.Strings[5128]="金罗克，我弄丢了我的赞达拉思考者腰带。你能帮我吗？"
D.Strings[5129]="金罗克，我的赞达拉思考者护臂不见了。你能给我一套新的吗？"
D.Strings[5130]="金罗克，我需要你帮我重铸一件赞达拉思考者套装。"
D.Strings[5131]="法希尔，我需要你帮我重铸一件赞达拉狂妄者套装。"
D.Strings[5132]="如果你丢失了任何一件赞达拉护甲，我想我可以帮忙。"
D.Strings[5133]="法希尔，我需要你帮我重铸一件赞达拉捕猎者套装。"
D.Strings[5134]="我搞丢了我的赞达拉狂妄者外套，现在需要一个新的，法希尔。"
D.Strings[5135]="法希尔，我弄丢了我的赞达拉狂妄者腰带。你还有多余的吗？"
D.Strings[5136]="我似乎不小心弄丢了我的赞达拉狂妄者护腕。你能帮忙吗？"
D.Strings[5137]="法希尔，我弄丢了我的赞达拉赞达拉捕猎者衬肩，需要一个新的。"
D.Strings[5138]="我的赞达拉捕猎者腰带不见了。你能帮我吗，法希尔？"
D.Strings[5139]="法希尔，我的赞达拉捕猎者护腕似乎不见了。你能再给我一付吗？"
D.Strings[5140]="金罗克，我需要你帮我重铸一付赞达拉占卜师护腕。"
D.Strings[5141]="我丢失了一件赞达拉预言者套装，我需要一件新的。"
D.Strings[5142]="梅维克，我弄丢了我的赞达拉预言者外套，需要一件新的。"
D.Strings[5143]="梅维克！我的赞达拉预言者腰带被一个混球小侏儒偷走了！你能不能再给我一条？"
D.Strings[5144]="我的赞达拉预言者护腕找不到了，需要一付新的。"
D.Strings[5145]="我弄丢了我的赞达拉占卜师外套，梅维克，你这还有吗？"
D.Strings[5146]="梅维克，我的赞达拉占卜师腰带似乎不见了。你能帮我吗？"
D.Strings[5147]="我的赞达拉占卜师护腕丢了，需要一付新的。"
D.Strings[5148]="我需要你帮我重制一件赞达拉忏悔者套装，阿塔比姆。"
D.Strings[5149]="我需要你帮我重制一件赞达拉幻术师套装，阿塔比姆。"
D.Strings[5150]="我需要你帮我重制一件赞达拉恶魔师套装，阿塔比姆。"
D.Strings[5151]="我的赞达拉忏悔者衬肩丢了，需要一付新的。"
D.Strings[5152]="我的赞达拉忏悔者腰带找不到了。你能帮助我吗？"
D.Strings[5153]="阿塔比姆，我的赞达拉忏悔者裹布找不到了。你能给我一付新的吗？"
D.Strings[5154]="我搞丢了我的赞达拉幻术师长袍，需要一件新的，阿塔比姆。"
D.Strings[5155]="阿塔比姆，我搞丢了我的赞达拉幻术师衬肩。你能给我一件新的吗？"
D.Strings[5156]="我的赞达拉幻术师裹布不见了，需要一件新的。"
D.Strings[5157]="我的赞达拉恶魔师长袍不见了，需要一件新的。"
D.Strings[5158]="阿塔比姆，我搞丢了我的赞达拉恶魔师衬肩。你能给我一件新的吗？"
D.Strings[5159]="我搞丢了我的赞达拉恶魔师裹布。你能给我一付新的吗？"
D.Strings[5160]="%s闪着微光，变得模糊起来！"
D.Strings[5161]="兄弟姐妹们，我曾去过理想中的乐土。我感受过令人心生敬畏的强大力量。那种被赐福的感觉紧紧环绕，我竟然产生了步入神灵梦境的错觉。"
D.Strings[5162]="玛提克，快说下去。那是什么？感觉怎么样？"
D.Strings[5163]="置身天堂时，你会感觉自己被来回牵扯着，在虚空间飘荡。"
D.Strings[5164]="但是怎么样才能……"
D.Strings[5165]="看！原始的魔法能量从大地裂痕中喷涌而出，奥术能量的藤蔓照亮了漆黑的天空。跪下从这些裂缝中汲取魔法能量，就像从溪流或是水井中饮水那样。采集来自天堂的藤蔓，就像从树上采摘苹果那样。"
D.Strings[5166]="%s剧烈地喘息起来。"
D.Strings[5167]="我……我这是在哪儿？"
D.Strings[5168]="你先好好休息吧，帅哥，恢复体力之后再说。"
D.Strings[5169]="非常感谢你的帮助，$C！"
D.Strings[5170]="啊，就是你找到那封信的吧。感谢你带来这个……关于我的家人的消息。如果我这里的食物和饮料有什么你喜欢的，请别客气。"
D.Strings[5171]="哎！排队好不好？我一点都吃不惯外域的东西。"
D.Strings[5172]="瞧见这么多新面孔，真好。我能为你做什么？"
D.Strings[5173]="我想看看你出售的货物，希德。"
D.Strings[5174]="我想把炉石绑定在荣耀堡，希德。"
D.Strings[5175]="情况怎么样？毫无疑问……嗞嗞……这通讯设备行不行啊？我代表……嗞嗞……碧蓝岗哨……问好。"
D.Strings[5176]="根据信号来源，我们判断你是在……飞船坠毁点的东南方。穿过晶水河……嗞嗞嗞嗞。抱歉，干扰实在太大了……"
D.Strings[5177]="$n，虽然我们到过理想中的乐土，可还有很多事情等着我们去做。要是我们继续在外域徘徊不前，怎么能赶上凯尔萨斯王子？$B$B我们必须找到一条安全的路线，保护好各类资源。要是遇到敌人，打得过就打，打不过就逃。"
D.Strings[5178]="你别想抓活的，渣滓！"
D.Strings[5179]="我情愿用任何东西交换一块治疗水晶！"
D.Strings[5180]="谢谢你帮忙递交清单！我的腿差不多已经痊愈，这样我就可以自己走回坠毁点了。"
D.Strings[5181]="我们究竟要怎样才能离开这里？"
D.Strings[5182]="感谢你照顾湖泊，鞭笞者，还有枭兽。"
D.Strings[5183]="没人会怀疑你的作用，$c。你做了你该做的。"
D.Strings[5184]="我很高兴看到你还健康地活着，$n！"
D.Strings[5185]="再次感谢你为我们补充了治疗水晶。我听说你在到处帮忙，加油！"
D.Strings[5186]="无论是在黑暗之门的那边还是这边，米伦和我都是非常优秀的猎人。到处晃晃，你也许可以学到点什么的。"
D.Strings[5187]="我希望你不是为我们的啤酒而来的。不要想了，我们是不会把啤酒分给你的！$B$B除了我们之外居然没有人会有这么好的远见，想到把啤酒带到外域来，嘿，这可不是我们的过错。"
D.Strings[5188]="%s爆炸了，整个区域沐浴在奥术残渣中！"
D.Strings[5189]="%s发怒了！"
D.Strings[5190]="希望外域不全都是像这个区域那么荒芜。这里和永歌森林的密林绿草反差真大。"
D.Strings[5191]="那些存在于外域的恶魔力量远比我们过去在这世界上看到过的任何东西都要强大。$B$B强大的力量应该给予那些不逃避它，而是学着去驾驭和掌握它的人。"
D.Strings[5192]="我出生在这里，$r。这是我的世界，我所了解的一切……当我还是个小孩子的时候，我的父母经常向我讲述你们那个世界的故事，你们那个世界的荣光。我是多么渴望离开这个地方啊。$B$B唉，命运是残酷的。我的父母已经去世很久了，长眠在这个坟墓里。我留在这里，为他们的荣耀而战，也为我的家族——洛萨之子的荣耀而战。"
D.Strings[5193]="有人需要帮忙去追捕那些巨魔吗？任何巨魔都可以。"
D.Strings[5194]="为什么我们和这些肮脏的巨魔结盟？只有死去的巨魔才是好巨魔。"
D.Strings[5195]="我能为你效劳吗？"
D.Strings[5196]="我可以看看你的货物吗？"
D.Strings[5197]="外域中弥漫着魔法的能量，到处都是。你能感觉到吗，$n？我不相信还有比这更适合我们种族的地方。很快辛多雷就会拥有一个属于自己的新世界！"
D.Strings[5198]="我的丈夫失踪好几天了。我们一起到这里来朝圣，我们本应该在一起的。$B$B我太担心他了，我触摸魔力水晶的次数远远超出了必需的范围。"
D.Strings[5199]="龙鹰在适当饲养的情况下是非常容易被驯服的。你不觉得那是十分迷人的吗？饲养正确的话是如此的友好，而野生龙鹰又是如此的凶猛和致命……我太喜欢它们了。"
D.Strings[5200]="不要……担心……我……"
D.Strings[5201]="我不觉得我们的处境有这么坏。我很确信一切都会很快得到纠正，太阳之井的能量也会恢复。事情不可能像大家所想的那样坏。"
D.Strings[5202]="与逐日者合作对大家都有好处，我得到了只能在外域进行的研究课题，而他们得到了……我迷人的魅力和独特的好眼光。"
D.Strings[5203]="当我父亲被派到这片废土来的时候，我还只是个婴儿。我所知道的有关他的一切都是别人告诉我的。$B$B你的梦境会改变吗，$n？我的梦境从来都不会改变，我只有一个梦：数量超乎想象的燃烧军团士兵像深红色的地平线包围着我，战争在远处打响。我跪在一个男人身前哭泣，那男人很可能就是我父亲。他大口喘着气，他的身体支离破碎，他在低声说着什么……不管怎么努力，我总是听不到他试图告诉我的事情。"
D.Strings[5204]="维护法律的尊严！"
D.Strings[5205]="为人民的信赖服务！"
D.Strings[5206]="我也许早就该去猎杀那个肮脏的野兽，不过现在我决定提供赏金悬赏他的脑袋。"
D.Strings[5207]="告诉我们! 你们的首领躲在哪里？"
D.Strings[5208]="不开口就别想得到任何东西，你这渣滓！"
D.Strings[5209]="可怜可怜我吧！我必须马上吃点东西……一块魔力水晶……一块碎片……任何东西都行！我实在无法忍受这种痛苦了！"
D.Strings[5210]="杀死那些入侵者！"
D.Strings[5211]="你认为我对这些家伙太残忍了是吗？$B$B这个月他们已经杀死了我的两名手下！我们对这些家伙太仁慈了。"
D.Strings[5212]="欢迎来到晴风村。银月城放弃了我们，但是我们拒绝离开这里。这里是我们的家。"
D.Strings[5213]="七块阿塔玛水晶在上！发现其他幸存者了！沙娜安，是你吗？真高兴可以再次看到你！"
D.Strings[5214]="这真是个好消息！你的努力拯救了我们，$n！"
D.Strings[5215]="我的职责只有一个：确保西部圣殿运转顺畅。$B$B请原谅我的坏脾气，就像你所看到的那样，这里的状况已经超出了我的控制。"
D.Strings[5216]="双子皇帝被杀之后，神庙中能够阻止传送法阵的魔法护罩已经远远被削弱了。如果你愿意，我可以将你直接传送到双子皇帝住所那里去。"
D.Strings[5217]="奥罗死后，通向最后那个密室的道路已经彻底畅通了。如果你愿意的话，我可以把你传送到那边去。"
D.Strings[5218]="你们这群凡人，你们的意志一无是处……现在，你们都将成为主人的奴仆，并忠诚地为主人服务！世上最光荣的事莫过于为主人的事业而牺牲！"
D.Strings[5219]="主人……会为我复仇雪耻的！"
D.Strings[5220]="可怜虫！"
D.Strings[5221]="以主人之名，杀了他们！"
D.Strings[5222]="休想从我面前逃掉！"
D.Strings[5223]="跪下求饶吧，懦夫！"
D.Strings[5224]="你还喜欢这里的节日气氛吗，$c？$b$b相对于一个负责照看火炬的护火者，我更像是一个历史学家，记录着每一次的庆典，当然，今年的庆典我也会记录下来。现在情况进展的不错，你说是不是？$b$b要知道，节庆火炬上燃烧着的圣火中，都蕴涵着强大的力量。我们现在这样监守着我们的火炬，但我相信，敌人的城市里，也有这样熊熊燃烧着的圣火……"
D.Strings[5225]="消灭他们！不要让那些天灾垃圾污染我们的城市！"
D.Strings[5226]="蠢货！你们以为胜券在握了吗？你们只不过是离地狱更近了一步而已。"
D.Strings[5227]="这场游戏已经让我觉得无聊了。继续吧，到我这里来，我会亲自毁灭你们的灵魂！"
D.Strings[5228]="联盟和部落很快就将被我们瓦解，之后，艾泽拉斯大陆也必然被天灾大军征服。"
D.Strings[5229]="入侵者……这里？！消灭他们，克尔苏加德！纳克萨玛斯绝不能被攻陷！"
D.Strings[5230]="大军几乎已经整装待发，随时可以从后方突袭敌人，陛下。"
D.Strings[5231]="是的，主人，他们的最终末日马上即将降临了……这是什么?"
D.Strings[5232]="如您所愿，主人！"
D.Strings[5233]="来呀，英雄们……巫妖王命令已下，你们就都要死。"
D.Strings[5234]="很好，冰荒废土的战士们，起来吧！我命令你们为主人而战斗，杀戮，直到死亡！一个活口都不要留！"
D.Strings[5235]="祈祷我的慈悲吧！"
D.Strings[5236]="呼出你的最后一口气！"
D.Strings[5237]="你的末日临近了！"
D.Strings[5238]="主人，我需要帮助！"
D.Strings[5239]="仆从们，侍卫们，隶属于黑暗与寒冷的战士们！听从克尔苏加德的召唤！"
D.Strings[5240]="一些小点心……"
D.Strings[5241]="你们逃不掉的。"
D.Strings[5242]="对，跑吧！那样伤口出血就更多了！"
D.Strings[5243]="啊……欢迎来到我的大厅。"
D.Strings[5244]="嘘……很快一切就都结束了。"
D.Strings[5245]="哦，我听见不少声音啊……不过马上就都要停止了。"
D.Strings[5246]="去哪里？做什么？太多的选择，可这一切都会在痛苦与死亡中终结。"
D.Strings[5247]="我该先吃谁呢？真是难以选择。每一个闻起来都这么鲜美……"
D.Strings[5248]="哦，小点心终于来了。我好久都没有吃肉和饮用鲜血了。"
D.Strings[5249]="准备接招吧！"
D.Strings[5250]="算你……厉害……"
D.Strings[5251]="你的命是我的了！"
D.Strings[5252]="嘿，瑟里耶克，别把他们赶跑了。等我们玩够了再说！"
D.Strings[5253]="真希望他们能撑久点儿，至少让我做完……自我介绍。"
D.Strings[5254]="肯定是我首开记录！有人敢打赌吗？"
D.Strings[5255]="你的灵魂现在属于我了！"
D.Strings[5256]="没有人能逃得掉！"
D.Strings[5257]="啊！别……高兴得……太早了！你们的胜利空洞而虚无，没有任何意义，我很快就将卷土重来！"
D.Strings[5258]="我要把你血脉里的血液全都冻住！"
D.Strings[5259]="黑暗的虚空正等着你呢！"
D.Strings[5260]="主人要吃了你！"
D.Strings[5261]="费尔根……完了。"
D.Strings[5262]="费尔根要让主人高兴。"
D.Strings[5263]="事业……未尽……"
D.Strings[5264]="死亡是唯一的解脱方式！"
D.Strings[5265]="我已经等待很久了。现在你们将面对灵魂的收割者。"
D.Strings[5266]="你们这些蠢货已经主动步入了陷阱。"
D.Strings[5267]="你们正在挑战一个无比强大的存在。"
D.Strings[5268]="虽然你们经历了千难万险才来到收割者的领域，来到我的面前。"
D.Strings[5269]="但是现在，活下来的唯一途径就是加入诅咒神教。"
D.Strings[5270]="来呀，放马过来呀！"
D.Strings[5271]="哦……又要血流成河了！"
D.Strings[5272]="下次，劳驾多带点朋友来！"
D.Strings[5273]="我最喜欢烤肉了！"
D.Strings[5274]="来吧！你们这群杂碎！我们可有四个人哪！"
D.Strings[5275]="哭哭闹闹！没完没了！我都听烦了！你们要是不能闭上嘴，我来帮你们！"
D.Strings[5276]="我要好好享受一下把你们这群傻瓜蛋杀光的感觉！"
D.Strings[5277]="你……就是下一个。"
D.Strings[5278]="闭上双眼，长眠吧。"
D.Strings[5279]="世间的一切种族终将灭绝，这是迟早的事情。"
D.Strings[5280]="我看到了无尽的苦难。我看到了无穷的折磨。我看见了滔天的愤怒。我……看到了一切……"
D.Strings[5281]="很快，这个世界也要颤抖。"
D.Strings[5282]="你的生命正走向终结。"
D.Strings[5283]="饥饿的蠕虫将要吞噬你腐烂的躯体。"
D.Strings[5284]="你寻死吗？"
D.Strings[5285]="不许动！"
D.Strings[5286]="你死后也永远不得安宁。"
D.Strings[5287]="这是主人的意志。"
D.Strings[5288]="臣服于天灾军团的力量吧！"
D.Strings[5289]="别多说废话了。让他们来吧。我们会把他们的骨头碾成灰的。"
D.Strings[5290]="保留你的愤懑，压抑你的怒火吧，很快你们就只能体会到挫折感了。"
D.Strings[5291]="生命本身毫无意义。只有死亡才能让你了解人性的真谛。"
D.Strings[5292]="荣耀归于我主！"
D.Strings[5293]="死吧，入侵者！"
D.Strings[5294]="我要侍奉主人……到最后一刻！"
D.Strings[5295]="起来吧，我的战士们！起来，再为主人尽忠一次！"
D.Strings[5296]="帕奇维克要跟你玩！"
D.Strings[5297]="帕奇维克是克尔苏加德的战神！"
D.Strings[5298]="怎么……搞的……"
D.Strings[5299]="哈哈，我正好刚刚完成热身！"
D.Strings[5300]="来吧！"
D.Strings[5301]="按我教导的去做！"
D.Strings[5302]="仁慈无用！"
D.Strings[5303]="你们太令我失望了，学生们！"
D.Strings[5304]="练习时间到此为止！都拿出真本事来！"
D.Strings[5305]="光荣地……战死……"
D.Strings[5306]="绊腿……有什么问题么？"
D.Strings[5307]="你该在家里待着。"
D.Strings[5308]="%s发出胜利的呼喊。"
D.Strings[5309]="斯塔拉格要碾碎你！"
D.Strings[5310]="主人，救救我！"
D.Strings[5311]="斯塔拉格宰了你！"
D.Strings[5312]="杀……"
D.Strings[5313]="咬碎……你的……骨头……"
D.Strings[5314]="打……烂……你！"
D.Strings[5315]="你感受到痛苦的滋味了吧……"
D.Strings[5316]="你们太迟了！！我……只好……服从……"
D.Strings[5317]="求求你！"
D.Strings[5318]="停下！停下这东西！！"
D.Strings[5319]="帮帮我！救救我！"
D.Strings[5320]="不……"
D.Strings[5321]="你……死吧！"
D.Strings[5322]="逃走吧，否则就太迟了！"
D.Strings[5323]="这就是……必然的归宿。"
D.Strings[5324]="原谅我。"
D.Strings[5325]="除了服从，我别无选择！"
D.Strings[5326]="入侵者，立刻结束这无谓的冒险！趁你们还活着，马上离开这里！"
D.Strings[5327]="或许……他们会觉悟过来，然后立刻逃离这儿。"
D.Strings[5328]="不要继续了！撤退，趁还有时间，你们应该立刻撤退！"
D.Strings[5329]="这是你的最高水平了吗？"
D.Strings[5330]="如果你在找活干的话，$c，拿起锄头去挖吧。你没看到那边有一大堆废墟么？"
D.Strings[5331]="你好，$n。我们洛萨之子已经被困在这个破败的世界中近二十年了。我们尽自己所能生存了下来，但是令我惊讶的是，我们现在所面对的威胁只不过是我们过去失败的影子。$B$B也许你可以帮助我们来弥补这一切？"
D.Strings[5332]="我不指望你给我带来了矿洞的消息，有吗？"
D.Strings[5333]="外域被污染的范围之大非常令人震惊，$c。塞纳里奥议会希望去了解这里的生物是怎么生存下来的。了解这个破碎、扭曲的世界和它的居民，也许我们可以学习到治愈我们自己世界的方法。"
D.Strings[5334]="我很伤心地看着在这片大地上发生的一切。塞纳里奥远征队会尽全力了解和治愈那些创伤。"
D.Strings[5335]="$C，你似乎很迷茫。不要逼我让你跟那些苦工一起干活。"
D.Strings[5336]="见到你真好，$c。你来的真及时。酋长不能亲自来这里，所以全靠我们了。"
D.Strings[5337]="萨尔玛需要你，$c。酋长需要你。做好准备去完成你的职责吧。"
D.Strings[5338]="不！！！诅咒你，入侵者，诅咒你！巫妖王的军团一定会杀死你的。你逃避不了必然的命运……"
D.Strings[5339]="是不是暗夜精灵破坏者在捣鬼？很难说。我们施加在西部圣殿的流量如此大，发生故障只是时间问题而已。"
D.Strings[5340]="很少有较量是可以靠着纯粹的力量取胜的。巧妙的使用和认识你的武器会让你常胜不败。"
D.Strings[5341]="让我看看你都能教我些什么，拉雷尼斯。"
D.Strings[5342]="我的……力量……正在恢复！"
D.Strings[5343]="你治愈了我！让我们的敌人尝尝失败的滋味吧！"
D.Strings[5344]="你帮我恢复了健康！我欠你个人情，$n。"
D.Strings[5345]="又一位英雄？命运在对着我们微笑，$n。"
D.Strings[5346]="我听说了一些关于你的探险故事，$n。我知道，当你踏上遗忘者的土地时，你会举止庄重优雅，并且把自己当作一个真正的辛多雷英雄！"
D.Strings[5347]="看！他们在跟踪我们！"
D.Strings[5348]="谢谢你愿意伸出援手，现在让我们离开这里，$n！"
D.Strings[5349]="请让我休息一会，我已经非常累了。"
D.Strings[5350]="终于到了猎鹰岗哨！现在，我的……？天哪！我的背包找不到了！这可怎么办……"
D.Strings[5351]="非常欢迎，$c。"
D.Strings[5352]="我没有时间来闲聊，$c。我必须照顾那些朝圣者，保证他们为漫长的旅程做好充足的准备。"
D.Strings[5353]="欢迎来到猎鹰岗哨，$c。我留意着那些朝圣者的需求，并帮助他们继续走完漫长的旅程。如果你还没有开始朝圣，我可以给你提供一些你需要的信息。"
D.Strings[5354]="愿圣光永远照耀你，$n。"
D.Strings[5355]="欢迎来到远行者居所。我们是一个发誓保卫人民的游侠组织。"
D.Strings[5356]="我想我已经开始后悔来进行这次朝圣了。我知道路途会很艰辛，而且我也并不是一个远行的新手，但我没有准备好面对外域的困难。$B$B最主要的是，那个塔雷里斯似乎想要在我完全恢复力量之前把我赶出这里。"
D.Strings[5357]="啊……我认识你吗？"
D.Strings[5358]="你好，$n！聚会不错吧？"
D.Strings[5359]="大家看啊，$n来了！"
D.Strings[5360]="消息在这圈子里传得很快。感谢你帮我们补充货源！"
D.Strings[5361]="这个聚会是最棒的！你不觉得吗？"
D.Strings[5362]="你应该尝尝魔泉美味，简直太棒了！"
D.Strings[5363]="我觉得今年的日光陈酿不是那么好喝。你觉得呢，$n？"
D.Strings[5364]="听说我们今晚都要去边界观看防御部队和天灾军团的战斗。多令人激动啊！"
D.Strings[5365]="你能相信那个埃莉萨拉·射日者的勇气吗？她居然认为自己可以引起萨瑟利尔男爵的注意，还有，你看到她都穿了些什么吗？太落伍了。真令人伤心，真的。"
D.Strings[5366]="对不起，我不需要帮忙。"
D.Strings[5367]="你是……？"
D.Strings[5368]="恐怕你把我和某个想和你说话的人搞混了吧。"
D.Strings[5369]="啊……滚开！"
D.Strings[5370]="什么？发生什么事了？"
D.Strings[5371]="我感觉不太舒服！"
D.Strings[5372]="是我把自己弄成这般田地的。先知雷古库特曾想警告我，但是粗心最终让我变成了这样。$B$B我是来这里研究塞斯高废墟的，但是在路上与燃烧军团发生了冲突。现在，我能给你们看的就只有腿上那道化脓的伤口。"
D.Strings[5373]="虽然我不能训练你，年轻的$c，但我可以给你我的祝福。在圣光中大胆地前进吧！$B$B还有别的事情吗？"
D.Strings[5374]="明确暗夜精灵的意图对我们来说是非常重要的，$c！请为了这个目标努力吧。"
D.Strings[5375]="不久之前，这个地方发生了一场可怕的战斗，我们守望堡和银色黎明在黑暗之门涌出的恶魔们无情的冲击下，几乎要全线崩溃。$B$B在那段黑暗的日子里，充满了流血和绝望……$B$B但是，艾泽拉斯各国很快就赶来支援，把那些恶魔赶了回去！战斗还在黑暗之门的另一边持续着……$B$B这座营地目前恢复了平静，但是我担心这里的宁静掩饰了黑暗之门另一边的疯狂。"
D.Strings[5376]="托尔贝恩家族的英雄事迹就像传说一样，我非常崇拜他。$B$B当我来到外域之后……我发现他还活着。$B$B<洛姆斯凝视着你的身后。>$B$B当我第一次看到他的时候，我几乎晕倒了。那种震撼是无可抵挡的，我跪在他的面前，泪水几乎要奔涌而出。$B$B我发誓会尽我的全力来保卫洛萨之子的安全。"
D.Strings[5377]="洛姆斯把我的美丽城市所遭遇的悲剧告诉了我。在我听到了洛丹伦的命运……还有我所深爱的激流堡的命运之后，我找不出什么合适的语言来形容我的悲伤。$B$B二十年前，没人听说过“燃烧军团”……那些该死的恶魔！$B好好休息，$n。等到我再回到艾泽拉斯去的时候，我发誓，激流堡将再次崛起！"
D.Strings[5378]="你们必须得到净化。"
D.Strings[5379]="这么……黑暗的……能量！这怎么可能？"
D.Strings[5380]="嘿！你想干什么，就像那样躲来躲去吗？"
D.Strings[5381]="对不起，你是不是想偷偷溜进去？"
D.Strings[5382]="我快抓狂了！所有可以用来修理这台发射器的零件，一件都没有！"
D.Strings[5383]="$n！再次感谢你的帮助。"
D.Strings[5384]="不，还没完全修好。但估计不会太久了。"
D.Strings[5385]="我所能记得的最后一件事是飞船在下降，而我们都进入了救生舱。我去看看有什么我可以帮忙的。谢谢你！"
D.Strings[5386]="我在哪？你是谁？天啊！飞船怎么了？"
D.Strings[5387]="啊……这里是哪？飞船就只剩下这点了？"
D.Strings[5388]="啊啊啊……疼死我了。你可以帮帮我吗？"
D.Strings[5389]="<哭泣> 我讨厌墓地。太多人死去了。还有我亲爱的鲁哈娜……"
D.Strings[5390]="%s轻声地哭泣着。"
D.Strings[5391]="%s默默地凝视着他面前的墓碑。"
D.Strings[5392]="%s悲痛地放声大哭。"
D.Strings[5393]="%s低下了头叹了口气，非常疲倦的样子。"
D.Strings[5394]="为什么，鲁哈娜？为什么？！"
D.Strings[5395]="为什么活下来的是我而不是你？！"
D.Strings[5396]="我永远都不会忘记你，我的爱人。"
D.Strings[5397]="我们永远都不会分开。"
D.Strings[5398]="我非常想念你！"
D.Strings[5399]="如果让我找到导致坠毁的元凶……！"
D.Strings[5400]="你会一直在我身边的。"
D.Strings[5401]="安息吧，我的爱，我的心，我的鲁哈娜。"
D.Strings[5402]="我们不会让你离开这个山谷的！"
D.Strings[5403]="真可惜，你在坠毁中生还，却要死在这里。"
D.Strings[5404]="我希望你能安息。"
D.Strings[5405]="%s抬起头，似乎在听着什么东西。"
D.Strings[5406]="你竟然敢洒出主人的酒！"
D.Strings[5407]="那是有200年历史的紫葡萄酒！"
D.Strings[5408]="你这样的家伙完全是在浪费它！"
D.Strings[5409]="你胆敢打扰主人的宴会！"
D.Strings[5410]="%s呼喊着她的主人！"
D.Strings[5411]="啊……好疼啊……"
D.Strings[5412]="疼死我了。请想想办法……"
D.Strings[5413]="我不知道我能不能坚持下来。帮帮我……"
D.Strings[5414]="阿努布雷坎释放了虫群！"
D.Strings[5415]="%s发出的嚎叫在北边的山脉中回响，提醒你跟着它。"
D.Strings[5416]="亚维鲁的魔法失效了！我又自由了！"
D.Strings[5417]="亚维鲁的魔法……仍然控制着我。你必须与我战斗，凡人。这是唯一可以解除那个魔法的办法！"
D.Strings[5418]="永远要对这个世界上的元素表示尊敬。"
D.Strings[5419]="我们必须努力了解这个世界上的元素之灵所维护的平衡。"
D.Strings[5420]="%s冲过去帮助她的主人。"
D.Strings[5421]="来吧，午夜，让我们解决这群乌合之众！"
D.Strings[5422]="懦夫！胆小鬼！"
D.Strings[5423]="这是……命运。"
D.Strings[5424]="晚餐又多了一道菜。"
D.Strings[5425]="我就知道……总有一天……猎人会变成猎物。"
D.Strings[5426]="你好！很高兴遇到你！"
D.Strings[5427]="你好。你是过来帮忙的吗？"
D.Strings[5428]="记住，$n，你尽心竭力地帮助他们便是对我们莫大的恩惠……"
D.Strings[5429]="你好，$r！我想你过得不错吧？"
D.Strings[5430]="有什么家乡来的消息吗，$c？"
D.Strings[5431]="靠近点，朋友。不要被我的眼睛吓到了。$B$B我可能许多年前就失明了，但我从不需要通过眼睛来看重要的东西。"
D.Strings[5432]="带上一张网，年轻的$c。我们需要食物！"
D.Strings[5433]="你好，过得不错吧？"
D.Strings[5434]="请教我如何钓鱼，迪泰娜。"
D.Strings[5435]="迪泰娜，我想要看看你出售的货物。"
D.Strings[5436]="很高兴看到其他的辛多雷$g兄弟:姐妹;！如你所见，这附近没有什么其他人可以说话。"
D.Strings[5437]="我很荣幸认识你。"
D.Strings[5438]="很高兴能和你说话，请尽量帮助联盟吧。"
D.Strings[5439]="你好。我是学者德尔兰，一个德莱尼人。你是谁？"
D.Strings[5440]="虽然我们有很多东西可以教给联盟的其他种族，但是我们同样也有很多东西要从他们那里学习。要多多使用你的眼睛、耳朵和心灵，$c。"
D.Strings[5441]="你好啊，$c。"
D.Strings[5442]="这座城市不漂亮吗，$c？我们可以找到这么知心的暗夜精灵朋友，真让我感到温暖。"
D.Strings[5443]="你好，我是守备官帕兰纳尔，一个信仰圣光的旅行圣骑士。我是来这里帮助暗夜精灵的。"
D.Strings[5444]="我热切希望我们可以把圣光带到灰谷中的那些被遗忘的地方。"
D.Strings[5445]="武器对我这样的战士来说无足轻重！"
D.Strings[5446]="把我传送到熔火之心去，洛索斯。"
D.Strings[5447]="你们可笑的魔法对天灾军团来说不值一提！"
D.Strings[5448]="我太忙了，没时间闲聊。如果你在寻找一份猎手的工作，去和河边迪泰娜聊聊吧。往东走，她应该还在那里忙呢。"
D.Strings[5449]="我是个需要训练的猎人，艾克提恩。"
D.Strings[5450]="看上去很有趣！亲爱的，你不觉得吗？"
D.Strings[5451]="看看埃索达，年轻的$c。很难想象我们在这场大灾难中生存了下来。$B$B<梅内莱厄斯叹了口气。>$B$B先知预言我们会在这里最终了解到自己的命运。我们用了毕生的时间来逃避疯狂的燃烧军团……现在我们终于可以在这里停下来了。$B$B不再逃跑……我已经准备好光荣地战死了。"
D.Strings[5452]="是巴尔兰达·新星派你来救我的吗？"
D.Strings[5453]="巴尔兰达派我到这里来救你出去，顺便拿回他的货物。他在蕨墙村等着你。"
D.Strings[5454]="我想我可以自己回蕨墙村。他们把货物放在了塔顶，多加小心！"
D.Strings[5455]="太棒了！真是太有趣了，难道不是吗？我满满地诅咒了这些恶心的失落者，很快我就可以在德莱尼人身上试试了！"
D.Strings[5456]="让灵魂指引你吧，$r。"
D.Strings[5457]="氏族的力量，$c！你来这里干什么？"
D.Strings[5458]="你好。我是德莱尼学者阿弗恩。我在这里研究农田避难所的失落者们，希望可以找到一个治愈他们的办法。"
D.Strings[5459]="欢迎你来到这里，$c。"
D.Strings[5460]="你好，$n。是什么风把你吹到这里来的？"
D.Strings[5461]="还没完！我还有几招没有用呢……"
D.Strings[5462]="你们应该不会不让一个可怜的老人喝点东西吧？不，不，当然不会。"
D.Strings[5463]="没错，我的儿子非常强大……但我也有自己的力量！"
D.Strings[5464]="我不是某个可笑的小丑，我是聂拉斯·埃兰！"
D.Strings[5465]="我要让你们知道，老狗也有几颗牙！"
D.Strings[5466]="燃烧吧，地狱的恶魔！"
D.Strings[5467]="我要把你们全都冰冻！"
D.Strings[5468]="我要结束这场噩梦！"
D.Strings[5469]="不要再烦我了！"
D.Strings[5470]="求求你们，不要这样！我的儿子……已经疯了！"
D.Strings[5471]="你们是谁？你们想要什么？离我远点！"
D.Strings[5472]="你怎么拿到这个的？是不是他派你来的？"
D.Strings[5473]="啧啧，好可爱啊！你怎么敢独自出来的？也许你在其他人派出搜索队之前赶紧回去。"
D.Strings[5474]="我这里没有更多的工作可以给你了，$n。我想让你知道，那些红钳鱼真是我一辈子也忘不了的美味……"
D.Strings[5475]="我当然有工作要给你！我们一直在找寻$c，希望你能比那些我们送回埃索达去埋掉的德莱尼人好一点。$B$B艾克提恩大笑起来。$B$B我在开玩笑呢！你真该看看你刚才那表情。他们被送回埃索达是为了治疗些小伤，很快都会痊愈的……"
D.Strings[5476]="回到你的人民那里，告诉他们派个萨满祭司到我这里来。"
D.Strings[5477]="回到德莱尼人那里，告诉他们派个萨满祭司到我这里来。"
D.Strings[5478]="萨满祭司，你在这里的事情都完结了。回到你的族人那里去吧。"
D.Strings[5479]="你有足够继续下去的理解力了吗，萨满祭司？你知道我们为什么在这里吗？"
D.Strings[5480]="能生存下来，并且和元素们生活在一起，这可真好啊。"
D.Strings[5481]="我为什么要和你说话，$r？"
D.Strings[5482]="看看你周围，萨满祭司。你可以看到在大地、空气、水和火焰这些元素之间的平衡吗？"
D.Strings[5483]="别紧张……我的狮鹫虽然看起来死气沉沉，但是它们仍然能把你安全地送往目的地。告诉我……你想要去哪座哨塔？"
D.Strings[5484]="要是你还没学会怎么去使用绷带，我很高兴向你展示下基本的绷带制作和使用方法。生与死之间的区别，经常是一根绑带决定的。"
D.Strings[5485]="法蒂玛，我想要学习急救技能，希望你能把你掌握的知识都传授给我。"
D.Strings[5486]="我会报仇的！！"
D.Strings[5487]="我现在很忙，年轻的$c，不好意思。"
D.Strings[5488]="你们浪费了我太多的时间……让这场游戏结束吧！"
D.Strings[5489]="你好，$c。我从埃索达被派来检查碧蓝岗哨的建筑。"
D.Strings[5490]="戴罗，我想要学习工程学。"
D.Strings[5491]="戴罗，我想要看看你出售的货物。"
D.Strings[5492]="好，我们走吧。我知道有个完美的地点！"
D.Strings[5493]="我迫不及待地想尝尝这瓶酒了！"
D.Strings[5494]="发生……了……什么事？把这只猫从我身边拿开！"
D.Strings[5495]="炼金师可以用普通的药草来创造奇迹，把它们转换成各种稳定的药水，比如治疗或者水下呼吸之类。"
D.Strings[5496]="我想要学习炼金术，丹达尔。"
D.Strings[5497]="咪咪用饥饿的眼神看着薇拉·火语。"
D.Strings[5498]="现在把药膏涂在她的伤口上。"
D.Strings[5499]="看上去这药膏没有起作用。真遗憾……"
D.Strings[5500]="可能还有个解决办法，到这边来，$n。我会向你解释我需要什么。"
D.Strings[5501]="这个应该有作用……"
D.Strings[5502]="醒来吧，小家伙。从睡眠中醒来吧……你现在安全了。"
D.Strings[5503]="%s坐了起来。"
D.Strings[5504]="我……我在哪里？这……这是什么地方？"
D.Strings[5505]="以艾露恩之光的名义！艾瑞达人！你们这群被诅咒的恶魔，你们对我做了什么？我并不是独身一人，我们会像以前那样和你们战斗到底！我……"
D.Strings[5506]="%s昏了过去。"
D.Strings[5507]="腐蚀者……但是……我们不是艾瑞达人！她必须明白这一点！如果还有其他类似她的生物，我们必须找到他们，给他们解释……"
D.Strings[5508]="薇拉·火语飞快地窜开，努力从咪咪那里逃走。"
D.Strings[5509]="以圣光的名义，离这座陵墓远一点！"
D.Strings[5510]="你好，什么风把你吹到寒风营地来了？"
D.Strings[5511]="小心！我们受到攻击了！"
D.Strings[5512]="一定是光明使者的印记所散发出的纯洁气息把天灾军团吸引来了。我们必须加倍小心！"
D.Strings[5513]="这片土地真应该被圣光彻底净化！我们继续吧，陵墓就在前面。"
D.Strings[5514]="欢迎你，朋友！"
D.Strings[5515]="感谢你专程来纪念我。你找回了这个印记——虽然它并没有什么实际的意义，但是仍然让我心里感到很温暖。"
D.Strings[5516]="请起身吧，我的朋友。拿着这份祝福，它是圣光力量的象征，也可以时刻提醒我们，那些逝去的英雄其实一直活在我们的心中。"
D.Strings[5517]="谢谢你，朋友。这一天我永远都不会忘怀！我想在这里待一会儿。请回到营地去找高阶牧师玛多妮尔，她一定对我们刚才遇到的事情很感兴趣。"
D.Strings[5518]="你为什么要这么做？我生前对你做过什么吗？"
D.Strings[5519]="啊，我明白了。是我的学生让你来的……麦拉·黎明之刃。他的心灵竟然变得如此黑暗，这真令我伤心。"
D.Strings[5520]="回到他那里去吧。回去告诉麦拉，我原谅他，我也理解他为什么会那样想。"
D.Strings[5521]="你好啊，$c。$B$B我正在等待鹰巢山国王的召见，要想争取这个机会还真是不容易。$B$B我听说蛮锤部族向来对外人“抱有警惕”，但显然他们不止有些警惕而已……希望在我见到羽须大人之后事情会有所改善，他似乎对联盟比较有好感。"
D.Strings[5522]="你要干什么？$B$B没有理由就靠近一个陌生人，你不觉得有点粗鲁吗？"
D.Strings[5523]="我只希望他能看到圣光，用他的力量来恢复曾经美丽的奎尔萨拉斯。"
D.Strings[5524]="你好啊，朋友。我的名字叫曲奇，烹饪是我的游戏。米维克索斯是个以烹饪和贸易著称的家族。"
D.Strings[5525]="教我怎么烹饪吧，曲奇。"
D.Strings[5526]="让我看看你的货物，曲奇。"
D.Strings[5527]="我想成为一个铁匠。"
D.Strings[5528]="让我看看你出售的货物，卡里普索。"
D.Strings[5529]="一个远古的生物在远处被唤醒了……"
D.Strings[5530]="愚蠢的家伙！我会很快终结你们的痛苦！"
D.Strings[5531]="愿圣光与你同在，$C。"
D.Strings[5532]="似乎援兵终于来了！欧麦尼欢迎你来到我们的营地，$n。"
D.Strings[5533]="伊坎试了又试。我想这些残冠氏族的人更像是失落者，你知道……那些失落了的……"
D.Strings[5534]="可能会需要一段时间，但这些破碎者终将学会如何使用圣光！"
D.Strings[5535]="你好，$n，我是兰德鲁·郎绍特，黑色烈焰的主管。这或许是你第一次听说黑色烈焰。我对此并不惊讶，因为我们向来低调。我们希望能够避免……派系争斗。$B$B黑色烈焰一贯致力于提供最好的服务和娱乐。只要你出得起价钱，不管是稀有的物品，刺激的战斗还是赚钱的游戏机会，我们都能提供。$B$B你是来找什么特殊的东西的吗？"
D.Strings[5536]="你有什么促销品？"
D.Strings[5537]="啊，奇珍异宝。我们收集艾泽拉斯各地的宝物，为强大的冒险者服务。$B$B既然你来找我，那么想必你已经知道自己想要什么了，$n。"
D.Strings[5538]="红色徽章"
D.Strings[5539]="你休想阻止我到达猎鹰岗哨！"
D.Strings[5540]="你需要什么东西吗，$c？也许我可以帮助你。"
D.Strings[5541]="蓝色徽章"
D.Strings[5542]="角鹰兽宝宝"
D.Strings[5543]="紫色焰火"
D.Strings[5544]="食人魔装束"
D.Strings[5545]="乌龟坐骑"
D.Strings[5546]="够了！我要落下来把你们打得粉碎！"
D.Strings[5547]="没用的虫子！让你们见识一下我的力量吧！"
D.Strings[5548]="……一种强效的混合剂！"
D.Strings[5549]="但是我在哪里才能找到合适的实验品呢？"
D.Strings[5550]="喝下这个，你这个蓝色的野蛮人！否则我保证会把你折磨致死！"
D.Strings[5551]="唔……好像我需要一个新的测试课题。"
D.Strings[5552]="我怜悯你，被遗忘者。你的灵魂暗淡无光。"
D.Strings[5553]="幽暗之地仅靠军事力量是无法夺回的，$n。我们魔导师才是关键。$B$B我们的狡诈和魔法知识是无往而不利的。"
D.Strings[5554]="嘿，曲奇！今天晚餐咱们吃了什么？不要告诉我是鸡肉！"
D.Strings[5555]="呀，将军。让我考虑一下……啊……有了。"
D.Strings[5556]="我计划给大家烹制浇着美味肉汁、还有一点点杉德尔船长特制配方的鲜嫩多汁的烤猪排。"
D.Strings[5557]="而且我们有从暴风城空运过来的奶酪蛋糕作为餐后甜品。"
D.Strings[5558]="是不是啊？这么棒？"
D.Strings[5559]="还是鸡肉……"
D.Strings[5560]="我恨你，曲奇。"
D.Strings[5561]="<女祭司伊尔蒂娜怀疑地看着你。>"
D.Strings[5562]="我是个暗夜精灵，陌生人。虽然你也许对我的种族一无所知，但我们早已对你和你的祖先了如指掌。你可以不把自己称为艾瑞达人。但是，在外形上你们有很多相似点。$B$B你帮了我的朋友们，我对此非常感谢；从现在开始，你就要独自走上危机四伏的道路。也许过不了多久，你可以消除我心中的恐惧和疑虑。"
D.Strings[5563]="你好，$r。你高尚的行为已经得到了认可。愿艾露恩保佑你。"
D.Strings[5564]="小心一点，陌生人。"
D.Strings[5565]="迄今为止，你帮了我们不少忙，$n。营地附近还有其他人需要你的帮助呢。$B$B别担心那些地精，我会妥善安排好一切的。"
D.Strings[5566]="阿达曼特，你能看下这块石板，顺便试着翻译一下上面的符文吗？"
D.Strings[5567]="当然！没问题，亲爱的！"
D.Strings[5568]="嗯，让我看看那块石板。"
D.Strings[5569]="%s慢慢地读着石板，用他们的母语读着那些文字。"
D.Strings[5570]="天哪……纳迦督军！"
D.Strings[5571]="嗯，你不会喜欢这个消息的，小姑娘。这块石板是纳迦的交流工具。他们的首领督军斯雷提兹命令他的纳迦们用武力来抢夺这块岛屿。"
D.Strings[5572]="看上去他得到了纳沙塔尔的增援！"
D.Strings[5573]="我们必须得干点什么了！"
D.Strings[5574]="谢谢你，阿达曼特。我想我知道谁最适合这项工作。"
D.Strings[5575]="很高兴能再次见到你，$n。也许当事情都解决了之后，我可以告诉你有关那些我们丢失的无价之宝的事情……"
D.Strings[5576]="联盟竟敢深入我的堡垒？把荣耀堡的战俘带出来，让刽子手们待命！他们会为这次入侵付出生命的代价！"
D.Strings[5577]="萨尔的那个冒牌部落胆敢深入我的堡垒？把萨尔玛的战俘带出来，让刽子手们待命！他们会为这次入侵付出生命的代价！"
D.Strings[5578]="你在看什么？"
D.Strings[5579]="我是来自铁炉堡的阿达曼特·铁心。我想你可能已经从我的制服上面猜出来了，我曾是铁炉堡精英守卫中的一员。是的，我曾经是麦格尼的左膀右臂！至少在我退休前。现在我开始涉足考古学，确切地说，这是我的爱好，而且我发现这真是个了解世界的好办法！"
D.Strings[5580]="<库雷呜咽着。>"
D.Strings[5581]="我干了些什么？为什么神明要如此残忍地惩罚我？我所爱的一切都没有了——不是死了就是被毁灭了。我的家人被森林里的怪物掳走，我的家被夷为平地，我的船沉了。$B$B这个已经崩溃的人在这座破碎的岛屿上束手无策。$B$B也许你来这里是要完成你那肮脏的工作？那么就快点，我不会抵抗的。拿走我的生命吧，陌生人；我自己下不了手，我的手在颤抖……"
D.Strings[5582]="我不会杀你的，暗夜精灵。神明也不会这么做的……"
D.Strings[5583]="如果不是神，那会是谁？什么样的力量会把这里变成这样？"
D.Strings[5584]="恐怕我的同胞应该对这次破坏负一些责任。燃烧军团逼我们逃出了家园，成为了难民。这个惨剧是由我们导致的。我们的飞船坠毁了——这块碎片是飞船的一部分。"
D.Strings[5585]="燃烧军团？恶魔？他们在猎杀你？我的人民也在被燃烧军团猎杀，被他们的黑暗主人作为诅咒的目标。$B$B<库雷擦去了泪水。>$B$B那就是我几年前把家搬到这里来的原因。"
D.Strings[5586]="看来我们有很多共同点，暗夜精灵。我对你的不幸爱莫能助，但也许是命运让我们聚到了一起。让我帮助你吧，库雷。让我的人民帮助你吧。我发誓我们会矫正自己犯下的错误。"
D.Strings[5587]="这边走，我们的房子在那里，穿过灌木丛就到。"
D.Strings[5588]="我可怜的家，所有的东西都被摧毁了。"
D.Strings[5589]="爸爸！爸爸！你还活着！"
D.Strings[5590]="%s拥抱着她的父亲。"
D.Strings[5591]="你应该感谢$n安全地把我带回来，爸爸。"
D.Strings[5592]="女儿！"
D.Strings[5593]="你好，$c。在暗夜精灵邀请我们德莱尼人加入他们之前，这片林地几乎已经被遗忘了。$B$B卡多雷人完全控制了这片土地，他们邀请我们加入重建林歌神殿的任务，对此我们德莱尼人深感荣耀。"
D.Strings[5594]="很高兴可以在这里看到新面孔。我们的哨站很小，但却有着大量的敌人。我们被那些企图消灭我们的家伙包围着：北面的萨特，东面伐木营地的兽人，还有那些冥火岭的恶魔。$B$B虽然几乎是身处死地，但即使我们全部牺牲，我们也要夺回这个地方！"
D.Strings[5595]="能在林歌神殿听到其他的人的声音，这可真是太好了，我都开始觉得自己可能是留在这里的最后一个卡多雷了。"
D.Strings[5596]="你能感觉到弥漫在我们周围的邪恶气息吗，$c？以阿古斯之手的名义，它必须被消灭掉！$B$B那些恶魔摧毁了我们曾经的家园阿古斯。我绝不会容忍他们蹂躏我们新的家园——艾泽拉斯！"
D.Strings[5597]="虽然你已经给南方的恶魔势力造成了沉重的打击，但我还是觉得那个地方有些问题。"
D.Strings[5598]="帮帮我！"
D.Strings[5599]="有你和你的朋友作为同盟，我们决定留在这座岛上进行重建工作。艾露恩保佑你，英雄。$B$B虽然悲伤仍然萦绕在我心中，但我相信我们可以生存下来。"
D.Strings[5600]="你是一个$R，对吧？在这儿遇见你真是令人振奋！我们欢迎任何能够寻求到的援助。"
D.Strings[5601]="入侵者！"
D.Strings[5602]="这里不欢迎你！"
D.Strings[5603]="%s拾起纳迦的旗帜。"
D.Strings[5604]="这到底是怎么回事，斯巴克？你为什么要召集这次会面？"
D.Strings[5605]="怎么回事？你几乎破坏了我的伪装，白痴！我告诉你把罗盘和航海地图放在一个安全的地方，而不是放在一个给任何傻瓜都可以发现的地方。"
D.Strings[5606]="主人不遗余力地探查有关埃索达所在之处的信息。你可能会破坏整个行动，包括我们在埃索达安插的间谍！"
D.Strings[5607]="放松一点，斯巴克！一切都在我的控制下。我们会慢慢挖光埃索达的水晶……让我和你都变得非常非常富裕。"
D.Strings[5608]="放松点？你知道凯尔萨斯会对那些让他失望的家伙做些什么吗，吉兹尔？无尽的痛苦……不要把这事情搞砸了，白痴！"
D.Strings[5609]="我们的秘血岛斥候已经定位到了我们的联系人。那个笨蛋维伦很快就会处于毫无防备的状态，让我们有充足的时间发动进攻！现在，在我把你蒸发掉之前离开我的视线……"
D.Strings[5610]="遵命，长官。不会再出错了……"
D.Strings[5611]="有很多恶魔要去消灭，$c。你有没有勇往直前的气概？"
D.Strings[5612]="结束了吗？"
D.Strings[5613]="这一切都会——"
D.Strings[5614]="由于损失了大批恶魔，燃烧军团若是想要再次进攻我们的伐木场，必定会再三考虑的。无论怎样，我仍然感觉到恶魔的力量在活跃着。"
D.Strings[5615]="你，站住！"
D.Strings[5616]="我迷路了……"
D.Strings[5617]="为什么……？"
D.Strings[5618]="为我们尊贵的英雄欢呼吧！"
D.Strings[5619]="你的故事将被传颂！"
D.Strings[5620]="我终于有个故事可以讲给孙儿们听了……一个叛徒曾与我们生活在一起！"
D.Strings[5621]="说实话，我从来就没喜欢过那个侏儒……"
D.Strings[5622]="我们能够在这样的考验中生存下来，真是太幸运了。如果不是你，在岛上的每个人可能早已经被杀死了。"
D.Strings[5623]="我怀疑还有多少这样的叛徒混在我们中间。我认识斯巴克很多年了，却从未想到过他会是个叛徒。"
D.Strings[5624]="塔里有入侵者！"
D.Strings[5625]="阻止他们！"
D.Strings[5626]="我完了！"
D.Strings[5627]="主人……会生气的……"
D.Strings[5628]="准备战斗！"
D.Strings[5629]="保卫卡拉赞！"
D.Strings[5630]="干掉他们！"
D.Strings[5631]="我失败了……"
D.Strings[5632]="你会受到惩罚的！"
D.Strings[5633]="你……会为此……付出代价。"
D.Strings[5634]="[熊怪语] 谢谢你，$n！"
D.Strings[5635]="你胆敢打扰我？！"
D.Strings[5636]="你们不属于这里！"
D.Strings[5637]="离我们远点！"
D.Strings[5638]="这……不……公平……"
D.Strings[5639]="我还不想死！"
D.Strings[5640]="天下没有不散的筵席。"
D.Strings[5641]="你会毁掉一切的！"
D.Strings[5642]="滚开！"
D.Strings[5643]="我们不希望被打扰！"
D.Strings[5644]="我在哪里？这是怎么——"
D.Strings[5645]="发生了什么？"
D.Strings[5646]="我不能害怕……"
D.Strings[5647]="滚开，懦夫！"
D.Strings[5648]="别想破坏庆典！"
D.Strings[5649]="我们被包围了！"
D.Strings[5650]="命运在与我作对！"
D.Strings[5651]="我的命运终结了。"
D.Strings[5652]="不，不是现在！不是这样的！"
D.Strings[5653]="我会把你碎尸万段！"
D.Strings[5654]="我会像切鱼那样把你切碎！"
D.Strings[5655]="我要把你碎尸万段！"
D.Strings[5656]="我战斗到了最后一刻……"
D.Strings[5657]="这不是结局……这不可能！"
D.Strings[5658]="我尽力了，主人，我尽力了。"
D.Strings[5659]="%s指示你跟着他。"
D.Strings[5660]="%s指着库欧图腾。"
D.Strings[5661]="%s提醒你跟着他。"
D.Strings[5662]="[熊怪语] Ritk kin'chikx azul azure summit..."
D.Strings[5663]="[熊怪语] 库欧飞了起来……越过河流。找到提克提。"
D.Strings[5664]="[熊怪语] 你要走的路还很长。看到那条河了吗？沿着河走，找到尤尔。"
D.Strings[5665]="%s叫你跟随他。"
D.Strings[5666]="[熊怪语] 去吧……去河的尽头看看。南边！"
D.Strings[5667]="放肆！"
D.Strings[5668]="爱管闲事的蠢货！你们会为此付出生命的代价！"
D.Strings[5669]="别想活着出去……"
D.Strings[5670]="过来和我玩玩吧！"
D.Strings[5671]="你是我的了。"
D.Strings[5672]="过来，你有我想要的东西！"
D.Strings[5673]="所以我说，“没问题，但是你得多掏点。”"
D.Strings[5674]="就五秒。我没有开玩笑！"
D.Strings[5675]="他问我是否可以让小鬼一起来——你能相信吗？说实话，那还不是最糟糕的……"
D.Strings[5676]="他们事后睡着，而我中途就睡着了……"
D.Strings[5677]="再靠近我的话，我就要大叫了。"
D.Strings[5678]="我要给你看看我的另外一面……"
D.Strings[5679]="过程本身还是很有趣的……"
D.Strings[5680]="<叹气>总是这么快就结束了。"
D.Strings[5681]="我想要你和我在一起……永远在一起。"
D.Strings[5682]="嘘……我还保守着个小秘密。"
D.Strings[5683]="我非常非常淘气……"
D.Strings[5684]="别浪费时间了，让我们切入主题吧。"
D.Strings[5685]="事情才刚刚开始变得有趣。"
D.Strings[5686]="我们在一起很开心！"
D.Strings[5687]="[熊怪语] 过来，$n。我们一起离开水。"
D.Strings[5688]="[熊怪语] 我们现在一起走吧。我们会找到瓦克。"
D.Strings[5689]="[熊怪语] 跟我去找瓦克。"
D.Strings[5690]="别妨碍我！"
D.Strings[5691]="你在干什么？滚开！"
D.Strings[5692]="我会怀念这场表演的！"
D.Strings[5693]="是的，我想我现在记起来了……"
D.Strings[5694]="清理一下这个地方！"
D.Strings[5695]="你的票在哪里？"
D.Strings[5696]="这场表演只允许客人观看！"
D.Strings[5697]="你不该来这儿！"
D.Strings[5698]="来跟其他的客人做伴吧……"
D.Strings[5699]="你离死不远了……"
D.Strings[5700]="[熊怪语] 快点，$n。瓦克在等你。"
D.Strings[5701]="你不能呆在这儿！"
D.Strings[5702]="这儿不欢迎你！"
D.Strings[5703]="我可以下班了吗？"
D.Strings[5704]="终于，我的工作完成了。"
D.Strings[5705]="我不会被业余演员轻视的！"
D.Strings[5706]="这场表演必须继续下去！"
D.Strings[5707]="太冷了，太暗了……我没有夸张，我有吗？"
D.Strings[5708]="一定要确保我在墓碑上的名字拼写正确……"
D.Strings[5709]="你们的傲慢是无可容忍的！"
D.Strings[5710]="你可没受到邀请！"
D.Strings[5711]="啊……那道光……"
D.Strings[5712]="真的结束了？"
D.Strings[5713]="这儿可没好处让你捞，只有死路一条！"
D.Strings[5714]="禁止访客！"
D.Strings[5715]="终于……自由了。"
D.Strings[5716]="是时候继续前进了。"
D.Strings[5717]="[熊怪语] 瞧瞧敌人犯下的残忍罪行吧。刺臂熊怪掳走了我们的幼子……他们还只是毫无反抗力的孩子，却被关押起来。英雄，请你搭救他们吧！"
D.Strings[5718]="相同的命运在等待着所有窃取主人财物的家伙！"
D.Strings[5719]="死亡对你这种家伙来说太仁慈了。"
D.Strings[5720]="其他人会顶替我的位置的！"
D.Strings[5721]="这……改变不了任何东西。无尽的诅咒在等待着你！"
D.Strings[5722]="欢迎来到林歌神殿,$c。如果有什么我可以为你效劳的，请随时告诉我。"
D.Strings[5723]="回头吧，在你还有机会回头的时候……"
D.Strings[5724]="你们唯一的结局就是陷入永恒的诅咒！"
D.Strings[5725]="%s对着它的捕捉者咆哮。"
D.Strings[5726]="[熊怪语] 止松熊怪不会忘记你的勇敢！"
D.Strings[5727]="[熊怪语] 止松要塞像欢迎英雄般欢迎你！"
D.Strings[5728]="[熊怪语] 预言是真的！"
D.Strings[5729]="你们赢得了许多挑战……可惜到头来还是白费劲！很快你们的同胞就要向我的主人低头了！"
D.Strings[5730]="我失败了……和平是不可能出现的。"
D.Strings[5731]="怎么……？"
D.Strings[5732]="邪兽人！"
D.Strings[5733]="流血的循环看不到尽头……我什么都做不了吗？"
D.Strings[5734]="不要回来，德莱尼渣滓。下次我们不会留下你的小命，不管你是不是拿着武器！"
D.Strings[5735]="去死吧！"
D.Strings[5736]="你都干了些什么，玛库鲁？这不是我们的方式！"
D.Strings[5737]="我知道你的感受，玛库鲁。瑟丹毕竟是我的兄弟。然而我们不能通过反对他的理想来纪念他。"
D.Strings[5738]="这些兽人恨我们，欧巴迪！他们杀了我们这么多的同伴，死亡是他们应得的。"
D.Strings[5739]="不！不……瑟丹！兽人们必须付出代价！"
D.Strings[5740]="你闻到了吗？好像有新鲜的肉进入了我们的堡垒。警惕那些入侵者。"
D.Strings[5741]="入侵者！给我顶住！等我放狗出来！"
D.Strings[5742]="已经晚了，让我的狗撕碎你们吧！"
D.Strings[5743]="<步兵笔直地站着，全身的肌肉都紧绷着。>"
D.Strings[5744]="我们试着取得这个世界的人民的认同和帮助来抵抗燃烧军团，因此我们必须同样学会和他们和平相处。$B$B当你游历整个艾泽拉斯的时候，请铭记这一点。让圣光指引你吧。"
D.Strings[5745]="控制人类步兵"
D.Strings[5746]="我准备好飞去埃索达了。"
D.Strings[5747]="是什么风把你吹到这里来的，渺小的$r？"
D.Strings[5748]="$n，你准备好了吗？"
D.Strings[5749]="你好，$c。很少有客人会到我这里来。有什么我可以帮忙的吗？"
D.Strings[5750]="你勇敢地游到了我的领域，陆行者。"
D.Strings[5751]="我一直都期待着你的到来。"
D.Strings[5752]="我想要学习更多关于锻造的知识。"
D.Strings[5753]="你知道这是哪儿吗？这是荣耀堡，甜心！爱上它，或者滚出去！"
D.Strings[5754]="这不是野营，蠢货！你在外域！要么打起精神来，要么从黑暗之门滚回去。"
D.Strings[5755]="我既没有时间，也没有兴趣来和你解释什么，混账！现在你还有什么要说的吗？或者你来这里只不过是要我和你一起去喝杯酒，公主？"
D.Strings[5756]="你什么毛病？"
D.Strings[5757]="我看你在这里跳来跳去，为什么不帮大家一个忙，把你的装备全部脱了扔在军械库里面？"
D.Strings[5758]="以库德兰的名义，是谁让你穿越黑暗之门的？"
D.Strings[5759]="压低你的嗓门，$C！"
D.Strings[5760]="如果你有什么话要说，就快点！"
D.Strings[5761]="我很忙，快点！"
D.Strings[5762]="你和高阶女牧师谈过话了吗？她非常渴望听到你去朝圣的故事。"
D.Strings[5763]="你寻找印记的进展怎么样了？"
D.Strings[5764]="真是个好日子，$c！"
D.Strings[5765]="太感谢了，你让我的朝圣之梦成真了！"
D.Strings[5766]="我不喜欢这一个……"
D.Strings[5767]="你这蠢货！"
D.Strings[5768]="我们杀了他的朋友吧！"
D.Strings[5769]="你为什么就不能让我来说话？"
D.Strings[5770]="如果你对我好，我就让你活下来。"
D.Strings[5771]="是时间让公会派点新鲜血液给我们了！真不巧，你们辛辛苦苦来到这里，却什么都看不到。我们被禁止为客人们表演了，你能相信吗？莫罗斯禁止我们进行新的演出，我的支持者们都要发狂了！我们必须对莫罗斯做点什么了。"
D.Strings[5772]="终于万事俱备了。你准备好了开始进行首演了吗？"
D.Strings[5773]="我不是个演员。"
D.Strings[5774]="不用担心，你会没事的。你看上去很自然！"
D.Strings[5775]="好吧，那么我试试看。"
D.Strings[5776]="女士们，先生们，晚上好！欢迎观看今晚的演出！"
D.Strings[5777]="艾克提恩，哪里是狩猎月痕雄鹿的最佳区域？"
D.Strings[5778]="你可以在碧蓝岗哨的南面和东面找到月痕雄鹿。"
D.Strings[5779]="艾克提恩，哪里是狩猎月痕巨鹿的最佳区域？"
D.Strings[5780]="就在碧蓝岗哨的北面，你在那里很容易找到月痕巨鹿。$B$B狩猎愉快，$n！"
D.Strings[5781]="我在哪里能找到更多感染的夜行豹幼崽，主教？"
D.Strings[5782]="感染的夜行豹幼崽似乎是从北面来的，我建议你会从那边开始狩猎。"
D.Strings[5783]="哇，你完全炸毁了那里。让我们把这当作一次热身吧。你准备好再去一次了吗？"
D.Strings[5784]="是的，主人。一切都在按照计划进行。"
D.Strings[5785]="%s把贝壳举起来放在耳边。"
D.Strings[5786]="你看不到我很忙么？"
D.Strings[5787]="结束了，斯巴克。上将已经知道是你背叛了联盟。现在你是要与我合作，告诉我你知道的一切，还是和要与我为敌？"
D.Strings[5788]="观众们都很挑剔，但是你会征服他们的。准备再试一下吗？"
D.Strings[5789]="我会演好它的！"
D.Strings[5790]="女士们，先生们，欢迎观看今晚的演出！"
D.Strings[5791]="[熊怪语] Mil'ork kix ilfin o oomtor..."
D.Strings[5792]="[熊怪语] Poorov'tarkh!"
D.Strings[5793]="[熊怪语] Yar vartslaf?"
D.Strings[5794]="[熊怪语] Boro gomsho!"
D.Strings[5795]="为你那可怜的生命求饶吧！"
D.Strings[5796]="跑吧，懦夫！逃跑吧！"
D.Strings[5797]="你的痛苦让我愉悦！"
D.Strings[5798]="你需要什么帮助吗，陌生人？"
D.Strings[5799]="厄尔，我想要看看你出售的货物。"
D.Strings[5800]="古尔弗是我的名字，陌生人。勇敢的古尔弗！"
D.Strings[5801]="请教我如何剥皮，古尔弗。"
D.Strings[5802]="我是莫多，止松要塞的猎人长者。"
D.Strings[5803]="莫多，我希望成为一名制皮师。请让我接受训练。"
D.Strings[5804]="欢迎来到我的商店！"
D.Strings[5805]="啊，英雄来了。欢迎来到止松要塞。"
D.Strings[5806]="你好，$c。我是止松酋长，止松要塞的继承人。"
D.Strings[5807]="你就是那个会保护我的人民，并指引止松要塞进入一个新时代的英雄！"
D.Strings[5808]="尽可能多地清理掉感染的夜行豹……应该很简单。"
D.Strings[5809]="$n，谢谢你帮我疗伤！"
D.Strings[5810]="帮帮我！我觉得这东西对我来说可能比较棘手。"
D.Strings[5811]="有谁能听到我的话吗？我需要帮助！我快要被干掉了！"
D.Strings[5812]="我坚持不下去了！告诉主教说我尽力了。"
D.Strings[5813]="再次感谢！"
D.Strings[5814]="德莱尼人的又一场胜利！"
D.Strings[5815]="又一头感染的野兽被消灭了！"
D.Strings[5816]="你怎么能把自己和德莱尼勇士相提并论呢！"
D.Strings[5817]="哈哈！太简单了。"
D.Strings[5818]="我是来猎杀这些感染的夜行豹的……应该很简单。"
D.Strings[5819]="这些该死的鞭笞者在哪里？"
D.Strings[5820]="碧蓝金鱼草？这名字起得……丹达尔显然是疯了！"
D.Strings[5821]="这些鹿一点也不像塔布羊。"
D.Strings[5822]="我在想村子里那个紫色的生物是什么……看上去真漂亮。"
D.Strings[5823]="是时候和你的创造者碰面了，$n！"
D.Strings[5824]="要钱还是要命！事实上，我只要你的命……"
D.Strings[5825]="我要将你的生命作为献给大王的祭品！"
D.Strings[5826]="为了银月城！为了逐日者！"
D.Strings[5827]="我恐怕现在正忙着修理这些马蹄铁。你不介意另挑一个时间再过来吧？"
D.Strings[5828]="我曾经为麦迪文效劳过……或者可以说是假装效劳过。我帮助紫罗兰之眼监视着我的主人。$B$B不过现在我所做的只是制造马蹄铁。一个又一个。"
D.Strings[5829]="你对紫罗兰之眼有所了解？或许我待会有时间的话会跟你聊聊。$B$B现在我得继续做事。"
D.Strings[5830]="我想要学习你的铁匠技术，库雷恩。"
D.Strings[5831]="<艾拉兰看上去正在研究着某种毒草。>$B$B如果你在找人帮你制作爱情药水，那么你来错地方了。我的知识全都是关于配制致盲、致残甚至致命的毒药……你也有希望成为我这样的行家。"
D.Strings[5832]="可以一口把你吃掉呀！"
D.Strings[5833]="快跑呀，小姑娘，快跑呀！"
D.Strings[5834]="欢迎来到公会注册处。有什么我可以为您效劳的吗？"
D.Strings[5835]="你好，我的孩子。"
D.Strings[5836]="喔，奶奶，你的耳朵怎么这么尖？"
D.Strings[5837]="可以更好地听你说话啊，孩子。"
D.Strings[5838]="喔，奶奶，你的眼睛怎么这么大？"
D.Strings[5839]="可以把你看得更清楚啊，孩子。"
D.Strings[5840]="喔，奶奶，你的衣服怎么这么紫？"
D.Strings[5841]="你好，年轻的萨满祭司。"
D.Strings[5842]="让我们一起解决这水体的污染吧。"
D.Strings[5843]="你做了件伟大的事，$n。我们随时欢迎你来这里。"
D.Strings[5844]="大厨师，你能教我做一手好菜吗？"
D.Strings[5845]="需要一些锻造物资吗？"
D.Strings[5846]="我得到了足够的鲜肉、鱼和蘑菇。还有很多喝的！"
D.Strings[5847]="你好，$n。随着你在荣耀堡的声望不断提升，我将允许你使用一些我们库存的其它物品。"
D.Strings[5848]="让我看看我现在可以买些什么。"
D.Strings[5849]="入侵者来了……"
D.Strings[5850]="我是埃德门图斯，秘血岗哨的首领。"
D.Strings[5851]="欢迎来到萨尔玛，$n。随着你在萨尔玛的声望不断提升，我可以让你使用我们的更多物资。"
D.Strings[5852]="需要我来照顾你的动物伙伴吗？"
D.Strings[5853]="我想要寄放我的宠物。"
D.Strings[5854]="在阿古斯，玛凯雷是我们最庄严最神圣的城市。$B$B如果我告诉你，那里的人行道都是用贵重的矿石铺设的，那里的河流甚至在完全黑暗的地方都能闪闪发光，你能相信吗？$B$B我向往那些日子……多久了？一千年？还是一万年？"
D.Strings[5855]="搜索一下将小岛一分为二的河流，但是要多加小心，水里有很多臭角刺鱼。"
D.Strings[5856]="欢迎来到秘血岗哨，$c。在我的旅途中，我收集到了各种文明的工具、文物和知识。$B$B如果你需要这些知识，只管来问我就是了。"
D.Strings[5857]="顾名思义，你可以在洛雷萨兰废墟周围找到这东西。$B$B确切地说，这名字其实是我起的……很棒吧。"
D.Strings[5858]="邪锥这个名字起源于堕落的邪恶魔法。去纳兹维安萨特营地寻找邪锥蘑菇吧，就在西边。"
D.Strings[5859]="血蘑菇和其它蘑菇比起来就普通多了，几乎可以在秘血岛周围森林中的任何地方找到。如果你不想丢了小命，就到秘血岛上的大道南边找找。"
D.Strings[5860]="如果你只能在秘血岛学到一样东西，$c，我希望那是“警惕”。这座岛屿会首先吞噬那些粗心大意的新手，然而慢慢压垮那些哪怕是最谨慎的战士。$B$B无论在哪里，总有敌人想要取走你的性命。"
D.Strings[5861]="自从坠毁之后，我看什么东西都是模糊一片。仿佛登上埃索达已经是很久很久以前的事情了。$B$B现在，我的世界中充满了变异的生物和无尽的血精灵。很快，也许我就不会记得任何别的东西了……"
D.Strings[5862]="在其他人看来，这个地方只有死亡、堕落和灾难。说实话，这里确实充满了这些东西。但是那些观点忽视了这个全新的环境赐予我们的机会。$B$B我不会呆呆地站在这里，忽视那些宝贵的机会，$c。在你的帮助下，我们可以向秘血岗哨的其他人展示如何利用环境，以及生活在这种环境中的生物。"
D.Strings[5863]="你好，$c。$B$B凯希尔就在那边，他是个非常聪明的家伙，跟他打交道要非常小心才行。$B$B他给我提供了一个“照顾雷象”的工作，愚蠢的我认为这只是一个简单的喂养或者训练之类的工作。当他交给我一把铁铲的时候，我才知道那是干什么的……"
D.Strings[5864]="$n，谢谢你的提醒！我们这就着手准备！"
D.Strings[5865]="英雄，感谢你的警告。止松要塞会准备好的。"
D.Strings[5866]="感谢你的提醒，$n。我们会做好防御准备的。"
D.Strings[5867]="我是凯希尔，雷象之王，阿古斯之手的成员。你是新来的吗？"
D.Strings[5868]="面对刺臂部族的愤怒吧！"
D.Strings[5869]="谢谢你救了我，$n！我父亲会很高兴的！"
D.Strings[5870]="我是阿彻鲁斯，秘血岗哨远征军首席指挥官。"
D.Strings[5871]="我是往来于这里和秘蓝岛之间的邮差，$c。如果你有什么消息需要递送，很可能是要交给我来办的。"
D.Strings[5872]="成为一个阿古斯之手的意义是什么……我们是圣光的代言人。我们全心全意的服务，就算让我们去死，我们也勇往直前。"
D.Strings[5873]="是他们派你来找我的吗？我不会丢下伙伴独自回去的。"
D.Strings[5874]="哇！谢谢你了！"
D.Strings[5875]="对，我是一个破碎者。我相信这并不会让你觉得不安吧。破碎者或者德莱尼人，我们必须忍受可能遭受的嘲笑。和这个世界上的元素们更好地理解和沟通，这才是最要紧的事。"
D.Strings[5876]="早上好，$c。你需要可靠的角鹰兽吗？"
D.Strings[5877]="我想骑着角鹰兽旅行。"
D.Strings[5878]="如果你需要去埃索达，就乘坐我的角鹰兽吧！"
D.Strings[5879]="%s开始生锈了！"
D.Strings[5880]="嘘！安静点，我正在监视那些鱼人。$B$B住在这个大龟壳里是我对科学的献身精神的体现。毕竟，要是让那些鱼人看到我在这里，它们肯定会做出一些反应，这样数据就乱套了！$B$B作为探险者协会的第一名侏儒会员，我大胆地来到了矮人从未涉足的地方！"
D.Strings[5881]="你疯了吗？看看你的周围，凡人。你没看到你正站在崩裂的大地上吗？离开这个地方，免得遭受我和我们的人民所遭受的痛苦……"
D.Strings[5882]="为什么你要受苦？"
D.Strings[5883]="你是瞎了还是疯了？$B$B我是个鬼魂，一个早已不存在的远古文明的遗留者，永远滞留在这片我没能保护好的土地上。$B$B在一万年之前，我和你一样是个血肉之躯。我曾经是这块土地的王子，也是一个被梦境之龙伊瑟拉赐福的龙骑士。"
D.Strings[5884]="伊瑟拉是什么？你又是怎么得到她的赐福的？"
D.Strings[5885]="你从没有听说过伊瑟拉？大自然的守护者？翡翠梦境的守护？她是所有绿龙的女王！是的，伊瑟拉亲自将她的血脉赐予了我的王国。我们和那些高贵的生物并肩战斗，他们允许我们骑在他们身上，在战争中击溃一切敌人。就这样愉快地过了几个世纪……直到……"
D.Strings[5886]="直到什么时候？"
D.Strings[5887]="死亡之翼的子孙们……伊瑟拉的仁爱激起了死亡之翼——黑龙军团的首领的怨恨。他们在我们睡觉时发起了攻击！许多人死在第一次攻势中，但绿龙勇敢地前来保护我们。$B$B<托雷斯王子指了指岛屿的周围。>$B$B那些骸骨就是绿龙们的残骸。黑龙没有给他们留下任何活口。"
D.Strings[5888]="为什么你还在这里？"
D.Strings[5889]="我是最后一个牺牲的。当我的灵魂离开我那凡人的躯体时，我发了一个血誓。$B$B<托雷斯王子摇了摇头。>$B$B一个在我和这片土地之间建立的誓言：我的血属于这个世界。我变成了一个孤独地守候者，讲述着我的人民的故事。$B$B我不能休息，直到我确信洛雷萨兰龙骑士的故事不会随着时间的流逝而被遗忘。"
D.Strings[5890]="学生们有点像绵羊。当你教导和关心他们时，他们是有用的，甚至可能是讨人喜欢的。$B$B但是只要你离开他们一分钟，他们就会从悬崖上摔下去，或者淹死在河里。"
D.Strings[5891]="这个公告牌上张贴着多种公告和执行危险任务的奖励。现在没什么可以吸引你的东西，也许你应该过段时间再回来看看。"
D.Strings[5892]="朋友，向你致意。如果你没什么要帮忙的就径直往前走吧。"
D.Strings[5893]="温德索尔元帅一直都盼着你呢，$n。不幸的是，眼下他身染微恙，不过应该很快就能康复。"
D.Strings[5894]="你做到了！太了不起了！温德索尔元帅一直都盼着你呢。你要我现在就通知他吗？"
D.Strings[5895]="勇士，向你致敬。你所立下的丰功伟绩将代代传颂。或许有一天，你的雕像会矗立在暴风城的英雄谷。"
D.Strings[5896]="离我远点，$r！很难说我什么时候会再次发病。$B$B离我远点，免得出事！"
D.Strings[5897]="听着，人类。我不关心你们的约定，但是你们有我要的东西。告诉我在哪里可以找到血铸铁锭。"
D.Strings[5898]="你怎么知道这些矿石的？甚至连男爵都不知道……$B$B拿走那被诅咒的东西，它们除了厄运，什么都没有带给我。我把它们藏在院子里的马厩旁边。$B$B<兰登的喉咙里发出了一声低吼。>"
D.Strings[5899]="给我回去工作！"
D.Strings[5900]="醒醒！给我起来！回去工作！"
D.Strings[5901]="检查了尸体之后，你断定这就是伊斯塔·晨星，进攻戴索姆却惨遭失败的血骑士。"
D.Strings[5902]="我可以帮助你建立公会。"
D.Strings[5903]="翻遍血骑士的尸体之后，你找到了那枚徽章。它并没有因为战争和周围的环境而受到任何损伤。"
D.Strings[5904]="艾露恩祝福着你，有什么我能为你效劳的吗？"
D.Strings[5905]="快一点！你拖得越久，我给你的痛苦就会越多！"
D.Strings[5906]="这是啥？！你爸妈没有教你学点什么东西吗？"
D.Strings[5907]="这太糟糕了……抽这些懒骨头把我的胳膊都抽酸了！"
D.Strings[5908]="不要松懈！不要松懈！"
D.Strings[5909]="谢谢你，$c。你能来拜访我们实在是太好了。"
D.Strings[5910]="你对三人执政团的效劳是一种荣耀，$n。多保重。当库卢斯准备好了的时候，他会召唤你的。"
D.Strings[5911]="你好，$c。我是库卢斯，阿古斯之手三人执政团的成员。"
D.Strings[5912]="我眼睁睁地看着他们无情地鞭打着他，这对于那位残忍的军官来说似乎早已是稀松平常的事情。残酷的鞭笞让我几乎崩溃。$B$B当我看到守备官撒鲁安被他们鞭笞时，我开始哭泣。不是因为恐惧……而是因为看到一位执政官被如此折磨而感到悲伤。要是我能逃出去，要是……"
D.Strings[5913]="过了很长一段时间，守备官失去了知觉。他已遭受太多的严刑拷打。那个残忍的家伙——他的名字似乎是叫玛提斯——竟然往守备官那早已伤痕累累的身体上泼洒腐水。但撒鲁安并没有清醒过来。"
D.Strings[5914]="我想大声尖叫，却只能发出微微的声音。因为刚才的反抗行动，我很快就被打倒在地。当我躺在地上时，看到玛提斯在撒鲁安的尸体旁来回走动，显得非常焦虑。他曾说过如果撒鲁安死于他的折磨，那个希隆娜丝会活活要了他的命。"
D.Strings[5915]="希隆娜丝计划把撒鲁安……$B$B<由于作者死去，故事突然中断了。接下去的记录是一片空白。>"
D.Strings[5916]="你好，$c。如果你想学习铁匠技术的话，我想你来对了地方。"
D.Strings[5917]="我想学习锻造技术。"
D.Strings[5918]="哦，不用担心巴迪。他不会伤害你的，他不过是喜欢这样抓来抓去而已。$B$B他只是一只又大又可爱的猫而已。$B$B不是吗，巴迪？可爱的小东西，我的小宝贝！"
D.Strings[5919]="我们塞纳里奥的德鲁伊们是大自然平衡的保护者，我们的职责就是保持平衡。当我们被召唤的时候，就不应该在采取决定性的行动前等待太久。不要听信别人的理论，尤其是我们当中的那些只负责观察的人！"
D.Strings[5920]="%s失去了知觉。"
D.Strings[5921]="回库卢斯那里去吧。我会把他带到秘血岗哨的。"
D.Strings[5922]="别想活捉我！"
D.Strings[5923]="听候您的吩咐，大人。"
D.Strings[5924]="我希望你们全部去搜查那个罪犯，残忍的玛提斯。我将一把信号枪交给了一位可靠的阿古斯之手特派员。当你们看到闪光信号的时候，就意味着玛提斯被发现了。记住，必须把玛提斯给我活着带回来。"
D.Strings[5925]="%s呼唤他们的同伴。"
D.Strings[5926]="兄弟姐妹们，今晚我们要搜索一个名叫玛提斯的血精灵，把他带来接受审判！第一个找到他的人可以得到在埃索达的一星期休假！"
D.Strings[5927]="出发！秘血岛的冒险之旅在等待着我们！"
D.Strings[5928]="开始试炼吧！布拉维·血怒，给我上！"
D.Strings[5929]="勇士莱伦德·光痕，让我为你而骄傲吧！"
D.Strings[5930]="玛尔娅·迅刃，让这个家伙看看真正的血骑士是怎么战斗的！"
D.Strings[5931]="斯塔克·射日者，给$n点痛苦尝尝！"
D.Strings[5932]="干得好，$n！你通过了第二个试炼！"
D.Strings[5933]="你是谁？离我远点。"
D.Strings[5934]="我们准备好带你离开这里了，萨尔。出发吧！"
D.Strings[5935]="%s喷着鼻息。"
D.Strings[5936]="从北面开始寻找，$n。我们的斥候说跳跃引擎在海岸线附近。"
D.Strings[5937]="跟我说说你的故事吧，预言者。"
D.Strings[5938]="我的故事？很高兴你问起这个。$B$B很久以前，在德拉诺世界——它的遗迹就是你所知道的外域——所有的德莱尼人都和平地生活着。但是燃烧军团来了，他们用魔法腐蚀了兽人。$B$B为了生存，我们除了战斗之外别无选择，但是这些魔法能量的辐射对我们中的一些人造成了可怕的影响，一段时间之后，我们变成了像我这样的破碎者，或者更糟糕的，变成看起来可以说是愚昧无知的失落者。$B$B要我继续说下去吗？"
D.Strings[5939]="是的，请继续。"
D.Strings[5940]="那些魔能作用在我们破碎者和失落者身上，切断了我们和圣光之间的联系。那时我完全不知道这到底是怎么回事，但是作为一名守备官，我一定要找出答案。于是我决定为了这个目的进行一次朝圣。$B$B因此在战争结束之后，我来到了那个破碎世界的沙漠中，祈求圣光回到我们身边。但是十年过去了，圣光从未答复我的祈祷。$B$B你还想听下去吗？"
D.Strings[5941]="请继续说下去，如果你不介意的话。"
D.Strings[5942]="幸运的是，我在那里找到了一片绿洲，我下定决心待在那里，直到我得到一个答复。所以我就坐在那里，只有在迫不得已的情况下才做出别的举动，依靠池塘周围的生物维系我的生命。那可真是我的骄傲啊。$B$B就像我说的那样，十年过去了，没有任何答复。但是我却记得那天晚上美丽的夕阳。一股温暖的风拂过大陆，我确信我听到了某个声音，但是没有人在我周围。$B$B就像你所能想象到的那样，我觉得我终于疯了。"
D.Strings[5943]="努波顿，请继续。"
D.Strings[5944]="那阵风有些异常，它丝毫没有停止下来的意思。风就这样刮过整个大陆，持续了几个星期，一会儿强一会儿弱，但从不停止。而且那个声音始终持续着，尽管我听不懂那是什么意思，也不知道它是从哪来的。$B$B在我独处的那段时间里，我学会了冷静和洞察问题的本质。我之所以这样做，是为了保证我还心智健全。那时，我突然开始听懂了那个声音。它从风中传出，而且它有很多话要说！"
D.Strings[5945]="它对你说了什么？"
D.Strings[5946]="它告诉了我秘密和力量，同样也告诉我了真相。圣光并没有遗弃破碎者！很久以前，兽人用来对付德莱尼人的魔能已经侵入了我们的躯体，使我们聆听圣光的能力被封闭了，同时也导致了我们身体的退化。$B$B但是我们的灵魂并没有被封闭，空气给了我另一种选择，让我可以指引我的人民。"
D.Strings[5947]="它教我领悟了萨满之路，那实际上是圣光的另一种表象。风与绿洲里的水、营地中的火焰和我脚下的大地是一体的，它们都要向我表达些什么。$B$B在随后的几年内，它们教会了我召唤元素和融入元素的力量。它们告诉我，天上的群星以及这个世界的万物，都是由这些元素构成的。$B$B当我觉得自己已经学到了足够多的知识之后，我离开了那里。"
D.Strings[5948]="我回到了我的人民身边，到处都是问候的笑脸和友善的手臂，大部分都是破碎者。许多德莱尼人对我们仍持有偏见，但他们似乎知道我要回来，果然不久之后我就知道了原因。$B$B维伦，全体德莱尼人的先知和领袖，在他的梦境中看到了我们的回归，他同样赶来问候我。他要求我和他私下谈话，于是我向他讲述了我的故事。他点了点头，露出了微笑，这一切和他预知的完全一样。"
D.Strings[5949]="维伦力劝我接受破碎者领袖的职位。但是更重要的是，他要求我来向所有破碎者和德莱尼人传授萨满的教义。我同意了他的建议。$B$B我们知道，在别人充满偏见的目光中，这是一项困难重重的提议，有人轻视我们破碎者，因为我们让他们想起了可怕的过去。而另一些人则相信萨满之路是对圣光的亵渎。$B$B无论如何，这就是我的故事。"
D.Strings[5950]="如果我们的敌人了解到我们唯一的愿望就是和他们和平共处的话，也许我们就不必进攻他们来换取我们自己的生存了？"
D.Strings[5951]="他们的末日就快来了，$n。$B$B到那一天，我肯定会在场的。"
D.Strings[5952]="新的敌人就在我们的家门口，我们绝对不允许我们的宿敌趁火打劫！"
D.Strings[5953]="你觉得这地方怎么样？当然，如果你问我的话，我觉得挺乏味的。"
D.Strings[5954]="你说，你看到西面那个拱形的东西划过湖泊吗？我在想那东西去哪里了……也许我应该潜水到那里去看看。"
D.Strings[5955]="恶心的真菌巨人！我们到底欠他们什么？"
D.Strings[5956]="要是我没有在这个地方扭了脚，现在我就应该在那里，和朋友们在一起。嗯，让我先想想如何走出这里？"
D.Strings[5957]="弗沃尔喜欢孢子人。他们救了弗沃尔。弗沃尔不吃他们。$B$B弗沃尔讨厌纳迦。"
D.Strings[5958]="我是伊索姆，阿古斯之手三人执政团的老三。"
D.Strings[5959]="这里躺着除草者格林萨姆的遗体，他是观察者杰哈恩的德鲁伊同伴。显然，当他想要逃出奴隶围栏时，他被迅速杀害了。"
D.Strings[5960]="我几乎要成功了！$B$B我来到这里是为了证明传说中的真菌巨人夸格米拉的存在。我完成了自己的愿望……理论上。$B$B你必须让我重获自由！作为回报，我会帮助你解决夸格米拉。"
D.Strings[5961]="好吧，拜特。我会让你出来。"
D.Strings[5962]="啊呀！看来你所制造的噪音已经引起了一些不必要的注意！"
D.Strings[5963]="谢天谢地多亏有了你！克劳恩和我正在调查这个地方时，沼地领主穆塞雷克突然出现在我们面前。$B$B不幸的是，克劳恩被他抓住了，而且他当时正在熊形态下，现在他变成沼地领主的宠物了。$B$B如果你要去救克劳恩的话，恐怕得跟他打一架。"
D.Strings[5964]="作为唯一幸存的破碎者，将预言者努波顿的萨满教义传播下去是我的荣幸和职责。"
D.Strings[5965]="该死的血精灵和他们不顾后果的魔法！"
D.Strings[5966]="不要浪费我的时间。你需要什么？"
D.Strings[5967]="被猎人抓去做宠物真是太丢人了！$B$B我欠你一条命。既然你已经把我从穆塞雷克手中救了出来，那么我自己就能找到出去的路了。"
D.Strings[5968]="观察者莉萨奥，你在这里干什么？"
D.Strings[5969]="愿圣光屈从于你的意志。"
D.Strings[5970]="在大自然中存在的所有东西都有着相互的联系，这被称作生态系统。如果我们小心地不去打扰它，通过简单的观察便可以了解到我们周围不同的生物体之间的复杂关系。$B$B一旦我们理解了这些，就可以采取适当的行动来保证所有生物的生存。反之，在没有这种认识的情况下去干预的话，就会引起破坏。$B$B我在这里观察孢子人和沼泽领主之间的复杂关系。"
D.Strings[5971]="$n，让我们看看这个计划是否有效。过来，巴迪！"
D.Strings[5972]="嗯，让我看看能否用那些你带回来的蘑菇制作一种食物喂给沼泽领主吃。"
D.Strings[5973]="巴迪，别闹了！看，这东西有效，真的有效！！现在我要做的就是在这里多培育一些这种蘑菇，我想那些沼泽领主会很可能会就此远离孢子人的。"
D.Strings[5974]="啊，谢谢你，$n！你成功地从沼泽领主手中拯救了孢子人，同时从我们的愤怒中拯救了沼泽领主。"
D.Strings[5975]="%s拿起一片蘑菇在它的“鼻子”旁闻了闻。它看上去很满足的样子，把蘑菇吃了下去！"
D.Strings[5976]="%s把剩下的蘑菇树连根拔起，然后卷走了它。"
D.Strings[5977]="等一会看看有什么事情发生！"
D.Strings[5978]="<守备官伊索姆向你致敬。>$B$B你和德门图斯说过话了吗？我想他正在找你。"
D.Strings[5979]="德鲁伊们保护我不受邪恶的纳迦和失落者的伤害。作为交换，我向他们传授有关这片沼泽中的植物和动物的知识。"
D.Strings[5980]="我被锁在这个笼子里，你应该感到庆幸，$r。"
D.Strings[5981]="<被俘虏的炎鹰间谍猜疑地盯着你。>$B$B我以前从来没有见过你。你是谁？"
D.Strings[5982]="我是个囚犯，你看我像什么？肮脏的德莱尼人在我走出太阳之门的时候抓住了我。他们杀了我们的传送门控制者，并且摧毁了太阳之门。凯尔萨斯大王一定会非常生气的。"
D.Strings[5983]="<被抓获的炎鹰密探开始傻笑。>$B$B别担心，新人，我们有很多传送门控制者和更多适合打开传送门的位置。我确信希隆娜丝将会很快建起一座新门。这些蓝皮肤的杂种们不会在这个世界上活太久了。无论如何，希隆娜丝和她的畸变者都会帮助炎鹰部队善后的。"
D.Strings[5984]="啊，对，我几乎忘了希隆娜丝这回事了。我为希隆娜丝效劳的日子可以追述到外域去，不过我从没有听说过这个“畸变者”。那些该死的德莱尼人在我还没有完全走出太阳之门前就抓住了我。"
D.Strings[5985]="那是希隆娜丝的主意……那个畸变者，确切地说，是一个德莱尼人。他是个德莱尼军事统帅部的高级成员，好像是叫三人执政团或者类似的东西。$B$B不管怎么说，他都是个魁梧、强大、充满愤怒的家伙。只要畸变者还在，任何针对矢量感应器的进攻都完全是浪费时间。"
D.Strings[5986]="不可思议。希隆娜丝是怎么做到这一点的？"
D.Strings[5987]="希隆娜丝声称，某些艾瑞达人拥有把其他种族转变成堕落者的能力。德莱尼人曾经是艾瑞达，而且希隆娜丝是个强大的艾瑞达。$B$B<间谍大笑起来。>$B$B你能相信吗？这些可怜的生物曾经都是强大的恶魔，但他们却拒绝了这种力量，多么愚蠢的家伙啊！"
D.Strings[5988]="希隆娜丝是个艾瑞达人……我是说，当然，这很明显。"
D.Strings[5989]="很明显，不然她怎么能渗透到他们中去，变成一个德莱尼人的模样？她和他们一起生活了很长时间。"
D.Strings[5990]="矢量感应器非常巨大。我希望我们能有更多的畸变者去看守其它几个弱点。"
D.Strings[5991]="几个？有两个弱点：建筑底层的西面和建筑底层的东面。嘿，等等。你怎么知道关于矢量感应器的事情的？你不是说你在你显身之前就被抓了吗？"
D.Strings[5992]="是啊，而且你相信了我。感谢你的情报，血精灵。你真是帮了我们好大的忙。"
D.Strings[5993]="摧毁矢量感应器的时机到了！"
D.Strings[5994]="现在已经没有退路了，$n。靠近我，小心背后。"
D.Strings[5995]="就是这个！你看到矢量感应器上突起的红色水晶了吗？那就是放置第一组炸药的地方。"
D.Strings[5996]="掩护我！"
D.Strings[5997]="不需要太久的，$n。不要让他们接近我。"
D.Strings[5998]="搞定了！快找掩护！"
D.Strings[5999]="不要过于兴奋，英雄，这只是最简单的部分。真正的挑战正在等着我们呢！走吧。"
D.Strings[6000]="那是什么东西？！"
D.Strings[6001]="做好准备，$n。"
D.Strings[6002]="圣光在上！她正在吸取矢量感应器的能量！"
D.Strings[6003]="掩护我，我们必须再快点。一旦我炸开了这边，就会破坏能量光束，她一定会冲出来的！我想她不会很高兴见到我们的。"
D.Strings[6004]="快完成了！只要再多一点时间……"
D.Strings[6005]="快找掩护！准备为你的性命而战吧，$n！"
D.Strings[6006]="沃洛斯在上！天啊！"
D.Strings[6007]="我……我简直不敢相信。你成功了！你消灭了血精灵和他们的首领！"
D.Strings[6008]="回秘血岗哨吧。我会在那里和你碰面……"
D.Strings[6009]="狂妄的孩子们，在你们快要见到你们的神明之前向他祈祷吧！"
D.Strings[6010]="我在耐心等候命令，$c。"
D.Strings[6011]="嘿！过来！对，过来……我在这个笼子里面！！！"
D.Strings[6012]="现在终于安全了，就像我刚才所说的那样，夸格米拉就在附近！$B$B我说到做到，现在我可以给你施加一个强化魔法，应该可以在你和他的战斗中帮到你。"
D.Strings[6013]="博学者，请给我施加这个魔法吧。"
D.Strings[6014]="[不流畅的通用语] 该庆祝了。"
D.Strings[6015]="英雄，你还记得我们吗？你还记得库尔兹的预言吗？这是个命中注定的时刻。你完成了你与生俱来的使命。$B$B<止松老酋长在你面前鞠躬。>$B$B德莱尼人会永远受到我的人民的欢迎。"
D.Strings[6016]="$n，这一路累得够呛吧。可算是长途跋涉啊……但是我相信，你注定要经历这许多不寻常的故事。我们都相信。向你致敬，$n！$B$B再次感谢你帮我们解决了这件麻烦事……"
D.Strings[6017]="你可能不记得我了，但是你救了我的命。我最近才刚刚恢复健康，可以自己下地行走了。$B$B我想感谢你为我做的一切，并为我所说过的话道歉……谢谢你，$n。希望艾露恩永远保佑你。"
D.Strings[6018]="我这辈子都不会忘记的，$n。$B$B<大主教梅内莱厄斯拥抱了你。>$B$B我们为你感到骄傲。"
D.Strings[6019]="很高兴再次见到你，$n。我带了个朋友过来，她非常想见到你。$B$B<凯希尔大笑起来。>"
D.Strings[6020]="我特地穿越无尽之海来看你，朋友。我们永远都不会忘记你为我们所做的一切。"
D.Strings[6021]="我想再次感谢你为我做的一切。你给了我驱赶森林中的野兽、夺回了我的家园的勇气。而且，我还找到了麦戈薇！"
D.Strings[6022]="德莱尼人的勇士和我们在一起。为秘蓝岛和秘血岛的救世主欢呼吧！"
D.Strings[6023]="这一切都是你的成就，$n。你成功地拯救了成千上万的人。$B$B你已经超越了这个世界上的冲突和灾难，让我们与你一起升华。$B$B你的功绩，许多人十辈子也无法达到，而你的旅程才刚刚开始。如果我们有几千个像你这样的英雄就好了。$B$B但是，$n，你的命运在外域等待着你。我从幻像中看到了一个不甚明了的预言。$B$B找到我们的人民，$n。找到他们，带他们回家……"
D.Strings[6024]="为秘蓝岛和秘血岛的救世主$n欢呼吧，阿古斯之手的英雄，德莱尼人的勇士！"
D.Strings[6025]="我们不能让我们的卫兵倒下，$C。这个世界布满了燃烧军团的爪牙和同盟，如果你发现了任何奇怪的东西，就立即告诉我。"
D.Strings[6026]="伊谢尔预计那些与她为敌的家伙也会入侵外域，这便是我们驻守此地的原因。$B$B我们可不愿看到敌人以超过那些纳迦军队的规模大举来犯。"
D.Strings[6027]="我不知道你是谁，但是我欢迎你的到来。阿克蒙德和他的天灾军团随时都有可能向我们进攻，$C。你会和我们一起面对这些恶魔吗？"
D.Strings[6028]="谢谢你，$c。好好准备一下。阿克蒙德正在行军，我们必须尽可能在这里坚守得更久一些。"
D.Strings[6029]="我们必须继续守住这里，越久越好！战斗到底！"
D.Strings[6030]="我是秘血岗哨的防务首领，有什么我可以帮你的吗？"
D.Strings[6031]="[不流畅的通用语] 止松要塞准备好了！非常感谢！"
D.Strings[6032]="你好，你是不是到这里来了解秘血岛事态的？"
D.Strings[6033]="我们无条件地为圣光效劳，也许你可能会对我们的目的感到好奇？"
D.Strings[6034]="告诉我关于防御者的事情吧。"
D.Strings[6035]="前面安全吗？让我们离开这里吧，$n。"
D.Strings[6036]="看起来没那么容易逃脱。做好准备！"
D.Strings[6037]="继续前进吧，这里并不安全！"
D.Strings[6038]="小心，$n！敌人就在前面！"
D.Strings[6039]="我们快到庇护所了！加油。"
D.Strings[6040]="欢迎来到血骑士的总部，我们是奎尔萨拉斯的防御者，银月城的忠实仆从，圣光的真正主人。"
D.Strings[6041]="大自然喜欢那些希望去了解它的秘密的人，$n。"
D.Strings[6042]="自然是一种强大的力量，$r。那些尝试征服它的人从来没有成功过。"
D.Strings[6043]="这些灵魂在躁动，$r。在纳格兰游历的时候留心你的周围，以免你被他们的愤怒吞噬。"
D.Strings[6044]="大地之环会设法维护元素们的权威和力量。"
D.Strings[6045]="在元素们陷入混乱的时刻，我们的人民怎么能战斗？难道他们不知道这个世界完全无法脱离元素的支持而存在？"
D.Strings[6046]="我是大地之环的温塔格。当你在元素王座逗留时，请尽量不要去打扰元素们。"
D.Strings[6047]="抱歉，$c。我把你错认成个有骨气的人。滚开，我们的秘密不是那些没经过训练的家伙有资格知道的。"
D.Strings[6048]="我现在没有时间来说教，$c。到别的地方去寻找你的知识吧。"
D.Strings[6049]="你好，$n。我希望你不是被跟踪到这里的？"
D.Strings[6050]="我们没什么可谈的，$c。也许你应该去找和你志趣相投的人。"
D.Strings[6051]="我很高兴看到有个心智健全的$r在这里。有什么我可以帮你的吗？"
D.Strings[6052]="啊，一个猎人伙伴。你需要什么？"
D.Strings[6053]="很明显你缺乏控制复杂的奥术能量所必需的能力，$c。闪开点。"
D.Strings[6054]="有什么我可以帮你的吗？"
D.Strings[6055]="我们只接受那些拥有钢铁般坚定的意志、怀着永不动摇的决心的同伴。似乎这两样优点你都不具备，$C。"
D.Strings[6056]="你是来寻求进一步的指导的吗，$n？"
D.Strings[6057]="这片土地被坠毁搞得一团糟。虽然你也许并不认同我们的哲学，$c，但是我期盼你尽量帮助别人。"
D.Strings[6058]="你好，我的$g兄弟:姐妹;。今天你需要怎样的指引呢？"
D.Strings[6059]="愿风指引你，$n。"
D.Strings[6060]="这本书包含了外域的植物种类的信息，其中大部分被详细介绍的植物产自赞加沼泽。$B$B书中的文字和图表可能有点超越你的理解能力，也许作者可以给你一些指点。"
D.Strings[6061]="我一直喜欢有条理的事情。我想这是我母亲的遗传。"
D.Strings[6062]="快乐源于秩序，公民。"
D.Strings[6063]="遵守银月城的法律。违法者将被消灭。"
D.Strings[6064]="要坚强起来。凯尔萨斯——错误——洛瑟玛会指引你们走向力量和光明！"
D.Strings[6065]="不要破坏城市的宁静。必须维护和平。"
D.Strings[6066]="我不知道该怎么看待你们这些$r。你们中的一些人可能会粗暴地杀害所有他所看到的孢子人。$B$B你看起来还算友好……尽管有点可笑。我希望如此。"
D.Strings[6067]="维护银月城的秩序。"
D.Strings[6068]="欢迎你来到孢子村，$r。通常在这附近看不到很多你的同类，但是你向我们证明了自己的价值。请不要拘束。"
D.Strings[6069]="沼泽领主正在吞食孢子囊！必须阻止它们！"
D.Strings[6070]="$n，你保护了我们年轻的族人。前往孢子村，跟我的同胞们碰面吧。你的美名早就在他们中流传开来了。"
D.Strings[6071]="我们听从你的调遣，血骑士。"
D.Strings[6072]="秘血岗哨的防御者抵御着任何针对这座哨所的威胁。"
D.Strings[6073]="防御者们在这里抵御着来自炎鹰部队的威胁。"
D.Strings[6074]="我们最近听说有一个拥有巨大力量的生物在矢量感应器附近被召唤了出来。我们不畏惧任何威胁，我们会用自己的生命来捍卫这里！"
D.Strings[6075]="<大地的隆隆声因为戈达乌暂停移动而停了下来。>$B$B说。"
D.Strings[6076]="为了太阳之王——呃——银月城的荣耀！"
D.Strings[6077]="%s朝卫兵们生硬地鞠了一躬，他板着脸，心中十分不情愿。"
D.Strings[6078]="%s的目光扫过一个个卫兵。"
D.Strings[6079]="%s俯视着那窄小的游侠练习场，作出一副谦逊的笑容。"
D.Strings[6080]="%s略微地歪了下头，向卫兵表示问候。"
D.Strings[6081]="我父亲去了更光怪陆离的地方寻找更大的猎物。不用担心，我们还会在这里继续打猎！"
D.Strings[6082]="保持警惕，$c。当野兽潜行靠近你的时候，你永远不会察觉得到。"
D.Strings[6083]="赫米特·奈辛瓦里，你在外域干什么？"
D.Strings[6084]="听着，$g小子:小姑娘;。我把远征队交给了我可靠的儿子，赫米特·奈辛瓦里二世。当你杀过全艾泽拉斯最凶猛的野兽之后，你就会开始渴望更多。$B$B你看到这里野兽的个头了吗？！$B$B我在这里猎杀着你所见过的最危险的猎物。我打算亲自抓住塔丝克，把她的徽记带回去做战利品。"
D.Strings[6085]="$n！我对你的狩猎能力印象深刻，你在荆棘谷的开始并不是那么如意，但你坚持到了最后，并且当你捕获了虎王邦加拉什后，你已经成为了最好的猎人之一。$B$B不过听好了，$g小伙子:小姑娘;，外域这里的猎物真的很难对付，我的伤疤可以证明这一点。"
D.Strings[6086]="普罗德摩尔女士的部队为了拖延阿克蒙德和他的燃烧军团，已经经历了一场恶战。现在这个严酷的任务摆在了我们的面前。你准备好面对他们的冲击了吗？"
D.Strings[6087]="我谦卑地欢迎你来到我们的神殿，灵魂。"
D.Strings[6088]="和那些在我们受苦的时候抛弃我们的德莱尼人协商？我不这么想。$B$B真正的灵魂是不会说出这种话的！露出你的真面目吧，骗子。是谁派你来的？"
D.Strings[6089]="这么看来，我们要不要信任那些使用这种诡计来欺骗我们的家伙呢？是不是德莱尼人对我们的感受毫不在意，以至于认为他们必须凭借欺骗来取得我们的注意？$B$B我们知道，他们想要“救赎”我们，但是我的人民不需要他们的救赎。我们会靠自己的能力生存下去，并自豪地、独立地向着我们的命运前进。把我的话带给你的同盟吧。"
D.Strings[6090]="那么让燃烧军团尽管使出他们的手段吧！"
D.Strings[6091]="燃烧军团紧紧逼迫着我们，但是我们顶住他们潮水般的进攻。阿克蒙德接近世界之树的时间越晚，我们离胜利就越近一步。"
D.Strings[6092]="好，一定要让他们理解。$B$B现在，如果你能离开我的神殿，我会非常感激的。"
D.Strings[6093]="朋友，欢迎来到奥雷柏尔营地。在这里你没有什么可以感到恐惧的。我们是破碎者，但并不是你的敌人。$B$B我是库雷尼的伊库提，我们是一群期望和德莱尼兄弟以及他们新结识的同盟们重建联系的破碎者。"
D.Strings[6094]="玛克图不认识你，$r。但是他很高兴和你相识。如果你需要购买或修理，就找玛克图。"
D.Strings[6095]="给我看看你的货物，玛克图。"
D.Strings[6096]="这座神殿留给我的记忆好像一层浓重的雾，至今我都不能把它组织成一个连贯的故事。这个地方应该曾经对我意味着什么……除非我能恢复那部分记忆，否则我会觉得我的记忆缺少了什么。$B$B也许德莱尼人可以帮助我恢复失去的记忆。"
D.Strings[6097]="让我看看你出售的材料和毒药。"
D.Strings[6098]="有些人叫我“提姆”，但是对我的朋友来说，我是“专家”。"
D.Strings[6099]="专家，嗯？那么你是哪一方面的专家？"
D.Strings[6100]="坦率地说，你还不够和我熟络到可以使用那个昵称。"
D.Strings[6101]="你好，$c。你想突破你的狩猎能力的极限吗？不用到处寻找了。$B$B赫米特·奈辛瓦里集合了这个世界上最好的探险队员。如果你够胆，就加入我们的队伍吧。"
D.Strings[6102]="不要被我们周围的废墟所蒙蔽，$c。达拉然仍然像以前那样强大。"
D.Strings[6103]="卡拉赞不仅仅是一座建筑物，$n。如果你追踪那些穿越艾泽拉斯的魔网能量线，就会发现它们全部都聚集在这里。$B$B<奥图鲁斯指了指高塔下方的一个看不见的位置。>$B$B非常迷人吧，不是吗？"
D.Strings[6104]="大法师奥瓦鲁克斯曾经写过一篇论文，探讨一个非常迷人的理论。他提出在另外一个世界有个原样复制的卡拉赞，而且两个卡拉赞之间由于某种未知原因共享着相同的空间。$B$B他不久以后就疯了。多遗憾啊。"
D.Strings[6105]="那些声名狼藉的罪犯与凶兽的悬赏被张贴在这里。对现在的你来说，这些悬赏实在太危险了，当你变强后再回来看看吧。"
D.Strings[6106]="纳鲁的智慧远远超出我们的理解。在过去的五个月里，我从阿达尔那里学到的东西，远比我这么多年在达拉然图书馆里学到的还多。"
D.Strings[6107]="通缉令上画着一条粗大的红色横线：死爪。“这笔赏金已经被英勇的$n领走了，他战胜了那个可怕的野兽。”以相同的红墨水书写的声明叙述了更多的细节。"
D.Strings[6108]="这块公告牌贴着各种通知与奖赏单。"
D.Strings[6109]="欢迎来到萨布拉金，$c。 我是暗影猎手德恩加，这个前哨站的督军和暗矛部族在赞加沼泽的司令官。"
D.Strings[6110]="别妄想把我的鱼人宝宝从我身边夺走！我有鹰的眼睛和像……像……有着强大力量的什么东西的耳朵！"
D.Strings[6111]="托尔加什相信他可以通过鸟的肠子或者通过摇骨头预测未来。但实际上，你所要做的就是询问那些灵魂。不过别告诉他这些，$n。他是个很固执的家伙。"
D.Strings[6112]="你已经证明了自己是个合格的猎人，$n。但是还有一种猎物令你寝食难安……那就是塔丝克！"
D.Strings[6113]="你猎获了巴克洛尔、班塔尔和裂肠者，甚至连强大的塔丝克也不是你的对手！你是我所认识的最优秀的猎手！"
D.Strings[6114]="我曾和一头塔布羊在荆棘丛里面厮打、肉搏，我那把锋利的匕首……<咳嗽>……和猎人的智慧拯救了我。$B$B突然，一对凶猛的雄性狩猎风鹏从天空中落到我的面前！它们卑鄙的攻击……<咳嗽>……一点作用都没有起。$B$B不久以后，我就把它们的喙拿来当战利品了。我的伤口在这次搏斗中感染了，有点烦人的是，我现在很痛，但我相信会在一两天内痊愈的。"
D.Strings[6115]="那是第一次我看到比树还高的蘑菇，我不是确定是否可以把这个地方当做家。过了一会儿你才转移了视线。"
D.Strings[6116]="我想要购买商业技能所需的工具。"
D.Strings[6117]="不要忘记当你在赞加沼泽的时候花点时间钓鱼。你从不知道什么时候你会再次看到水。"
D.Strings[6118]="我想要购买渔具。"
D.Strings[6119]="指点一下我的钓鱼技术吧。"
D.Strings[6120]="泰雷多尔对德莱尼人牧师和朝圣者来说曾经是个隐密的据点。很少会有人拜访这些隐居的牧师。$B$B当兽人开始攻击德莱尼人的时候，难民的数量多到无法想象。学者安霍尔和其他人把泰雷多尔从一座神殿转变成了一处避风港。很多德莱尼人，包括我自己，都很感谢他为拯救我们的生命所做出的一切。"
D.Strings[6121]="在泰雷多尔顶部观景真是华丽啊，难道不是吗？"
D.Strings[6122]="欢迎来到泰雷多尔，$c。如果你有任何事情需要帮忙，尽管来找我。"
D.Strings[6123]="我从没有在同一个地方看到过这么多的蘑菇。给我足够的时间，我保证可以找到它们的所有用处。"
D.Strings[6124]="泰雷多尔在过去的二十年里所见证的变化，远比过去的几个世纪还要多得多。我不是在抱怨，$n。世界在那段时间里改变了很多。$B$B圣光给我带来了许多朋友和同伴，如果我还是一个闭门冥思的牧师，就根本不会有这种机会。好好利用你在这里的时间来学习一切知识吧，这可以帮助你了解你的旅程和你的目标。"
D.Strings[6125]="暗影猎手德恩加派我、建筑工和一些战士到这里来建立这座哨所。我们刚刚完工，他就已经要求汇报了！$B$B如果你需要补给，我可以给你提供一些东西，但是我们仍然在等待第一批物资。"
D.Strings[6126]="如果你有机会遇到巫医托尔加什，告诉他，他的药和符咒不起作用！我完全按照他告诉我的去做，但是玛加沙仍然只把注意力放在祖莱身上。$B$B不敢相信巫医告诉我的事情竟然是假的。"
D.Strings[6127]="里维伊的脸皮就像科多兽那样厚！可笑的是，他并不觉得他的骚扰行为是这么的明显。我看到他直勾勾地盯着我，还自以为没人发现他。$B$B他让我觉得毛骨悚然，我真的希望暗影猎手德恩加没有派他和我们在一起。建造沼泽鼠岗哨原本是一个摆脱他的好机会。"
D.Strings[6128]="你好，$c。我是被他们叫做破碎者的家伙。就像失落者那样，只不过还没像他们那么糟糕。邪能的摧残让我们从原来德莱尼人的形态转变到现在的这个样子。"
D.Strings[6129]="加拉达尔现在很混乱，陌生人。自从祖母生了病，加尔鲁什变得非常沮丧。他真是一点都不像他的父亲。$B$B<古库斯叹了口气。>"
D.Strings[6130]="终于结束了！一切都终结了！为你们的世界默哀吧！Hach min corai！"
D.Strings[6131]="不，这不可能！不！！！"
D.Strings[6132]="暗潮纳迦氏族和血鳞纳迦氏族首领的悬赏布告被列在这里。听说他们两个都非常危险，也许你应该以后再去看看。"
D.Strings[6133]="暗潮纳迦氏族和血鳞纳迦氏族首领的悬赏布告被列在这里。"
D.Strings[6134]="他们死了。他们全都死了……$B$B暗血氏族突袭了我们，一些我不能理解的事情充斥着我的大脑。告诉我，你有没有感到过就像你的整个生命都在燃烧那样的愤怒？一种足以让生命枯萎的愤怒，一种足以烧尽你的血液的愤怒……那就是我所感觉到的。$B$B<萨鲁法尔的眼中闪过了血红色的光芒。>$B$B我是最后一个幸存者。他们三十个人个包围了我……暗血……之后的一切我都不记得了。我昏了过去，很久才醒过来。"
D.Strings[6135]="黑暗就在前面，隐约可见，陌生人……"
D.Strings[6136]="灵魂们非常容易激动。我们必须找到这场骚动的原因。"
D.Strings[6137]="又过来了一些！小心！"
D.Strings[6138]="最好我们现在就分开，以免他们派更多人来追击我们。希望我们之间有人可以成功回到加尔鲁什那里。保重，陌生人。"
D.Strings[6139]="不要让他们跑了！先杀掉那个强壮的家伙！"
D.Strings[6140]="想跑？没门！消灭他们！"
D.Strings[6141]="尝尝闪电的厉害，混蛋！"
D.Strings[6142]="冰霜震击！！！"
D.Strings[6143]="不，不，不！回到这边来！"
D.Strings[6144]="魔导师会杀了我的……"
D.Strings[6145]="过来，你这个小……"
D.Strings[6146]="唉唷。他们告诉我这些水晶可以完美运转！这帮奸商！"
D.Strings[6147]="不要挡着摄政王的路！我说真的！"
D.Strings[6148]="要是我抓住你，我会把你的零件都给分解掉，所以你最好……"
D.Strings[6149]="啊，不速之客。我得准备一下……"
D.Strings[6150]="我真是太笨拙了。"
D.Strings[6151]="赫米特是我所认识的最棒的猎人。很久以前，我们在艾泽拉斯的冬泉谷的山上偶遇。他和我正在追踪着一个相同的目标：那只名叫拉克西里的豹子。$B$B与其为了一个猎物打得头破血流，还不如下个赌注决定胜负：谁能得到霜刃豹的毛皮，就可以要求对方做些什么。那真是我一辈子的耻辱，我这“好儿子”的绰号就是这么来的。$B$B我看上去像一个“好儿子”吗？"
D.Strings[6152]="强大的猎人$n回来了。给我讲讲你最新的狩猎故事吧。"
D.Strings[6153]="嗯，嗯，我感觉好点了，但我其实有点喜欢这里……"
D.Strings[6154]="前面就是去塔拉的路。我们在前面的岔道分开，他们肯定会派更多人来追击我们的。希望我们当中有人能活着回到塔拉。"
D.Strings[6155]="我为你们感到可悲，小家伙们！"
D.Strings[6156]="搞定你了，对不对？"
D.Strings[6157]="怎么可能？啊，这真是个残酷的世界……"
D.Strings[6158]="展览厅只对访客开放。"
D.Strings[6159]="馆长无法继续运……作……"
D.Strings[6160]="你的请求未能得到批准。"
D.Strings[6161]="不合作将导致攻击行动。"
D.Strings[6162]="托托，你不会让这些家伙伤害我们的，对吧？"
D.Strings[6163]="啊，托托，我们必须找到回家的路！那位老巫师是我们唯一的希望了！稻草人、狮子，还有铁皮人，你们能不能——呀，有人来了！"
D.Strings[6164]="啊，我终于……终于可以回家啦！"
D.Strings[6165]="托托！不！你们杀了托托！"
D.Strings[6166]="你是个什么魔鬼，这样煎熬着我？"
D.Strings[6167]="离别是这样甜蜜的凄清。"
D.Strings[6168]="罗密欧，我来了！我为你干了这一杯！"
D.Strings[6169]="来吧，可爱的黑颜的夜，把我的罗密欧给我！"
D.Strings[6170]="啊，好刀子！这就是你的鞘子；你刺了进去，让我死了吧!"
D.Strings[6171]="你要激怒我吗？那就来吧!"
D.Strings[6172]="现在我又重新得到了多大的安慰！"
D.Strings[6173]="无情的泥土，我要擘开你的馋吻!"
D.Strings[6174]="你杀了我……却洋洋得意。"
D.Strings[6175]="你们的行为是不可饶恕的。"
D.Strings[6176]="抛弃一切堕落的杂念。"
D.Strings[6177]="死亡来临了。你们自问无愧于良知吗？"
D.Strings[6178]="啊哈哈哈……"
D.Strings[6179]="不纯的思想会导致亵渎的行为。"
D.Strings[6180]="这样就没问题了。"
D.Strings[6181]="时间……时间总是不够。"
D.Strings[6182]="啊，真惨。"
D.Strings[6183]="星界财团已经策划这个行动好几个月了！我们要挖掘宇宙中最大的钻石——沃舒古。$B$B就在我们要开始动手的时候，节点亲王哈拉迈德送来口信说，我们需要暂缓一下，直到解决一个虚空风暴地区的政治问题。我只能把我们的行动改变为在空闲时间走私宝石，但是这似乎在慢慢消耗我们的利润。"
D.Strings[6184]="杰赫要在这里专心完成一项工作。而我负责保证在他工作时没人可以打扰他。"
D.Strings[6185]="你知道我们是谁吗，陌生人？我们是玛格汉，棕色的兽人，我听到你们的同类都是这么叫我们的。玛格汉是幸存者：一个消失了的王朝的幸存者，红色天灾的幸存者，这个破碎世界的幸存者……$B$B我叫约林，基尔罗格之子。死眼家族最后的血统，血环氏族的酋长。"
D.Strings[6186]="我投降！不要杀我！"
D.Strings[6187]="若是赫米特知道如何在射击猎物时避免打中机翼的话，我们就不会坠毁。$B$B不用担心，我会很快把它修好的。"
D.Strings[6188]="救救我！请救救我！"
D.Strings[6189]="你怎么能就这么把我留在这里？"
D.Strings[6190]="何时才能结束这种痛苦啊？"
D.Strings[6191]="我很高兴那个邪恶的甘克雷·骨拳没能得逞！如果你想带点毛皮给哈罗德的话，我有很多。"
D.Strings[6192]="我拒绝承认失败！我是艾瑞达的王子！我……是……"
D.Strings[6193]="你显然没有奢望自己可以获胜。"
D.Strings[6194]="你的贪婪和愚蠢注定了你的结局。"
D.Strings[6195]="你不过是个无聊的玩具，甚至不能让我提起战斗的兴趣。"
D.Strings[6196]="疯狂将你们带到我的面前，而我将以死亡终结你们！"
D.Strings[6197]="%s开始放置炸弹！"
D.Strings[6198]="谁竟敢打断……什么？你们都干了些什么？你们毁掉了一切！"
D.Strings[6199]="靠近点！再近点……燃烧吧！"
D.Strings[6200]="你们为什么要这么做！"
D.Strings[6201]="别让他们把我……做成草垫。"
D.Strings[6202]="看来我并不是一个失败品！"
D.Strings[6203]="我的生命属于您，主人……"
D.Strings[6204]="啊，你们来的正是时候。仪式就要开始了！"
D.Strings[6205]="你的血让我的法阵更强大！"
D.Strings[6206]="主人会非常高兴的。"
D.Strings[6207]="主人，请接受这谦卑的祭品……"
D.Strings[6208]="让这份祭品见证我的忠诚。"
D.Strings[6209]="盖亚安祖母让我们获得了升华。所有你遇到的玛格汉族人的生活都与盖亚安祖母有着某些特殊的联系。当她去世的时候，我们会非常怀念她的。"
D.Strings[6210]="来吧，黑暗中的潜伏者！听从我的召唤！"
D.Strings[6211]="快来吧，我的宠物们。来吃个够吧！"
D.Strings[6212]="盖亚安祖母曾跟我说，我的名字来自一位伟大的兽人英雄。"
D.Strings[6213]="啊……美味极了。"
D.Strings[6214]="又变成一堆废铜烂铁了。"
D.Strings[6215]="看来我还没有锈成一团废铁。"
D.Strings[6216]="麦迪文会被打倒的！"
D.Strings[6217]="我们是不会被阻止的！"
D.Strings[6218]="最后的守护者，去死吧！"
D.Strings[6219]="我们还没有完！"
D.Strings[6220]="必须保护裂缝！"
D.Strings[6221]="你的时间不够了！"
D.Strings[6222]="胜利将会是我们的！"
D.Strings[6223]="坚持！不惜一切代价取得胜利！"
D.Strings[6224]="继续战斗下去！不要胆怯！"
D.Strings[6225]="你似乎是个通情达理的$R。或许我们能互相帮助。"
D.Strings[6226]="我会让你为此付出代价的！"
D.Strings[6227]="督军卡利瑟里斯会很高兴看到你们这些傲慢的家伙被干掉的！"
D.Strings[6228]="别想再插手我们的事情！"
D.Strings[6229]="坚强一些。凯尔萨斯背叛了我们，我们的希冀变成了泡影，但是不要失去信心。我们会坚持到底，就像以前一样。阿尔萨斯的铁蹄没有摧毁我们的精神，凯尔萨斯也绝不可能让我们毁灭。就让这变故成为我们永远铭记的一课吧。"
D.Strings[6230]="你想到我们美丽的城市哪个区域逛逛？"
D.Strings[6231]="我们的银月城有两座拍卖行，你喜欢哪个？"
D.Strings[6232]="去西面那个。"
D.Strings[6233]="西面的那座拍卖行可以在花园街市中间找到，就在长者步道往西一点。"
D.Strings[6234]="去东面那个。"
D.Strings[6235]="皇家贸易区的拍卖行可以在城市的东部找到，就在血骑士和猎人的训练区域往南一点。"
D.Strings[6236]="西边。"
D.Strings[6237]="银月城银行就在花园街市。去东南角找找吧。"
D.Strings[6238]="东边。"
D.Strings[6239]="如果你想要在城市的东部找一家银行的话，就在皇家贸易区的北墙那里。"
D.Strings[6240]="龙鹰管理员"
D.Strings[6241]="葛拉米和她的龙鹰就在城外的牧羊人之门西面。"
D.Strings[6242]="坦德莉恩是银月城的公会注册员。她的住处就在长者步街上，魔导师之门附近。"
D.Strings[6243]="银月城旅店座落在皇家贸易区，由一个叫维兰德拉的女人经营着。我听说那个有名的调酒师有时也会出现在那里。"
D.Strings[6244]="在我们美丽的城市里有许多邮箱。靠近皇家贸易区银行的那个对你来说应该非常方便。"
D.Strings[6245]="沙尔蕾恩在城市里面照顾动物，避免它们在主人离开的时候因为无所事事而发狂。她就在远行者广场的游侠大厅外面。"
D.Strings[6246]="远行者广场的血骑士慷慨地允许银月城的武器大师伊蕾达使用他们的大厅。虽然她的训练费用并不便宜，但是你会非常欣赏她的专业素养。"
D.Strings[6247]="战场军官们在远行者广场的血骑士大厅深处。虽然他们有点……粗鲁，但还是有些优点的。"
D.Strings[6248]="你希望选择哪条发展之路？"
D.Strings[6249]="德鲁伊之路？我们的人不会选择这个……但是你很幸运。一个女性牛头人——至少，我相信那是个女性——在长者步道的北面尽头建了个住处。她叫哈雷尼·平原行者。"
D.Strings[6250]="哦，你在找……他们。好啊，如果你真的想浪费你的时间来和那些迟钝的家伙谈话，可以在远行者广场里面找到这些游侠。桑迪恩会接待你的。"
D.Strings[6251]="啊，你在找传授神秘魔法的导师吗？你可以在日怒之塔找到奎恩萨斯和其他的魔导师。"
D.Strings[6252]="女伯爵莉亚德琳，血骑士的领袖，把她的血骑士总部设在远行者广场的边上。如果你需要什么指导的话，可以去和勇士巴卡希谈谈。倘若你想要保住自己的脑袋，记得在那里说话时放礼貌点。"
D.Strings[6253]="我们这座美丽城市中的牧师在日怒之塔内。去那里找贝蕾丝特拉女士吧。"
D.Strings[6254]="有时候很难找到那些敏捷的家伙，不过你很可能在谋杀小径的深处偶遇潜行者瑟兰尼斯和他的伙计们。"
D.Strings[6255]="召唤恶魔是一种很危险的行为，但是那又可以让你掌握巨大的力量。奥拉玛是我们的常驻专家，在谋杀小径指导着术士们。"
D.Strings[6256]="你要学习何种专业技能？"
D.Strings[6257]="炼金师们都在逐日王庭，你可以去找卡博隆，他会很热情地教你一大堆关于制造药水的知识。"
D.Strings[6258]="波玛尔在远行者广场传授铁匠的技术。虽然这是个……脏活，但我想它还是有一些优点的。"
D.Strings[6259]="我相信附魔师瑟丹娜正在招收学生。你可以在逐日王庭的某个亭子里面找到她。"
D.Strings[6260]="一个奇怪的选择……但是我想这并不是我该评判的。你应该去找丹文，她的工程台就在逐日王庭附近，通往远行者广场的那条路上。"
D.Strings[6261]="埃雷图斯是个……处理各种伤口的大师。如果学习急救是你的目标，就去长者步道找他吧，他就在皇家贸易区的入口附近。"
D.Strings[6262]="奎尔萨拉斯的水里有着大量的鱼，你从来都没发现过吗？德拉森对钓鱼很有经验，你可以在长者步道靠近皇家贸易区的地方找到他。"
D.Strings[6263]="植物学家娜萨兰有着一副寻找药草的敏锐眼睛，我想她可能会把她的智慧传授给像你这样的家伙吧。你可以在逐日王庭那里的亭子中找到她和炼金师们。"
D.Strings[6264]="如果你要找珠宝匠，就去皇家贸易区的南部寻找卡琳达的商店。"
D.Strings[6265]="沿着长者步道走到东南方的尽头，莱纳里斯在那里开了一家制皮点。她会教你的，只要你肯付钱。"
D.Strings[6266]="如果在泥土里面挖掘对你来说是一种有趣的娱乐，就去远行者广场找比利尔分享你的疯狂吧。我相信他会很高兴看到他不是唯一的疯子。"
D.Strings[6267]="提恩是个很有天赋的剥皮师，她所生产的山猫皮是我见过的最好的东西。如果你想从她那里学到点本事，可以在长者步道的东南尽头找到她。"
D.Strings[6268]="裁缝基伦一直在寻找好奇的学生来传授他那精巧的手艺。他的店有点不好找，就在花园街市的拍卖行的北面。你可以在那座建筑的底层找到他。"
D.Strings[6269]="在纳格兰，食物竟敢追杀食人魔！"
D.Strings[6270]="再加点盐和胡椒你就更美味了。"
D.Strings[6271]="为什么你对拉普这么粗暴？拉普只是饿了。"
D.Strings[6272]="好吧，好吧！拉普投降！"
D.Strings[6273]="我需要答案，食人魔！"
D.Strings[6274]="好好好！拉普什么都说！"
D.Strings[6275]="为什么石拳氏族出现在这么远的地方？你要知道这是库雷尼的领地。"
D.Strings[6276]="石拳氏族好饿！要吃东西！战槌氏族把石拳氏族赶到了北面。石拳需要更多食物。"
D.Strings[6277]="你以为你可以想吃什么就吃什么吗？你肯定是想去吃塔拉的破碎者。"
D.Strings[6278]="不是。我只不过想慢慢咀嚼而已。我并不是所有的东西都吃的。呃，也许我会吃那些小东西。$B$B他们味道真好！"
D.Strings[6279]="这意味着战争，拉普！我说的是战争！"
D.Strings[6280]="<拉普耸了耸肩。>$B$B你把战争给石拳氏族带来，我们炖它吃。"
D.Strings[6281]="把我弄出这里，$r！"
D.Strings[6282]="谢谢，$R！我的父亲一定会好好奖励你的！再见！"
D.Strings[6283]="了解这些新植物的分类对我们远征队来说非常重要。这不只是为了医用或者食用。$B$B植物是很多其它生命存活的基础，了解它们可以让我们更好地了解整个大自然。"
D.Strings[6284]="这是我最后一次被抓住！我保证！再见！"
D.Strings[6285]="我们赢得了宝贵的时间。现在必须撤退。"
D.Strings[6286]="我们完成了自己的使命，现在就看其他人了。"
D.Strings[6287]="是谁这么大胆地站在兰特瑞索·火刃面前？你不知道自己死到临头了吗，$g小子:小姑娘;？"
D.Strings[6288]="我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。"
D.Strings[6289]="那么你就是个蠢货。你不知道我是谁吗？"
D.Strings[6290]="我应该知道吗？你看上去就像个兽人。"
D.Strings[6291]="一个兽人……$B$B<兰特瑞索露出轻蔑的表情。>$B$B我是个拥有一半兽人血统的剑圣。"
D.Strings[6292]="那么另一半是什么？"
D.Strings[6293]="德莱尼人……因为这个，我既不是兽人又不是德莱尼人。我的血统是非常稀有的，同族们大部分在十年前都已经被杀了……我凭借我的意志活了下来。"
D.Strings[6294]="我听说过你的族群，但是我从没想到真的会遇到一个。"
D.Strings[6295]="闭嘴，$R。我所经历过的一切，你只有在传说中才听说过。我无情地杀死过男人、女人，甚至是孩子。我为两任部落酋长效力过……而现在，我统治着石拳氏族。"
D.Strings[6296]="对不起。我并不是有意冒犯。我来这里是为了我的人民的利益。"
D.Strings[6297]="那么你的人民想从兰特瑞索这里得到什么，$r？"
D.Strings[6298]="我的人民需要你撤回你的石拳食人魔，并停止所有针对我们领土的进攻。作为回报，我们同样会撤回我们的部队。"
D.Strings[6299]="<兰特瑞索大笑起来。>$B$B你知道你在哪里吗，蠢货？这里是食人魔的领地。在兽人之前，甚至在德莱尼人之前，食人魔就已经存在了。现在，你想要打一场你必定失败的战争？石拳氏族会消灭你们，如果石拳没有消灭你们，战槌氏族一样会……$B$B我相信你们的领袖很明白这一点……"
D.Strings[6300]="那么，我们会和你战斗到底，兰特瑞索。我们不会就这么眼睁睁看着你掠夺我们的村庄，杀害我们的人民。"
D.Strings[6301]="<兰特瑞索怒视着你。>$B$B也许有另外一个办法……如果你完成了我要你做的事情，我可以答应你的领袖的要求。$B$B有了你的帮助，也许我们都可以得到完美的结果。"
D.Strings[6302]="我要做些什么呢？"
D.Strings[6303]="你得捏造出一堆故事，让基尔索罗堡垒的兽人相信战槌食人魔袭击了他们的营地；你还得再编另一堆故事，让战槌食人魔相信基尔索罗兽人正在攻击他们的营地。$B$B这样困扰我们的两大难题就都解决了。$B$B石拳氏族会夺回他们的领地，而你的族人再也不会受到石拳、战槌和暗影议会的攻击。"
D.Strings[6304]="没有什么畸形的虫子可以把我赶出赞加沼泽！我会让它们知道探险者协会不是好惹的……"
D.Strings[6305]="很快就会结束了！"
D.Strings[6306]="又一个战利品！"
D.Strings[6307]="干得好，午夜！"
D.Strings[6308]="不许触摸展品。"
D.Strings[6309]="你不是访客。"
D.Strings[6310]="画廊的规定必须严格遵守。"
D.Strings[6311]="馆长已经为保护画廊准备就绪。"
D.Strings[6312]="我说到哪里了？哦，对了……"
D.Strings[6313]="你叫我吗？"
D.Strings[6314]="愚蠢的家伙！时间就是吞噬你躯体的烈焰！"
D.Strings[6315]="你如何抵挡这无坚不摧的力量？"
D.Strings[6316]="所有的世界都向我敞开大门！"
D.Strings[6317]="你面对的不仅仅是玛克扎尔，还有我所号令的军团！"
D.Strings[6318]="终于……噩梦结束了……"
D.Strings[6319]="我不会再次受辱的！"
D.Strings[6320]="今晚，一切都变得虚虚实实，真伪难辨；今晚，你们的眼睛将欺骗你们的心灵！"
D.Strings[6321]="比如说，这位老奶奶正在等待她的孙女……显然，头发斑白的慈祥老奶奶没有什么威胁！"
D.Strings[6322]="但是我不能说得太多！你们必须自己看清隐藏在伪装下面的真相！现在——演出开始！"
D.Strings[6323]="今晚，我们将见证人类灵魂深处的信念。一位迷失的小女孩，在忠诚的伙伴们的帮助下寻找回家的路！"
D.Strings[6324]="但是……一个邪恶的老巫婆正在追赶着她！"
D.Strings[6325]="她能逃脱魔掌吗？她能平安回家吗？只有时间才能回答这些问题。现在——演出开始！"
D.Strings[6326]="今晚，我们将看到一段受到百般阻挠的爱情！"
D.Strings[6327]="但是，大家知道，并非所有的爱情故事都有完满的结局。有些时候，爱情就像荆棘一样危险！"
D.Strings[6328]="耳闻为虚眼见为实，当两个彼此相爱的人在今晚见面时，又将会上演什么样的悲剧？大家拭目以待吧！现在——演出开始！"
D.Strings[6329]="想要张贴悬赏令的人必须事先与监护者布罗克交谈。$B$B未经批准擅自张贴将被起诉。张贴悬赏令不需支付金币。"
D.Strings[6330]="想要张贴悬赏令的人必须事先与监护者莫布吉尔交谈。$B$B未经批准擅自张贴将被起诉。张贴悬赏令不需支付金币。"
D.Strings[6331]="那些该死的食人魔。他们应该被推到虚空里。有人能从这些野人手里拯救我们吗？这已经是最近第五次绑架了！"
D.Strings[6332]="那已经是我们所能提供的最好的奖励了。希望有人会接受那个任务。"
D.Strings[6333]="$r，如果你在找活干的话，去看下公告板吧。"
D.Strings[6334]="是谁胆敢攻击我的坐骑？"
D.Strings[6335]="也许你应该找个更加厉害的对手过招！"
D.Strings[6336]="他们一点也不尊重死者，$r。我们必须狠狠教训一下这些食人魔了。"
D.Strings[6337]="我们必须搜寻幸存者。如果仍然有人活着，我们至少得试试救他们回来……"
D.Strings[6338]="总有一天，一个英雄将会挺身而出，让兽人重获昔日的荣耀。"
D.Strings[6339]="谢谢你，$R！你为玛格汉所做的一切，我们都将铭记在心。"
D.Strings[6340]="食人魔，去死吧！"
D.Strings[6341]="太感谢你了，英雄！"
D.Strings[6342]="灵魂与你同在，$r！"
D.Strings[6343]="干得好，冒险者。雷基·冬寒的死让我们获得了一个短暂的喘息机会。好好利用这段珍贵的时间吧。治疗一下你的伤口，做好准备，很快阿克蒙德就会向我们派出更强大的部队。我的部队会在战斗再次开始时增援你的。"
D.Strings[6344]="那么就让阿克蒙德再吃一场败仗吧！"
D.Strings[6345]="你是谁？你想要得到什么？"
D.Strings[6346]="你为什么这样对我们？"
D.Strings[6347]="有四道光！四道！"
D.Strings[6348]="我的巨蛾们会为我报仇的！"
D.Strings[6349]="大家都去哪儿了？"
D.Strings[6350]="宴会上的客人应该对我们更尊重些！"
D.Strings[6351]="啊，一个多么神圣的地方被破坏了！"
D.Strings[6352]="我可以教你采矿。你感兴趣吗？"
D.Strings[6353]="在我的头上涂些治疗药膏。你喜欢我的荆棘王冠吗？"
D.Strings[6354]="我可以教你草药学。你感兴趣吗？"
D.Strings[6355]="太棒了！你打败了安纳塞隆，延缓了阿克蒙德的计划，让我们离胜利更近了一步。但是，我的部队不能留在这里。他们都已经非常疲倦，现在是撤退的时候了。如果你还能支撑下去的话，就到东面去，找到萨尔的营地吧。那是我们的另外一个据点。保重。"
D.Strings[6356]="我们必须把那些补给箱给弄回来！"
D.Strings[6357]="谢谢你，$n！你救了我多少次了？三次？我已经把你当亲人看待了！"
D.Strings[6358]="进入这片树林的时候小心点，$c。这地方被一个邪恶的光环笼罩着，肯定是那些杀害我的德鲁伊同胞的家伙留下的。"
D.Strings[6359]="这片森林是个怪异的地方，这里的坏魂能要比联盟还多，所以你自己得小心点。"
D.Strings[6360]="部落不是这片森林里潜伏着的唯一危险。不要让它宁静的表象迷惑了你。"
D.Strings[6361]="$R，你确实很强壮，但是你配得上战槌勇士的称号吗？"
D.Strings[6362]="战斗即将开始！$n对凶猛的裂蹄牛——断蹄！"
D.Strings[6363]="不要挡我的路，$r。你没看到我们正在战斗吗！"
D.Strings[6364]="进入鲜血竞技场吧，$n。战斗就要开始了！"
D.Strings[6365]="$n打败了断蹄！"
D.Strings[6366]="太棒了！卡兹洛加死亡时发出的嚎叫应该会让燃烧军团感到畏惧。他们现在认识到了你们所拥有的力量，那么准备好接受燃烧军团的更强烈的打击吧。"
D.Strings[6367]="太精彩了！杀死一个像阿兹加洛这样的深渊领主并不是件小事，我的朋友。如果我们有更多的时间，我会很乐意倾听你和你同伴的故事。但是阿克蒙德不会给我们休息的机会，不管怎样，我的斥候报告说，燃烧军团正在我们营地外聚集更强大的力量，而且阿克蒙德离世界之树已经非常近了。我们正在普罗德摩尔女士的帮助下撤退。你应该立即向世界之树进发。我们世界的命运仍然未定。"
D.Strings[6368]="蓝色兄弟最高！"
D.Strings[6369]="战斗马上开始！无情的暗血双子对阵$n！"
D.Strings[6370]="难以置信！$n击败了暗血兄弟！"
D.Strings[6371]="出来，小家伙们！穆格高克要跟你们玩！"
D.Strings[6372]="穆格高克一点都不疼，鸟人！"
D.Strings[6373]="很好！鸟人们走开！穆格高克找到了一个新朋友！"
D.Strings[6374]="站起来吧，死去的兄弟们！起来战斗吧！"
D.Strings[6375]="为从刀锋山来的裂石之王洛卡达尔欢呼吧！$n正在为$g他的:她的;生命而战！"
D.Strings[6376]="洛卡达尔要揍扁弱小的$n！"
D.Strings[6377]="$n又一次胜利了！"
D.Strings[6378]="真没劲！穆戈尔更厉害！"
D.Strings[6379]="一个破碎者的尸体躺在这里。神秘的是，他死亡的原因并不是由于那变异的蛾子。$B$B也许是因为他手上的奇怪物品？"
D.Strings[6380]="靠近点……再靠近点……看看虚空给我们带来了什么！"
D.Strings[6381]="来自未知世界的强者，瑟克拉加斯！$n能否在虚空能量的冲击下幸存呢？"
D.Strings[6382]="穆戈尔没有印象！瑟克拉加斯是由空气和暗影组成的！像被压扁的兽人一样软！"
D.Strings[6383]="这是我们最为期待的时刻！战槌勇士要开始他本周在鲜血竞技场的第一场表演了！$n会不会像这位勇士的其他对手那样被轻松打败呢？我们拭目以待……"
D.Strings[6384]="我要把这个挑战者撕成碎片！"
D.Strings[6385]="什么！？不可能！！你要和穆戈尔战斗了！穆戈尔杀啊！！！"
D.Strings[6386]="现在你将面对真正的冠军！我会给你一个逃跑的机会，小家伙。在穆戈尔把你杀死之前逃跑吧！"
D.Strings[6387]="没有机会了！现在你要付出代价了！"
D.Strings[6388]="穆戈尔向你挑战。你必须同意！进入竞技场，准备战斗吧。"
D.Strings[6389]="$n打败了战槌英雄穆戈尔！大家为$n欢呼吧！"
D.Strings[6390]="我发怒了！你把穆戈尔打疼了！！"
D.Strings[6391]="你好啊，勇士！你想过作一个全职的角斗士吗？你和我搭档肯定可以赚很多钱。"
D.Strings[6392]="很忙……很忙！什么？"
D.Strings[6393]="埃博尔，你是想马上把我要知道的东西告诉我，还是吃点苦头？"
D.Strings[6394]="现在我被打得就差一口气了，你想要什么？"
D.Strings[6395]="我们无论如何都要彻底调查这次惨案！"
D.Strings[6396]="非常感谢你来支援我们对抗燃烧军团的战斗。吉安娜·普罗德摩尔女士正需要你的帮助。"
D.Strings[6397]="噩梦般的时刻就在眼前了，$c。阿克蒙德成功地靠近了诺达希尔，并开始吸取世界之树的能量。玛法里奥需要更多时间来准备他的计划，我们必须尽全力完成这几乎不可能的任务。在我的部队抵抗潮水般的燃烧军团部队时，你必须直接进攻阿克蒙德。"
D.Strings[6398]="欢迎来到时光旅店！"
D.Strings[6399]="放松你疲惫的双腿，我们拥有整个世界的时间……"
D.Strings[6400]="我可以请你喝一杯吗？我保证这是真正的陈年老酒！"
D.Strings[6401]="天涯旅店没有什么我想要的。不过，这里却能吸引许多对我在售卖的商品十分感兴趣的客户。$B$B我专门研究稀奇的工程学物品，已经获得了很大的成就。有时候，我这里可能还会有一两件奇货出售。$B$B怎么样，有什么你感兴趣的吗？"
D.Strings[6402]="当你往西边看的时候，你看到了什么，凡人？"
D.Strings[6403]="我看到了扭曲的钢铁，碎裂的大地。"
D.Strings[6404]="你知道我看到了什么？一个入侵的先兆。$B$B虽然主人非常睿智地封印了传送门，但他失去了他的……我该怎么来表达这个？他的专注。是的……专注。$B$B因此，军团抓住了这个机会。他们现在渗透了进来，数量在一天天地膨胀。"
D.Strings[6405]="军团？"
D.Strings[6406]="燃烧军团。恶魔。我可以清晰地看到他们，就像你能清晰地看到自己的双手那样。以前，我总是能一眼看清他们。$B$B随着燃烧军团的回归，他们正在进行着新的诡计。在通常的情况下，我可以感觉到千里之外的恶魔。$B$B<奥图里斯的面孔扭曲了一下。>"
D.Strings[6407]="现在呢？"
D.Strings[6408]="他们躲避着我。我的视野不能穿越他们的防线。他们部署了结界来避免我的窥探。$B$B<奥图里斯指了指西边。>$B$B他们畏惧我们，因为他们知道我们无所畏惧。换取这种力量需要付出巨大的代价，惨痛的牺牲。"
D.Strings[6409]="你现在要怎么才能看到他们？"
D.Strings[6410]="<奥图里斯转向你笑了笑。>$B$B我不行。$B$B<奥图里斯指了指他的坐骑，奈瑟兰达姆斯。>$B$B我们必须在这些铸魔营地有能力完成它们正在建造的东西之前阻止他们。"
D.Strings[6411]="铸魔营地？"
D.Strings[6412]="那是他们的这些邪恶的建筑物的名称。燃烧军团雇用了莫尔葛恶魔和甘尔葛恶魔，在这些营地中建造具备大规模杀伤能力的武器。有了结界的存在，我就不能发现他们正在纳格兰建造些什么！$B$B你将是我的眼睛。你的武器将是我的愤怒。"
D.Strings[6413]="啊，怎么又是你！滚开！"
D.Strings[6414]="这是我从你的调查中得到的情报。$B$B那里有着两座主要的铸魔营地——仇恨和畏惧。铸魔营地：仇恨在我们的西边，而西南边是铸魔营地：畏惧。每座营地中都有一个军团传送点，一座熔炉，还有几座法术结界塔。每座营地都配备了由愤怒卫士控制的邪能火炮。最后，每座营地都还有一个深渊领主监督着。$B$B就这样，这应该一点也问题没有……$B$B<奥图里斯大笑起来。>"
D.Strings[6415]="我想我应该趁别人还在讨论是否可以进入沃舒古的时候自己先想办法赚些钱。$B$B时间就是利润！"
D.Strings[6416]="灯塔点亮了，是时候发动进攻了！拿上一面联盟军旗，把它插在墓地中吧！"
D.Strings[6417]="双塔废墟还没有被占领！我的命令是当这两座灯塔都被点亮、并且整个区域都被占领的时候发放军旗。到那里去控制灯塔吧！"
D.Strings[6418]="你闯进我的家门来威胁我？我可不认为你能如愿。"
D.Strings[6419]="<萨萨拉比姆对着你咆哮，然后回头去喝他那起泡的饮料。>"
D.Strings[6420]="[恶魔语] Ka kalix！"
D.Strings[6421]="奥图里斯派我过来的。他说你能帮我。"
D.Strings[6422]="忒洛斯，我知道你了解真相。告诉我吧。"
D.Strings[6423]="<监护者忒洛斯滑稽地看着你，停了停，看起来似乎很难控制自己。>$B$B赞加沼泽……真相太近了。$B$B<他的脸再次变得疯狂起来。>$B$B他还在监视着吗！？"
D.Strings[6424]="嘿！清醒一点，哥们！赞加沼泽怎么了？"
D.Strings[6425]="那是什么？赞加沼泽？为什么我要去那里？$B$B<忒洛斯似乎正在陷入沉思。>$b$B是的，赞加沼泽……我们……德鲁伊们快要发现为什么水平面正在下降。它正毁灭着一切！$B$B<癫狂又在监护者的眼中出现。>$B$B毁灭我们吧！明亮的圣光！轰！！"
D.Strings[6426]="我没有时间跟你玩！监护者，到底发生了什么事？！"
D.Strings[6427]="火翼的血精灵们……不知道为什么，他们想阻止我们。$B$B<监护者忒洛斯努力地想镇静下来。>$B$B他们……他们派了一个破碎者作为……作为大使……但是他有炸弹！$B$B他们都死了，他们都死了！他们想逃跑！有些幸运的家伙甚至都不知道。$B$B我肯定是在爆炸的边缘。那实在太糟了……又开始监视我们了！$B$B<忒洛斯变得很沮丧，直钩钩地看着前方，好像把你当成了空气。>"
D.Strings[6428]="你要干什么？"
D.Strings[6429]="我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。"
D.Strings[6430]="呼嘶呼呼？？"
D.Strings[6431]="<弗鲁恩发出一连串奇怪的唧唧咯咯的声音。>"
D.Strings[6432]="你开玩笑吧？他已经把我杀了！他还想要什么？"
D.Strings[6433]="他想要“金币”。再说一次……要么付钱要么纳命来……"
D.Strings[6434]="我选择第三项：杀了你！"
D.Strings[6435]="拉里克要教训你！"
D.Strings[6436]="$n，再次感谢你帮我找出了树林里这件惨剧的真相。"
D.Strings[6437]="你可以随便处理他，我已经不需要他了！"
D.Strings[6438]="你想杀了他？随便你！"
D.Strings[6439]="别在他身上浪费时间了，他是个没用的东西。"
D.Strings[6440]="对！不要留情！"
D.Strings[6441]="有个废柴挂了，继续，干掉下一个！"
D.Strings[6442]="就算你不动手，我也会杀了他！"
D.Strings[6443]="啊，多么浪费啊。下一个！"
D.Strings[6444]="谢谢你们帮我省去不少麻烦。现在，该我来找找乐子了！"
D.Strings[6445]="你想要我们一起上？很好！"
D.Strings[6446]="来吧，让我看看你们真正的实力！"
D.Strings[6447]="我的工作是照顾那些可怜的灵魂。我愿意接受任何帮忙，无论他们是奥尔多还是占星者。$B$B我们太缺人手了，如果食人魔知道怎么扎绷带，我甚至愿意让他们帮忙。这座城市里的政治派系对我来说毫无意义。"
D.Strings[6448]="你能相信吗？这个虚灵身上竟然没有一只蜥蜴眼！$B$B然而他们的首领竟然还有胆子自称为“走私大亨！”"
D.Strings[6449]="你好，$n。我们是奥尔多，圣光的牧师和沙塔尔的仆人。$B$B我们随时欢迎你来这里。"
D.Strings[6450]="谁是沙塔尔？"
D.Strings[6451]="“生于圣光”应该是最接近沙塔尔这个词原意的翻译。那是我们给从伊利丹的爪牙手中夺取并重建沙塔斯城的纳鲁所起的名字。"
D.Strings[6452]="沙塔斯城不是一个德莱尼人的城市吗？为什么允许其他人生活在这里？"
D.Strings[6453]="沙塔斯城不仅仅是个为了对抗燃烧军团和伊利丹而设立的运输中转站，还是给那些企图寻找庇护的人们的避难所。$B$B如果我们赶走那些难民的话，我们就是伪君子了。$B$B如果你想问的是占星者，那么我要说，虽然我不喜欢他们，也不喜欢他们首领那救赎愿景的疯狂想法，但是这并不能让我怀疑纳鲁的智慧。$B$B这是一个艰难的时刻，$n。我们需要团结一切可以团结的力量。"
D.Strings[6454]="我的兄弟姐妹们，听我说。我们必须开始关注自身的生存了。虽然我们在一场灾难中勉强幸存了下来，但是我担心下一场灾难会把我们彻底摧毁。"
D.Strings[6455]="你们看不到眼前正在发生些什么事情吗？睁开你们的眼睛，一切都明明白白展现在你们眼前。我们的新同盟是什么？为什么我们背叛了过去的盟友，却要与所有生命的大敌亲密相处？"
D.Strings[6456]="不，你错了！我们才是遭到背叛的人！"
D.Strings[6457]="什么时候连矮人都变成了我们的朋友？"
D.Strings[6458]="人类在我们最黑暗的时刻抛弃了我们！他们的王子亲自领导了对我们领土的袭击。"
D.Strings[6459]="你这个蠢货！王子的爪牙就是那些被遗忘者，就是我们现在的同盟！而且他现在已经背叛了我们！"
D.Strings[6460]="她曾经是银月城的游侠将军，现在也会是我们忠诚的盟友！"
D.Strings[6461]="你把她当作朋友？你真是个蠢货。这个“黑暗女王”不是希尔瓦娜斯。"
D.Strings[6462]="欢迎来到奥蕾莉亚要塞，$c。"
D.Strings[6463]="机警点，$c。这片森林中充满隐藏的危险和潜在的敌人。"
D.Strings[6464]="我记得所有事情……"
D.Strings[6465]="这太糟了。$B$B我并不计较我们在这里有多不舒服，但我们必须做点什么，为那些白骨荒野的亡者减轻痛苦。"
D.Strings[6466]="灵魂的召唤……我被吞噬了。"
D.Strings[6467]="这痛苦简直无法忍受。"
D.Strings[6468]="不要再哭了！停下！"
D.Strings[6469]="它快死了。它快死了。它快死了。"
D.Strings[6470]="我们会怎么样？"
D.Strings[6471]="我控制不了……它在拉我进去……虚空在扩大……"
D.Strings[6472]="如果你在期盼正式的欢迎，那么你会失望的，$c。我们在这里并不拘泥于传统。怎么行就怎么做。"
D.Strings[6473]="钉满了羊皮纸的悬赏榜上有一张纸很显眼。上面写的是：希望有人能够去白骨荒野清理白骨秃鹫。"
D.Strings[6474]="不，没关系。我经常遇到这种事情。$B$B<泰拉看上去有些高兴又有些恼火。>$B$B我是个**高等**精灵，不是个血精灵。所以不要担心，我不会把你的所有法力吸个精光的。"
D.Strings[6475]="白骨秃鹫，我恨他们！$B$B要不是我失去了眼睛，要不是我那时灵时不灵的法术，我早就出去把他们全部轰成渣了！"
D.Strings[6476]="%s晕倒了。"
D.Strings[6477]="我看到奥尔多正在修缮那些城墙。你知道，他们想要重建整座城市。$B$B他们比老工头奥斯洛在湖畔镇干得快多了，他不是把工具遗失在河里，就是被豺狼人拿走他的补给。$B$B我应该要求奥尔多去帮助他，这样他们就会很快修好那座断桥了。"
D.Strings[6478]="那里有着大片的森林，$c。让萨满和灵魂们玩耍，让战士们耍他们的剑。泰罗卡森林是个要让我赚大钱的地方。"
D.Strings[6479]="玛鲁卡兹喋喋不休地讲述着这片森林的辉煌历史，但是在我们解决掉现在的问题前，我不会再奢靡无度了。$B$B我不是说他在这里的工作不重要，但是必须有人要去检查一下要塞的防御和后勤工作。"
D.Strings[6480]="直到我游遍了纳格兰并进入这片森林之前，我都在担心我们失去了太多的文化传承。看来我多虑了。$B$B这里的风貌依然保持完好！"
D.Strings[6481]="我的同胞的命运随着黑暗之门的打开进入了新的篇章。在某种程度上来说，我的流放使我免于堕落。但是看到远行者把他们的命运都交给了凯尔萨斯……$B$B我不敢相信我以前的朋友可以做出这样的事情。$B$B我那回家的梦看来永远都不可能实现了，这片森林是我唯一的家。"
D.Strings[6482]="当我最初来到这里时，我曾希望能和这个小镇所用名字的主人会面。$B$B<洛瑟蕾丝扫视着周围。>$B$B当年幼的高等精灵成长到学徒的年龄时，他们的脑袋里想的便不再是“我要成为一名远行者”，而是“我要当一名魔导师”。$B$B说实话，我不觉得我曾经幻想过成为远行者。没有人会梦想成为一名女裁缝，但就像我母亲常常说的那样，我们不能让远行者就这么不穿衣服走来走去。"
D.Strings[6483]="你有没有看到每当我拿起一件衣服或者帽子的时候，洛瑟蕾丝总是对我眨眼睛？当这附近的事情安定下来后，我一定会带她去森林里散散步。$B$B有时候，我还是挺想念暴风城的那些豪华旅店的。"
D.Strings[6484]="<凯德对你发出嘘声。>$B$B你这个蠢货！小声点，否则你会把那些兽人和联盟全引到我们这里来！$B$B对，就那样，点点头就行了，在我们完成谈话后，走远点，把我们的见面忘了吧。"
D.Strings[6485]="我们也许可以一起工作，但那只是为了增加判断力。再说一次，注意你的言行。$B$B我敢保证，周围还有别的人。"
D.Strings[6486]="你们！赶快去打水！在火势蔓延起来之前扑灭它！快一点，你们这些该死的东西！"
D.Strings[6487]="流血是真实的。我们只能相信自己！"
D.Strings[6488]="血？还有这些兽人，这些见风使舵的家伙？他们会帮我们吗？"
D.Strings[6489]="死亡之痕横穿过我们的土地！它每天都在生长。就像以前那样，我们对魔法的需要使得我们脆弱，同样也把我们带向毁灭。"
D.Strings[6490]="没有魔法，我们要怎么生存？"
D.Strings[6491]="看看这座神奇的城市！这就是魔法本身。"
D.Strings[6492]="但是那代价呢？你完全被蒙蔽了。我们都完全被蒙蔽了。"
D.Strings[6493]="你称我们是叛徒吗？"
D.Strings[6494]="魔导师们是叛徒！他们已经注定了我们的毁灭。"
D.Strings[6495]="一派胡言。回到你的森林里去！"
D.Strings[6496]="你会让我们像野蛮人那样生活的！"
D.Strings[6497]="不，不是野蛮人！这是道德。我们毫无节制的行为会最终摧毁我们，进而摧毁我们所努力构建的一切。"
D.Strings[6498]="我们竭尽全力挣扎奋斗，为的是求得生存的机会，而不是给自己带来真正的毁灭。"
D.Strings[6499]="嗯，你想要什么？你没看到我正忙着吗？暗影议会可不会按小时给我付工钱。"
D.Strings[6500]="我们站在毁灭的边缘。我们必须重新考虑这轻率的行动计划。"
D.Strings[6501]="为什么你要把这些全都修理了？"
D.Strings[6502]="我看上去像在干什么？我正在尽我的全力修理这个地方，这样我们就可以搬进来常驻了！$B$B随着基地在森林中运作起来，我们就更容易监视沙塔斯城、奥蕾莉亚岗哨、裂石堡，以及塞纳里奥的德鲁伊们。我们在奥金顿的基地中可不方便做这个。$B$B等一下，我认识你吗？"
D.Strings[6503]="嗯？该死的，现在我不得不重新开始了！"
D.Strings[6504]="你在干什么？"
D.Strings[6505]="加紧练习！很快我就会有足够的能力跟其他召唤者一起进入奥金顿的暗影迷宫了。$b$b我希望能得到召唤一些大东西的机会！也许是和摩摩尔一样大的家伙，但是我不会失去对他的控制！"
D.Strings[6506]="你觉得我能为你做些什么吗？没看到我正在讨论关于我们杰出领袖的重要事情吗？$B$B有话快说！"
D.Strings[6507]="顾问，有什么新消息吗？"
D.Strings[6508]="好吧，我正在给我们的首领进行汇报。应该只需要再多几周，我们就可以让这地方处于良好的运行状态。$B$B不过，我们可能想让暗影议会只派遣兽人来这里，那样的话，我们就能宣称这村子是我们的属地，便于进行秘密工作了。$B$B等一下，我认识你吗？你叫什么名字？"
D.Strings[6509]="你好，年轻的$r。"
D.Strings[6510]="你好，盖亚安祖母。加尔鲁什告诉我您想和我谈谈。"
D.Strings[6511]="你好，亲爱的。我是盖亚安，玛格汉的女族长。$B$B<盖亚安祖母咳嗽了一下。>$B$B你在这里，那及说明黑暗之门已经重新开启了。在这里的大部分兽人都太年轻或是太虚弱，以至于不能记起黑暗之门。$B$B<盖亚安祖母指了指她周围的兽人。>$B$B他们大部分是孤儿，或很快就会变成孤儿了。是的，这就是黑手酋长的做法，让体弱者远离健康者，只有强壮的兽人可以生存……"
D.Strings[6512]="祖母，这里的兽人都是您抚养长大的吗？"
D.Strings[6513]="他们在这里长大，我们让他们远离伤害。我尽可能地照顾他们的健康。很多都夭折了，但是更多的孩子茁壮成长了起来。就像加尔鲁什那样……$B$B<盖亚安祖母叹了口气。>$B$B你知道，他失去了他的信心。他告诉我，我是他的一切。如果失去了我，吞噬了他的父亲、诅咒了我们的人民的嗜血狂热会彻底占据他。"
D.Strings[6514]="您相信吗？"
D.Strings[6515]="<盖亚安祖母虚弱地笑了笑。>$B$B当然不，亲爱的。但是这并不是我相不相信的问题……$B$B加尔鲁什有能力来领导玛格汉。他是个强壮又聪明的领袖，万灵都很支持他。他只是需要自信。他的心中充满了恐惧……他的恐惧太深了，如果不能善加引导，他的愤怒会毁灭他自己和他周围所有的人。"
D.Strings[6516]="那怎么办？我已经试过很多办法了。我尽全力来帮助纳格兰的人民，但是每次我想接近加尔鲁什，他总是避开我。"
D.Strings[6517]="我希望我能知道该怎么做，亲爱的。他不会听你的，同样他也不会听我的。事实上，这就是我还在这里的原因，这就是我还没有和卡舒尔宗母一起离开的原因。他必须找回他的自信。如果没有合适的领导，我们的人民根本活不过这个冬天。"
D.Strings[6518]="离开？您怎么能选择离开呢？"
D.Strings[6519]="<盖亚安祖母笑了笑。>$B$B我老了，我的时日已经不多了。当我去世以后，我的灵魂会前往灵魂的国度。我会在那里与我的祖先们团聚。那就是我们关注着仍然活着的人民的地方。$B$B当加拉达还活着的时候，卡舒尔宗母的职责就和我现在的一样。"
D.Strings[6520]="这个职责是什么？"
D.Strings[6521]="部族母亲的职责就是倾听。倾听风、水、火和大地。从它们那里收集对氏族有用的信息，就像氏族中的其他人收集皮毛以供大家御寒一样。与我交流的正是灵魂……在我的梦里，卡舒尔宗母就像灵魂和她谈话那样对我谈话……当我去世之后，我会以相同的方式和德拉吉亚和塞雷斯蒂谈话。$B$B<盖亚安祖母微笑着。>"
D.Strings[6522]="我能为你做点什么吗, 盖亚安祖母？"
D.Strings[6523]="我需要燃烧弹包。"
D.Strings[6524]="要多少有多少，$n。小心使用，如果使用不当的话，这些东西是相当麻烦的。"
D.Strings[6525]="我要查出那些家伙的真正计划！"
D.Strings[6526]="列兵维克斯，我还需要一个伪装。"
D.Strings[6527]="我们要找出那些家伙在格兰戈瓦村干些什么！"
D.Strings[6528]="斥候奈弗蒂丝，我还需要一个伪装。"
D.Strings[6529]="我们在这里有一项任务，$g小子:姑娘;，要保证这个任务万无一失。$B$B我们必须先发制人！"
D.Strings[6530]="我肯定在某个地方做错了什么，才被分配到这里来。"
D.Strings[6531]="你有没有听说他们在暗影迷宫里完全失去了对摩摩尔的控制？！"
D.Strings[6532]="他们没有付足够的工钱给我们。但是在这座荒废的村庄总比在奥金顿里躲躲藏藏好多了。"
D.Strings[6533]="我加入他们，因为他们说可以付给我足够的钱让我去学院。我叔叔说我下个学期就可以去了！"
D.Strings[6534]="你好，你肯定是新来的吧！很高兴认识你！$B$B有没有从奥金顿暗影迷宫传来有关我们是否重新控制了摩摩尔的消息？"
D.Strings[6535]="我们一群人准备稍后去沙塔斯城喝酒，你有兴趣吗？"
D.Strings[6536]="有兴趣加入我们的皮球联赛吗？大部分情况下，我们在周一至周三比赛。$B$B我们很欢迎你在这次轮班以后加入我们。"
D.Strings[6537]="我希望这个地方可以成为暗影议会的前哨基地。我知道这听上去很奇怪，但是我真的有点想念暗影迷宫了。"
D.Strings[6538]="<他斜靠了过来。>$B$B就我和你，我想也许哪天晚上我们可以一起出去，你知道我的意思。"
D.Strings[6539]="<她斜靠了过来。>$B$B就我和你，我想也许哪天晚上我们可以一起出去，你知道我的意思。"
D.Strings[6540]="你以为你是谁，竟敢走进来打扰我？我是这座村子中的暗影议会首领。滚出我的视野！$B$B如果再让我看到你，你就玩完了，懂吗？$B$B你是喜欢被埋葬在奥金顿的迷宫里，还是去给摩摩尔当祭品呢？"
D.Strings[6541]="炼金术训练师就在圣光穹顶。愿圣光与你同在。"
D.Strings[6542]="尽管获取财富已经不是我们生活的动力了，但我们仍懂得有钱能使鬼推磨的道理。你可以在纳鲁之座找到我们的拍卖行。"
D.Strings[6543]="银行就在埃索达的中心地带。愿圣光与你同在。"
D.Strings[6544]="斯泰法努斯是我们的角鹰兽管理员。他就在埃索达的中央。愿圣光庇护你。"
D.Strings[6545]="你可以在圣光穹顶找到我们的战场军官。在布雷尔旁还有个叫米格里克·布罗斯托的家伙，他自称是这个世界上的竞技场巡回赛的官方代表。"
D.Strings[6546]="米阿尔是我们埃索达的首席铁匠，你可以在贸易阶梯的底层找到她。愿圣光与你同行。"
D.Strings[6547]="你在寻找什么训练师？"
D.Strings[6548]="德鲁伊？啊……沙兰尤斯，你在找沙兰尤斯吧。你可以在埃索达的外面找到这个暗夜精灵，就在瓦拉尔港口附近。"
D.Strings[6549]="我们的附魔师们就在水晶大厅，珠宝匠的对面。圣光与你同在。"
D.Strings[6550]="这么看来，你想帮我们修理埃索达吗？我听说让埃索达再度恢复所有功能需要几年的时间，但你只有两个小时。开个玩笑。我们的工程师们就在贸易阶梯的底层，愿圣光与你同行。"
D.Strings[6551]="以圣光之名！有人愿意关心其他人的安宁真是一种幸福。在这种时候，我们就是应该互帮互助帮助。努丝可以教你急救技能，她就在水晶大厅的水晶洞附近。圣光与你同在！"
D.Strings[6552]="你能不能先别——"
D.Strings[6553]="你可以在水晶大厅靠近圣泉的地方找到钓鱼训练师伊雷特。"
D.Strings[6554]="公会注册员就在贸易阶梯的入口附近。"
D.Strings[6555]="草药学训练师塞摩尔汉就在圣光穹顶的后墙对面。"
D.Strings[6556]="你在寻找猎人？他们就在贸易阶梯第二层的猎手圣殿中。"
D.Strings[6557]="我们的医护中心位于圣光穹顶中心的上方，靠近埃索达的主入口。"
D.Strings[6558]="你的技巧已经达到学习新东西的标准了吗？"
D.Strings[6559]="法里在训练那些对珠宝加工感兴趣的人。你可以在水晶大厅靠近巨洞的方位找到她。"
D.Strings[6560]="埃索达的制皮训练师在贸易阶梯。愿圣光保佑你。"
D.Strings[6561]="法师训练师就在圣光穹顶。愿圣光与你同在。"
D.Strings[6562]="纳鲁的祝福。我能帮你什么忙吗？"
D.Strings[6563]="采矿训练师就在贸易阶梯后面。"
D.Strings[6564]="你可以在纳鲁之座内的圣光礼拜堂找到埃索达的圣骑士训练师。"
D.Strings[6565]="我们的牧师训练师就在靠近纳鲁之座入口的圣光教团房间里。愿圣光伴随你。"
D.Strings[6566]="水晶大厅中有数名萨满祭司训练师。或者你可以找预言者努波顿谈谈，对这位破碎者表示一下你的怜悯之情。愿圣光与你同在。"
D.Strings[6567]="埃索达的剥皮训练师跟制皮训练师都在贸易阶梯。愿圣光保佑你。"
D.Strings[6568]="你可以在医护中心找到我们的兽栏管理员阿尔泰德，他就站在中间轮轴的上一层，靠近埃索达主出口那里。"
D.Strings[6569]="以前，我们曾穿过连体衣。感谢灵感不断的裁缝们，我们终于可以脱下那些不实用的制服了。你可以在贸易阶梯找到这些引领时尚的设计师。"
D.Strings[6570]="想成为一名伟大的战士吗？战争不会让你变得伟大。尽管如此，你可以在战士平台找到我们伟大的战士训练师，战士平台就在贸易阶梯的上方。"
D.Strings[6571]="欢迎来到皇家贸易区，$g先生:女士;。有什么我可以帮你的吗？"
D.Strings[6572]="感谢你选择了银月城银行。今天我能为你做些什么？"
D.Strings[6573]="想要学习更多武器技能吗？武器大师就在贸易阶梯最高层的战士阶梯。"
D.Strings[6574]="你好，今天有什么可以帮你的吗？"
D.Strings[6575]="欢迎来到银月城银行，$g先生:女士;。你想使用存储服务吗？"
D.Strings[6576]="埃索达的地下储藏室规模庞大，守卫森严。你的物品放在这里一定很安全。"
D.Strings[6577]="我们控制着埃索达的储存设施。你有什么东西需要存取吗？"
D.Strings[6578]="嘿！你觉得你能帮我离开这吗？"
D.Strings[6579]="好吧，让我们离开这里。"
D.Strings[6580]="你确信你准备好了？再等一会儿。"
D.Strings[6581]="好吧，我们出发吧！"
D.Strings[6582]="好吧，我想我可以自己逃出这里了。很感谢你的帮助！"
D.Strings[6583]="在我们出发之前，我最好装备一些武器和护甲。"
D.Strings[6584]="走吧。"
D.Strings[6585]="入侵者，你们在遗忘的深渊边缘摇摆！燃烧军团就是你们的末日！"
D.Strings[6586]="入侵者和囚犯在一起！杀死他们！！"
D.Strings[6587]="这里没有什么可以看的。往前走。"
D.Strings[6588]="这和你没关系。继续走。"
D.Strings[6589]="有骑兵来了。"
D.Strings[6590]="萨尔！你不会真的以为可以逃脱吧？你和你的伙伴们很快就要去接受布莱克摩尔的审讯……不过我得先跟你玩玩。"
D.Strings[6591]="谢谢你们，朋友。我非常感激你们。塔蕾莎在哪里？我非常希望能在动身离开之前再见她一次，并再次感谢她。"
D.Strings[6592]="塔蕾莎不能见你，萨尔。"
D.Strings[6593]="你是什么意思？是不是塔蕾莎有危险？"
D.Strings[6594]="现在的处境非常复杂，萨尔。对你来说，最好在更多布莱克摩尔的人出现前离开这里。我们会保证塔蕾莎的安全。"
D.Strings[6595]="我不会这么做的。我不会把塔蕾莎留在危险中，而我却自己跑开。我不是个懦夫。现在告诉我，她在哪里？"
D.Strings[6596]="塔伦米尔。"
D.Strings[6597]="很好。塔伦米尔就在西面。既然时间紧迫……"
D.Strings[6598]="如果我们作为一个整体来抗争，就不可能被忽视了！"
D.Strings[6599]="让所有人听到你们的声音！现在是时候团结起来拯救我们的人民了。"
D.Strings[6600]="洛瑟玛必须听到我们的呼声！我们不能再沉默下去了！"
D.Strings[6601]="应该没问题了。如果你还需要我的话，召唤我。"
D.Strings[6602]="洛瑟玛重建的银月城真是我们的骄傲。"
D.Strings[6603]="英明的魔导师将会指引我们走向繁荣的未来。"
D.Strings[6604]="我们会报复联盟！我们永远也不会忘记，永远也不会原谅他们！"
D.Strings[6605]="不要用惊讶的眼光看着我，$r。德莱尼人的到来和与我们的结盟都已经被启示者库尔兹言中了。"
D.Strings[6606]="<你用熊怪语问候大使弗拉萨布，他笑了笑。>$B$B你一定是预言中被提到的那个人了，见到你很荣幸。$B$B我是弗拉萨布大使，止松老酋长派驻秘血岗哨的代表。"
D.Strings[6607]="我加入探险者协会这么多年来，已经踏遍了整个艾泽拉斯，但我从没见过秘血岛那样的地方。"
D.Strings[6608]="请不要对我说任何事，我不想再介入他们的麻烦之中。"
D.Strings[6609]="我们刚刚抵达这里，却已经有许多战友和朋友在途中丧生了。"
D.Strings[6610]="不吃鱼，你怎么能吃布丁呢?"
D.Strings[6611]="如果你不把鱼吃了，就别想吃布丁！"
D.Strings[6612]="我们就骑马过去！"
D.Strings[6613]="如果你到这里来不是为了帮忙，就滚出去。"
D.Strings[6614]="有了你的帮助，我们也许能获胜！"
D.Strings[6615]="这些树木后面就是塔伦米尔。敦霍尔德的暴乱应该可以让我们有时间在整个村庄被人类士兵包围前找到塔蕾莎。我们去附近的谷仓找找，然后去城镇里面看看。"
D.Strings[6616]="你可以使用哈兰作战勋章和哈兰研究勋章从我这里购买东西。"
D.Strings[6617]="我们准备好了，萨尔。"
D.Strings[6618]="我可以教你剥皮。你感兴趣吗？"
D.Strings[6619]="你是指银月城旅店，还是旅者的梦乡？"
D.Strings[6620]="旅者的梦乡。"
D.Strings[6621]="银月城旅店。"
D.Strings[6622]="旅者的梦乡位于长者步道和花园街市之间，你可以从任一方向走到那里。"
D.Strings[6623]="塔蕾莎肯定在旅店里。我们走吧。"
D.Strings[6624]="塔蕾莎！这是什么邪恶的魔法？"
D.Strings[6625]="萨尔，你逃出来了！"
D.Strings[6626]="感谢你们帮助萨尔逃脱，朋友们。现在我只希望你们同样能帮我。我早上醒来时，发现自己被囚禁在这个魔法监牢中。一个奇怪的巫师告诉我，我必须在这里待一段时间。"
D.Strings[6627]="奇怪的巫师？"
D.Strings[6628]="是的，朋友们。这个人不是达拉然的巫师。他的衣服看上去是外来的，还有他的口音我也不是很熟悉。他不停地说着什么时间这个、时间那个之类的话。你得找到那个巫师，让他来释放我。"
D.Strings[6629]="我们会把你救出去的，塔蕾莎。不要担心。我怀疑那个巫师很可能在就在附近徘徊。"
D.Strings[6630]="我很高兴塔蕾莎还活着，现在我们必须找到一个方法把她从魔法禁锢中解救出来。"
D.Strings[6631]="作为贫民窟的代表，我要在此提出我们的建议，那就是：必须扫清在奥金顿横行的暗影议会成员。这关系到我们是否能在未来阻止他们再次创造一个新的白骨荒野，制造一次更大的灾难！$B$B我们的人民已经承受了太多的痛苦。我在这里盼望着那些痛苦立刻停止！"
D.Strings[6632]="末日守卫"
D.Strings[6633]="愤怒卫士"
D.Strings[6634]="魅魔"
D.Strings[6635]="破坏魔"
D.Strings[6636]="恐惧魔王"
D.Strings[6637]="艾瑞达"
D.Strings[6638]="深渊领主"
D.Strings[6639]="甘尔葛"
D.Strings[6640]="莫尔葛"
D.Strings[6641]="恶魔卫士"
D.Strings[6642]="坐一会吧，朋友。赞加沼泽所遭受的破坏真让人身心疲惫。"
D.Strings[6643]="如果你想要在这里休息，跟我说就行了！"
D.Strings[6644]="感谢你帮我制造药膏，$n。如果它真能缓解痛苦，我会去看看我能让这条腿走多远。"
D.Strings[6645]="萨尔！出来面对你的命运吧！"
D.Strings[6646]="那是什么东西？"
D.Strings[6647]="塔蕾莎性命堪忧，你一定非常关心她，你一定想要救她……"
D.Strings[6648]="啊，你来了。我原本希望以比较隐秘的方式解决问题，但是现在看来正面冲突是在所难免的了。你的命运之路在此终结，萨尔。你和你那些爱管闲事的朋友全都得死！"
D.Strings[6649]="欢迎来到加拉达尔，陌生人。你在找一处可以休息的地方吗？"
D.Strings[6650]="够了。我要把你们全部消灭！"
D.Strings[6651]="啊……另一位寻求启迪的萨满祭司，我说得对吗？灵魂们说得不够清楚吗？你要我帮你指明命运之路的方向吗？"
D.Strings[6652]="我是斯卡泰斯，在这里引领萨满祭司寻求启迪……但即使信念不同者也可以在这里得到指引。你想看看吗？"
D.Strings[6653]="我想，先知。"
D.Strings[6654]="喝下这瓶东西，迷雾就会消失一段时间。和灵魂们一起去吧，我的朋友。"
D.Strings[6655]="塞莱恩是城里最好的厨师之一，你可以在旅者的梦乡旅店的楼上找到她。你同样可以从她的助手那儿买到烹调用品。"
D.Strings[6656]="我应该坐地铁去铁炉堡看看冬天爷爷。"
D.Strings[6657]="你没看到我现在很忙吗？"
D.Strings[6658]="嗯？你要做什么？"
D.Strings[6659]="对了，你是……？"
D.Strings[6660]="我天真烂漫的妹妹西尔兰娜对这林子里面的危险一无所知。但是不管怎么样，等我把货物装好了，我们就搬到城里去。$B$B我这里的包太多了，你不如拿几个去用吧。"
D.Strings[6661]="我没有时间闲扯，$r。确切地说，除非你愿意帮我解决矿井里的麻烦。"
D.Strings[6662]="我不知道该怎么感谢你对我的帮助了。现在，唯一的问题就是说服那些矿工回来工作。"
D.Strings[6663]="谢谢你解救了我，$n！我马上就回沙塔斯城去！"
D.Strings[6664]="<伊斯法尔叹了口气。>$B$B几间树屋还算不上是家，但是这已经比塞泰克大厅好多了。$B$B就算和在沙塔斯城一样舒适，我也不会丢下我的妹妹一个人回到老家斯克提斯去。她被我们的长兄抓走了，被困在塞泰克大厅里。"
D.Strings[6665]="我们的机会来了！让我出去！"
D.Strings[6666]="我马上带你离开这里。"
D.Strings[6667]="试炼竞技场曾经是个满是荣耀的地方。不过，热砂港集团的出现，带来了成车的黄金和比兽人的斧子更硬的羽毛笔……"
D.Strings[6668]="塞泰克一族认为他们是所有鸦人中最忠诚于主人的信徒。不要多问关于主人的事，$R，只有鸦人才有资格了解他的神秘传说。$B$B塞泰克认为奥金顿的毁灭是主人到来的信号。他们带着我们最伟大的英雄泰罗克的圣物去了废墟。$B$B他们仍然在神殿的废墟中寻找主人，但是我看穿了他们的谎言。我不再和他们同流合污了。"
D.Strings[6669]="当我还大厅中徘徊的时候，利爪之王艾吉斯随身携带着泰罗克的羽毛，把它作为他权力的象征。$B$B我的兄弟——黑暗编织者塞斯在我们的仪式上戴着泰罗克的面具。$B$B至于泰罗克的传说，我们不可能确切地知道它在哪里，但是他们通常把它放在大厅的某个符文法阵中间。"
D.Strings[6670]="利爪之王艾吉斯和我兄弟黑暗编织者塞斯一样，都是塞泰克的领导者之一。$B$B是他们带领塞泰克一族从斯克提斯来到了奥金顿废墟。最初，艾吉斯是一个有着超凡魅力的领袖，但是他陷入了疯狂。$B$B现在，他公然宣称他就是再生的泰罗克！他想让所有鸦人向他屈服，接受他的统治。你能相信他居然如此傲慢吗？"
D.Strings[6671]="谁是利爪之王艾吉斯？"
D.Strings[6672]="谁是塞泰克？"
D.Strings[6673]="我在哪里可以找到泰罗克的圣物？"
D.Strings[6674]="谁是这个你一直提起的泰罗克？"
D.Strings[6675]="他是鸦人有史以来最伟大的英雄。$B$B据说在远古时代，他用自己的爪子建造了斯克提斯。他是我们最伟大的勇士和守护者，但当我们开始放弃对鲁克玛的崇拜时，他离开了我们。$B$B我们开始崇拜一个承诺给我们无尽力量的新主人。$B$B有人说泰罗卡和鲁克玛是同一个人，所以他在我们背弃他的时候离开了我们。"
D.Strings[6676]="我自由了！感谢你们！"
D.Strings[6677]="再见，塔蕾莎。我永远不会忘记你的善良。"
D.Strings[6678]="如果有酒就着奶酪吃该有多好啊……"
D.Strings[6679]="啊……多么可怕的工作啊！"
D.Strings[6680]="为什么母亲不能选择别的工作呢？"
D.Strings[6681]="苦工就是那样力大无脑！他们还是很听话的，不过必须在开始前被“踢几下”才行，我想你应该能明白我的意思。"
D.Strings[6682]="有印象吗，$c？"
D.Strings[6683]="只要你有钱，我就能弄到你要的东西。"
D.Strings[6684]="请随便看看，如果你对什么感兴趣，就告诉我。"
D.Strings[6685]="请自便，看看这把武器。如果你想修理你的武器和装备，我们这里也提供周到的服务。"
D.Strings[6686]="我有你所需要的施法材料。"
D.Strings[6687]="只有锋利的武器和坚固的护甲可以让纳格兰回归原有的宁静。让我修理你的装备吧，这样你才能去惩奸除恶。"
D.Strings[6688]="你在找毒药和施法材料的供应商吗？如果是的话，那么你来对地方了！"
D.Strings[6689]="我出售工匠们需要的物品。不过只是些基础物品，没什么特别的。"
D.Strings[6690]="你迷路了吗？这里大部分的商人都居住在城镇中心。"
D.Strings[6691]="我有很多零碎的小东西。"
D.Strings[6692]="我快要疯了。我碰不到那些该死的蛋！"
D.Strings[6693]="它们看上去太美味了……"
D.Strings[6694]="要是我能让这台该死的机器工作起来就好了！"
D.Strings[6695]="啊，美味的鸟蛋啊……你们都将是我的……"
D.Strings[6696]="很多年来，荣耀堡都在独自抵抗着地狱火半岛的敌人。现在，既然黑暗之门已经重新开启，援助者们像潮水一样从艾泽拉斯涌入，也许这个血腥的僵局将会被打破。"
D.Strings[6697]="我们在地狱火半岛的敌人非常多，遗憾的是，地狱火堡垒的兽人便是其中之一。$B$B但是……没有谁比这些兽人更适合用来历练部落的新兵了。"
D.Strings[6698]="很高兴再次见到你，$n！只要再调整下跳跃的轨道就完美了！"
D.Strings[6699]="我要兑换徽记！"
D.Strings[6700]="%s发出一声可怕的尖叫。"
D.Strings[6701]="德鲁伊们在月光林地举行春节庆典。如果你觉得路途太遥远了，他们在暴风城外提供传送服务。"
D.Strings[6702]="春节对我们来说是个特别的日子。我们寻找古代的长者，对他们表示敬意。"
D.Strings[6703]="春节对暗夜精灵来说有着特殊的意义。我们在全世界寻找长者的智慧。"
D.Strings[6704]="感觉好像每个人都想在槲寄生下吻我。"
D.Strings[6705]="据我所知，联盟的人民在铁炉堡庆祝这个冬幕节。"
D.Strings[6706]="尽管我们并不完全理解冬幕节的传统，但是……入乡随俗。"
D.Strings[6707]="现在的冬幕节已经跟以前不一样了，但是我仍然很有节日的感觉。"
D.Strings[6708]="冬天爷爷就在奥格瑞玛，乘坐双足飞龙很快就能抵达那里。"
D.Strings[6709]="对卡多雷而言，春节是最重要的节日。德鲁伊举办的庆典总是非常热闹。"
D.Strings[6710]="冬幕节一直以来都是个人类的节日。看着地精和兽人开始掺合进来，感觉相当诡异。"
D.Strings[6711]="冬天爷爷就在铁炉堡银行门口。他身旁的树下堆满了礼物。"
D.Strings[6712]="瞧瞧那些没见过世面的家伙，过个冬幕节就激动成这样。铁炉堡的银行是节日庆典的中心。"
D.Strings[6713]="春节庆典在月光林地进行。你可以自己艰苦跋涉，或者使用塞纳里奥区的德鲁伊们提供的传送服务到那里去。"
D.Strings[6714]="我到过无数个世界，但是我从没有看到过像冬幕节宴会那样的令人愉快的庆典。你应该去铁炉堡亲眼看看。"
D.Strings[6715]="艾泽拉斯的德鲁伊们正在月光林地举办一场大型庆典。如果你在城市里找到春节狂欢者，他们可以把你传送到月光林地。"
D.Strings[6716]="如果你想真正体验一下冬幕节，就应该去奥格瑞玛看看。"
D.Strings[6717]="如果你在银月城找到春节狂欢者，他们可以把你传送到月光林地去参加庆典。"
D.Strings[6718]="最热闹的春节庆典正在月光林地进行。如果你觉得到那里去实在太远，可以去智慧谷找德鲁伊们把你传送过去。"
D.Strings[6719]="我们也开始庆祝冬幕节了，但这里的宴会感觉有点空旷。奥格瑞玛那边才是真正的庆典。"
D.Strings[6720]="对遗忘者来说，月亮已经取代了太阳在我们心中的地位。如果你想要参加节日庆典的话，就去卡利姆多的月光林地吧。幽暗城王座厅的德鲁伊可以将你传送到那里。"
D.Strings[6721]="在寒冷的季节中，冬幕节的庆典是个非常温暖的去处，它的中心就在奥格瑞玛。"
D.Strings[6722]="最隆重的春节庆典正在月光林地进行。德鲁伊们可以把你从雷霆崖的长者高地传送到那里。"
D.Strings[6723]="来这儿瞧瞧吧。这些武器都很上等呢，不是吗？你肯定想要购买吧。$r，别的地方可找不到锻造工艺如此精湛的武器。"
D.Strings[6724]="你在看什么，$r？"
D.Strings[6725]="多尴尬啊！有人把我错认成了冬天爷爷的助手。"
D.Strings[6726]="春节是一年中看烟火的最好时节！"
D.Strings[6727]="我们应该去月光林地，看看德鲁伊们举办的春节庆典。"
D.Strings[6728]="去铁炉堡的秘法区和暗夜精灵的德鲁伊谈谈。他们会把你传送到月光林地去参加春节庆典。"
D.Strings[6729]="你可以在力量谷中心找到冬天爷爷。他就在圣诞树下。"
D.Strings[6730]="最精彩的春节庆典正在月光林地举行。当然你不用跋山涉水走去那里，智慧谷的德鲁伊们可以直接传送你过去。"
D.Strings[6731]="纳格兰的原始大草原是我所见过的最好的狩猎地点。"
D.Strings[6732]="你喜欢鱼吗，$r？我这里有鱼，最新鲜的鱼，过来看看我的货物吧。"
D.Strings[6733]="永远不要直视破碎者的眼睛。我认为，如果他们愿意的话，他们可以把你的灵魂从眼中抽出来！"
D.Strings[6734]="从我面前走开，孩子！你没有看到我在训练吗？没错，我会成为下一个战槌勇士的。$B$B是的，我差不多准备好去古老的鲜血竞技场参加挑战了。但是你想都不要想，孩子。你实在太弱了。竞技场的报幕员古尔戈索克甚至都不会让你偷看正在进行的战斗。$B$B闪远点。"
D.Strings[6735]="好吧，看看你自己。你觉得自己够强壮吗？或是你觉得你已经强壮到足以挑战鲜血竞技场的战槌勇士了？$B$B<斗士大笑起来。>$B$B不大可能，但你如果非常想验证一下你的力量，就朝北方一直走，在分割纳格兰和赞加沼泽的山脚之下，你可以找到鲜血竞技场。旧嘲颅废墟的古尔戈索克掌管着那里，他同样也掌管着奖赏。说到奖赏，我听说这个赛季的奖品非常棒！"
D.Strings[6736]="哇！看看他的肌肉！"
D.Strings[6737]="我真想变得像斗士那样！"
D.Strings[6738]="他会赢吗？他能赢吗？"
D.Strings[6739]="他真是训练有素！"
D.Strings[6740]="他是怎么做到的？"
D.Strings[6741]="审问者想搞清楚这些血精灵在纳格兰干什么。我听说他们是为了西边的钻石山——沃舒古的水晶粉末残渣而来。$B$B毫无疑问，他们想把这些残渣用于某些阴险的计划或是掺进什么调和物里面……$B$B如果你想帮我们查明真相，阻止那些血精灵的话，你必须知道，血精灵们和阿古斯之手的士兵们正在西北部的哈兰发生冲突。加入战斗，让他们看看什么才是正确的！"
D.Strings[6742]="德莱尼人又来了！他们偷袭了我们两名正在西边道路上巡逻的狼骑兵。不用说，我们赢了。$B$B现在我不确定发生了什么，但据我的斥候说，哈兰到处都是血精灵和德莱尼人。我不喜欢血精灵，至于德莱尼人，我恨死他们了。如果你在哈兰看到德莱尼人或是任何他们的盟友，就帮我狠狠教训他们。$B$B如果你现在就要去……哈兰就在西面。"
D.Strings[6743]="别想活着逃走！"
D.Strings[6744]="别让他们跑了！杀了他们！"
D.Strings[6745]="你知道得太多了！"
D.Strings[6746]="为了凯尔萨斯！"
D.Strings[6747]="一个都别让他们逃跑了！"
D.Strings[6748]="我会先要你的能量，再要你的命！"
D.Strings[6749]="荣耀属于联盟！"
D.Strings[6750]="我们已经占领了双塔废墟！快去参与防守！"
D.Strings[6751]="这块陈旧的德莱尼公告板被库雷尼重新打磨过了，现在用来张贴公告和悬赏名单。"
D.Strings[6752]="暗影猎手德恩加用这块公告板来张贴重要的公告和萨布拉金的新悬赏名单。"
D.Strings[6753]="水果商人！你的小车仍然挡着我们的路。我再给你一个小时，把它从我们的地盘挪开。不要再考验我们的耐心！"
D.Strings[6754]="我要是发誓说我有更多苹果就好了。葛罗克！"
D.Strings[6755]="那些可怜的兽人在叫喊什么？谁去看看怎么回事？"
D.Strings[6756]="啊，你不能拒绝，你能吗？你不能。你能吗？讨论一下嘛。你想变得更快、更高、更强吗？我卖的每一个护身符都绝对有效！过来买一个这样神奇的小玩意吧！半价！"
D.Strings[6757]="我会……看一看的。"
D.Strings[6758]="嘿！嘿，$r！我有个东西简直是给你量身定做的！你看到过提克巴朗吗？偷你东西的可怕生物。你所需要的就是我的防盗符咒，保证可以吓走所有的提克巴朗！"
D.Strings[6759]="看这里，$c！我这里有样东西给你，你绝对需要。是块肥皂，是的……而且系在一根绳子上！我没有要冒犯的意思，$G先生:甜心;，但是我相信你知道我在说什么？"
D.Strings[6760]="你看上去很忧愁。是不是某些特殊的人让你如此低落，嗯？不用担心，不用担心。从我这里买一枚勋章吧，他们永远都不会再成为你的问题了，$g伙计:小姐;！"
D.Strings[6761]="到处都有危险，不是吗？知道你需要什么吗？保护。我可以帮你挑战死亡！把这块非凡的石头戴在脖子上，看，如果你可以在灵魂世界找到自己，那么你就能复活！只不过需要一个跑向尸体的过程，然后你就重生了，一个崭新的你！"
D.Strings[6762]="多棒的护身符啊！难以置信的古董！那些新来的珠宝工匠们从未尝试过的、格里伏塔的神秘物品！买下这些魔法护身符，提升你的能力吧！很便宜的！"
D.Strings[6763]="过来，$r。你不想让你自己在地下城里受到伤害吧，对吗？努力工作，为了什么？一些毫无价值的饰品？不，你所需要的就是一个我制作的护身符。保证有用！"
D.Strings[6764]="你看上去很疲惫，$c。我有东西给你。这些护身符，它们可以帮你跳跃障碍物和游过河流，就像那是你与生俱来的能力一样。它们让你吃的食物充满能量，让你的伤口在眨眼间就能愈合！"
D.Strings[6765]="哇！这些掌声都是献给我的？感谢你们的到来！"
D.Strings[6766]="谢谢你到这儿来看我！希望你已经准备好享受这个时刻了，我早就迫不及待了。"
D.Strings[6767]="嘿，朋友们，够了够了……那是我第一次。"
D.Strings[6768]="你准备好开怀大笑了吗？"
D.Strings[6769]="你有没有注意到那些可爱的兽人孩子看上去全都长得一个样？"
D.Strings[6770]="这个侏儒告诉牛头人说，他去过熔火之心。"
D.Strings[6771]="我有个好问题，为什么西瓜里面有水？"
D.Strings[6772]="他们长大之后就不可爱了，真是糟糕。贫瘠之地的成人礼上大概会执行“爬上大树再狠狠地摔下来”这样的仪式。"
D.Strings[6773]="牛头人说，“真是吹牛。”"
D.Strings[6774]="因为它们是在春天种植的！"
D.Strings[6775]="演出时间！我把这叫做“愚蠢的牛头人”！"
D.Strings[6776]="喜剧演员清了清喉咙。"
D.Strings[6777]="怎么和女人打交道？我的意思是她们就像是……"
D.Strings[6778]="侏儒们更糟！他们一直在说一些……"
D.Strings[6779]="谢谢！别忘记给服务生小费！晚安。"
D.Strings[6780]="已经结束了？真不错。路上小心，晚安。"
D.Strings[6781]="好吧，是时间取下这些可笑的肌肉了。大家晚安！"
D.Strings[6782]="最后一个模仿。有点难度，但是你们能猜出是谁吗……"
D.Strings[6783]="当雷象坐在你家围栏上的时候，你该怎么办？"
D.Strings[6784]="去弄个新围栏！！"
D.Strings[6785]="我和我的妻子一起快乐地生活了二十三年……"
D.Strings[6786]="然后我们相遇了！"
D.Strings[6787]="你把坏的回旋标叫做什么？"
D.Strings[6788]="一根棍子！"
D.Strings[6789]="我爱血精灵女人。特别是当她们说这些话题的时候……"
D.Strings[6790]="我听说侏儒们可以实现愿望……"
D.Strings[6791]="我的愿望就是让他们走远点！"
D.Strings[6792]="我遇到过的牛头人都非常美……"
D.Strings[6793]="味！"
D.Strings[6794]="要是你想要大笑一场，就去天涯旅店吧！"
D.Strings[6795]="现在表演结束了，有人可以带我去刷血色修道院吗？"
D.Strings[6796]="大家好！离下个笑话还有多久？"
D.Strings[6797]="感谢大家光临。现在请鼓掌欢迎沙塔斯城最棒的——派瑞·加奈尔！"
D.Strings[6798]="派瑞·加奈尔！多棒的表演！酒馆是通宵营业的，所以请待在这尽情享受吧！"
D.Strings[6799]="显然我和你的人民是敌对的。"
D.Strings[6800]="要是我知道会这样，我就该穿上我的[大笑长靴]。"
D.Strings[6801]="哇！这里的笑声好像从来没停过，是吗？"
D.Strings[6802]="我不想对你们说谎，士兵们。我们被打得屁滚尿流！有没有像兽人那样带种的，站出来去做点什么？"
D.Strings[6803]="是的，我们有麻烦了。我想那是显而易见的。但问题是，我们要怎么办？"
D.Strings[6804]="都长长脑子吧，在你们认识到一头冲进燃烧军团的小队是自杀行为之前，我还要送多少具尸体回你们的家？还有，不要在我面前用力晃你们的大脑袋，好像你们明白我在说什么似的。"
D.Strings[6805]="习惯就好，姑娘们。像我一样关心这些悲惨的幸存者吧。欢迎来到地狱火半岛，你的新家。"
D.Strings[6806]="客官，您是打尖儿，还是住店？"
D.Strings[6807]="再快点，蠢货！如果我们找不到主人想要的阿塔玛水晶，他不会高兴的。"
D.Strings[6808]="冬天爷爷会把给每个人的礼物放在铁炉堡的树下。我已经等不及要去拿我的了。"
D.Strings[6809]="挖快点，可怜虫！不要逼我对你下狠手！"
D.Strings[6810]="不要停下来！如果你敢有哪怕一秒钟放下锄头的念头，我保证会让你明白什么叫死去活来！"
D.Strings[6811]="那些从天上滑落到坠星山的巨型水晶，隐藏着我们必须解读的迷团。"
D.Strings[6812]="有时候，直接了当地提问是最好的。"
D.Strings[6813]="主人，我失败了……"
D.Strings[6814]="如果你被燃烧军团俘虏了，对他们说“Xar il romath da tidesbi”，他们就会马上杀了你，因为你侮辱了他们的神。否则你就会受到无尽的折磨或者更糟的……"
D.Strings[6815]="我正在为前线指挥官托尔克执行轰炸任务。我需要一头武装飞龙！"
D.Strings[6816]="可笑的凡人，你们只是延迟了不可避免的命运。一个恶魔倒下去，十个恶魔会站起来。这就是卡扎克的意志……"
D.Strings[6817]="有好玩的啦！"
D.Strings[6818]="你胆敢妨碍主人的计划？你会付出代价的，愚蠢的凡人！"
D.Strings[6819]="消灭这些入侵者，肮脏的残冠氏族！如果你们不服从我的命令，我会让你们尝到无尽的痛苦！"
D.Strings[6820]="去吧，你们这些可怜虫！让那些蠢货们知道藐视主人的下场！"
D.Strings[6821]="不要妄想逃跑，可怜的破碎者！不消灭这些入侵者，我就让你们生不如死！"
D.Strings[6822]="感谢你解救了我，$n。现在让我们离开这里！"
D.Strings[6823]="就要到了！让我们逃离这里！"
D.Strings[6824]="烟林牧场在奥格瑞玛和铁炉堡开了商店。不知道他们今年在构想些什么？"
D.Strings[6825]="金发，绿皮肤，带角的脑袋，蓝皮肤——所有这些家伙都给我们伟大的地精工程学带来了新的市场！即使是与燃烧军团的第二次战争展望都会提高我们的销量！"
D.Strings[6826]="士兵们！散开！"
D.Strings[6827]="德鲁伊们在月光林地举行春节庆典。要是那里对你来说太远了，他们正在各大城市提供着传送服务。"
D.Strings[6828]="我们在这里保护着加基森在安戈洛的利益，而且那和你毫无关系。"
D.Strings[6829]="地狱火半岛是一个满目疮痍的区域——对那里的居民们来说，那是多么的残酷和艰难。确保在冒险前修理并囤积好补给品吧。"
D.Strings[6830]="在我们开始严肃对待之前，还有多少士兵要死在这里？"
D.Strings[6831]="你们觉得这些恶魔会跟我们公平地交战吗？它们比兽人更野蛮，比亡灵更狡猾。千万不要试图以普通的战争标准来评判燃烧军团。"
D.Strings[6832]="我很遗憾地告诉你们，今天我们又送了十个士兵回家——装在裹尸袋里。"
D.Strings[6833]="这场战争——不要错误地认为它是除了战争以外的什么东西——是不会自动获胜的。如果我们不尽全力来为这块破碎世界的每一寸土地战斗，我们就会失去一切。"
D.Strings[6834]="小点声，睁开你的眼睛看看，$n。我们被这里的敌人包围了。"
D.Strings[6835]="潜入敦霍尔德城堡的收容所，在圆桶中放置燃烧弹。点燃五枚燃烧弹，一旦声东击西之计成功，就去敦霍尔德城堡的地下室找到萨尔，并保护他逃走，你必须确保萨尔的生命安全！$B$B如果你准备好了，就跟布拉森谈谈，飞往敦霍尔德城堡吧。"
D.Strings[6836]="如果你愿意的话，我可以直接带你去敦霍尔德。"
D.Strings[6837]="在我带你飞往敦霍尔德之前，你要先从伊洛希恩那儿搞一包燃烧弹。不要浪费时间。"
D.Strings[6838]="我准备好去敦霍尔德城堡了。"
D.Strings[6839]="可怕……太可怕了！$B$B我们从虚空风暴的52区起飞，航行途中正想着心事，但他们却把我们射了下来！我知道我们不应该利用那条捷径去泰罗卡森林的！"
D.Strings[6840]="每年的这个时候，烟林牧场的地精们总是会出售一些非常棒的糖果。"
D.Strings[6841]="冬天爷爷会把每个人的礼物放在奥格瑞玛的树下，我在想今年他会给我什么。"
D.Strings[6842]="原谅我……我别无选择。"
D.Strings[6843]="结束我的痛苦吧！"
D.Strings[6844]="让这些可怜的破碎者累到吐血吧，伊利达雷！要是这个被遗弃的地方有任何值钱的东西，我们会找到它的！"
D.Strings[6845]="远征军岗哨是联盟最接近燃烧军团前线的联络点。这里的北面除了恶魔还是恶魔。找个朋友搭伴旅行吧。"
D.Strings[6846]="看紧这些破碎者人渣！已经有很多从我们这里逃走了！"
D.Strings[6847]="我们必须找到主人想要的东西！只许成功，不许失败！"
D.Strings[6848]="不要让这些可怜虫有一点点喘息的时间！如果这里真的有一颗阿塔玛水晶的话，那么我们会找到它的！"
D.Strings[6849]="因为我了解古代德莱尼水晶和遗迹，所以伊利达雷的恶魔们把我囚禁在这里。$B$B他们奴役了我的很多族人，并且利用我们寻找一块能量巨大的水晶……一块可能根本不在这里的水晶。"
D.Strings[6850]="你为什么不逃呢？"
D.Strings[6851]="为什么？就算伊利丹的恶魔不再抓住我、奴役我，那么赞加沼泽的纳迦也会这么做的。$B$B加入伊利丹和他的恶魔大军无非是为破碎者氏族套上新的枷锁罢了。我们的人民没有任何希望。"
D.Strings[6852]="啊，冬幕欢乐制造器。下一次我们该想点什么？"
D.Strings[6853]="那些漂亮的冬帽都是哪里来的？"
D.Strings[6854]="我发誓，我再也不会走捷径了！我怎么知道地狱火半岛的上空那么危险？"
D.Strings[6855]="学者尼度门，我有一事相求。"
D.Strings[6856]="我们刚派了另一队新手队伍进驻了纳格兰。你能为他们祈祷平安吗？"
D.Strings[6857]="当然，我的朋友。请问有什么可以效劳的？"
D.Strings[6858]="一个高贵的请求。这是一种荣誉，艾罗塞姆。"
D.Strings[6859]="我的朋友们，请与我一起谦卑地向圣光祈祷。"
D.Strings[6860]="我们信奉的圣光，我们恳求你……"
D.Strings[6861]="快磨斧子，说你呢！我要它锋利到可以劈风断水！"
D.Strings[6862]="在我们与黑暗的斗争中，我们派出了我们的孩子冲锋陷阵。"
D.Strings[6863]="请为他们祝福，请保护他们吧，请赐予他们成功，凌驾于那些想伤害我们的人……"
D.Strings[6864]="我们乞求你继续保佑我们古老的家园。"
D.Strings[6865]="愿我们能以一颗包容的心来看待那些精灵访客。"
D.Strings[6866]="要是你不适合修理工作的话，我们就要考虑你是否适合用来做菜了。干活去！"
D.Strings[6867]="我不懂你在说什么！"
D.Strings[6868]="请不要打我！"
D.Strings[6869]="要是给我看到谁偷懒，我就把他们绑在投石器上，丢到黑暗神殿去！"
D.Strings[6870]="无论什么时候，你们这些苦工要是想休息的话，那边的坟地等着你们呢。"
D.Strings[6871]="喜剧演员扮成了一个牛头人。"
D.Strings[6872]="喜剧演员扮成了一个侏儒。"
D.Strings[6873]="喜剧演员扮成了一个血精灵。"
D.Strings[6874]="喜剧演员扮成了一个女性人类。"
D.Strings[6875]="喜剧演员扮成了一个兽人。"
D.Strings[6876]="布隆！嗨，布隆！打我！"
D.Strings[6877]="%s眨着眼，露出很困惑的表情。"
D.Strings[6878]="什么，用我的拳头？"
D.Strings[6879]="不，拳头太弱了。用锤子敲我！"
D.Strings[6880]="我……不觉得这是个好主意，笨蛋。你可能会受伤……"
D.Strings[6881]="快点，你这个娘娘腔！"
D.Strings[6882]="呃……笨蛋？"
D.Strings[6883]="……太棒了！"
D.Strings[6884]="<当你接近纳鲁的时候，一道柔和的光线充盈了你的全身。和缓的乐声在你的心房回荡，尽管纳鲁一语未发，但一种安全感却油然而生。欢迎你来到沙塔斯城。>"
D.Strings[6885]="如果你没有要紧事的话，就给我走开。"
D.Strings[6886]="施舍个铜币吧，$G先生:女士;？"
D.Strings[6887]="嘿，$G先生:女士;，可怜可怜我吧，我还有五个孩子等着吃饭呢！"
D.Strings[6888]="请不要视而不见……"
D.Strings[6889]="请施舍一点铜币吧？"
D.Strings[6890]="猎人们，到我这里来！让我们给这些恶魔们看看，和艾泽拉斯作对是什么下场！"
D.Strings[6891]="灵魂们在为我们歌唱！他们在高唱着战斗之歌！"
D.Strings[6892]="战斗到底，兄弟姐妹们！今天我们狩猎恶魔！"
D.Strings[6893]="我们会让燃烧军团再次看到，他们休想抢走我们的世界！"
D.Strings[6894]="这些恶魔必将被击败！为了艾泽拉斯而战！"
D.Strings[6895]="即使我们的命运注定要在今天完结，我们也不能就这么轻易地死去！跟我冲啊！让这些恶魔像割麦子一样倒下！"
D.Strings[6896]="尽管你们的肌肉疲惫不堪，你们的鲜血浸透了这片土地，但是你们是在为了这个世界而战。任何邪恶的力量都挡不住我们！"
D.Strings[6897]="艾泽拉斯的士兵们，你们正在与邪恶的燃烧军团对抗。所有信仰圣光的人民的希冀和祈祷与你们同在。在我们勇敢的同盟和战友们的帮助下，你们会坚守每一寸土地，击退恶魔的冲击。你们将阻止这些肆虐了很多世界的暴徒！"
D.Strings[6898]="恶魔们应该知道，我们就是他们的末日。虽然他们希望毁灭我们，但最终被毁灭的将是他们。卡扎克和他们的爪牙们将会被我们打败。但是为了这个目标，我们必须以自己的血肉之躯来阻止他们。"
D.Strings[6899]="每一分，每一秒，我都看到艾泽拉斯的人民证明了我们来此的理由。我很骄傲能与你们并肩而战，如果我会在今天死去，那我也要与我的朋友一起战死！"
D.Strings[6900]="我刚从铁炉堡飞过来，小子！我坐骑的翅膀都快累断了！"
D.Strings[6901]="我知道你们要干什么，而我将永远打消你们的念头！"
D.Strings[6902]="我上周在闪金镇。你去过那里吗？"
D.Strings[6903]="那镇子真小，我让一个小孩给我画张地图。结果他画在了迪菲亚通缉令的背面……"
D.Strings[6904]="还是一比一的！"
D.Strings[6905]="她真漂亮，不是吗？斯卡雷……她是我们的指挥官库德兰忠实的狮鹫。库德兰常常在蛮锤要塞中处理事务，他公务繁忙时我就负责照料斯卡雷。她的羽毛真美，作战时却尽显出勇猛的一面。她愿意为了库德兰而死，真的。你肯定没有见过比她更忠诚的宝贝儿。\n\n照料她真是我的荣幸啊。"
D.Strings[6906]="闪金镇旅店为他们的湖畔景观房做广告……"
D.Strings[6907]="结果我看到有个鱼人在我的窗边游泳。"
D.Strings[6908]="多少狗头人换一根蜡烛？"
D.Strings[6909]="流血吧！"
D.Strings[6910]="跑吧，你们这些懦夫！"
D.Strings[6911]="你别想插手这件事！"
D.Strings[6912]="不能……让萨尔……逃走。"
D.Strings[6913]="看这是谁啊，醉鬼拉里克……他的妈妈太胖了，连龙都不要吃她……"
D.Strings[6914]="因为他们不知道该把剩下的肉放在哪里！"
D.Strings[6915]="嘿！嘿！嘿！这不是醉鬼拉里克吗……他妈妈太胖了，她不仅上了《今日食人魔》的封面……"
D.Strings[6916]="还上了封底！"
D.Strings[6917]="侏儒们曾经是非常值得尊敬的种族……"
D.Strings[6918]="有一天我看到有人沿着大街边走边叫，“一旦你变成侏儒，你就只能租房子住了！”"
D.Strings[6919]="通常你不能相信地精……"
D.Strings[6920]="我在开玩笑吗？如果你和地精们做生意，你最好给钱包装上个铁套子。"
D.Strings[6921]="你是个奴隶！你永远都是个奴隶！"
D.Strings[6922]="我不知道布莱克摩尔为什么看中你，在我看来你只不过是个愚蠢的兽人！"
D.Strings[6923]="萨尔不可能逃脱！"
D.Strings[6924]="你真以为自己可以活着离开这里？"
D.Strings[6925]="卫兵……卫兵！"
D.Strings[6926]="只有我这么觉得吗？部落简直是我们可以找到的最难看的敌人？"
D.Strings[6927]="你们不要感到失落，我的意思是血精灵是多么迷人啊。都是翻译的错。"
D.Strings[6928]="只能招募你的家畜作为同盟是多么令人失望啊！"
D.Strings[6929]="我有一条狗，但我不会把剑给它。"
